export const MATE_ASK_TTL_MS = 7 * 86_400_000;
/** What a turn the lead starts itself for automatic crew updates says in the owner's place (lead-follow.ts): never their answer. */
export const LEAD_FOLLOW_MESSAGE = "Automatic crew update: inspect the saved results or decisions and tell me what needs attention. Do not rerun work.";

/** Settings → Integrations (no version bump): each integration's last check. `outcome` is ok, failed, or absent (the check found
 * nothing set up, such as no `gh` sign-in). `ok_at` and `error`/`error_at` keep the last success and the last
 * failure across checks, so a row can say both. `account` is a display name only, never a credential. */
export const INTEGRATIONS_SCHEMA = `
CREATE TABLE IF NOT EXISTS integration_check (
  key         TEXT PRIMARY KEY,
  outcome     TEXT NOT NULL CHECK (outcome IN ('ok', 'failed', 'absent')),
  account     TEXT,
  detail      TEXT,
  problem     TEXT,
  checked_at  TEXT NOT NULL,
  ok_at       TEXT,
  error       TEXT,
  error_at    TEXT
);
`;
/** Sprint 8: database backups. One settings row (off, or every so many hours, keeping the newest N in a folder; no
 * folder means `backups` beside the database), every backup's outcome, and a lease the console's backup loop holds
 * and renews while it runs: one process backs up at a time, and a restore sees that the console is running. */
const BACKUP_SCHEMA = `
CREATE TABLE IF NOT EXISTS backup_settings (
  id          INTEGER PRIMARY KEY CHECK (id = 1),
  enabled     INTEGER NOT NULL DEFAULT 1,
  every_hours INTEGER NOT NULL DEFAULT 24,
  keep        INTEGER NOT NULL DEFAULT 7,
  folder      TEXT
);
CREATE TABLE IF NOT EXISTS backup_run (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  trigger        TEXT NOT NULL CHECK (trigger IN ('scheduled', 'manual')),
  started_at     TEXT NOT NULL,
  finished_at    TEXT,
  ok             INTEGER,
  file           TEXT,
  bytes          INTEGER,
  schema_version INTEGER,
  removed        INTEGER NOT NULL DEFAULT 0,
  error          TEXT
);
CREATE TABLE IF NOT EXISTS backup_lease (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  holder     TEXT,
  held_until TEXT
);
`;
export type BackupSettings = { enabled: boolean; everyHours: number; keep: number; folder: string | null };
export const DEFAULT_BACKUP_SETTINGS: BackupSettings = { enabled: true, everyHours: 24, keep: 7, folder: null };
export type BackupRun = { id: number; trigger: "scheduled" | "manual"; startedAt: string; finishedAt: string | null; ok: boolean | null; file: string | null; bytes: number | null; schemaVersion: number | null; removed: number; error: string | null };
/** The settings in words, for the ledger. */
export function backupSettingsWords(settings: BackupSettings): string {
  if (!settings.enabled) return `off, keep ${settings.keep}, ${settings.folder ?? "the default folder"}`;
  return `every ${settings.everyHours === 1 ? "hour" : `${settings.everyHours} hours`}, keep ${settings.keep}, ${settings.folder ?? "the default folder"}`;
}
/** One row per run for its approved project check: the live progress while
 * it runs and the machine-owned result once it finishes, so the task page,
 * lifecycle updates, `status` and `task wait` all read the same record
 * without opening retained logs. The sealed receipt stays the evidence.
 * `status` is empty until the result is recorded; `snapshot` is empty until
 * the check's output shows progress. `release` is copied from the run's
 * Strict mode when the result is recorded, so the newest release check is
 * one indexed read. A run without a result is history from before results
 * were recorded, or a check still running. The run table itself is
 * unchanged. (This table absorbed the separate v106 check_progress table.) */
const RUN_CHECK_TABLE = (name: string) => `
CREATE TABLE IF NOT EXISTS ${name} (
  run         INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  status      TEXT CHECK (status IS NULL OR status IN ('passed', 'failed', 'not-run')),
  exit_code   INTEGER,
  suites_json TEXT NOT NULL DEFAULT '[]',
  release     INTEGER NOT NULL DEFAULT 0 CHECK (release IN (0, 1)),
  recorded_at TEXT,
  snapshot    TEXT,
  line        TEXT,
  final       INTEGER NOT NULL DEFAULT 0 CHECK (final IN (0, 1)),
  updated_at  TEXT,
  notified_at TEXT
);`;
const RUN_CHECK_SCHEMA = `${RUN_CHECK_TABLE("run_check")}
CREATE INDEX IF NOT EXISTS run_check_release ON run_check (run DESC) WHERE release = 1;
`;

/** A file from before the merge keeps a result-only run_check (status
 * required) and a separate check_progress. Move both into the one record,
 * in one transaction. Rows for a run that no longer exists are left behind.
 * The old check_progress stays as it was: a deploy refuses a migration that
 * loses a table's historical rows. Runs once: a merged file is untouched, so
 * the old progress never overwrites newer. */
function mergeCheckTables(db: Database): void {
  if (hasColumn(db, "run_check", "snapshot")) return;
  const progress = tableExists(db, "check_progress");
  db.exec("BEGIN IMMEDIATE");
  try {
    db.exec(RUN_CHECK_TABLE("run_check_next"));
    db.exec(`INSERT INTO run_check_next (run, status, exit_code, suites_json, release, recorded_at)
      SELECT run, status, exit_code, suites_json, release, recorded_at FROM run_check WHERE run IN (SELECT id FROM run)`);
    db.exec("DROP TABLE run_check");
    db.exec("ALTER TABLE run_check_next RENAME TO run_check");
    db.exec("CREATE INDEX IF NOT EXISTS run_check_release ON run_check (run DESC) WHERE release = 1");
    if (progress) {
      db.exec(`INSERT INTO run_check (run, snapshot, line, final, updated_at, notified_at)
        SELECT run, snapshot, line, final, updated_at, notified_at FROM check_progress WHERE run IN (SELECT id FROM run)
        ON CONFLICT(run) DO UPDATE SET snapshot = excluded.snapshot, line = excluded.line,
          final = excluded.final, updated_at = excluded.updated_at, notified_at = excluded.notified_at`);
    }
    db.exec("COMMIT");
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
}

export type RunCheckSuite = {
  name: string;
  status: "passed" | "failed" | "not-run";
  exitCode: number | null;
};
export type RunCheck = { status: "passed" | "failed" | "not-run"; exitCode: number | null; suites: RunCheckSuite[] };

const isCheckExitCode = (value: unknown): boolean =>
  value === null || (Number.isSafeInteger(value) && Number(value) >= 0 && Number(value) <= 2_147_483_647);

/** Read a stored suite list; a malformed optional summary reads as no suite detail. */
export function checkSuitesOf(value: unknown): RunCheckSuite[] {
  try {
    const parsed = JSON.parse(String(value ?? "[]")) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((one): one is RunCheckSuite => {
      if (one === null || typeof one !== "object") return false;
      const row = one as Record<string, unknown>;
      return typeof row["name"] === "string" && row["name"].trim() !== "" && row["name"].length <= 80 &&
        ["passed", "failed", "not-run"].includes(String(row["status"])) && isCheckExitCode(row["exitCode"]);
    }).slice(0, 8);
  } catch {
    return [];
  }
}

export type MonitoringStatus = { sink: string; target: string | null; through: number; sent: number; lastOkAt: string | null; lastError: string | null; lastErrorAt: string | null; failures: number; nextTryAt: string | null };

export type CheckProgress = CheckProgressSnapshot & { run: number; updatedAt: string; notifiedAt: string | null };

/** The detail on a task's registration written again at its filing (v103), over a ref an earlier lookup made. */
const REGISTERED_AT_FILING = "again, as it was filed";
/** A ledger entry with its seal (v103); null until the next pass seals it. */
export type SealedLedgerEntry = LedgerEntry & { seal: { prev: string; hash: string } | null };
// v103 chains the action ledger (every entry sealed with the one before it), keeps checkpoints of the chain, and records teammate tool calls (from the store) and minted coordinators (by trigger) in it.
// v104 keeps where each monitoring destination (the audit stream to a webhook or a folder, traces to an OpenTelemetry collector) has delivered to, and who is sending.
// v105 prices every run (reported, or tokens at the catalogue price) and keeps monthly budgets per project, person, teammate and installation.
// v106 keeps the organisation policy, retention periods, backup settings and runs, check progress, and runner capacity changes.
// v107 keeps a check's progress and result in one record (run_check absorbs check_progress).
// v108 keeps sign-in pauses: one incident per provider whose sign-in stopped working (provider_auth_pause).
// v109 remembers which sign-in pause parked a task (task_ref.auth_wait_pause), so reviews and other runs outside the tick wait for it too.
export const SCHEMA_VERSION = 109;

/** v102: a project's approval rules, and each person's approval of an exact scope (two are needed for protected work). */
const APPROVAL_SCHEMA = `
CREATE TABLE IF NOT EXISTS approval_policy (
  repo            TEXT PRIMARY KEY,
  not_requester   INTEGER NOT NULL DEFAULT 0 CHECK (not_requester IN (0,1)),
  protect_project INTEGER NOT NULL DEFAULT 0 CHECK (protect_project IN (0,1)),
  protected_paths TEXT NOT NULL DEFAULT '[]',
  updated_by      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS scope_approval_vote (
  task_id  TEXT NOT NULL,
  digest   TEXT NOT NULL,
  approver TEXT NOT NULL,
  at       TEXT NOT NULL,
  PRIMARY KEY (task_id, digest, approver)
);
CREATE TABLE IF NOT EXISTS scope_author (
  task_id TEXT NOT NULL,
  digest  TEXT NOT NULL,
  author  TEXT NOT NULL,
  at      TEXT NOT NULL,
  PRIMARY KEY (task_id, digest, author)
);
`;

/** v101: API tokens and the browser sessions that survive a restart. Only hashes of their secrets are kept. */
const CREDENTIALS_SCHEMA = `
CREATE TABLE IF NOT EXISTS api_token (
  id           TEXT PRIMARY KEY,
  account      TEXT NOT NULL REFERENCES approver(name),
  name         TEXT NOT NULL,
  secret_hash  TEXT NOT NULL,
  access       TEXT NOT NULL CHECK (access IN ('read','act')),
  created_at   TEXT NOT NULL,
  created_by   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  last_used_at TEXT,
  revoked_at   TEXT,
  revoked_by   TEXT
);
CREATE INDEX IF NOT EXISTS api_token_account ON api_token (account);
CREATE TABLE IF NOT EXISTS web_session (
  id_hash          TEXT PRIMARY KEY,
  account          TEXT NOT NULL,
  csrf             TEXT NOT NULL,
  role             TEXT NOT NULL CHECK (role IN ('approver','viewer')),
  generation       INTEGER NOT NULL,
  created_at       INTEGER NOT NULL,
  last_seen        INTEGER NOT NULL,
  project          TEXT,
  project_revision INTEGER NOT NULL,
  sso_at           INTEGER,
  agent            TEXT,
  address          TEXT
);
CREATE INDEX IF NOT EXISTS web_session_account ON web_session (account);
`;
export type ApiTokenRow = { id: string; account: string; name: string; access: "read" | "act"; createdAt: string; createdBy: string; expiresAt: string; lastUsedAt: string | null; revokedAt: string | null; revokedBy: string | null };
export type WebSessionRow = { idHash: string; account: string; csrf: string; role: "approver" | "viewer"; generation: number; createdAt: number; lastSeen: number; project: string | null; projectRevision: number; ssoAt: number | null; agent: string | null; address: string | null };

/** v100: which account each identity-provider identity (issuer + subject) signs in as. */
const SSO_SCHEMA = `
CREATE TABLE IF NOT EXISTS sso_identity (
  issuer       TEXT NOT NULL,
  subject      TEXT NOT NULL,
  account      TEXT NOT NULL REFERENCES approver(name),
  email        TEXT,
  created_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  PRIMARY KEY (issuer, subject)
);
CREATE INDEX IF NOT EXISTS sso_identity_account ON sso_identity (account);
`;

/**
 * Every timestamp column holds `Date.prototype.toISOString()` output and
 * nothing else, which is UTC, zero-padded, and always three fractional
 * digits. Expiry is then a string comparison, which is only sound because that
 * format sorts lexicographically the same way it sorts chronologically.
 *
 * The invariant is load-bearing, so it is stated here rather than assumed: a
 * timestamp written with an offset (`-07:00`) or with different fractional
 * precision would compare wrong, and a lease would expire early or never.
 * Anything writing to this database goes through a `Date`.
 */

/** The backend name the built-in store registers itself under. */
export const BUILT_IN = "built-in";

export type TaskState = "queued" | "running" | "done" | "failed" | "cancelled";

type CancellationRefusal = "reason-required" | "bad-reason";
type CancellationTransition = { changed: boolean; reason?: never } | { changed: false; reason: CancellationRefusal };

/** States from which no further work is dispatched. */
export const TERMINAL_STATES: readonly TaskState[] = ["done", "failed", "cancelled"];

export type Task = {
  id: string;
  title: string;
  state: TaskState;
  createdAt: string;
  updatedAt: string;
  /** Queue rank — 0 is filing order; higher is picked sooner. Scheduling
   * only, never authority: approval gates are untouched by it. */
  priority: number;
};

export type TaskRef = {
  id: number;
  backend: string;
  externalId: string;
  /** Where the work lives, when known. null dispatches anywhere; no gap claims it. */
  repo: string | null;
  /** The worker this task is reserved for; null = any free worker.
   * Scheduling only — enforced in the claim primitive, never authority. */
  assignedRunner: string | null;
  /** The coordinator that filed this task (v31) — authoritative linkage,
   * written only by the branded door; null is every other filer. */
  coordinatorCid: string | null;
  zones: string[];
  capabilityRequirements: string[];
  parkRate: number;
  /** Consecutive concluded failures. Three stalls the task; any success resets. */
  strikes: number;
  /** Planning mode: 'requested' dispatches a planner; 'drafted' awaits review. */
  plan: "requested" | "drafted" | null;
  /** Planning failures, counted apart from build strikes by design. */
  planStrikes: number;
  /** What comes back (v34): a branch to publish, or a report to read.
   * Set at filing and never rewritten — a scout's strikes are the task's. */
  deliverable: "branch" | "report";
  /** The standing order this task is an instance of; null for one-off work. */
  routineId: number | null;
  /** The pinned agent, when a fire transaction stamped one. Authoritative. */
  agentProvider: string | null;
  agentModel: string | null;
  /** Durable per-task override. null means the installation default is used
   * the next time this task's scope is filed. Approved scopes still bind the
   * concrete provider argv and never change under a setting edit. */
  permissionMode?: UnattendedPermissionMode | null;
  /** Durable per-task evidence-policy override. null inherits the
   * installation default when a scope is next written. */
  qualityMode?: QualityMode | null;
  /** v47: the task's declared risk; null reads as routine when the next
   * scope is filed. The scope stores the signed level. */
  riskLevel?: RiskLevel | null;
  /** v47: the approver's per-phase route overrides, applied when the next
   * scope is filed and recorded in the sealed route. null = the stored
   * list is malformed; the next filing goes unresolved rather than routing
   * as if nobody had overridden anything. */
  routeOverrides?: RouteOverride[] | null;
  /** v2 routing: how big the change is (sized at filing by the classifier
   * or the description, or set by a person); null when never sized. */
  sizing?: TaskSizing | null;
  /** The build tier the task's latest filed route chose (light, routine,
   * strong — or override/pinned when a person or a pin chose the agent). */
  routeTier?: string | null;
  /** Plan pins (P2/C7): read ONLY by the plan phase; precedence plan pin
   * > plan flags > plan config > installation > default. */
  planProvider: string | null;
  planModel: string | null;
  /** The task whose reviewed run this one revises (M6.8); null ordinarily. */
  revisionOf: string | null;
  /** The immutable brief artifact carrying the exact comment batch. */
  revisionBriefArtifact: number | null;
  /** Recorded, not asserted: what the grant's selector is checked against. */
  origin: TaskOrigin;
};

/** A standing order: a pre-approved template whose instances build unattended. */

