export type TeammateMemoryRow = { id: number; teammate: number; text: string; source: "teammate" | "person"; card: number | null; createdBy: string; createdAt: string; updatedBy: string; updatedAt: string; usedAt: string | null };
/** v95: a rule change a teammate suggests from what its people approved. */
export type TeammateSuggestionRow = { id: number; teammate: number; tool: string; action: string; rule: ToolRule; was: ToolRule; evidence: number[]; said: string;
  state: "open" | "accepted" | "dismissed" | "stale"; decidedBy: string | null; decidedAt: string | null; createdAt: string };

function readTeammateMemory(row: Record<string, unknown>): TeammateMemoryRow {
  return { id: Number(row["id"]), teammate: Number(row["teammate"]), text: String(row["text"]), source: String(row["source"]) as TeammateMemoryRow["source"], card: row["card"] === null ? null : Number(row["card"]),
    createdBy: String(row["created_by"]), createdAt: String(row["created_at"]), updatedBy: String(row["updated_by"]), updatedAt: String(row["updated_at"]), usedAt: row["used_at"] === null ? null : String(row["used_at"]) };
}

function readTeammateSuggestion(row: Record<string, unknown>): TeammateSuggestionRow {
  const parsed = <T>(key: string, fallback: T): T => { try { return JSON.parse(String(row[key])) as T; } catch { return fallback; } };
  return { id: Number(row["id"]), teammate: Number(row["teammate"]), tool: String(row["tool"]), action: String(row["action"]), rule: parsed<ToolRule>("rule_json", { use: "ask" }), was: parsed<ToolRule>("was_json", { use: "ask" }),
    evidence: parsed<number[]>("evidence_json", []), said: String(row["said"]), state: String(row["state"]) as TeammateSuggestionRow["state"],
    decidedBy: row["decided_by"] === null ? null : String(row["decided_by"]), decidedAt: row["decided_at"] === null ? null : String(row["decided_at"]), createdAt: String(row["created_at"]) };
}
/** v94: one action a project tool offers, as it described itself when listed. */
export type ToolActionInfo = { name: string; about: string; input: Record<string, unknown> | null; readOnly: boolean };
/** v94: a teammate's rule for one action: do it, ask first, or never; "free" may ask first above a number in its input. */
export type ToolRule = { use: "free" | "ask" | "never"; limit?: { field: string; over: number };
  /** v97: another action of the same tool that undoes this one, called with the same input when a person presses Undo. */
  undo?: string };
export type TeammateGrantRow = { teammate: number; tool: string; actions: ToolActionInfo[]; rules: Record<string, ToolRule>; listedAt: string | null; updatedBy: string; updatedAt: string };
export type TeammateCallState = "asked" | "approved" | "denied" | "refused" | "running" | "done" | "failed";
/** v94: a tool call a teammate made, or asked to make, on one visit of a card: the receipt. */
export type TeammateCallRow = { id: number; teammate: number; card: number; entry: number; tool: string; action: string; input: Record<string, unknown>; rule: ToolRule["use"]; why: string;
  state: TeammateCallState; result: string | null; decidedBy: string | null; decidedAt: string | null; createdAt: string; doneAt: string | null;
  /** v97: the call this one undid (a person's Undo), and who undid this one. */
  undoOf: number | null; undoneBy: string | null; undoneAt: string | null };
/** v97: one model turn a teammate took. */
export type TeammateTurnRow = { id: number; teammate: number; card: number | null; model: string; ok: boolean; ms: number; costUsd: number | null; tokensIn: number | null; tokensOut: number | null; at: string };

function readTeammateCall(row: Record<string, unknown>): TeammateCallRow {
  const text = (key: string) => row[key] === null || row[key] === undefined ? null : String(row[key]);
  let input: Record<string, unknown> = {};
  try { input = JSON.parse(String(row["input_json"])) as Record<string, unknown>; } catch { input = {}; }
  return { id: Number(row["id"]), teammate: Number(row["teammate"]), card: Number(row["card"]), entry: Number(row["entry"]), tool: String(row["tool"]), action: String(row["action"]), input,
    rule: String(row["rule"]) as ToolRule["use"], why: String(row["why"]), state: String(row["state"]) as TeammateCallState, result: text("result"), decidedBy: text("decided_by"), decidedAt: text("decided_at"),
    createdAt: String(row["created_at"]), doneAt: text("done_at"), undoOf: row["undo_of"] === null || row["undo_of"] === undefined ? null : Number(row["undo_of"]), undoneBy: text("undone_by"), undoneAt: text("undone_at") };
}

function readTeammateGrant(row: Record<string, unknown>): TeammateGrantRow {
  const parsed = <T>(key: string, fallback: T): T => { try { return JSON.parse(String(row[key])) as T; } catch { return fallback; } };
  return { teammate: Number(row["teammate"]), tool: String(row["tool"]), actions: parsed<ToolActionInfo[]>("actions_json", []), rules: parsed<Record<string, ToolRule>>("rules_json", {}),
    listedAt: row["listed_at"] === null ? null : String(row["listed_at"]), updatedBy: String(row["updated_by"]), updatedAt: String(row["updated_at"]) };
}

function readTeammateRow(row: Record<string, unknown>): TeammateRow {
  return { id: Number(row["id"]), repo: String(row["repo"]), handle: String(row["handle"]), state: String(row["state"]) as TeammateRow["state"], version: Number(row["version"]), soul: String(row["soul"]),
    model: row["model"] === null ? null : String(row["model"]), dailyTurns: Number(row["daily_turns"]), manager: String(row["manager"]), createdBy: String(row["created_by"]), createdAt: String(row["created_at"]),
    updatedBy: String(row["updated_by"]), updatedAt: String(row["updated_at"]), summaryAt: row["summary_at"] === null ? null : String(row["summary_at"]),
    deskFlow: row["desk_flow"] === null || row["desk_flow"] === undefined ? null : Number(row["desk_flow"]),
    weeklyAt: row["weekly_at"] === null || row["weekly_at"] === undefined ? null : String(row["weekly_at"]) };
}
function readTeammateQuestion(row: Record<string, unknown>): TeammateQuestionRow {
  const text = (key: string) => row[key] === null || row[key] === undefined ? null : String(row[key]);
  return { id: Number(row["id"]), teammate: Number(row["teammate"]), card: Number(row["card"]), entry: Number(row["entry"]), question: String(row["question"]),
    options: JSON.parse(String(row["options_json"])) as { id: string; label: string }[], askedOf: String(row["asked_of"]), state: String(row["state"]) as TeammateQuestionRow["state"],
    choice: text("choice"), answer: text("answer"), answeredBy: text("answered_by"), answeredVia: text("answered_via"), answeredAt: text("answered_at"), createdAt: String(row["created_at"]),
    toolCall: row["tool_call"] === null || row["tool_call"] === undefined ? null : Number(row["tool_call"]),
    suggestion: row["suggestion"] === null || row["suggestion"] === undefined ? null : Number(row["suggestion"]) };
}
/** A flow; `owner` is who its "the owner decides" zones ask (v86): whoever made it, unless it was handed to someone else. */
export type FlowRow = { id: number; repo: string; name: string; definitionJson: string; revision: number; state: "active" | "archived"; createdBy: string; createdAt: string; updatedBy: string; updatedAt: string; owner: string };
export type FlowStepRunRow = { card: number; entry: number; stage: string; kind: FlowStepKind; script: string | null; scriptVersion: number | null; state: "running" | "passed" | "failed" | "waiting"; attempts: number;
  nextAt: string | null; startedAt: string; finishedAt: string | null; durationMs: number | null; exitCode: number | null; result: string | null; log: string | null;
  /** sort: what Jev answered, as JSON (flow-sort.ts reads it). */
  decisionJson: string | null };
/** A project script (v84). v90: in shell, Python or Node; `file` (a path in the project) runs instead of the body. */
export type FlowScriptRow = { id: number; repo: string; name: string; about: string; body: string; timeoutMinutes: number; version: number; digest: string; savedBy: string; savedAt: string;
  language: "shell" | "python" | "node"; file: string | null;
  /** Why it can't run yet ("imported": it came in with a flow file and waits for a person's approval); null when it runs. */
  held: string | null };
/** Where a card came from when a trigger made it: what to call it and where to look (a GitHub issue, a Linear issue, another flow's card). */
/** Where a card came from. `mail` (v89): the email it came from, so a reply to its sender stays in the thread.
 * `chat` (v89): the chat message it came from — the app, the channel, the conversation to answer in, the
 * message's thread, and the pairing that connected the channel (whose chat answers there). */
export type FlowCardSource = { kind: string; label: string; url: string | null; mail?: { id: string | null; references: string[]; subject: string; from: string };
  chat?: { app: string; installation: string; chat: string; conversation: string; thread: string; binding: number } };
export type FlowCardRow = { id: number; flow: number; title: string; description: string | null; stage: string; entry: number; state: "active" | "done" | "cancelled"; task: string | null; primaryTask: string | null; note: string | null; waiting: string | null; outputs: Record<string, string>; createdBy: string; createdAt: string; updatedAt: string; source: FlowCardSource | null; owner: string | null };
/** One line of a card's discussion: a comment (and whom it @mentioned), or who became its owner. */
export type FlowCommentRow = { id: number; card: number; kind: "comment" | "owner"; author: string; body: string; mentions: string[]; at: string };
export type FlowTriggerRow = { id: number; flow: number; kind: string; configJson: string; state: "active" | "paused" | "removed"; hookHash: string | null; cursor: string | null; nextAt: string | null; lastAt: string | null; lastOutcome: string | null; failures: number; createdBy: string; createdAt: string; updatedAt: string };
export type FlowEventOutcome = "created" | "ok" | "fail" | "moved" | "approved" | "sent-back" | "cancelled";

function readFlowRow(row: Record<string, unknown>): FlowRow {
  return { id: Number(row["id"]), repo: String(row["repo"]), name: String(row["name"]), definitionJson: flowDefinitionFromStore(String(row["definition_json"])), revision: Number(row["revision"]),
    state: String(row["state"]) as FlowRow["state"], createdBy: String(row["created_by"]), createdAt: String(row["created_at"]), updatedBy: String(row["updated_by"]), updatedAt: String(row["updated_at"]),
    owner: row["owner"] === null || row["owner"] === undefined ? String(row["created_by"]) : String(row["owner"]) };
}

function readFlowScriptRow(row: Record<string, unknown>): FlowScriptRow {
  return { id: Number(row["id"]), repo: String(row["repo"]), name: String(row["name"]), about: String(row["about"]), body: String(row["body"]), timeoutMinutes: Number(row["timeout_minutes"]),
    version: Number(row["version"]), digest: String(row["digest"]), savedBy: String(row["saved_by"]), savedAt: String(row["saved_at"]),
    language: row["language"] === "python" || row["language"] === "node" ? row["language"] : "shell", file: row["file"] === null || row["file"] === undefined ? null : String(row["file"]),
    held: row["held"] === null || row["held"] === undefined ? null : String(row["held"]) };
}

function readFlowStepRunRow(row: Record<string, unknown>): FlowStepRunRow {
  const optional = (key: string) => row[key] === null || row[key] === undefined ? null : String(row[key]);
  const number = (key: string) => row[key] === null || row[key] === undefined ? null : Number(row[key]);
  return { card: Number(row["card"]), entry: Number(row["entry"]), stage: String(row["stage"]), kind: String(row["kind"]) as FlowStepRunRow["kind"], script: optional("script"), scriptVersion: number("script_version"),
    state: String(row["state"]) as FlowStepRunRow["state"], attempts: Number(row["attempts"]), nextAt: optional("next_at"), startedAt: String(row["started_at"]), finishedAt: optional("finished_at"),
    durationMs: number("duration_ms"), exitCode: number("exit_code"), result: optional("result"), log: optional("log"), decisionJson: optional("decision_json") };
}

function readFlowCardRow(row: Record<string, unknown>): FlowCardRow {
  let outputs: Record<string, string> = {};
  try { const parsed = JSON.parse(String(row["outputs_json"] ?? "{}")) as unknown; if (parsed !== null && typeof parsed === "object") outputs = Object.fromEntries(Object.entries(parsed as Record<string, unknown>).filter((entry): entry is [string, string] => typeof entry[1] === "string")); } catch { outputs = {}; }
  const optional = (key: string) => row[key] === null || row[key] === undefined ? null : String(row[key]);
  return { id: Number(row["id"]), flow: Number(row["flow"]), title: String(row["title"]), description: optional("description"), stage: String(row["stage"]), entry: Number(row["entry"]),
    state: String(row["state"]) as FlowCardRow["state"], task: optional("task"), primaryTask: optional("primary_task"), note: optional("note"), waiting: optional("waiting"), outputs,
    createdBy: String(row["created_by"]), createdAt: String(row["created_at"]), updatedAt: String(row["updated_at"]), source: readFlowCardSource(row["source_json"]), owner: optional("owner") };
}

function readFlowCardSource(value: unknown): FlowCardSource | null {
  if (typeof value !== "string") return null;
  try {
    const parsed = JSON.parse(value) as Record<string, unknown>;
    if (typeof parsed["label"] !== "string") return null;
    const mail = parsed["mail"] !== null && typeof parsed["mail"] === "object" ? parsed["mail"] as Record<string, unknown> : null;
    const chat = parsed["chat"] !== null && typeof parsed["chat"] === "object" ? parsed["chat"] as Record<string, unknown> : null;
    return { kind: String(parsed["kind"] ?? ""), label: parsed["label"], url: typeof parsed["url"] === "string" ? parsed["url"] : null,
      ...(mail === null || typeof mail["from"] !== "string" ? {} : { mail: { id: typeof mail["id"] === "string" ? mail["id"] : null, references: Array.isArray(mail["references"]) ? mail["references"].filter((one): one is string => typeof one === "string") : [],
        subject: typeof mail["subject"] === "string" ? mail["subject"] : "", from: mail["from"] } }),
      ...(chat === null || typeof chat["app"] !== "string" || typeof chat["chat"] !== "string" || typeof chat["thread"] !== "string" || typeof chat["binding"] !== "number" ? {} : { chat: {
        app: chat["app"], installation: String(chat["installation"] ?? ""), chat: chat["chat"], conversation: typeof chat["conversation"] === "string" ? chat["conversation"] : chat["chat"], thread: chat["thread"], binding: chat["binding"] } }) };
  } catch { return null; }
}

function readFlowTriggerRow(row: Record<string, unknown>): FlowTriggerRow {
  const optional = (key: string) => row[key] === null || row[key] === undefined ? null : String(row[key]);
  return { id: Number(row["id"]), flow: Number(row["flow"]), kind: String(row["kind"]), configJson: String(row["config_json"]), state: String(row["state"]) as FlowTriggerRow["state"],
    hookHash: optional("hook_hash"), cursor: optional("cursor"), nextAt: optional("next_at"), lastAt: optional("last_at"), lastOutcome: optional("last_outcome"),
    failures: Number(row["failures"] ?? 0), createdBy: String(row["created_by"]), createdAt: String(row["created_at"]), updatedAt: String(row["updated_at"]) };
}

/** The one task a card is about: a task its confirmation created (a new
 * task, a revision), else the task it names (and, for feedback on a result,
 * that result). Null for a card about no single task. A pointer for
 * replies, never an authority. */
export function proposalTaskOf(proposal: MateProposal | null): { task: string; run: number | null } | null {
  if (proposal === null) return null;
  const named = typeof proposal.payload["task"] === "string" && proposal.payload["task"] !== "" ? proposal.payload["task"] : null;
  const creates = proposal.kind === "task" || (proposal.kind === "review" && proposal.payload["operation"] === "revise");
  const made = creates && proposal.state === "confirmed" ? proposal.outcome?.["taskId"] : undefined;
  if (typeof made === "string" && made !== "" && made !== named) return { task: made, run: null };
  if (named === null) return null;
  const run = proposal.kind === "review" ? proposal.payload["run"] : null;
  return { task: named, run: typeof run === "number" && Number.isSafeInteger(run) ? run : null };
}

export type MateTurn = {
  id: number;
  approver: string;
  session: number;
  thread: number;
  credentialKey: string;
  state: "queued" | "running" | "answered" | "failed";
  generation: number;
  createdAt: string;
  deadlineAt: string;
  finishedAt: string | null;
  reservedMicrousd: number;
  settledMicrousd: number | null;
  steps: number;
  tokensIn: number | null;
  tokensOut: number | null;
  failureReason: string | null;
};

export type Routine = {
  id: number;
  name: string;
  /** v102: who made it (its instances are filed as theirs); null before v102 or when no person is known. */
  createdBy: string | null;
  repo: string;
  goal: string;
  outOfScope: string | null;
  touches: string[];
  /** v39: the signed rubric every instance's scope copies forward. */
  acceptance: AcceptanceCriterion[];
  requirements: string[];
  /** 'every:<minutes>', 'daily:<HH:MM>[@Zone]', or 'weekly:<0-6>:<HH:MM>[@Zone]' (UTC by default). */
  schedule: string;
  singleFlight: boolean;
  /** Rolling 7-day dollar ceiling; null = none. Enforcement fails closed. */
  costCeilingUsd: number | null;
  /** Per-instance dollar cap (v16); copied into each instance's scope. */
  budgetPerRunMicrousd: number | null;
  paused: boolean;
  /** Of every term above. Approval binds to this exact value. */
  digest: string;
  approvedAt: string | null;
  approvedBy: string | null;
  approvedDigest: string | null;
  /** The next scheduled occurrence; null until approved. */
  nextFireAt: string | null;
  /** Immutable filing provenance (v12); null on rows from before it existed. */
  filedVia: string | null;
  createdAt: string;
  updatedAt: string;
  /** v24: the working execution profile and the approval's sealed snapshot. */
  profile?: ExecutionProfile | null;
  approvedProfile?: ExecutionProfile | null;
  /** v48: the four-role agent route the digest binds, and the snapshot the
   * approval sealed. Null on a routine filed before routing froze — such a
   * routine cannot be approved or fired until it is filed again. A row
   * carrying unreadable route bytes reads null too, and fails closed. */
  route?: PhaseRoute | null;
  approvedRoute?: PhaseRoute | null;
  /** v48: true when the row CARRIES route or profile bytes that do not
   * read back — a corrupt snapshot, as distinct from one never taken. Every
   * surface says which, and both fail closed. */
  routeUnreadable?: boolean;
  approvedRouteUnreadable?: boolean;
  approvedProfileUnreadable?: boolean;
  /** THE RAW TERMS VERDICT (raw authority repair): null when every stored
   * term the digest binds read back EXACTLY — touches and requirements as
   * JSON lists of strings, the rubric as whole criteria with no unknown
   * key, the flags as 0/1, the ceilings as numbers or null — and the words
   * when one did not. The integrity projection reads it FIRST: a row whose
   * terms cannot be read exactly is not approved, not live, not approvable,
   * and not refreshable, so the lenient fields above can never become a
   * firing's authority. Undefined on a hand-built routine. */
  termsProblem?: string | null;
};

/** One scheduled slot's outcome, fired or skipped — never silent. */
export type RoutineFire = {
  id: number;
  routineId: number;
  scheduledFor: string;
  outcome: "fired" | "skipped";
  reason: string | null;
  instanceTaskRef: number | null;
  createdAt: string;
};

/** Who placed a hold — and therefore who alone may lift it. */
/** 'stop' (v52) = the pause one exact attempt's operator stop placed — lifted
 * only by resuming THAT attempt, never by `unhold` or by answering a decision. */
export type HoldOwner = "operator" | "decision" | "incident" | "backoff" | "contest" | "revision" | "stop";

export type Hold = {
  id: number;
  taskRef: number;
  ownerKind: HoldOwner;
  ownerId: string;
  reason: string;
  until: string | null;
  heldAt: string;
};

/** Something a repo's work needs. Metadata only; the value lives on the runner. */
export type Capability = {
  repo: string;
  kind: "env" | "cli" | "mcp" | "ci" | "other";
  name: string;
  /** A command whose exit 0 means "present and alive". null: nothing can vouch. */
  probe: string | null;
  status: "unprobed" | "verified" | "failed";
  addedBy: string;
  createdAt: string;
  lastVerifiedAt: string | null;
  /** Whose environment answered the probe. Verification is a claim about one machine. */
  verifiedBy: string | null;
  /** What the probe said when it said no. */
  lastResult: string | null;
  expiresAt: string | null;
};

/** `kind:name`, the unambiguous way a requirement names a capability. */
export function capabilityKey(capability: Pick<Capability, "kind" | "name">): string {
  return `${capability.kind}:${capability.name}`;
}

/** Parse `kind:name`; a bare name is refused rather than guessed at. */
export function parseCapabilityKey(
  key: string,
): { kind: Capability["kind"]; name: string } | null {
  const split = key.indexOf(":");
  if (split <= 0 || split === key.length - 1) return null;
  const kind = key.slice(0, split);
  if (!["env", "cli", "mcp", "ci", "other"].includes(kind)) return null;
  return { kind: kind as Capability["kind"], name: key.slice(split + 1) };
}

/** Supplied by the producer, never inferred from display text or links. */
export type NotificationSource = { run: number } | { taskRef: number } | { project: string } | { installation: true };
type NotificationInput = { dedupeKey: string; kind: string; subject: string; body: string; pushClass?: "decision" | "pick" | "merge" | "attention"; link?: string; source?: NotificationSource;
  /** v83: one person's notification — only their own phone, chats and browsers get it; no channel-wide webhook does. */
  recipient?: string };

/**
 * Task lifecycle updates (Telegram task updates, 2026-09-16): the CLOSED
 * vocabulary of routine progress facts the shared mutations record beside
 * the change that made them true. None carries a push class — they are
 * digest-eligible progress, never a page — and every one is project-bound
 * through the task it names. A decision, incident, gap, stall, publication
 * or merge page keeps its own producer; nothing here repeats one.
 */
export const LIFECYCLE_KINDS = [
  "task-filed",
  "scope-approved",
  "approval-withdrawn",
  "task-held",
  "task-released",
  "task-queued",
  "task-requeued",
  "task-cancelled",
  "run-started",
  "run-phase",
  "check-progress",
  "run-finished",
  "run-stopping",
  "run-stopped",
  "run-resumed",
  "review-requested",
  "review-finished",
  "acceptance-evidence",
  "acceptance-ready",
] as const;
export type LifecycleKind = (typeof LIFECYCLE_KINDS)[number];
/** Every lifecycle dedupe key starts here: `life:<kind>:<identity>:<ordinal>`. */
export const LIFECYCLE_KEY_PREFIX = "life:";
/** A progress fact, told apart by its durable key — never by display text. */
export function isLifecycleNotification(row: Pick<Notification, "dedupeKey">): boolean {
  return row.dedupeKey.startsWith(LIFECYCLE_KEY_PREFIX);
}

/** Only known progress producers can repaint a card. Decisions and urgent
 * incidents keep their own alerts; a routine retry updates its saved attempt. */
export function isTelegramProgressNotification(row: Pick<Notification, "dedupeKey" | "kind" | "pushClass" | "run">): boolean {
  if (row.kind === "check-progress" && row.pushClass === "progress" && row.run !== null) return isLifecycleNotification(row);
  if (row.pushClass !== null) return false;
  if (row.kind === "build-failed" && row.run !== null && row.dedupeKey === `run:${row.run}:failed`) return true;
  // The owner's lead took the attempt on, or let it lapse (lead-voice.ts): its card repaints in place.
  if ((row.kind === "lead-on-it" || row.kind === "lead-lapsed") && row.run !== null) return true;
  return isLifecycleNotification(row) &&
    ["run-started", "run-phase", "run-finished", "review-requested", "review-finished", "run-stopping", "run-stopped", "run-resumed", "task-held", "task-released"].includes(row.kind);
}

/** Display words for a lifecycle fact: one line, control-free, bounded, with
 * paths and long hex hidden the way the phone scrub hides them. The inputs
 * are already validated task text or identifiers; this is the belt. */
function lifecycleWords(value: string, cap: number): string {
  // Scan the original value: shortening a credential first can make it
  // unrecognizable to the detector while still leaking part of it.
  if (scanForSecrets(value).length > 0 || /\b\d{5,}:[A-Za-z0-9_-]{20,}\b/.test(value)) return "[sensitive text hidden]";
  const text = value
    .replace(/(?:[A-Za-z]:[\\/]|\\\\)[^\s"'<>]+/g, "[path]")
    .replace(/(^|[\s"'`(<[=:,])\/(?:[A-Za-z0-9._~-]+\/)*[A-Za-z0-9._~-]+/g, "$1[path]")
    .replace(/\b[0-9a-f]{32,}\b/gi, "[digest]")
    .replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060-\u206f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return text.length <= cap ? text : `${text.slice(0, cap - 1).replace(/[\uD800-\uDBFF]$/, "")}…`;
}

/** The phase words a phone reads: what the machine is doing to the attempt now. */
const LIFECYCLE_PHASE_WORDS: Record<RunPhase, { subject: string; body: string }> = {
  "agent-running": { subject: "agent working", body: "The agent is working in its own checkout. Nothing is finished yet." },
  "validating-handoff": { subject: "checking the handoff", body: "The agent finished its turn; what it handed back is being checked." },
  "capturing-evidence": { subject: "capturing evidence", body: "The diff, checks and proof are being captured." },
  "committing": { subject: "committing", body: "The work is being committed on the task branch." },
  "verifying-proof": { subject: "verifying the proof", body: "The proof is being checked against the approved acceptance criteria." },
  "correcting-proof": { subject: "correcting the proof", body: "The proof did not match the sealed result; a bounded correction turn is running." },
};

/** An operator's cancellation as one closed sentence: the reason, if any,
 * scrubbed like every phone string and ended with a full stop unless it
 * already ends one (a shortened reason ends in an ellipsis). */
function cancellationWords(reason: string | null): string {
  if (reason === null || reason.trim() === "") return "Cancelled by an operator.";
  const words = lifecycleWords(reason, 120);
  return `Cancelled by an operator: ${words}${/[.!?…]$/.test(words) ? "" : "."}`;
}

/** What an independent review concluded, in the words the saved result shows. */
const LIFECYCLE_REVIEW_WORDS: Record<"verified" | "attested" | "short" | "refuted" | "none", { subject: string; body: string }> = {
  verified: { subject: "checks verified", body: "Every acceptance check was verified against the saved result." },
  refuted: { subject: "evidence conflicts with the result", body: "The reviewer found evidence that contradicts the saved result. It is not accepted as done." },
  attested: { subject: "agent-reported evidence only", body: "The result rests on agent-reported evidence that was not independently verified." },
  short: { subject: "required evidence is missing", body: "Required evidence is missing from the saved result." },
  none: { subject: "comments only", body: "The reviewer left comments; no acceptance judgement was recorded." },
};

/** Why a task still waits after one hold lifts — the other owner, in words. */
const LIFECYCLE_HOLD_WORDS: Record<HoldOwner, string> = {
  operator: "an operator's hold",
  decision: "an unanswered question",
  incident: "an unresolved incident",
  backoff: "its retry backoff",
  contest: "a tournament",
  revision: "a plan revision awaiting approval",
  stop: "a stopped attempt that has not been resumed",
};

/** A fact that wants a person, durably. */
export type Notification = {
  id: number;
  /** v83: the one person this is for, or null for everyone it concerns. */
  recipient: string | null;
  dedupeKey: string;
  kind: string;
  subject: string;
  body: string;
  createdAt: string;
  attempts: number;
  lastAttemptAt: string | null;
  lastError: string | null;
  deliveredAt: string | null;
  receipt: string | null;
  /** The closed push attention class, or null = this fact never pushes. */
  pushClass: "decision" | "pick" | "merge" | "attention" | "progress" | null;
  /** The machine-minted console path a push may deep-link — never free text. */
  link: string | null;
  /**
   * When the fact stopped wanting a person — a decision answered, an incident
   * resolved. Distinct from delivery, and it never deletes the row: receipts
   * are the audit trail of what was actually sent.
   */
  resolvedAt: string | null;
  scope: "unknown" | "installation" | "project" | "task";
  project: string | null;
  taskRef: number | null;
  taskId: string | null;
  run: number | null;
};

export type TelegramDelivery = Notification & { destination: string; claimGeneration: number };

/** How chats reach one person (quiet chat): only when they are needed, or every step. */
export type NotificationMode = "quiet" | "all";
/** Screenshots with results: none (the default), the first one, or up to four (result-shots.ts). */
export type ResultScreenshots = "off" | "first" | "all";
export const RESULT_SCREENSHOTS: readonly ResultScreenshots[] = ["off", "first", "all"];
export type NotificationPreference = { mode: NotificationMode; digestAt: string | null; digestOn: string | null; updatedAt: string | null; screenshots: ResultScreenshots };
/** One person's saved screenshots following a result message: its own outbox row, addressed to them (result-shots.ts). */
export const RESULT_SHOTS_KIND = "result-screenshots";
/** The screenshots a flow's "Send to me" or "Person chooses" visit sends its person (flow-send.ts): up to four, whatever
 * their result-screenshots choice, since the flow asked for them. */
export const FLOW_SHOTS_KIND = "flow-screenshots";
/** Tasks filed this close together share one chat message. */
export const QUIET_GROUP_MS = 60_000;
export function isDigestTime(value: string): boolean {
  return /^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/.test(value);
}
/** The one chat message a destination keeps for a task, or for several tasks filed together. */
export type ChatCard = { id: number; destination: string; anchorAt: string; message: string | null; digest: string | null; tasks: number[] };
export type ChatBatch = { id: number; destination: string; openedAt: string; message: string | null; digest: string | null;
  items: { taskRef: number; run: number | null; notification: number | null }[] };


/**
 * What one recovery walk over a gone runner's work settled (P0.1a): the run
 * ids it finished as failed/interrupted and the built-in task ids it returned
 * to the queue because no newer live lease owned them. Both empty on a
 * repeat pass — the walk is idempotent by construction.
 */
export type RunnerWorkRecovery = {
  runs: number[];
  requeued: string[];
};

/** How a stop's settlement was established (v52). `interrupted` = the
 * owning worker sealed the attempt after its processes ended; `held` = the
 * held-session supervisor fenced it; `recovered` = dead-incarnation
 * recovery settled a run whose worker is proven gone; `finished` = the
 * attempt reached another ending first (the stop was recorded, but the
 * run's own outcome stands — the words say which). */
export type StopSettlement = "interrupted" | "recovered" | "held" | "finished";

/** One exact attempt's operator stop (v52) — its provenance, its settlement,
 * and the resume that lifted it, all on one row. */
export type RunStop = {
  run: number;
  taskRef: number;
  requestedBy: string;
  requestedVia: StopVia;
  requestedAt: string;
  settledAt: string | null;
  settlement: StopSettlement | null;
  resumedAt: string | null;
  resumedBy: string | null;
  resumedVia: StopVia | null;
};

/** Which surface asked for a stop or a resume — named by the caller, never defaulted. */
export type StopVia = "cli" | "web" | "telegram" | "slack" | "discord" | "teams";

/** One ROOT review attempt of a source run (v50): the reviewer run, its
 * ordinal, how it ended, and the request it was spent on. */
export type ReviewAttemptRow = {
  runId: number;
  attempt: number;
  outcome: Run["outcome"];
  reason: string | null;
  runner: string;
  provider: string;
  model: string | null;
  startedAt: string;
  finishedAt: string | null;
  requestId: number | null;
};

/** How a review ask was produced (v50, explicit-only retries): a fresh
 * credentialed operator act, or a build disposition's one-shot producer. */
export type ReviewRequestOrigin = "operator" | "automatic";

/**
 * One source run's bounded review history (v50): every root attempt in
 * ordinal order, the open request if one is queued, and the ONE state the
 * facts add up to. `retriesRemaining` counts explicit retries still
 * admissible (a queued request has already spent one); `nextAttempt` is
 * the ordinal the queued or next request runs as.
 *
 *   unrequested — no attempt yet and nothing queued (the plain first ask)
 *   queued      — a request waits for a pass (attempt `nextAttempt`)
 *   running     — a root reviewer is open right now
 *   succeeded   — a root ingested its review; the allowance is closed
 *   retryable   — the latest root ended failed/interrupted; a retry may be asked
 *   exhausted   — REVIEW_ROOT_ATTEMPTS roots ended without a review
 */
export type ReviewRetryState = {
  cap: number;
  attempts: ReviewAttemptRow[];
  openRequest: { id: number; requestedBy: string; basis: "human" | "mode"; origin: ReviewRequestOrigin; requestedAt: string } | null;
  live: ReviewAttemptRow | null;
  latest: ReviewAttemptRow | null;
  succeeded: ReviewAttemptRow | null;
  state: "unrequested" | "queued" | "running" | "succeeded" | "retryable" | "exhausted";
  retriesUsed: number;
  retriesRemaining: number;
  nextAttempt: number | null;
};

/** One build attempt. `outcome` null means it never finished — also an answer. */
export type Run = {
  id: number;
  taskRef: number;
  leaseId: string;
  runner: string;
  /** Explicit watch ownership for claimless review runs; null on cron/legacy reviews. */
  watchIncarnation?: string | null;
  /** v50: a ROOT reviewer's attempt ordinal for its source run (1..3);
   * null on correction children and every other role. */
  reviewAttempt?: number | null;
  /** 'repair' = a resumed session mending its own park payload. Never
   * 'driver'; see the DDL. 'reviewer' (v29) = an artifact-only pass.
   * 'scout' (v34) = a read-only investigation whose deliverable is a report. */
  role: "builder" | "repair" | "planner" | "reviewer" | "scout";
  /** Which harness ran it. History is 'claude' truthfully: nothing else ever spawned. */
  provider: string;
  parentRun: number | null;
  sessionId: string | null;
  baseRevision: string | null;
  /** v24 dispatch stamps; null on runs from before them. */
  scopeDigest?: string | null;
  profileDigest?: string | null;
  /** v41: the scope-bound evidence policy this exact attempt ran under. */
  qualityMode?: QualityMode;
  /** NULL on exactly the reviewer role (v29 exclusive CHECK): an
   * artifact-only run never had a workspace, and every consumer must say
   * so rather than dereference one that does not exist. */
  branch: string | null;
  worktree: string | null;
  model: string | null;
  /** 'interrupted' (v25) = a held attended session cut down mid-flight. */
  outcome: "built" | "failed" | "refused" | "parked" | "no-change" | "interrupted" | null;
  reason: string | null;
  /** The attended authorization this run consumed (v25); null = ordinary dispatch. */
  attendedAuthorization?: string | null;
  committed: boolean | null;
  startedAt: string;
  finishedAt: string | null;
  /** Stamped by the invocation gateway just before the provider spawns. */
  providerStartedAt: string | null;
  /** The provider binary's probed version — attested authoritatively for
   * tier-2 providers, best-effort provenance for tier-1 (Phase 3 B2). */
  providerVersion: string | null;
  tokensIn: number | null;
  tokensOut: number | null;
  costUsd: number | null;
  /** HEAD after the agent, as accepted — what a publication may push. */
  headRevision: string | null;
  /** The validated terminal handoff's conclusion. */
  handoff: string | null;
  /** When racing: which tournament agent this run belongs to. */
  contestant: number | null;
  /**
   * Where the machine is in ITS OWN state machine — stamped by the control
   * plane at boundaries it owns, never parsed from a provider stream (M5.4).
   * Meaningful while the run is open; the last value simply remains after.
   */
  phase: RunPhase | null;
  /**
   * The fallback-chain metadata (v30), NULL on every run outside a chain.
   * `chainCycle`/`chainIndex`/`entryDigest` are stamped at admission (or at
   * base-cycle open) and bind the run to exactly one entry of an immutable
   * approved chain — the runtime re-derives authority from the snapshot,
   * never from these, but reads them to know which entry ran.
   */
  chainCycle?: number | null;
  chainIndex?: number | null;
  entryDigest?: string | null;
  /**
   * How this attempt authenticated (v30) — 'subscription' or 'api-key' —
   * stamped by the gateway. Decides which exhaustion class a match yields.
   */
  authMode?: "subscription" | "api-key" | null;
  /**
   * The gateway's honest classification of how this attempt ENDED (v30),
   * computed at disposal from the structural terminal + the authoritative
   * version + auth mode (exhaustion.ts). Fail-closed: 'unknown' until a
   * fixture-backed recognizer exists. NEVER an authority by itself — the
   * dispatch's C8 gate re-checks hasRecognizer before any advance.
   */
  terminalClass?: TerminalClass | null;
  /** v44 (adaptive execution plans): the exact plan revision this attempt's
   * brief was built from, and the authority snapshot digest at that moment
   * (`authoritySnapshotDigest` of the signed scope digest + publication
   * authority). Null on every run before the feature, and on any role that
   * carries no plan (a scout, a reviewer). */
  planRevision?: number | null;
  authorityDigest?: string | null;
};

/** The bounded activity vocabulary. Machine-authored — a model's prose never becomes one of these. */
export const RUN_PHASES = [
  "agent-running",
  "validating-handoff",
  "capturing-evidence",
  "committing",
  "verifying-proof",
  "correcting-proof",
] as const;
export type RunPhase = (typeof RUN_PHASES)[number];

// ---- attended core (v25, Parity II Phase 2) --------------------------------

/**
 * One person's signed authority for ONE watched attempt (ruling 12). The id
 * is a pre-minted UUID — it IS the attempt identity the dispatch proof
 * consumes. Consumed (attemptRun set) is NOT closed: the authorization
 * stays active across its held session; closure is explicit and terminal.
 */
export type AttendedAuthorization = {
  id: string;
  taskRef: number;
  approver: string;
  runner: string;
  runnerGeneration: number;
  compositeDigest: string;
  termsJson: string;
  maxSessionTurns: number;
  /** A STOP THRESHOLD, not a ceiling: the agent halts when its total crosses it. */
  budgetMicrousd: number;
  /** Continuation: the finished parent attempt, also inside the signed terms. */
  parentRun: number | null;
  followup: string | null;
  createdAt: string;
  absoluteExpiry: string;
  lastBeatAt: string | null;
  attemptRun: number | null;
  consumedAt: string | null;
  closedAt: string | null;
  endReason: string | null;
};

/**
 * One stdin injection into a held session (ruling 15). Author is a verified
 * operator name for 'operator' turns ONLY — brief and repair turns are
 * machine-authored and say so with null. 'uncertain' is TERMINAL: written
 * (or accepted) but never proven settled; charged at its reservation and
 * NEVER reinjected.
 */
export type SessionTurn = {
  id: number;
  run: number;
  seq: number;
  sourceKind: "brief" | "answer" | "operator" | "repair";
  /** The decision id for 'answer' turns, the triggering decision for 'repair'. */
  sourceId: number | null;
  author: string | null;
  text: string;
  reservedMicrousd: number;
  accountedMicrousd: number | null;
  accountedAt: string | null;
  recordedAt: string;
  writtenAt: string | null;
  acceptedAt: string | null;
  settledAt: string | null;
  /** Marginal delta from the held session's durable cumulative baseline. */
  measuredMicrousd: number | null;
  outputTokens: number | null;
  state: "recorded" | "written" | "accepted" | "settled" | "uncertain" | "cancelled";
};

/**
 * Durable crash custody for one held session (ruling 15). The orphan
 * predicate is lease-based; 'fencing' is a helpable, leased state with
 * deadline takeover. cumulativeMicrousd is the settlement baseline the
 * provider's cumulative totals are diffed against.
 */
export type HeldSession = {
  run: number;
  authorizationId: string;
  runner: string;
  leaseId: string;
  upIncarnation: string;
  cookie: string;
  socketPath: string;
  supervisorPid: number | null;
  agentPgid: number | null;
  cumulativeMicrousd: number;
  cumulativeTokensOut: number;
  state: "open" | "fencing";
  fencer: string | null;
  fencingDeadline: string | null;
  startedAt: string;
  endedAt: string | null;
  endReason: string | null;
};

export type RecordTurnRefusal =
  | "no-held-session"
  | "fenced"
  | "turn-cap"
  | "turn-open"
  | "budget-exhausted"
  | "decision-open"
  | "repair-exhausted"
  | "answer-delivered";

/**
 * One operator steering note (arc 1, v22). Attached ≠ delivered: attachment
 * says which build the note rode toward; delivery settles only on the
 * stream's own receipt. Superseded = the task ended with it still pending.
 */
export type SteerNote = {
  /** v24 (ruling 11): "verified" = credentialed authorship; anything else is history, never brief-bound. */
  authorshipState: "verified" | "unverified-legacy";
  supersededReason: string | null;
  id: number;
  taskRef: number;
  author: string;
  note: string;
  createdAt: string;
  attachedRun: number | null;
  attachedAt: string | null;
  deliveredAt: string | null;
  supersededAt: string | null;
};

/** One phone enrollment for web push (arc 3, v23). A row per ACTIVATION —
 * retirement is history, never deletion. */
export type PushSubscription = {
  id: number;
  endpoint: string;
  p256dh: string;
  auth: string;
  approver: string;
  approverGeneration: number;
  uaWords: string;
  vapidFingerprint: string;
  startsAfterNotification: number;
  createdAt: string;
  lastOkAt: string | null;
  consecutiveFailures: number;
  retiredAt: string | null;
  retiredReason: string | null;
};

/** One (notification, subscription) push delivery. `accepted` = the push
 * SERVICE took it (RFC 8030) — nothing claims a phone displayed it. */
export type PushPair = {
  id: number;
  notification: number;
  subscription: number;
  state: "pending" | "claimed" | "accepted" | "rejected" | "undeliverable" | "retired";
  claimOwner: string | null;
  claimGeneration: number;
  attempts: number;
  nextAttemptAt: string | null;
  lastError: string | null;
  acceptedAt: string | null;
};

/** One option of a decision. `reversible` is a field so a scheduler can refuse to auto-apply. */
export type DecisionOption = {
  id: string;
  label: string;
  consequence: string;
  reversible: boolean;
};

/** The judgement call an agent refused to guess at (§7). Identity = its run. */
export type Decision = {
  id: number;
  run: number;
  urgency: "blocking";
  state: "open" | "expired" | "answered";
  recap: string;
  question: string;
  options: DecisionOption[];
  /** An option id. */
  recommendation: string;
  assignee: string | null;
  /** Attention metadata only — never a hold expiry. */
  deadline: string | null;
  createdAt: string;
  answeredAt: string | null;
  answeredBy: string | null;
  answeredVia: "cli" | "web" | "telegram" | "slack" | "discord" | "teams" | null;
  choice: string | null;
  note: string | null;
};

/** Evidence, by reference. `key` is relative to the evidence root, never absolute. */
export type Artifact = {
  id: number;
  run: number;
  kind:
    | "diff"
    | "status"
    | "park-payload"
    | "plan"
    | "terminal-diff"
    | "diff-stat"
    | "handoff"
    | "revision-brief"
    | "base-tree"
    | "report"
    | "proof"
    | "check-log"
    | "screenshot"
    | "structured-output"
    /** v51 (contract handoff, task 1): the planner's recorded SOURCE —
     * the filed request quoted into its brief — and the ingestion record
     * of what it proposed against those terms. */
    | "plan-contract"
    | "review-context";
  key: string;
  bytesOriginal: number;
  bytesStored: number;
  truncated: boolean;
  sha256: string;
  /** The command that produced it, and how that command exited. */
  capture: string;
  createdAt: string;
  redacted: boolean;
  /** Typed verdict of the capture itself (v14); null on rows from before. */
  captureStatus: "ok" | "failed" | null;
};

// ---- adaptive execution plans (v44) ---------------------------------------

export type PlanRevisionKind = "initial" | "operator-edit" | "builder-proposal";
export type PlanRevisionStatus = "applied" | "blocked" | "rejected";

/** One immutable entry in a task's plan-revision ledger. `artifact` carries
 * the complete replacement plan document; every other content field
 * (reason, evidenceLink, author, parentHash) never changes once written —
 * `status`/`resolvedAt`/`resolvedBy` are the one part an operator's later
 * accept/reject act may update. */
export type PlanRevision = {
  id: number;
  taskRef: number;
  revision: number;
  artifact: number;
  parentHash: string | null;
  reason: string;
  evidenceLink: string | null;
  author: string;
  originRun: number | null;
  kind: PlanRevisionKind;
  authorityKind: "plan-only" | "authority-change";
  authorityDigest: string;
  changedFields: string[];
  status: PlanRevisionStatus;
  createdAt: string;
  resolvedAt: string | null;
  resolvedBy: string | null;
};

/** One atomic milestone-progress checkpoint a running build recorded. */
export type RunCheckpoint = {
  id: number;
  run: number;
  taskRef: number;
  planRevision: number;
  snapshot: ProgressSnapshot;
  createdAt: string;
};

/** The bridge's digest cadence (v34). everyMs null = every fact pages as it lands. */
export type TelegramDigest = {
  everyMs: number | null;
  setBy: string | null;
  setAt: string | null;
  lastSentAt: string | null;
};

/** One Telegram chat allowed to answer as one approver. Revoked, never deleted. */
export type TelegramTeamChat = {
  id: number;
  botId: string;
  chatId: string;
  binding: number;
  kind: "group" | "private";
  conversation: string;
  boundBy: string;
  boundAt: string;
  cursor: number;
};

/** A Telegram button on a flow decision (v86): one action, for one visit of one card. */
export type TelegramFlowAction = { token: string; binding: number; card: number; entry: number; action: "approve" | "edit" | "send-back"; chatId: string; messageId: string | null; expiresAt: string; consumedAt: string | null };
/** A prompt the bot sent after Edit or Send back: a reply to it is the new draft, or the note. */
export type TelegramFlowPrompt = { chatId: string; messageId: string; binding: number; card: number; entry: number; mode: "edit" | "send-back" };
/** One option's button on a "Person chooses" message (flow-send.ts). */
export type TelegramFlowChoice = { token: string; binding: number; card: number; entry: number; choice: number; label: string; chatId: string; messageId: string | null; expiresAt: string; consumedAt: string | null };
/** What a "Send to me" or "Person chooses" visit sent its person (flow-send.ts). */
export type FlowSendRow = { card: number; entry: number; stage: string; person: string; contentJson: string; createdAt: string };

export type TelegramBinding = {
  id: number;
  botId: string;
  chatId: string;
  userId: string;
  approver: string;
  approverGeneration: number;
  pairedAt: string;
  pairedBy: string;
  revokedAt: string | null;
  revokedBy: string | null;
};

/** What one opaque callback token means. The token is all Telegram ever sees. */
export type TelegramAction = {
  token: string;
  binding: number;
  decision: number;
  optionId: string;
  phase: "choose" | "confirm" | "cancel";
  chatId: string;
  messageId: string | null;
  createdAt: string;
  expiresAt: string | null;
  consumedAt: string | null;
  /** Binds a confirm to the exact note it displayed; null = no note armed. */
  noteDigest: string | null;
};

/** One ordinary paired Telegram message on its way through the shared mate engine (v62). */
export type TelegramConversation = {
  id: number;
  binding: number;
  botId: string;
  chatId: string;
  userId: string;
  approver: string;
  approverGeneration: number;
  updateId: number;
  messageId: string;
  replyTo: string | null;
  /** The mate request receipt identity: 32 hex, derived from bot, binding and update. */
  request: string;
  text: string;
  /** Server-authored context for the turn — the exact task/result a reply bound to. */
  context: string | null;
  taskId: string | null;
  sourceRun: number | null;
  state: "queued" | "running" | "done" | "failed";
  claimOwner: string | null;
  claimExpiresAt: string | null;
  attempts: number;
  nextAttemptAt: string | null;
  session: number | null;
  turn: number | null;
  /** A short outcome word: answered, replayed, refused:<reason>, failed:<reason>, revoked, … */
  outcome: string | null;
  replyMessageId: string | null;
  createdAt: string;
  startedAt: string | null;
  finishedAt: string | null;
};

/** One outbound part of a conversation — a slice of the reply, one proposal card, or (v64) one verified result screenshot — durable before it is sent (v63). */
export type TelegramConversationPart = {
  conversation: number;
  ordinal: number;
  kind: "reply" | "card" | "image";
  /** The reply slice, the card, or an image part's short caption. */
  text: string;
  /** The operator's message the first reply part answers. */
  replyTo: string | null;
  /** The pending proposal a card carries; null once that proposal is gone. */
  proposal: number | null;
  /** The inline keyboard exactly as sent; its callback data are the card's opaque tokens, minted with the part. */
  keyboard: { text: string; callback_data: string }[][] | null;
  /** `dropped`: a card whose proposal was resolved elsewhere before it went out, or an image whose artifact could not be verified — moot or refused, never a lost message. */
  state: "pending" | "sent" | "dropped";
  /** Telegram's confirmed message id — the only thing that makes a part sent. */
  messageId: string | null;
  /** v64, image parts only: the exact task and run the image belongs to, the artifact row and the hash its record carried when planned. */
  taskId: string | null;
  run: number | null;
  artifact: number | null;
  sha256: string | null;
  attempts: number;
  /** Sends whose answer was lost: a later attempt may have duplicated the part. */
  uncertain: number;
  nextAttemptAt: string | null;
  lastError: string | null;
  createdAt: string;
  sentAt: string | null;
};

/** What one outbound part is planned from: a reply slice, a card with its minted keyboard, or an image by typed identity. */
export type TelegramConversationPartPlan =
  | { kind: "reply"; text: string; replyTo?: string | null; keyboard?: TelegramConversationPart["keyboard"] }
  | { kind: "card"; text: string; proposal: number; keyboard: TelegramConversationPart["keyboard"] }
  | { kind: "image"; text: string; taskId: string; run: number; artifact: number; sha256: string };

/** One verified screenshot a mate turn selected for an exact result (v64): trusted identities only, never bytes or paths. */
export type MateTurnEvidence = {
  turn: number;
  ordinal: number;
  taskId: string;
  taskRef: number;
  run: number;
  artifact: number;
  sha256: string;
  format: "png" | "jpeg";
  bytes: number;
  caption: string;
  createdAt: string;
};

/** What one opaque proposal-card token means (v62). */
export type TelegramProposalAction = {
  token: string;
  binding: number;
  proposal: number;
  phase: "confirm" | "dismiss" | "yes" | "cancel";
  chatId: string;
  messageId: string | null;
  createdAt: string;
  expiresAt: string | null;
  consumedAt: string | null;
};

/** A park that never became a decision. Stays in every brief until resolved. */
export type Incident = {
  id: number;
  run: number;
  kind:
    | "malformed-decision"
    | "attempts-exhausted"
    | "commit-failure"
    | "malformed-plan"
    | "plan-attempts-exhausted"
    | "malformed-report"
    | "malformed-proof";
  createdAt: string;
  resolvedAt: string | null;
  resolvedBy: string | null;
};

/** What a publication grant permits — two external writes, named separately. */
export type PublicationCapability = "push-branch" | "open-pr";

export type PublicationGrant = {
  id: number;
  repo: string;
  /** owner/name on GitHub — exact, never inferred from a remote at publish time. */
  githubRepo: string;
  remote: string;
  /** Only branches under this prefix may be pushed. */
  headPrefix: string;
  base: string;
  capabilities: PublicationCapability[];
  selector: "ours" | "all";
  draft: boolean;
  grantedBy: string;
  grantedAt: string;
  revokedBy: string | null;
  revokedAt: string | null;
  /** Merge authority (v21): explicit, default off — its own yes. */
  merge?: boolean;
  mergeMethod?: "squash" | "merge" | "rebase" | null;
  mergeDeleteBranch?: boolean;
  /** When a pull request is owed: every finished build ("build", the original grant), or only when a person
   * chooses "Complete and open a pull request" ("complete", the one-step project setup). */
  publishOn?: "build" | "complete";
  /** The project's optional "Merge when checks pass", off by default (complete-mode grants only). */
  mergeWhenGreen?: boolean;
};

/** One run's road to a PR, durable at every phase. */
export type Publication = {
  id: number;
  run: number;
  taskRef: number;
  githubRepo: string;
  remote: string;
  base: string;
  head: string;
  /** The exact commit completion accepted — what gets pushed, byte for byte. */
  headSha: string;
  bodyHash: string;
  draft: boolean;
  state: "intended" | "pushed" | "opened" | "failed";
  prNumber: number | null;
  prUrl: string | null;
  attempts: number;
  lastError: string | null;
  createdAt: string;
  updatedAt: string;
  /** GitHub's observed verdict — MERGED/CLOSED means done, whatever local state says. */
  remoteState: string | null;
  /** What CI was last SEEN doing (passing/failing/running/none) — never inferred. */
  lastCheckState: string | null;
  lastCheckAt: string | null;
};

/** Every mutation takes one. A repeat returns the first answer, unchanged. */
export type Mutation = {
  idempotencyKey?: string;
  actor?: string;
  /** When it happened. Supplied by callers that hold a clock; see `once`. */
  at?: Date;
};

export const DEFAULT_ACTOR = "operator";

/** A run admission that must not stand (atomic authority closure): thrown
 * inside the admitting transaction so every write rolls back; the generic
 * road lets it escape as the error it is, the dedicated roads catch it and
 * answer in words. Nothing half-admitted survives either way. */
export class RunAdmissionRefused extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RunAdmissionRefused";
  }
}

/** A present fallback-chain row carries this many entries after the base
 * (atomic authority closure) — the same bound `config set fallback`
 * enforces at the CLI, held again at the store's read and write so a row
 * outside it is a stated problem, never an empty chain. */
export const FALLBACK_ENTRIES_MIN = 1;
export const FALLBACK_ENTRIES_MAX = 3;

const SCHEMA = `
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schema_version (
  version INTEGER NOT NULL
);

-- Restart-safe position of bounded maintenance reads. These offsets confer
-- no execution, approval, delivery or evidence authority.
CREATE TABLE IF NOT EXISTS service_cursor (
  key TEXT PRIMARY KEY,
  value INTEGER NOT NULL CHECK (value >= 0),
  updated_at TEXT NOT NULL
);

-- The built-in task store.
CREATE TABLE IF NOT EXISTS task (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL,
  state      TEXT NOT NULL CHECK (state IN ('queued','running','done','failed','cancelled')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  priority   INTEGER NOT NULL DEFAULT 0
);

-- Dependency edges, owned natively because this backend is ours. Edges are
-- never emulated on top of a backend that lacks them; see §4.
-- The queue revision (v19): bumped by every EXPLICIT queue edit (drag,
-- assign, next, undo) and CAS-checked by the console's moves, so a second
-- tab's stale drag refuses whole. Scheduler claims deliberately do not
-- bump it — the revision detects competing operators, not dispatch.
CREATE TABLE IF NOT EXISTS queue_state (
  id       INTEGER PRIMARY KEY CHECK (id = 1),
  revision INTEGER NOT NULL DEFAULT 0
);
INSERT OR IGNORE INTO queue_state (id, revision) VALUES (1, 0);

CREATE TABLE IF NOT EXISTS task_edge (
  blocked TEXT NOT NULL REFERENCES task(id) ON DELETE CASCADE,
  blocker TEXT NOT NULL REFERENCES task(id) ON DELETE CASCADE,
  PRIMARY KEY (blocked, blocker),
  CHECK (blocked <> blocker)
);

-- The overlay starts here. Nothing below this line knows which backend the
-- work actually lives in.
-- The origin column is what the grant's default selector actually rests on.
-- It records whether Toolroll created this task or merely came across it,
-- and it is written here rather than asserted by whoever is asking to write:
-- a policy that says "only our tasks" while letting the caller declare which
-- those are is not a policy.
CREATE TABLE IF NOT EXISTS task_ref (
  id                      INTEGER PRIMARY KEY AUTOINCREMENT,
  backend                 TEXT NOT NULL,
  external_id             TEXT NOT NULL,
  -- Which repository the work belongs to, when that is known. Capabilities
  -- are repo-scoped, so a gap can only count the tasks it blocks if tasks
  -- say where they live. NULL is honest for a task nobody has placed yet —
  -- it dispatches anywhere, and no gap claims it.
  repo                    TEXT,
  -- The worker this task is reserved for (v19); NULL = any free worker.
  assigned_runner         TEXT,
  zones                   TEXT NOT NULL DEFAULT '[]',
  capability_requirements TEXT NOT NULL DEFAULT '[]',
  park_rate               REAL NOT NULL DEFAULT 0,
  origin                  TEXT NOT NULL DEFAULT 'theirs',
  -- Planning mode (v7): 'requested' dispatches a planner before any scope
  -- is approved; 'drafted' means a proposed scope + plan document await the
  -- operator. NULL is the ordinary task that never asked for a plan.
  plan                    TEXT CHECK (plan IN ('requested','drafted')),
  -- Planning failures count separately from build strikes: a planner that
  -- cannot finish must never spend the builder's three attempts.
  plan_strikes            INTEGER NOT NULL DEFAULT 0,
  -- The standing order this task is an instance of, when it is one (v8).
  -- Ordinary one-off work carries NULL; the board uses this to keep
  -- instances in their track row instead of the main lanes.
  routine_id              INTEGER REFERENCES routine(id),
  -- The pinned agent (v9): which provider/model this task's builds run on,
  -- stamped by the routine fire transaction (digest-authoritative) — a
  -- runtime flag never overrides a pin. NULL = resolve from config.
  agent_provider          TEXT,
  agent_model             TEXT,
  -- Per-task unattended permission override (v37). NULL inherits the
  -- installation default when a scope is next filed; approvals bind the
  -- resulting concrete profile, never this mutable preference.
  permission_mode         TEXT CHECK (permission_mode IN ('auto','bypassPermissions')),
  -- Per-task quality override (v41). NULL inherits the installation
  -- default when the next scope is filed; the scope stores the concrete
  -- signed choice.
  quality_mode            TEXT CHECK (quality_mode IN ('default','strict')),
  -- Per-task declared risk (v47, phase routing). NULL reads as routine
  -- when the next scope is filed; the scope stores the signed level.
  risk_level              TEXT CHECK (risk_level IN ('routine','elevated','high')),
  -- An approver's explicit per-phase route overrides (v47): a JSON list of
  -- {phase, provider, model, by, at}, at most one per phase. Read when the
  -- next scope is filed; the sealed route records what applied.
  route_overrides_json    TEXT,
  -- A revision task (M6.8): which task's reviewed run it revises, and the
  -- immutable brief artifact carrying the exact comment batch. Every
  -- revision requires its own approval; nothing is inherited.
  revision_of             TEXT,
  revision_brief_artifact INTEGER REFERENCES artifact(id),
  -- Immutable provenance (v12): which door filed this work — 'cli',
  -- 'console', 'intake', 'template:<name>', 'revision'. Stamped once at
  -- filing, never updated; NULL is history from before the column existed.
  filed_via               TEXT,
  -- The coordinator that filed this task (v31, MCP gateway): the
  -- AUTHORITATIVE linkage — written only by the branded coordinator door,
  -- joined by exact cid, never parsed out of filed_via (which stays
  -- display-only). NULL is every other filer.
  coordinator_cid         TEXT REFERENCES coordinator_credential(cid),
  -- The deliverable (v34, scout tasks): 'branch' is every task until now;
  -- 'report' dispatches a scout — a read-only session whose whole output
  -- is one report artifact. Stamped at filing, never rewritten.
  deliverable             TEXT NOT NULL DEFAULT 'branch' CHECK (deliverable IN ('branch','report')),
  UNIQUE (backend, external_id)
);

-- v31 (MCP gateway): the coordinator principal (DESIGN.md 9b). Minted by
-- an operator password ceremony; the token is hashed at rest and shown
-- once. cid is the IMMUTABLE identity — names are unique only among the
-- living, so revoke-and-remint never conflates generations in audit or
-- cap accounting.
CREATE TABLE IF NOT EXISTS coordinator_credential (
  cid             TEXT PRIMARY KEY,
  name            TEXT NOT NULL,
  credential_hash TEXT NOT NULL,
  repos           TEXT NOT NULL,
  per_hour        INTEGER NOT NULL,
  created_by      TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  revoked_at      TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS coordinator_live_name
  ON coordinator_credential (name) WHERE revoked_at IS NULL;

-- The coordinator audit (v31): filing, dismissal, and revocation rows,
-- inserted ATOMICALLY with their state change — never a separate write.
CREATE TABLE IF NOT EXISTS coordinator_event (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  cid        TEXT NOT NULL REFERENCES coordinator_credential(cid),
  kind       TEXT NOT NULL CHECK (kind IN ('filed','dismissed','revoked')),
  task_id    TEXT,
  detail     TEXT,
  created_at TEXT NOT NULL
);

-- MCP-specific idempotency (v31): keyed by immutable credential identity,
-- carrying the canonical request digest — same key + same digest replays
-- the original answer without a rate charge; a different digest refuses.
-- The global Store.replay is digest-blind and is NOT this.
CREATE TABLE IF NOT EXISTS mcp_idempotency (
  cid            TEXT NOT NULL REFERENCES coordinator_credential(cid),
  key            TEXT NOT NULL,
  request_digest TEXT NOT NULL,
  task_id        TEXT NOT NULL,
  created_at     TEXT NOT NULL,
  PRIMARY KEY (cid, key)
);

-- Phase configuration (v9): which provider/model each phase runs on.
-- scope 'installation' is the plane-wide answer; a canonical repo path is
-- that project's override. Rows are COMPLETE pairs (provider required,
-- model optional = harness default), written only through authenticated,
-- audited verbs — spend routing is authority, not preference.
CREATE TABLE IF NOT EXISTS phase_config (
  scope      TEXT NOT NULL,
  phase      TEXT NOT NULL CHECK (phase IN ('plan','build','repair','review')),
  provider   TEXT NOT NULL CHECK (provider IN ('claude','codex','openrouter','gemini')),
  model      TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  PRIMARY KEY (scope, phase)
);

-- The fallback chain configuration (v30): the ORDERED fallback entries
-- AFTER the base (which the ordinary phase resolution supplies). Stored as
-- JSON per (scope, phase) — each entry names a provider, model, auth mode,
-- and optional repair model. Resolution folds base + these into the
-- ChainEntry[] the approval seals; nothing dispatches on it until an
-- approval binds it. A new table: it arrives by IF NOT EXISTS on fresh AND
-- upgraded databases alike.
CREATE TABLE IF NOT EXISTS fallback_config (
  scope       TEXT NOT NULL,
  phase       TEXT NOT NULL CHECK (phase IN ('build')),
  entries_json TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  updated_by  TEXT NOT NULL,
  PRIMARY KEY (scope, phase)
);

-- The STRONG candidate tier (v47, phase routing): the operator's named
-- strongest agent per phase, project or installation scoped, exactly like
-- phase_config rows (which remain the routine tier). Strength is never
-- inferred from a model's name — a phase without a strong row keeps its
-- configured default and the route says so.
CREATE TABLE IF NOT EXISTS phase_tier_config (
  scope      TEXT NOT NULL,
  phase      TEXT NOT NULL CHECK (phase IN ('plan','build','repair','review')),
  tier       TEXT NOT NULL CHECK (tier IN ('light','strong')),
  provider   TEXT NOT NULL CHECK (provider IN ('claude','codex','openrouter','gemini')),
  model      TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  PRIMARY KEY (scope, phase, tier)
);

-- Runner-scoped provider readiness (v47): what one authenticated runner
-- observed about one provider without spending — installed, logged in, key
-- present — with the probe named and the time kept. 'unknown' is a real
-- answer (claude has no non-spending login check) and is never upgraded.
-- The route projection reads these beside the sealed route; the dispatch
-- gate halts a leg the dispatching runner reports unavailable, and nothing
-- substitutes for it.
CREATE TABLE IF NOT EXISTS provider_readiness (
  runner      TEXT NOT NULL REFERENCES runner(name) ON DELETE CASCADE,
  provider    TEXT NOT NULL CHECK (provider IN ('claude','codex','openrouter','gemini')),
  state       TEXT NOT NULL CHECK (state IN ('ready','unavailable','unknown')),
  reason      TEXT NOT NULL,
  probe       TEXT NOT NULL,
  observed_at TEXT NOT NULL,
  PRIMARY KEY (runner, provider)
);

-- Route provenance per run (v47): which sealed route a run spent under and
-- the exact leg it used — the actual provider and model, and whether that
-- leg was recommended, overridden, pinned, an approved fallback entry, or
-- a legacy resolution. One row per run, written IN the admission
-- transaction that opens the run (startRun) so provenance can never lag
-- authority, and IMMUTABLE set-once: an identical restamp is idempotent, a
-- conflicting one refuses execution.
CREATE TABLE IF NOT EXISTS run_route (
  run          INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  route_digest TEXT NOT NULL,
  phase        TEXT NOT NULL CHECK (phase IN ('plan','build','repair','review')),
  provider     TEXT NOT NULL,
  model        TEXT,
  chosen       TEXT NOT NULL CHECK (chosen IN ('recommended','override','pinned','legacy','fallback')),
  stamped_at   TEXT NOT NULL
);

-- A standing order (v8): a pre-approved template whose instances build
-- without asking, because the operator agreed to the TEMPLATE — schedule,
-- budget, and "each firing builds unattended" restated at the yes. The
-- digest covers every term that constrains the order, and approval binds to
-- it exactly as a scope approval does: editing any term strands the yes.
CREATE TABLE IF NOT EXISTS routine (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  name             TEXT NOT NULL UNIQUE,
  repo             TEXT NOT NULL,
  goal             TEXT NOT NULL,
  out_of_scope     TEXT,
  touches          TEXT NOT NULL DEFAULT '[]',
  requirements     TEXT NOT NULL DEFAULT '[]',
  -- 'every:<minutes>', 'daily:<HH:MM>[@Zone]', or 'weekly:<0-6>:<HH:MM>[@Zone]' (UTC by default). Parsed, never guessed at.
  schedule         TEXT NOT NULL,
  single_flight    INTEGER NOT NULL DEFAULT 1,
  -- Rolling 7-day ceiling in dollars. NULL is honestly "no ceiling";
  -- enforcement FAILS CLOSED on unmeasured paid runs (finding 5).
  cost_ceiling_usd REAL,
  -- Per-INSTANCE dollar cap (v16): copied into each instance's scope as
  -- its digest-bound budget term, enforced by the same native-cap
  -- plumbing as any scope budget. NULL = only the global backstop.
  budget_per_run_microusd INTEGER,
  paused           INTEGER NOT NULL DEFAULT 0,
  digest           TEXT NOT NULL,
  approved_at      TEXT,
  approved_by      TEXT,
  approved_digest  TEXT,
  -- v24: the routine's execution profile; firings stamp instances FROM
  -- the APPROVED snapshot, never from fresh resolution.
  profile_json          TEXT,
  approved_profile_json TEXT,
  digest_version        INTEGER NOT NULL DEFAULT 1,
  profile_provenance    TEXT,
  -- v48: the routine's four-role agent route, and the snapshot approval
  -- sealed. Every firing copies the APPROVED route onto its instance, so a
  -- configuration change after the yes can never re-route a firing.
  route_json            TEXT,
  approved_route_json   TEXT,
  -- The next scheduled occurrence. NULL until approved; advanced by the
  -- fire transaction and nothing else, aligned to cadence (finding 10).
  next_fire_at     TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  -- Immutable provenance (v12), same contract as task_ref.filed_via.
  filed_via        TEXT,
  -- v39: the signed rubric every instance's scope copies forward. A
  -- routine is validated mandatory-non-empty at creation/edit time
  -- (validateRoutineTerms) -- by the time a firing reads this column it
  -- is guaranteed present, so fireRoutine never re-checks it.
  acceptance_json  TEXT
);

-- Append-only installation facts (v12): set-once markers about THIS
-- database file — 'demo' stamps a sandbox no worker may spend against;
-- 'first-success-at' retires the first-run checklist permanently. Writes
-- go through recordInstallationFact (INSERT OR IGNORE); nothing updates
-- or deletes a fact, so a marker can never be quietly unset.
CREATE TABLE IF NOT EXISTS installation_fact (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  created_at TEXT NOT NULL
);


-- Tournament builds (v14). Internal names stay technical; every screen
-- says "tournament", "agents", and "worker processes" in plain words.
--
-- The approved terms are a durable row of their own (round-3 finding 31):
-- immutable once written, one ACTIVE row per task, approved by the same
-- ceremony that approves the scope — the approval binds a joint digest
-- over both. Money is integer micro-dollars; the overrun reserve is the
-- worst one API call the pinned envelope permits, held apart from the
-- spendable budget and never granted to a later invocation.
CREATE TABLE IF NOT EXISTS tournament_terms (
  id                        INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref                  INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  generation                INTEGER NOT NULL,
  active                    INTEGER NOT NULL DEFAULT 1,
  -- v27: 'race' = dollar-capped tournament (money contract required);
  -- 'comparison' = labeled cross-runtime comparison (no dollar terms
  -- exist; each lane's sealed clock is its bound). The money CHECK is
  -- kind-aware: races keep their positive budgets, comparisons pin 0.
  kind                      TEXT NOT NULL DEFAULT 'race' CHECK (kind IN ('race','comparison')),
  race_digest               TEXT NOT NULL,
  -- The ordered agents, JSON: [{provider, model, repairModel}] — exact
  -- model ids, resolved at filing, priced at price_version.
  agents                    TEXT NOT NULL,
  n                         INTEGER NOT NULL CHECK (n BETWEEN 2 AND 4),
  per_agent_budget_microusd INTEGER NOT NULL,
  overrun_reserve_microusd  INTEGER NOT NULL,
  total_budget_microusd     INTEGER NOT NULL,
  price_version             INTEGER NOT NULL,
  retries                   INTEGER NOT NULL CHECK (retries = 0),
  -- 'none', or the JSON of the publication grant constraints in force.
  publication_policy        TEXT NOT NULL,
  created_at                TEXT NOT NULL,
  approved_at               TEXT,
  approved_by               TEXT,
  approved_digest           TEXT,
  CHECK ((kind = 'race' AND per_agent_budget_microusd > 0 AND overrun_reserve_microusd > 0 AND total_budget_microusd > 0)
      OR (kind = 'comparison' AND per_agent_budget_microusd = 0 AND overrun_reserve_microusd = 0 AND total_budget_microusd = 0))
);

-- One active terms row per task (the whole table is new, so this partial
-- index may live here — the v11c trap only bites indexes over columns
-- that older files gain later by addColumn).
CREATE UNIQUE INDEX IF NOT EXISTS tournament_terms_one_active
  ON tournament_terms (task_ref) WHERE active = 1;

-- A running tournament. States are stable machine tokens (envelopes need
-- them); screens translate to plain words at render. The current lease
-- identity lives HERE so aggregation, reaping, and crash recovery all
-- fence on the same facts (finding 17/27).
CREATE TABLE IF NOT EXISTS contest (
  id                 INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref           INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  terms              INTEGER NOT NULL REFERENCES tournament_terms(id),
  generation         INTEGER NOT NULL DEFAULT 1,
  state              TEXT NOT NULL CHECK (state IN
    ('dispatching','racing','pick-wait','decision-wait','picked','abandoned','interrupted','exhausted')),
  scope_digest       TEXT NOT NULL,
  race_digest        TEXT NOT NULL,
  base_sha           TEXT,
  setup_digest       TEXT,
  current_lease_id   TEXT,
  runner             TEXT,
  incarnation        TEXT,
  created_at         TEXT NOT NULL,
  picked_at          TEXT,
  picked_by          TEXT,
  winner_contestant  INTEGER,
  overdue_paged      INTEGER NOT NULL DEFAULT 0,
  -- v24: 1 = legacy race digest (provider/model/repair only) — admission
  -- keeps byte-comparing the stored fingerprint; 2 = full-profile terms.
  race_semantics     INTEGER NOT NULL DEFAULT 1,
  -- v27: denormalized from the terms at admission, so screens, holds,
  -- and recovery speak the right words without a join.
  kind               TEXT NOT NULL DEFAULT 'race'
);

CREATE INDEX IF NOT EXISTS contest_by_task ON contest (task_ref, id DESC);

-- One racing agent. Money is three columns kept deliberately apart
-- (finding 25): measured = what the provider reported, monotonic;
-- accounted = what the ledger charges (the full reservation when the
-- real figure is unknowable); unknown_spend = the honest flag that the
-- two differ. Custody (finding 29) records who owns the checkout while
-- a parked agent waits on an answer.
CREATE TABLE IF NOT EXISTS contestant (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  contest             INTEGER NOT NULL REFERENCES contest(id) ON DELETE CASCADE,
  ordinal             INTEGER NOT NULL,
  provider            TEXT NOT NULL,
  model               TEXT NOT NULL,
  repair_model        TEXT NOT NULL,
  -- v24: the contestant's full execution-profile snapshot (canonical JSON).
  profile_json        TEXT,
  branch              TEXT NOT NULL,
  worktree            TEXT,
  generation          INTEGER NOT NULL DEFAULT 1,
  state               TEXT NOT NULL DEFAULT 'pending' CHECK (state IN
    ('pending','ready','building','parked','built','failed','stopped')),
  active_run          INTEGER REFERENCES run(id),
  budget_microusd     INTEGER NOT NULL,
  reserve_microusd    INTEGER NOT NULL,
  measured_microusd   INTEGER NOT NULL DEFAULT 0,
  accounted_microusd  INTEGER NOT NULL DEFAULT 0,
  unknown_spend       INTEGER NOT NULL DEFAULT 0,
  cleanup             TEXT CHECK (cleanup IN ('pending','done','attention')),
  custody             TEXT,
  UNIQUE (contest, ordinal)
);

-- One row per worker process, ordinary builds and tournaments alike
-- (finding 26): reserved before anything spawns, running once the
-- process exists (with its group id, so recovery can check the OS
-- before calling the capacity back), released on observed exit. The
-- capacity a runner enforces in 'processes' mode counts these rows.
CREATE TABLE IF NOT EXISTS execution_slot (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  runner        TEXT NOT NULL,
  state         TEXT NOT NULL DEFAULT 'reserved' CHECK (state IN ('reserved','running','released')),
  run           INTEGER REFERENCES run(id),
  contestant    INTEGER REFERENCES contestant(id),
  incarnation   TEXT,
  process_group INTEGER,
  reserved_at   TEXT NOT NULL,
  running_at    TEXT,
  released_at   TEXT
);

CREATE INDEX IF NOT EXISTS execution_slot_live ON execution_slot (runner, state);

-- Durable ceremony nonces (finding 21/30): minted by a POST (never a
-- GET), stored hashed, consumed CONDITIONALLY inside the same
-- transaction as the act they authorize — which the in-memory map could
-- never promise. Scope-approval nonces stay in memory this release, by
-- ruling.
CREATE TABLE IF NOT EXISTS ceremony_nonce (
  hash        TEXT PRIMARY KEY,
  approver    TEXT NOT NULL,
  subject     TEXT NOT NULL,
  subject_id  INTEGER NOT NULL,
  digest      TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  consumed_at TEXT
);

CREATE INDEX IF NOT EXISTS ceremony_nonce_expiry ON ceremony_nonce (expires_at);

-- Spend defaults (v15, operator request): global dollar thresholds, set by
-- the authenticated config verb. Defaults PREFILL filings and act as an
-- installation-wide backstop; the digest-bound scope term stays the
-- per-task authority — a default never silently edits an approval.
CREATE TABLE IF NOT EXISTS spend_defaults (
  id                       INTEGER PRIMARY KEY CHECK (id = 1),
  build_per_run_microusd   INTEGER,
  race_per_agent_microusd  INTEGER,
  race_total_microusd      INTEGER,
  -- How many agents compete by default (v16, operator request). Applies
  -- only where a filing names ONE agent and no explicit count — an
  -- explicit list or count always wins, and the race digest binds the
  -- actual lineup either way.
  race_agents              INTEGER CHECK (race_agents BETWEEN 2 AND 4),
  updated_at               TEXT NOT NULL,
  updated_by               TEXT NOT NULL
);

-- Unattended permission default (v37). It is a filing default only: changing
-- it never rewrites an existing scope or approval. Each approved scope binds
-- the concrete provider argv produced from this choice.
CREATE TABLE IF NOT EXISTS permission_default (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  mode       TEXT NOT NULL CHECK (mode IN ('auto','bypassPermissions')),
  updated_at TEXT,
  updated_by TEXT
);
INSERT OR IGNORE INTO permission_default (id, mode) VALUES (1, 'auto');

-- Evidence-quality default (v41). Separate from permissions and operating
-- modes: it changes how much validation a task asks for, never what an agent
-- is allowed to do. Existing scopes remain default and keep their digest.
CREATE TABLE IF NOT EXISTS quality_default (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  mode       TEXT NOT NULL CHECK (mode IN ('default','strict')),
  updated_at TEXT,
  updated_by TEXT
);
INSERT OR IGNORE INTO quality_default (id, mode) VALUES (1, 'default');

-- Fleet chat (v13, membership adapters in v35). Chat providers remain a
-- separate type from build providers: direct APIs use pinned dollar prices;
-- subscription adapters use the installed harness's cached login and zero
-- dollar ledger rows. One installation-scoped row; written only by the
-- authenticated config verb.
CREATE TABLE IF NOT EXISTS chat_config (
  id                      INTEGER PRIMARY KEY CHECK (id = 1),
  provider                TEXT NOT NULL CHECK (provider IN ('anthropic-api','openrouter-api','claude-subscription','codex-subscription')),
  model                   TEXT NOT NULL,
  daily_turns             INTEGER NOT NULL DEFAULT 50,
  -- The rolling 7-day spend ceiling, integer micro-dollars (change 4):
  -- reservations count against it transactionally. Subscription-backed
  -- chat stores zero: there is no truthful dollar meter on plan usage.
  weekly_ceiling_microusd INTEGER NOT NULL,
  -- The PINNED price (v13b): snapshotted from the provider's own catalog
  -- (or the compiled table) at the authenticated save, integer
  -- micro-dollars per token. Reservations and settlement use THESE, so an
  -- upstream price change never silently moves the ledger math —
  -- re-saving re-pins. NULL only on rows written before the columns
  -- existed; readers fall back to the compiled table then.
  price_in_microusd       INTEGER,
  price_out_microusd      INTEGER,
  updated_at              TEXT NOT NULL,
  updated_by              TEXT NOT NULL
);

-- One chat turn = one possible API request. METADATA ONLY — no prompt, no
-- reply, no free text (v2 finding 12); failure_reason is a CLOSED enum.
-- Spend is accounted in integer micro-dollars: reserved worst-case at
-- insert (input estimate + max_tokens at the pinned price), settled from
-- the provider's usage block. A turn that MAY have started but whose cost
-- is unknown latches unknown_spend=1 and blocks its credential until the
-- acknowledgement ceremony records who accepted the worst case (change 5/6).
CREATE TABLE IF NOT EXISTS chat_turn (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  approver          TEXT NOT NULL,
  -- Domain-separated sha256 over provider+key, full hex — a stable,
  -- non-secret accounting identity (128+ bits per change 6).
  credential_key    TEXT NOT NULL,
  provider          TEXT NOT NULL CHECK (provider IN ('anthropic-api','openrouter-api','claude-subscription','codex-subscription')),
  model             TEXT NOT NULL,
  state             TEXT NOT NULL CHECK (state IN ('queued','running','answered','failed')),
  -- Terminal transitions are generation-checked CAS: a late response
  -- cannot resurrect a swept row (change 5).
  generation        INTEGER NOT NULL DEFAULT 1,
  created_at        TEXT NOT NULL,
  started_at        TEXT,
  deadline_at       TEXT,
  finished_at       TEXT,
  tokens_in         INTEGER,
  tokens_out        INTEGER,
  reserved_microusd INTEGER NOT NULL,
  settled_microusd  INTEGER,
  failure_reason    TEXT CHECK (failure_reason IN
    ('provider-error','timeout','over-budget','malformed-reply','secret-refused','crashed','over-cap','unknown-spend')),
  unknown_spend     INTEGER NOT NULL DEFAULT 0,
  acknowledged_at   TEXT,
  acknowledged_by   TEXT,
  reply_bytes       INTEGER,
  candidate_count   INTEGER,
  kind              TEXT NOT NULL DEFAULT 'chat',
  mate_turn         INTEGER
);

CREATE INDEX IF NOT EXISTS chat_turn_credential ON chat_turn (credential_key, created_at);
CREATE INDEX IF NOT EXISTS chat_turn_approver ON chat_turn (approver, created_at);

-- The mate (v32, persistent sessions in v36): one conversation per approver
-- that manages the fleet by proposal. A session is delegated chat spend,
-- signed once and live until explicitly ended (ruling 10);
-- a thread is the conversation, ceiling-bound (ruling 9); messages hold
-- operator and assistant text only until explicit closure (ruling 11); a proposal is
-- inert until its turn finalizes and executes only through a confirm
-- transaction (ruling 7); a turn is the accounting row for one operator
-- message and its several provider requests, each of which is a chat_turn
-- step (ruling 5).
CREATE TABLE IF NOT EXISTS mate_session (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  approver            TEXT NOT NULL,
  approver_generation INTEGER NOT NULL,
  credential_key      TEXT NOT NULL,
  ceiling_microusd    INTEGER NOT NULL,
  spent_microusd      INTEGER NOT NULL DEFAULT 0,
  ceiling_digest      TEXT NOT NULL,
  terms_digest        TEXT NOT NULL,
  minted_at           TEXT NOT NULL,
  ended_at            TEXT,
  ended_by            TEXT
);
CREATE INDEX IF NOT EXISTS mate_session_live ON mate_session (approver, ended_at);

CREATE TABLE IF NOT EXISTS mate_thread (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  approver       TEXT NOT NULL,
  ceiling_digest TEXT NOT NULL,
  opened_at      TEXT NOT NULL,
  last_turn_at   TEXT,
  closed_at      TEXT,
  scope_kind     TEXT NOT NULL DEFAULT 'lead' CHECK (scope_kind IN ('lead','project','task')),
  scope_key      TEXT
);
CREATE INDEX IF NOT EXISTS mate_thread_live ON mate_thread (approver, closed_at);

CREATE TABLE IF NOT EXISTS mate_message (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  thread     INTEGER NOT NULL REFERENCES mate_thread(id) ON DELETE CASCADE,
  turn       INTEGER,
  role       TEXT NOT NULL CHECK (role IN ('operator','assistant')),
  text       TEXT NOT NULL,
  activity   TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS mate_message_thread ON mate_message (thread, id);

-- v78: the task a paired chat chose to talk about (/tasks, /task <name>),
-- per surface and binding; cleared by /lead. A choice, not an authority:
-- every turn and tool still re-proves the task against the ceiling.
CREATE TABLE IF NOT EXISTS chat_focus (
  surface    TEXT NOT NULL,
  binding    INTEGER NOT NULL,
  task       TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (surface, binding)
);

-- v81: flows. A flow is a canvas of zones (the definition JSON: each zone's
-- step and where it leads); a card is one piece of work moving through it,
-- pointing at the task its current zone filed; flow_event is its history.
CREATE TABLE IF NOT EXISTS flow (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  repo            TEXT NOT NULL,
  name            TEXT NOT NULL,
  definition_json TEXT NOT NULL,
  revision        INTEGER NOT NULL DEFAULT 1,
  state           TEXT NOT NULL CHECK (state IN ('active','archived')),
  created_by      TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  updated_by      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  owner           TEXT
);
CREATE TABLE IF NOT EXISTS flow_card (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  flow         INTEGER NOT NULL REFERENCES flow(id),
  title        TEXT NOT NULL,
  description  TEXT,
  stage        TEXT NOT NULL,
  entry        INTEGER NOT NULL DEFAULT 1,
  state        TEXT NOT NULL CHECK (state IN ('active','done','cancelled')),
  task         TEXT,
  primary_task TEXT,
  note         TEXT,
  waiting      TEXT,
  outputs_json TEXT NOT NULL DEFAULT '{}',
  created_by   TEXT NOT NULL,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  source_json  TEXT,
  owner        TEXT
);
CREATE INDEX IF NOT EXISTS flow_card_live ON flow_card (flow, state);
CREATE TABLE IF NOT EXISTS flow_event (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  card       INTEGER NOT NULL REFERENCES flow_card(id),
  from_stage TEXT,
  to_stage   TEXT NOT NULL,
  outcome    TEXT NOT NULL CHECK (outcome IN ('created','ok','fail','moved','approved','sent-back','cancelled')),
  actor      TEXT NOT NULL,
  note       TEXT,
  at         TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS flow_event_card ON flow_event (card, id);

-- v82: flow triggers. What starts cards in a flow without someone adding
-- them: a button with questions, a schedule, GitHub or Linear (checked by
-- the worker, or pushed to a secret webhook address), or another flow's
-- cards reaching a zone. config_json is the trigger's terms; secrets (a
-- Linear key, a webhook's signing secret) live in 0600 files, and only a
-- hash of a webhook's address is kept here. flow_trigger_event is every
-- outside thing a trigger has seen, so one issue never makes two cards.
CREATE TABLE IF NOT EXISTS flow_trigger (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  flow         INTEGER NOT NULL REFERENCES flow(id),
  kind         TEXT NOT NULL CHECK (kind IN ('button','schedule','github','linear','flow','webhook','email','chat')),
  config_json  TEXT NOT NULL,
  state        TEXT NOT NULL CHECK (state IN ('active','paused','removed')),
  hook_hash    TEXT UNIQUE,
  cursor       TEXT,
  next_at      TEXT,
  last_at      TEXT,
  last_outcome TEXT,
  failures     INTEGER NOT NULL DEFAULT 0,
  created_by   TEXT NOT NULL,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS flow_trigger_live ON flow_trigger (flow, state);

-- v83: people on flow cards. A card's owner is on flow_card; watchers
-- follow a card; flow_comment is what people said on it (kind 'comment',
-- with the accounts it @mentioned) and who became its owner (kind 'owner',
-- body the new owner or empty). Card history reads both.
CREATE TABLE IF NOT EXISTS flow_card_watcher (
  card     INTEGER NOT NULL REFERENCES flow_card(id),
  name     TEXT NOT NULL,
  added_at TEXT NOT NULL,
  PRIMARY KEY (card, name)
);
CREATE TABLE IF NOT EXISTS flow_comment (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  card          INTEGER NOT NULL REFERENCES flow_card(id),
  kind          TEXT NOT NULL CHECK (kind IN ('comment','owner')),
  author        TEXT NOT NULL,
  body          TEXT NOT NULL,
  mentions_json TEXT NOT NULL DEFAULT '[]',
  at            TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS flow_comment_card ON flow_comment (card, id);

-- v84: steps that run outside a model. flow_script is a project's library
-- of reusable scripts (each save is a new version; who saved it and when is
-- kept, and the digest names the exact body that ran). A "Run a script"
-- zone names one. flow_step_run is one visit of a card to a script
-- or update zone: the claim that keeps two workers from running it twice,
-- its attempts, and what came of it — the log, exit code and time taken,
-- which the flow's insights read. v85 adds sort zones: kind 'sort', and
-- decision_json keeps what Jev answered (its pick, how sure, the notes).
CREATE TABLE IF NOT EXISTS flow_script (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  repo            TEXT NOT NULL,
  name            TEXT NOT NULL,
  about           TEXT NOT NULL,
  body            TEXT NOT NULL,
  timeout_minutes INTEGER NOT NULL,
  version         INTEGER NOT NULL,
  digest          TEXT NOT NULL,
  saved_by        TEXT NOT NULL,
  saved_at        TEXT NOT NULL,
  state           TEXT NOT NULL CHECK (state IN ('active','removed')),
  language        TEXT NOT NULL DEFAULT 'shell',
  file            TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS flow_script_live ON flow_script (repo, name) WHERE state = 'active';
CREATE TABLE IF NOT EXISTS flow_step_run (
  card           INTEGER NOT NULL REFERENCES flow_card(id),
  entry          INTEGER NOT NULL,
  stage          TEXT NOT NULL,
  kind           TEXT NOT NULL CHECK (kind IN ('check','update','sort','draft','request','email','tool','teammate')),
  script         TEXT,
  script_version INTEGER,
  state          TEXT NOT NULL CHECK (state IN ('running','passed','failed','waiting')),
  attempts       INTEGER NOT NULL DEFAULT 0,
  next_at        TEXT,
  started_at     TEXT NOT NULL,
  finished_at    TEXT,
  duration_ms    INTEGER,
  exit_code      INTEGER,
  result         TEXT,
  log            TEXT,
  decision_json  TEXT,
  PRIMARY KEY (card, entry)
);
CREATE INDEX IF NOT EXISTS flow_step_run_recent ON flow_step_run (started_at);
CREATE TABLE IF NOT EXISTS flow_trigger_event (
  trigger    INTEGER NOT NULL REFERENCES flow_trigger(id),
  key        TEXT NOT NULL,
  card       INTEGER REFERENCES flow_card(id),
  note       TEXT,
  at         TEXT NOT NULL,
  PRIMARY KEY (trigger, key)
);
-- v91: a card's email conversation. Each email a Send email step sent (its
-- Message-ID and whom it went to) and each reply that came back, so a reply
-- finds its card (and only from someone the card wrote to) and a follow-up
-- stays in the thread.
CREATE TABLE IF NOT EXISTS flow_mail (
  message_id TEXT PRIMARY KEY,
  card       INTEGER NOT NULL REFERENCES flow_card(id),
  direction  TEXT NOT NULL CHECK (direction IN ('sent','received')),
  address    TEXT NOT NULL,
  at         TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS flow_mail_card ON flow_mail (card, at);
-- v92: AI teammates. One per project and name; its soul file (who it is,
-- how it writes, what it decides on its own, what it asks about, what it
-- never does) is versioned like scripts. Its manager hears its questions
-- and its daily summary.
CREATE TABLE IF NOT EXISTS teammate (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  repo         TEXT NOT NULL,
  handle       TEXT NOT NULL,
  state        TEXT NOT NULL CHECK (state IN ('active','paused','removed')),
  version      INTEGER NOT NULL,
  soul         TEXT NOT NULL,
  model        TEXT,
  daily_turns  INTEGER NOT NULL DEFAULT 200,
  manager      TEXT NOT NULL,
  created_by   TEXT NOT NULL,
  created_at   TEXT NOT NULL,
  updated_by   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  summary_at   TEXT,
  desk_flow    INTEGER REFERENCES flow(id),
  weekly_at    TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS teammate_live ON teammate (repo, handle) WHERE state <> 'removed';
CREATE TABLE IF NOT EXISTS teammate_version (
  teammate   INTEGER NOT NULL REFERENCES teammate(id),
  version    INTEGER NOT NULL,
  soul       TEXT NOT NULL,
  saved_by   TEXT NOT NULL,
  saved_at   TEXT NOT NULL,
  PRIMARY KEY (teammate, version)
);
-- What a teammate did and why, what it asked, and what its people told it.
CREATE TABLE IF NOT EXISTS teammate_event (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  teammate    INTEGER NOT NULL REFERENCES teammate(id),
  card        INTEGER REFERENCES flow_card(id),
  entry       INTEGER,
  kind        TEXT NOT NULL CHECK (kind IN ('decided','handled','handed','asked','answered','note','paused','resumed','summary','failed')),
  said        TEXT NOT NULL,
  detail_json TEXT,
  by          TEXT,
  at          TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS teammate_event_recent ON teammate_event (teammate, id);
-- A question a teammate put to a person about one visit of a card: open until answered.
CREATE TABLE IF NOT EXISTS teammate_question (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  teammate      INTEGER NOT NULL REFERENCES teammate(id),
  card          INTEGER NOT NULL REFERENCES flow_card(id),
  entry         INTEGER NOT NULL,
  question      TEXT NOT NULL,
  options_json  TEXT NOT NULL,
  asked_of      TEXT NOT NULL,
  state         TEXT NOT NULL CHECK (state IN ('open','answered','dropped')),
  choice        TEXT,
  answer        TEXT,
  answered_by   TEXT,
  answered_via  TEXT,
  answered_at   TEXT,
  created_at    TEXT NOT NULL,
  tool_call     INTEGER REFERENCES teammate_call(id),
  suggestion    INTEGER REFERENCES teammate_suggestion(id)
);
-- v94: the project tools a teammate may use, and its rule for each of their
-- actions: do it, ask first (a person approves the exact call), or never.
-- actions_json is what the tool offered when it was last listed.
CREATE TABLE IF NOT EXISTS teammate_tool (
  teammate     INTEGER NOT NULL REFERENCES teammate(id),
  tool         TEXT NOT NULL,
  actions_json TEXT NOT NULL,
  rules_json   TEXT NOT NULL,
  listed_at    TEXT,
  updated_by   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  PRIMARY KEY (teammate, tool)
);
-- v94: every tool call a teammate made or asked to make on a card: the
-- receipt. An ask-first call waits (asked) until its person approves or
-- denies it; what the tool answered is kept, secrets scrubbed.
CREATE TABLE IF NOT EXISTS teammate_call (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  teammate    INTEGER NOT NULL REFERENCES teammate(id),
  card        INTEGER NOT NULL REFERENCES flow_card(id),
  entry       INTEGER NOT NULL,
  tool        TEXT NOT NULL,
  action      TEXT NOT NULL,
  input_json  TEXT NOT NULL,
  rule        TEXT NOT NULL CHECK (rule IN ('free','ask','never')),
  why         TEXT NOT NULL,
  state       TEXT NOT NULL CHECK (state IN ('asked','approved','denied','refused','running','done','failed')),
  result      TEXT,
  decided_by  TEXT,
  decided_at  TEXT,
  created_at  TEXT NOT NULL,
  done_at     TEXT,
  undo_of     INTEGER REFERENCES teammate_call(id),
  undone_by   TEXT,
  undone_at   TEXT
);
CREATE INDEX IF NOT EXISTS teammate_call_card ON teammate_call (card, entry, id);
-- v97: every model turn a teammate took: what it cost (the CLI's own
-- estimate) and how long it took — its weekly report.
CREATE TABLE IF NOT EXISTS teammate_turn (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  teammate    INTEGER NOT NULL REFERENCES teammate(id),
  card        INTEGER REFERENCES flow_card(id),
  model       TEXT NOT NULL,
  ok          INTEGER NOT NULL,
  ms          INTEGER NOT NULL,
  cost_usd    REAL,
  tokens_in   INTEGER,
  tokens_out  INTEGER,
  at          TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS teammate_turn_recent ON teammate_turn (teammate, at);
CREATE INDEX IF NOT EXISTS teammate_call_recent ON teammate_call (teammate, id);
-- v95: what a teammate remembers: facts it kept from its own turns, and
-- what its people told it (replacing v92's notes). Searchable, editable, and
-- forgotten on request; each turn reads what its people said and what fits
-- the card.
CREATE TABLE IF NOT EXISTS teammate_memory (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  teammate    INTEGER NOT NULL REFERENCES teammate(id),
  text        TEXT NOT NULL,
  source      TEXT NOT NULL CHECK (source IN ('teammate','person')),
  card        INTEGER REFERENCES flow_card(id),
  state       TEXT NOT NULL CHECK (state IN ('active','forgotten')),
  created_by  TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  updated_by  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  used_at     TEXT
);
CREATE INDEX IF NOT EXISTS teammate_memory_live ON teammate_memory (teammate, state, id);
-- v95: a rule change a teammate suggests from what its people approved (five
-- approvals in a row of one action, say). Its manager accepts it or not; a
-- suggestion made when the rule was different goes stale.
CREATE TABLE IF NOT EXISTS teammate_suggestion (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  teammate      INTEGER NOT NULL REFERENCES teammate(id),
  tool          TEXT NOT NULL,
  action        TEXT NOT NULL,
  rule_json     TEXT NOT NULL,
  was_json      TEXT NOT NULL,
  evidence_json TEXT NOT NULL,
  said          TEXT NOT NULL,
  state         TEXT NOT NULL CHECK (state IN ('open','accepted','dismissed','stale')),
  decided_by    TEXT,
  decided_at    TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS teammate_suggestion_action ON teammate_suggestion (teammate, tool, action, id);
-- v91: where the reply watcher stands in the mailbox. One row.
CREATE TABLE IF NOT EXISTS flow_mail_watch (
  id           INTEGER PRIMARY KEY CHECK (id = 1),
  cursor       TEXT,
  next_at      TEXT,
  failures     INTEGER NOT NULL DEFAULT 0,
  last_outcome TEXT,
  updated_at   TEXT
);

-- v80: project tools. The MCP servers one project's builds may use (the
-- list replaces every other MCP source a build could load); secret values
-- live in 0600 files, never here. tool_seal is the list a task's approval
-- saw: a tool added later reaches only work approved after it, and a
-- removed tool leaves every build at once. run_tool is what one attempt
-- actually launched with, and what was left out and why.
CREATE TABLE IF NOT EXISTS project_tool (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  repo           TEXT NOT NULL,
  name           TEXT NOT NULL,
  spec_json      TEXT NOT NULL,
  digest         TEXT NOT NULL,
  source         TEXT NOT NULL,
  state          TEXT NOT NULL CHECK (state IN ('active','removed')),
  created_at     TEXT NOT NULL,
  created_by     TEXT NOT NULL,
  removed_at     TEXT,
  removed_by     TEXT,
  last_test_json TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS project_tool_live ON project_tool (repo, name) WHERE state = 'active';
CREATE TABLE IF NOT EXISTS tool_seal (
  task            TEXT NOT NULL,
  approved_digest TEXT NOT NULL,
  tools_json      TEXT NOT NULL,
  sealed_at       TEXT NOT NULL,
  PRIMARY KEY (task, approved_digest)
);
CREATE TABLE IF NOT EXISTS run_tool (
  run        INTEGER PRIMARY KEY,
  tools_json TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- v79: a Telegram message that showed one task (a /task status, a task
-- picked from /tasks): a reply to it is about that task. Like chat_focus,
-- a pointer and never an authority — the turn re-proves the task.
CREATE TABLE IF NOT EXISTS telegram_task_message (
  binding    INTEGER NOT NULL,
  chat_id    TEXT NOT NULL,
  message_id TEXT NOT NULL,
  task_id    TEXT NOT NULL,
  source_run INTEGER,
  created_at TEXT NOT NULL,
  PRIMARY KEY (binding, chat_id, message_id)
);

CREATE TABLE IF NOT EXISTS mate_proposal (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  thread         INTEGER NOT NULL REFERENCES mate_thread(id) ON DELETE CASCADE,
  turn           INTEGER NOT NULL,
  kind           TEXT NOT NULL CHECK (kind IN ('task','next','reserve','hold','unhold','steer','scope','cancel','answer','repair','agents','review','control','task_action','action')),
  payload_json   TEXT NOT NULL,
  ceiling_digest TEXT NOT NULL,
  state          TEXT NOT NULL CHECK (state IN ('drafting','pending','confirming','confirmed','refused','dismissed','expired')),
  created_at     TEXT NOT NULL,
  resolved_at    TEXT,
  resolved_by    TEXT,
  outcome_json   TEXT
);
CREATE INDEX IF NOT EXISTS mate_proposal_thread ON mate_proposal (thread, state);

CREATE TABLE IF NOT EXISTS coordinator_proposal (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  cid          TEXT NOT NULL REFERENCES coordinator_credential(cid),
  name         TEXT NOT NULL,
  repo         TEXT NOT NULL,
  kind         TEXT NOT NULL CHECK (kind IN ('next','reserve','hold','unhold','scope','cancel','answer')),
  payload_json TEXT NOT NULL,
  state        TEXT NOT NULL CHECK (state IN ('pending','confirming','confirmed','refused','dismissed','expired')),
  created_at   TEXT NOT NULL,
  resolved_at  TEXT,
  resolved_by  TEXT,
  outcome_json TEXT
);
CREATE INDEX IF NOT EXISTS coordinator_proposal_state ON coordinator_proposal (state, repo);

CREATE TABLE IF NOT EXISTS mate_turn (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  approver          TEXT NOT NULL,
  session           INTEGER NOT NULL REFERENCES mate_session(id),
  thread            INTEGER NOT NULL REFERENCES mate_thread(id),
  credential_key    TEXT NOT NULL,
  state             TEXT NOT NULL CHECK (state IN ('queued','running','answered','failed')),
  generation        INTEGER NOT NULL DEFAULT 1,
  created_at        TEXT NOT NULL,
  deadline_at       TEXT NOT NULL,
  finished_at       TEXT,
  reserved_microusd INTEGER NOT NULL,
  settled_microusd  INTEGER,
  steps             INTEGER NOT NULL DEFAULT 0,
  tokens_in         INTEGER,
  tokens_out        INTEGER,
  failure_reason    TEXT
);
CREATE INDEX IF NOT EXISTS mate_turn_live ON mate_turn (approver, state);

-- The firing ledger (v8): one row per scheduled slot, fired or skipped.
-- UNIQUE (routine_id, scheduled_for) is the idempotency — two passes both
-- finding the same due slot insert once, and the second learns it lost.
-- Skips are recorded, not silent: a budget block or a single-flight block
-- must render as a hollow dot, not read as "covered" (finding 10).
CREATE TABLE IF NOT EXISTS routine_fire (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  routine_id        INTEGER NOT NULL REFERENCES routine(id) ON DELETE CASCADE,
  scheduled_for     TEXT NOT NULL,
  outcome           TEXT NOT NULL CHECK (outcome IN ('fired','skipped')),
  reason            TEXT,
  instance_task_ref INTEGER REFERENCES task_ref(id),
  created_at        TEXT NOT NULL,
  UNIQUE (routine_id, scheduled_for)
);

CREATE INDEX IF NOT EXISTS routine_fire_recent ON routine_fire (routine_id, id DESC);

-- A hold is an operational pause, not a claim about the work's structure,
-- which is why it may live out here while dependency edges may not.
--
-- Every hold has an owner, because "lift the hold" is only safe when the
-- lifter and the placer are the same authority. One row per task let a
-- decision's answer delete an operator's unrelated pause — or a later manual
-- hold silently replace the one keeping a parked task off the ready set.
-- UNIQUE (owner_kind, owner_id) keeps each owner to one hold; readiness
-- rejects on ANY active row, so two owners holding one task both count.
CREATE TABLE IF NOT EXISTS hold (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref   INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  owner_kind TEXT NOT NULL CHECK (owner_kind IN ('operator','decision','incident','backoff','contest','revision','stop')),
  owner_id   TEXT NOT NULL,
  reason     TEXT NOT NULL,
  until      TEXT,
  held_at    TEXT NOT NULL,
  UNIQUE (owner_kind, owner_id)
);

-- One row per lease, not per task: the claim log is append-only.
--
-- Overwriting a task's claim on reclaim would erase the superseded lease, and
-- then a runner coming back from the dead to report its work could only be
-- told "I have never heard of that lease" — indistinguishable, from where it
-- is standing, from talking to the wrong database. Keeping the row lets it be
-- told the truth: you were superseded, at this generation, by this runner.
--
-- UNIQUE (task_ref, lease_generation) *is* the compare-and-swap. Two runners
-- racing both compute the same next generation; the database lets exactly one
-- of them insert it.
CREATE TABLE IF NOT EXISTS claim (
  lease_id         TEXT PRIMARY KEY,
  task_ref         INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  lease_generation INTEGER NOT NULL,
  runner           TEXT NOT NULL,
  acquired_at      TEXT NOT NULL,
  expires_at       TEXT NOT NULL,
  heartbeat_at     TEXT NOT NULL,
  released_at      TEXT,
  -- Who let go, because "released" alone conflates four different events:
  -- the runner handing it back ('released'), a completion being accepted
  -- ('completed'), expiry reap ('reaped'), and dead-runner recovery
  -- ('recovered'). A retry that finds its lease released must know which:
  -- answering "duplicate" to a runner whose lease was in fact reclaimed
  -- would accept work the reclaim already disowned.
  released_by      TEXT,
  UNIQUE (task_ref, lease_generation)
);

-- A capability: something a repo's work needs that this machine either has
-- or does not — a credential in the environment, a CLI that is logged in, an
-- MCP server that answers. Metadata only, and the absence of a value column
-- is load-bearing (§3): the control plane records "present, verified at T",
-- and the value itself lives on the runner, in a keychain or a gitignored
-- .env, where a database dump cannot leak it.
CREATE TABLE IF NOT EXISTS capability (
  repo             TEXT NOT NULL,
  kind             TEXT NOT NULL CHECK (kind IN ('env','cli','mcp','ci','other')),
  name             TEXT NOT NULL,
  probe            TEXT,
  status           TEXT NOT NULL DEFAULT 'unprobed' CHECK (status IN ('unprobed','verified','failed')),
  added_by         TEXT NOT NULL,
  created_at       TEXT NOT NULL,
  last_verified_at TEXT,
  -- Who ran the probe that produced this status. Verification is a claim
  -- about one environment: the machine whose shell answered. Another runner
  -- trusts it only by re-proving it where it stands, which is what tick does.
  verified_by      TEXT,
  -- The probe's own words when it said no — "exit 1", "timed out", "sh not
  -- found". Collapsing those into one bit would discard exactly the detail
  -- that tells an operator whether to paste a key or fix a PATH.
  last_result      TEXT,
  expires_at       TEXT,
  PRIMARY KEY (repo, kind, name)
);

-- One build attempt, durable. The in-memory BuildResult evaporates with the
-- process; the morning briefing, and anybody asking "what happened to t-1
-- overnight", need the answer to survive a crash. A row is written before
-- the agent runs and finalized after — outcome NULL means the attempt was
-- cut down mid-flight, which is itself worth knowing.
CREATE TABLE IF NOT EXISTS run (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  lease_id      TEXT NOT NULL,
  runner        TEXT NOT NULL,
  -- v24 dispatch stamps: the digests this invocation was PROVED against
  -- (warm resume matches on both), and the provider CLI version as
  -- provenance — never authority.
  scope_digest     TEXT,
  profile_digest   TEXT,
  provider_version TEXT,
  -- 'repair' is a resumed session mending its own malformed park payload.
  -- Deliberately NOT 'driver': the design's driver is the event-woken gate
  -- role that first exists at M4, and recording repair under that name now
  -- would make the two indistinguishable in every cost report afterwards.
  -- 'scout' (v34) reads a repository and delivers a report — its own word
  -- so scouting spend never hides under planning or building.
  role          TEXT NOT NULL DEFAULT 'builder' CHECK (role IN ('builder','repair','planner','reviewer','scout')),
  -- Which provider harness this attempt ran on (v9). The default is a
  -- truthful backfill for history: every run before v9 passed through the
  -- fixed claude gateway. New dispatches always supply it explicitly.
  provider      TEXT NOT NULL DEFAULT 'claude',
  parent_run    INTEGER REFERENCES run(id),
  -- The agent session, kept so a malformed park can be repaired by resuming
  -- the conversation that produced it instead of paying for a fresh one.
  session_id    TEXT,
  -- HEAD before the agent spent anything. Evidence is a diff against this,
  -- not against whatever the index looked like when the agent stopped: an
  -- agent that staged or committed before parking would otherwise show a
  -- clean diff over material changes.
  base_revision TEXT,
  branch        TEXT,
  worktree      TEXT,
  model         TEXT,
  phase         TEXT,
  contestant    INTEGER REFERENCES contestant(id),
  -- 'interrupted' (v25) is a held attended session cut down mid-flight —
  -- fence, expiry, crash custody, or shutdown. A real word, never a
  -- synthesized park; the one-shot road keeps writing failed/interrupted
  -- as outcome+reason exactly as before.
  outcome       TEXT CHECK (outcome IN ('built','failed','refused','parked','no-change','interrupted')),
  reason        TEXT,
  committed     INTEGER,
  -- The attended authorization this run consumed (v25) — the ruling-12
  -- attempt identity, stamped in the same transaction that consumes the
  -- one attempt. NULL = ordinary approved/tournament dispatch.
  attended_authorization TEXT REFERENCES attended_authorization(id),
  started_at    TEXT NOT NULL,
  finished_at   TEXT,
  -- Stamped by the invocation gateway the instant before the provider
  -- process spawns. A run without it never paid anything; the zero-token
  -- invariant is "provider spawns == runs carrying this stamp".
  provider_started_at TEXT,
  tokens_in     INTEGER,
  tokens_out    INTEGER,
  cost_usd      REAL,
  -- The provider's own usage object, bounded, for when the parsed columns
  -- above turn out to have missed something. NULL = unmeasured, and the
  -- brief says so rather than summing a lie.
  usage_json    TEXT,
  -- HEAD after the agent, as accepted. The builder owns commits; an agent
  -- that moved HEAD itself is refused, so this names the exact commit any
  -- publication may push.
  head_revision TEXT,
  -- The validated terminal handoff's conclusion — bounded, typed at
  -- ingestion, and the only agent prose a PR body may quote.
  handoff       TEXT,
  -- The fallback-chain and credential stamps (v30), inline since v34 —
  -- the same columns ALTER appended on older files; the v34 rebuild
  -- recognizes both placements as one shape.
  chain_cycle INTEGER REFERENCES fallback_cycle(id), chain_index INTEGER, entry_digest TEXT, auth_mode TEXT, terminal_class TEXT,
  -- v29 (the reviewer role): artifact-only runs carry NO workspace,
  -- honestly — every other role requires both (exclusive, no sentinels).
  CHECK ((role = 'reviewer' AND branch IS NULL AND worktree IS NULL)
      OR (role <> 'reviewer' AND branch IS NOT NULL AND worktree IS NOT NULL))
);

-- The decision record (§7): the judgement call an agent refused to guess at,
-- typed so it renders identically every time and fits on a phone. "run" is
-- the decision's whole identity — task, repo, branch, and lease are reached
-- by joining through it, never stored again here, because two copies of an
-- identity is how a decision ends up holding one task while showing another
-- task's evidence. v25 dropped the one-decision-per-run UNIQUE: a held
-- attended session parks, is answered, continues, and parks again — many
-- decisions, one run. At most ONE unresolved decision per run (partial
-- unique, post-migration block).
CREATE TABLE IF NOT EXISTS decision (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  urgency        TEXT NOT NULL CHECK (urgency IN ('blocking')),
  state          TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open','expired','answered')),
  recap          TEXT NOT NULL,
  question       TEXT NOT NULL,
  options        TEXT NOT NULL,
  recommendation TEXT NOT NULL,
  assignee       TEXT,
  -- Attention metadata only. A deadline is never a hold expiry: a blocking
  -- decision that goes overdue becomes 'expired' and MORE visible, not a
  -- task that quietly dispatches itself unanswered.
  deadline       TEXT,
  created_at     TEXT NOT NULL,
  answered_at    TEXT,
  answered_by    TEXT,
  -- Which racing agent asked (v14); lets one-open-question-per-agent be a
  -- real database rule instead of a hope (finding 28). NULL = ordinary.
  contestant     INTEGER REFERENCES contestant(id),
  -- Typed closure (v14): 'excluded' = the operator stopped the asking
  -- agent instead of answering. Never a fake option.
  closed_reason  TEXT CHECK (closed_reason IN ('excluded')),
  answered_via   TEXT CHECK (answered_via IN ('cli','web','telegram')),
  choice         TEXT,
  note           TEXT,
  -- v25 held-session linkage. session_turn = the turn whose settlement
  -- produced this park (causal, held runs only). delivered_turn = the
  -- answer turn that claimed delivery into the live session — the
  -- delivery-CAS target: set once (WHERE delivered_turn IS NULL), reverted
  -- only when that turn terminally never reached acceptance.
  session_turn   INTEGER REFERENCES session_turn(id),
  delivered_turn INTEGER REFERENCES session_turn(id)
);

-- Evidence, by reference (§4): the file lives on the runner under the
-- evidence root, and "key" is relative to that root — never an absolute path
-- a row could point anywhere with. The capture columns record how the file
-- was made and whether it is complete, because a truncated diff presented as
-- the whole story is worse than no diff.
CREATE TABLE IF NOT EXISTS artifact (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  kind           TEXT NOT NULL CHECK (kind IN ('diff','status','park-payload','plan','terminal-diff','diff-stat','handoff','revision-brief','base-tree','report','proof','check-log','screenshot','structured-output','plan-contract','review-context')),
  key            TEXT NOT NULL,
  bytes_original INTEGER NOT NULL,
  bytes_stored   INTEGER NOT NULL,
  truncated      INTEGER NOT NULL DEFAULT 0,
  sha256         TEXT NOT NULL,
  capture        TEXT NOT NULL,
  created_at     TEXT NOT NULL,
  redacted       INTEGER NOT NULL DEFAULT 0,
  -- Typed capture verdict (v14, finding 20): authority never parses the
  -- prose capture description again. NULL = recorded before v14.
  capture_status TEXT CHECK (capture_status IN ('ok','failed'))
);

-- Which artifacts a decision shows. A relation rather than JSON ids in the
-- decision row, so "artifact.run = decision.run" can be enforced at insert —
-- the agent's own payload never chooses what counts as evidence.
CREATE TABLE IF NOT EXISTS decision_artifact (
  decision INTEGER NOT NULL REFERENCES decision(id) ON DELETE CASCADE,
  artifact INTEGER NOT NULL REFERENCES artifact(id) ON DELETE CASCADE,
  PRIMARY KEY (decision, artifact)
);

-- Which answers a resume run was actually given, snapshot included — causal
-- provenance, not timestamps. "The run after the answer" stops being true the
-- moment a resume fails and a second decision is answered in between.
CREATE TABLE IF NOT EXISTS run_decision (
  run      INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  decision INTEGER NOT NULL REFERENCES decision(id) ON DELETE CASCADE,
  choice   TEXT NOT NULL,
  note     TEXT,
  PRIMARY KEY (run, decision)
);

-- A durable attention record for the parks that never became decisions: the
-- agent tried to park, repair ran out, and the task is now held with nothing
-- in DECIDE to show for it. Unlike a failed run, an incident cannot age out
-- of a briefing window — it stays in every brief until somebody resolves it.
CREATE TABLE IF NOT EXISTS incident (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  run         INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL CHECK (kind IN ('malformed-decision','attempts-exhausted','commit-failure','malformed-plan','plan-attempts-exhausted','malformed-report','malformed-proof')),
  created_at  TEXT NOT NULL,
  resolved_at TEXT,
  resolved_by TEXT
);

-- The durable outbox (§6). A notification is a fact that something wants a
-- person, recorded next to the record that made it true — because one that
-- lives only in a process's memory dies with the process, at exactly the
-- moment it was most worth sending. dedupe_key is an episode identity: a
-- gap nags once per occurrence, not once per cron firing and not forever.
CREATE TABLE IF NOT EXISTS notification (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  dedupe_key      TEXT NOT NULL UNIQUE,
  kind            TEXT NOT NULL,
  subject         TEXT NOT NULL,
  body            TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  attempts        INTEGER NOT NULL DEFAULT 0,
  last_attempt_at TEXT,
  last_error      TEXT,
  delivered_at    TEXT,
  -- What the delivery command said on success — the closest thing to a
  -- provider receipt a shell command can hand back.
  receipt         TEXT,
  -- The push surface (arc 3, v23): a CLOSED attention class and a
  -- machine-minted console link, stamped by producers at enqueue.
  -- Unstamped kinds never reach a phone; subject/body never do either.
  push_class      TEXT CHECK (push_class IN ('decision','pick','merge','attention')),
  link            TEXT
);

-- Away mode (v34, mate arc §10): the Telegram bridge's digest cadence.
-- One row. every_ms NULL = off (every fact pages as it lands); set, the
-- bridge holds ROUTINE rows unclaimed until the window elapses and sends
-- them as one message — decisions and attention-class facts still page
-- singly. last_sent_at anchors the window; it never deletes a row.
CREATE TABLE IF NOT EXISTS telegram_digest (
  id           INTEGER PRIMARY KEY CHECK (id = 1),
  every_ms     INTEGER,
  set_by       TEXT,
  set_at       TEXT,
  last_sent_at TEXT
);
INSERT OR IGNORE INTO telegram_digest (id, every_ms) VALUES (1, NULL);

-- Permission to write to a tracker, one row per repository and backend.
-- Absence of a row is denial; there is no wildcard and no inheritance.
CREATE TABLE IF NOT EXISTS backend_grant (
  repo             TEXT NOT NULL,
  backend          TEXT NOT NULL,
  paths            TEXT NOT NULL DEFAULT '[]',
  mutations        TEXT NOT NULL DEFAULT '[]',
  selector         TEXT NOT NULL,
  credential_scope TEXT,
  observed_by_git  INTEGER NOT NULL,
  granted_at       TEXT NOT NULL,
  granted_by       TEXT NOT NULL,
  -- External dispatch (v20): a SEPARATE authority from tracker writes —
  -- "this plane will BUILD what this tracker nominates". Never granted
  -- by default; dispatch=1 requires remote_repo and plane_id (enforced
  -- in saveGrant — ALTER ADD COLUMN cannot carry cross-column CHECKs).
  dispatch                INTEGER NOT NULL DEFAULT 0 CHECK (dispatch IN (0, 1)),
  remote_repo             TEXT,
  plane_id                TEXT,
  dispatch_blocked        TEXT CHECK (dispatch_blocked IN ('pending-marker','unreachable','foreign','missing','multiple-or-malformed')),
  dispatch_blocked_at     TEXT,
  dispatch_blocked_detail TEXT,
  PRIMARY KEY (repo, backend)
);

-- The external mirror (v20): a synced tracker item, dispatchable as an
-- ORDINARY local task. Identity and provenance are immutable — labels
-- and titles may nominate work; only this row establishes whose it is.
CREATE TABLE IF NOT EXISTS external_mirror (
  local_task_id   TEXT PRIMARY KEY REFERENCES task(id) ON DELETE CASCADE,
  backend         TEXT NOT NULL,
  remote_repo     TEXT NOT NULL,
  remote_id       TEXT NOT NULL,
  provenance      TEXT NOT NULL CHECK (provenance IN ('local-create','intake','granted-all')),
  intake_grant    INTEGER,
  established_by  TEXT NOT NULL,
  established_at  TEXT NOT NULL,
  remote_state    TEXT NOT NULL CHECK (remote_state IN ('open','closed','missing')),
  close_generation INTEGER,
  sync_generation INTEGER NOT NULL DEFAULT 0,
  dispatch_ok     INTEGER NOT NULL DEFAULT 0 CHECK (dispatch_ok IN (0, 1)),
  reopened_by     TEXT,
  reopened_at     TEXT,
  CHECK ((provenance = 'intake') = (intake_grant IS NOT NULL)),
  UNIQUE (backend, remote_repo, remote_id)
);

-- Immutability guard: identity/provenance columns refuse CHANGES; an
-- upsert rewriting identical values passes.
CREATE TRIGGER IF NOT EXISTS external_mirror_immutable
BEFORE UPDATE ON external_mirror
WHEN OLD.backend IS NOT NEW.backend OR OLD.remote_repo IS NOT NEW.remote_repo
  OR OLD.remote_id IS NOT NEW.remote_id OR OLD.provenance IS NOT NEW.provenance
  OR OLD.intake_grant IS NOT NEW.intake_grant
  OR OLD.established_by IS NOT NEW.established_by OR OLD.established_at IS NOT NEW.established_at
BEGIN
  SELECT RAISE(ABORT, 'external mirror identity is immutable');
END;

-- One row per sync pass; only a COMPLETE pass advances mirror
-- generations (a capped or failed scan proves nothing about absence).
CREATE TABLE IF NOT EXISTS sync_ledger (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  backend     TEXT NOT NULL,
  remote_repo TEXT NOT NULL,
  generation  INTEGER NOT NULL,
  started_at  TEXT NOT NULL,
  finished_at TEXT,
  outcome     TEXT CHECK (outcome IN ('complete','capped','failed')),
  candidates  INTEGER NOT NULL DEFAULT 0,
  mirrored    INTEGER NOT NULL DEFAULT 0,
  detail      TEXT,
  UNIQUE (backend, remote_repo, generation)
);

-- Durable write-back intents: delivery has its own ledger; a run's
-- outcome is never rewritten by a tracker write failing.
CREATE TABLE IF NOT EXISTS external_intent (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  mirror       TEXT NOT NULL REFERENCES external_mirror(local_task_id),
  kind         TEXT NOT NULL CHECK (kind IN ('comment','transition','close')),
  body         TEXT,
  state        TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','delivered','refused')),
  attempts     INTEGER NOT NULL DEFAULT 0,
  last_error   TEXT,
  created_at   TEXT NOT NULL,
  delivered_at TEXT
);

-- The merge grant's evidence (v21): the LATEST CI observation per PR,
-- generation-ordered so a stalled older response can never overwrite —
-- or authorize past — a newer one. Only a WINNING settle has effects.
CREATE TABLE IF NOT EXISTS ci_observation (
  github_repo TEXT NOT NULL,
  pr_number   INTEGER NOT NULL,
  head_sha    TEXT NOT NULL,
  state       TEXT NOT NULL CHECK (state IN ('passing','failing','running','none')),
  generation  INTEGER NOT NULL,
  observed_at TEXT NOT NULL,
  PRIMARY KEY (github_repo, pr_number)
);

-- Durable merge intents (v21): one per publication, claim-leased with a
-- generation fence so overlapping passes cannot double-fire and a crash
-- can never strand a claim or leave "did it merge?" ambiguous.
CREATE TABLE IF NOT EXISTS merge_intent (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  publication   INTEGER NOT NULL UNIQUE REFERENCES publication(id),
  grant_terms_hash TEXT NOT NULL,
  head_sha      TEXT NOT NULL,
  method        TEXT NOT NULL CHECK (method IN ('squash','merge','rebase')),
  delete_branch INTEGER NOT NULL DEFAULT 0 CHECK (delete_branch IN (0, 1)),
  state         TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','claimed','waiting-human','firing','merged','refused','superseded')),
  claimed_by    TEXT,
  claimed_until TEXT,
  -- v29 (modes): WHOSE signature this intent fires under, bound at
  -- creation and re-proved in the firing CAS — 'grant' = the grant
  -- ceremony's own unattended-merge signature; 'mode' = a live automerge
  -- mode; 'human' = the per-merge password ceremony.
  authority_basis TEXT NOT NULL DEFAULT 'grant' CHECK (authority_basis IN ('grant','mode','human')),
  mode_digest   TEXT,
  -- v29: the durable one-winner linearization point — the CAS into
  -- 'firing' stamps both; staleness is firing_deadline passing, never a
  -- guess.
  firing_at     TEXT,
  firing_deadline TEXT,
  generation    INTEGER NOT NULL DEFAULT 0,
  attempts      INTEGER NOT NULL DEFAULT 0,
  last_error    TEXT,
  receipt       TEXT,
  created_at    TEXT NOT NULL,
  settled_at    TEXT,
  CHECK (state <> 'claimed' OR (claimed_by IS NOT NULL AND claimed_until IS NOT NULL)),
  CHECK (state <> 'firing' OR (firing_at IS NOT NULL AND firing_deadline IS NOT NULL))
);

-- A CI repair in flight durably blocks its source PR's merge (v21).
-- STICKY by design: no task-lifecycle path touches it — it lifts only
-- by the authenticated unblock act or the PR itself closing remotely.
CREATE TABLE IF NOT EXISTS merge_blocker (
  publication INTEGER NOT NULL REFERENCES publication(id),
  reason      TEXT NOT NULL CHECK (reason IN ('repair-open')),
  task_id     TEXT,
  created_at  TEXT NOT NULL,
  -- v29: lifting is a stamp, not a DELETE — who unblocked, and when, is
  -- an audit answer the People screen promises. One LIVE blocker per
  -- publication (partial unique in the post-migration block); lifted
  -- rows are history and never block a new block.
  lifted_at   TEXT,
  lifted_by   TEXT
);

-- An OPERATING MODE (v29): a per-repository, password-signed, expiring
-- envelope that pre-authorizes the SIGNER'S OWN future acts — filing
-- approvals, quick mints, escalated permission defaults, automerge —
-- through the exact predicates the design chain binds. The absence of a
-- row is 'locked': today's ceremony-per-act world, the default forever.
-- Raising authority is a password ceremony; revoking is one click; every
-- transition is an event row.
CREATE TABLE IF NOT EXISTS operating_mode (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  repo            TEXT NOT NULL,
  name            TEXT NOT NULL CHECK (name IN ('standard','hands-off')),
  terms_json      TEXT NOT NULL,
  digest          TEXT NOT NULL,
  signed_by       TEXT NOT NULL REFERENCES approver(name) ON DELETE RESTRICT,
  signed_at       TEXT NOT NULL,
  absolute_expiry TEXT NOT NULL,
  revoked_at      TEXT,
  revoked_by      TEXT,
  revoke_reason   TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS one_live_mode_per_repo
  ON operating_mode (repo) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS operating_mode_event (
  id       INTEGER PRIMARY KEY AUTOINCREMENT,
  mode     INTEGER NOT NULL REFERENCES operating_mode(id),
  kind     TEXT NOT NULL CHECK (kind IN ('signed','renewed','revoked','expired-closed','signer-revoked')),
  actor    TEXT NOT NULL,
  at       TEXT NOT NULL
);

-- A single-use invite (v29): 128-bit token, sha256 stored, role pinned at
-- mint. attempts meters ADMITTED submissions — the slot is spent
-- atomically BEFORE the KDF runs, and never refunded.
CREATE TABLE IF NOT EXISTS invite (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  token_hash  TEXT NOT NULL UNIQUE,
  role        TEXT NOT NULL CHECK (role IN ('approver','viewer')),
  minted_by   TEXT NOT NULL REFERENCES approver(name) ON DELETE RESTRICT,
  minted_at   TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  attempts    INTEGER NOT NULL DEFAULT 0,
  consumed_by TEXT,
  consumed_at TEXT,
  revoked_at  TEXT
);

-- The daily rails' reservation counter (v29): one row per repo per UTC
-- day, incremented atomically at admission — never a query-then-hope.
CREATE TABLE IF NOT EXISTS mode_rail (
  repo            TEXT NOT NULL,
  utc_day         TEXT NOT NULL,
  reserved_starts INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (repo, utc_day)
);

-- What a task is allowed to become, and whether a person agreed to it.
--
-- approved_digest is the whole mechanism: approval records the exact scope it
-- saw, so rewriting the scope afterwards does not carry the approval with it.
CREATE TABLE IF NOT EXISTS task_scope (
  task_id         TEXT PRIMARY KEY REFERENCES task(id) ON DELETE CASCADE,
  goal            TEXT NOT NULL,
  out_of_scope    TEXT,
  touches         TEXT NOT NULL DEFAULT '[]',
  proposed_at     TEXT NOT NULL,
  digest          TEXT NOT NULL,
  -- The dollar cap per build attempt, integer micro-dollars (v15):
  -- approved spend, digest-bound, enforced by the provider's own stop.
  budget_microusd INTEGER,
  approved_at     TEXT,
  approved_by     TEXT,
  approved_digest TEXT,
  -- The execution profile (v24, Parity II foundations): WHAT RUNS, bound
  -- into what the operator signs. profile_json = the working profile;
  -- approved_profile_json = the immutable snapshot the approval act took;
  -- digest_version 1 = legacy fields-only digest (grandfathered), 2 =
  -- profile-bearing. profile_state 'unresolved' blocks dispatch AND
  -- approval, with its reason in words. Provenance (resolvedFrom,
  -- grandfathered, provider version) lives in profile_provenance and
  -- NEVER enters a digest.
  profile_json          TEXT,
  profile_state         TEXT NOT NULL DEFAULT 'resolved' CHECK (profile_state IN ('resolved','unresolved')),
  unresolved_reason     TEXT,
  approved_profile_json TEXT,
  digest_version        INTEGER NOT NULL DEFAULT 1,
  profile_provenance    TEXT,
  -- The EXPLICIT fallback chain (v30, fallback chains). proposed_chain_json
  -- is the WORKING snapshot saveScope binds the digest to when the repo has
  -- configured fallbacks (mirrors profile_json); approved_chain_json is the
  -- immutable snapshot the approval COPIED from it (mirrors
  -- approved_profile_json = profile_json), so what is sealed is exactly what
  -- the signed digest bound — never re-resolved. Both NULL = a legacy
  -- single-profile (or no-profile) scope, untouched. approval_kind names
  -- which the approval sealed: 'profile' (legacy) or 'chain'.
  proposed_chain_json   TEXT,
  approved_chain_json   TEXT,
  -- The signed acceptance rubric (v39, Acceptance Contract v2): the SAME
  -- additive shape as every digest-bound field before it. NULL/absent
  -- reads back as [] and digests exactly as a rubric-less scope always
  -- has -- grandfathering is this column simply not existing on a row
  -- nobody has rewritten since. What makes a rubric MANDATORY going
  -- forward is enforced by the authoring roads (proposeGuarded,
  -- createConsoleTask, routine firing, the planner), never by this
  -- schema or by saveScope itself.
  acceptance_json       TEXT,
  -- The concrete quality policy (v41), folded into digest only when strict
  -- so every historical/default approval remains byte-identical.
  quality_mode          TEXT NOT NULL DEFAULT 'default' CHECK (quality_mode IN ('default','strict')),
  approval_kind         TEXT NOT NULL DEFAULT 'profile' CHECK (approval_kind IN ('profile','chain')),
  -- The phase route (v47, explainable risk-aware routing). risk_level is
  -- the signed risk; proposed_route_json is the WORKING canonical route
  -- saveScope computed from risk, quality, evidence, publication, the
  -- configured candidate tiers, and the task's overrides; EVERY route
  -- filed since v47 folds its digest into the scope digest, routine-shaped
  -- ones included. approved_route_json is the immutable snapshot the seal
  -- COPIED, exactly as approved_profile_json mirrors profile_json —
  -- dispatch re-proves against it and mutable configuration can never
  -- rewrite it. route_era is the DURABLE marker: NULL only on a row proven
  -- to predate v47 (legacy — its sealed profile alone governs the build);
  -- the route version on every row saveScope has written since. A row with
  -- an era and a missing or unreadable route is corrupt and FAILS CLOSED
  -- at approval, dispatch, review, and repair alike.
  risk_level            TEXT NOT NULL DEFAULT 'routine' CHECK (risk_level IN ('routine','elevated','high')),
  proposed_route_json   TEXT,
  approved_route_json   TEXT,
  route_era             INTEGER
);

-- Whoever is allowed to say yes to a scope.
--
-- Separate from a runner on purpose: a runner is a machine that does work, and
-- an approver is a person who agrees to it. Sharing one table would mean any
-- credential that can take a task can also approve one, which is the exact
-- collapse this whole gate exists to prevent.
CREATE TABLE IF NOT EXISTS approver (
  name            TEXT PRIMARY KEY,
  credential_hash TEXT NOT NULL,
  added_at        TEXT NOT NULL,
  -- v29 (multi-user): 'viewer' authenticates and reads; every
  -- consequential act requires ACTIVE role 'approver'. Revocation is a
  -- stamp — history stays attributable forever.
  role            TEXT NOT NULL DEFAULT 'approver' CHECK (role IN ('approver','viewer')),
  revoked_at      TEXT,
  revoked_by      TEXT,
  -- Bumped whenever the credential is replaced. Anything that derives
  -- authority from an approver — a paired Telegram chat, an outstanding
  -- pairing code — records the generation it was granted under, and a
  -- rotation strands every grant from the old one.
  generation      INTEGER NOT NULL DEFAULT 1
);

-- One Telegram chat speaking as one approver. Bindings are never deleted:
-- revocation is a stamp, because "who could answer as whom, when" is an
-- audit question a DELETE cannot answer. The partial unique index (v72) is
-- the rule that one Telegram user has one live binding per bot: several
-- teammates pair their own private chats with the same bot.
CREATE TABLE IF NOT EXISTS telegram_binding (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  bot_id              TEXT NOT NULL,
  chat_id             TEXT NOT NULL,
  user_id             TEXT NOT NULL,
  approver            TEXT NOT NULL REFERENCES approver(name) ON DELETE RESTRICT,
  approver_generation INTEGER NOT NULL,
  paired_at           TEXT NOT NULL,
  paired_by           TEXT NOT NULL,
  pair_update_id      INTEGER,
  revoked_at          TEXT,
  revoked_by          TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS telegram_binding_live_user
  ON telegram_binding (bot_id, user_id) WHERE revoked_at IS NULL;

-- v72: a Telegram chat's place in the shared team conversations. A group
-- follows exactly one team conversation (and a conversation has at most one
-- group); a private chat may select one conversation to talk in instead of
-- its personal assistant. The cursor is the last conversation message this
-- chat received. Rows are revoked, never deleted.
CREATE TABLE IF NOT EXISTS telegram_team_chat (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  bot_id       TEXT NOT NULL,
  chat_id      TEXT NOT NULL,
  binding      INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  kind         TEXT NOT NULL CHECK (kind IN ('group','private')),
  conversation TEXT NOT NULL REFERENCES team_conversation(id) ON DELETE RESTRICT,
  bound_by     TEXT NOT NULL,
  bound_at     TEXT NOT NULL,
  cursor       INTEGER NOT NULL DEFAULT 0,
  revoked_at   TEXT,
  revoked_by   TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS telegram_team_chat_live
  ON telegram_team_chat (bot_id, chat_id) WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS telegram_team_chat_group
  ON telegram_team_chat (conversation) WHERE revoked_at IS NULL AND kind = 'group';

-- v61: destination receipts around the existing outbox, independent of its
-- legacy shell/webhook receipt and of push_delivery. No second scheduler.
CREATE TABLE IF NOT EXISTS notification_delivery (
  notification INTEGER NOT NULL REFERENCES notification(id) ON DELETE RESTRICT,
  destination TEXT NOT NULL,
  claim_owner TEXT,
  claim_generation INTEGER NOT NULL DEFAULT 0,
  claim_expires_at TEXT,
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TEXT,
  last_attempt_at TEXT,
  last_error TEXT,
  delivered_at TEXT,
  receipt TEXT,
  PRIMARY KEY (notification, destination)
);
CREATE TABLE IF NOT EXISTS telegram_outbound_message (
  binding INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  bot_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  message_id TEXT NOT NULL,
  notification INTEGER NOT NULL REFERENCES notification(id) ON DELETE RESTRICT,
  destination TEXT NOT NULL,
  project TEXT,
  task_ref INTEGER REFERENCES task_ref(id),
  task_id TEXT,
  source_run INTEGER REFERENCES run(id),
  created_at TEXT NOT NULL,
  PRIMARY KEY (binding, chat_id, message_id, notification)
);
CREATE TABLE IF NOT EXISTS telegram_retry (
  bot_id TEXT PRIMARY KEY,
  next_attempt_at TEXT NOT NULL
);

-- One-time pairing codes, hashed like every other credential, consumed in
-- one transaction with the binding they create.
CREATE TABLE IF NOT EXISTS telegram_pairing (
  code_hash       TEXT PRIMARY KEY,
  approver        TEXT NOT NULL REFERENCES approver(name) ON DELETE RESTRICT,
  approver_generation INTEGER NOT NULL,
  created_at      TEXT NOT NULL,
  created_by      TEXT NOT NULL,
  expires_at      TEXT NOT NULL,
  consumed_at     TEXT,
  consumed_chat   TEXT,
  consumed_user   TEXT,
  consumed_update INTEGER
);

-- Every Telegram update this installation has applied, exactly once. The
-- PRIMARY KEY is the idempotency: a replayed batch re-applies nothing.
CREATE TABLE IF NOT EXISTS telegram_update (
  update_id  INTEGER PRIMARY KEY,
  applied_at TEXT NOT NULL,
  result     TEXT NOT NULL
);

-- Opaque one-tap actions. callback_data carries only the random token; what
-- the tap MEANS — which binding, decision, option, and phase — lives here,
-- where a stolen bot token cannot read or forge it. Confirm challenges are
-- short-lived rows in the same table, consumed exactly once.
CREATE TABLE IF NOT EXISTS telegram_action (
  token       TEXT PRIMARY KEY,
  binding     INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  decision    INTEGER NOT NULL REFERENCES decision(id) ON DELETE CASCADE,
  option_id   TEXT NOT NULL,
  phase       TEXT NOT NULL CHECK (phase IN ('choose','confirm','cancel')),
  chat_id     TEXT NOT NULL,
  message_id  TEXT,
  created_at  TEXT NOT NULL,
  expires_at  TEXT,
  consumed_at TEXT
);
CREATE INDEX IF NOT EXISTS telegram_action_by_decision ON telegram_action (decision);

-- v86: a flow card waiting at a "Person decides" zone reaches the decider on
-- Telegram with Approve / Edit / Send back. Each button is one opaque token
-- for one visit of one card (card, entry), placed on the message it rides so
-- a tap on any other message proves itself stale. Edit and Send back ask
-- for a reply to a prompt: telegram_flow_prompt names which prompt means
-- what, so the reply becomes the new draft or the note.
CREATE TABLE IF NOT EXISTS telegram_flow_action (
  token       TEXT PRIMARY KEY,
  binding     INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  card        INTEGER NOT NULL REFERENCES flow_card(id),
  entry       INTEGER NOT NULL,
  action      TEXT NOT NULL CHECK (action IN ('approve','edit','send-back')),
  chat_id     TEXT NOT NULL,
  message_id  TEXT,
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  consumed_at TEXT
);
CREATE INDEX IF NOT EXISTS telegram_flow_action_visit ON telegram_flow_action (card, entry);
-- v93: a teammate's question on Telegram. One button per option (choice)
-- and one to reply in words (choice NULL), placed on the message it rides;
-- a reply to the prompt the Reply button sends is the answer.
CREATE TABLE IF NOT EXISTS telegram_question_action (
  token       TEXT PRIMARY KEY,
  binding     INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  question    INTEGER NOT NULL REFERENCES teammate_question(id),
  choice      TEXT,
  chat_id     TEXT NOT NULL,
  message_id  TEXT,
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  consumed_at TEXT
);
CREATE TABLE IF NOT EXISTS telegram_question_prompt (
  chat_id     TEXT NOT NULL,
  message_id  TEXT NOT NULL,
  binding     INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  question    INTEGER NOT NULL REFERENCES teammate_question(id),
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  consumed_at TEXT,
  PRIMARY KEY (chat_id, message_id)
);
CREATE TABLE IF NOT EXISTS telegram_flow_prompt (
  chat_id     TEXT NOT NULL,
  message_id  TEXT NOT NULL,
  binding     INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  card        INTEGER NOT NULL REFERENCES flow_card(id),
  entry       INTEGER NOT NULL,
  mode        TEXT NOT NULL CHECK (mode IN ('edit','send-back')),
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  consumed_at TEXT,
  PRIMARY KEY (chat_id, message_id)
);

-- Which outbound Telegram message carries which decision (v10). A free-text
-- reply is routed through the EXACT message it replies to — never "the
-- latest decision", never "the only open one" (Codex free-text review,
-- finding 1). Losing the send/record race fails closed: an unrecorded
-- message routes nothing.
CREATE TABLE IF NOT EXISTS telegram_decision_message (
  binding    INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE CASCADE,
  chat_id    TEXT NOT NULL,
  message_id TEXT NOT NULL,
  decision   INTEGER NOT NULL REFERENCES decision(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL,
  PRIMARY KEY (binding, chat_id, message_id)
);

-- The free-text draft (v10): an operator's note, held immutable and
-- expiring until a TAP commits it with the choice. One live draft per
-- (binding, decision); a newer valid reply SUPERSEDES, never edits.
CREATE TABLE IF NOT EXISTS telegram_note_draft (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  binding    INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE CASCADE,
  decision   INTEGER NOT NULL REFERENCES decision(id) ON DELETE CASCADE,
  update_id  INTEGER NOT NULL,
  message_id TEXT NOT NULL,
  reply_to   TEXT NOT NULL,
  note       TEXT NOT NULL,
  state      TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','armed','superseded','consumed','discarded')),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS telegram_note_draft_live
  ON telegram_note_draft (binding, decision) WHERE state IN ('pending','armed');

-- v62: the durable inbound conversation queue. An ordinary paired message
-- becomes a row in the SAME transaction that marks its update applied, so
-- the poll cursor never moves past text nobody holds. The row carries the
-- exact binding, sender, update, message and the request identity the
-- shared mate engine receipts it under; the async model turn runs OUTSIDE
-- any transaction under a short claim, and a replay or restart finds the
-- receipt instead of dispatching the provider again.
CREATE TABLE IF NOT EXISTS telegram_conversation (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  binding             INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  bot_id              TEXT NOT NULL,
  chat_id             TEXT NOT NULL,
  user_id             TEXT NOT NULL,
  approver            TEXT NOT NULL,
  approver_generation INTEGER NOT NULL,
  update_id           INTEGER NOT NULL UNIQUE,
  message_id          TEXT NOT NULL,
  reply_to            TEXT,
  request             TEXT NOT NULL UNIQUE,
  text                TEXT NOT NULL,
  context             TEXT,
  task_id             TEXT,
  source_run          INTEGER,
  state               TEXT NOT NULL CHECK (state IN ('queued','running','done','failed')),
  claim_owner         TEXT,
  claim_expires_at    TEXT,
  attempts            INTEGER NOT NULL DEFAULT 0,
  next_attempt_at     TEXT,
  session             INTEGER,
  turn                INTEGER,
  outcome             TEXT,
  reply_message_id    TEXT,
  created_at          TEXT NOT NULL,
  started_at          TEXT,
  finished_at         TEXT
);
CREATE INDEX IF NOT EXISTS telegram_conversation_queue ON telegram_conversation (bot_id, state, id);

-- v62: opaque one-tap tokens for the mate's proposal cards, the same shape
-- as telegram_action for decisions: callback_data carries only the token,
-- and what a tap MEANS (which binding, which proposal, which phase) lives
-- here. Consumed exactly once; an irreversible answer arms a yes/cancel
-- pair first, exactly as a decision button does.
CREATE TABLE IF NOT EXISTS telegram_proposal_action (
  token       TEXT PRIMARY KEY,
  binding     INTEGER NOT NULL REFERENCES telegram_binding(id) ON DELETE RESTRICT,
  proposal    INTEGER NOT NULL REFERENCES mate_proposal(id) ON DELETE CASCADE,
  phase       TEXT NOT NULL CHECK (phase IN ('confirm','dismiss','yes','cancel')),
  chat_id     TEXT NOT NULL,
  message_id  TEXT,
  created_at  TEXT NOT NULL,
  expires_at  TEXT,
  consumed_at TEXT
);
CREATE INDEX IF NOT EXISTS telegram_proposal_action_by_proposal ON telegram_proposal_action (proposal);

-- v63: the outbound half of a conversation, durable BEFORE any send. Once
-- the engine's turn is answered (or recovered from its receipt), the exact
-- reply text, split into Telegram-sized parts, and one card per pending
-- proposal are written here in one transaction; the bridge then sends
-- them in order under the row's claim, marking a part sent only when
-- Telegram confirmed a message id. A crash, an outage, a rate limit or a
-- restart resumes from the first unsent part — never another model call,
-- proposal, task or revision. A card's buttons are minted with the part,
-- so a resend carries the same tokens. A part whose network answer was
-- lost is counted as uncertain: a resend may duplicate it, and the row
-- says so instead of claiming an exactly-once Telegram cannot provide.
-- v64: an 'image' part is one verified screenshot of one exact result,
-- named by typed columns — task, run, artifact and the hash its record
-- carried when the part was planned — never by JSON inside text or a
-- keyboard, and never by bytes: every send re-reads the artifact from the
-- evidence root and re-verifies it against these columns first. Its text
-- is the short caption. A confirmed image message binds replies to that
-- exact task and run, exactly as an outbox fact's message does.
CREATE TABLE IF NOT EXISTS telegram_conversation_part (
  conversation    INTEGER NOT NULL REFERENCES telegram_conversation(id) ON DELETE CASCADE,
  ordinal         INTEGER NOT NULL,
  kind            TEXT NOT NULL CHECK (kind IN ('reply','card','image')),
  text            TEXT NOT NULL,
  reply_to        TEXT,
  proposal        INTEGER REFERENCES mate_proposal(id) ON DELETE SET NULL,
  keyboard_json   TEXT,
  state           TEXT NOT NULL CHECK (state IN ('pending','sent','dropped')),
  message_id      TEXT,
  attempts        INTEGER NOT NULL DEFAULT 0,
  uncertain       INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TEXT,
  last_error      TEXT,
  created_at      TEXT NOT NULL,
  sent_at         TEXT,
  task_id         TEXT,
  source_run      INTEGER REFERENCES run(id),
  artifact        INTEGER,
  sha256          TEXT,
  PRIMARY KEY (conversation, ordinal),
  CHECK ((state = 'sent') = (message_id IS NOT NULL)),
  CHECK ((state = 'sent') = (sent_at IS NOT NULL)),
  CHECK ((kind = 'image') = (task_id IS NOT NULL AND source_run IS NOT NULL AND artifact IS NOT NULL AND sha256 IS NOT NULL))
);

-- v64: the screenshots one mate turn selected for an exact result, kept
-- under the turn so a channel that delivers files (Telegram) plans them
-- from the completed turn after a crash without another model call. Only
-- trusted identities ride here — the task, its run, the artifact row and
-- the hash that row carried — never bytes, paths or model prose. A failed
-- turn's rows are deleted with its drafts; a channel sends nothing from a
-- turn that did not answer, and re-verifies every artifact before upload.
CREATE TABLE IF NOT EXISTS mate_turn_evidence (
  turn       INTEGER NOT NULL REFERENCES mate_turn(id) ON DELETE CASCADE,
  ordinal    INTEGER NOT NULL,
  task_id    TEXT NOT NULL,
  task_ref   INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  run        INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  artifact   INTEGER NOT NULL REFERENCES artifact(id) ON DELETE CASCADE,
  sha256     TEXT NOT NULL,
  format     TEXT NOT NULL CHECK (format IN ('png','jpeg')),
  bytes      INTEGER NOT NULL,
  caption    TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (turn, ordinal),
  UNIQUE (turn, artifact)
);

-- The bridge's poll lease and cursor, per bot. One live poller at a time;
-- the cursor only ever moves forward, and only under a live generation.
CREATE TABLE IF NOT EXISTS bridge_lease (
  bot_id       TEXT PRIMARY KEY,
  owner        TEXT NOT NULL,
  generation   INTEGER NOT NULL,
  cursor       INTEGER NOT NULL DEFAULT 0,
  expires_at   TEXT NOT NULL,
  heartbeat_at TEXT NOT NULL,
  push_url     TEXT,
  push_at      TEXT,
  push_problem TEXT
);
-- v98: updates Telegram pushed to /hooks/telegram, kept until the bridge
-- applies them (in update order, through the same door as polled ones).
CREATE TABLE IF NOT EXISTS telegram_inbox (
  update_id    INTEGER PRIMARY KEY,
  bot_id       TEXT NOT NULL,
  payload      TEXT NOT NULL,
  received_at  TEXT NOT NULL
);

-- Provider quota, keyed to what actually exhausts: one runner's credential
-- against one provider and scope — never the whole runner (§8 gate 3). A
-- free CPU slot against an exhausted quota is not capacity. 'half-open'
-- admits exactly one real dispatch after the reset; its success clears the
-- row, the same structured signal re-stamps it. Nothing stamps this from
-- stderr prose — only structured signals or an operator.
-- The scheduler's durable wake signal. Every readiness-changing write bumps
-- the sequence; watch records what it saw before a pass and runs again
-- immediately if the world moved while it worked. A boolean dirty flag
-- loses the wake that lands mid-pass; a monotonic sequence cannot.
CREATE TABLE IF NOT EXISTS wake (
  id  INTEGER PRIMARY KEY CHECK (id = 1),
  seq INTEGER NOT NULL DEFAULT 0
);
INSERT OR IGNORE INTO wake (id, seq) VALUES (1, 0);

-- One watch per (runner, repo), with an incarnation the claims it dispatches
-- carry. A restarted watch that heartbeats before its dead predecessor is
-- noticed would otherwise mask the crash forever (finding 8): recovery is
-- keyed to the superseded incarnation, not to runner liveness.
CREATE TABLE IF NOT EXISTS watch_lease (
  runner       TEXT NOT NULL,
  repo         TEXT NOT NULL,
  owner        TEXT NOT NULL,
  generation   INTEGER NOT NULL,
  started_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  heartbeat_at TEXT NOT NULL,
  PRIMARY KEY (runner, repo)
);

CREATE TABLE IF NOT EXISTS quota (
  runner      TEXT NOT NULL,
  provider    TEXT NOT NULL,
  scope       TEXT NOT NULL DEFAULT '',
  -- v30 (fallback chains): quota identity must distinguish a subscription
  -- from an API key, else exhausting a claude subscription would wrongly
  -- block a claude api-key fallback. auth_mode + a stable NON-SECRET
  -- credential fingerprint join the key. Defaults keep every pre-v30 row
  -- identical (mode 'subscription', empty fp) since that is what they were.
  auth_mode   TEXT NOT NULL DEFAULT 'subscription' CHECK (auth_mode IN ('subscription','api-key')),
  credential_fp TEXT NOT NULL DEFAULT '',
  state       TEXT NOT NULL CHECK (state IN ('exhausted','half-open')),
  reason      TEXT NOT NULL,
  observed_at TEXT NOT NULL,
  reset_at    TEXT,
  PRIMARY KEY (runner, provider, scope, auth_mode, credential_fp)
);

-- A fallback CYCLE (v30): one durable attempt to walk an approved chain
-- for one task. The STATE MACHINE (design C7) lives here; every move is a
-- fenced CAS proving the exact from-state. transition_generation is
-- monotonic — a stale writer cannot re-move a state it already left.
CREATE TABLE IF NOT EXISTS fallback_cycle (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  -- The approved chain this cycle walks; the cycle is void if the approval
  -- moves (the CAS re-proves it).
  chain_digest  TEXT NOT NULL,
  cursor        INTEGER NOT NULL DEFAULT 0,
  state         TEXT NOT NULL CHECK (state IN ('open','sanitizing','awaiting-release','pending-admission','incident','closed')),
  transition_generation INTEGER NOT NULL DEFAULT 0,
  -- The current tail run (the entry running, or the predecessor being
  -- sanitized). NULL only transiently at pending-admission before the next
  -- run opens.
  tail_run      INTEGER REFERENCES run(id),
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  closed_reason TEXT
);

-- One immutable fallback TRANSITION (v30): the audit + the single-use
-- authority for the next entry. Inserted inside advanceFallbackFenced /
-- quota-skip; consumed once at admission. Uniqueness on (cycle, from_index)
-- makes a transition one-per-step; consumed_by makes the authority one-shot.
CREATE TABLE IF NOT EXISTS fallback_transition (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  cycle         INTEGER NOT NULL REFERENCES fallback_cycle(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL CHECK (kind IN ('exhaustion','quota-skip')),
  from_index    INTEGER NOT NULL,
  to_index      INTEGER NOT NULL,
  -- The predecessor run whose exhaustion (or whose skip evidence) earned
  -- this step; NULL for a fresh cycle's index-0 (there is no transition
  -- into index 0 — a cycle starts there).
  predecessor_run INTEGER REFERENCES run(id),
  -- The gateway-stamped terminal class + proven evidence identity that
  -- authorized an 'exhaustion' step (NULL for quota-skip, which cites
  -- durable quota evidence instead).
  terminal_class  TEXT,
  evidence_provider TEXT,
  evidence_version  TEXT,
  evidence_auth_mode TEXT,
  evidence_fp     TEXT,
  created_at    TEXT NOT NULL,
  -- The run that consumed this transition's authority (single-use). NULL
  -- until admission; set once, in the same txn that opens the next run.
  consumed_by   INTEGER REFERENCES run(id)
);

-- One watch, as an episode with edges (§6): the night is a row, not "the
-- last 24 hours", so the morning briefing can bound itself to exactly what
-- one watch did — runs and publications attribute by runner and window.
-- ended_at NULL means it is still running, or died and never said. v5.
CREATE TABLE IF NOT EXISTS watch_episode (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  repo        TEXT NOT NULL,
  runner      TEXT NOT NULL,
  incarnation TEXT NOT NULL UNIQUE,
  started_at  TEXT NOT NULL,
  ended_at    TEXT,
  ticks       INTEGER NOT NULL DEFAULT 0,
  built       INTEGER NOT NULL DEFAULT 0,
  broke       INTEGER NOT NULL DEFAULT 0
);

-- A project the console has opened: identity is the canonical repo path.
-- Registry only — a row here NEVER authorizes access (the ceiling is server
-- configuration); it remembers names and recency for the opener page. v6.
CREATE TABLE IF NOT EXISTS project (
  path           TEXT PRIMARY KEY,
  name           TEXT NOT NULL,
  added_at       TEXT NOT NULL,
  last_opened_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS project_recent ON project (last_opened_at);

-- Standing permission to publish built work: git push and PR creation are
-- two different external writes, so they are two named capabilities under
-- one grant whose every term — exact GitHub repository, remote, allowed
-- head prefix, base branch — was shown to the approver before the yes.
-- Absence is denial; revocation is immediate. v5.
CREATE TABLE IF NOT EXISTS publication_grant (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  repo         TEXT NOT NULL,
  github_repo  TEXT NOT NULL,
  remote       TEXT NOT NULL,
  head_prefix  TEXT NOT NULL,
  base         TEXT NOT NULL,
  capabilities TEXT NOT NULL,
  selector     TEXT NOT NULL CHECK (selector IN ('ours','all')),
  draft        INTEGER NOT NULL DEFAULT 1,
  granted_by   TEXT NOT NULL,
  granted_at   TEXT NOT NULL,
  revoked_by   TEXT,
  revoked_at   TEXT
);

-- One live grant per repo: proposing again replaces, revoking ends it.
CREATE UNIQUE INDEX IF NOT EXISTS publication_grant_live
  ON publication_grant (repo) WHERE revoked_at IS NULL;

-- The durable publication intent (§M4): completion and "this must reach a
-- PR" are one fenced write, and everything the worker needs afterwards —
-- the exact SHA to push, the exact refs, the body's identity — lives here,
-- so every phase is retryable after a crash and a retry can adopt the PR
-- it already opened instead of minting a twin. v5.
CREATE TABLE IF NOT EXISTS publication (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  run         INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
  task_ref    INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  github_repo TEXT NOT NULL,
  remote      TEXT NOT NULL,
  base        TEXT NOT NULL,
  head        TEXT NOT NULL,
  head_sha    TEXT NOT NULL,
  body_hash   TEXT NOT NULL,
  draft       INTEGER NOT NULL,
  state       TEXT NOT NULL CHECK (state IN ('intended','pushed','opened','failed')),
  pr_number   INTEGER,
  pr_url      TEXT,
  attempts    INTEGER NOT NULL DEFAULT 0,
  last_error  TEXT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  -- The remote's own verdict, observed (M8 audit C-6): MERGED/CLOSED ends
  -- the watch without widening the local state CHECK.
  remote_state TEXT,
  -- What CI was last SEEN doing, and when (audit SD-4): the review queue
  -- ranks observed-passing first and never upgrades silence to green.
  last_check_state TEXT,
  last_check_at    TEXT
);

-- A machine that may be given work.
--
-- credential_hash, never the credential: the token is shown to the operator
-- once at registration and then exists only as a hash here. A control plane
-- that can hand back a runner's token is one whose database is worth stealing.
CREATE TABLE IF NOT EXISTS runner (
  name            TEXT PRIMARY KEY,
  host            TEXT NOT NULL,
  credential_hash TEXT NOT NULL,
  capacity        INTEGER NOT NULL,
  -- What capacity bounds (v14, finding 26): 'tasks' is the original
  -- contract (live claims) and stays the default; 'processes' counts
  -- worker processes via execution_slot and is an explicit opt-in —
  -- an upgrade never silently changes what an operator's number means.
  capacity_mode   TEXT NOT NULL DEFAULT 'tasks' CHECK (capacity_mode IN ('tasks','processes')),
  repos           TEXT NOT NULL DEFAULT '[]',
  agents          TEXT NOT NULL DEFAULT '[]',
  registered_at   TEXT NOT NULL,
  heartbeat_at    TEXT NOT NULL,
  retired_at      TEXT,
  -- The queue column's theme note (v19) — operator prose, display only.
  queue_note      TEXT
);

-- A checked-out working copy, leased to one runner at a time.
--
-- Its lease is deliberately the same shape as a task claim: a runner that dies
-- holding a worktree has to be recoverable the same way, and two mechanisms
-- for one idea is how the second one ends up subtly wrong.
CREATE TABLE IF NOT EXISTS worktree (
  path          TEXT PRIMARY KEY,
  repo          TEXT NOT NULL,
  branch        TEXT NOT NULL,
  runner        TEXT REFERENCES runner(name) ON DELETE SET NULL,
  task_ref      INTEGER REFERENCES task_ref(id) ON DELETE SET NULL,
  created_at    TEXT NOT NULL,
  leased_at     TEXT,
  released_at   TEXT,
  -- Reconstructed state is trusted only after it has been checked; see
  -- treehouse's rule about state you did not watch being created.
  verified      INTEGER NOT NULL DEFAULT 0,
  -- Per-occupancy epoch (live-peek findings 16/28): a fresh random value
  -- written ATOMICALLY with every lease and rotated on release, so it can
  -- never repeat across release/forget/adopt/recreation. An observation
  -- proved against one epoch is DISCARDED if the epoch moved before it
  -- rendered — the fence that keeps a successor occupant's files out of a
  -- predecessor's page.
  lease_epoch   TEXT,
  -- The approved setup this checkout last ran to completion (M5.7):
  -- matching the live setup's digest is the cache hit; anything else runs
  -- it again before an agent may spawn here.
  setup_digest  TEXT
);

-- The per-repo worktree setup (M5.7): the command every fresh checkout runs
-- before any agent spawns in it — dependencies, .env copies, generated
-- code. Digest-bound and operator-approved like every other authority: the
-- command TEXT is stored, secret VALUES never are. One live row per repo;
-- clearing revokes rather than deletes, because who approved what remains
-- a fact.
CREATE TABLE IF NOT EXISTS worktree_setup (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  repo        TEXT NOT NULL,
  command     TEXT NOT NULL,
  timeout_ms  INTEGER NOT NULL,
  digest      TEXT NOT NULL,
  approved_by TEXT NOT NULL,
  approved_at TEXT NOT NULL,
  revoked_at  TEXT,
  revoked_by  TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS worktree_setup_live
  ON worktree_setup (repo) WHERE revoked_at IS NULL;

-- The per-repo verification command (Priority 2): the ONE shell command the
-- plane re-runs, unattended, in a leased worktree after a build commits —
-- operator-approved and digest-bound like worktree_setup, its own table
-- rather than a second column on it: setup prepares a checkout, this
-- checks a finished one, and revocation histories must not entangle.
CREATE TABLE IF NOT EXISTS verify_command (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  repo        TEXT NOT NULL,
  command     TEXT NOT NULL,
  timeout_ms  INTEGER NOT NULL,
  digest      TEXT NOT NULL,
  -- v45: opt-in authority for exactly one post-commit replay of this
  -- setup digest when the verification command cannot start because a
  -- required project executable is unavailable. NULL preserves every older grant.
  recovery_setup_digest TEXT,
  approved_by TEXT NOT NULL,
  approved_at TEXT NOT NULL,
  revoked_at  TEXT,
  revoked_by  TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS verify_command_live
  ON verify_command (repo) WHERE revoked_at IS NULL;

-- The proof verdict (Priority 2): the machine-authored judgement, computed
-- once at completion by adjudicate() and never re-inferred at render — a
-- table keyed by run, not a run column, so widening it never touches
-- run's own exact recognizers.
CREATE TABLE IF NOT EXISTS proof_verdict (
  run         INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  verdict     TEXT NOT NULL CHECK (verdict IN ('verified','attested','short','refuted')),
  reasons_json TEXT NOT NULL,
  decided_at  TEXT NOT NULL,
  -- v39: the criterion-to-evidence matrix adjudicate() computed alongside
  -- the verdict -- one shared render, never re-derived. NULL for every
  -- verdict decided before this migration, and for any run whose scope
  -- signed no rubric (adjudicate returns [] and this column stores NULL,
  -- not "[]", so a surface can tell "no matrix" from "an empty one" --
  -- not that the two currently read any differently).
  matrix_json TEXT,
  -- v40 (evidence-review-v1): the verdict adjudicate() computed, BEFORE an
  -- independent reviewer's judgements were folded in — NULL means "no
  -- review folded", reading back exactly as today. Never overwritten once
  -- set: one SUCCESSFUL review per source run, ever (v50's
  -- one_successful_root_review_per_source), so this is written at most
  -- once, by the same transaction that folds it.
  machine_verdict TEXT CHECK (machine_verdict IS NULL OR machine_verdict IN ('verified','attested','short','refuted'))
);

-- The independent evidence reviewer's per-criterion judgement (v40,
-- evidence-review-v1): bound to the exact reviewed bytes — the sealed diff
-- artifact and its hash, exactly like diff_comment — and immutable. One
-- reviewer run may judge many criteria; parseReview refuses a payload that
-- names the same id twice before this table ever sees it.
CREATE TABLE IF NOT EXISTS criterion_review (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  reviewer_run  INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  source_run    INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  criterion_id  TEXT NOT NULL,
  judgement     TEXT NOT NULL CHECK (judgement IN ('upholds','contradicts','cannot-tell')),
  note          TEXT NOT NULL,
  artifact      INTEGER NOT NULL REFERENCES artifact(id) ON DELETE CASCADE,
  artifact_sha  TEXT NOT NULL,
  author        TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  -- Audit hardening (still evidence-review-v1, unreleased): every input the
  -- reviewer was actually shown, hash-bound and RE-VALIDATED against the
  -- live store at ingest time by ingestReview() -- never trusted from the
  -- caller's say-so. NULL exactly when that input never existed for this
  -- run (no verify command configured, no screenshots claimed): an
  -- omission, recorded as one, never confused with a mismatch.
  scope_digest       TEXT,
  head_sha           TEXT,
  proof_artifact     INTEGER,
  proof_sha          TEXT,
  check_log_artifact INTEGER,
  check_log_sha      TEXT,
  screenshots_json   TEXT NOT NULL DEFAULT '[]',
  -- v51 (inherited review context): the sealed context inventory the
  -- reviewer was shown, hash-bound and re-validated at ingest exactly like
  -- the proof. NULL exactly when the run captured no inventory (every run
  -- that is not a revision, and every run before v51).
  context_artifact   INTEGER,
  context_sha        TEXT
);

-- The bounded repair loop's ledger (v40, evidence-review-v1): one row per
-- ATTEMPT, chained by root_task (the ORIGINAL task a chain repairs, never
-- a mid-chain draft) and bound one-to-one to the source run it was drafted
-- from. The single inbox item and the run/task pages read this ledger,
-- never re-derive it. outcome starts 'drafted' and settles exactly once.
-- draft_task is NULL exactly for the one edge case a draft is never made
-- at all: the FIRST attempt in a chain refused outright by the integrity
-- stop (no prior attempt exists to settle instead). Every other stop
-- (attempts-spent, no-progress) settles an EXISTING drafted row.
CREATE TABLE IF NOT EXISTS repair_chain (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  root_task       TEXT NOT NULL,
  source_run      INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
  attempt         INTEGER NOT NULL,
  draft_task      TEXT,
  basis           TEXT NOT NULL CHECK (basis IN ('human','mode')),
  mode_digest     TEXT,
  unresolved_json TEXT NOT NULL,
  outcome         TEXT NOT NULL DEFAULT 'drafted'
                    CHECK (outcome IN ('drafted','attempts-spent','no-progress','integrity-refused','resolved')),
  created_at      TEXT NOT NULL,
  settled_at      TEXT
);
CREATE INDEX IF NOT EXISTS repair_chain_root ON repair_chain (root_task, attempt);

-- An operator's explicit acceptance of a short/refuted verdict (Priority
-- 2): the one act that lets a task read "done" despite incomplete proof.
-- Recorded, never inferred — accepting is a person's act, like approving a
-- scope.
CREATE TABLE IF NOT EXISTS proof_acceptance (
  run         INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  approver    TEXT NOT NULL,
  note        TEXT,
  accepted_at TEXT NOT NULL
);

-- An operator's note on a run (M6): immutable, bounded, append-only — the
-- human's verdict next to the machine's record. Never a mutation of the
-- run itself; runs and evidence are audit history.
CREATE TABLE IF NOT EXISTS run_note (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  run        INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  author     TEXT NOT NULL,
  note       TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- The intake grant (M8.16): permission to turn labeled GitHub issues into
-- LOCAL UNAPPROVED task proposals — and nothing else. Detection is not
-- authorization; a grant names the exact repository, the exact label, and
-- (for PR-comment intake) which reviewer logins may steer. No mutation of
-- the remote in v1: reads make proposals, people approve them.
CREATE TABLE IF NOT EXISTS intake_grant (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  repo        TEXT NOT NULL,
  github      TEXT NOT NULL,
  label       TEXT NOT NULL,
  reviewers   TEXT,
  approved_by TEXT NOT NULL,
  approved_at TEXT NOT NULL,
  revoked_at  TEXT,
  revoked_by  TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS intake_grant_live
  ON intake_grant (repo) WHERE revoked_at IS NULL;

-- A review comment on an IMMUTABLE terminal diff (M6.8). Bound to the exact
-- artifact and its hash — a comment on bytes that can never change — plus
-- the file and line it speaks to. Immutable themselves: an edit supersedes,
-- and consumption by a revision task is recorded, never deletion.
CREATE TABLE IF NOT EXISTS diff_comment (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  artifact      INTEGER NOT NULL REFERENCES artifact(id) ON DELETE CASCADE,
  artifact_sha  TEXT NOT NULL,
  run           INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  path          TEXT,
  line          INTEGER,
  note          TEXT NOT NULL,
  author        TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  superseded_by INTEGER REFERENCES diff_comment(id),
  consumed_by   TEXT,
  -- Where an ingested comment came from (M8.17): gh:<owner/name>:<id>.
  -- The GitHub comment id is the idempotency key — one ingest, ever.
  -- Its unique index is created AFTER migration (see openStore): a
  -- database whose diff_comment predates the column would die on an
  -- index statement inside this schema block before addColumn could run.
  source_key    TEXT
);

-- A standing ask for an agent review of one finished run's sealed diff
-- (v29, the reviewer role). Manual (task review) and automatic (a mode
-- whose terms say reviewAuto) requests land here identically; the tick's
-- review pass consumes them. One OPEN request per run (index after
-- migration). v50 (bounded review retries): a run gains at most
-- REVIEW_ROOT_ATTEMPTS root reviewer children — the first ask plus at most
-- two EXPLICIT retries after a failed or interrupted attempt — never a
-- second one while one is live or once one succeeded. Review stays
-- additive, never a loop: nothing here ever retries by itself.
CREATE TABLE IF NOT EXISTS review_request (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  run             INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  -- Who asked, as words for the page. AUTHORITY lives in basis/mode_digest
  -- below, never in this string (Codex reviewer round 1, finding 4: an
  -- operator who NAMES themselves 'mode:…' must not be misclassified).
  requested_by    TEXT NOT NULL,
  -- 'human' = an operator's credentialed ask, always dispatchable.
  -- 'mode' = a reviewAuto mode queued it; dispatch re-proves the EXACT
  -- digest below is still the active mode — a renewal is a new signature
  -- and does not inherit its predecessor's queued asks.
  basis           TEXT NOT NULL DEFAULT 'human' CHECK (basis IN ('human','mode')),
  mode_digest     TEXT,
  -- v47: the approved route digest the request was queued under. Admission
  -- re-proves the task's sealed route still carries it — a re-approved
  -- task with a different route spends the request unrun, in words.
  route_digest    TEXT,
  requested_at    TEXT NOT NULL,
  consumed_at     TEXT,
  consumed_reason TEXT,
  -- v50: the ROOT reviewer run this request was spent on — written by the
  -- very admission that consumed it, so a request and its attempt are one
  -- durable fact. NULL on a request spent without a run (route-changed,
  -- mode-ended, already-reviewed, …) and on any v49 row the migration
  -- could not bind to exactly one root.
  reviewer_run    INTEGER REFERENCES run(id),
  -- v50 (explicit-only retries): how the ask was PRODUCED, apart from
  -- whose authority it carries. 'operator' = a fresh credentialed act
  -- (task review, the Retry review button). 'automatic' = a build
  -- disposition's producer (a reviewAuto mode, a Strict / release scope)
  -- — one-shot per source run: it queues the first attempt only, and a
  -- replayed disposition (crash recovery, a re-dispose) can neither queue
  -- nor admit a retry. Request and admission both refuse on it BEFORE
  -- any rail or run exists; a mode-basis row is automatic whatever this
  -- column says.
  origin          TEXT NOT NULL DEFAULT 'operator' CHECK (origin IN ('operator','automatic'))
);

-- Operator steering (arc 1, v22): a note that lands at the next safe
-- boundary — the next brief the builder composes for this task. Attachment
-- and delivery are SEPARATE facts: attached_at says which build the note
-- rode toward; delivered_at settles only on the stream's own receipt (the
-- agent's first words, or a successful completion). At-least-once, honestly
-- labeled. Superseded means the task ended with the note still pending.
CREATE TABLE IF NOT EXISTS task_steer (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  author        TEXT NOT NULL,
  note          TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  attached_run  INTEGER REFERENCES run(id),
  attached_at   TEXT,
  delivered_at  TEXT,
  superseded_at TEXT,
  -- v24 (ruling 11): authorship is a VERIFIED principal or it is history.
  -- The default is the legacy label so any road that forgets to say
  -- otherwise fails closed into "unverified".
  authorship_state  TEXT NOT NULL DEFAULT 'unverified-legacy' CHECK (authorship_state IN ('verified','unverified-legacy')),
  superseded_reason TEXT,
  CHECK ((attached_run IS NULL) = (attached_at IS NULL)),
  CHECK (delivered_at IS NULL OR attached_run IS NOT NULL)
);

-- Adaptive execution plans (v44): an append-only ledger of plan revisions.
-- Revision 1 for a task filed before this migration is never backfilled
-- here — it stays a read-only projection off the existing planner artifact,
-- so an old task with zero rows in this table is still exactly as readable
-- as one with a hundred. 'artifact' carries the complete replacement plan
-- document (kind 'plan', same shape the planner itself writes);
-- 'parent_hash' is the prior revision's artifact sha256, so a reader can
-- walk the chain without a second query per hop. 'authority_digest' is the
-- signed-scope-plus-publication-authority digest at filing time — the
-- complete thing an approval could invalidate. 'status' is the one mutable
-- field: 'blocked' becomes 'applied' or 'rejected' by an operator's act;
-- the content columns beside it never change once written.
CREATE TABLE IF NOT EXISTS plan_revision (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref         INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  revision         INTEGER NOT NULL,
  artifact         INTEGER NOT NULL REFERENCES artifact(id),
  parent_hash      TEXT,
  reason           TEXT NOT NULL,
  evidence_link    TEXT,
  author           TEXT NOT NULL,
  origin_run       INTEGER REFERENCES run(id),
  kind             TEXT NOT NULL CHECK (kind IN ('initial', 'operator-edit', 'builder-proposal')),
  authority_kind   TEXT NOT NULL CHECK (authority_kind IN ('plan-only', 'authority-change')),
  authority_digest TEXT NOT NULL,
  changed_fields   TEXT,
  status           TEXT NOT NULL CHECK (status IN ('applied', 'blocked', 'rejected')),
  created_at       TEXT NOT NULL,
  resolved_at      TEXT,
  resolved_by      TEXT,
  UNIQUE (task_ref, revision)
);

-- The running build's milestone checkpoints (v44): append-only, one row per
-- atomic snapshot a build reported. 'plan_revision' is the exact revision
-- this snapshot's ids were validated against (run.plan_revision names the
-- same value at the run level; both are kept so a checkpoint remains
-- self-describing after the run row is long gone from a query's join). The
-- newest row per run is that run's current progress; earlier rows are the
-- history a reader can show without a second table.
CREATE TABLE IF NOT EXISTS run_checkpoint (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  run           INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  plan_revision INTEGER NOT NULL REFERENCES plan_revision(id),
  snapshot_json TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

-- A phone enrolled for web push (arc 3, v23). One row PER ACTIVATION —
-- re-enrolling a retired endpoint is a new row with its own binding and
-- audit trail; the partial unique index below keeps one LIVE row per
-- endpoint. starts_after_notification is the transactional high-water
-- mark: only notifications newer than the enrollment are ever paged.
CREATE TABLE IF NOT EXISTS push_subscription (
  id                        INTEGER PRIMARY KEY AUTOINCREMENT,
  endpoint                  TEXT NOT NULL,
  p256dh                    TEXT NOT NULL,
  auth                      TEXT NOT NULL,
  approver                  TEXT NOT NULL,
  approver_generation       INTEGER NOT NULL,
  ua_words                  TEXT NOT NULL,
  vapid_fingerprint         TEXT NOT NULL,
  starts_after_notification INTEGER NOT NULL,
  created_at                TEXT NOT NULL,
  last_ok_at                TEXT,
  consecutive_failures      INTEGER NOT NULL DEFAULT 0,
  retired_at                TEXT,
  retired_reason            TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS push_subscription_live
  ON push_subscription (endpoint) WHERE retired_at IS NULL;

-- One (notification, subscription) delivery pair (arc 3): push's OWN
-- ledger — the outbox's delivered_at/claim columns are never consulted
-- and never written, so push stays additive to every other channel.
-- 'accepted' means the PUSH SERVICE took it (RFC 8030); nothing here
-- claims a phone displayed anything. At-least-once: a crash between
-- acceptance and settlement re-sends after the lease expires.
CREATE TABLE IF NOT EXISTS push_delivery (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  notification     INTEGER NOT NULL REFERENCES notification(id) ON DELETE CASCADE,
  subscription     INTEGER NOT NULL REFERENCES push_subscription(id) ON DELETE CASCADE,
  state            TEXT NOT NULL DEFAULT 'pending'
                     CHECK (state IN ('pending','claimed','accepted','rejected','undeliverable','retired')),
  claim_owner      TEXT,
  claim_expires_at TEXT,
  claim_generation INTEGER NOT NULL DEFAULT 0,
  attempts         INTEGER NOT NULL DEFAULT 0,
  next_attempt_at  TEXT,
  last_error       TEXT,
  created_at       TEXT NOT NULL,
  accepted_at      TEXT,
  UNIQUE (notification, subscription),
  CHECK (state <> 'claimed' OR (claim_owner IS NOT NULL AND claim_expires_at IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS push_delivery_due
  ON push_delivery (state, next_attempt_at) WHERE state IN ('pending','claimed');

CREATE TABLE IF NOT EXISTS mutation (
  idempotency_key TEXT PRIMARY KEY,
  operation       TEXT NOT NULL,
  result          TEXT NOT NULL,
  actor           TEXT NOT NULL,
  created_at      TEXT NOT NULL
);

-- The attended authorization (v25, Parity II Phase 2 ruling 12): one person,
-- one password, signing EVERY rendered term of one watched attempt — repo,
-- task, runner + its generation, scope digest, execution profile, budget as
-- a STOP THRESHOLD (the agent halts when its total crosses it; the final
-- step may run a little past), a per-session turn cap, per-turn clock, the
-- exact head it builds from, and an absolute expiry. The id is a pre-minted
-- UUID: it IS the attempt identity the dispatch proof consumes. "Live" is a
-- liveness.ts computation over last_beat_at/absolute_expiry — never an
-- index predicate. A CONSUMED authorization (attempt_run set) stays OPEN
-- across its held session; closure is explicit (run end, expiry,
-- revocation), and minting closes an expired predecessor transactionally.
CREATE TABLE IF NOT EXISTS attended_authorization (
  id                TEXT PRIMARY KEY,
  task_ref          INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  approver          TEXT NOT NULL,
  runner            TEXT NOT NULL,
  runner_generation INTEGER NOT NULL,
  composite_digest  TEXT NOT NULL,
  terms_json        TEXT NOT NULL,
  max_session_turns INTEGER NOT NULL,
  budget_microusd   INTEGER NOT NULL,
  -- Continuation (A4): the finished parent attempt this authorization
  -- continues, and the follow-up text — BOTH also inside the signed
  -- terms_json; these columns exist so admission can join without parsing.
  parent_run        INTEGER REFERENCES run(id),
  followup          TEXT,
  created_at        TEXT NOT NULL,
  absolute_expiry   TEXT NOT NULL,
  last_beat_at      TEXT,
  attempt_run       INTEGER UNIQUE REFERENCES run(id),
  consumed_at       TEXT,
  closed_at         TEXT,
  end_reason        TEXT
);

-- The turn ledger (v25, ruling 15): every stdin injection into a held
-- session is a row — the initial brief, every decision answer, every
-- operator turn, every machine repair turn. Recorded DURABLY before any
-- write; the recording transaction is where the turn cap, the single-flight
-- rule, the budget reservation, and the lease re-proof all gate. The
-- input-acceptance boundary (spike fact 5): stdin-write success is NOT
-- acceptance — acceptance is THIS turn's system/init (or its result,
-- retroactively). A written turn whose acceptance never arrives settles
-- terminal 'uncertain': charged at its reservation, NEVER reinjected.
-- measured_microusd is the MARGINAL delta from held_session's durable
-- cumulative baseline (the provider's totals are cumulative per process).
CREATE TABLE IF NOT EXISTS session_turn (
  id                 INTEGER PRIMARY KEY AUTOINCREMENT,
  run                INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  seq                INTEGER NOT NULL,
  source_kind        TEXT NOT NULL CHECK (source_kind IN ('brief','answer','operator','repair')),
  source_id          INTEGER,
  -- Verified operator name for source_kind 'operator' ONLY; brief and
  -- repair turns are machine-authored and say so with NULL.
  author             TEXT,
  text               TEXT NOT NULL,
  reserved_microusd  INTEGER NOT NULL,
  accounted_microusd INTEGER,
  accounted_at       TEXT,
  recorded_at        TEXT NOT NULL,
  written_at         TEXT,
  accepted_at        TEXT,
  settled_at         TEXT,
  measured_microusd  INTEGER,
  output_tokens      INTEGER,
  state              TEXT NOT NULL DEFAULT 'recorded'
                       CHECK (state IN ('recorded','written','accepted','settled','uncertain','cancelled')),
  UNIQUE (run, seq)
);

-- Crash custody for held sessions (v25, ruling 15): written as a custody
-- INTENT in the same transaction as the dispatch proof, stamped with the
-- supervisor pid + agent process group immediately after spawn. The orphan
-- predicate is LEASE-BASED (the recorded lease is no longer the task's
-- current live lease) — never mere incarnation difference, because two live
-- up processes may share this database. 'fencing' is a helpable, leased
-- state: a fencer that dies is taken over at its deadline, and every step
-- is CAS-protected so a loser stops only while a live fencer owns the work.
CREATE TABLE IF NOT EXISTS held_session (
  run                   INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  authorization_id      TEXT NOT NULL REFERENCES attended_authorization(id),
  runner                TEXT NOT NULL,
  lease_id              TEXT NOT NULL,
  up_incarnation        TEXT NOT NULL,
  cookie                TEXT NOT NULL,
  socket_path           TEXT NOT NULL,
  supervisor_pid        INTEGER,
  agent_pgid            INTEGER,
  cumulative_microusd   INTEGER NOT NULL DEFAULT 0,
  cumulative_tokens_out INTEGER NOT NULL DEFAULT 0,
  state                 TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open','fencing')),
  fencer                TEXT,
  fencing_deadline      TEXT,
  started_at            TEXT NOT NULL,
  ended_at              TEXT,
  end_reason            TEXT
);

-- v52 (safe task stop and resume): an operator's stop, bound to ONE exact
-- attempt. The row is durable BEFORE any process is signalled, so a crash
-- between the request and the kill still settles as a stop, never as a
-- success. settled_at lands only once the attempt's owned processes are
-- established gone — the worker's own fenced interruption seal, the held
-- supervisor's fence, or dead-incarnation recovery — and the successor a
-- resume admits is never named here: it inherits the draft through the
-- ordinary recovered-draft road with a fresh lease. Repair turns and
-- reviewer corrections inherit their parent's stop by sharing its lease;
-- a later independently admitted attempt does not. One stop per run:
-- a repeated request is the same request, never a second one.
CREATE TABLE IF NOT EXISTS run_stop (
  run           INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  requested_by  TEXT NOT NULL,
  requested_via TEXT NOT NULL CHECK (requested_via IN ('cli','web','telegram')),
  requested_at  TEXT NOT NULL,
  settled_at    TEXT,
  settlement    TEXT CHECK (settlement IN ('interrupted','recovered','held','finished')),
  resumed_at    TEXT,
  resumed_by    TEXT,
  resumed_via   TEXT CHECK (resumed_via IN ('cli','web','telegram')),
  CHECK ((settled_at IS NULL) = (settlement IS NULL)),
  CHECK (resumed_at IS NULL OR settled_at IS NOT NULL),
  CHECK ((resumed_at IS NULL) = (resumed_by IS NULL))
);

-- Retained spawn witnesses also cover reviewers and setup/check children,
-- which need not have an execution slot or a persistent worktree marker.
-- PIDs are only queried for liveness; they never authorize a signal.
-- v53 (OS containment and login recovery): each witness also carries the
-- OS boot it was born under (boot_id — a verified boot change on the same
-- host proves the process gone; NULL keeps the conservative road), and the
-- native OS object the spawn ran inside (containment = the backend,
-- container = the cgroup directory or job name, container_empty_at = when
-- the OS proved it empty). A native witness with no empty proof keeps every
-- stop/resume fence closed until the object can be proven empty.
CREATE TABLE IF NOT EXISTS run_process (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  run INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  pid INTEGER CHECK (pid > 0),
  host TEXT NOT NULL,
  process_group INTEGER NOT NULL CHECK (process_group IN (0,1)),
  observed_at TEXT NOT NULL,
  exited_at TEXT,
  boot_id TEXT,
  containment TEXT,
  container TEXT,
  container_empty_at TEXT,
  container_identity TEXT
);
CREATE INDEX IF NOT EXISTS run_process_by_run ON run_process(run, exited_at);

CREATE INDEX IF NOT EXISTS task_by_state ON task (state);
CREATE INDEX IF NOT EXISTS edge_by_blocker ON task_edge (blocker);
CREATE INDEX IF NOT EXISTS claim_by_task ON claim (task_ref, lease_generation DESC);
CREATE INDEX IF NOT EXISTS hold_by_task ON hold (task_ref);
CREATE INDEX IF NOT EXISTS run_stop_by_task ON run_stop (task_ref, requested_at DESC);
`;

/**
 * The subset of `node:sqlite` this module uses, named so the rest of the file
 * is not written against an `any` and so a test can substitute a handle.
 */
export type Statement = {
  run(...params: unknown[]): { changes: number | bigint; lastInsertRowid?: number | bigint };
  get(...params: unknown[]): Record<string, unknown> | undefined;
  all(...params: unknown[]): Record<string, unknown>[];
};

export type Database = {
  exec(sql: string): void;
  prepare(sql: string): Statement;
  close(): void;
};

/**
 * Beside `repos.json`, for the same reason it is there: someone will want to
 * back it up, sync it, or delete it, and a database hidden somewhere clever is
 * a database nobody can find when it matters.
 */
export function databasePath(env: Record<string, string | undefined>, home: string): string {
  // Provider children receive a unique path through this variable. Keeping
  // the override database-specific avoids changing XDG_CONFIG_HOME for every
  // other tool an agent may need while ensuring a self-hosting task cannot
  // migrate or lock the control plane that launched it.
  const isolated = envValue(env, "DB");
  if (isolated !== undefined && isolated !== "") return isolated;
  // Each rename (nightorders → standing-orders, 2026-08-13; → toolroll,
  // 2026-09-29) must not orphan an installation: a database that already
  // lives under an older name keeps being found there until one exists
  // under the new one. A fresh install gets ~/.config/toolroll.
  return namedPath(configBase(env, home), ["orders.db"]);
}

export type OpenOptions = {
  /** Substituted in tests; production opens node:sqlite itself. */
  connect?: (file: string) => Database;
};

/** Every connection's wait at SQLite's lock boundary, in milliseconds. */
export const CONCURRENT_WRITER_WAIT_MS = 15_000;

/** A brief competing CLI/worker write queues at SQLite's lock boundary.
 * This is per connection, including non-migrating desktop/MCP connections.
 * It does not replay a transaction body or conceal a persistent lock. */
function waitForConcurrentWriter(db: Database): void {
  db.exec(`PRAGMA busy_timeout = ${CONCURRENT_WRITER_WAIT_MS}`);
}

/** How long one BEGIN IMMEDIATE attempt in beginWriteWithin sits in
 * SQLite's busy handler before the clock is consulted — nominal ms, so
 * brief contention still queues inside SQLite without a round trip. */
const WRITE_WAIT_SLICE_MS = 100;

/** SQLITE_BUSY in its primary or any extended form (node:sqlite reports
 * the extended code as `errcode`; the low byte is the primary code). */
export function isDatabaseBusy(error: unknown): boolean {
  const code = (error as { errcode?: unknown } | null)?.errcode;
  return typeof code === "number" && (code & 0xff) === 5;
}

/**
 * BEGIN IMMEDIATE with its wait charged by the monotonic clock, not by
 * SQLite's busy handler alone.
 *
 * The busy handler sleeps in steps (1, 2, 5 … 100 ms) and gives up when the
 * sleep it ASKED for adds up to busy_timeout — it never reads a clock. In
 * the process tree where builds 1540/1541 ran (a launchd job that sets no
 * ProcessType; measurements in docs/assessments/WORKSPACE_0_RESULT_2026-09-13.md)
 * each of those sleeps was observed stretched by up to ~100 ms, so five
 * nominal seconds took ~12 real ones and a persistent lock overran the
 * ten-second test bound. Here each attempt spends one short slice in
 * SQLite and the budget is accounted in elapsed performance.now() time:
 * the loop stops retrying once the budget has elapsed, so the refusal
 * lands within the budget plus the ACTUAL latency of one attempt. That is
 * elapsed-time accounting, not a hard deadline — one attempt is a blocking
 * SQLite call, and if the OS suspends or stretches it (sleep, heavy
 * throttling) the refusal can arrive later than budget + one nominal slice.
 * Only the BEGIN itself is retried: a body never runs before its
 * connection holds the write lock, so nothing is partially written or
 * replayed. The connection's own busy_timeout is restored whichever way
 * the loop ends.
 *
 * Coverage: only Store.transact begins its write through this door.
 * Autocommit statements and the other BEGIN IMMEDIATEs in this file
 * (migrate and the per-version table rebuilds) keep the plain busy_timeout
 * wait, which is still counted in nominal sleep.
 */
function beginWriteWithin(db: Database, budgetMs: number): void {
  const deadline = performance.now() + budgetMs;
  db.exec(`PRAGMA busy_timeout = ${WRITE_WAIT_SLICE_MS}`);
  try {
    for (;;) {
      try {
        db.exec("BEGIN IMMEDIATE");
        return;
      } catch (error) {
        if (!isDatabaseBusy(error) || performance.now() >= deadline) throw error;
      }
    }
  } finally {
    waitForConcurrentWriter(db);
  }
}

/**
 * Open the database, creating it and its directory if needed. The import is
 * inside the function rather than at the top of the file so that a command
 * which never touches the store — every command that exists today — neither
 * loads SQLite nor pays its warning.
 */
export function openStore(file: string, options: OpenOptions = {}): Store {
  const connect = options.connect ?? defaultConnect;
  // The database's directory is 0700 from birth (round-2 finding 5 — the
  // DESIGN.md threat boundary is a claim only if the modes are real).
  if (file !== ":memory:") mkdirSync(dirname(file), { recursive: true, mode: 0o700 });

  const db = connect(file);
  try {
    waitForConcurrentWriter(db);
    return initializeStore(db, file);
  } catch (error) {
    // An unsuccessful open must not retain an unfinished migration's lock
    // for the lifetime of a long-running caller.
    try { db.close(); } catch { /* Preserve the original opening failure. */ }
    throw error;
  }
}

/** v71: shared lead identity and admission. Existing mate history remains private. */
export const TEAM_TABLES = ["team_lead", "team_lead_project", "team_lead_member", "team_conversation", "team_participant", "team_message", "team_read", "team_follow", "team_mate_session", "team_task_owner", "team_event", "team_request"] as const;
const TEAM_SCHEMA = `
CREATE TABLE IF NOT EXISTS team_lead (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, instructions TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
 status TEXT NOT NULL CHECK(status IN ('active','paused')), created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS team_lead_project (
 lead TEXT NOT NULL REFERENCES team_lead(id), project TEXT NOT NULL, PRIMARY KEY(lead,project)
);
CREATE TABLE IF NOT EXISTS team_lead_member (
 lead TEXT NOT NULL REFERENCES team_lead(id), account TEXT NOT NULL REFERENCES approver(name),
 role TEXT NOT NULL CHECK(role IN ('viewer','contributor','manager')), active INTEGER NOT NULL DEFAULT 1,
 revision INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(lead,account)
);
CREATE TABLE IF NOT EXISTS team_conversation (
 id TEXT PRIMARY KEY, lead TEXT NOT NULL REFERENCES team_lead(id), title TEXT NOT NULL,
 visibility TEXT NOT NULL CHECK(visibility IN ('private','team')), projects_json TEXT NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1, thread INTEGER NOT NULL UNIQUE REFERENCES mate_thread(id),
 created_by TEXT NOT NULL REFERENCES approver(name), created_at TEXT NOT NULL, last_claimed_at TEXT
);
CREATE TABLE IF NOT EXISTS team_participant (
 conversation TEXT NOT NULL REFERENCES team_conversation(id), account TEXT NOT NULL REFERENCES approver(name),
 role TEXT NOT NULL CHECK(role IN ('viewer','contributor','manager')), active INTEGER NOT NULL DEFAULT 1,
 revision INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(conversation,account)
);
CREATE TABLE IF NOT EXISTS team_message (
 message INTEGER PRIMARY KEY REFERENCES mate_message(id), conversation TEXT NOT NULL REFERENCES team_conversation(id),
 author TEXT NOT NULL REFERENCES approver(name), author_generation INTEGER NOT NULL, lead_member_revision INTEGER NOT NULL, participant_revision INTEGER NOT NULL, request_id TEXT NOT NULL,
 payload_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','answered','failed','cancelled','uncertain')),
 revision INTEGER NOT NULL DEFAULT 1, generation INTEGER NOT NULL DEFAULT 0, runner TEXT, claimed_at TEXT,
 turn_id INTEGER REFERENCES mate_turn(id), stop_requested INTEGER NOT NULL DEFAULT 0, error TEXT,
 UNIQUE(conversation,author,request_id)
);
CREATE INDEX IF NOT EXISTS team_message_queue ON team_message(status,message);
CREATE INDEX IF NOT EXISTS team_message_conversation ON team_message(conversation,message);
CREATE UNIQUE INDEX IF NOT EXISTS team_message_single_writer ON team_message(conversation) WHERE status='running';
CREATE TABLE IF NOT EXISTS team_read (
 conversation TEXT NOT NULL REFERENCES team_conversation(id), account TEXT NOT NULL REFERENCES approver(name),
 message INTEGER NOT NULL, PRIMARY KEY(conversation,account)
);
CREATE TABLE IF NOT EXISTS team_follow (
 conversation TEXT NOT NULL REFERENCES team_conversation(id), account TEXT NOT NULL REFERENCES approver(name),
 generation INTEGER NOT NULL, lead_member_revision INTEGER NOT NULL, participant_revision INTEGER NOT NULL, enabled INTEGER NOT NULL, PRIMARY KEY(conversation,account)
);
CREATE TABLE IF NOT EXISTS team_mate_session (
 session INTEGER PRIMARY KEY REFERENCES mate_session(id), thread INTEGER NOT NULL REFERENCES mate_thread(id)
);
CREATE INDEX IF NOT EXISTS team_mate_session_thread ON team_mate_session(thread,session);
CREATE TABLE IF NOT EXISTS team_task_owner (
 task_ref INTEGER PRIMARY KEY REFERENCES task_ref(id), lead TEXT NOT NULL REFERENCES team_lead(id), conversation TEXT REFERENCES team_conversation(id),
 revision INTEGER NOT NULL DEFAULT 1, changed_by TEXT NOT NULL, changed_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS team_event (
 id INTEGER PRIMARY KEY AUTOINCREMENT, lead TEXT NOT NULL REFERENCES team_lead(id),
 conversation TEXT REFERENCES team_conversation(id), kind TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS team_event_conversation ON team_event(conversation,id);
CREATE INDEX IF NOT EXISTS team_event_lead ON team_event(lead,id);
CREATE INDEX IF NOT EXISTS team_lead_member_account ON team_lead_member(account,active,lead);
CREATE INDEX IF NOT EXISTS team_participant_account ON team_participant(account,active,conversation);
CREATE TABLE IF NOT EXISTS team_request (
 account TEXT NOT NULL, generation INTEGER NOT NULL, request_id TEXT NOT NULL, payload_hash TEXT NOT NULL,
 response_json TEXT NOT NULL, PRIMARY KEY(account,generation,request_id)
);
`;

function initializeStore(db: Database, file: string): Store {
  // THE EPOCH, BEFORE ANY DDL (implementation review, finding 3): even
  // the fresh-SCHEMA exec below adds this build's new tables and indexes
  // to an old database, so the sentinel commits FIRST — a non-migrating
  // reader must never see new shapes under an old positive version.
  // THE PREFLIGHT (v48 integrity): the version is read as EXACTLY ONE
  // safe, supported integer before any DDL — one row, a safe integer,
  // its magnitude between 1 and this build's version. A database with no
  // version table is a fresh file; anything else (two rows, a text or
  // fractional version, a newer build's version, a zero) refuses here,
  // with the file untouched, rather than running this build's DDL over a
  // shape it cannot name.
  const preflight = schemaVersionPreflight(db, file);
  if (preflight !== null && Math.abs(preflight) >= 70 && !tableExists(db, "service_cursor")) {
    throw new Error(`${file}: service progress is missing; refusing to silently reset worker cursors`);
  }
  if (preflight !== null && Math.abs(preflight) >= 71) {
    for (const table of TEAM_TABLES) if (!tableExists(db, table)) throw new Error(`${file}: team history is missing; refusing to recreate membership or queued work`);
  }
  if (preflight !== null && Math.abs(preflight) >= 72) {
    if (!tableExists(db, "telegram_team_chat")) throw new Error(`${file}: Telegram team chat history is missing; refusing to recreate subscriptions`);
    if (!hasColumn(db, "telegram_team_chat", "binding")) throw new Error(`${file}: Telegram team chat pairing metadata is missing; refusing to recreate subscription authority`);
  }
  // Check existing authority metadata before even stamping a migration.
  if (preflight !== null && Math.abs(preflight) >= 54) {
    for (const table of ["approver", "invite"]) {
      if (!db.prepare(`PRAGMA table_info(${table})`).all().some(row => row["name"] === "projects_json")) {
        throw new Error(`${file}: project access metadata is missing from ${table}; refusing to widen access`);
      }
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 55 && db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='plan_authorization'").get() === undefined) {
    throw new Error(`${file}: plan authorization metadata is missing; refusing to recreate authority`);
  }
  if (preflight !== null && Math.abs(preflight) >= 56) {
    for (const table of ["workflow_recipe", "workflow_preview"]) {
      if (db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(table) === undefined) throw new Error(`${file}: workflow recipe metadata is missing; refusing to recreate launch history`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 58) {
    for (const table of ["learning_capture", "learning_policy", "project_lesson", "learning_event", "learning_snapshot"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: learning history is missing; refusing to recreate authority`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 59) {
    for (const table of ["project_knowledge", "knowledge_change", "knowledge_snapshot"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: project knowledge history is missing; refusing to recreate it`);
    }
  }
  // THE SENTINEL IS A CHECKED COMPARE-AND-SET (raw authority repair): the
  // row moves from exactly the version the preflight read to its negative,
  // or this open refuses — a second migrator that raced this one between
  // the preflight and here has already moved the row, and nothing alters a
  // file whose version it did not read.
  if (preflight !== null && Math.abs(preflight) >= 61) {
    for (const table of ["notification_delivery", "telegram_outbound_message", "telegram_retry"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: Telegram delivery history is missing; refusing to recreate receipts`);
    }
    for (const column of ["provenance_scope", "project", "task_ref", "task_id", "source_run"]) {
      if (!hasColumn(db, "notification", column)) throw new Error(`${file}: notification provenance is missing; refusing to recreate authority`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 62) {
    for (const table of ["telegram_conversation", "telegram_proposal_action"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: Telegram conversation history is missing; refusing to recreate it`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 63) {
    if (!tableExists(db, "telegram_conversation_part")) throw new Error(`${file}: Telegram reply history is missing; refusing to recreate it`);
  }
  if (preflight !== null && Math.abs(preflight) >= 64) {
    if (!tableExists(db, "mate_turn_evidence") || !hasColumn(db, "telegram_conversation_part", "artifact")) throw new Error(`${file}: Telegram image history is missing; refusing to recreate it`);
  }
  if (preflight !== null && Math.abs(preflight) >= 65) {
    for (const table of ["skill_package", "skill_owner", "project_skill_change", "skill_snapshot", "skill_test"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: saved skills are missing; refusing to recreate them`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 66) {
    const ddl = db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name='mate_proposal'").get()?.["sql"];
    if (typeof ddl !== "string" || canonicalDdl(ddl) !== canonicalDdl(MATE_PROPOSAL_V66_DDL("mate_proposal"))) throw new Error(`${file}: shared action history has an unknown shape; refusing to recreate it`);
  }
  if (preflight !== null && Math.abs(preflight) >= 67) {
    for (const table of SLACK_TABLES) if (!tableExists(db, table)) throw new Error(`${file}: Slack history is missing; refusing to recreate receipts`);
  }
  if (preflight !== null && Math.abs(preflight) >= 68) {
    for (const table of chatTables("discord")) if (!tableExists(db, table)) throw new Error(`${file}: Discord history is missing; refusing to recreate receipts`);
  }
  if (preflight !== null && preflight > 0 && preflight < SCHEMA_VERSION) {
    const stamped = db.prepare("UPDATE schema_version SET version = ? WHERE version = ?").run(-preflight, preflight);
    if (Number(stamped.changes) !== 1) {
      throw new Error(`${file}: refusing to open — the schema version moved from v${preflight} between the preflight and the epoch stamp (another process is migrating it); this build speaks schema v${SCHEMA_VERSION} and alters nothing it cannot name`);
    }
  }
  db.exec(SCHEMA);
  db.exec(LEARNING_SCHEMA);
  db.exec(KNOWLEDGE_SCHEMA);
  db.exec(MEMORY_SCHEMA);
  db.exec(MODELS_SCHEMA);
  db.exec(SKILLS_SCHEMA);
  db.exec(SLACK_SCHEMA);
  db.exec(chatSchema("discord"));
  db.exec(chatSchema("teams"));
  db.exec(TEAM_SCHEMA);
  db.exec(SSO_SCHEMA);
  db.exec(CREDENTIALS_SCHEMA);
  db.exec(APPROVAL_SCHEMA);
  db.exec(LEDGER_CHAIN_SCHEMA);
  db.exec(MONITORING_SCHEMA);
  db.exec(INTEGRATIONS_SCHEMA);
  db.exec(MATE_ASK_SCHEMA);
  // Decisions in the chat app (no version bump: additive only): result, plan and merge buttons, and Request changes.
  db.exec(CHAT_DECIDE_SCHEMA);
  // A flow's "Send to me" and "Person chooses" zones (no version bump: additive only).
  db.exec(FLOW_SEND_SCHEMA);
  db.exec(SPEND_SCHEMA);
  // Sign-in pauses: one row per incident of a provider's sign-in no longer working.
  db.exec(PROVIDER_AUTH_SCHEMA);
  // The sign-in pause the dispatch gate last left this task waiting on (null: none), for the work index.
  addColumn(db, "task_ref", "auth_wait_pause", "INTEGER REFERENCES provider_auth_pause(id)");
  // Sized routing (no version bump: additive, and a wider tier check whose rows carry over): how big each task is,
  // who sized it and why, and the build tier its route chose; the light tier joins the strong one.
  addColumn(db, "task_ref", "size", "TEXT CHECK (size IN ('small','medium','large'))");
  addColumn(db, "task_ref", "size_risky", "INTEGER CHECK (size_risky IN (0, 1))");
  addColumn(db, "task_ref", "size_source", "TEXT CHECK (size_source IN ('classifier','heuristic','person'))");
  addColumn(db, "task_ref", "size_reason", "TEXT");
  addColumn(db, "task_ref", "route_tier", "TEXT");
  widenPhaseTierSchema(db);
  db.exec(PHASE_TIER_ALTERNATE_SCHEMA);
  db.exec(REVIEW_SCHEMA);
  db.exec(RETENTION_SCHEMA);
  // 1-day evidence: an older file's retention_setting only allowed 7 days or more (no version bump: its rows carry over).
  widenRetentionSchema(db);
  db.exec(CHECKOUT_CLEANUP_SCHEMA);
  db.exec(BACKUP_SCHEMA);
  // Sprint 8: the organisation policy (one row, or none: nothing restricted).
  db.exec(POLICY_SCHEMA);
  db.exec(RUN_CHECK_SCHEMA);
  db.exec(QUIET_CHAT_SCHEMA);
  // Screenshots with results: each person's choice (an older notification_preference gains it), and what was sent.
  addColumn(db, "notification_preference", "screenshots", "TEXT NOT NULL DEFAULT 'off' CHECK (screenshots IN ('off', 'first', 'all'))");
  db.exec(RESULT_SHOT_SCHEMA);
  // The update a batch line speaks for: its newest fact about that task (null: a finished result).
  addColumn(db, "chat_batch_item", "notification", "INTEGER");
  db.exec(LEAD_QUIET_SCHEMA);
  db.exec(LEAD_CONFIG_SCHEMA);
  // What a person's lead knows about them, beside its name and persona (an older lead_config gains it).
  addColumn(db, "lead_config", "about_json", "TEXT NOT NULL DEFAULT '[]'");
  db.exec(LEAD_COMMITMENT_SCHEMA);
  mergeCheckTables(db);
  addColumn(db, "monitoring_status", "target", "TEXT");
  // v105: how a teammate's turn was billed (this computer's Claude sign-in, as last seen).
  addColumn(db, "teammate_turn", "billing", "TEXT");
  // (A database from an earlier build of v105 made run_spend before these.)
  addColumn(db, "run_spend", "billing", "TEXT NOT NULL DEFAULT 'subscription' CHECK (billing IN ('subscription', 'api-key'))");
  addColumn(db, "run_spend", "billing_fixed", "INTEGER NOT NULL DEFAULT 0");
  migrate(db, preflight === null ? null : Math.abs(preflight));
  // Complete → pull request → merge: when a grant publishes, the project's "Merge when checks pass", and each
  // followed pull request's CI revisions and merge record (no version bump: additive only).
  addColumn(db, "publication_grant", "publish_on", "TEXT NOT NULL DEFAULT 'build' CHECK (publish_on IN ('build', 'complete'))");
  addColumn(db, "publication_grant", "merge_when_green", "INTEGER NOT NULL DEFAULT 0 CHECK (merge_when_green IN (0, 1))");
  db.exec(PULL_REQUEST_SCHEMA);
  // A pull request a flow's Pull request zone opened: the zone follows its CI, so Complete's follower leaves it alone.
  addColumn(db, "pull_request_follow", "flow_card", "INTEGER REFERENCES flow_card(id)");
  addColumn(db, "flow_card", "source_json", "TEXT");
  addColumn(db, "flow_card", "owner", "TEXT");
  addColumn(db, "flow", "owner", "TEXT");
  // v90: scripts in Python and Node, and scripts that run a file in the project.
  addColumn(db, "flow_script", "language", "TEXT NOT NULL DEFAULT 'shell'");
  addColumn(db, "flow_script", "file", "TEXT");
  // A script that came in with an imported flow waits for a person to approve it before it runs (no version bump: additive only).
  addColumn(db, "flow_script", "held", "TEXT");
  addColumn(db, "notification", "recipient", "TEXT");
  addColumn(db, "approver", "projects_json", "TEXT");
  addColumn(db, "invite", "projects_json", "TEXT");
  db.exec(LEDGER_SCHEMA);
  db.exec(RECIPE_SCHEMA);
  db.exec(PLAN_AUTO_SCHEMA);
  installLedgerTriggers(db);
  // Attention/history indexes come AFTER migration: on a database whose
  // constrained tables still carry a pre-rebuild shape, creating a partial
  // index first would fail with a raw SQL error instead of the migration's
  // articulate refusal.
  db.exec(`-- Attention and history predicates the inbox/done tabs saturate on. v6.
CREATE INDEX IF NOT EXISTS decision_attention ON decision (run, id) WHERE state IN ('open','expired');
CREATE INDEX IF NOT EXISTS incident_attention ON incident (run, id) WHERE resolved_at IS NULL;
CREATE INDEX IF NOT EXISTS task_ref_repo ON task_ref (repo, id);
-- Metadata-only family lists: history stays append-only, while each task's
-- current lease/result and exact recorded completion are indexed lookups.
CREATE INDEX IF NOT EXISTS work_family_parent ON task_ref (backend, revision_of, repo, id);
CREATE INDEX IF NOT EXISTS work_result ON run (task_ref, id DESC, role, outcome, head_revision, scope_digest, finished_at) WHERE finished_at IS NOT NULL AND role IN ('builder','scout');
CREATE INDEX IF NOT EXISTS work_spawned_run ON run (task_ref, id) WHERE provider_started_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS work_unsettled_custody ON run_process (run) WHERE exited_at IS NULL AND container_empty_at IS NULL;
CREATE INDEX IF NOT EXISTS work_unfinished ON run (task_ref, id DESC) WHERE outcome IS NULL;
CREATE INDEX IF NOT EXISTS work_live_claim ON claim (task_ref, lease_generation DESC, expires_at) WHERE released_at IS NULL;
CREATE INDEX IF NOT EXISTS work_runner_claim ON claim (runner, expires_at) WHERE released_at IS NULL;
CREATE INDEX IF NOT EXISTS work_completion ON action_ledger (task_id, action, source, run_id, id DESC);
CREATE INDEX IF NOT EXISTS work_task_ledger ON action_ledger (task_id, id DESC);
CREATE INDEX IF NOT EXISTS work_artifact_run ON artifact (run, created_at);
CREATE INDEX IF NOT EXISTS work_open_decision ON decision (run, id DESC) WHERE state <> 'answered' AND answered_at IS NULL;
CREATE INDEX IF NOT EXISTS run_task_outcome ON run (task_ref, outcome, id DESC);
CREATE INDEX IF NOT EXISTS task_done_recent ON task (updated_at DESC, id DESC) WHERE state = 'done';
CREATE INDEX IF NOT EXISTS run_started ON run (started_at, id);
-- Lead status and task wait stay on bounded indexed reads: this follows one
-- task's attempts. The newest release check is indexed on run_check itself.
CREATE INDEX IF NOT EXISTS lead_status_task_run ON run (task_ref, id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS diff_comment_source ON diff_comment (source_key) WHERE source_key IS NOT NULL;
-- One open question per racing agent (v14, finding 28) — lives here, after
-- the migration, because decision.contestant arrives by addColumn on
-- existing files (the v11c lesson).
CREATE UNIQUE INDEX IF NOT EXISTS one_open_decision_per_contestant
  ON decision (contestant) WHERE contestant IS NOT NULL AND state IN ('open','expired');
-- Pending steering, in filing order (arc 1, v22) — after migration because
-- task_steer arrives by CREATE TABLE IF NOT EXISTS on existing files.
CREATE INDEX IF NOT EXISTS task_steer_pending
  ON task_steer (task_ref, id) WHERE delivered_at IS NULL AND superseded_at IS NULL;
-- v25 attended-core uniqueness rules — after migration because decision is
-- rebuilt there and the new tables arrive by IF NOT EXISTS on existing files.
-- One OPEN authorization per task (closure is explicit, so this is a plain
-- column predicate, never a time computation).
CREATE UNIQUE INDEX IF NOT EXISTS one_open_authorization_per_task
  ON attended_authorization (task_ref) WHERE closed_at IS NULL;
-- Answer exactly-once: a retried answer cannot inject twice while a prior
-- injection is live or proven. Terminal failures (uncertain never-accepted,
-- cancelled) release the slot — the delivery-CAS on decision.delivered_turn
-- is the live gate, this index the backstop (v6 W5).
CREATE UNIQUE INDEX IF NOT EXISTS one_live_merge_blocker
  ON merge_blocker (publication) WHERE lifted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS session_turn_answer_once
  ON session_turn (source_kind, source_id)
  WHERE source_kind = 'answer' AND state NOT IN ('uncertain','cancelled');
-- Many decisions per run (v25 rebuild dropped the UNIQUE), but at most one
-- UNRESOLVED at a time.
CREATE UNIQUE INDEX IF NOT EXISTS one_open_decision_per_run
  ON decision (run) WHERE state IN ('open','expired');
-- The coordinator's per-pulse scan: resolved decisions on held runs whose
-- answer has not yet been injected.
CREATE INDEX IF NOT EXISTS decision_undelivered
  ON decision (run, id) WHERE state = 'answered' AND delivered_turn IS NULL;
-- v29 (the reviewer role) — after migration because run is rebuilt there
-- and review_request arrives by IF NOT EXISTS on existing files. One
-- OPEN request per run at a time.
CREATE UNIQUE INDEX IF NOT EXISTS one_open_review_request
  ON review_request (run) WHERE consumed_at IS NULL;
-- v50 (bounded review retries) replaces v29's one_review_per_source with
-- four exact backstops. A ROOT reviewer carries its attempt ordinal
-- (run.review_attempt, 1..REVIEW_ROOT_ATTEMPTS); a correction child
-- carries NULL. Per source run: one ordinal each, at most one root still
-- open, at most one root that ingested a review (a root ends 'no-change'
-- ONLY through ingestReview), and per reviewer parent at most one
-- correction child — the linear chain v29 always had.
CREATE UNIQUE INDEX IF NOT EXISTS root_review_attempt_ordinal
  ON run (parent_run, review_attempt) WHERE role = 'reviewer' AND review_attempt IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_live_root_review_per_source
  ON run (parent_run) WHERE role = 'reviewer' AND review_attempt IS NOT NULL AND outcome IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_successful_root_review_per_source
  ON run (parent_run) WHERE role = 'reviewer' AND review_attempt IS NOT NULL AND outcome = 'no-change';
CREATE UNIQUE INDEX IF NOT EXISTS one_correction_per_reviewer
  ON run (parent_run) WHERE role = 'reviewer' AND review_attempt IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_root_review_per_request
  ON review_request (reviewer_run) WHERE reviewer_run IS NOT NULL;
-- v30 (fallback chains): one transition per (cycle, from_index) — the
-- durable backstop the fenced advance/skip CAS relies on (Codex foundation
-- review, finding 1). After migration, since fallback_transition arrives by
-- IF NOT EXISTS on existing files.
CREATE UNIQUE INDEX IF NOT EXISTS fallback_transition_step
  ON fallback_transition (cycle, from_index);
-- One LIVE cycle per task (Codex E1 review, finding 5): the DB backstop
-- behind openFallbackCycle's transact guard.
CREATE UNIQUE INDEX IF NOT EXISTS one_live_fallback_cycle_per_task
  ON fallback_cycle (task_ref) WHERE state NOT IN ('closed','incident');
-- v44 (adaptive execution plans) — after migration because plan_revision and
-- run_checkpoint arrive by IF NOT EXISTS on existing files. At most one
-- revision 'blocked' at a time (a second proposal waits for the first to
-- resolve rather than racing it); progress reads walk one run's checkpoints
-- in order. (task_ref, revision) is already unique via the table's own
-- UNIQUE constraint, so no extra index is needed for that.
CREATE UNIQUE INDEX IF NOT EXISTS one_blocked_revision_per_task
  ON plan_revision (task_ref) WHERE status = 'blocked';
CREATE INDEX IF NOT EXISTS run_checkpoint_by_run ON run_checkpoint (run, id);
CREATE INDEX IF NOT EXISTS run_checkpoint_by_task ON run_checkpoint (task_ref, id);`);

  // THE BOOKKEEPING WRITE, checked (raw authority repair): migrate() has
  // already done the work by the time this runs; the row is bookkeeping
  // about it, not the trigger for it — and it is written ONLY from the
  // exact marker this open stamped or resumed. A fresh file gains its one
  // row; an upgrade clears exactly its own sentinel (−from); a resumed
  // epoch clears exactly the sentinel the preflight read; a current file
  // is left alone. A row that is not what this open expects was moved by
  // another process, and this open refuses rather than overwriting it.
  const expectedMarker = preflight === null ? null : preflight === SCHEMA_VERSION ? null : preflight < 0 ? preflight : -preflight;
  if (preflight === null) {
    const inserted = db.prepare("INSERT INTO schema_version (version) SELECT ? WHERE NOT EXISTS (SELECT 1 FROM schema_version)").run(SCHEMA_VERSION);
    if (Number(inserted.changes) !== 1) {
      throw new Error(`${file}: refusing to open — a schema version appeared under this fresh open (another process is creating it); this build speaks schema v${SCHEMA_VERSION} and alters nothing it cannot name`);
    }
  } else if (expectedMarker !== null) {
    const cleared = db.prepare("UPDATE schema_version SET version = ? WHERE version = ?").run(SCHEMA_VERSION, expectedMarker);
    if (Number(cleared.changes) !== 1) {
      throw new Error(`${file}: refusing to open — the epoch sentinel ${expectedMarker} moved under this migration (another process is migrating it); this build speaks schema v${SCHEMA_VERSION} and alters nothing it cannot name`);
    }
  }

  return new Store(db);
}

/**
 * THE ONE STRICT VERSION READER (raw authority repair): every door — the
 * migrating open, the non-migrating door, the per-unit-of-work live check
 * — reads the stored schema version through this, BEFORE any DDL, as
 * exactly one safe, supported integer, or learns in words what is wrong.
 *
 *   `{ ok: true, version: null }` — a genuinely FRESH file: no
 *     schema_version table and NOTHING ELSE in it. A file that carries
 *     tables but no version table is not fresh; it is a database some
 *     other program (or a half-written one) shaped, and it refuses.
 *   `{ ok: true, version: n }` — one integer row: a positive supported
 *     version (1 … this build's), or a mid-flight epoch sentinel (−from,
 *     with from strictly BELOW this build's version — an upgrade never
 *     begins at the version it is upgrading to, so −SCHEMA_VERSION is an
 *     impossible marker no build ever wrote, and refuses).
 *   `{ ok: false, problem }` — no row, two rows, a text or fractional or
 *     unsafe value, zero, a newer build's version or sentinel, or the
 *     impossible negative of this build's own version.
 *
 * Proved by name and by storage class, never by catching an error: an
 * error while READING the version must refuse, not read as "fresh".
 */
export function readSchemaVersion(db: Database): { ok: true; version: number | null } | { ok: false; problem: string } {
  const refuse = (problem: string): { ok: false; problem: string } => ({ ok: false, problem });
  const table = db.prepare("SELECT 1 AS hit FROM sqlite_master WHERE type = 'table' AND name = 'schema_version'").get();
  if (table === undefined) {
    // No version table: fresh ONLY when the file holds nothing at all —
    // no objects, AND none of the metadata SQLite persists in the header
    // (the user version, the application id, the schema cookie). A file
    // whose sqlite_master is empty but whose header carries a non-default
    // cookie was shaped by SOMETHING (a `PRAGMA user_version = 77`, a
    // schema created and dropped) and is not a new file this build may
    // expand over; it refuses, untouched, at every door.
    const anything = db.prepare("SELECT COUNT(*) AS n FROM sqlite_master").get() as { n?: unknown } | undefined;
    if (Number(anything?.n ?? 0) > 0) return refuse("the file carries tables but no schema_version table — it is not a fresh database, and not one this build shaped");
    for (const [pragma, word] of [
      ["user_version", "user version"],
      ["application_id", "application id"],
      ["schema_version", "schema cookie"],
    ] as const) {
      const row = db.prepare(`PRAGMA ${pragma}`).get() as Record<string, unknown> | undefined;
      const value = row === undefined ? undefined : row[pragma];
      if (value === undefined) return refuse(`the file's ${word} cannot be read — it is not a fresh database`);
      if (String(value) !== "0") return refuse(`the file carries no schema_version table but a persisted ${word} of ${String(value)} — it is not a fresh database, and not one this build shaped`);
    }
    // THE COMPLETE FRESH-FILE INVARIANT (final authority closure): a
    // genuinely fresh database has NO persisted page at all — a
    // nonexistent path, a zero-byte file, or `:memory:` reads a page
    // count of zero. A file that already holds a page (one written by
    // `PRAGMA journal_mode = WAL` alone, whose sqlite_master is empty and
    // whose header cookies all still read zero) was shaped by something,
    // and is not a new file this build may expand over: it refuses,
    // untouched and byte-identically, on every open.
    const pages = db.prepare("PRAGMA page_count").get() as Record<string, unknown> | undefined;
    const pageCount = pages === undefined ? undefined : pages["page_count"];
    if (pageCount === undefined) return refuse("the file's page count cannot be read — it is not a fresh database");
    if (String(pageCount) !== "0") return refuse(`the file carries no schema_version table but ${String(pageCount)} persisted page(s) — it is not a fresh database, and not one this build shaped`);
    return { ok: true, version: null };
  }
  // The value is read as its storage class and its decimal text, so a
  // 64-bit integer past the safe range is judged as text rather than
  // thrown (or rounded) by the binding on the way out.
  const rows = db.prepare("SELECT typeof(version) AS kind, CAST(version AS TEXT) AS text FROM schema_version").all() as { kind: unknown; text: unknown }[];
  if (rows.length !== 1) return refuse(rows.length === 0 ? "schema_version carries no row" : `schema_version carries ${rows.length} rows, not one`);
  const kind = String(rows[0]?.kind);
  const text = String(rows[0]?.text);
  const version = /^-?\d+$/.test(text) ? Number(text) : Number.NaN;
  if (kind !== "integer" || !Number.isSafeInteger(version) || String(version) !== text) return refuse(`schema_version is ${kind === "text" ? JSON.stringify(text) : text} (${kind}), not a safe integer`);
  const magnitude = Math.abs(version);
  if (magnitude === 0) return refuse("schema_version is 0, which no build ever wrote");
  if (magnitude > SCHEMA_VERSION) return refuse(`it is schema v${magnitude}, written by a newer build`);
  if (version === -SCHEMA_VERSION) return refuse(`schema_version is ${version}, a mid-flight marker no build ever wrote (an upgrade never begins at v${SCHEMA_VERSION}, the version it upgrades to)`);
  return { ok: true, version };
}

/**
 * The stored schema version as exactly one safe, supported integer — or
 * null for a genuinely fresh file, or a thrown refusal naming what is
 * wrong (v48 integrity). Runs BEFORE any DDL so a shape this build cannot
 * name is never altered. A negative version within the supported range is
 * a migration that died mid-flight; the idempotent migrator resumes it.
 */
export function schemaVersionPreflight(db: Database, file: string): number | null {
  const read = readSchemaVersion(db);
  if (!read.ok) throw new Error(`${file}: refusing to open — ${read.problem}; this build speaks schema v${SCHEMA_VERSION} and alters nothing it cannot name`);
  return read.version;
}

/**
 * The non-migrating door (MCP gateway spec v6): open an EXISTING database
 * without creating directories, executing schema DDL, or migrating — the
 * MCP server must never write schema or take migration locks. Refusals
 * are words, not exceptions: an absent file, a version that is not
 * exactly this build's, or a negative version (a migration mid-flight —
 * the epoch sentinel) all refuse. Long-lived callers re-check with
 * `store.schemaCurrent()` inside every unit of work, because another
 * process may migrate underneath them.
 */
export function openStoreNoMigrate(
  file: string,
  options: OpenOptions = {},
): { ok: true; store: Store } | { ok: false; reason: "missing" | "version"; message: string } {
  const connect = options.connect ?? defaultConnect;
  if (file === ":memory:" || !existsSync(file)) {
    return { ok: false, reason: "missing", message: `${file} does not exist — run \`toolroll\` once to create it` };
  }
  const db = connect(file);
  waitForConcurrentWriter(db);
  // The same referential law every migrating connection gets from SCHEMA —
  // this door never execs SCHEMA, so the pragma is explicit (review f9).
  db.exec("PRAGMA foreign_keys = ON");
  // The SAME strict reader the migrating door uses (raw authority repair):
  // a file this build cannot name refuses in its words, never as "no
  // version" and never as a version some lenient read coerced.
  let read: ReturnType<typeof readSchemaVersion>;
  try {
    read = readSchemaVersion(db);
  } catch (error) {
    // A file SQLite itself cannot read is refused in words too — never as
    // "no version", never by letting the error stand in for an answer.
    read = { ok: false, problem: `the schema version cannot be read (${error instanceof Error ? error.message : String(error)})` };
  }
  if (!read.ok) {
    db.close();
    return { ok: false, reason: "version", message: `${file}: ${read.problem} — open it with the CLI or console first` };
  }
  const seen = read.version;
  if (seen === null) {
    // A file deleted between the existence check and the connect makes
    // SQLite create an EMPTY one — refuse, and take the empty residue
    // back out so the race leaves no trace (review finding 9).
    db.close();
    try {
      if (statSync(file).size === 0) unlinkSync(file);
    } catch {
      // Already gone, or someone else's — leave it.
    }
    return { ok: false, reason: "version", message: `${file}: it carries no schema version — open it with the CLI or console first` };
  }
  if (seen !== SCHEMA_VERSION) {
    db.close();
    const said =
      seen === null
        ? "it carries no schema version"
        : seen < 0
          ? `a migration is mid-flight (epoch ${-seen})`
          : `it is schema v${seen} and this build speaks v${SCHEMA_VERSION}`;
    return { ok: false, reason: "version", message: `${file}: ${said} — open it with the CLI or console first` };
  }
  return { ok: true, store: new Store(db) };
}

/**
 * Loaded through `createRequire` rather than a top-level import so that the
 * cost — and the experimental warning — falls only on a command that actually
 * opens the database. `import()` would work too, but it would make opening the
 * store async for every caller in order to save nothing.
 *
 * Node prints `ExperimentalWarning: SQLite is an experimental feature` to
 * stderr the first time this runs. It is left alone: an earlier version
 * filtered it by swapping the process-wide `warning` listeners, which turned
 * every `process.once("warning")` anyone else had registered into a permanent
 * one and re-emitted the rest in a format Node does not use. Hiding one line
 * of stderr is not worth breaking a global for. The right fix belongs in the
 * launcher — `--disable-warning=ExperimentalWarning` — not in a library.
 */
/**
 * Columns added after somebody's database already existed.
 *
 * `CREATE TABLE IF NOT EXISTS` does exactly nothing to a table that is already
 * there, so a column added to the schema later never reaches an existing file
 * — and every test opening `:memory:` or a fresh path passes while the first
 * real database fails on the next query. This one was found by opening one.
 *
 * Additive only, and idempotent: each column is added if it is missing and
 * skipped if it is not. Nothing here rewrites or drops anything.
 */
function migrate(db: Database, origin: number | null): void {
  // THE MIGRATION EPOCH (MCP gateway spec v6, Codex rounds 3/5). This
  // migrator alters schema first and bumps schema_version last, so a
  // reader re-checking the version can pass MID-DDL. The fix is a
  // committed marker BEFORE any DDL: an upgrading database's version row
  // goes NEGATIVE (−from) in its own autocommitted statement, and the
  // final bookkeeping write at the end of openStore replaces it with the
  // target. A non-migrating reader treats a negative version — or any
  // version other than its own — as "not mine to touch". A crash mid-
  // migration leaves the sentinel VISIBLE instead of a silently
  // half-shaped database; re-running the same (idempotent) migrator
  // clears it, which the resume below allows.
  // The epoch sentinel was committed by openStore BEFORE the SCHEMA exec
  // (review finding 3). A negative version here is a prior death mid-
  // flight — this run resumes it (every step is IF-NOT-EXISTS/
  // recognize-and-rebuild idempotent) and the final bookkeeping clears it.
  addColumn(db, "task_ref", "origin", "TEXT NOT NULL DEFAULT 'theirs'");
  addColumn(db, "task_ref", "repo", "TEXT");
  addColumn(db, "claim", "released_by", "TEXT");
  addColumn(db, "notification", "resolved_at", "TEXT");
  // Delivery claiming: two deliverers (the bridge, `outbox deliver`) must
  // not both send one row. A claim is a short lease on the act of sending.
  addColumn(db, "notification", "claim_owner", "TEXT");
  addColumn(db, "notification", "claim_expires_at", "TEXT");
  addColumn(db, "approver", "generation", "INTEGER NOT NULL DEFAULT 1");
  // v77: a lead thread belongs to the lead conversation, a project or a task.
  addColumn(db, "mate_thread", "scope_kind", "TEXT NOT NULL DEFAULT 'lead' CHECK (scope_kind IN ('lead','project','task'))");
  addColumn(db, "mate_thread", "scope_key", "TEXT");
  db.exec("CREATE INDEX IF NOT EXISTS mate_thread_scope ON mate_thread (approver, scope_kind, scope_key, closed_at)");
  // v4 additive: failure strikes and the watch incarnation a claim was
  // dispatched under.
  addColumn(db, "task_ref", "strikes", "INTEGER NOT NULL DEFAULT 0");
  addColumn(db, "claim", "incarnation", "TEXT");
  // v72: one live Telegram binding per (bot, user) replaces one per bot, so
  // several teammates can pair their own chats. The schema text already
  // created the new index; the old rule is dropped here, idempotently.
  db.exec("DROP INDEX IF EXISTS telegram_binding_live");
  // v73: the same rule for Slack and Discord — one binding per (installation,
  // member) instead of one per installation.
  db.exec("DROP INDEX IF EXISTS slack_one_binding");
  db.exec("DROP INDEX IF EXISTS discord_one_binding");
  rebuild(db);
  rebuildDecisionVia(db);
  // v4 CHECK widenings, each a copy-rename against an exactly recognized
  // predecessor. Order matters only in that they follow the older rebuilds:
  // an M2 database reaches the v4 shapes through rebuild() directly.
  rebuildForV4(
    db,
    "run",
    "'built','failed','refused','parked'",
    "'no-change'",
    V4_RUN_DDL("run_next"),
    V4_RUN_COLUMNS,
  );
  rebuildForV4(
    db,
    "hold",
    "'operator','decision','incident'",
    "'backoff'",
    `CREATE TABLE hold_next (
       id         INTEGER PRIMARY KEY AUTOINCREMENT,
       task_ref   INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
       owner_kind TEXT NOT NULL CHECK (owner_kind IN ('operator','decision','incident','backoff')),
       owner_id   TEXT NOT NULL,
       reason     TEXT NOT NULL,
       until      TEXT,
       held_at    TEXT NOT NULL,
       UNIQUE (owner_kind, owner_id)
     )`,
    ["id", "task_ref", "owner_kind", "owner_id", "reason", "until", "held_at"],
  );
  rebuildForV4(
    db,
    "incident",
    "'malformed-decision'",
    "'attempts-exhausted'",
    `CREATE TABLE incident_next (
       id          INTEGER PRIMARY KEY AUTOINCREMENT,
       run         INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
       kind        TEXT NOT NULL CHECK (kind IN ('malformed-decision','attempts-exhausted','commit-failure','malformed-plan','plan-attempts-exhausted')),
       created_at  TEXT NOT NULL,
       resolved_at TEXT,
       resolved_by TEXT
     )`,
    ["id", "run", "kind", "created_at", "resolved_at", "resolved_by"],
  );
  // Columns the v4 run shape carries; idempotent for any table that arrived
  // here by a path that already has them.
  addColumn(db, "run", "provider_started_at", "TEXT");
  addColumn(db, "run", "tokens_in", "INTEGER");
  addColumn(db, "run", "tokens_out", "INTEGER");
  addColumn(db, "run", "cost_usd", "REAL");
  addColumn(db, "run", "usage_json", "TEXT");
  addColumn(db, "run", "head_revision", "TEXT");
  addColumn(db, "run", "handoff", "TEXT");
  // v7 (planning): additive task_ref columns, then three CHECK widenings —
  // each a copy-rename against an exactly recognized predecessor, run AFTER
  // every older normalizer so a v6 database is the only shape they see
  // (Codex planning review, finding 8: editing the fresh DDL alone would
  // skip existing files, recording v7 over a table that still refuses
  // planner rows).
  addColumn(db, "task_ref", "plan", "TEXT CHECK (plan IN ('requested','drafted'))");
  // v32 (the mate): a chat_turn row may be one step of a mate turn; a
  // scope may have been written by a confirmed mate proposal.
  addColumn(db, "chat_turn", "kind", "TEXT NOT NULL DEFAULT 'chat'");
  addColumn(db, "chat_turn", "mate_turn", "INTEGER");
  addColumn(db, "task_scope", "proposed_via", "TEXT");
  // v35 (subscription-backed mate): the chat provider CHECKs admit the
  // two local harness login modes. The dollar columns stay intact for API
  // traffic; subscription rows carry zero because no dollar amount is
  // observable or enforceable through a membership login.
  rebuildChatProvidersForV35(db);
  // v36 (long-running mate): the password-minted conversation is an
  // explicit-lifecycle capability, not a wall-clock lease. Existing v35
  // sessions are closed during migration because their signed terms were
  // time-bounded; the operator can mint a persistent session deliberately.
  rebuildMateSessionForV36(db);
  // v37 (unattended permissions): the installation singleton arrives via
  // SCHEMA on both roads; task overrides are additive and null by default.
  addColumn(db, "task_ref", "permission_mode", "TEXT CHECK (permission_mode IN ('auto','bypassPermissions'))");
  // v33 (mate v3): `answer` joins the proposal kinds — a CHECK widening,
  // copy-rename against the v32 shape.
  rebuildMateProposalForV33(db);
  db.exec("CREATE INDEX IF NOT EXISTS mate_proposal_thread ON mate_proposal (thread, state)");
  addColumn(db, "task_ref", "plan_strikes", "INTEGER NOT NULL DEFAULT 0");
  rebuildForV4(
    db,
    "run",
    "role IN ('builder','repair')",
    "'planner'",
    V4_RUN_DDL("run_next"),
    V4_RUN_COLUMNS,
  );
  rebuildForV4(
    db,
    "artifact",
    "'diff','status','park-payload'",
    "'plan'",
    `CREATE TABLE artifact_next (
       id             INTEGER PRIMARY KEY AUTOINCREMENT,
       run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
       kind           TEXT NOT NULL CHECK (kind IN ('diff','status','park-payload','plan')),
       key            TEXT NOT NULL,
       bytes_original INTEGER NOT NULL,
       bytes_stored   INTEGER NOT NULL,
       truncated      INTEGER NOT NULL DEFAULT 0,
       sha256         TEXT NOT NULL,
       capture        TEXT NOT NULL,
       created_at     TEXT NOT NULL,
       redacted       INTEGER NOT NULL DEFAULT 0
     )`,
    ["id", "run", "kind", "key", "bytes_original", "bytes_stored", "truncated", "sha256", "capture", "created_at", "redacted"],
  );
  rebuildForV4(
    db,
    "incident",
    "'malformed-decision','attempts-exhausted','commit-failure'",
    "'malformed-plan'",
    `CREATE TABLE incident_next (
       id          INTEGER PRIMARY KEY AUTOINCREMENT,
       run         INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
       kind        TEXT NOT NULL CHECK (kind IN ('malformed-decision','attempts-exhausted','commit-failure','malformed-plan','plan-attempts-exhausted')),
       created_at  TEXT NOT NULL,
       resolved_at TEXT,
       resolved_by TEXT
     )`,
    ["id", "run", "kind", "created_at", "resolved_at", "resolved_by"],
  );
  // v8 (routines): purely additive — two new tables arrive through the fresh
  // SCHEMA's CREATE TABLE IF NOT EXISTS (they did not exist before, so the
  // recognizer story of the CHECK widenings does not apply), and task_ref
  // grows the nullable instance link. The routine table exists by the time
  // this runs because openStore executes SCHEMA first.
  addColumn(db, "task_ref", "routine_id", "INTEGER REFERENCES routine(id)");
  // v9 (providers): run.provider rides all three canonical shapes — fresh
  // SCHEMA, V4_RUN_DDL, V4_RUN_COLUMNS — AND this additive column for
  // databases whose run table is already current (the rebuilds only fire
  // on pre-v7 shapes; ordering per the Codex provider review, Q7). The
  // default backfills history truthfully: only claude ever spawned.
  addColumn(db, "run", "provider", "TEXT NOT NULL DEFAULT 'claude'");
  // The instance/task agent pin: stamped at routine fire time so a firing
  // resolved under approved terms cannot be re-routed by later flags.
  addColumn(db, "task_ref", "agent_provider", "TEXT");
  addColumn(db, "task_ref", "agent_model", "TEXT");
  // v10 (free-text answers): two new tables via the fresh SCHEMA, plus the
  // digest that binds an irreversible confirmation to the EXACT note it
  // confirmed (Codex free-text review, finding 3).
  addColumn(db, "telegram_action", "note_digest", "TEXT");
  // v11 (M5 worktree setup): additive — the worktree_setup table arrives
  // through the fresh SCHEMA's IF NOT EXISTS, and existing worktree rows
  // gain the setup cache column.
  addColumn(db, "worktree", "setup_digest", "TEXT");
  // v11b (M6.8 revision tasks): additive columns; diff_comment arrives via
  // the fresh SCHEMA's IF NOT EXISTS.
  addColumn(db, "task_ref", "revision_of", "TEXT");
  addColumn(db, "task_ref", "revision_brief_artifact", "INTEGER REFERENCES artifact(id)");
  // v11c (M8 audit C-6): the remote's observed PR verdict, additive.
  addColumn(db, "publication", "remote_state", "TEXT");
  // v11c (audit SD-4): the last OBSERVED check state, additive.
  addColumn(db, "publication", "last_check_state", "TEXT");
  addColumn(db, "publication", "last_check_at", "TEXT");
  // v11c (M8.17 PR-comment intake): the ingest idempotency key, additive —
  // a same-day v11 database gains it here; fresh ones carry it already.
  // Its unique index rides the post-migration block in openStore.
  addColumn(db, "diff_comment", "source_key", "TEXT");
  // v11 (M5 activity): the machine-authored phase — stamped by the control
  // plane at its own state-machine boundaries, never parsed out of a
  // provider stream. Transient in meaning (read while the run is open),
  // durable in storage (the simplest shared state between daemon and
  // console is the database they already share).
  addColumn(db, "run", "phase", "TEXT");
  // v11 (M5 terminal diff): artifact.kind admits 'terminal-diff' (the
  // immutable base→head patch captured before the worktree releases) and
  // 'diff-stat' (its machine-parsed summary). Same recognized-exactly
  // CHECK-widening recipe as v7's.
  rebuildForV4(
    db,
    "artifact",
    "'diff','status','park-payload','plan'",
    "'terminal-diff','diff-stat'",
    `CREATE TABLE artifact_next (
       id             INTEGER PRIMARY KEY AUTOINCREMENT,
       run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
       kind           TEXT NOT NULL CHECK (kind IN ('diff','status','park-payload','plan','terminal-diff','diff-stat')),
       key            TEXT NOT NULL,
       bytes_original INTEGER NOT NULL,
       bytes_stored   INTEGER NOT NULL,
       truncated      INTEGER NOT NULL DEFAULT 0,
       sha256         TEXT NOT NULL,
       capture        TEXT NOT NULL,
       created_at     TEXT NOT NULL,
       redacted       INTEGER NOT NULL DEFAULT 0
     )`,
    ["id", "run", "kind", "key", "bytes_original", "bytes_stored", "truncated", "sha256", "capture", "created_at", "redacted"],
  );
  // v11b (M6 handoff + revision briefs): the same recipe again, recognizing
  // BOTH the pre-v11 shape (already rebuilt by the step above when this
  // runs on an old file) and a database that opened at v11 earlier today.
  rebuildForV4(
    db,
    "artifact",
    "'terminal-diff','diff-stat'",
    "'handoff','revision-brief'",
    `CREATE TABLE artifact_next (
       id             INTEGER PRIMARY KEY AUTOINCREMENT,
       run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
       kind           TEXT NOT NULL CHECK (kind IN ('diff','status','park-payload','plan','terminal-diff','diff-stat','handoff','revision-brief')),
       key            TEXT NOT NULL,
       bytes_original INTEGER NOT NULL,
       bytes_stored   INTEGER NOT NULL,
       truncated      INTEGER NOT NULL DEFAULT 0,
       sha256         TEXT NOT NULL,
       capture        TEXT NOT NULL,
       created_at     TEXT NOT NULL,
       redacted       INTEGER NOT NULL DEFAULT 0
     )`,
    ["id", "run", "kind", "key", "bytes_original", "bytes_stored", "truncated", "sha256", "capture", "created_at", "redacted"],
  );
  // v12 (adoption review, finding 7): immutable filing provenance, additive.
  // installation_fact arrives through the fresh SCHEMA's IF NOT EXISTS.
  addColumn(db, "task_ref", "filed_via", "TEXT");
  addColumn(db, "routine", "filed_via", "TEXT");
  // v13 (fleet chat): purely additive — chat_config and chat_turn arrive
  // through the fresh SCHEMA's IF NOT EXISTS; no existing table changes.
  // v13b: the pinned per-token price joins the config row, additive.
  addColumn(db, "chat_config", "price_in_microusd", "INTEGER");
  addColumn(db, "chat_config", "price_out_microusd", "INTEGER");
  // v14 (tournaments): five new tables ride the fresh SCHEMA's IF NOT
  // EXISTS; existing tables gain nullable columns here; and hold's
  // owner_kind CHECK is WIDENED by the recognized-exactly rebuild — v14
  // is deliberately NOT purely additive, and this is the one place that
  // says so.
  addColumn(db, "run", "contestant", "INTEGER REFERENCES contestant(id)");
  addColumn(db, "decision", "contestant", "INTEGER REFERENCES contestant(id)");
  addColumn(db, "decision", "closed_reason", "TEXT CHECK (closed_reason IN ('excluded'))");
  addColumn(db, "artifact", "capture_status", "TEXT CHECK (capture_status IN ('ok','failed'))");
  addColumn(db, "runner", "capacity_mode", "TEXT NOT NULL DEFAULT 'tasks'");
  rebuildForV4(
    db,
    "hold",
    "'operator','decision','incident','backoff'",
    "'contest'",
    `CREATE TABLE hold_next (
       id         INTEGER PRIMARY KEY AUTOINCREMENT,
       task_ref   INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
       owner_kind TEXT NOT NULL CHECK (owner_kind IN ('operator','decision','incident','backoff','contest')),
       owner_id   TEXT NOT NULL,
       reason     TEXT NOT NULL,
       until      TEXT,
       held_at    TEXT NOT NULL,
       UNIQUE (owner_kind, owner_id)
     )`,
    ["id", "task_ref", "owner_kind", "owner_id", "reason", "until", "held_at"],
  );
  // v15 (budgets, operator request): the per-attempt dollar cap joins the
  // scope, and spend_defaults arrives via the fresh SCHEMA's IF NOT EXISTS.
  addColumn(db, "task_scope", "budget_microusd", "INTEGER");
  // v16 (stage 6 + operator request): the default competing-agent count,
  // and the per-instance dollar cap on standing orders.
  addColumn(db, "spend_defaults", "race_agents", "INTEGER CHECK (race_agents BETWEEN 2 AND 4)");
  addColumn(db, "routine", "budget_per_run_microusd", "INTEGER");
  // v17 (live peek): the occupancy fence on checkouts, and artifact.kind
  // admits 'base-tree' (the enveloped dispatch-time snapshot the peek
  // consumes) — same recognized-exactly CHECK-widening recipe as v11's,
  // with the FULL current column set so capture_status survives.
  addColumn(db, "worktree", "lease_epoch", "TEXT");
  rebuildForV4(
    db,
    "artifact",
    "'diff','status','park-payload','plan','terminal-diff','diff-stat','handoff','revision-brief'",
    "'base-tree'",
    `CREATE TABLE artifact_next (
       id             INTEGER PRIMARY KEY AUTOINCREMENT,
       run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
       kind           TEXT NOT NULL CHECK (kind IN ('diff','status','park-payload','plan','terminal-diff','diff-stat','handoff','revision-brief','base-tree')),
       key            TEXT NOT NULL,
       bytes_original INTEGER NOT NULL,
       bytes_stored   INTEGER NOT NULL,
       truncated      INTEGER NOT NULL DEFAULT 0,
       sha256         TEXT NOT NULL,
       capture        TEXT NOT NULL,
       created_at     TEXT NOT NULL,
       redacted       INTEGER NOT NULL DEFAULT 0,
       capture_status TEXT CHECK (capture_status IN ('ok','failed'))
     )`,
    ["id", "run", "kind", "key", "bytes_original", "bytes_stored", "truncated", "sha256", "capture", "created_at", "redacted", "capture_status"],
  );
  // v18 (chains and next): the queue rank. Scheduling, never authority —
  // no digest binds it and no approval is voided by it.
  addColumn(db, "task", "priority", "INTEGER NOT NULL DEFAULT 0");
  // v19 (queue columns): reservations, the column note, and the queue
  // revision the console's drag CAS-checks. All additive; no index in
  // the fresh SCHEMA (the recorded partial-index trap).
  addColumn(db, "task_ref", "assigned_runner", "TEXT");
  addColumn(db, "runner", "queue_note", "TEXT");
  db.exec(`CREATE TABLE IF NOT EXISTS queue_state (
    id       INTEGER PRIMARY KEY CHECK (id = 1),
    revision INTEGER NOT NULL DEFAULT 0
  )`);
  db.exec("INSERT OR IGNORE INTO queue_state (id, revision) VALUES (1, 0)");
  // v20 (external dispatch): dispatch authority + blocked state on the
  // grant (cross-column rule dispatch=1 → remote_repo/plane_id lives in
  // saveGrant — ALTER ADD COLUMN cannot carry cross-column CHECKs), and
  // the mirror/ledger/intent tables. The trigger and every table are
  // shared with the fresh SCHEMA via CREATE IF NOT EXISTS.
  addColumn(db, "backend_grant", "dispatch", "INTEGER NOT NULL DEFAULT 0 CHECK (dispatch IN (0, 1))");
  addColumn(db, "backend_grant", "remote_repo", "TEXT");
  addColumn(db, "backend_grant", "plane_id", "TEXT");
  addColumn(db, "backend_grant", "dispatch_blocked", "TEXT CHECK (dispatch_blocked IN ('pending-marker','unreachable','foreign','missing','multiple-or-malformed'))");
  addColumn(db, "backend_grant", "dispatch_blocked_at", "TEXT");
  addColumn(db, "backend_grant", "dispatch_blocked_detail", "TEXT");
  db.exec(`CREATE TABLE IF NOT EXISTS external_mirror (
    local_task_id   TEXT PRIMARY KEY REFERENCES task(id) ON DELETE CASCADE,
    backend         TEXT NOT NULL,
    remote_repo     TEXT NOT NULL,
    remote_id       TEXT NOT NULL,
    provenance      TEXT NOT NULL CHECK (provenance IN ('local-create','intake','granted-all')),
    intake_grant    INTEGER,
    established_by  TEXT NOT NULL,
    established_at  TEXT NOT NULL,
    remote_state    TEXT NOT NULL CHECK (remote_state IN ('open','closed','missing')),
    close_generation INTEGER,
    sync_generation INTEGER NOT NULL DEFAULT 0,
    dispatch_ok     INTEGER NOT NULL DEFAULT 0 CHECK (dispatch_ok IN (0, 1)),
    reopened_by     TEXT,
    reopened_at     TEXT,
    CHECK ((provenance = 'intake') = (intake_grant IS NOT NULL)),
    UNIQUE (backend, remote_repo, remote_id)
  )`);
  db.exec(`CREATE TRIGGER IF NOT EXISTS external_mirror_immutable
    BEFORE UPDATE ON external_mirror
    WHEN OLD.backend IS NOT NEW.backend OR OLD.remote_repo IS NOT NEW.remote_repo
      OR OLD.remote_id IS NOT NEW.remote_id OR OLD.provenance IS NOT NEW.provenance
      OR OLD.intake_grant IS NOT NEW.intake_grant
      OR OLD.established_by IS NOT NEW.established_by OR OLD.established_at IS NOT NEW.established_at
    BEGIN
      SELECT RAISE(ABORT, 'external mirror identity is immutable');
    END`);
  db.exec(`CREATE TABLE IF NOT EXISTS sync_ledger (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    backend     TEXT NOT NULL,
    remote_repo TEXT NOT NULL,
    generation  INTEGER NOT NULL,
    started_at  TEXT NOT NULL,
    finished_at TEXT,
    outcome     TEXT CHECK (outcome IN ('complete','capped','failed')),
    candidates  INTEGER NOT NULL DEFAULT 0,
    mirrored    INTEGER NOT NULL DEFAULT 0,
    detail      TEXT,
    UNIQUE (backend, remote_repo, generation)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS external_intent (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    mirror       TEXT NOT NULL REFERENCES external_mirror(local_task_id),
    kind         TEXT NOT NULL CHECK (kind IN ('comment','transition','close')),
    body         TEXT,
    state        TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','delivered','refused')),
    attempts     INTEGER NOT NULL DEFAULT 0,
    last_error   TEXT,
    created_at   TEXT NOT NULL,
    delivered_at TEXT
  )`);
  // v21 (merge grant): merge authority as explicit fields on the
  // publication grant (cross-column rule merge=1 → merge_method lives in
  // savePublicationGrant + a trigger — additive ALTER cannot carry it),
  // plus the observation/intent/blocker tables shared with fresh SCHEMA.
  addColumn(db, "publication_grant", "merge", "INTEGER NOT NULL DEFAULT 0 CHECK (merge IN (0, 1))");
  addColumn(db, "publication_grant", "merge_method", "TEXT CHECK (merge_method IN ('squash','merge','rebase'))");
  addColumn(db, "publication_grant", "merge_delete_branch", "INTEGER NOT NULL DEFAULT 0 CHECK (merge_delete_branch IN (0, 1))");
  db.exec(`CREATE TABLE IF NOT EXISTS ci_observation (
    github_repo TEXT NOT NULL,
    pr_number   INTEGER NOT NULL,
    head_sha    TEXT NOT NULL,
    state       TEXT NOT NULL CHECK (state IN ('passing','failing','running','none')),
    generation  INTEGER NOT NULL,
    observed_at TEXT NOT NULL,
    PRIMARY KEY (github_repo, pr_number)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS merge_intent (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    publication   INTEGER NOT NULL UNIQUE REFERENCES publication(id),
    grant_terms_hash TEXT NOT NULL,
    head_sha      TEXT NOT NULL,
    method        TEXT NOT NULL CHECK (method IN ('squash','merge','rebase')),
    delete_branch INTEGER NOT NULL DEFAULT 0 CHECK (delete_branch IN (0, 1)),
    state         TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','claimed','merged','refused','superseded')),
    claimed_by    TEXT,
    claimed_until TEXT,
    generation    INTEGER NOT NULL DEFAULT 0,
    attempts      INTEGER NOT NULL DEFAULT 0,
    last_error    TEXT,
    receipt       TEXT,
    created_at    TEXT NOT NULL,
    settled_at    TEXT,
    CHECK (state <> 'claimed' OR (claimed_by IS NOT NULL AND claimed_until IS NOT NULL))
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS merge_blocker (
    publication INTEGER NOT NULL UNIQUE REFERENCES publication(id),
    reason      TEXT NOT NULL CHECK (reason IN ('repair-open')),
    task_id     TEXT,
    created_at  TEXT NOT NULL
  )`);
  // v23 (arc 3, the phone): the push surface. Two NEW tables (their own
  // indexes may ride beside them — the whole tables are new) plus two
  // additive notification columns stamped by producers: a closed
  // attention class and a machine-minted console link. Kinds without a
  // class never push.
  addColumn(db, "notification", "push_class", "TEXT CHECK (push_class IN ('decision','pick','merge','attention'))");
  addColumn(db, "notification", "link", "TEXT");
  db.exec(`CREATE TABLE IF NOT EXISTS push_subscription (
    id                        INTEGER PRIMARY KEY AUTOINCREMENT,
    endpoint                  TEXT NOT NULL,
    p256dh                    TEXT NOT NULL,
    auth                      TEXT NOT NULL,
    approver                  TEXT NOT NULL,
    approver_generation       INTEGER NOT NULL,
    ua_words                  TEXT NOT NULL,
    vapid_fingerprint         TEXT NOT NULL,
    starts_after_notification INTEGER NOT NULL,
    created_at                TEXT NOT NULL,
    last_ok_at                TEXT,
    consecutive_failures      INTEGER NOT NULL DEFAULT 0,
    retired_at                TEXT,
    retired_reason            TEXT
  )`);
  db.exec(`CREATE UNIQUE INDEX IF NOT EXISTS push_subscription_live
    ON push_subscription (endpoint) WHERE retired_at IS NULL`);
  db.exec(`CREATE TABLE IF NOT EXISTS push_delivery (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    notification     INTEGER NOT NULL REFERENCES notification(id) ON DELETE CASCADE,
    subscription     INTEGER NOT NULL REFERENCES push_subscription(id) ON DELETE CASCADE,
    state            TEXT NOT NULL DEFAULT 'pending'
                       CHECK (state IN ('pending','claimed','accepted','rejected','undeliverable','retired')),
    claim_owner      TEXT,
    claim_expires_at TEXT,
    claim_generation INTEGER NOT NULL DEFAULT 0,
    attempts         INTEGER NOT NULL DEFAULT 0,
    next_attempt_at  TEXT,
    last_error       TEXT,
    created_at       TEXT NOT NULL,
    accepted_at      TEXT,
    UNIQUE (notification, subscription),
    CHECK (state <> 'claimed' OR (claim_owner IS NOT NULL AND claim_expires_at IS NOT NULL))
  )`);
  db.exec(`CREATE INDEX IF NOT EXISTS push_delivery_due
    ON push_delivery (state, next_attempt_at) WHERE state IN ('pending','claimed')`);

  // v22 (arc 1, the live window): operator steering notes. A NEW table —
  // additive, identical to the fresh SCHEMA; its partial pending index
  // lives in openStore's post-migration block (the v11c lesson).
  db.exec(`CREATE TABLE IF NOT EXISTS task_steer (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
    author        TEXT NOT NULL,
    note          TEXT NOT NULL,
    created_at    TEXT NOT NULL,
    attached_run  INTEGER REFERENCES run(id),
    attached_at   TEXT,
    delivered_at  TEXT,
    superseded_at TEXT,
    CHECK ((attached_run IS NULL) = (attached_at IS NULL)),
    CHECK (delivered_at IS NULL OR attached_run IS NOT NULL)
  )`);

  // v24 (Parity II foundations): the execution-profile columns, added with
  // LEGACY defaults — an existing row is grandfathered/unverified until the
  // data pass below classifies it; every new INSERT writes these columns
  // explicitly, so a road that forgets fails closed into the legacy label.
  addColumn(db, "task_scope", "profile_json", "TEXT");
  addColumn(db, "task_scope", "profile_state", "TEXT NOT NULL DEFAULT 'resolved'");
  addColumn(db, "task_scope", "unresolved_reason", "TEXT");
  addColumn(db, "task_scope", "approved_profile_json", "TEXT");
  addColumn(db, "task_scope", "digest_version", "INTEGER NOT NULL DEFAULT 1");
  addColumn(db, "task_scope", "profile_provenance", "TEXT");
  addColumn(db, "routine", "profile_json", "TEXT");
  addColumn(db, "routine", "approved_profile_json", "TEXT");
  addColumn(db, "routine", "digest_version", "INTEGER NOT NULL DEFAULT 1");
  addColumn(db, "routine", "profile_provenance", "TEXT");
  addColumn(db, "contest", "race_semantics", "INTEGER NOT NULL DEFAULT 1");
  addColumn(db, "contestant", "profile_json", "TEXT");
  addColumn(db, "run", "scope_digest", "TEXT");
  addColumn(db, "run", "profile_digest", "TEXT");
  addColumn(db, "run", "provider_version", "TEXT");
  addColumn(db, "task_steer", "authorship_state", "TEXT NOT NULL DEFAULT 'unverified-legacy'");
  addColumn(db, "task_steer", "superseded_reason", "TEXT");
  // The v24 DATA pass runs exactly once — on a database whose stored
  // version predates it. A fresh database (no version row yet) has
  // nothing to classify, and a v24 database must never be re-classified:
  // a freshly approved routine with no profile column YET would otherwise
  // be "grandfathered" by its own migration on the next open.
  // The version the file was AT when this upgrade began (v48 authority repair): openStore
  // has already negated it into the epoch sentinel, and a sentinel resumed
  // after a crash is negative too — so the ORIGIN is the magnitude, never
  // the sign. Read as a plain comparison, −47 < 24 re-ran the v24 data
  // pass on every upgrade from v24 onward and on every resumed epoch.
  // The origin arrives from the one strict preflight reader (raw
  // authority repair) — never re-read leniently here, mid-DDL.
  if (origin !== null && origin < 24) migrateToV24(db);

  // v25 (attended core): two shape rebuilds, each recognized exactly and
  // idempotent, ordered AFTER every addColumn above so the only pre-v25
  // shape they ever see is the full v24 one. The three new tables arrive
  // through the fresh SCHEMA's IF NOT EXISTS (the v8 routines precedent);
  // their foreign keys into `run` survive the rename-swap by name, and the
  // rebuild's own foreign_key_check proves it.
  rebuildForV4(
    db,
    "run",
    "'built','failed','refused','parked','no-change'",
    "'interrupted'",
    V25_RUN_DDL("run_next"),
    V25_RUN_COLUMNS,
  );
  rebuildDecisionForV25(db);

  // v26 (attested runtime): phase_config's provider CHECK gains 'gemini'.
  rebuildPhaseConfigForV26(db);

  // v27 (labeled comparisons): tournament_terms gains kind + kind-aware
  // money CHECKs (a rebuild — the old positive-budget CHECKs live in the
  // DDL); contest gains the denormalized kind additively.
  addColumn(db, "contest", "kind", "TEXT NOT NULL DEFAULT 'race' CHECK (kind IN ('race','comparison'))");
  rebuildTournamentTermsForV27(db);

  // v28 (parallel attended sessions): the one-held-session-per-runner
  // bound is withdrawn — parallelism is many tasks, each with its own
  // signed envelope; per-task and per-run singulars all stay.
  db.exec("DROP INDEX IF EXISTS one_held_session_per_runner");

  // v29 (operating modes + the reviewer role + multi-user): additive
  // columns FIRST (round-4 ordering), then the exact-recognizer rebuilds.
  // The four new tables arrive through the fresh SCHEMA's IF NOT EXISTS.
  addColumn(db, "approver", "role", "TEXT NOT NULL DEFAULT 'approver' CHECK (role IN ('approver','viewer'))");
  addColumn(db, "approver", "revoked_at", "TEXT");
  addColumn(db, "approver", "revoked_by", "TEXT");
  addColumn(db, "attended_authorization", "authority_basis", "TEXT NOT NULL DEFAULT 'password' CHECK (authority_basis IN ('password','mode'))");
  addColumn(db, "attended_authorization", "mode_digest", "TEXT");
  addColumn(db, "task_scope", "approval_basis", "TEXT");
  addColumn(db, "task_scope", "mode_digest", "TEXT");
  addColumn(db, "diff_comment", "reviewer_run", "INTEGER REFERENCES run(id)");
  // review_request arrives whole by IF NOT EXISTS; these cover a file
  // that created the table before basis/mode_digest existed. FAIL CLOSED
  // on that upgrade (Codex reviewer round 2, finding 1): a pre-typed open
  // request queued by a mode would default to basis 'human' and survive
  // the mode's revocation — and legacy display strings are ambiguous with
  // human names, so NO open pre-typed request keeps its authority. Spent
  // as 'legacy-untyped'; a person simply asks again.
  const preTypedRequests = tableExists(db, "review_request") && !hasColumn(db, "review_request", "basis");
  addColumn(db, "review_request", "basis", "TEXT NOT NULL DEFAULT 'human' CHECK (basis IN ('human','mode'))");
  addColumn(db, "review_request", "mode_digest", "TEXT");
  if (preTypedRequests) {
    db.exec(
      `UPDATE review_request SET consumed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), consumed_reason = 'legacy-untyped' WHERE consumed_at IS NULL`,
    );
  }
  addColumn(db, "diff_comment", "severity", "TEXT CHECK (severity IN ('note','question','problem'))");
  addColumn(db, "task_ref", "plan_provider", "TEXT");
  addColumn(db, "task_ref", "plan_model", "TEXT");
  addColumn(db, "merge_blocker", "lifted_at", "TEXT");
  addColumn(db, "merge_blocker", "lifted_by", "TEXT");
  rebuildRunForV29(db);
  rebuildPhaseConfigForV29(db);
  rebuildMergeIntentForV29(db);
  rebuildMergeBlockerForV29(db);

  // v30 (fallback chains): additive columns on top of the v29 shapes; the
  // three new tables (fallback_cycle, fallback_transition) + the quota
  // identity rebuild arrive through the fresh SCHEMA's IF NOT EXISTS on a
  // fresh DB, and here on an upgrade. Quota needs a RECOGNIZED rebuild (its
  // PK changes) — additive columns cannot change a primary key.
  // v31 (MCP gateway): the coordinator linkage column; the three new
  // tables arrive through the fresh SCHEMA's IF NOT EXISTS on both roads.
  addColumn(db, "task_ref", "coordinator_cid", "TEXT REFERENCES coordinator_credential(cid)");
  addColumn(db, "task_scope", "proposed_chain_json", "TEXT");
  addColumn(db, "task_scope", "approved_chain_json", "TEXT");
  addColumn(db, "task_scope", "approval_kind", "TEXT NOT NULL DEFAULT 'profile' CHECK (approval_kind IN ('profile','chain'))");
  addColumn(db, "run", "chain_cycle", "INTEGER REFERENCES fallback_cycle(id)");
  addColumn(db, "run", "chain_index", "INTEGER");
  addColumn(db, "run", "entry_digest", "TEXT");
  addColumn(db, "run", "auth_mode", "TEXT");
  addColumn(db, "run", "terminal_class", "TEXT");
  rebuildQuotaForV30(db);
  // v34 (scout tasks, Telegram digests): the deliverable column is
  // additive; three CHECK widenings — run.role admits 'scout' (an exact
  // recognizer over the v29+v30 shape), artifact.kind admits 'report',
  // incident.kind admits 'malformed-report' (the recorded copy-rename
  // recipe, with the FULL current column sets). telegram_digest arrives
  // through the fresh SCHEMA's IF NOT EXISTS. The attention indexes are
  // re-created after migration, as always.
  addColumn(db, "task_ref", "deliverable", "TEXT NOT NULL DEFAULT 'branch' CHECK (deliverable IN ('branch','report'))");
  rebuildRunForV34(db);
  rebuildArtifactForV34(db);
  rebuildIncidentForV34(db);

  // v38 (verified done): artifact.kind admits 'proof','check-log','screenshot';
  // incident.kind admits 'malformed-proof' — both exact recognizers over the
  // v34 shape (the same CHECK widening recipe, one generation later).
  // verify_command, proof_verdict, and proof_acceptance are wholly new
  // tables and arrive through the fresh SCHEMA's IF NOT EXISTS on both roads.
  rebuildArtifactForV38(db);
  rebuildIncidentForV38(db);

  // v39 (Acceptance Contract v2): purely additive, no CHECK widening, no
  // table rebuild — a nullable column an absent value reads back as `[]`
  // from, which is exactly the golden-digest grandfathering this migration
  // promises: every row from before this code existed keeps the digest it
  // already has.
  addColumn(db, "task_scope", "acceptance_json", "TEXT");
  addColumn(db, "routine", "acceptance_json", "TEXT");
  addColumn(db, "proof_verdict", "matrix_json", "TEXT");

  // v40 (evidence-review-v1): purely additive, no CHECK widening, no table
  // rebuild. machine_verdict is a nullable column on the existing
  // proof_verdict table; criterion_review and repair_chain are wholly new
  // tables and arrive through the fresh SCHEMA's IF NOT EXISTS on both
  // roads — nothing here rewrites a row that predates this migration.
  addColumn(db, "proof_verdict", "machine_verdict", "TEXT");
  // The review BINDING columns (audit hardening, still evidence-review-v1):
  // the fresh criterion_review DDL was widened by seven hash-bound input
  // columns (scope_digest, head_sha, proof_artifact, proof_sha,
  // check_log_artifact, check_log_sha, screenshots_json) UNDER THE SAME
  // schema version — so a database that already carried the ten-column
  // table kept it through IF NOT EXISTS, and ingestReview's INSERT failed
  // on it with "table criterion_review has no column named scope_digest"
  // (run 1507). Additive, in-version, idempotent: every column arrives
  // exactly as the fresh DDL declares it, every existing row keeps its ten
  // values byte for byte, and a row from before the hardening reads back
  // UNBOUND — NULL bindings, an empty screenshot list — which is the truth
  // about it: nothing is backfilled, because no evidence of what that
  // reviewer was shown exists to bind. A file already at this build's
  // version takes the same road on its next plain open; nothing else about
  // it moves.
  addColumn(db, "criterion_review", "scope_digest", "TEXT");
  addColumn(db, "criterion_review", "head_sha", "TEXT");
  addColumn(db, "criterion_review", "proof_artifact", "INTEGER");
  addColumn(db, "criterion_review", "proof_sha", "TEXT");
  addColumn(db, "criterion_review", "check_log_artifact", "INTEGER");
  addColumn(db, "criterion_review", "check_log_sha", "TEXT");
  addColumn(db, "criterion_review", "screenshots_json", "TEXT NOT NULL DEFAULT '[]'");
  // v51 (inherited review context): the context inventory binding, additive
  // and NULL on every judgement recorded before a run could carry one.
  addColumn(db, "criterion_review", "context_artifact", "INTEGER");
  addColumn(db, "criterion_review", "context_sha", "TEXT");

  // v41 (two quality modes): additive and backwards-compatible. Default
  // deliberately means the historical workflow; only an explicitly strict
  // scope changes its digest and queues the isolated semantic reviewer.
  addColumn(db, "task_ref", "quality_mode", "TEXT CHECK (quality_mode IN ('default','strict'))");
  addColumn(db, "task_scope", "quality_mode", "TEXT NOT NULL DEFAULT 'default' CHECK (quality_mode IN ('default','strict'))");
  addColumn(db, "run", "quality_mode", "TEXT NOT NULL DEFAULT 'default' CHECK (quality_mode IN ('default','strict'))");

  // v42 (dependency repair): the mate may propose one explicit, confirmed
  // repair — retry the failed blocker, replace the edge, or unlink it. This
  // widens only the proposal CHECK; the dependency primitives remain the
  // authority and re-prove live graph state when the card is confirmed.
  rebuildMateProposalForV42(db);
  db.exec("CREATE INDEX IF NOT EXISTS mate_proposal_thread ON mate_proposal (thread, state)");

  // v43 (task companion): chat may draft one operator steering note. The
  // note remains inert until the operator confirms its card; the existing
  // credentialed steering primitive is still the only write authority.
  rebuildMateProposalForV43(db);
  db.exec("CREATE INDEX IF NOT EXISTS mate_proposal_thread ON mate_proposal (thread, state)");

  // v44 (adaptive execution plans): plan_revision and run_checkpoint are
  // wholly new tables and arrive through the fresh SCHEMA's IF NOT EXISTS.
  // `run` gains two nullable columns naming the exact plan revision and
  // authority snapshot a build's brief was constructed from — additive,
  // null on every run from before this migration. `hold`'s owner_kind CHECK
  // is WIDENED to admit 'revision': the pause an authority-changing
  // proposal places while it awaits an operator, lifted by that operator's
  // accept or reject act exactly like a decision hold is lifted by
  // answering it.
  addColumn(db, "run", "plan_revision", "INTEGER REFERENCES plan_revision(id)");
  addColumn(db, "run", "authority_digest", "TEXT");
  rebuildForV4(
    db,
    "hold",
    "'operator','decision','incident','backoff','contest'",
    "'revision'",
    `CREATE TABLE hold_next (
       id         INTEGER PRIMARY KEY AUTOINCREMENT,
       task_ref   INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
       owner_kind TEXT NOT NULL CHECK (owner_kind IN ('operator','decision','incident','backoff','contest','revision')),
       owner_id   TEXT NOT NULL,
       reason     TEXT NOT NULL,
       until      TEXT,
       held_at    TEXT NOT NULL,
       UNIQUE (owner_kind, owner_id)
     )`,
    ["id", "task_ref", "owner_kind", "owner_id", "reason", "until", "held_at"],
  );

  // v45 (bounded environment recovery): older verification approvals keep
  // their exact authority. Only a newly confirmed verify row may bind the
  // digest of an already-approved setup command for one recovery replay.
  addColumn(db, "verify_command", "recovery_setup_digest", "TEXT");

  // v46 (structured-output repair): preserve every planner/reviewer reply
  // involved in a bounded correction as sealed evidence. This is a CHECK
  // widening, using the same exact-recognizer copy/rename discipline as
  // v34 and v38; no historical row changes meaning.
  rebuildArtifactForV46(db);

  // v47 (explainable risk-aware phase routing): additive columns only, the
  // v41 quality precedent verbatim — every historical scope reads back as
  // routine risk with no route, digests exactly as it did, and its sealed
  // profile remains the whole authority for its build. The three new
  // tables arrive by IF NOT EXISTS on fresh and upgraded files alike.
  addColumn(db, "task_ref", "risk_level", "TEXT CHECK (risk_level IN ('routine','elevated','high'))");
  addColumn(db, "task_ref", "route_overrides_json", "TEXT");
  addColumn(db, "task_scope", "risk_level", "TEXT NOT NULL DEFAULT 'routine' CHECK (risk_level IN ('routine','elevated','high'))");
  addColumn(db, "task_scope", "proposed_route_json", "TEXT");
  addColumn(db, "task_scope", "approved_route_json", "TEXT");
  // The route ERA: NULL on every row that existed before this migration —
  // the one durable proof that a scope predates routing — and set by every
  // saveScope since. Never backfilled.
  addColumn(db, "task_scope", "route_era", "INTEGER");
  // v69: a prepared commit the machine installs as the attempt, no agent.
  addColumn(db, "task_scope", "candidate", "TEXT");
  addColumn(db, "review_request", "route_digest", "TEXT");

  // v48 (routing authority): a routine freezes its four-role agent route
  // at filing and approval seals it — two additive columns, NULL on every
  // routine that predates this migration (such a routine cannot fire again
  // until approved afresh, in words). Chat may propose one confirmed agent
  // change, so `agents` joins the proposal kinds through the same exact,
  // row-preserving copy-rename every earlier widening used.
  addColumn(db, "routine", "route_json", "TEXT");
  addColumn(db, "routine", "approved_route_json", "TEXT");
  rebuildMateProposalForV48(db);
  rebuildMateProposalForV60(db);
  rebuildMateProposalForV66(db);
  db.exec("CREATE INDEX IF NOT EXISTS mate_proposal_thread ON mate_proposal (thread, state)");

  // v49: reviews have no task claim. Bind watch-owned reviews explicitly so
  // takeover can recover them without closing concurrent cron reviews.
  // Historical rows remain unbound; never infer custody from timestamps.
  addColumn(db, "run", "watch_incarnation", "TEXT");

  // v50 (bounded review retries): two additive columns, one exact data
  // pass, one index replacement. `run.review_attempt` is the root
  // reviewer's ordinal for its source run (1..REVIEW_ROOT_ATTEMPTS; NULL on
  // a correction child and on every other role);
  // `review_request.reviewer_run` binds a spent request to the root that
  // answered it. The data pass runs exactly once, on a file whose stored
  // version predates v50 (the v24 precedent — the origin is the magnitude
  // of the epoch sentinel, so a resumed upgrade runs it again, and it is
  // idempotent). v29's one_review_per_source partial unique is dropped
  // here and replaced by the four exact backstops in the post-migration
  // index block; every historical row, id, outcome, comment, judgement,
  // and evidence binding is left byte for byte as it was.
  addColumn(db, "run", "review_attempt", "INTEGER");
  addColumn(db, "review_request", "reviewer_run", "INTEGER REFERENCES run(id)");
  if (origin !== null && origin < 50) migrateToV50(db);
  db.exec("DROP INDEX IF EXISTS one_review_per_source");
  // v50 (explicit-only retries): `review_request.origin` says how an ask
  // was produced — the column and its one classification pass arrive
  // together, in one write transaction (migrateReviewRequestOrigin).
  migrateReviewRequestOrigin(db);

  // v51 (preserve the filed planning contract): artifact.kind additionally
  // admits 'plan-contract' — the planner's recorded source and its
  // ingestion record. The same exact-recognizer copy/rename as v46; no
  // historical row changes meaning.
  rebuildArtifactForV51(db);

  // v52 (safe task stop and resume): `run_stop` is a wholly new table and
  // arrives through the fresh SCHEMA's IF NOT EXISTS. `hold`'s owner_kind
  // CHECK is WIDENED to admit 'stop' — the pause an exact attempt's stop
  // places, lifted only by resuming that attempt — through the same
  // exact-recognizer copy/rename v44 used for 'revision'. No historical
  // row changes meaning.
  rebuildForV4(
    db,
    "hold",
    "'operator','decision','incident','backoff','contest','revision'",
    "'stop'",
    `CREATE TABLE hold_next (
       id         INTEGER PRIMARY KEY AUTOINCREMENT,
       task_ref   INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
       owner_kind TEXT NOT NULL CHECK (owner_kind IN ('operator','decision','incident','backoff','contest','revision','stop')),
       owner_id   TEXT NOT NULL,
       reason     TEXT NOT NULL,
       until      TEXT,
       held_at    TEXT NOT NULL,
       UNIQUE (owner_kind, owner_id)
     )`,
    ["id", "task_ref", "owner_kind", "owner_id", "reason", "until", "held_at"],
  );

  // v61: legacy rows remain unknown, including previously delivered rows.
  // No text/link parsing can turn historical content into authorization.
  addColumn(db, "notification", "provenance_scope", "TEXT NOT NULL DEFAULT 'unknown' CHECK (provenance_scope IN ('unknown','installation','project','task'))");
  addColumn(db, "notification", "project", "TEXT");
  addColumn(db, "notification", "task_ref", "INTEGER REFERENCES task_ref(id)");
  addColumn(db, "notification", "task_id", "TEXT");
  addColumn(db, "notification", "source_run", "INTEGER REFERENCES run(id)");

  // v62 (Telegram conversation): a stop confirmed from a paired phone is
  // recorded as exactly that. The audit CHECK admits 'telegram' through the
  // exact-recognizer rebuild; every v52 row, id and settlement is carried
  // whole, and an unknown shape refuses rather than being guessed.
  rebuildRunStopForV62(db);
  rebuildSlackAuditForV67(db);
  rebuildDiscordAuditForV68(db);
  rebuildTeamsAuditForV74(db);

  // v64 (result screenshots on demand): telegram_conversation_part admits
  // 'image' and carries typed media identity through the same exact-
  // recognizer copy/rename; every v63 reply and card row, its message id,
  // attempts and uncertain count is carried whole. mate_turn_evidence is a
  // wholly new table and arrives through the fresh SCHEMA's IF NOT EXISTS.
  rebuildTelegramConversationPartForV64(db);

  // v53 (OS containment and login recovery): four additive, nullable
  // columns on run_process. A legacy witness has NULL in all four, which
  // every reader treats as "unknown boot, observed containment" — the
  // conservative road it already took. No historical row changes meaning.
  addColumn(db, "run_process", "boot_id", "TEXT");
  addColumn(db, "run_process", "containment", "TEXT");
  addColumn(db, "run_process", "container", "TEXT");
  addColumn(db, "run_process", "container_empty_at", "TEXT");
  addColumn(db, "run_process", "container_identity", "TEXT");

  // v85 (sort steps): flow_step_run's kind CHECK admits 'sort', and a new
  // nullable decision_json keeps what Jev answered. The same exact-
  // recognizer copy/rename; every v84 check and update run is carried whole.
  rebuildForV4(
    db,
    "flow_step_run",
    "CHECK (kind IN ('check','update'))",
    "'sort'",
    `CREATE TABLE flow_step_run_next (
       card           INTEGER NOT NULL REFERENCES flow_card(id),
       entry          INTEGER NOT NULL,
       stage          TEXT NOT NULL,
       kind           TEXT NOT NULL CHECK (kind IN ('check','update','sort')),
       script         TEXT,
       script_version INTEGER,
       state          TEXT NOT NULL CHECK (state IN ('running','passed','failed','waiting')),
       attempts       INTEGER NOT NULL DEFAULT 0,
       next_at        TEXT,
       started_at     TEXT NOT NULL,
       finished_at    TEXT,
       duration_ms    INTEGER,
       exit_code      INTEGER,
       result         TEXT,
       log            TEXT,
       decision_json  TEXT,
       PRIMARY KEY (card, entry)
     )`,
    ["card", "entry", "stage", "kind", "script", "script_version", "state", "attempts", "next_at", "started_at", "finished_at", "duration_ms", "exit_code", "result", "log", "decision_json"],
  );
  db.exec("CREATE INDEX IF NOT EXISTS flow_step_run_recent ON flow_step_run (started_at)");

  // v86 (draft steps): kind admits 'draft' through the same copy/rename,
  // carrying every v85 run whole.
  rebuildForV4(
    db,
    "flow_step_run",
    "CHECK (kind IN ('check','update','sort'))",
    "'draft'",
    `CREATE TABLE flow_step_run_next (
       card           INTEGER NOT NULL REFERENCES flow_card(id),
       entry          INTEGER NOT NULL,
       stage          TEXT NOT NULL,
       kind           TEXT NOT NULL CHECK (kind IN ('check','update','sort','draft')),
       script         TEXT,
       script_version INTEGER,
       state          TEXT NOT NULL CHECK (state IN ('running','passed','failed','waiting')),
       attempts       INTEGER NOT NULL DEFAULT 0,
       next_at        TEXT,
       started_at     TEXT NOT NULL,
       finished_at    TEXT,
       duration_ms    INTEGER,
       exit_code      INTEGER,
       result         TEXT,
       log            TEXT,
       decision_json  TEXT,
       PRIMARY KEY (card, entry)
     )`,
    ["card", "entry", "stage", "kind", "script", "script_version", "state", "attempts", "next_at", "started_at", "finished_at", "duration_ms", "exit_code", "result", "log", "decision_json"],
  );
  db.exec("CREATE INDEX IF NOT EXISTS flow_step_run_recent ON flow_step_run (started_at)");

  // v87 (steps that reach outside): kind admits 'request', 'email' and
  // 'tool', carrying every v86 run whole.
  rebuildForV4(
    db,
    "flow_step_run",
    "CHECK (kind IN ('check','update','sort','draft'))",
    "'request'",
    `CREATE TABLE flow_step_run_next (
       card           INTEGER NOT NULL REFERENCES flow_card(id),
       entry          INTEGER NOT NULL,
       stage          TEXT NOT NULL,
       kind           TEXT NOT NULL CHECK (kind IN ('check','update','sort','draft','request','email','tool')),
       script         TEXT,
       script_version INTEGER,
       state          TEXT NOT NULL CHECK (state IN ('running','passed','failed','waiting')),
       attempts       INTEGER NOT NULL DEFAULT 0,
       next_at        TEXT,
       started_at     TEXT NOT NULL,
       finished_at    TEXT,
       duration_ms    INTEGER,
       exit_code      INTEGER,
       result         TEXT,
       log            TEXT,
       decision_json  TEXT,
       PRIMARY KEY (card, entry)
     )`,
    ["card", "entry", "stage", "kind", "script", "script_version", "state", "attempts", "next_at", "started_at", "finished_at", "duration_ms", "exit_code", "result", "log", "decision_json"],
  );
  db.exec("CREATE INDEX IF NOT EXISTS flow_step_run_recent ON flow_step_run (started_at)");

  // v94 (teammate tools): a visit may hold several questions — one of its own,
  // and one per ask-first tool call — so the (card, entry) uniqueness moves to
  // partial indexes. Every question is carried whole, with its id.
  rebuildForV4(
    db,
    "teammate_question",
    "UNIQUE (card, entry)",
    "tool_call     INTEGER",
    `CREATE TABLE teammate_question_next (
       id            INTEGER PRIMARY KEY AUTOINCREMENT,
       teammate      INTEGER NOT NULL REFERENCES teammate(id),
       card          INTEGER NOT NULL REFERENCES flow_card(id),
       entry         INTEGER NOT NULL,
       question      TEXT NOT NULL,
       options_json  TEXT NOT NULL,
       asked_of      TEXT NOT NULL,
       state         TEXT NOT NULL CHECK (state IN ('open','answered','dropped')),
       choice        TEXT,
       answer        TEXT,
       answered_by   TEXT,
       answered_via  TEXT,
       answered_at   TEXT,
       created_at    TEXT NOT NULL,
       tool_call     INTEGER REFERENCES teammate_call(id),
       suggestion    INTEGER REFERENCES teammate_suggestion(id)
     )`,
    ["id", "teammate", "card", "entry", "question", "options_json", "asked_of", "state", "choice", "answer", "answered_by", "answered_via", "answered_at", "created_at", "tool_call", "suggestion"],
  );
  // v99: the action ledger admits sign-in and policy events, each with a short detail.
  rebuildLedgerForV99(db);
  // v101: a coordinator credential's expiry (null: made before expiry existed, until renewed).
  addColumn(db, "coordinator_credential", "expires_at", "TEXT");
  // v102: who filed a task (a person, or the person a coordinator acts for; null when no person is known) and what kind of filer.
  addColumn(db, "task_ref", "filed_by", "TEXT");
  addColumn(db, "task_ref", "filed_by_kind", "TEXT");
  // v102: who made a standing order (its instances are filed as theirs).
  addColumn(db, "routine", "created_by", "TEXT");
  // v98: where Telegram pushes this bot's updates, as the bridge last found it.
  addColumn(db, "bridge_lease", "push_url", "TEXT");
  addColumn(db, "bridge_lease", "push_at", "TEXT");
  addColumn(db, "bridge_lease", "push_problem", "TEXT");
  // v96: a teammate's desk flow.
  addColumn(db, "teammate", "desk_flow", "INTEGER REFERENCES flow(id)");
  // v97: its weekly report, and undoing its tool calls.
  addColumn(db, "teammate", "weekly_at", "TEXT");
  addColumn(db, "teammate_call", "undo_of", "INTEGER REFERENCES teammate_call(id)");
  addColumn(db, "teammate_call", "undone_by", "TEXT");
  addColumn(db, "teammate_call", "undone_at", "TEXT");
  // v95: a rule-change suggestion is a question too (to the manager, about the card that prompted it), never the visit's own question.
  addColumn(db, "teammate_question", "suggestion", "INTEGER REFERENCES teammate_suggestion(id)");
  if (/WHERE tool_call IS NULL\s*$/.test(String(db.prepare("SELECT sql FROM sqlite_master WHERE type = 'index' AND name = 'teammate_question_visit'").get()?.["sql"] ?? ""))) db.exec("DROP INDEX teammate_question_visit");
  db.exec("CREATE UNIQUE INDEX IF NOT EXISTS teammate_question_visit ON teammate_question (card, entry) WHERE tool_call IS NULL AND suggestion IS NULL");
  db.exec("CREATE UNIQUE INDEX IF NOT EXISTS teammate_question_suggestion ON teammate_question (suggestion) WHERE suggestion IS NOT NULL");
  // v95: what people told a teammate (v92 notes) becomes its memory, once: the join line stays in its log.
  // (Only when there are notes: even an INSERT that copies nothing starts the table's sqlite_sequence row, and a reopen must change nothing.)
  if (Number(db.prepare("SELECT COUNT(*) AS n FROM teammate_memory").get()?.["n"] ?? 0) === 0
    && db.prepare("SELECT 1 AS hit FROM teammate_event WHERE kind = 'note' AND said NOT LIKE '% onto the team.' LIMIT 1").get() !== undefined) {
    db.exec(`INSERT INTO teammate_memory (teammate, text, source, card, state, created_by, created_at, updated_by, updated_at)
      SELECT teammate, said, 'person', NULL, 'active', COALESCE(by, 'someone'), at, COALESCE(by, 'someone'), at FROM teammate_event
      WHERE kind = 'note' AND said NOT LIKE '% onto the team.' ORDER BY id`);
  }
  db.exec("CREATE UNIQUE INDEX IF NOT EXISTS teammate_question_call ON teammate_question (tool_call) WHERE tool_call IS NOT NULL");
  db.exec("CREATE INDEX IF NOT EXISTS teammate_question_open ON teammate_question (card, entry, state)");

  // v92 (teammates): kind admits 'teammate', carrying every v87 run whole.
  rebuildForV4(
    db,
    "flow_step_run",
    "CHECK (kind IN ('check','update','sort','draft','request','email','tool'))",
    "'teammate'",
    `CREATE TABLE flow_step_run_next (
       card           INTEGER NOT NULL REFERENCES flow_card(id),
       entry          INTEGER NOT NULL,
       stage          TEXT NOT NULL,
       kind           TEXT NOT NULL CHECK (kind IN ('check','update','sort','draft','request','email','tool','teammate')),
       script         TEXT,
       script_version INTEGER,
       state          TEXT NOT NULL CHECK (state IN ('running','passed','failed','waiting')),
       attempts       INTEGER NOT NULL DEFAULT 0,
       next_at        TEXT,
       started_at     TEXT NOT NULL,
       finished_at    TEXT,
       duration_ms    INTEGER,
       exit_code      INTEGER,
       result         TEXT,
       log            TEXT,
       decision_json  TEXT,
       PRIMARY KEY (card, entry)
     )`,
    ["card", "entry", "stage", "kind", "script", "script_version", "state", "attempts", "next_at", "started_at", "finished_at", "duration_ms", "exit_code", "result", "log", "decision_json"],
  );
  db.exec("CREATE INDEX IF NOT EXISTS flow_step_run_recent ON flow_step_run (started_at)");

  // v89 (inbox triggers): kind admits 'email' and 'chat', carrying every
  // trigger whole (its id, so flow_trigger_event keeps pointing at it).
  rebuildForV4(
    db,
    "flow_trigger",
    "CHECK (kind IN ('button','schedule','github','linear','flow','webhook'))",
    "'email'",
    `CREATE TABLE flow_trigger_next (
       id           INTEGER PRIMARY KEY AUTOINCREMENT,
       flow         INTEGER NOT NULL REFERENCES flow(id),
       kind         TEXT NOT NULL CHECK (kind IN ('button','schedule','github','linear','flow','webhook','email','chat')),
       config_json  TEXT NOT NULL,
       state        TEXT NOT NULL CHECK (state IN ('active','paused','removed')),
       hook_hash    TEXT UNIQUE,
       cursor       TEXT,
       next_at      TEXT,
       last_at      TEXT,
       last_outcome TEXT,
       failures     INTEGER NOT NULL DEFAULT 0,
       created_by   TEXT NOT NULL,
       created_at   TEXT NOT NULL,
       updated_at   TEXT NOT NULL
     )`,
    ["id", "flow", "kind", "config_json", "state", "hook_hash", "cursor", "next_at", "last_at", "last_outcome", "failures", "created_by", "created_at", "updated_at"],
  );
  db.exec("CREATE INDEX IF NOT EXISTS flow_trigger_live ON flow_trigger (flow, state)");
}

/** The origin CHECK, verbatim from the fresh review_request DDL. */
const REVIEW_REQUEST_ORIGIN_DEFINITION = "TEXT NOT NULL DEFAULT 'operator' CHECK (origin IN ('operator','automatic'))";

/**
 * The v50 provenance pass (explicit-only retries): `review_request.origin`
 * arrives together with its one classification, atomically. On a file from
 * before the column, a mode-basis row was by definition automatic; a
 * human-basis row was either an operator's ask or the Strict / release
 * producer's, and the two are byte-identical — so an OPEN human-basis ask
 * that would already be a retry (its source carries a root attempt) cannot
 * be proved to be a fresh operator act, and is spent as 'legacy-origin'
 * rather than admitted on a guess (the v29 legacy-untyped precedent: a
 * person simply asks again). Consumed rows keep their words; nothing is
 * ever admitted from them.
 *
 * THE COLUMN IS THE MARK THAT THE PASS RAN, so the ALTER and the two
 * UPDATEs commit as one unit or not at all: an interruption after the
 * column was added, between the classification writes, or before the
 * commit rolls the column back with them, and the next open runs the whole
 * pass again (fault injection, review-retry dogfood: an ALTER committed on
 * its own left a replayed Strict retry open as an operator's ask, and it
 * admitted attempt 2). The presence check is repeated INSIDE the write
 * lock: a second opener that waited on BEGIN IMMEDIATE for the first
 * migrator finds the column already there and classifies nothing — an
 * operator ask queued after the first migrator committed is not a legacy
 * row, and a repeated pass would have spent it as one.
 */
function migrateReviewRequestOrigin(db: Database): void {
  if (!tableExists(db, "review_request") || hasColumn(db, "review_request", "origin")) return;
  db.exec("BEGIN IMMEDIATE");
  try {
    if (!hasColumn(db, "review_request", "origin")) {
      db.exec(`ALTER TABLE review_request ADD COLUMN origin ${REVIEW_REQUEST_ORIGIN_DEFINITION}`);
      db.exec("UPDATE review_request SET origin = 'automatic' WHERE basis = 'mode'");
      db.exec(
        `UPDATE review_request SET consumed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), consumed_reason = 'legacy-origin'
          WHERE consumed_at IS NULL AND basis = 'human'
            AND EXISTS (SELECT 1 FROM run WHERE run.parent_run = review_request.run AND run.role = 'reviewer' AND run.review_attempt IS NOT NULL)`,
      );
    }
    db.exec("COMMIT");
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
}

/** The bounded review-retry law (v50): a source run takes at most this
 * many ROOT reviewer attempts, ever — the first ask plus two explicit
 * retries. Correction children (the same-session structured-output
 * repairs) are not attempts; they continue one. */
export const REVIEW_ROOT_ATTEMPTS = 3;

/** The one reading of a request row's production (v50, explicit-only
 * retries): a mode-basis ask is automatic whatever its origin column says
 * — the column is the strict-scope producer's only durable mark, the
 * basis is the mode's. */
function reviewRequestOriginOf(row: Record<string, unknown>): ReviewRequestOrigin {
  return String(row["basis"]) === "mode" || String(row["origin"] ?? "operator") === "automatic" ? "automatic" : "operator";
}

/**
 * The v50 data pass: every existing root reviewer (a reviewer whose parent
 * is NOT a reviewer) becomes attempt 1 of its source — v49's
 * one_review_per_source guaranteed there was never more than one — and
 * each such root is bound to the one request v49's admission spent on it.
 * The binding is derived only from the one-to-one relation v29..v49
 * guaranteed (a request consumed by an admission was stamped
 * `dispatched`, then `reviewed`, `reviewer-…`, or `interrupted`; every
 * other consumed reason spent a request WITHOUT a run). A root with no
 * such request stays unbound — an omission recorded as one, never a
 * guess. A source run whose history contradicts that relation (two roots,
 * or two run-bearing requests for one root) is a shape this migration
 * cannot prove, and the upgrade refuses in words rather than binding a
 * retry allowance to it.
 */
function migrateToV50(db: Database): void {
  if (!tableExists(db, "run") || !tableExists(db, "review_request")) return;
  db.exec("BEGIN IMMEDIATE");
  try {
    const roots = db
      .prepare(
        `SELECT reviewer.id AS id, reviewer.parent_run AS source, reviewer.review_attempt AS attempt
           FROM run AS reviewer
           JOIN run AS parent ON parent.id = reviewer.parent_run
          WHERE reviewer.role = 'reviewer' AND parent.role <> 'reviewer'
          ORDER BY reviewer.id`,
      )
      .all() as { id: number | bigint; source: number | bigint; attempt: number | bigint | null }[];
    const bySource = new Map<number, number[]>();
    for (const root of roots) {
      const list = bySource.get(Number(root.source)) ?? [];
      list.push(Number(root.id));
      bySource.set(Number(root.source), list);
    }
    for (const [source, ids] of bySource) {
      if (ids.length > 1) {
        throw new Error(`run #${source} carries ${ids.length} root reviewer runs (#${ids.join(", #")}) — a shape v49 never wrote; refusing to assign review attempts to it`);
      }
    }
    const bind = db.prepare("UPDATE run SET review_attempt = 1 WHERE id = ? AND review_attempt IS NULL");
    const spent = db.prepare(
      `SELECT id FROM review_request
        WHERE run = ? AND consumed_at IS NOT NULL
          AND (consumed_reason = 'dispatched' OR consumed_reason = 'reviewed' OR consumed_reason = 'interrupted' OR consumed_reason LIKE 'reviewer-%')
        ORDER BY id`,
    );
    const link = db.prepare("UPDATE review_request SET reviewer_run = ? WHERE id = ? AND reviewer_run IS NULL");
    for (const root of roots) {
      if (root.attempt === null || root.attempt === undefined) bind.run(Number(root.id));
      const requests = spent.all(Number(root.source)) as { id: number | bigint }[];
      if (requests.length > 1) {
        throw new Error(`run #${Number(root.source)} spent ${requests.length} review requests on one reviewer run (#${Number(root.id)}) — a shape v49 never wrote; refusing to bind a retry allowance to it`);
      }
      if (requests.length === 1) link.run(Number(root.id), Number(requests[0]!.id));
    }
    db.exec("COMMIT");
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
}

/** The v17 artifact shape — what every v17..v33 database carries (the
 * fresh DDL canonicalizes to it too). */
function V17_ARTIFACT_DDL(name: string): string {
  return `CREATE TABLE ${name} (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
    kind           TEXT NOT NULL CHECK (kind IN ('diff','status','park-payload','plan','terminal-diff','diff-stat','handoff','revision-brief','base-tree')),
    key            TEXT NOT NULL,
    bytes_original INTEGER NOT NULL,
    bytes_stored   INTEGER NOT NULL,
    truncated      INTEGER NOT NULL DEFAULT 0,
    sha256         TEXT NOT NULL,
    capture        TEXT NOT NULL,
    created_at     TEXT NOT NULL,
    redacted       INTEGER NOT NULL DEFAULT 0,
    capture_status TEXT CHECK (capture_status IN ('ok','failed'))
  )`;
}
function V34_ARTIFACT_DDL(name: string): string {
  return V17_ARTIFACT_DDL(name).replace("'revision-brief','base-tree'", "'revision-brief','base-tree','report'");
}
const ARTIFACT_COLUMNS = ["id", "run", "kind", "key", "bytes_original", "bytes_stored", "truncated", "sha256", "capture", "created_at", "redacted", "capture_status"] as const;

/** The v7 incident shape — every v7..v33 database, and the fresh DDL. */
function V7_INCIDENT_DDL(name: string): string {
  return `CREATE TABLE ${name} (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    run         INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
    kind        TEXT NOT NULL CHECK (kind IN ('malformed-decision','attempts-exhausted','commit-failure','malformed-plan','plan-attempts-exhausted')),
    created_at  TEXT NOT NULL,
    resolved_at TEXT,
    resolved_by TEXT
  )`;
}
function V34_INCIDENT_DDL(name: string): string {
  return V7_INCIDENT_DDL(name).replace("'plan-attempts-exhausted'", "'plan-attempts-exhausted','malformed-report'");
}
const INCIDENT_COLUMNS = ["id", "run", "kind", "created_at", "resolved_at", "resolved_by"] as const;

/** v38: artifact.kind additionally admits 'proof','check-log','screenshot'. */
function V38_ARTIFACT_DDL(name: string): string {
  return V34_ARTIFACT_DDL(name).replace("'revision-brief','base-tree','report'", "'revision-brief','base-tree','report','proof','check-log','screenshot'");
}

/** v46: raw planner/reviewer protocol attempts become first-class evidence. */
function V46_ARTIFACT_DDL(name: string): string {
  return V38_ARTIFACT_DDL(name).replace("'proof','check-log','screenshot'", "'proof','check-log','screenshot','structured-output'");
}

/** v51: the planner's recorded source and plan-contract record are evidence. */
function V51_ARTIFACT_DDL(name: string): string {
  return V46_ARTIFACT_DDL(name).replace("'screenshot','structured-output'", "'screenshot','structured-output','plan-contract','review-context'");
}

/** v38: incident.kind additionally admits 'malformed-proof'. */
function V38_INCIDENT_DDL(name: string): string {
  return V34_INCIDENT_DDL(name).replace("'plan-attempts-exhausted','malformed-report'", "'plan-attempts-exhausted','malformed-report','malformed-proof'");
}

/**
 * One exact copy-rename (v4 review, finding 7 — substrings are not
 * recognizers): the stored DDL must equal the known old shape or the
 * target, canonicalized; anything else refuses. Rows and ids are carried
 * whole; foreign keys are checked before commit.
 */
function rebuildExact(
  db: Database,
  table: string,
  oldDdl: ((name: string) => string) | readonly ((name: string) => string)[],
  targetDdl: (name: string) => string,
  columns: readonly string[],
): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?").get(table);
  if (row === undefined) return;
  const stored = canonicalDdl(String(row["sql"]));
  if (stored === canonicalDdl(targetDdl(table))) return;
  const predecessors = typeof oldDdl === "function" ? [oldDdl] : oldDdl;
  if (!predecessors.some(ddl => stored === canonicalDdl(ddl(table)))) {
    throw new Error(`the ${table} table's DDL is not a shape this migration knows — refusing to rebuild it`);
  }
  db.exec("PRAGMA foreign_keys = OFF");
  try {
    db.exec("BEGIN IMMEDIATE");
    try {
      // The AUTOINCREMENT bookkeeping, read before the copy (v51): a
      // drop-and-rename moves the table's sqlite_sequence row to the end
      // and resets its counter to the surviving max id. Both are restored
      // below — the original counter (never reusing an id a deleted row
      // once held) in the original row order — so an upgraded file's
      // bookkeeping is byte for byte what the predecessor wrote.
      const sequenceBefore = tableExists(db, "sqlite_sequence")
        ? (db.prepare("SELECT name, seq FROM sqlite_sequence ORDER BY rowid").all() as { name: string; seq: number | bigint }[])
        : [];
      db.exec(targetDdl(`${table}_next`));
      const names = columns.join(", ");
      db.exec(`INSERT INTO ${table}_next (${names}) SELECT ${names} FROM ${table}`);
      db.exec(`DROP TABLE ${table}`);
      db.exec(`ALTER TABLE ${table}_next RENAME TO ${table}`);
      if (sequenceBefore.some(row => row.name === table)) {
        db.exec("DELETE FROM sqlite_sequence");
        const restore = db.prepare("INSERT INTO sqlite_sequence (name, seq) VALUES (?, ?)");
        // Bound as INTEGER (a JS number would land as REAL in this untyped
        // system table and read back as a different type).
        for (const row of sequenceBefore) restore.run(row.name, typeof row.seq === "bigint" ? row.seq : BigInt(row.seq));
      } else if (tableExists(db, "sqlite_sequence")) {
        // Copying an empty AUTOINCREMENT table can mint a zero counter.
        // Preserve the absence of bookkeeping the predecessor never wrote.
        db.prepare("DELETE FROM sqlite_sequence WHERE name = ?").run(table);
      }
      const broken = db.prepare("PRAGMA foreign_key_check").all();
      if (broken.length > 0) throw new Error(`foreign keys did not survive the ${table} rebuild`);
      db.exec("COMMIT");
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  } finally {
    db.exec("PRAGMA foreign_keys = ON");
  }
}

function readApiToken(row: Record<string, unknown>): ApiTokenRow {
  const text = (key: string) => row[key] == null ? null : String(row[key]);
  return { id: String(row["id"]), account: String(row["account"]), name: String(row["name"]), access: row["access"] === "act" ? "act" : "read", createdAt: String(row["created_at"]), createdBy: String(row["created_by"]),
    expiresAt: String(row["expires_at"]), lastUsedAt: text("last_used_at"), revokedAt: text("revoked_at"), revokedBy: text("revoked_by") };
}

function readWebSession(row: Record<string, unknown>): WebSessionRow {
  return { idHash: String(row["id_hash"]), account: String(row["account"]), csrf: String(row["csrf"]), role: row["role"] === "viewer" ? "viewer" : "approver", generation: Number(row["generation"]),
    createdAt: Number(row["created_at"]), lastSeen: Number(row["last_seen"]), project: row["project"] == null ? null : String(row["project"]), projectRevision: Number(row["project_revision"]),
    ssoAt: row["sso_at"] == null ? null : Number(row["sso_at"]), agent: row["agent"] == null ? null : String(row["agent"]), address: row["address"] == null ? null : String(row["address"]) };
}

/**
 * v99: the ledger's source admits 'sign-in' and 'policy', and each row may
 * carry a short detail. The work triggers on other tables write into the
 * ledger, and a rename refuses while a trigger points at a table that's gone,
 * so every trigger naming it is dropped first; openStore puts them back
 * (LEDGER_SCHEMA and installLedgerTriggers run after migration).
 */
function rebuildLedgerForV99(db: Database): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'action_ledger'").get();
  if (row === undefined || canonicalDdl(String(row["sql"])) === canonicalDdl(LEDGER_TABLE("action_ledger"))) return;
  for (const trigger of db.prepare("SELECT name FROM sqlite_master WHERE type = 'trigger' AND sql LIKE '%action_ledger%'").all()) {
    db.exec(`DROP TRIGGER IF EXISTS "${String(trigger["name"]).replace(/"/g, '""')}"`);
  }
  rebuildExact(db, "action_ledger", LEDGER_V54_TABLE, LEDGER_TABLE, LEDGER_V54_COLUMNS);
}

/** v34: artifact.kind admits 'report'. A table already rebuilt to the v38
 * shape (migrate() runs unconditionally on every open, including a fresh
 * database created straight at the current shape) is a DONE shape too —
 * the same "old-shape-plus-later-widening" recognizer rebuildRunForV29
 * uses for V34_RUN_DDL. */
export function rebuildArtifactForV34(db: Database): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'artifact'").get();
  if (
    row !== undefined &&
    [V38_ARTIFACT_DDL("artifact"), V46_ARTIFACT_DDL("artifact"), V51_ARTIFACT_DDL("artifact")].some(ddl => canonicalDdl(String(row["sql"])) === canonicalDdl(ddl))
  ) return;
  rebuildExact(db, "artifact", V17_ARTIFACT_DDL, V34_ARTIFACT_DDL, ARTIFACT_COLUMNS);
}

/** v34: incident.kind admits 'malformed-report'. Same v38-shape tolerance as rebuildArtifactForV34. */
export function rebuildIncidentForV34(db: Database): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'incident'").get();
  if (row !== undefined && canonicalDdl(String(row["sql"])) === canonicalDdl(V38_INCIDENT_DDL("incident"))) return;
  rebuildExact(db, "incident", V7_INCIDENT_DDL, V34_INCIDENT_DDL, INCIDENT_COLUMNS);
}

/** v38: artifact.kind admits 'proof','check-log','screenshot'. */
export function rebuildArtifactForV38(db: Database): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'artifact'").get();
  if (
    row !== undefined &&
    [V46_ARTIFACT_DDL("artifact"), V51_ARTIFACT_DDL("artifact")].some(ddl => canonicalDdl(String(row["sql"])) === canonicalDdl(ddl))
  ) return;
  rebuildExact(db, "artifact", [V17_ARTIFACT_DDL, V34_ARTIFACT_DDL], V38_ARTIFACT_DDL, ARTIFACT_COLUMNS);
}

/** v46: artifact.kind additionally admits structured-output. A table
 * already at the v51 shape is a DONE shape (migrate() runs every step on
 * every open). */
export function rebuildArtifactForV46(db: Database): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'artifact'").get();
  if (row !== undefined && canonicalDdl(String(row["sql"])) === canonicalDdl(V51_ARTIFACT_DDL("artifact"))) return;
  rebuildExact(db, "artifact", V38_ARTIFACT_DDL, V46_ARTIFACT_DDL, ARTIFACT_COLUMNS);
}

/** v51: artifact.kind additionally admits plan-contract and review-context. */
export function rebuildArtifactForV51(db: Database): void {
  rebuildExact(db, "artifact", V46_ARTIFACT_DDL, V51_ARTIFACT_DDL, ARTIFACT_COLUMNS);
}

/** v38: incident.kind admits 'malformed-proof'. */
export function rebuildIncidentForV38(db: Database): void {
  rebuildExact(db, "incident", [V7_INCIDENT_DDL, V34_INCIDENT_DDL], V38_INCIDENT_DDL, INCIDENT_COLUMNS);
}

/** The v34 run shape: 'scout' joins the roles, and the v30 columns sit
 * inline before the table CHECK (where ALTER put them on older files). */
function V34_RUN_DDL(name: string): string {
  return V29_RUN_DDL(name)
    .replace("'builder','repair','planner','reviewer'", "'builder','repair','planner','reviewer','scout'")
    .replace(
      "    handoff       TEXT,\n    CHECK",
      "    handoff       TEXT,\n    chain_cycle INTEGER REFERENCES fallback_cycle(id), chain_index INTEGER, entry_digest TEXT, auth_mode TEXT, terminal_class TEXT,\n    CHECK",
    );
}

/** v41 is an additive column after every run-table rebuild. SQLite inserts
 * the new column immediately before the table CHECK, so the exact recognizers
 * must admit that known final shape on later opens without weakening to
 * substring checks. */
function V34_RUN_PLUS_V41_DDL(name: string): string {
  return V34_RUN_DDL(name).replace(
    "    chain_cycle INTEGER REFERENCES fallback_cycle(id), chain_index INTEGER, entry_digest TEXT, auth_mode TEXT, terminal_class TEXT,\n    CHECK",
    "    chain_cycle INTEGER REFERENCES fallback_cycle(id), chain_index INTEGER, entry_digest TEXT, auth_mode TEXT, terminal_class TEXT, quality_mode TEXT NOT NULL DEFAULT 'default' CHECK (quality_mode IN ('default','strict')),\n    CHECK",
  );
}

/** v44: plan_revision and authority_digest are additive columns after every
 * run-table rebuild, exactly like v41's quality_mode — SQLite inserts each
 * new column immediately before the table CHECK, so this known final shape
 * must be admitted by name wherever the run table's shape is recognized. */
function V34_RUN_PLUS_V41_PLUS_V44_DDL(name: string): string {
  return V34_RUN_PLUS_V41_DDL(name).replace(
    " quality_mode TEXT NOT NULL DEFAULT 'default' CHECK (quality_mode IN ('default','strict')),\n    CHECK",
    " quality_mode TEXT NOT NULL DEFAULT 'default' CHECK (quality_mode IN ('default','strict')), plan_revision INTEGER REFERENCES plan_revision(id), authority_digest TEXT,\n    CHECK",
  );
}

function V49_RUN_DDL(name: string): string {
  return V34_RUN_PLUS_V41_PLUS_V44_DDL(name).replace(
    " authority_digest TEXT,\n    CHECK",
    " authority_digest TEXT, watch_incarnation TEXT,\n    CHECK",
  );
}

/** v50: review_attempt is one more additive column after every run-table
 * rebuild — the same known final shape rule as v41, v44, and v49. */
function V50_RUN_DDL(name: string): string {
  return V49_RUN_DDL(name).replace(
    " watch_incarnation TEXT,\n    CHECK",
    " watch_incarnation TEXT, review_attempt INTEGER,\n    CHECK",
  );
}

const V34_RUN_COLUMNS = [
  "id", "task_ref", "lease_id", "runner", "scope_digest", "profile_digest", "provider_version", "role", "provider",
  "parent_run", "session_id", "base_revision", "branch", "worktree", "model", "phase", "contestant", "outcome",
  "reason", "committed", "attended_authorization", "started_at", "finished_at", "provider_started_at", "tokens_in",
  "tokens_out", "cost_usd", "usage_json", "head_revision", "handoff", "chain_cycle", "chain_index", "entry_digest",
  "auth_mode", "terminal_class",
] as const;

/**
 * v34: run.role admits 'scout'. An EXACT recognizer, like v29's and v33's:
 * the stored DDL must be the v29+v30 shape (either placement of the v30
 * columns is the same shape) or already v34; anything else refuses rather
 * than being guessed. Rows and ids are carried whole; foreign keys are
 * checked before commit; the indexes return with the post-migration block.
 */
export function rebuildRunForV34(db: Database): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'run'").get();
  if (row === undefined) return;
  const stored = canonicalDdl(String(row["sql"]));
  if (
    stored === canonicalDdl(V34_RUN_DDL("run")) ||
    stored === canonicalDdl(V34_RUN_PLUS_V41_DDL("run")) ||
    stored === canonicalDdl(V34_RUN_PLUS_V41_PLUS_V44_DDL("run")) ||
    stored === canonicalDdl(V49_RUN_DDL("run")) ||
    stored === canonicalDdl(V50_RUN_DDL("run"))
  ) return;
  if (stored !== canonicalDdl(V29_RUN_PLUS_V30_COLS_DDL)) {
    throw new Error("the run table's DDL is not a shape this migration knows — refusing to rebuild it");
  }
  db.exec("PRAGMA foreign_keys = OFF");
  try {
    db.exec("BEGIN IMMEDIATE");
    try {
      db.exec(V34_RUN_DDL("run_next"));
      const names = V34_RUN_COLUMNS.join(", ");
      db.exec(`INSERT INTO run_next (${names}) SELECT ${names} FROM run`);
      db.exec("DROP TABLE run");
      db.exec("ALTER TABLE run_next RENAME TO run");
      const broken = db.prepare("PRAGMA foreign_key_check").all();
      if (broken.length > 0) throw new Error("foreign keys did not survive the run rebuild");
      db.exec("COMMIT");
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  } finally {
    db.exec("PRAGMA foreign_keys = ON");
  }
}

/** v30: quota's PRIMARY KEY grows auth_mode + credential_fp (a subscription
 * and an API key exhaust independently). A PK change is a rebuild, not an
 * addColumn; recognized exactly like every other v-rebuild. */
const MATE_PROPOSAL_V32_DDL = `CREATE TABLE IF NOT EXISTS mate_proposal (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  thread         INTEGER NOT NULL REFERENCES mate_thread(id) ON DELETE CASCADE,
  turn           INTEGER NOT NULL,
  kind           TEXT NOT NULL CHECK (kind IN ('task','next','reserve','hold','unhold','scope','cancel')),
  payload_json   TEXT NOT NULL,
  ceiling_digest TEXT NOT NULL,
  state          TEXT NOT NULL CHECK (state IN ('drafting','pending','confirming','confirmed','refused','dismissed','expired')),
  created_at     TEXT NOT NULL,
  resolved_at    TEXT,
  resolved_by    TEXT,
  outcome_json   TEXT
)`;
const MATE_PROPOSAL_V33_DDL = (name: string): string => `CREATE TABLE ${name} (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  thread         INTEGER NOT NULL REFERENCES mate_thread(id) ON DELETE CASCADE,
  turn           INTEGER NOT NULL,
  kind           TEXT NOT NULL CHECK (kind IN ('task','next','reserve','hold','unhold','scope','cancel','answer')),
  payload_json   TEXT NOT NULL,
  ceiling_digest TEXT NOT NULL,
  state          TEXT NOT NULL CHECK (state IN ('drafting','pending','confirming','confirmed','refused','dismissed','expired')),
  created_at     TEXT NOT NULL,
  resolved_at    TEXT,
  resolved_by    TEXT,
  outcome_json   TEXT
)`;
const MATE_PROPOSAL_V42_DDL = (name: string): string =>
  MATE_PROPOSAL_V33_DDL(name).replace("'cancel','answer'", "'cancel','answer','repair'");
const MATE_PROPOSAL_V43_DDL = (name: string): string =>
  MATE_PROPOSAL_V42_DDL(name).replace("'hold','unhold'", "'hold','unhold','steer'");
const MATE_PROPOSAL_V48_DDL = (name: string): string =>
  MATE_PROPOSAL_V43_DDL(name).replace("'answer','repair'", "'answer','repair','agents'");
const MATE_PROPOSAL_V60_DDL = (name: string): string =>
  MATE_PROPOSAL_V48_DDL(name).replace("'agents'", "'agents','review','control','task_action'");

const MATE_PROPOSAL_V66_DDL = (name: string): string =>
  MATE_PROPOSAL_V60_DDL(name).replace("'task_action'", "'task_action','action'");

export function rebuildMateProposalForV66(db: Database): void {
  rebuildExact(db, "mate_proposal", MATE_PROPOSAL_V60_DDL, MATE_PROPOSAL_V66_DDL,
    ["id", "thread", "turn", "kind", "payload_json", "ceiling_digest", "state", "created_at", "resolved_at", "resolved_by", "outcome_json"]);
  db.exec("CREATE INDEX IF NOT EXISTS mate_proposal_thread ON mate_proposal (thread, state)");
}

const RUN_STOP_V52_DDL = (name: string): string => `CREATE TABLE ${name} (
  run           INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
  requested_by  TEXT NOT NULL,
  requested_via TEXT NOT NULL CHECK (requested_via IN ('cli','web')),
  requested_at  TEXT NOT NULL,
  settled_at    TEXT,
  settlement    TEXT CHECK (settlement IN ('interrupted','recovered','held','finished')),
  resumed_at    TEXT,
  resumed_by    TEXT,
  resumed_via   TEXT CHECK (resumed_via IN ('cli','web')),
  CHECK ((settled_at IS NULL) = (settlement IS NULL)),
  CHECK (resumed_at IS NULL OR settled_at IS NOT NULL),
  CHECK ((resumed_at IS NULL) = (resumed_by IS NULL))
)`;
const RUN_STOP_V62_DDL = (name: string): string =>
  RUN_STOP_V52_DDL(name).replace("requested_via IN ('cli','web')", "requested_via IN ('cli','web','telegram')").replace("resumed_via IN ('cli','web')", "resumed_via IN ('cli','web','telegram')");


const DECISION_V66_DDL = (name: string): string => `CREATE TABLE ${name} (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
  urgency        TEXT NOT NULL CHECK (urgency IN ('blocking')),
  state          TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open','expired','answered')),
  recap          TEXT NOT NULL,
  question       TEXT NOT NULL,
  options        TEXT NOT NULL,
  recommendation TEXT NOT NULL,
  assignee       TEXT,
  -- Attention metadata only. A deadline is never a hold expiry: a blocking
  -- decision that goes overdue becomes 'expired' and MORE visible, not a
  -- task that quietly dispatches itself unanswered.
  deadline       TEXT,
  created_at     TEXT NOT NULL,
  answered_at    TEXT,
  answered_by    TEXT,
  -- Which racing agent asked (v14); lets one-open-question-per-agent be a
  -- real database rule instead of a hope (finding 28). NULL = ordinary.
  contestant     INTEGER REFERENCES contestant(id),
  -- Typed closure (v14): 'excluded' = the operator stopped the asking
  -- agent instead of answering. Never a fake option.
  closed_reason  TEXT CHECK (closed_reason IN ('excluded')),
  answered_via   TEXT CHECK (answered_via IN ('cli','web','telegram')),
  choice         TEXT,
  note           TEXT,
  -- v25 held-session linkage. session_turn = the turn whose settlement
  -- produced this park (causal, held runs only). delivered_turn = the
  -- answer turn that claimed delivery into the live session — the
  -- delivery-CAS target: set once (WHERE delivered_turn IS NULL), reverted
  -- only when that turn terminally never reached acceptance.
  session_turn   INTEGER REFERENCES session_turn(id),
  delivered_turn INTEGER REFERENCES session_turn(id)
)`;
const DECISION_V67_DDL = (name: string): string => DECISION_V66_DDL(name).replace("'cli','web','telegram'", "'cli','web','telegram','slack'");
const RUN_STOP_V67_DDL = (name: string): string => RUN_STOP_V62_DDL(name).replaceAll("'cli','web','telegram'", "'cli','web','telegram','slack'");
const DECISION_V68_DDL = (name:string):string => DECISION_V67_DDL(name).replace("'cli','web','telegram','slack'", "'cli','web','telegram','slack','discord'");
const RUN_STOP_V68_DDL = (name:string):string => RUN_STOP_V67_DDL(name).replaceAll("'cli','web','telegram','slack'", "'cli','web','telegram','slack','discord'");
/** v74: Microsoft Teams joins the recorded surfaces a stop or an answer names. */
export const DECISION_V74_DDL = (name:string):string => DECISION_V68_DDL(name).replace("'cli','web','telegram','slack','discord'", "'cli','web','telegram','slack','discord','teams'");
export const RUN_STOP_V74_DDL = (name:string):string => RUN_STOP_V68_DDL(name).replaceAll("'cli','web','telegram','slack','discord'", "'cli','web','telegram','slack','discord','teams'");
function isTeamsAudit(db:Database,table:"decision"|"run_stop"):boolean {
 const row=db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name=?").get(table);
 return row!==undefined&&canonicalDdl(String(row.sql))===canonicalDdl((table==="decision"?DECISION_V74_DDL:RUN_STOP_V74_DDL)(table));
}
export function rebuildTeamsAuditForV74(db:Database):void {
 if(!isTeamsAudit(db,"decision")) rebuildExact(db,"decision",DECISION_V68_DDL,DECISION_V74_DDL,["id","run","urgency","state","recap","question","options","recommendation","assignee","deadline","created_at","answered_at","answered_by","contestant","closed_reason","answered_via","choice","note","session_turn","delivered_turn"]);
 if(!isTeamsAudit(db,"run_stop")) rebuildExact(db,"run_stop",RUN_STOP_V68_DDL,RUN_STOP_V74_DDL,["run","task_ref","requested_by","requested_via","requested_at","settled_at","settlement","resumed_at","resumed_by","resumed_via"]);
 db.exec("CREATE INDEX IF NOT EXISTS run_stop_by_task ON run_stop (task_ref, requested_at DESC)");
}
function isDiscordAudit(db:Database,table:"decision"|"run_stop"):boolean {
 if(isTeamsAudit(db,table)) return true;
 const row=db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name=?").get(table);
 return row!==undefined&&canonicalDdl(String(row.sql))===canonicalDdl((table==="decision"?DECISION_V68_DDL:RUN_STOP_V68_DDL)(table));
}
export const DECISION_V68_DDL_FOR_TESTS = (name:string):string => DECISION_V68_DDL(name);
export const RUN_STOP_V68_DDL_FOR_TESTS = (name:string):string => RUN_STOP_V68_DDL(name);
export function rebuildDiscordAuditForV68(db:Database):void {
 if(isTeamsAudit(db,"decision")&&isTeamsAudit(db,"run_stop")) return;
 if(!isTeamsAudit(db,"decision")) rebuildExact(db,"decision",DECISION_V67_DDL,DECISION_V68_DDL,["id","run","urgency","state","recap","question","options","recommendation","assignee","deadline","created_at","answered_at","answered_by","contestant","closed_reason","answered_via","choice","note","session_turn","delivered_turn"]);
 if(!isTeamsAudit(db,"run_stop")) rebuildExact(db,"run_stop",RUN_STOP_V67_DDL,RUN_STOP_V68_DDL,["run","task_ref","requested_by","requested_via","requested_at","settled_at","settlement","resumed_at","resumed_by","resumed_via"]);
 db.exec("CREATE INDEX IF NOT EXISTS run_stop_by_task ON run_stop (task_ref, requested_at DESC)");
}
function isSlackAudit(db: Database, table: "decision" | "run_stop"): boolean {
  if(isDiscordAudit(db,table)) return true;
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name=?").get(table);
  return row !== undefined && canonicalDdl(String(row.sql)) === canonicalDdl((table === "decision" ? DECISION_V67_DDL : RUN_STOP_V67_DDL)(table));
}
export function rebuildSlackAuditForV67(db: Database): void {
  if(!isDiscordAudit(db,"decision")) rebuildExact(db, "decision", DECISION_V66_DDL, DECISION_V67_DDL,
    ["id","run","urgency","state","recap","question","options","recommendation","assignee","deadline","created_at","answered_at","answered_by","contestant","closed_reason","answered_via","choice","note","session_turn","delivered_turn"]);
  if(!isDiscordAudit(db,"run_stop")) rebuildExact(db, "run_stop", RUN_STOP_V62_DDL, RUN_STOP_V67_DDL,
    ["run","task_ref","requested_by","requested_via","requested_at","settled_at","settlement","resumed_at","resumed_by","resumed_via"]);
  db.exec("CREATE INDEX IF NOT EXISTS run_stop_by_task ON run_stop (task_ref, requested_at DESC)");
}

const TELEGRAM_CONVERSATION_PART_V63_DDL = (name: string): string => `CREATE TABLE ${name} (
  conversation    INTEGER NOT NULL REFERENCES telegram_conversation(id) ON DELETE CASCADE,
  ordinal         INTEGER NOT NULL,
  kind            TEXT NOT NULL CHECK (kind IN ('reply','card')),
  text            TEXT NOT NULL,
  reply_to        TEXT,
  proposal        INTEGER REFERENCES mate_proposal(id) ON DELETE SET NULL,
  keyboard_json   TEXT,
  state           TEXT NOT NULL CHECK (state IN ('pending','sent','dropped')),
  message_id      TEXT,
  attempts        INTEGER NOT NULL DEFAULT 0,
  uncertain       INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TEXT,
  last_error      TEXT,
  created_at      TEXT NOT NULL,
  sent_at         TEXT,
  PRIMARY KEY (conversation, ordinal),
  CHECK ((state = 'sent') = (message_id IS NOT NULL)),
  CHECK ((state = 'sent') = (sent_at IS NOT NULL))
)`;
const TELEGRAM_CONVERSATION_PART_V64_DDL = (name: string): string => `CREATE TABLE ${name} (
  conversation    INTEGER NOT NULL REFERENCES telegram_conversation(id) ON DELETE CASCADE,
  ordinal         INTEGER NOT NULL,
  kind            TEXT NOT NULL CHECK (kind IN ('reply','card','image')),
  text            TEXT NOT NULL,
  reply_to        TEXT,
  proposal        INTEGER REFERENCES mate_proposal(id) ON DELETE SET NULL,
  keyboard_json   TEXT,
  state           TEXT NOT NULL CHECK (state IN ('pending','sent','dropped')),
  message_id      TEXT,
  attempts        INTEGER NOT NULL DEFAULT 0,
  uncertain       INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TEXT,
  last_error      TEXT,
  created_at      TEXT NOT NULL,
  sent_at         TEXT,
  task_id         TEXT,
  source_run      INTEGER REFERENCES run(id),
  artifact        INTEGER,
  sha256          TEXT,
  PRIMARY KEY (conversation, ordinal),
  CHECK ((state = 'sent') = (message_id IS NOT NULL)),
  CHECK ((state = 'sent') = (sent_at IS NOT NULL)),
  CHECK ((kind = 'image') = (task_id IS NOT NULL AND source_run IS NOT NULL AND artifact IS NOT NULL AND sha256 IS NOT NULL))
)`;
/** The v63 columns, in order: what an upgrade copies, and what a wind-back keeps. */
export const TELEGRAM_CONVERSATION_PART_V63_COLUMNS = ["conversation", "ordinal", "kind", "text", "reply_to", "proposal", "keyboard_json", "state", "message_id", "attempts", "uncertain", "next_attempt_at", "last_error", "created_at", "sent_at"] as const;

