const PHASE_CONFIG_V26_DDL = `CREATE TABLE phase_config_next (
  scope      TEXT NOT NULL,
  phase      TEXT NOT NULL CHECK (phase IN ('plan','build','repair')),
  provider   TEXT NOT NULL CHECK (provider IN ('claude','codex','openrouter','gemini')),
  model      TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  PRIMARY KEY (scope, phase)
)`;

/**
 * The v26 rebuild: phase_config recognized by FULL canonical-DDL equality
 * (sqlite_master's stored form, whitespace-collapsed), rows copied
 * verbatim, refused on any unrecognized shape. Idempotent: the v26 form
 * returns without touching anything.
 */
function rebuildPhaseConfigForV26(db: Database): void {
  const row = db
    .prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'phase_config'")
    .get();
  if (row === undefined) return;
  const stored = canonicalDdl(String(row["sql"]));
  const target = canonicalDdl(PHASE_CONFIG_V26_DDL).replace("phase_config_next", "phase_config");
  if (stored === target) return;
  // A LATER shape is also done: a fresh database is born at the newest
  // DDL, and this earlier rebuild waves it through to v29's own pass.
  if (stored === canonicalDdl(PHASE_CONFIG_V29_DDL).replace("phase_config_next", "phase_config")) return;
  if (stored !== canonicalDdl(PHASE_CONFIG_V25_DDL)) {
    throw new Error("the phase_config table's DDL is not a shape this migration knows — refusing to rebuild it");
  }
  db.exec("PRAGMA foreign_keys = OFF");
  try {
    db.exec("BEGIN IMMEDIATE");
    try {
      db.exec(PHASE_CONFIG_V26_DDL);
      db.exec(
        `INSERT INTO phase_config_next (scope, phase, provider, model, updated_at, updated_by)
         SELECT scope, phase, provider, model, updated_at, updated_by FROM phase_config`,
      );
      db.exec("DROP TABLE phase_config");
      db.exec("ALTER TABLE phase_config_next RENAME TO phase_config");
      db.exec("COMMIT");
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  } finally {
    db.exec("PRAGMA foreign_keys = ON");
  }
}

/**
 * The v24 DATA pass (foundations findings 10/16 + rulings 10/11): runs once
 * per database — idempotent because every UPDATE keys on the legacy state
 * it is classifying away from.
 *
 * - APPROVED scopes/routines (the full predicate: approved_digest equals
 *   the stored digest — reproposal keeps historical approval fields, so
 *   approved_at alone lies) get their EFFECTIVE profile resolved with
 *   today's precedence (pin > project > installation > default) and
 *   snapshotted as the approval profile, GRANDFATHERED (digest untouched,
 *   provenance says so). Unresolvable = profile_state 'unresolved': not
 *   dispatchable, not re-approvable, until restated.
 * - UNAPPROVED scopes get a working profile and their digest RECOMPUTED to
 *   v2 (nothing signed is altered — there is no live approval).
 * - Legacy contestants get per-contestant snapshots under race semantics 1;
 *   stored race fingerprints stay byte-identical.
 * - Every pre-v24 steer note is unverified-legacy (the column default);
 *   UNDELIVERED ones are additionally superseded so they can never enter
 *   a future brief (ruling 11's quarantine).
 */
function migrateToV24(db: Database): void {
  const now = new Date().toISOString();

  // -- steering quarantine ---------------------------------------------
  db.prepare(
    `UPDATE task_steer SET superseded_at = ?, superseded_reason = 'unverified-author'
      WHERE authorship_state = 'unverified-legacy' AND delivered_at IS NULL AND superseded_at IS NULL`,
  ).run(now);

  // -- effective-profile resolution, replicated for raw-db use ----------
  const KNOWN = new Set(["claude", "codex", "openrouter"]);
  const configRow = (scope: string): { provider: string; model: string | null } | null => {
    const row = db.prepare("SELECT provider, model FROM phase_config WHERE scope = ? AND phase = 'build'").get(scope) as
      | { provider: string; model: string | null }
      | undefined;
    return row ?? null;
  };
  const effective = (
    repo: string | null,
    pinProvider: string | null,
    pinModel: string | null,
  ): { ok: true; profile: ExecutionProfile; resolvedFrom: string } | { ok: false; reason: string } => {
    let provider: string | null = null;
    let model: string | null = null;
    let resolvedFrom = "default";
    if (pinProvider !== null) {
      provider = pinProvider;
      model = pinModel;
      resolvedFrom = "pinned";
    } else {
      const row = (repo === null ? null : configRow(repo)) ?? configRow("installation");
      if (row !== null) {
        provider = row.provider;
        model = row.model;
        resolvedFrom = "config";
      } else {
        provider = "claude";
        model = null;
      }
    }
    if (!KNOWN.has(provider)) return { ok: false, reason: `unknown provider \`${provider}\`` };
    if (model === null || model === "") return { ok: false, reason: "no configured model — name one and re-approve" };
    // Legacy effective repair behavior was inherit-the-build-model (flags
    // were per-invocation, never per-task), so "inherit" is the honest pin.
    const profile: ExecutionProfile =
      provider === "claude"
        ? {
            provider: "claude",
            model,
            permissionArgv: "acceptEdits",
            maxTurns: CLAUDE_LIMITS.maxTurns,
            repairMaxTurns: CLAUDE_LIMITS.repairMaxTurns,
            timeoutSeconds: CLAUDE_LIMITS.timeoutSeconds,
            repairTimeoutSeconds: CLAUDE_LIMITS.repairTimeoutSeconds,
            repairModel: "inherit",
          }
        : {
            provider: provider as "codex" | "openrouter",
            model,
            sandboxMode: "workspace-write",
            maxTurns: "unsupported",
            repairMaxTurns: "unsupported",
            timeoutSeconds: CODEX_SHAPED_LIMITS.timeoutSeconds,
            repairTimeoutSeconds: CODEX_SHAPED_LIMITS.repairTimeoutSeconds,
            repairModel: "inherit",
          };
    return { ok: true, profile, resolvedFrom };
  };

  // -- scopes ------------------------------------------------------------
  const scopes = db
    .prepare(
      `SELECT ts.task_id AS taskId, ts.goal, ts.out_of_scope AS outOfScope, ts.touches,
              ts.budget_microusd AS budget, ts.digest, ts.approved_digest AS approvedDigest,
              tr.repo AS repo, tr.agent_provider AS pinProvider, tr.agent_model AS pinModel
         FROM task_scope ts
         LEFT JOIN task_ref tr ON tr.id = (SELECT id FROM task_ref WHERE external_id = ts.task_id ORDER BY id LIMIT 1)
        WHERE ts.profile_json IS NULL AND ts.profile_state = 'resolved' AND ts.approved_profile_json IS NULL`,
    )
    .all() as {
    taskId: string; goal: string; outOfScope: string | null; touches: string;
    budget: number | null; digest: string; approvedDigest: string | null;
    repo: string | null; pinProvider: string | null; pinModel: string | null;
  }[];
  const setUnresolved = db.prepare(
    "UPDATE task_scope SET profile_state = 'unresolved', unresolved_reason = ? WHERE task_id = ?",
  );
  const pinApproved = db.prepare(
    `UPDATE task_scope SET profile_json = ?, approved_profile_json = ?, profile_provenance = ? WHERE task_id = ?`,
  );
  const stampUnapproved = db.prepare(
    `UPDATE task_scope SET profile_json = ?, digest = ?, digest_version = 2, profile_provenance = ? WHERE task_id = ?`,
  );
  for (const row of scopes) {
    const approved = row.approvedDigest !== null && row.approvedDigest === row.digest;
    const resolved = effective(row.repo, row.pinProvider, row.pinModel);
    if (!resolved.ok) {
      setUnresolved.run(resolved.reason, row.taskId);
      continue;
    }
    const snapshot = canonicalProfileJson(resolved.profile);
    const provenance = JSON.stringify({ resolvedFrom: resolved.resolvedFrom, grandfathered: approved, pinnedAt: now });
    if (approved) {
      // digest + digest_version stay EXACTLY as signed (golden-tested).
      pinApproved.run(snapshot, snapshot, provenance, row.taskId);
    } else {
      let touches: string[] = [];
      try { touches = JSON.parse(row.touches) as string[]; } catch { touches = []; }
      const recomputed = digestOf(
        { goal: row.goal, outOfScope: row.outOfScope, touches, budgetMicrousd: row.budget },
        resolved.profile,
      );
      stampUnapproved.run(snapshot, recomputed, provenance, row.taskId);
    }
  }

  // -- routines ----------------------------------------------------------
  const routines = db
    .prepare(
      `SELECT id, repo, digest, approved_digest AS approvedDigest FROM routine
        WHERE profile_json IS NULL AND approved_profile_json IS NULL`,
    )
    .all() as { id: number; repo: string; digest: string; approvedDigest: string | null }[];
  const pinRoutine = db.prepare(
    "UPDATE routine SET profile_json = ?, approved_profile_json = ?, profile_provenance = ? WHERE id = ?",
  );
  const parkRoutine = db.prepare(
    `UPDATE routine SET approved_at = NULL, approved_by = NULL, approved_digest = NULL, next_fire_at = NULL,
            profile_provenance = ? WHERE id = ?`,
  );
  const stampRoutine = db.prepare("UPDATE routine SET profile_json = ?, profile_provenance = ? WHERE id = ?");
  for (const row of routines) {
    const approved = row.approvedDigest !== null && row.approvedDigest === row.digest;
    const resolved = effective(row.repo, null, null);
    if (!resolved.ok) {
      if (approved) {
        // A standing order may not keep firing on floating authority
        // (ruling 10): the approval is demoted, said in provenance; the
        // routines screen shows it pending like any unapproved routine.
        parkRoutine.run(JSON.stringify({ demoted: "profile-unresolved", reason: resolved.reason, at: now }), row.id);
      } else {
        stampRoutine.run(null, JSON.stringify({ unresolved: resolved.reason, at: now }), row.id);
      }
      continue;
    }
    const snapshot = canonicalProfileJson(resolved.profile);
    const provenance = JSON.stringify({ resolvedFrom: resolved.resolvedFrom, grandfathered: approved, pinnedAt: now });
    if (approved) pinRoutine.run(snapshot, snapshot, provenance, row.id);
    else stampRoutine.run(snapshot, provenance, row.id);
  }

  // -- legacy contestants: exact provider/model/repair already stored -----
  const contestants = db
    .prepare("SELECT id, provider, model, repair_model AS repairModel FROM contestant WHERE profile_json IS NULL")
    .all() as { id: number; provider: string; model: string; repairModel: string }[];
  const stampContestant = db.prepare("UPDATE contestant SET profile_json = ? WHERE id = ?");
  for (const row of contestants) {
    if (!KNOWN.has(row.provider)) continue; // stays null; admission keeps byte-comparing v1 fingerprints
    const profile: ExecutionProfile =
      row.provider === "claude"
        ? {
            provider: "claude", model: row.model, permissionArgv: "acceptEdits",
            maxTurns: CLAUDE_LIMITS.maxTurns, repairMaxTurns: CLAUDE_LIMITS.repairMaxTurns,
            timeoutSeconds: CLAUDE_LIMITS.timeoutSeconds, repairTimeoutSeconds: CLAUDE_LIMITS.repairTimeoutSeconds,
            repairModel: row.repairModel,
          }
        : {
            provider: row.provider as "codex" | "openrouter", model: row.model,
            sandboxMode: "workspace-write", maxTurns: "unsupported", repairMaxTurns: "unsupported",
            timeoutSeconds: CODEX_SHAPED_LIMITS.timeoutSeconds, repairTimeoutSeconds: CODEX_SHAPED_LIMITS.repairTimeoutSeconds,
            repairModel: row.repairModel,
          };
    stampContestant.run(canonicalProfileJson(profile), row.id);
  }
}

/** The v4 run shape, shared by the fresh SCHEMA, the M2 rebuild, and the v3→v4 rebuild. */
function V4_RUN_DDL(name: string): string {
  return `CREATE TABLE ${name} (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
    lease_id      TEXT NOT NULL,
    runner        TEXT NOT NULL,
    role          TEXT NOT NULL DEFAULT 'builder' CHECK (role IN ('builder','repair','planner')),
    provider      TEXT NOT NULL DEFAULT 'claude',
    parent_run    INTEGER REFERENCES run(id),
    session_id    TEXT,
    base_revision TEXT,
    branch        TEXT NOT NULL,
    worktree      TEXT NOT NULL,
    model         TEXT,
    phase         TEXT,
    outcome       TEXT CHECK (outcome IN ('built','failed','refused','parked','no-change')),
    reason        TEXT,
    committed     INTEGER,
    started_at    TEXT NOT NULL,
    finished_at   TEXT,
    provider_started_at TEXT,
    tokens_in     INTEGER,
    tokens_out    INTEGER,
    cost_usd      REAL,
    usage_json    TEXT,
    head_revision TEXT,
    handoff       TEXT
  )`;
}

const V4_RUN_COLUMNS = [
  "id", "task_ref", "lease_id", "runner", "role", "provider", "parent_run", "session_id",
  "base_revision", "branch", "worktree", "model", "phase", "outcome", "reason",
  "committed", "started_at", "finished_at", "provider_started_at", "tokens_in",
  "tokens_out", "cost_usd", "usage_json", "head_revision", "handoff",
];

/**
 * The v25 run shape: outcome admits 'interrupted' and the attended
 * authorization stamp arrives. The column list is the FULL v24 set —
 * this rebuild runs after every addColumn in migrate(), so the only
 * pre-v25 shape it ever sees carries all of them, and the intersection
 * copy tolerates an interrupted earlier migration exactly like v4's.
 */
function V25_RUN_DDL(name: string): string {
  return `CREATE TABLE ${name} (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    task_ref      INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
    lease_id      TEXT NOT NULL,
    runner        TEXT NOT NULL,
    scope_digest     TEXT,
    profile_digest   TEXT,
    provider_version TEXT,
    role          TEXT NOT NULL DEFAULT 'builder' CHECK (role IN ('builder','repair','planner')),
    provider      TEXT NOT NULL DEFAULT 'claude',
    parent_run    INTEGER REFERENCES run(id),
    session_id    TEXT,
    base_revision TEXT,
    branch        TEXT NOT NULL,
    worktree      TEXT NOT NULL,
    model         TEXT,
    phase         TEXT,
    contestant    INTEGER REFERENCES contestant(id),
    outcome       TEXT CHECK (outcome IN ('built','failed','refused','parked','no-change','interrupted')),
    reason        TEXT,
    committed     INTEGER,
    attended_authorization TEXT REFERENCES attended_authorization(id),
    started_at    TEXT NOT NULL,
    finished_at   TEXT,
    provider_started_at TEXT,
    tokens_in     INTEGER,
    tokens_out    INTEGER,
    cost_usd      REAL,
    usage_json    TEXT,
    head_revision TEXT,
    handoff       TEXT
  )`;
}

const V25_RUN_COLUMNS = [
  "id", "task_ref", "lease_id", "runner", "scope_digest", "profile_digest",
  "provider_version", "role", "provider", "parent_run", "session_id",
  "base_revision", "branch", "worktree", "model", "phase", "contestant",
  "outcome", "reason", "committed", "attended_authorization", "started_at",
  "finished_at", "provider_started_at", "tokens_in", "tokens_out", "cost_usd",
  "usage_json", "head_revision", "handoff",
];

/**
 * v25: the decision table sheds its one-decision-per-run UNIQUE (a held
 * session parks, is answered, and parks again — many decisions, one run)
 * and gains the held-session linkage columns. Recognized exactly: the only
 * pre-v25 shape is rebuildDecisionVia's output (or the fresh pre-v25
 * SCHEMA, which is byte-compatible on the recognizer fragments); anything
 * else refuses loudly. The one-unresolved-per-run rule moves to a partial
 * unique index in openStore's post-migration block.
 */
function rebuildDecisionForV25(db: Database): void {
  const row = db
    .prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'decision'")
    .get();
  if (row === undefined) return;
  const ddl = String(row["sql"]);
  if (ddl.includes("delivered_turn")) return;
  if (!ddl.includes("UNIQUE REFERENCES run(id)")) {
    throw new Error(
      "the decision table's DDL is not a shape this migration knows — refusing to rebuild it",
    );
  }

  const present = new Set(
    db.prepare("PRAGMA table_info(decision)").all().map(one => String(one["name"])),
  );
  const target = [
    "id", "run", "urgency", "state", "recap", "question", "options",
    "recommendation", "assignee", "deadline", "created_at", "answered_at",
    "answered_by", "contestant", "closed_reason", "answered_via", "choice", "note",
  ];
  const carried = target.filter(column => present.has(column));
  const names = carried.join(", ");

  db.exec("PRAGMA foreign_keys = OFF");
  try {
    db.exec("BEGIN IMMEDIATE");
    try {
      db.exec(
        `CREATE TABLE decision_next (
           id             INTEGER PRIMARY KEY AUTOINCREMENT,
           run            INTEGER NOT NULL REFERENCES run(id) ON DELETE CASCADE,
           urgency        TEXT NOT NULL CHECK (urgency IN ('blocking')),
           state          TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open','expired','answered')),
           recap          TEXT NOT NULL,
           question       TEXT NOT NULL,
           options        TEXT NOT NULL,
           recommendation TEXT NOT NULL,
           assignee       TEXT,
           deadline       TEXT,
           created_at     TEXT NOT NULL,
           answered_at    TEXT,
           answered_by    TEXT,
           contestant     INTEGER REFERENCES contestant(id),
           closed_reason  TEXT CHECK (closed_reason IN ('excluded')),
           answered_via   TEXT CHECK (answered_via IN ('cli','web','telegram')),
           choice         TEXT,
           note           TEXT,
           session_turn   INTEGER REFERENCES session_turn(id),
           delivered_turn INTEGER REFERENCES session_turn(id)
         )`,
      );
      db.exec(`INSERT INTO decision_next (${names}) SELECT ${names} FROM decision`);
      db.exec("DROP TABLE decision");
      db.exec("ALTER TABLE decision_next RENAME TO decision");
      const broken = db.prepare("PRAGMA foreign_key_check").all();
      if (broken.length > 0) {
        throw new Error(`decision rebuild left ${broken.length} dangling foreign key(s)`);
      }
      db.exec("COMMIT");
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  } finally {
    db.exec("PRAGMA foreign_keys = ON");
  }
}

/**
 * One v4 CHECK widening: recognized exactly, refused otherwise. The copy
 * moves the intersection of the target's columns and the columns actually
 * present, so an interrupted earlier migration cannot lose data.
 */
function rebuildForV4(
  db: Database,
  table: string,
  oldFragment: string,
  newFragment: string,
  targetDDL: string,
  targetColumns: readonly string[],
): void {
  const row = db
    .prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?")
    .get(table);
  if (row === undefined) return;
  const ddl = String(row["sql"]);
  if (ddl.includes(newFragment)) return;
  if (!ddl.includes(oldFragment)) {
    throw new Error(`the ${table} table's DDL is not a shape this migration knows — refusing to rebuild it`);
  }

  const present = new Set(
    db.prepare(`PRAGMA table_info(${table})`).all().map(one => String(one["name"])),
  );
  const carried = targetColumns.filter(column => present.has(column));
  const names = carried.join(", ");

  db.exec("PRAGMA foreign_keys = OFF");
  try {
    db.exec("BEGIN IMMEDIATE");
    try {
      // The AUTOINCREMENT bookkeeping (the v51 rebuildExact discipline,
      // applied here for v52's hold widening): a drop-and-rename moves or
      // mints the table's sqlite_sequence row; the rows that stood before
      // are restored in their order and with their counters, and a row
      // the copy minted for a table that had none is removed again.
      const sequenceBefore = tableExists(db, "sqlite_sequence")
        ? (db.prepare("SELECT name, seq FROM sqlite_sequence ORDER BY rowid").all() as { name: string; seq: number | bigint }[])
        : [];
      db.exec(targetDDL);
      db.exec(`INSERT INTO ${table}_next (${names}) SELECT ${names} FROM ${table}`);
      db.exec(`DROP TABLE ${table}`);
      db.exec(`ALTER TABLE ${table}_next RENAME TO ${table}`);
      if (tableExists(db, "sqlite_sequence")) {
        if (sequenceBefore.some(row => row.name === table)) {
          db.exec("DELETE FROM sqlite_sequence");
          const restore = db.prepare("INSERT INTO sqlite_sequence (name, seq) VALUES (?, ?)");
          for (const row of sequenceBefore) restore.run(row.name, typeof row.seq === "bigint" ? row.seq : BigInt(row.seq));
        } else {
          db.prepare("DELETE FROM sqlite_sequence WHERE name = ?").run(table);
        }
      }
      if (table === "hold") db.exec("CREATE INDEX IF NOT EXISTS hold_by_task ON hold (task_ref)");
      const broken = db.prepare("PRAGMA foreign_key_check").all();
      if (broken.length > 0) {
        throw new Error(`${table} rebuild left ${broken.length} dangling foreign key(s)`);
      }
      db.exec("COMMIT");
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  } finally {
    db.exec("PRAGMA foreign_keys = ON");
  }
}

/**
 * v3: decision.answered_via admits 'telegram'. Same copy-rename recipe as
 * rebuild(), but the detection is exact: only the two DDL shapes this
 * project has ever written are recognized, and anything else refuses loudly
 * — a substring guess against somebody's hand-edited schema is how a
 * migration eats a database.
 */
function rebuildDecisionVia(db: Database): void {
  if (isSlackAudit(db, "decision")) return;
  const row = db
    .prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'decision'")
    .get();
  if (row === undefined) return;
  const ddl = String(row["sql"]);
  if (ddl.includes("'cli','web','telegram'")) return;
  if (!ddl.includes("'cli','web'")) {
    throw new Error(
      "the decision table's DDL is not a shape this migration knows — refusing to rebuild it",
    );
  }

  db.exec("PRAGMA foreign_keys = OFF");
  try {
    db.exec("BEGIN IMMEDIATE");
    try {
      db.exec(
        `CREATE TABLE decision_next (
           id             INTEGER PRIMARY KEY AUTOINCREMENT,
           run            INTEGER NOT NULL UNIQUE REFERENCES run(id) ON DELETE CASCADE,
           urgency        TEXT NOT NULL CHECK (urgency IN ('blocking')),
           state          TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open','expired','answered')),
           recap          TEXT NOT NULL,
           question       TEXT NOT NULL,
           options        TEXT NOT NULL,
           recommendation TEXT NOT NULL,
           assignee       TEXT,
           deadline       TEXT,
           created_at     TEXT NOT NULL,
           answered_at    TEXT,
           answered_by    TEXT,
           answered_via   TEXT CHECK (answered_via IN ('cli','web','telegram')),
           choice         TEXT,
           note           TEXT
         )`,
      );
      db.exec(
        `INSERT INTO decision_next (id, run, urgency, state, recap, question, options,
                                    recommendation, assignee, deadline, created_at,
                                    answered_at, answered_by, answered_via, choice, note)
         SELECT id, run, urgency, state, recap, question, options,
                recommendation, assignee, deadline, created_at,
                answered_at, answered_by, answered_via, choice, note FROM decision`,
      );
      db.exec("DROP TABLE decision");
      db.exec("ALTER TABLE decision_next RENAME TO decision");
      const broken = db.prepare("PRAGMA foreign_key_check").all();
      if (broken.length > 0) {
        throw new Error(`decision rebuild left ${broken.length} dangling foreign key(s)`);
      }
      db.exec("COMMIT");
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  } finally {
    db.exec("PRAGMA foreign_keys = ON");
  }
}

/**
 * The tables whose shape changed, not merely grew.
 *
 * `run`'s outcome CHECK had to admit 'parked' and `hold` had to move its
 * primary key, and SQLite's ALTER can do neither — so this is the manual's
 * copy-rename recipe: build the new table, move the rows, drop the old, take
 * its name. Detected by column presence, like `addColumn`, so it runs once
 * per database ever and is a no-op on a fresh file whose SCHEMA already has
 * the new shape.
 *
 * Every fresh-`:memory:` test passes without this function existing; the
 * first park against a real M2 database is what it exists for.
 */
function rebuild(db: Database): void {
  const oldHold = tableExists(db, "hold") && !hasColumn(db, "hold", "owner_kind");
  const oldRun = tableExists(db, "run") && !hasColumn(db, "run", "role");
  if (!oldHold && !oldRun) return;

  // Foreign keys off so `run` can be dropped while decision/artifact rows
  // name it — and a PRAGMA is a no-op inside a transaction, so it brackets
  // one rather than living in it. The check at the end proves the swap left
  // every reference intact before anything commits.
  db.exec("PRAGMA foreign_keys = OFF");
  try {
    db.exec("BEGIN IMMEDIATE");
    try {
      if (oldHold) {
        db.exec(
          `CREATE TABLE hold_next (
             id         INTEGER PRIMARY KEY AUTOINCREMENT,
             task_ref   INTEGER NOT NULL REFERENCES task_ref(id) ON DELETE CASCADE,
             owner_kind TEXT NOT NULL CHECK (owner_kind IN ('operator','decision','incident','backoff')),
             owner_id   TEXT NOT NULL,
             reason     TEXT NOT NULL,
             until      TEXT,
             held_at    TEXT NOT NULL,
             UNIQUE (owner_kind, owner_id)
           )`,
        );
        // Every pre-M3 hold was placed by a person; ownership records that.
        db.exec(
          `INSERT INTO hold_next (task_ref, owner_kind, owner_id, reason, until, held_at)
           SELECT task_ref, 'operator', CAST(task_ref AS TEXT), reason, until, held_at FROM hold`,
        );
        db.exec("DROP TABLE hold");
        db.exec("ALTER TABLE hold_next RENAME TO hold");
        db.exec("CREATE INDEX IF NOT EXISTS hold_by_task ON hold (task_ref)");
      }
      if (oldRun) {
        // Straight to the newest shape: an M2 database does not stop at v3
        // on its way here.
        db.exec(V4_RUN_DDL("run_next"));
        db.exec(
          `INSERT INTO run_next (id, task_ref, lease_id, runner, branch, worktree, model,
                                 outcome, reason, committed, started_at, finished_at)
           SELECT id, task_ref, lease_id, runner, branch, worktree, model,
                  outcome, reason, committed, started_at, finished_at FROM run`,
        );
        db.exec("DROP TABLE run");
        db.exec("ALTER TABLE run_next RENAME TO run");
      }
      const broken = db.prepare("PRAGMA foreign_key_check").all();
      if (broken.length > 0) {
        throw new Error(`schema rebuild left ${broken.length} dangling foreign key(s)`);
      }
      db.exec("COMMIT");
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  } finally {
    db.exec("PRAGMA foreign_keys = ON");
  }
}

function tableExists(db: Database, table: string): boolean {
  return (
    db.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(table) !==
    undefined
  );
}

function hasColumn(db: Database, table: string, column: string): boolean {
  return db
    .prepare(`PRAGMA table_info(${table})`)
    .all()
    .some(row => String(row["name"]) === column);
}

/** A tier's candidates on other providers (sized routing): one row per provider, beside the tier's own candidate
 * (phase_config for routine, phase_tier_config for light and strong). At filing the one with more plan room runs. */
const PHASE_TIER_ALTERNATE_SCHEMA = `
CREATE TABLE IF NOT EXISTS phase_tier_alternate (
  scope      TEXT NOT NULL,
  phase      TEXT NOT NULL CHECK (phase IN ('plan','build')),
  tier       TEXT NOT NULL CHECK (tier IN ('light','routine','strong')),
  provider   TEXT NOT NULL CHECK (provider IN ('claude','codex','openrouter','gemini')),
  model      TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  PRIMARY KEY (scope, phase, tier, provider)
);
`;

/** A file from before the light tier keeps `tier IN ('strong')` in phase_tier_config's CHECK: rebuild the table with
 * the wider one, keeping every row, in one transaction. A file already widened is untouched. */
function widenPhaseTierSchema(db: Database): void {
  const row = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'phase_tier_config'").get();
  if (row === undefined || /'light'/.test(String(row["sql"]))) return;
  db.exec("BEGIN IMMEDIATE");
  try {
    db.exec(`CREATE TABLE phase_tier_config_next (
  scope      TEXT NOT NULL,
  phase      TEXT NOT NULL CHECK (phase IN ('plan','build','repair','review')),
  tier       TEXT NOT NULL CHECK (tier IN ('light','strong')),
  provider   TEXT NOT NULL CHECK (provider IN ('claude','codex','openrouter','gemini')),
  model      TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  PRIMARY KEY (scope, phase, tier)
)`);
    db.exec("INSERT INTO phase_tier_config_next SELECT scope, phase, tier, provider, model, updated_at, updated_by FROM phase_tier_config");
    db.exec("DROP TABLE phase_tier_config");
    db.exec("ALTER TABLE phase_tier_config_next RENAME TO phase_tier_config");
    db.exec("COMMIT");
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
}

/** A task's stored size, or null when it was never sized (or reads as nothing this code writes). */
function sizingOfRow(row: Record<string, unknown>): TaskSizing | null {
  if (!isTaskSize(row["size"])) return null;
  const source = row["size_source"];
  if (source !== "classifier" && source !== "heuristic" && source !== "person") return null;
  return { size: row["size"], risky: Number(row["size_risky"] ?? 0) === 1, source, reason: row["size_reason"] == null ? "" : String(row["size_reason"]) };
}

function addColumn(db: Database, table: string, column: string, definition: string): void {
  if (hasColumn(db, table, column)) return;
  db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
}

/** Reporting never creates, migrates, or repairs a store. SQLite itself
 * enforces read-only access, including the race where the file disappears. */
export function openStoreReadOnly(file: string): Store | null {
  let db: Database | undefined;
  try {
    const require = createRequire(import.meta.url);
    const { DatabaseSync } = require("node:sqlite") as {
      DatabaseSync: new (path: string, options: { readOnly: boolean }) => Database;
    };
    db = new DatabaseSync(file, { readOnly: true });
    waitForConcurrentWriter(db);
    const version = readSchemaVersion(db);
    if (!version.ok || version.version !== SCHEMA_VERSION) {
      db.close();
      return null;
    }
    return new Store(db);
  } catch {
    db?.close();
    return null;
  }
}

function defaultConnect(file: string): Database {
  const require = createRequire(import.meta.url);
  const { DatabaseSync } = require("node:sqlite") as {
    DatabaseSync: new (path: string) => Database;
  };
  return new DatabaseSync(file);
}

/** A proved review binding changed; database/runtime errors keep their own category. */
export class ReviewBindingError extends Error {
  constructor(message: string) { super(message); this.name = "ReviewBindingError"; }
}

export class Store {
  constructor(private readonly db: Database) {}

  /** TESTS ONLY: raw database access for migration fixtures. Production
   * code never calls this — the typed methods are the API. */
  raw(): Database {
    return this.db;
  }

  /** Exposed so `claim.ts` can run its compare-and-swap in one transaction. */
  get handle(): Database {
    return this.db;
  }

  /** The database's own file (null in memory): where the agent fence begins. */
  databaseFile(): string | null {
    const main = this.db.prepare("PRAGMA database_list").all().find(row => row["name"] === "main");
    const file = main === undefined ? "" : String(main["file"] ?? "");
    return file === "" ? null : file;
  }

  close(): void {
    this.db.close();
  }

  // ---- the built-in task store -------------------------------------------

  /**
   * Creating a task also creates its overlay reference, because a task with no
   * `TaskRef` cannot be claimed, held, or scheduled — it would be work the
   * control plane can see and never act on.
   */
  createTask(spec: { id: string; title: string; deliverable?: "branch" | "report"; filedBy?: Filer }, now: Date, mutation: Mutation = {}): Task {
    return this.once(mutation, "createTask", () =>
      // Both rows or neither, and the comment above is why: this used to be
      // two unwrapped statements, and the first real database caught it. A
      // schema change made the second one fail, the first had already
      // committed, and the result was a task with no reference — invisible to
      // the ready query, unclaimable, and silently given a reference later by
      // something else, with the wrong origin. Exactly the state this
      // invariant exists to rule out, arrived at by the invariant not being
      // enforced.
      this.transact(() => {
      const stamp = now.toISOString();
      this.db
        .prepare(
          "INSERT INTO task (id, title, state, created_at, updated_at) VALUES (?, ?, 'queued', ?, ?)",
        )
        .run(spec.id, spec.title, stamp, stamp);
      // A ref some lookup made before this task existed registered then, not now: register it again, so the task's
      // ledger history (v103 evidence packs) starts at its filing.
      // (Any backend's: the ledger names a task by its id alone.)
      const earlier = this.db.prepare("SELECT 1 AS hit FROM task_ref WHERE external_id = ?").get(spec.id) !== undefined;
      // Created here, so it is ours — the one place that is true by construction.
      const ref = this.refFor(BUILT_IN, spec.id, "ours");
      // Who filed it, when someone is acting: the lead's work pings nobody.
      this.noteTaskAct(ref.id, "filed", now);
      if (earlier) this.recordAction({ at: stamp, actor: "system", repo: ref.repo, taskId: spec.id, runId: null, action: "task registered", outcome: "recorded", source: "work", detail: REGISTERED_AT_FILING });
      // v102: who filed it, set once with the filing (separation of duties reads it; nothing changes it).
      if (spec.filedBy !== undefined) {
        this.db.prepare("UPDATE task_ref SET filed_by = ?, filed_by_kind = ? WHERE id = ?").run(spec.filedBy.name, spec.filedBy.kind, ref.id);
        this.recordAction({ at: stamp, actor: spec.filedBy.name ?? "system", repo: null, taskId: spec.id, runId: null, action: "task filed", outcome: "recorded", source: "work", detail: spec.filedBy.kind === "person" ? null : spec.filedBy.kind });
      }
      // The deliverable (v34) lands in the SAME transaction as the filing,
      // and there is no API to change it afterwards.
      if (spec.deliverable === "report") {
        this.db.prepare("UPDATE task_ref SET deliverable = 'report' WHERE id = ?").run(ref.id);
      }
      this.bumpWake();
      return {
        id: spec.id,
        title: spec.title,
        state: "queued" as TaskState,
        createdAt: stamp,
        updatedAt: stamp,
        priority: 0,
      };
      }),
    );
  }

  getTask(id: string): Task | null {
    const row = this.db.prepare("SELECT * FROM task WHERE id = ?").get(id);
    return row === undefined ? null : readTask(row);
  }

  /** Oldest first, so a list reads in the order the work was thought of. */
  listTasks(state?: TaskState): Task[] {
    const rows =
      state === undefined
        ? this.db.prepare("SELECT * FROM task ORDER BY created_at, id").all()
        : this.db.prepare("SELECT * FROM task WHERE state = ? ORDER BY created_at, id").all(state);
    return rows.map(readTask);
  }

  /** What this task is waiting for, whether or not those are finished. */
  blockers(id: string): string[] {
    return this.db
      .prepare("SELECT blocker FROM task_edge WHERE blocked = ? ORDER BY blocker")
      .all(id)
      .map(row => String(row["blocker"]));
  }

  /** The external id behind a reference, for reporting a claim back in words. */
  externalIdFor(taskRef: number): string | null {
    const row = this.db.prepare("SELECT external_id FROM task_ref WHERE id = ?").get(taskRef);
    return row === undefined ? null : String(row["external_id"]);
  }

  /** The whole reference by its id — the overlay's view of one task. */
  refForId(taskRef: number): TaskRef | null {
    const row = this.db.prepare("SELECT * FROM task_ref WHERE id = ?").get(taskRef);
    return row === undefined ? null : readTaskRef(row);
  }

  /**
   * THE one writer of `state = 'cancelled'` (MCP gateway spec v6, Codex
   * round-5 finding 2). Every cancellation road — the generic state verb,
   * operator dismissal, the external-mirror latch, a disowned fenced
   * completion — lands here, so a cancellation can never happen without a
   * stated reason and (once coordinator filings exist) its durable event.
   * An architecture test proves no other statement writes 'cancelled'.
   *
   * The floor does NOT decide admission — callers keep their own guards
   * (live-claim refusals, latch conditions, fencing) and pass the states
   * they admit from (`null` = any). It returns raw changes; callers keep
   * their own refusal words and wake bumps.
   */
  applyCancellation(
    taskId: string,
    reason:
      | { kind: "operator"; text: string | null }
      | { kind: "machine"; code: "mirror-latched" | "disowned-completion" },
    now: Date,
    admittedFrom: readonly TaskState[] | null,
    replacedBy?: string,
  ): CancellationTransition {
    return this.transact(() => this.applyCancellationLocked(taskId, reason, now, admittedFrom, replacedBy));
  }

  private applyCancellationLocked(
    taskId: string,
    reason:
      | { kind: "operator"; text: string | null }
      | { kind: "machine"; code: "mirror-latched" | "disowned-completion" },
    now: Date,
    admittedFrom: readonly TaskState[] | null,
    replacedBy?: string,
  ): CancellationTransition {
    const ref = this.db
      .prepare("SELECT id, coordinator_cid FROM task_ref WHERE backend = ? AND external_id = ?")
      .get(BUILT_IN, taskId);
    const coordinator = ref?.["coordinator_cid"] != null;
    // Check the authoritative linkage and the reason in the transaction
    // that changes state. No wrapper can substitute a generic dismissal.
    if (reason.kind === "operator") {
      if (coordinator) {
        if (reason.text === null || reason.text.trim() === "") return { changed: false, reason: "reason-required" };
        if (reason.text.length > 500 || hasDisguisedText(reason.text)) return { changed: false, reason: "bad-reason" };
      } else if (reason.text !== null && (reason.text.length > 500 || hasForbiddenControls(reason.text))) {
        // Preserve the ordinary-task API's existing validation behavior.
        throw new Error("a cancellation reason is at most 500 plain characters");
      }
    }
    const filter = admittedFrom === null ? "" : ` AND state IN (${admittedFrom.map(() => "?").join(",")})`;
    const prior = this.db.prepare("SELECT state FROM task WHERE id = ?").get(taskId);
    const { changes } = this.db
      .prepare(`UPDATE task SET state = 'cancelled', updated_at = ? WHERE id = ?${filter}`)
      .run(now.toISOString(), taskId, ...(admittedFrom ?? []));
    if (Number(changes) === 0) return { changed: false };
    // Replaced: the successor is part of the cancellation, so every surface says "Replaced by <id>".
    if (ref !== undefined && replacedBy !== undefined) {
      this.db.prepare(`INSERT INTO task_replacement (task_ref, successor, by, at) VALUES (?, ?, ?, ?)
        ON CONFLICT (task_ref) DO UPDATE SET successor = excluded.successor, by = excluded.by, at = excluded.at`)
        .run(Number(ref["id"]), replacedBy, currentActor() === null ? null : actorLabel(currentActor()!), now.toISOString());
    }
    if (ref !== undefined && prior?.["state"] !== "cancelled") this.noteTaskAct(Number(ref["id"]), "cancelled", now);
    // A cancelled task's pending steering settles superseded in the SAME
    // transaction, whichever road cancelled it — a note silently waiting
    // for a build that can no longer happen is wrong on every road, not
    // just the state verb's.
    if (ref !== undefined) this.supersedeSteerNotes(Number(ref["id"]), now);
    // The reason is part of the transition, not decoration: a
    // coordinator-filed task's dismissal writes its durable event IN THIS
    // transaction — operator text and typed machine codes alike (MCP spec
    // v6: events atomic with state changes; the filer deserves words).
    if (ref !== undefined && coordinator) {
      const detail = reason.kind === "operator" ? reason.text! : reason.code;
      this.db
        .prepare("INSERT INTO coordinator_event (cid, kind, task_id, detail, created_at) VALUES (?, 'dismissed', ?, ?, ?)")
        .run(String(ref["coordinator_cid"]), taskId, detail, now.toISOString());
    }
    // The cancellation fact (Telegram task updates) rides the one floor
    // every road lands on, beside the audit row — never a separate write,
    // never inferred from the state verb's words. The unfiltered state verb
    // rewrites 'cancelled' over 'cancelled'; that is the same state.
    if (ref !== undefined && prior?.["state"] !== "cancelled") {
      this.noteLifecycle(
        {
          taskRef: Number(ref["id"]), kind: "task-cancelled", identity: `t${Number(ref["id"])}`,
          subject: replacedBy === undefined ? "Cancelled" : `Replaced by ${replacedBy}`,
          body: replacedBy !== undefined
            ? `${replacedBy} replaces it. Nothing more runs for it.`
            : reason.kind === "operator"
            ? `${cancellationWords(reason.text)} Nothing more runs for it.`
            : reason.code === "mirror-latched"
              ? "The tracker closed it. Nothing more runs for it."
              : "The tracker closed it while it was being built, so the finished work was not accepted.",
          link: chatControlHref("task", replacedBy ?? taskId),
        },
        now,
      );
    }
    return { changed: true };
  }

  setTaskState(
    id: string,
    state: TaskState,
    now: Date,
    mutation: Mutation = {},
    cancellationReason?: string,
    replacedBy?: string,
  ): { ok: true } | { ok: false; reason: "unknown-task" | "external-closed" | CancellationRefusal } {
    return this.once(
      mutation,
      "setTaskState",
      () => {
        // The terminal guard lives IN the primitive so every present and
        // future caller is covered (external dispatch, finding 23): a
        // mirror the tracker closed cannot be marked done — reopen it
        // first, or leave it cancelled. cancelled/failed stay allowed;
        // they are the latch's own vocabulary.
        if (state === "done") {
          const latched = this.db
            .prepare("SELECT 1 AS hit FROM external_mirror WHERE local_task_id = ? AND remote_state <> 'open'")
            .get(id);
          if (latched !== undefined) return { ok: false as const, reason: "external-closed" as const };
        }
        return this.transact(() => {
          if (state === "cancelled") {
            const done = this.applyCancellation(id, { kind: "operator", text: cancellationReason ?? null }, now, null, replacedBy);
            if (done.reason !== undefined) return { ok: false as const, reason: done.reason };
            if (!done.changed) return { ok: false as const, reason: "unknown-task" as const };
            this.bumpWake();
            return { ok: true as const };
          }
          const prior = this.db.prepare("SELECT state FROM task WHERE id = ?").get(id);
          const { changes } = this.db
            .prepare("UPDATE task SET state = ?, updated_at = ? WHERE id = ?")
            .run(state, now.toISOString(), id);
          if (Number(changes) === 0) return { ok: false as const, reason: "unknown-task" as const };
          if (state === "done" && prior?.["state"] !== "done") {
            const done = this.lookupRef(id);
            if (done !== null) this.noteTaskAct(done.id, "completed", now);
          }
          // The return-to-queue fact (Telegram task updates): a running
          // task its worker released unfinished, or a closed one reopened
          // by the state verb. Marking done or failed by hand rides the
          // run that concluded it, and 'running' is the attempt's own
          // start fact — neither is repeated here.
          if (state === "queued" && prior !== undefined && prior["state"] !== "queued") {
            const ref = this.lookupRef(id);
            if (ref !== null) {
              this.noteLifecycle(
                {
                  taskRef: ref.id, kind: "task-queued", identity: `t${ref.id}`,
                  subject: "Back in the queue",
                  body: prior["state"] === "running" ? "Its worker released it without finishing; another attempt can start." : "Reopened for another attempt.",
                  link: chatControlHref("task", id),
                },
                now,
              );
            }
          }
          // A finished task's pending steering settles superseded in the
          // SAME transaction (arc 1): shown as what it is, never a note
          // silently waiting for a build that can no longer happen.
          if (state === "done") {
            const ref = this.db
              .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
              .get(BUILT_IN, id);
            if (ref !== undefined) this.supersedeSteerNotes(Number(ref["id"]), now);
          }
          this.bumpWake();
          return { ok: true as const };
        });
      },
      // A refusal mutated nothing, so there is nothing to replay — and
      // recording it would answer "no" forever, including after somebody
      // creates the task or reopens the mirror (finding 42).
      result => result.ok,
    );
  }

  /**
   * `blocked` waits for `blocker`.
   *
   * A cycle is refused rather than stored. Stored, it would be invisible: every
   * task in the ring stays un-ready forever and the ready set simply comes back
   * one task shorter each night, with nothing anywhere saying why.
   */
  addEdge(blocked: string, blocker: string, mutation: Mutation = {}): { ok: true } | { ok: false; reason: string } {
    return this.once(mutation, "addEdge", () =>
      // The reachability check and the insert have to be one atomic step.
      // Apart, two callers adding `a waits on b` and `b waits on a` at the
      // same moment each see no cycle, and between them store one.
      this.transact(() => {
        if (blocked === blocker) return { ok: false as const, reason: "a task cannot block itself" };
        if (this.reaches(blocker, blocked)) {
          return { ok: false as const, reason: `${blocker} already waits on ${blocked} — that is a cycle` };
        }
        this.db
          .prepare("INSERT OR IGNORE INTO task_edge (blocked, blocker) VALUES (?, ?)")
          .run(blocked, blocker);
        return { ok: true as const };
      }),
      result => result.ok,
    );
  }

  /**
   * Remove one dependency edge. Removal cannot create a cycle, so no
   * closure check — but delete-and-wake stay one transaction so it
   * serializes cleanly against claim admission: whichever commits first,
   * the claim's own re-proof sees a consistent world. Removing an edge
   * makes a task DISPATCHABLE sooner, never buildable without approval.
   */
  removeEdge(blocked: string, blocker: string, mutation: Mutation = {}): { ok: true } | { ok: false; reason: string } {
    return this.once(mutation, "removeEdge", () =>
      this.transact(() => {
        const changes = this.db
          .prepare("DELETE FROM task_edge WHERE blocked = ? AND blocker = ?")
          .run(blocked, blocker).changes;
        if (Number(changes) === 0) return { ok: false as const, reason: "not-waiting" };
        // A tick that snapshotted its ready list before this commit waits
        // for the next pass — the wake is what makes "next pass" now.
        this.bumpWake();
        return { ok: true as const };
      }),
      result => result.ok,
    );
  }

  /** Replace one dependency edge atomically. Every condition is checked
   * before either write, so a refused replacement leaves the old blocker
   * intact. The wake makes a live watch reconsider the graph immediately. */
  replaceEdge(
    blocked: string,
    blocker: string,
    replacement: string,
    mutation: Mutation = {},
  ): { ok: true } | { ok: false; reason: string } {
    return this.once(mutation, "replaceEdge", () =>
      this.transact(() => {
        const standing = this.db
          .prepare("SELECT 1 AS hit FROM task_edge WHERE blocked = ? AND blocker = ?")
          .get(blocked, blocker);
        if (standing === undefined) return { ok: false as const, reason: "not-waiting" };
        if (blocked === replacement) return { ok: false as const, reason: "a task cannot block itself" };
        if (this.getTask(replacement) === null) return { ok: false as const, reason: "unknown-replacement" };
        if (this.reaches(replacement, blocked)) {
          return { ok: false as const, reason: `${replacement} already waits on ${blocked} — that is a cycle` };
        }
        this.db.prepare("DELETE FROM task_edge WHERE blocked = ? AND blocker = ?").run(blocked, blocker);
        this.db.prepare("INSERT OR IGNORE INTO task_edge (blocked, blocker) VALUES (?, ?)").run(blocked, replacement);
        this.bumpWake();
        return { ok: true as const };
      }),
      result => result.ok,
    );
  }

  /**
   * Move a task to the front of the queue: rank = one past the highest
   * rank any still-dispatchable task holds, computed and written in ONE
   * transaction (two racing "next" calls get distinct ranks; the later
   * ask wins). Scheduling only: it refuses anything not plainly queued —
   * building, finished, failed, cancelled, or racing a tournament — and
   * never touches updated_at, which the board reads as the stall clock.
   */
  moveTaskNext(taskId: string, now: Date, mutation: Mutation = {}): { ok: true; priority: number } | { ok: false; reason: string } {
    return this.once(mutation, "moveTaskNext", () =>
      this.transact(() => {
        const task = this.db.prepare("SELECT state FROM task WHERE id = ?").get(taskId);
        if (task === undefined) return { ok: false as const, reason: "unknown-task" };
        const ref = this.db
          .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
          .get(BUILT_IN, taskId);
        if (ref !== undefined) {
          // The live claim is checked BEFORE the state: taking a task sets
          // it running, so "claimed" would otherwise be unreachable and the
          // operator would read the less honest "not queued".
          if (this.currentLiveLease(Number(ref["id"]), now) !== null) return { ok: false as const, reason: "claimed" };
          const racing = this.db
            .prepare(
              `SELECT 1 AS hit FROM contest WHERE task_ref = ?
                AND state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted') LIMIT 1`,
            )
            .get(Number(ref["id"]));
          if (racing !== undefined) return { ok: false as const, reason: "contest-open" };
        }
        if (String(task["state"]) !== "queued") return { ok: false as const, reason: "not-queued" };
        // Rank is per COLUMN (assigned worker + repo partition) — "next"
        // means the front of THIS task's own queue, not a global race. A
        // legacy row with no reference lives in the (null, null) partition.
        const partition = this.db
          .prepare("SELECT repo, assigned_runner FROM task_ref WHERE backend = ? AND external_id = ?")
          .get(BUILT_IN, taskId);
        const top = this.db
          .prepare(
            `SELECT MAX(task.priority) AS top FROM task
               LEFT JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
              WHERE task.state IN ('queued','running')
                AND (task_ref.assigned_runner IS ?) AND (task_ref.repo IS ?)`,
          )
          .get(BUILT_IN, partition?.["assigned_runner"] ?? null, partition?.["repo"] ?? null);
        const highest = top === undefined || top["top"] === null ? 0 : Number(top["top"]);
        if (highest >= Number.MAX_SAFE_INTEGER - 1) return { ok: false as const, reason: "rank-overflow" };
        const priority = highest + 1;
        this.db.prepare("UPDATE task SET priority = ? WHERE id = ?").run(priority, taskId);
        this.bumpQueueRevision();
        this.bumpWake();
        return { ok: true as const, priority };
      }),
      result => result.ok,
    );
  }

  /** Undo a promotion: back to filing order. Refuses nothing but absence —
   * demoting finished work is harmless. */
  clearTaskPriority(taskId: string, mutation: Mutation = {}): { ok: true } | { ok: false; reason: string } {
    return this.once(mutation, "clearTaskPriority", () =>
      this.transact(() => {
        const changes = this.db.prepare("UPDATE task SET priority = 0 WHERE id = ?").run(taskId).changes;
        if (Number(changes) === 0) return { ok: false as const, reason: "unknown-task" };
        this.bumpQueueRevision();
        this.bumpWake();
        return { ok: true as const };
      }),
      result => result.ok,
    );
  }

  // ---- queue columns (v19) -------------------------------------------------

  /** The worker a task is reserved for, or null — the claim gate's read. */
  assignedRunnerOf(taskRef: number): string | null {
    const row = this.db.prepare("SELECT assigned_runner FROM task_ref WHERE id = ?").get(taskRef);
    return row === undefined || row["assigned_runner"] === null ? null : String(row["assigned_runner"]);
  }

  queueRevision(): number {
    const row = this.db.prepare("SELECT revision FROM queue_state WHERE id = 1").get();
    return row === undefined ? 0 : Number(row["revision"]);
  }

  private bumpQueueRevision(): void {
    this.db.exec("UPDATE queue_state SET revision = revision + 1 WHERE id = 1");
  }

  /** The column note — operator prose, display only. */
  setRunnerQueueNote(name: string, note: string | null): { ok: true } | { ok: false; reason: string } {
    const changes = this.db.prepare("UPDATE runner SET queue_note = ? WHERE name = ?").run(note, name).changes;
    return Number(changes) === 1 ? { ok: true } : { ok: false, reason: "no-such-worker" };
  }

  /**
   * One atomic queue move (queue-columns review, findings 3/9/13): the
   * revision CAS, every refusal, the assignment write, and the rerank of
   * BOTH affected columns are one transaction. The rerank member set is
   * the FREE members only — anything live-claimed or racing a tournament
   * keeps its rank untouched, so a drag can never rewrite work being
   * taken (a setup-failure release rejoins with the rank the operator
   * last gave it — intent, not a bug). Scheduling, never authority.
   */
  moveTask(
    args: { taskId: string; toRunner: string | null; beforeTaskId: string | null; queueRevision?: number },
    now: Date,
    mutation: Mutation = {},
  ): { ok: true } | { ok: false; reason: string } {
    return this.once(mutation, "moveTask", () =>
      this.transact(() => {
        if (args.queueRevision !== undefined && args.queueRevision !== this.queueRevision()) {
          return { ok: false as const, reason: "stale" };
        }
        const task = this.db.prepare("SELECT state FROM task WHERE id = ?").get(args.taskId);
        if (task === undefined) return { ok: false as const, reason: "unknown-task" };
        const ref = this.db
          .prepare("SELECT id, repo, assigned_runner FROM task_ref WHERE backend = ? AND external_id = ?")
          .get(BUILT_IN, args.taskId);
        if (ref === undefined) return { ok: false as const, reason: "unknown-task" };
        // Claimed before not-queued: taking a task sets it running, so the
        // honest word for mid-build work is "claimed" (same rule as next).
        if (this.currentLiveLease(Number(ref["id"]), now) !== null) return { ok: false as const, reason: "claimed" };
        if (String(task["state"]) !== "queued") return { ok: false as const, reason: "not-queued" };
        const racing = this.db
          .prepare(
            `SELECT 1 AS hit FROM contest WHERE task_ref = ?
              AND state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted') LIMIT 1`,
          )
          .get(Number(ref["id"]));
        if (racing !== undefined) return { ok: false as const, reason: "contest-open" };
        if (args.toRunner !== null) {
          const worker = this.db.prepare("SELECT retired_at FROM runner WHERE name = ?").get(args.toRunner);
          if (worker === undefined) return { ok: false as const, reason: "no-such-worker" };
          const alreadyOwns = ref["assigned_runner"] !== null && String(ref["assigned_runner"]) === args.toRunner;
          if (worker["retired_at"] !== null && !alreadyOwns) return { ok: false as const, reason: "worker-retired" };
        }
        const repo = ref["repo"] === null ? null : String(ref["repo"]);
        const fromRunner = ref["assigned_runner"] === null ? null : String(ref["assigned_runner"]);

        // The FREE members of a partition, in current queue order.
        const freeMembers = (runner: string | null): string[] =>
          this.db
            .prepare(
              `SELECT task.id AS id FROM task
                 JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
                WHERE task.state = 'queued'
                  AND (task_ref.assigned_runner IS ? )
                  AND (task_ref.repo IS ?)
                  AND NOT EXISTS (
                    SELECT 1 FROM claim WHERE claim.task_ref = task_ref.id
                      AND claim.released_at IS NULL AND claim.expires_at > ?
                      AND claim.lease_generation = (
                        SELECT MAX(newest.lease_generation) FROM claim AS newest
                        WHERE newest.task_ref = task_ref.id))
                  AND NOT EXISTS (
                    SELECT 1 FROM contest WHERE contest.task_ref = task_ref.id
                      AND contest.state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted'))
                ORDER BY task.priority DESC, task.created_at, task_ref.id`,
            )
            .all(BUILT_IN, runner, repo, now.toISOString())
            .map(row => String(row["id"]));

        const target = freeMembers(args.toRunner).filter(id => id !== args.taskId);
        if (args.beforeTaskId !== null) {
          if (args.beforeTaskId === args.taskId) return { ok: false as const, reason: "stale" };
          const at = target.indexOf(args.beforeTaskId);
          if (at === -1) return { ok: false as const, reason: "stale" };
          target.splice(at, 0, args.taskId);
        } else {
          target.push(args.taskId);
        }

        this.db
          .prepare("UPDATE task_ref SET assigned_runner = ? WHERE backend = ? AND external_id = ?")
          .run(args.toRunner, BUILT_IN, args.taskId);
        const rank = this.db.prepare("UPDATE task SET priority = ? WHERE id = ?");
        target.forEach((id, index) => rank.run(target.length - index, id));
        if (fromRunner !== args.toRunner) {
          const source = freeMembers(fromRunner).filter(id => id !== args.taskId);
          source.forEach((id, index) => rank.run(source.length - index, id));
        }
        this.bumpQueueRevision();
        this.bumpWake();
        return { ok: true as const };
      }),
      result => result.ok,
    );
  }

  /**
   * The queue screen's snapshot: every queued task in the project, in
   * column order, each saying whether the scheduler already has its hands
   * on it (those cards render pinned, not draggable — finding 13).
   */
  queueScoped(
    repo: string | null,
    now: Date,
  ): {
    id: string;
    title: string;
    repo: string | null;
    assignedRunner: string | null;
    approved: boolean;
    blockers: number;
    taken: boolean;
    createdAt: string;
  }[] {
    const stamp = now.toISOString();
    return this.db
      .prepare(
        `SELECT task.id AS id, task.title AS title, task_ref.repo AS repo,
                task_ref.assigned_runner AS assigned, task.created_at AS created_at,
                EXISTS (SELECT 1 FROM task_scope WHERE task_scope.task_id = task.id
                  AND task_scope.approved_digest = task_scope.digest AND task_scope.approved_at IS NOT NULL) AS approved,
                (SELECT COUNT(*) FROM task_edge JOIN task AS blocker ON blocker.id = task_edge.blocker
                  WHERE task_edge.blocked = task.id AND blocker.state <> 'done') AS blockers,
                (EXISTS (SELECT 1 FROM claim WHERE claim.task_ref = task_ref.id
                    AND claim.released_at IS NULL AND claim.expires_at > ?
                    AND claim.lease_generation = (SELECT MAX(newest.lease_generation) FROM claim AS newest
                      WHERE newest.task_ref = task_ref.id))
                 OR EXISTS (SELECT 1 FROM contest WHERE contest.task_ref = task_ref.id
                    AND contest.state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted'))) AS taken
           FROM task JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
          WHERE task.state = 'queued'
            AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
          ORDER BY task.priority DESC, task.created_at, task_ref.id
          LIMIT 200`,
      )
      .all(stamp, BUILT_IN, repo, repo)
      .map(row => ({
        id: String(row["id"]),
        title: String(row["title"]),
        repo: row["repo"] === null ? null : String(row["repo"]),
        assignedRunner: row["assigned"] === null ? null : String(row["assigned"]),
        approved: Number(row["approved"]) === 1,
        blockers: Number(row["blockers"]),
        taken: Number(row["taken"]) === 1,
        createdAt: String(row["created_at"]),
      }));
  }

  /**
   * Where a queued task stands, using the COMPLETE order — rank, then
   * filing time, then reference id (finding 15: rank alone calls every
   * unranked task "first"). Position is within the task's own column.
   */
  queuePosition(taskId: string): { position: number; total: number; column: string | null } | null {
    const me = this.db
      .prepare(
        `SELECT task.priority AS priority, task.created_at AS created_at, task_ref.id AS ref,
                task_ref.repo AS repo, task_ref.assigned_runner AS assigned
           FROM task JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
          WHERE task.id = ? AND task.state = 'queued'`,
      )
      .get(BUILT_IN, taskId);
    if (me === undefined) return null;
    const row = this.db
      .prepare(
        `SELECT
           COUNT(*) AS total,
           SUM(CASE WHEN task.priority > ?
                 OR (task.priority = ? AND task.created_at < ?)
                 OR (task.priority = ? AND task.created_at = ? AND task_ref.id < ?)
               THEN 1 ELSE 0 END) AS ahead
           FROM task JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
          WHERE task.state = 'queued' AND (task_ref.assigned_runner IS ?) AND (task_ref.repo IS ?)`,
      )
      .get(
        Number(me["priority"]), Number(me["priority"]), String(me["created_at"]),
        Number(me["priority"]), String(me["created_at"]), Number(me["ref"]),
        BUILT_IN, me["assigned"], me["repo"],
      );
    return {
      position: Number(row?.["ahead"] ?? 0) + 1,
      total: Number(row?.["total"] ?? 1),
      column: me["assigned"] === null ? null : String(me["assigned"]),
    };
  }

  /**
   * The fleet screen's snapshot: every queued task across projects in
   * column order (like queueScoped but project-wide). The console layer
   * still filters each row through the ceiling before rendering — this is
   * a survey, not an admission, and a repo outside the wall never leaves
   * the page.
   */
  fleetQueue(
    now: Date,
  ): {
    id: string;
    title: string;
    repo: string | null;
    assignedRunner: string | null;
    approved: boolean;
    blockers: number;
    taken: boolean;
  }[] {
    const stamp = now.toISOString();
    return this.db
      .prepare(
        `SELECT task.id AS id, task.title AS title, task_ref.repo AS repo,
                task_ref.assigned_runner AS assigned,
                EXISTS (SELECT 1 FROM task_scope WHERE task_scope.task_id = task.id
                  AND task_scope.approved_digest = task_scope.digest AND task_scope.approved_at IS NOT NULL) AS approved,
                (SELECT COUNT(*) FROM task_edge JOIN task AS blocker ON blocker.id = task_edge.blocker
                  WHERE task_edge.blocked = task.id AND blocker.state <> 'done') AS blockers,
                (EXISTS (SELECT 1 FROM claim WHERE claim.task_ref = task_ref.id
                    AND claim.released_at IS NULL AND claim.expires_at > ?
                    AND claim.lease_generation = (SELECT MAX(newest.lease_generation) FROM claim AS newest
                      WHERE newest.task_ref = task_ref.id))
                 OR EXISTS (SELECT 1 FROM contest WHERE contest.task_ref = task_ref.id
                    AND contest.state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted'))) AS taken
           FROM task JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
          WHERE task.state = 'queued'
          ORDER BY task.priority DESC, task.created_at, task_ref.id
          LIMIT 400`,
      )
      .all(stamp, BUILT_IN)
      .map(row => ({
        id: String(row["id"]),
        title: String(row["title"]),
        repo: row["repo"] === null ? null : String(row["repo"]),
        assignedRunner: row["assigned"] === null ? null : String(row["assigned"]),
        approved: Number(row["approved"]) === 1,
        blockers: Number(row["blockers"]),
        taken: Number(row["taken"]) === 1,
      }));
  }

  /** Whether this connection is already inside transact(); see below. */
  private transacting = false;

  /**
   * IMMEDIATE, so two writers queue rather than both deciding they may write.
   *
   * Reentrant: a body that calls another transact()-wrapped method joins the
   * outer transaction instead of throwing "within a transaction". The outer
   * caller owns commit and rollback — which is the point: the Telegram
   * bridge composes pairing, action consumption, and the answer CAS into
   * one atomic unit precisely by nesting the methods that each guard
   * themselves when called alone.
   */
  transact<T>(body: () => T): T {
    if (this.transacting) return body();
    beginWriteWithin(this.db, CONCURRENT_WRITER_WAIT_MS);
    this.transacting = true;
    try {
      const result = body();
      this.db.exec("COMMIT");
      return result;
    } catch (error) {
      this.db.exec("ROLLBACK");
      throw error;
    } finally {
      this.transacting = false;
    }
  }

  /**
   * A named SAVEPOINT for a multi-statement primitive that must roll back
   * WHOLESALE on a mid-body error, EVEN when nested inside an outer
   * transaction a caller might catch around (fallback chains, Codex E1
   * review, finding 4): a plain reentrant transact() only propagates the
   * throw, so an outer catch could commit a half-done body (a cursor moved
   * without its transition). A savepoint releases on success and rolls
   * back to itself on any throw, so the body is all-or-nothing regardless
   * of the enclosing transaction. Reentrancy is handled by unique names.
   */
  private savepointCounter = 0;
  // Recovery eligibility uses a savepoint for a consistent read; settlement nests
  // its exact recheck/write here so an outer failure still rolls back both records.
  savepoint<T>(body: () => T): T {
    const name = `sp_${this.savepointCounter++}`;
    this.db.exec(`SAVEPOINT ${name}`);
    try {
      const result = body();
      this.db.exec(`RELEASE ${name}`);
      return result;
    } catch (error) {
      this.db.exec(`ROLLBACK TO ${name}`);
      this.db.exec(`RELEASE ${name}`);
      throw error;
    }
  }

  /** Whether `to` is reachable from `from` by following what it waits on. */
  private reaches(from: string, to: string): boolean {
    const row = this.db
      .prepare(
        `WITH RECURSIVE waits(id) AS (
           SELECT ?
           UNION
           SELECT task_edge.blocker FROM task_edge JOIN waits ON task_edge.blocked = waits.id
         )
         SELECT 1 AS hit FROM waits WHERE id = ? LIMIT 1`,
      )
      .get(from, to);
    return row !== undefined;
  }

  /**
   * The ready set: queued, every blocker finished, no active hold, and not
   * already claimed by somebody else.
   *
   * A hold whose `until` has passed is not a hold. Reading it as one would
   * strand work at exactly the moment it was supposed to resume.
   */
  listReady(now: Date, forRunner?: string): TaskRef[] {
    const stamp = now.toISOString();
    // With a runner named, this is the DISPATCH view (queue-columns v2):
    // tasks reserved for others are absent, and the runner's own reserved
    // work comes before the shared queue. Without one it is the report.
    const reservation =
      forRunner === undefined
        ? ""
        : " AND (task_ref.assigned_runner IS NULL OR task_ref.assigned_runner = ?) ";
    const order =
      forRunner === undefined
        ? "ORDER BY task.priority DESC, task.created_at, task_ref.id"
        : "ORDER BY (task_ref.assigned_runner IS NULL) ASC, task.priority DESC, task.created_at, task_ref.id";
    const rows = this.db
      .prepare(
        `SELECT task_ref.* FROM task
         JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
         WHERE task.state = 'queued'
           ${reservation}
           AND NOT EXISTS (
             SELECT 1 FROM hold
             WHERE hold.task_ref = task_ref.id
               AND (hold.until IS NULL OR hold.until > ?)
           )
           -- Only the newest lease can be holding the task. The claim log is
           -- append-only, so asking "does any unreleased row exist" would let
           -- a long-superseded lease keep work off the ready set forever.
           AND NOT EXISTS (
             SELECT 1 FROM claim
             WHERE claim.task_ref = task_ref.id
               AND claim.released_at IS NULL
               AND claim.expires_at > ?
               AND claim.lease_generation = (
                 SELECT MAX(newest.lease_generation) FROM claim AS newest
                 WHERE newest.task_ref = task_ref.id
               )
           )
           AND NOT EXISTS (
             SELECT 1 FROM task_edge
             JOIN task AS blocker ON blocker.id = task_edge.blocker
             WHERE task_edge.blocked = task.id AND blocker.state <> 'done'
           )
           -- External mirrors ride only while cheap eligibility holds; the
           -- admission transaction is the law, this is the courtesy filter
           -- (dispatch v3, finding 20 — the stale-scan reports the rest).
           AND NOT EXISTS (
             SELECT 1 FROM external_mirror
             WHERE external_mirror.local_task_id = task.id
               AND (external_mirror.remote_state <> 'open' OR external_mirror.dispatch_ok = 0)
           )
         ${order}`,
      )
      .all(...(forRunner === undefined ? [BUILT_IN, stamp, stamp] : [BUILT_IN, forRunner, stamp, stamp]));

    return rows.map(readTaskRef);
  }

  // ---- the overlay --------------------------------------------------------

  /**
   * Get or create the reference.
   *
   * Creating one grants nothing on its own, and defaults to `theirs`: merely
   * referring to a task — which happens whenever anything is looked up — must
   * never be what makes it ours to write.
   */
  refFor(backend: string, externalId: string, origin: TaskOrigin = "theirs"): TaskRef {
    const existing = this.db
      .prepare("SELECT * FROM task_ref WHERE backend = ? AND external_id = ?")
      .get(backend, externalId);
    if (existing !== undefined) {
      // Ownership only ever widens by an explicit act, never by being looked
      // up again with a more generous argument.
      if (origin === "ours" && String(existing["origin"]) !== "ours") {
        this.db.prepare("UPDATE task_ref SET origin = 'ours' WHERE id = ?").run(existing["id"]);
        return readTaskRef({ ...existing, origin: "ours" });
      }
      return readTaskRef(existing);
    }

    this.db
      .prepare("INSERT INTO task_ref (backend, external_id, origin) VALUES (?, ?, ?)")
      .run(backend, externalId, origin);
    const created = this.db
      .prepare("SELECT * FROM task_ref WHERE backend = ? AND external_id = ?")
      .get(backend, externalId);
    return readTaskRef(created as Record<string, unknown>);
  }

  /** The reference if it exists — a read that never creates, for surfaces that only look. */
  lookupRef(taskId: string): TaskRef | null {
    const row = this.db
      .prepare("SELECT * FROM task_ref WHERE backend = ? AND external_id = ?")
      .get(BUILT_IN, taskId);
    return row === undefined ? null : readTaskRef(row);
  }

  /** Whether this task is one we created, as recorded — not as asserted. */
  originOf(backend: string, externalId: string): TaskOrigin {
    const row = this.db
      .prepare("SELECT origin FROM task_ref WHERE backend = ? AND external_id = ?")
      .get(backend, externalId);
    return row !== undefined && String(row["origin"]) === "ours" ? "ours" : "theirs";
  }

  /**
   * The operator's hold — the CLI's pause button. One per task, replaced on
   * repeat. Decision and incident holds go through `holdOwned`, and lifting
   * this one never touches theirs.
   */
  hold(taskRef: number, reason: string, until: Date | null, now: Date, mutation: Mutation = {}): void {
    this.once(mutation, "hold", () => {
      this.holdOwned(
        { taskRef, ownerKind: "operator", ownerId: String(taskRef), reason, until },
        now,
      );
      return null;
    });
  }

  /** Place a hold on behalf of its owner. One hold per owner, replaced on repeat. */
  holdOwned(
    hold: {
      taskRef: number;
      ownerKind: HoldOwner;
      ownerId: string;
      reason: string;
      until: Date | null;
    },
    now: Date,
  ): void {
    this.transact(() => this.holdOwnedLocked(hold, now));
  }

  private holdOwnedLocked(
    hold: { taskRef: number; ownerKind: HoldOwner; ownerId: string; reason: string; until: Date | null },
    now: Date,
  ): void {
    const prior = this.db
      .prepare("SELECT task_ref, reason, until FROM hold WHERE owner_kind = ? AND owner_id = ?")
      .get(hold.ownerKind, hold.ownerId);
    this.db
      .prepare(
        `INSERT INTO hold (task_ref, owner_kind, owner_id, reason, until, held_at)
         VALUES (?, ?, ?, ?, ?, ?)
         ON CONFLICT (owner_kind, owner_id) DO UPDATE SET task_ref = excluded.task_ref,
                                                          reason = excluded.reason,
                                                          until = excluded.until,
                                                          held_at = excluded.held_at`,
      )
      .run(
        hold.taskRef,
        hold.ownerKind,
        hold.ownerId,
        hold.reason,
        hold.until === null ? null : hold.until.toISOString(),
        now.toISOString(),
      );
    // Only the OPERATOR'S pause speaks here (Telegram task updates): a
    // decision, incident, backoff, contest, revision or stop hold arrives
    // beside its own page or its own stop fact, and repeating those would
    // teach a phone to skim. A repeat of the same pause is the same state.
    if (hold.ownerKind !== "operator") return;
    const until = hold.until === null ? null : hold.until.toISOString();
    const same = prior !== undefined && Number(prior["task_ref"]) === hold.taskRef && String(prior["reason"]) === hold.reason && (prior["until"] ?? null) === until;
    if (same) return;
    const taskId = this.externalIdFor(hold.taskRef);
    if (taskId === null) return;
    this.noteLifecycle(
      {
        taskRef: hold.taskRef, run: this.runsFor(hold.taskRef).find(one => one.role === "builder" && one.contestant === null)?.id ?? null,
        kind: "task-held", identity: `t${hold.taskRef}`,
        subject: until === null ? "Paused" : `Paused until ${until.slice(0, 16).replace("T", " ")} UTC`,
        body: "The next attempt waits until the hold is released. An attempt already running is not stopped by this.",
        link: chatControlHref("recovery", taskId),
      },
      now,
    );
  }

  /**
   * The CLI's unhold lifts only the operator's own hold. A task still held by
   * an open decision stays held — the way out of that hold is answering it.
   */
  unhold(taskRef: number, mutation: Mutation = {}, now?: Date): boolean {
    return this.once(
      mutation,
      "unhold",
      () => this.transact(() => {
        const { changes } = this.db
          .prepare("DELETE FROM hold WHERE task_ref = ? AND owner_kind = 'operator'")
          .run(taskRef);
        if (Number(changes) === 0) return false;
        this.bumpWake();
        // The release fact (Telegram task updates) says what is true NOW:
        // free to run, or still held by another owner — named, so a phone
        // never reads "released" as "running next".
        const at = now ?? mutation.at ?? new Date();
        const taskId = this.externalIdFor(taskRef);
        if (taskId !== null) {
          const others = this.activeHolds(taskRef, at).map(one => LIFECYCLE_HOLD_WORDS[one.ownerKind]);
          this.noteLifecycle(
            {
              taskRef, run: this.runsFor(taskRef).find(one => one.role === "builder" && one.contestant === null)?.id ?? null,
              kind: "task-released", identity: `t${taskRef}`,
              subject: "Hold released",
              body: others.length === 0 ? "The next attempt can start." : `It still waits on ${[...new Set(others)].join(" and ")}.`,
              link: chatControlHref(others.length === 0 ? "task" : "recovery", taskId),
            },
            at,
          );
        }
        return true;
      }),
      lifted => lifted,
    );
  }

  /** Lift exactly one owner's hold, whoever else may still be holding. */
  releaseOwnedHold(ownerKind: HoldOwner, ownerId: string): boolean {
    const { changes } = this.db
      .prepare("DELETE FROM hold WHERE owner_kind = ? AND owner_id = ?")
      .run(ownerKind, ownerId);
    return Number(changes) > 0;
  }

  /** The hold in force right now, if any. An elapsed `until` is not one. */
  activeHold(taskRef: number, now: Date): Hold | null {
    const [first = null] = this.activeHolds(taskRef, now);
    return first;
  }

  /** Every hold in force — a task can be held by more than one owner at once. */
  activeHolds(taskRef: number, now: Date): Hold[] {
    return this.db
      .prepare(
        `SELECT * FROM hold WHERE task_ref = ? AND (until IS NULL OR until > ?)
         ORDER BY held_at, id`,
      )
      .all(taskRef, now.toISOString())
      .map(readHold);
  }

  // ---- grants -------------------------------------------------------------

  /**
   * Enrolling twice replaces rather than accumulates. Two grants over one
   * backend would mean the effective permission is whichever row a query
   * happened to reach first, and a permission you cannot read off the page is
   * not a permission anyone can reason about.
   */
  saveGrant(grant: BackendGrant, mutation: Mutation = {}): void {
    // The cross-column dispatch rule lives HERE because ALTER ADD COLUMN
    // cannot carry cross-column CHECKs: dispatch demands its exact remote
    // repository and a plane identity, or it is not a dispatch grant.
    if (grant.dispatch === true && (grant.remoteRepo == null || grant.planeId == null)) {
      throw new Error("a dispatch grant names exactly one remote repository and carries a plane id");
    }
    this.once(mutation, "saveGrant", () => {
      this.db
        .prepare(
          `INSERT INTO backend_grant
             (repo, backend, paths, mutations, selector, credential_scope, observed_by_git, granted_at, granted_by,
              dispatch, remote_repo, plane_id, dispatch_blocked, dispatch_blocked_at, dispatch_blocked_detail)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
           ON CONFLICT (repo, backend) DO UPDATE SET
             paths = excluded.paths, mutations = excluded.mutations,
             selector = excluded.selector, credential_scope = excluded.credential_scope,
             observed_by_git = excluded.observed_by_git,
             granted_at = excluded.granted_at, granted_by = excluded.granted_by,
             dispatch = excluded.dispatch, remote_repo = excluded.remote_repo,
             plane_id = excluded.plane_id, dispatch_blocked = excluded.dispatch_blocked,
             dispatch_blocked_at = excluded.dispatch_blocked_at,
             dispatch_blocked_detail = excluded.dispatch_blocked_detail`,
        )
        .run(
          grant.repo,
          grant.backend,
          JSON.stringify(grant.paths),
          JSON.stringify(grant.mutations),
          grant.selector,
          grant.credentialScope,
          grant.observedByGit ? 1 : 0,
          grant.grantedAt,
          grant.grantedBy,
          grant.dispatch === true ? 1 : 0,
          grant.remoteRepo ?? null,
          grant.planeId ?? null,
          grant.dispatchBlocked ?? null,
          grant.dispatchBlockedAt ?? null,
          grant.dispatchBlockedDetail ?? null,
        );
      return null;
    });
  }

  // ---- external mirrors (v20) ---------------------------------------------

  /**
   * Establish a mirror: the ONE act that makes a local task stand for a
   * tracker item. Identity and provenance are immutable after this row
   * (trigger-enforced); labels and titles may nominate work, only this
   * establishes whose it is. Refuses tasks carrying race terms or an open
   * tournament (D1 — external work does not race in this release).
   */
  establishMirror(
    mirror: {
      localTaskId: string;
      backend: string;
      remoteRepo: string;
      remoteId: string;
      provenance: "local-create" | "intake" | "granted-all";
      intakeGrant?: number | null;
      establishedBy: string;
      syncGeneration?: number;
    },
    now: Date,
  ): { ok: true } | { ok: false; reason: "unknown-task" | "duplicate" | "racing" } {
    return this.transact(() => {
      const ref = this.db
        .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
        .get(BUILT_IN, mirror.localTaskId);
      if (ref === undefined) return { ok: false as const, reason: "unknown-task" as const };
      const racing = this.db
        .prepare(
          `SELECT 1 AS hit FROM contest WHERE task_ref = ?
            AND state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted') LIMIT 1`,
        )
        .get(Number(ref["id"]));
      const terms = this.db
        .prepare("SELECT 1 AS hit FROM tournament_terms WHERE task_ref = ? AND active = 1 LIMIT 1")
        .get(Number(ref["id"]));
      if (racing !== undefined || terms !== undefined) return { ok: false as const, reason: "racing" as const };
      const inserted = this.db
        .prepare(
          `INSERT OR IGNORE INTO external_mirror
             (local_task_id, backend, remote_repo, remote_id, provenance, intake_grant,
              established_by, established_at, remote_state, sync_generation, dispatch_ok)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'open', ?, 1)`,
        )
        .run(
          mirror.localTaskId,
          mirror.backend,
          mirror.remoteRepo,
          mirror.remoteId,
          mirror.provenance,
          mirror.provenance === "intake" ? (mirror.intakeGrant ?? null) : null,
          mirror.establishedBy,
          now.toISOString(),
          mirror.syncGeneration ?? 0,
        );
      if (Number(inserted.changes) === 0) return { ok: false as const, reason: "duplicate" as const };
      return { ok: true as const };
    });
  }

  mirrorByTask(taskId: string): ExternalMirror | null {
    const row = this.db.prepare("SELECT * FROM external_mirror WHERE local_task_id = ?").get(taskId);
    return row === undefined ? null : readMirror(row);
  }

  mirrorByRemote(backend: string, remoteRepo: string, remoteId: string): ExternalMirror | null {
    const row = this.db
      .prepare("SELECT * FROM external_mirror WHERE backend = ? AND remote_repo = ? AND remote_id = ?")
      .get(backend, remoteRepo, remoteId);
    return row === undefined ? null : readMirror(row);
  }

  externalMirrors(backend: string, remoteRepo: string): ExternalMirror[] {
    return this.db
      .prepare("SELECT * FROM external_mirror WHERE backend = ? AND remote_repo = ? ORDER BY local_task_id")
      .all(backend, remoteRepo)
      .map(readMirror);
  }

  /**
   * The latch (v3 §1): an authoritative closed/missing observation. ONE
   * transaction, and it never touches claims or runs — an idle mirror's
   * task is cancelled here (cancelTask's own matrix: queued/failed/
   * running, never done — done stays done, dependency satisfaction never
   * regresses); an in-flight one is left for the completion gate.
   */
  latchMirror(
    localTaskId: string,
    observed: "closed" | "missing",
    generation: number,
    now: Date,
  ): void {
    this.transact(() => {
      this.db
        .prepare(
          `UPDATE external_mirror
             SET remote_state = ?, dispatch_ok = 0,
                 close_generation = COALESCE(close_generation, ?), sync_generation = ?
           WHERE local_task_id = ?`,
        )
        .run(observed, generation, generation, localTaskId);
      const ref = this.db
        .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
        .get(BUILT_IN, localTaskId);
      if (ref === undefined) return;
      const live = this.currentLiveLease(Number(ref["id"]), now) !== null;
      const contested = this.db
        .prepare(
          `SELECT 1 AS hit FROM contest WHERE task_ref = ?
            AND state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted') LIMIT 1`,
        )
        .get(Number(ref["id"]));
      if (!live && contested === undefined) {
        this.applyCancellation(
          localTaskId,
          { kind: "machine", code: "mirror-latched" },
          now,
          ["queued", "failed", "running"],
        );
      }
      this.bumpWake();
    });
  }

  /** A fresh authoritative OPEN observation — recorded as reality; the
   * latch (dispatch_ok) clears only through the reopen act. */
  observeMirrorOpen(localTaskId: string, generation: number): void {
    this.db
      .prepare("UPDATE external_mirror SET remote_state = 'open', sync_generation = ? WHERE local_task_id = ?")
      .run(generation, localTaskId);
  }

  /**
   * The reopen act (v3 §7 + findings 18/30): an authenticated CAS that
   * requires the tracker to have been SEEN open again after the close,
   * and the task to be clean — no live claim, no open tournament, no
   * active hold, no open question, no unresolved incident. It reconciles
   * task state from any admitted state back to queued; the approved
   * scope is preserved (its digest never changed) — this act is the
   * operator's decision to resume.
   */
  reopenMirror(
    localTaskId: string,
    by: string,
    now: Date,
  ): { ok: true } | { ok: false; reason: "unknown-task" | "not-latched" | "not-seen-open" | "claimed" | "contest-open" | "held" | "question-open" | "incident-open" | "bad-state" } {
    return this.transact(() => {
      const mirror = this.mirrorByTask(localTaskId);
      if (mirror === null) return { ok: false as const, reason: "unknown-task" as const };
      if (mirror.dispatchOk && mirror.closeGeneration === null) return { ok: false as const, reason: "not-latched" as const };
      if (mirror.remoteState !== "open" || mirror.closeGeneration === null || mirror.syncGeneration <= mirror.closeGeneration) {
        return { ok: false as const, reason: "not-seen-open" as const };
      }
      const ref = this.db
        .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
        .get(BUILT_IN, localTaskId);
      if (ref === undefined) return { ok: false as const, reason: "unknown-task" as const };
      const taskRef = Number(ref["id"]);
      if (this.currentLiveLease(taskRef, now) !== null) return { ok: false as const, reason: "claimed" as const };
      const contested = this.db
        .prepare(
          `SELECT 1 AS hit FROM contest WHERE task_ref = ?
            AND state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted') LIMIT 1`,
        )
        .get(taskRef);
      if (contested !== undefined) return { ok: false as const, reason: "contest-open" as const };
      if (this.activeHolds(taskRef, now).length > 0) return { ok: false as const, reason: "held" as const };
      const question = this.db
        .prepare(
          `SELECT 1 AS hit FROM decision JOIN run ON run.id = decision.run
            WHERE run.task_ref = ? AND decision.answered_at IS NULL LIMIT 1`,
        )
        .get(taskRef);
      if (question !== undefined) return { ok: false as const, reason: "question-open" as const };
      const incident = this.db
        .prepare(
          `SELECT 1 AS hit FROM incident JOIN run ON run.id = incident.run
            WHERE run.task_ref = ? AND incident.resolved_at IS NULL LIMIT 1`,
        )
        .get(taskRef);
      if (incident !== undefined) return { ok: false as const, reason: "incident-open" as const };
      const task = this.db.prepare("SELECT state FROM task WHERE id = ?").get(localTaskId);
      if (task === undefined || !["cancelled", "failed", "queued"].includes(String(task["state"]))) {
        return { ok: false as const, reason: "bad-state" as const };
      }
      this.db
        .prepare(
          `UPDATE external_mirror SET dispatch_ok = 1, close_generation = NULL, reopened_by = ?, reopened_at = ?
            WHERE local_task_id = ?`,
        )
        .run(by, now.toISOString(), localTaskId);
      this.db
        .prepare("UPDATE task SET state = 'queued', updated_at = ? WHERE id = ?")
        .run(now.toISOString(), localTaskId);
      this.noteLifecycle(
        { taskRef, kind: "task-queued", identity: `t${taskRef}`, subject: "Back in the queue", body: "The tracker item is open again; another attempt can start.", link: chatControlHref("task", localTaskId) },
        now,
      );
      this.bumpWake();
      return { ok: true as const };
    });
  }

  /** The last COMPLETE sync pass for a tracker, or null — freshness's anchor. */
  lastCompleteSync(backend: string, remoteRepo: string): { generation: number; finishedAt: string } | null {
    const row = this.db
      .prepare(
        `SELECT generation, finished_at FROM sync_ledger
          WHERE backend = ? AND remote_repo = ? AND outcome = 'complete'
          ORDER BY generation DESC LIMIT 1`,
      )
      .get(backend, remoteRepo);
    return row === undefined || row["finished_at"] === null
      ? null
      : { generation: Number(row["generation"]), finishedAt: String(row["finished_at"]) };
  }

  openSyncPass(backend: string, remoteRepo: string, now: Date): { id: number; generation: number } {
    return this.transact(() => {
      const last = this.db
        .prepare("SELECT MAX(generation) AS top FROM sync_ledger WHERE backend = ? AND remote_repo = ?")
        .get(backend, remoteRepo);
      const generation = (last === undefined || last["top"] === null ? 0 : Number(last["top"])) + 1;
      this.db
        .prepare(
          "INSERT INTO sync_ledger (backend, remote_repo, generation, started_at) VALUES (?, ?, ?, ?)",
        )
        .run(backend, remoteRepo, generation, now.toISOString());
      const row = this.db.prepare("SELECT last_insert_rowid() AS id").get();
      return { id: Number(row?.["id"]), generation };
    });
  }

  /**
   * Close a pass. ONLY `complete` advances the surviving mirrors'
   * generations — atomically with the ledger transition, so freshness can
   * never outrun the observation that earned it (v3 §6). A capped or
   * failed pass proves nothing about absence and advances nothing.
   */
  closeSyncPass(
    id: number,
    outcome: "complete" | "capped" | "failed",
    counts: { candidates: number; mirrored: number },
    now: Date,
    detail: string | null = null,
  ): void {
    this.transact(() => {
      this.db
        .prepare(
          "UPDATE sync_ledger SET finished_at = ?, outcome = ?, candidates = ?, mirrored = ?, detail = ? WHERE id = ?",
        )
        .run(now.toISOString(), outcome, counts.candidates, counts.mirrored, detail, id);
      if (outcome === "complete") {
        const pass = this.db.prepare("SELECT backend, remote_repo, generation FROM sync_ledger WHERE id = ?").get(id);
        if (pass !== undefined) {
          this.db
            .prepare(
              "UPDATE external_mirror SET sync_generation = ? WHERE backend = ? AND remote_repo = ? AND sync_generation < ?",
            )
            .run(Number(pass["generation"]), String(pass["backend"]), String(pass["remote_repo"]), Number(pass["generation"]));
        }
      }
    });
  }

  /**
   * The admission gate's fact (v3 §2 / v4 §26): why this mirror may not
   * dispatch right now, or null for "go" — and "not-a-mirror" costs one
   * indexed lookup for every ordinary task. The FULL live grant tuple is
   * re-proved here: revocation, narrowing, and marker blocks take effect
   * at the very next admission.
   */
  mirrorAdmissionRefusal(
    taskRef: number,
    now: Date,
    maxAgeMs: number,
  ): "stale-mirror" | "external-closed" | "dispatch-revoked" | "plane-blocked" | null | "not-a-mirror" {
    const ref = this.db.prepare("SELECT external_id, repo FROM task_ref WHERE id = ?").get(taskRef);
    if (ref === undefined) return "not-a-mirror";
    const mirror = this.mirrorByTask(String(ref["external_id"]));
    if (mirror === null) return "not-a-mirror";
    if (mirror.remoteState !== "open" || !mirror.dispatchOk) return "external-closed";
    const repo = ref["repo"] === null ? null : String(ref["repo"]);
    const grant = repo === null ? null : this.grantFor(repo, mirror.backend);
    if (grant === null || grant.dispatch !== true || grant.remoteRepo !== mirror.remoteRepo) return "dispatch-revoked";
    if (grant.selector === "ours" && mirror.provenance === "granted-all") return "dispatch-revoked";
    if (grant.dispatchBlocked != null) return "plane-blocked";
    const anchor = this.lastCompleteSync(mirror.backend, mirror.remoteRepo);
    if (
      anchor === null ||
      mirror.syncGeneration < anchor.generation ||
      now.getTime() - new Date(anchor.finishedAt).getTime() > maxAgeMs
    ) {
      return "stale-mirror";
    }
    return null;
  }

  /**
   * The stale-scan's rows (dispatch v3, finding 20): every mirror in this
   * repo that admission would refuse right now, with its typed reason —
   * so a skipped mirror is REPORTED, never silently absent from ready.
   */
  ineligibleMirrors(
    repo: string | null,
    now: Date,
    maxAgeMs: number,
  ): { taskId: string; why: "stale-mirror" | "external-closed" | "dispatch-revoked" | "plane-blocked" }[] {
    const rows = this.db
      .prepare(
        `SELECT external_mirror.local_task_id AS id, task_ref.id AS ref FROM external_mirror
           JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = external_mirror.local_task_id
           JOIN task ON task.id = external_mirror.local_task_id
          WHERE task.state = 'queued' AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
          LIMIT 100`,
      )
      .all(BUILT_IN, repo, repo);
    const skipped: { taskId: string; why: "stale-mirror" | "external-closed" | "dispatch-revoked" | "plane-blocked" }[] = [];
    for (const row of rows) {
      const why = this.mirrorAdmissionRefusal(Number(row["ref"]), now, maxAgeMs);
      if (why !== null && why !== "not-a-mirror") skipped.push({ taskId: String(row["id"]), why });
    }
    return skipped;
  }

  /** Whether a fresh completion may stand as done (v4 §24) — read INSIDE
   * completeFenced's transaction. Non-mirrors always complete. */
  mirrorAllowsCompletion(taskId: string): boolean {
    const row = this.db
      .prepare("SELECT remote_state, dispatch_ok FROM external_mirror WHERE local_task_id = ?")
      .get(taskId);
    if (row === undefined) return true;
    return String(row["remote_state"]) === "open" && Number(row["dispatch_ok"]) === 1;
  }

  /** Whether a stored acquire mutation exists — the replay marker's fact. */
  hasMutationRecord(mutation: Mutation): boolean {
    if (mutation.idempotencyKey === undefined) return false;
    const row = this.db
      .prepare("SELECT 1 AS hit FROM mutation WHERE idempotency_key = ? LIMIT 1")
      .get(mutation.idempotencyKey);
    return row !== undefined;
  }

  enqueueExternalIntent(
    mirror: string,
    kind: "comment" | "transition" | "close",
    body: string | null,
    now: Date,
  ): void {
    this.db
      .prepare("INSERT INTO external_intent (mirror, kind, body, created_at) VALUES (?, ?, ?, ?)")
      .run(mirror, kind, body, now.toISOString());
  }

  pendingExternalIntents(limit = 50): { id: number; mirror: string; kind: "comment" | "transition" | "close"; body: string | null; attempts: number }[] {
    return this.db
      .prepare("SELECT id, mirror, kind, body, attempts FROM external_intent WHERE state = 'pending' ORDER BY id LIMIT ?")
      .all(Math.max(1, Math.min(limit, 200)))
      .map(row => ({
        id: Number(row["id"]),
        mirror: String(row["mirror"]),
        kind: String(row["kind"]) as "comment" | "transition" | "close",
        body: row["body"] === null ? null : String(row["body"]),
        attempts: Number(row["attempts"]),
      }));
  }

  settleExternalIntent(id: number, state: "delivered" | "refused", now: Date, error: string | null = null): void {
    this.db
      .prepare(
        `UPDATE external_intent SET state = ?, attempts = attempts + 1, last_error = ?,
           delivered_at = CASE WHEN ? = 'delivered' THEN ? ELSE delivered_at END
         WHERE id = ?`,
      )
      .run(state, error, state, now.toISOString(), id);
  }

  /** Marker verification writes its verdict here — fail closed, typed. */
  setDispatchBlocked(
    repo: string,
    backend: string,
    blocked: "pending-marker" | "unreachable" | "foreign" | "missing" | "multiple-or-malformed" | null,
    now: Date,
    detail: string | null = null,
  ): void {
    this.db
      .prepare(
        `UPDATE backend_grant SET dispatch_blocked = ?, dispatch_blocked_at = ?, dispatch_blocked_detail = ?
          WHERE repo = ? AND backend = ?`,
      )
      .run(blocked, blocked === null ? null : now.toISOString(), detail, repo, backend);
  }

  /** null is denial, and is the answer for anything never enrolled. */
  grantFor(repo: string, backend: string): BackendGrant | null {
    const row = this.db
      .prepare("SELECT * FROM backend_grant WHERE repo = ? AND backend = ?")
      .get(repo, backend);
    return row === undefined ? null : readGrant(row);
  }

  listGrants(): BackendGrant[] {
    return this.db
      .prepare("SELECT * FROM backend_grant ORDER BY repo, backend")
      .all()
      .map(readGrant);
  }

  revokeGrant(repo: string, backend: string, mutation: Mutation = {}): boolean {
    return this.once(
      mutation,
      "revokeGrant",
      () => {
        const { changes } = this.db
          .prepare("DELETE FROM backend_grant WHERE repo = ? AND backend = ?")
          .run(repo, backend);
        return Number(changes) > 0;
      },
      revoked => revoked,
    );
  }

  // ---- scope --------------------------------------------------------------

  saveScope(
    scope: Scope,
    mutation: Mutation = {},
    options: {
      profile?: ExecutionProfile;
      /** v48: a FROZEN route — a routine firing's approved snapshot —
       * filed verbatim instead of being recommended afresh from today's
       * configuration. Requires an explicit profile, and the two must
       * agree exactly (the same belt every other road wears). */
      route?: PhaseRoute;
      permissionMode?: UnattendedPermissionMode;
      qualityMode?: QualityMode;
      riskLevel?: RiskLevel;
      posture?: "escalated";
      proposedVia?: "mate" | "coordinator" | "scout" | null;
    } = {},
  ): void {
    this.once(mutation, "saveScope", () => this.transact(() => {
      // THE filing invariant (foundations findings 5/13/19): every scope
      // row leaves this method either RESOLVED (working profile stamped,
      // digest recomputed to bind it, version 2) or UNRESOLVED with its
      // reason in words — saved atomically either way, because refusing
      // after the caller already validated everything else would strand
      // planner and revision output (finding 19). An explicit options
      // profile wins (routine firings stamp the routine's APPROVED
      // profile; demo stamps its illustrative one); otherwise resolution
      // runs pin > project > installation > default with the exact-model
      // rule.
      let profile: ExecutionProfile | null = options.profile ?? null;
      let unresolvedReason: string | null = null;
      let provenance: string | null = options.profile === undefined ? null : JSON.stringify({ resolvedFrom: "explicit" });
      const ref = this.lookupRef(scope.taskId);
      // Sprint 8: the organisation policy's permission ceiling lowers what a new filing asks for (a mode's escalated
      // posture, the installation default, the task's own choice) before anyone reads or signs it.
      const orgPolicy = this.orgPolicy();
      const escalatedAllowed = orgPolicy.ceiling === "escalated";
      const asked: UnattendedPermissionMode =
        options.posture === "escalated"
          ? "bypassPermissions"
          : options.permissionMode ?? ref?.permissionMode ?? this.permissionDefault().mode;
      const permissionMode: UnattendedPermissionMode = escalatedAllowed ? asked : "auto";
      const qualityMode: QualityMode = options.qualityMode ?? ref?.qualityMode ?? this.qualityDefault().mode;
      // A form/CLI choice is a durable TASK choice. The active operating
      // mode's escalated posture is intentionally not persisted here: when
      // that signed mode expires, a later rewrite falls back to the task's
      // own choice (or the installation default).
      if (options.permissionMode !== undefined && ref !== null) {
        this.db.prepare("UPDATE task_ref SET permission_mode = ? WHERE id = ?").run(options.permissionMode, ref.id);
      }
      if (options.qualityMode !== undefined && ref !== null) {
        this.db.prepare("UPDATE task_ref SET quality_mode = ? WHERE id = ?").run(options.qualityMode, ref.id);
      }
      // THE ROUTE (v47): recommended once, here, from signed facts — risk,
      // quality, the rubric's evidence needs, publication authority — over
      // the CONFIGURED candidate tiers, the task's recorded overrides, and
      // its pins. EVERY leg is exact (provider and model id); the build and
      // repair legs then DRIVE the execution profile below, so the sealed
      // profile and the sealed route can never disagree. A configuration
      // that cannot make an exact, runnable route files the scope
      // UNRESOLVED with the words — never a guess, never a substitution.
      const riskLevel: RiskLevel = options.riskLevel ?? ref?.riskLevel ?? "routine";
      if (options.riskLevel !== undefined && ref !== null) {
        this.db.prepare("UPDATE task_ref SET risk_level = ? WHERE id = ?").run(options.riskLevel, ref.id);
      }
      let route: PhaseRoute | null = null;
      const overrides = ref === null || ref.routeOverrides === undefined ? [] : ref.routeOverrides;
      // An explicit profile (a routine firing's APPROVED profile, the
      // demo's illustrative one) is the build AND repair pin: the route
      // restates it exactly, never re-resolves it.
      const buildPin =
        options.profile !== undefined
          ? { ok: true as const, pin: { provider: options.profile.provider, model: options.profile.model } }
          : exactPinOf(ref?.agentProvider ?? null, ref?.agentModel ?? null, "build");
      const repairPin: ExactSpec | null =
        options.profile === undefined ? null : { provider: options.profile.provider, model: options.profile.repairModel === "inherit" ? options.profile.model : options.profile.repairModel };
      const planPin = exactPinOf(ref?.planProvider ?? null, ref?.planModel ?? null, "plan");
      const candidatesResolved: ReturnType<typeof resolveRouteCandidates> =
        options.route !== undefined
          ? { ok: false, phase: "build", problem: "a frozen route never consults today's configuration" }
          : resolveRouteCandidates(this, ref?.repo ?? null, { plan: planPin.ok ? planPin.pin : null, build: buildPin.ok ? buildPin.pin : null });
      if (options.route !== undefined) {
        // The frozen road (v48): a routine firing files the route its
        // approval sealed, byte for byte. Nothing here re-reads
        // configuration — a later `config set` cannot touch a firing.
        if (options.profile === undefined) {
          unresolvedReason = "a frozen agent route needs the approved agent profile beside it — the firing cannot file";
        } else {
          route = options.route;
          const problems = routeProblems(route);
          if (problems.length > 0) unresolvedReason = problems.join("; ");
        }
      } else if (!candidatesResolved.ok) {
        unresolvedReason = candidatesResolved.problem;
      } else if (overrides === null) {
        unresolvedReason = "the task's recorded route overrides cannot be read — clear or re-record them with `task route`";
      } else if (!buildPin.ok) {
        unresolvedReason = buildPin.problem;
      } else if (!planPin.ok) {
        unresolvedReason = planPin.problem;
      } else {
        route = recommendRoute({
          risk: riskLevel,
          qualityMode,
          evidence: [...new Set(scope.acceptance.flatMap(one => one.evidence))] as RouteEvidenceKind[],
          publication: this.publicationAuthorityOf(ref?.repo ?? null, new Date(scope.proposedAt)),
          candidates: candidatesResolved.candidates,
          overrides,
          pins: { plan: planPin.pin, build: buildPin.pin, repair: repairPin },
          // v2: the task's size and each provider's plan headroom, sealed
          // with the route like every other input.
          size: ref?.sizing ?? null,
          headroom: this.planHeadroom(new Date(scope.proposedAt)),
        });
        const problems = routeProblems(route);
        if (problems.length > 0) unresolvedReason = problems.join("; ");
      }
      // The tier the build leg runs on, recorded per task for the spend report.
      if (route !== null && ref !== null) {
        const buildLeg = legOf(route, "build");
        this.db.prepare("UPDATE task_ref SET route_tier = ? WHERE id = ?").run(buildLeg.chosen === "recommended" ? buildLeg.tier : buildLeg.chosen, ref.id);
      }
      if (unresolvedReason !== null) {
        // Fail closed: an explicit profile does not outrank a route that
        // cannot be made exact — the scope says why, and nothing runs.
        profile = null;
      } else if (route !== null) {
        const buildLeg = legOf(route, "build");
        const repairLeg = legOf(route, "repair");
        if (profile === null) {
          // The repair model rides as a flag only when the leg says more
          // than "the build's own model" — an inheriting repair stays the
          // stable literal "inherit" (= the exact build model), so a
          // profile's bytes do not change for saying the same thing.
          const inheriting = candidatesResolved.ok && candidatesResolved.candidates.repair.routine === null && repairLeg.chosen === "recommended" && repairLeg.tier === "routine" && repairLeg.model === buildLeg.model;
          const resolved = resolveScopeProfile(
            this,
            ref?.repo ?? null,
            ref === null ? undefined : { agentProvider: ref.agentProvider, agentModel: ref.agentModel },
            { permissionMode, provider: buildLeg.provider, model: buildLeg.model, ...(inheriting ? {} : { repairModel: repairLeg.model }) },
          );
          if (resolved.ok) {
            profile = resolved.profile;
            provenance = JSON.stringify({
              resolvedFrom: "route",
              routineFrom: candidatesResolved.ok ? candidatesResolved.candidates.build.routine.source : null,
              repairFrom: "route",
              routeDigest: routeDigestOf(route),
            });
          } else {
            unresolvedReason = resolved.problem;
          }
        }
        // The exactness belt: whatever road produced the profile, it must
        // BE the route's build and repair legs — a disagreement here is a
        // bug in resolution, and it files unresolved rather than sealing
        // two authorities.
        if (profile !== null) {
          const repairModel = profile.repairModel === "inherit" ? profile.model : profile.repairModel;
          if (profile.provider !== buildLeg.provider || profile.model !== buildLeg.model || repairModel !== repairLeg.model) {
            unresolvedReason = `the agent profile (${profile.provider} · ${profile.model}, repair ${repairModel}) does not match the route (${buildLeg.provider} · ${buildLeg.model}, repair ${repairLeg.model}) — re-file the scope`;
            profile = null;
          }
        }
      }
      // Explicit profiles normally win byte-for-byte (routine firings and
      // demo fixtures depend on that). The signed operating mode's
      // escalated posture is the one exception, retained from C7: it must
      // apply even when a CLI caller supplied a concrete profile.
      if (options.posture === "escalated" && escalatedAllowed && profile !== null) {
        profile =
          profile.provider === "claude"
            ? { ...profile, permissionArgv: "bypassPermissions" }
            : profile.provider === "gemini"
              ? { ...profile, approvalArgv: "yolo" }
              : { ...profile, sandboxMode: "danger-full-access" };
      }
      // Anything still above the ceiling files at the highest level beneath it its provider has; a provider with none
      // keeps its terms, and approval refuses them in words.
      const lowered = (one: ExecutionProfile): ExecutionProfile => { const verdict = underCeiling(orgPolicy, one); return verdict.ok ? verdict.profile : one; };
      if (profile !== null) profile = lowered(profile);
      const digestInput = {
        goal: scope.goal,
        outOfScope: scope.outOfScope,
        touches: scope.touches,
        budgetMicrousd: scope.budgetMicrousd,
        acceptance: scope.acceptance,
        qualityMode,
        candidate: scope.candidate ?? null,
      };
      // EVERY route filed since v47 binds into the digest — routine-shaped
      // ones included — so approval freezes exactly which agent runs each
      // phase, and a route edit stales it. An unresolved scope still binds
      // whatever route it managed to compute (a stated problem is a term
      // too); only a row with no route at all keeps the caller's draft
      // digest, and it can never be approved.
      const digest =
        profile === null
          ? route !== null || qualityMode === "strict" ? digestOf(digestInput, null, route) : scope.digest
          : digestOf(digestInput, profile, route);
      // The fallback-chain binding (v30): when the scope resolved FROM CONFIG
      // (not an explicit routine/demo profile) and the repo has configured
      // fallbacks, the scope files as a CHAIN — the digest binds the whole
      // ordered chain, and the WORKING snapshot is stored so the seal copies
      // it verbatim (never re-resolves), exactly as approved_profile_json
      // mirrors profile_json. Inert until an operator configures fallbacks:
      // with none — every repo today — proposedChainJson stays NULL and the
      // digest is the byte-identical single-profile binding. A malformed or
      // duplicate chain config does NOT corrupt the scope: it files honestly
      // as the single profile, and the config error surfaces at the config
      // surface, never here.
      let proposedChainJson: string | null = null;
      let boundDigest = digest;
      // THE AUTH MODE AT FILING (atomic authority closure): the credential
      // the resolved profile's provider would spend under is read strictly
      // here, on every road — explicit profile or resolved — so a present
      // mode file that says neither word files the scope UNRESOLVED in its
      // words rather than sealing a credential nobody chose. The seal, the
      // consent door, and the spawn read the same way.
      if (profile !== null) {
        const filedAuth = readAuthModeStrict(profile.provider);
        if (!filedAuth.ok) {
          profile = null;
          unresolvedReason = filedAuth.problem;
          boundDigest = digestOf(digestInput, null, route);
        }
      }
      if (options.profile === undefined && profile !== null) {
        const chainRef = this.lookupRef(scope.taskId);
        const chainRepo = chainRef?.repo ?? null;
        // A fallback row that cannot be READ is a stated problem (v48):
        // the scope files unresolved in its words rather than sealing a
        // single profile as if nothing had been configured.
        const fallbackProblem = chainRepo === null ? null : this.fallbackConfigProblem(chainRepo);
        if (fallbackProblem !== null) {
          profile = null;
          unresolvedReason = `the configured fallback chain cannot file: ${fallbackProblem}`;
          boundDigest = digestOf(digestInput, null, route);
        } else if (chainRepo !== null && this.fallbackConfig(chainRepo).length > 0) {
          // The base entry's auth mode is read STRICTLY (raw authority
          // repair): a stored auth-mode file that says neither word is a
          // stated problem, never the subscription default — the scope
          // files unresolved in its words rather than sealing a credential
          // the operator never chose.
          const baseAuth = readAuthModeStrict(profile.provider);
          const chain = baseAuth.ok
            ? resolveScopeChain(
                this,
                chainRepo,
                chainRef === null ? undefined : { agentProvider: chainRef.agentProvider, agentModel: chainRef.agentModel },
                { permissionMode, provider: profile.provider, model: profile.model, repairModel: profile.repairModel },
                baseAuth.mode,
              )
            : { ok: false as const, reason: "bad-auth-mode" as const, problem: baseAuth.problem };
          if (chain.ok && chain.kind === "chain") {
            chain.chain = chain.chain.map(entry => ({ ...entry, profile: lowered(entry.profile) }));
            proposedChainJson = canonicalChainJson(chain.chain);
            boundDigest = digestOf(
              { goal: scope.goal, outOfScope: scope.outOfScope, touches: scope.touches, budgetMicrousd: scope.budgetMicrousd, acceptance: scope.acceptance, qualityMode },
              { chain: chain.chain },
              route,
            );
          } else if (!chain.ok) {
            // The operator CONFIGURED fallbacks that cannot file (F+G
            // review, finding 4): silently filing single-profile would
            // approve something other than what they believe they set. The
            // scope goes VISIBLY unresolved — dispatch and approval both
            // blocked, the reason in words — until the config or the base
            // routing is fixed.
            profile = null;
            unresolvedReason = `the configured fallback chain cannot file: ${chain.problem} — fix \`config set fallback\` for this repository, or clear it`;
            boundDigest = digestOf(digestInput, null, route);
          }
        }
      }
      this.db
        .prepare(
          `INSERT INTO task_scope
             (task_id, goal, out_of_scope, touches, budget_microusd, proposed_at, digest, approved_at, approved_by, approved_digest,
              profile_json, profile_state, unresolved_reason, digest_version, profile_provenance, proposed_chain_json, acceptance_json, quality_mode,
              risk_level, proposed_route_json, route_era, candidate)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
           ON CONFLICT (task_id) DO UPDATE SET
             goal = excluded.goal, out_of_scope = excluded.out_of_scope,
             touches = excluded.touches, budget_microusd = excluded.budget_microusd,
             proposed_at = excluded.proposed_at,
             digest = excluded.digest, approved_at = excluded.approved_at,
             approved_by = excluded.approved_by, approved_digest = excluded.approved_digest,
             profile_json = excluded.profile_json, profile_state = excluded.profile_state,
             unresolved_reason = excluded.unresolved_reason, digest_version = excluded.digest_version,
             profile_provenance = excluded.profile_provenance, proposed_chain_json = excluded.proposed_chain_json,
             acceptance_json = excluded.acceptance_json, quality_mode = excluded.quality_mode,
             risk_level = excluded.risk_level, proposed_route_json = excluded.proposed_route_json, route_era = excluded.route_era,
             candidate = excluded.candidate`,
        )
        .run(
          scope.taskId,
          scope.goal,
          scope.outOfScope,
          JSON.stringify(scope.touches),
          scope.budgetMicrousd ?? null,
          scope.proposedAt,
          boundDigest,
          scope.approvedAt,
          scope.approvedBy,
          scope.approvedDigest,
          profile === null ? null : canonicalProfileJson(profile),
          profile === null ? "unresolved" : "resolved",
          unresolvedReason,
          profile === null ? 1 : 2,
          provenance,
          proposedChainJson,
          scope.acceptance.length === 0 ? null : JSON.stringify(scope.acceptance),
          qualityMode,
          riskLevel,
          route === null ? null : canonicalRouteJson(route),
          // The durable era: every row this method writes is a routed row.
          ROUTE_ERA,
          scope.candidate ?? null,
        );
      // Who wrote THIS text (mate arc, ruling 2): set per write, so a human
      // rewrite clears the mate's mark and a mate rewrite sets it.
      this.db.prepare("UPDATE task_scope SET proposed_via = ? WHERE task_id = ?").run(options.proposedVia ?? null, scope.taskId);
      return null;
    }));
  }

  /**
   * Re-file a scope under its OWN current words (v47): the route is
   * recomputed from the task's risk, overrides, and today's configuration,
   * the digest recomputed to bind it, and everything an operator wrote —
   * goal, boundaries, rubric, quality, budget, who authored it — carried
   * verbatim. The previous approval is kept and goes stale by the digest
   * exactly as a rewrite would. Null when the task has no scope.
   */
  refileScope(taskId: string, now: Date): Scope | null {
    return this.transact(() => {
      const row = this.db.prepare("SELECT * FROM task_scope WHERE task_id = ?").get(taskId);
      if (row === undefined) return null;
      const scope = readScope(row);
      const proposedVia = row["proposed_via"] === null || row["proposed_via"] === undefined ? null : (String(row["proposed_via"]) as "mate" | "coordinator" | "scout");
      const draft = { goal: scope.goal, outOfScope: scope.outOfScope, touches: scope.touches, budgetMicrousd: scope.budgetMicrousd, acceptance: scope.acceptance, qualityMode: scope.qualityMode ?? "default" };
      this.saveScope(
        { ...scope, proposedAt: now.toISOString(), digest: digestOf(draft) },
        {},
        { qualityMode: scope.qualityMode ?? "default", proposedVia },
      );
      return this.getScope(taskId);
    });
  }

  /** The approval SEAL (foundations finding 4/17): stamps the approval
   * fields and snapshots the CURRENT working profile as the immutable
   * approved profile — one UPDATE, no re-resolution, so what is sealed is
   * exactly what the signed digest was bound to. Returns false when the
   * scope vanished mid-ceremony. */
  sealScopeApproval(taskId: string, by: string, now: Date, mutation: Mutation = {}, basis?: { kind: "mode"; modeDigest: string }, approverKind?: ApproverKind): boolean {
    return (
      this.once(mutation, "sealScopeApproval", () => {
        // THE COORDINATOR QUARANTINE, enforced in the primitive (MCP spec
        // v6, round-3 f1): mode coverage never admits a coordinator-filed
        // task — console, CLI `task scope`, and direct callers alike hit
        // this wall. The promise to the operator is a fresh password
        // ceremony that shows WHO asked; only `basis: password` seals it.
        if (basis !== undefined) {
          const filedByCoordinator = this.db
            .prepare("SELECT 1 AS hit FROM task_ref WHERE backend = ? AND external_id = ? AND coordinator_cid IS NOT NULL")
            .get(BUILT_IN, taskId);
          if (filedByCoordinator !== undefined) return false;
          // THE MATE QUARANTINE (mate arc, ruling 2): a scope a confirmed
          // mate proposal wrote is model-authored text; mode coverage never
          // seals it. Only the password ceremony — which shows the operator
          // every word — approves it.
          const writtenByMate = this.db
            .prepare("SELECT 1 AS hit FROM task_scope WHERE task_id = ? AND proposed_via IN ('mate','coordinator','scout')")
            .get(taskId);
          if (writtenByMate !== undefined) return false;
        }
        // SEPARATION OF DUTIES (v102), enforced in the primitive so no road
        // around it exists: a project's rules can refuse the requester, and
        // protected work seals only once two people approved these exact
        // bytes (the ceremony records each vote first) — never on a mode,
        // a routine or an AI teammate's word.
        const kind: ApproverKind = approverKind ?? (basis !== undefined ? "mode" : by.endsWith(" (AI)") ? "ai" : "person");
        if (this.approvalGate(taskId, by, kind).verdict !== "seal") return false;
        // Sprint 8: the organisation policy, on every road that seals (a person's yes says why first).
        if (this.scopePolicyRefusal(taskId) !== null) return false;
        // THE SEAL'S BELT (v47, one strict projection since the v48
        // integrity repair): the row seals only what `scopeAuthorityOf`
        // proves from its raw bytes — exact-key profile, chain, and route;
        // safe integers and timer-safe clocks; a well-formed auth mode on
        // every chain entry; build/repair parity between route and
        // profile; the profile as the chain's entry zero; and the digest
        // re-derived, complete, from those very values. A row that
        // predates routing (no era) cannot take a NEW yes: an approval now
        // names exactly which agent plans, builds, repairs, and reviews,
        // and this row names none — re-filing routes it (an old approval
        // already on such a row is grandfathered; this only refuses to
        // mint another). A route with a stated leg problem seals nothing.
        const working = this.db.prepare("SELECT * FROM task_scope WHERE task_id = ?").get(taskId) as Record<string, unknown> | undefined;
        if (working === undefined) return false;
        const authority = scopeAuthorityOf(readScope(working), { authMode: provider => readAuthModeStrict(provider) });
        if (!authority.ok) return false;
        if (routeProblems(authority.route).length > 0) return false;
        const changed = this.db
          .prepare(
            `UPDATE task_scope
                SET approved_at = ?, approved_by = ?, approved_digest = digest,
                    approved_profile_json = profile_json,
                    approval_basis = ?, mode_digest = ?,
                    -- The chain snapshot seals exactly as the profile does:
                    -- COPY the working proposed_chain_json into the immutable
                    -- approved_chain_json, and set approval_kind from whether
                    -- one exists. Because saveScope bound the signed digest to
                    -- that same proposed chain, what is sealed is byte-for-byte
                    -- what the approver agreed to — never re-resolved. A
                    -- rewritten-then-reapproved scope re-seals from its CURRENT
                    -- working snapshot, so a stale chain can never survive.
                    approved_chain_json = proposed_chain_json,
                    approval_kind = CASE WHEN proposed_chain_json IS NOT NULL THEN 'chain' ELSE 'profile' END,
                    -- The ROUTE seals exactly as the profile and chain do
                    -- (v47): copied, never re-resolved.
                    approved_route_json = proposed_route_json
              WHERE task_id = ?`,
          )
          .run(now.toISOString(), by, basis === undefined ? "password" : basis.kind, basis === undefined ? null : basis.modeDigest, taskId);
        if (changed.changes > 0) {
          // The project's tools this yes saw (v80): a later addition needs a later yes.
          this.sealProjectTools(taskId, String(working["digest"]), now);
          // A fresh yes lifts the stale-approval hold and closes its page
          // (setup review): the approval is what was stale, and it is new.
          const ref = this.db.prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?").get(BUILT_IN, taskId);
          if (ref !== undefined) {
            if (basis === undefined) this.noteTaskAct(Number(ref["id"]), "approved", now);
            this.db.prepare("DELETE FROM hold WHERE owner_kind = 'backoff' AND owner_id = ?").run(`stale:${Number(ref["id"])}`);
            this.db
              .prepare("UPDATE notification SET resolved_at = ? WHERE dedupe_key LIKE ? AND resolved_at IS NULL")
              .run(now.toISOString(), `stale-approval:${Number(ref["id"])}:%`);
            // The approval fact (Telegram task updates): a NEW yes on these
            // exact bytes. Re-sealing an approval that already stands on
            // the same digest is the same state and says nothing.
            const alreadyOn = working["approved_at"] == null ? null : working["approved_digest"];
            if (alreadyOn !== working["digest"]) {
              this.noteLifecycle(
                {
                  taskRef: Number(ref["id"]), kind: "scope-approved", identity: `t${Number(ref["id"])}`,
                  subject: "Scope approved",
                  body: basis === undefined
                    ? `Approved by ${currentActor()?.lead === true ? "the lead" : lifecycleWords(by, 40)}. A connected worker can take it next.`
                    : "Approved automatically under the operating mode. A connected worker can take it next.",
                  link: chatControlHref("task", taskId),
                },
                now,
              );
            }
          }
        }
        return changed.changes > 0;
      }) === true
    );
  }

  /** Whether this task's scope carries a LIVE seal: approved, and the
   * approved digest is the current one (a rewritten scope unseals). The
   * coordinator quarantine's one question (MCP spec v6). */
  scopeSealed(taskId: string): boolean {
    const row = this.db
      .prepare(
        "SELECT 1 AS hit FROM task_scope WHERE task_id = ? AND approved_at IS NOT NULL AND approved_digest = digest",
      )
      .get(taskId);
    return row !== undefined;
  }

  getScope(taskId: string): Scope | null {
    const row = this.db.prepare("SELECT * FROM task_scope WHERE task_id = ?").get(taskId);
    return row === undefined ? null : readScope(row);
  }

  /**
   * The mode-approval belt, as ONE question every consumer asks the same
   * way (Codex people round 2, finding 2): false exactly when this task's
   * approval was sealed by a mode signature that no longer stands — the
   * signed row live by CLOCK (durable closure not required), the digest
   * exact, the signer an active approver. Password-sealed and unapproved
   * scopes answer true: this belt only ever REMOVES mode authority.
   */
  modeApprovalLive(taskRef: number, now: Date): boolean {
    const dead = this.db
      .prepare(
        `SELECT 1 AS dead FROM task_scope
          JOIN task_ref ON task_ref.id = ? AND task_ref.backend = 'built-in' AND task_scope.task_id = task_ref.external_id
         WHERE task_scope.approval_basis = 'mode' AND task_scope.approved_at IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM operating_mode om
                            JOIN approver signer ON signer.name = om.signed_by
                           WHERE om.repo = task_ref.repo AND om.revoked_at IS NULL
                             AND om.absolute_expiry > ? AND om.digest = task_scope.mode_digest
                             AND signer.revoked_at IS NULL AND signer.role = 'approver')`,
      )
      .get(taskRef, now.toISOString());
    return dead === undefined;
  }

  // ---- approvers ----------------------------------------------------------

  saveApprover(name: string, credentialHash: string, now: Date, mutation: Mutation = {}): void {
    this.once(mutation, "saveApprover", () => {
      // Replacing a credential is a rotation: the generation moves, and
      // everything that derived authority from the old one — a paired chat,
      // an outstanding pairing code — is stranded by the comparison, then
      // swept by revokeDerivedAuthority in the same transaction.
      this.transact(() => {
        this.db
          .prepare(
            `INSERT INTO approver (name, credential_hash, added_at, generation) VALUES (?, ?, ?, 1)
             ON CONFLICT (name) DO UPDATE SET credential_hash = excluded.credential_hash,
                                              added_at = excluded.added_at,
                                              generation = approver.generation + 1`,
          )
          .run(name, credentialHash, now.toISOString());
        this.revokeDerivedAuthority(name, "credential-rotation", now);
      });
      return null;
    });
  }

  /** The full account row for identity checks (v29): hash, role,
   * generation, revocation — one read, no inference. */
  accountOf(name: string): { credentialHash: string; role: "approver" | "viewer"; generation: number; revokedAt: string | null; projects: ProjectAccess } | null {
    const row = this.db
      .prepare("SELECT credential_hash, role, generation, revoked_at, projects_json FROM approver WHERE name = ?")
      .get(name);
    if (row === undefined) return null;
    return {
      projects: readProjectAccess(row["projects_json"]),
      credentialHash: String(row["credential_hash"]),
      role: String(row["role"]) === "viewer" ? "viewer" : "approver",
      generation: Number(row["generation"]),
      revokedAt: row["revoked_at"] === null || row["revoked_at"] === undefined ? null : String(row["revoked_at"]),
    };
  }

  // ---- operating modes (v29, the modes chain) ---------------------------

  /** The live mode for a repo: unrevoked, unexpired, its SIGNER still an
   * active approver (D7's belt — a missed cascade cannot leave a dead
   * signer's authority alive). Expired-but-unrevoked rows are closed here,
   * durably, so the partial unique can never wedge a replacement. */
  activeMode(repo: string, now: Date): { id: number; name: string; termsJson: string; digest: string; signedBy: string; absoluteExpiry: string } | null {
    const row = this.db
      .prepare(
        `SELECT operating_mode.* FROM operating_mode
          JOIN approver ON approver.name = operating_mode.signed_by AND approver.revoked_at IS NULL AND approver.role = 'approver'
         WHERE operating_mode.repo = ? AND operating_mode.revoked_at IS NULL`,
      )
      .get(repo);
    if (row === undefined) return null;
    if (Date.parse(String(row["absolute_expiry"])) <= now.getTime()) {
      this.transact(() => {
        this.db
          .prepare("UPDATE operating_mode SET revoked_at = ?, revoked_by = ?, revoke_reason = 'expired' WHERE id = ? AND revoked_at IS NULL")
          .run(now.toISOString(), "the-clock", Number(row["id"]));
        this.db
          .prepare("INSERT INTO operating_mode_event (mode, kind, actor, at) VALUES (?, 'expired-closed', 'the-clock', ?)")
          .run(Number(row["id"]), now.toISOString());
        this.reconcileIntentsForMode(String(row["repo"]), null, now);
      });
      return null;
    }
    return {
      id: Number(row["id"]),
      name: String(row["name"]),
      termsJson: String(row["terms_json"]),
      digest: String(row["digest"]),
      signedBy: String(row["signed_by"]),
      absoluteExpiry: String(row["absolute_expiry"]),
    };
  }

  /** Sign (or renew) a mode: closes any predecessor with a typed event and
   * ATOMICALLY reconciles the repo's nonterminal merge intents to the new
   * posture (F2). The caller has already run the password ceremony. */
  signMode(
    spec: { repo: string; name: string; termsJson: string; digest: string; signedBy: string; absoluteExpiry: string; publication: "notify" | "automerge" },
    now: Date,
  ): number {
    return this.transact(() => {
      // The automerge prerequisite, proved INSIDE the signature (Codex
      // surfaces round 1, finding 4): a grant revoked between the screen
      // and the signature must lose — the pre-checks only shape the words.
      if (spec.publication === "automerge" && !this.hasMergeCapableGrant(spec.repo, now)) {
        throw new Error("automerge needs a merge-capable publication grant — grant one, then sign");
      }
      const previous = this.db
        .prepare("SELECT id FROM operating_mode WHERE repo = ? AND revoked_at IS NULL")
        .get(spec.repo);
      const renewal = previous !== undefined;
      if (renewal) {
        this.db
          .prepare("UPDATE operating_mode SET revoked_at = ?, revoked_by = ?, revoke_reason = 'renewed' WHERE id = ?")
          .run(now.toISOString(), spec.signedBy, Number(previous["id"]));
      }
      const inserted = this.db
        .prepare(
          `INSERT INTO operating_mode (repo, name, terms_json, digest, signed_by, signed_at, absolute_expiry)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(spec.repo, spec.name, spec.termsJson, spec.digest, spec.signedBy, now.toISOString(), spec.absoluteExpiry);
      const id = Number(inserted.lastInsertRowid);
      this.db
        .prepare("INSERT INTO operating_mode_event (mode, kind, actor, at) VALUES (?, ?, ?, ?)")
        .run(id, renewal ? "renewed" : "signed", spec.signedBy, now.toISOString());
      this.recordAction({ at: now.toISOString(), actor: spec.signedBy, repo: spec.repo, taskId: null, runId: null, source: "policy",
        action: `operating mode ${renewal ? "renewed" : "signed"}: ${spec.name}`, outcome: renewal ? "renewed" : "signed", detail: `until ${spec.absoluteExpiry.slice(0, 16).replace("T", " ")} UTC · ${spec.publication === "automerge" ? "merges automatically" : "notifies on results"}` });
      this.reconcileIntentsForMode(spec.repo, { digest: spec.digest, publication: spec.publication }, now);
      return id;
    });
  }

  /** One click for any approver (v4 doctrine): lowering authority needs no
   * ceremony. Reconciliation drops mode-basis intents to waiting-human;
   * `firing` rows are untouched — an issued call is one-shot (E1). */
  revokeMode(repo: string, by: string, reason: string, now: Date): boolean {
    return this.transact(() => {
      const row = this.db
        .prepare("SELECT id FROM operating_mode WHERE repo = ? AND revoked_at IS NULL")
        .get(repo);
      if (row === undefined) return false;
      this.db
        .prepare("UPDATE operating_mode SET revoked_at = ?, revoked_by = ?, revoke_reason = ? WHERE id = ?")
        .run(now.toISOString(), by, reason, Number(row["id"]));
      this.db
        .prepare("INSERT INTO operating_mode_event (mode, kind, actor, at) VALUES (?, 'revoked', ?, ?)")
        .run(Number(row["id"]), by, now.toISOString());
      this.recordAction({ at: now.toISOString(), actor: by, repo, taskId: null, runId: null, source: "policy", action: "operating mode revoked", outcome: "revoked", detail: reason });
      this.reconcileIntentsForMode(repo, null, now);
      return true;
    });
  }

  /** F2/R-REVOKE: the ONE reconciliation road. newMode null = no live
   * automerge authority (revocation, expiry, or a notify posture):
   * mode-basis pending/claimed intents drop to waiting-human, leases
   * cleared, generations bumped. newMode with automerge: nonterminal
   * grant/mode intents REBIND to the new digest and return to pending.
   * `firing` is never touched by either arm. */
  private reconcileIntentsForMode(repo: string, newMode: { digest: string; publication: "notify" | "automerge" } | null, now: Date): void {
    // MODE-DERIVED SCOPE APPROVALS demote here too (Codex people round 1,
    // finding 2 — R-REVOKE's "next gate" made durable): an approval sealed
    // under a mode signature that no longer stands falls back to the human
    // ceremony. Only UNDISPATCHED work demotes — the task still queued with
    // no live claim; running and finished work keeps its history untouched.
    const demotable = `WHERE approval_basis = 'mode' AND approved_at IS NOT NULL
            AND (? IS NULL OR mode_digest <> ?)
            AND EXISTS (SELECT 1 FROM task_ref JOIN task ON task.id = task_ref.external_id
                         WHERE task_ref.backend = 'built-in'
                           AND task_ref.external_id = task_scope.task_id AND task_ref.repo = ?
                           AND task.state = 'queued')
            AND NOT EXISTS (SELECT 1 FROM claim JOIN task_ref tr ON tr.id = claim.task_ref
                             WHERE tr.backend = 'built-in'
                               AND tr.external_id = task_scope.task_id AND tr.repo = ?
                               AND claim.released_at IS NULL AND claim.expires_at > ?)`;
    const demotableArgs = [
      newMode === null ? null : newMode.digest,
      newMode === null ? null : newMode.digest,
      repo,
      repo,
      now.toISOString(),
    ];
    // Read the exact rows first, in this transaction: each demoted task
    // tells its project's phones the yes it ran on has ended (Telegram
    // task updates) — the same rows the UPDATE below touches, no more.
    const demoted = this.db
      .prepare(`SELECT task_id FROM task_scope ${demotable}`)
      .all(...demotableArgs)
      .map(row => String(row["task_id"]));
    this.db
      .prepare(
        `UPDATE task_scope
            SET approved_at = NULL, approved_by = NULL, approved_digest = NULL,
                approved_profile_json = NULL, approval_basis = 'password', mode_digest = NULL
          ${demotable}`,
      )
      .run(...demotableArgs);
    for (const taskId of demoted) {
      const ref = this.lookupRef(taskId);
      if (ref === null) continue;
      this.noteLifecycle(
        { taskRef: ref.id, kind: "approval-withdrawn", identity: `t${ref.id}`, subject: "Approval needs renewing", body: "The automatic approval it ran under has ended. Approve it again before it runs.", link: chatControlHref("approval", taskId) },
        now,
      );
    }
    const repoIntents = `publication IN (
                SELECT publication.id FROM publication
                  JOIN run ON run.id = publication.run
                  JOIN task_ref ON task_ref.id = run.task_ref
                 WHERE task_ref.repo = ?)`;
    if (newMode !== null && newMode.publication === "automerge") {
      this.db
        .prepare(
          `UPDATE merge_intent SET state = 'pending', authority_basis = 'mode', mode_digest = ?,
                  claimed_by = NULL, claimed_until = NULL, generation = generation + 1
            WHERE state IN ('waiting-human','pending','claimed') AND ${repoIntents}`,
        )
        .run(newMode.digest, repo);
      return;
    }
    if (newMode !== null) {
      // A NOTIFY mode is the operator choosing the stricter posture for
      // the repo (D1): EVERY nonterminal intent waits for a human while it
      // is active — grant basis included. `firing` is untouched (E1).
      this.db
        .prepare(
          `UPDATE merge_intent SET state = 'waiting-human', authority_basis = 'human', mode_digest = NULL,
                  claimed_by = NULL, claimed_until = NULL, generation = generation + 1
            WHERE state IN ('pending','claimed') AND ${repoIntents}`,
        )
        .run(repo);
      return;
    }
    // No live mode (revocation or expiry): only MODE-derived authority
    // dies — a grant-basis intent reverts to the grant's own signature,
    // which the mode never restricted retroactively.
    this.db
      .prepare(
        `UPDATE merge_intent SET state = 'waiting-human', authority_basis = 'human', mode_digest = NULL,
                claimed_by = NULL, claimed_until = NULL, generation = generation + 1
          WHERE state IN ('pending','claimed') AND authority_basis = 'mode' AND ${repoIntents}`,
      )
      .run(repo);
  }

  /** The daily rails' atomic reservation (D4): caps are derived from the
   * ACTIVE mode inside this transaction — never caller-supplied. Returns
   * ok, or the typed rail that refused. Bypass roads never call this. */
  reserveModeRail(repo: string, starts: number, now: Date): { ok: true } | { ok: false; rail: "daily-runs" | "daily-dollars"; detail: string } {
    return this.transact(() => {
      const mode = this.activeMode(repo, now);
      if (mode === null) return { ok: true as const };
      let terms: { dailyRunCap?: number | null; dailyMeasuredCapMicrousd?: number | null };
      try {
        terms = JSON.parse(mode.termsJson) as typeof terms;
      } catch {
        return { ok: true as const };
      }
      const day = now.toISOString().slice(0, 10);
      if (typeof terms.dailyMeasuredCapMicrousd === "number") {
        const spent = this.db
          .prepare(
            `SELECT COALESCE(SUM(CAST(ROUND(run.cost_usd * 1000000) AS INTEGER)), 0) AS total
               FROM run JOIN task_ref ON task_ref.id = run.task_ref
              WHERE task_ref.repo = ? AND run.cost_usd IS NOT NULL
                AND run.provider_started_at >= ? AND run.provider_started_at < ?`,
          )
          .get(repo, `${day}T00:00:00.000Z`, `${day}T23:59:59.999Z`);
        if (Number(spent?.["total"] ?? 0) >= terms.dailyMeasuredCapMicrousd) {
          return {
            ok: false as const,
            rail: "daily-dollars" as const,
            detail: `the day's measured budget ($${(terms.dailyMeasuredCapMicrousd / 1_000_000).toFixed(2)}) is spent — running work may finish; new admissions wait for tomorrow (UTC)`,
          };
        }
      }
      if (typeof terms.dailyRunCap === "number") {
        this.db
          .prepare("INSERT INTO mode_rail (repo, utc_day, reserved_starts) VALUES (?, ?, 0) ON CONFLICT (repo, utc_day) DO NOTHING")
          .run(repo, day);
        const updated = this.db
          .prepare("UPDATE mode_rail SET reserved_starts = reserved_starts + ? WHERE repo = ? AND utc_day = ? AND reserved_starts + ? <= ?")
          .run(starts, repo, day, starts, terms.dailyRunCap);
        if (Number(updated.changes) === 0) {
          return {
            ok: false as const,
            rail: "daily-runs" as const,
            detail: `the day's ${terms.dailyRunCap} agent starts are reserved — new admissions wait for tomorrow (UTC)`,
          };
        }
      }
      return { ok: true as const };
    });
  }

  approverHash(name: string): string | null {
    const row = this.db.prepare("SELECT credential_hash FROM approver WHERE name = ?").get(name);
    return row === undefined ? null : String(row["credential_hash"]);
  }

  approverGeneration(name: string): number | null {
    const row = this.db.prepare("SELECT generation FROM approver WHERE name = ?").get(name);
    return row === undefined ? null : Number(row["generation"]);
  }

  /**
   * Strand everything that speaks for an approver at one remove: live
   * Telegram bindings are revoked (softly — the audit trail stays), unspent
   * pairing codes and unconsumed action tokens die with them. Called on
   * credential rotation and on explicit unpair.
   */
  revokeDerivedAuthority(approver: string, by: string, now: Date): void {
    const stamp = now.toISOString();
    // v99: the machine credentials (coordinators) a person made end with their standing: a revocation or an
    // access change, not a password rotation (a new password is not less trust). Each end is audited as a
    // coordinator revocation, its pending proposals expire with it, and the ledger says why.
    // v101: persisted browser sessions end with every change (they carry the old generation), and API tokens end
    // with a revocation or an access change, not a password change.
    this.db.prepare("DELETE FROM web_session WHERE account = ?").run(approver);
    if (by !== "credential-rotation") {
      for (const row of this.db.prepare("SELECT id FROM api_token WHERE account = ? AND revoked_at IS NULL").all(approver)) this.revokeApiToken(String(row["id"]), by, now, "ended with the account's standing");
      for (const row of this.db.prepare("SELECT cid, name FROM coordinator_credential WHERE created_by = ? AND revoked_at IS NULL").all(approver)) {
        const cid = String(row["cid"]);
        this.db.prepare("UPDATE coordinator_credential SET revoked_at = ? WHERE cid = ?").run(stamp, cid);
        this.db.prepare("INSERT INTO coordinator_event (cid, kind, detail, created_at) VALUES (?, 'revoked', ?, ?)").run(cid, `with ${approver}'s standing, by ${by}`, stamp);
        this.sweepCoordinatorProposals(now, cid);
        this.recordAction({ at: stamp, actor: by, repo: null, taskId: null, runId: null, action: `coordinator revoked: ${String(row["name"])}`, outcome: "revoked", source: "access", detail: `made by ${approver}` });
      }
    }
    // The mate (ruling 10; slice-2 review finding 1): a credential rotation
    // or a revocation ends every session the old standing minted, its live
    // turns (charged whole), and its thread with every proposal in it.
    this.failLiveMateTurnsFor(approver, by === "credential-rotation" ? "rotated" : "revoked", now);
    this.endMateSessionsFor(approver, by, now);
    this.closeMateThreadsFor(approver, now);
    const bindings = this.db
      .prepare("SELECT id FROM telegram_binding WHERE approver = ? AND revoked_at IS NULL")
      .all(approver)
      .map(row => Number(row["id"]));
    this.db
      .prepare(
        "UPDATE telegram_binding SET revoked_at = ?, revoked_by = ? WHERE approver = ? AND revoked_at IS NULL",
      )
      .run(stamp, by, approver);
    for (const binding of bindings) {
      this.db
        .prepare("UPDATE telegram_action SET consumed_at = ? WHERE binding = ? AND consumed_at IS NULL")
        .run(stamp, binding);
    }
    this.db
      .prepare("DELETE FROM telegram_pairing WHERE approver = ? AND consumed_at IS NULL")
      .run(approver);
    // Push enrollments are derived authority too (arc 3 finding 6): the
    // rotation retires every live subscription of the old credential and
    // terminally settles its delivery pairs — claimed ones included, so an
    // in-flight sender's fence fails instead of paging a stranded device.
    const subscriptions = this.db
      .prepare("SELECT id FROM push_subscription WHERE approver = ? AND retired_at IS NULL")
      .all(approver)
      .map(row => Number(row["id"]));
    for (const id of subscriptions) this.retirePushSubscription(id, "credential-rotation", now);
  }

  listApprovers(): { name: string; addedAt: string }[] {
    return this.db
      .prepare("SELECT name, added_at FROM approver ORDER BY name")
      .all()
      .map(row => ({ name: String(row["name"]), addedAt: String(row["added_at"]) }));
  }

  /** Instance administration stays with unrestricted active operators. */
  isInstanceOperator(name: string): boolean {
    const account = this.accountOf(name);
    return account !== null && account.revokedAt === null && account.role === "approver" && account.projects === null;
  }

  accountCanAccess(name: string, repo: string | null): boolean {
    const account = this.accountOf(name);
    return account !== null && account.revokedAt === null && projectAccessAllows(account.projects, repo);
  }

  setAccountProjects(name: string, projects: ProjectAccess, by: string, now: Date): { ok: true } | { ok: false; reason: string } {
    const access = normalizeProjectAccess(projects);
    return this.transact(() => {
      if (!this.isInstanceOperator(by)) return { ok: false as const, reason: "instance-operator-required" };
      const account = this.accountOf(name);
      if (account === null || account.revokedAt !== null) return { ok: false as const, reason: "no-active-account" };
      if (this.isInstanceOperator(name) && access !== null && !this.accountFacts().some(one => one.name !== name && this.isInstanceOperator(one.name))) {
        return { ok: false as const, reason: "last-instance-operator" };
      }
      if (JSON.stringify(account.projects) === JSON.stringify(access)) return { ok: true as const };
      this.db.prepare("UPDATE approver SET projects_json = ?, generation = generation + 1 WHERE name = ?")
        .run(access === null ? null : JSON.stringify(access), name);
      // End derived sessions/grants, preserving completed, explicitly signed
      // instance promises exactly as account revocation already does.
      this.db.prepare("UPDATE attended_authorization SET closed_at = ?, end_reason = 'approver-revoked' WHERE approver = ? AND closed_at IS NULL").run(now.toISOString(), name);
      this.db.prepare("UPDATE invite SET revoked_at = ? WHERE minted_by = ? AND revoked_at IS NULL AND consumed_at IS NULL").run(now.toISOString(), name);
      for (const row of this.db.prepare("SELECT repo FROM operating_mode WHERE signed_by = ? AND revoked_at IS NULL").all(name)) {
        this.revokeMode(String(row["repo"]), by, "operator", now);
      }
      this.revokeDerivedAuthority(name, by, now);
      for (const repo of [...new Set([...(account.projects ?? []), ...(access ?? [])])]) {
        this.recordAction({ at: now.toISOString(), actor: by, repo, taskId: null, runId: null,
          action: `project access changed for ${name}`, outcome: access === null || access.includes(repo) ? "granted" : "removed", source: "access" });
      }
      this.recordAction({ at: now.toISOString(), actor: by, repo: null, taskId: null, runId: null,
        action: `account access changed for ${name}`, outcome: access === null ? "instance access" : `${access.length} projects`, source: "access" });
      return { ok: true as const };
    });
  }

  // ---- Separation of duties (v102) -----------------------------------------

  /** A project's approval rules; no row is no rules. */
  approvalRules(repo: string): ApprovalRules & { updatedBy: string | null; updatedAt: string | null } {
    const row = this.db.prepare("SELECT * FROM approval_policy WHERE repo = ?").get(repo);
    if (row === undefined) return { ...NO_RULES, updatedBy: null, updatedAt: null };
    let paths: string[] = [];
    try { const parsed = JSON.parse(String(row["protected_paths"])); if (Array.isArray(parsed)) paths = parsed.filter((one): one is string => typeof one === "string"); } catch { paths = []; }
    return { notRequester: Number(row["not_requester"]) === 1, protectProject: Number(row["protect_project"]) === 1, protectedPaths: paths, updatedBy: String(row["updated_by"]), updatedAt: String(row["updated_at"]) };
  }

  /** Change a project's rules; the ledger keeps before → after. */
  setApprovalRules(repo: string, next: ApprovalRules, by: string, now: Date): void {
    this.transact(() => {
      const before = this.approvalRules(repo);
      this.db.prepare(`INSERT INTO approval_policy (repo, not_requester, protect_project, protected_paths, updated_by, updated_at) VALUES (?,?,?,?,?,?)
        ON CONFLICT(repo) DO UPDATE SET not_requester = excluded.not_requester, protect_project = excluded.protect_project, protected_paths = excluded.protected_paths, updated_by = excluded.updated_by, updated_at = excluded.updated_at`)
        .run(repo, next.notRequester ? 1 : 0, next.protectProject ? 1 : 0, JSON.stringify(next.protectedPaths), by, now.toISOString());
      this.recordPolicy(by, repo, "approval rules changed", rulesWords(before), rulesWords(next), now);
    });
  }

  /** Who filed a task, when anyone knows. */
  taskFiler(taskId: string): Filer | null {
    const row = this.db.prepare("SELECT filed_by, filed_by_kind FROM task_ref WHERE backend = ? AND external_id = ?").get(BUILT_IN, taskId);
    if (row === undefined || row["filed_by_kind"] == null) return null;
    return { name: row["filed_by"] == null ? null : String(row["filed_by"]), kind: String(row["filed_by_kind"]) as FilerKind };
  }

  /** Everyone who asked for this task's current work: whoever filed it or any
   * task it revises (up to the root), and whoever wrote its current scope.
   * The requester rule refuses all of them. */
  requestersOf(taskId: string): Set<string> {
    const names = new Set<string>();
    const chain = this.revisionAncestryStatus(taskId).chain;
    for (const id of chain.length === 0 ? [taskId] : chain) {
      const filer = this.taskFiler(id);
      if (filer?.name != null && (filer.kind === "person" || filer.kind === "coordinator")) names.add(filer.name);
    }
    // Anyone who wrote any version of its scope (or changed its routing), here or on any task it revises: a
    // revision copies its source's words, and a refile that changes the digest must not wash them clean.
    for (const id of chain.length === 0 ? [taskId] : chain) {
      for (const row of this.db.prepare("SELECT DISTINCT author FROM scope_author WHERE task_id = ?").all(id)) names.add(String(row["author"]));
    }
    return names;
  }

  /** Who wrote these exact scope bytes (a person at a scope edit, a chat confirmation, a coding hand-off). */
  recordScopeAuthor(taskId: string, digest: string, author: string, now: Date): void {
    this.db.prepare("INSERT OR IGNORE INTO scope_author (task_id, digest, author, at) VALUES (?,?,?,?)").run(taskId, digest, author, now.toISOString());
  }

  /** What the project's rules say about `by` approving this task's current scope. */
  approvalGate(taskId: string, by: string, kind: ApproverKind): ApprovalGate {
    const ref = this.db.prepare("SELECT repo FROM task_ref WHERE backend = ? AND external_id = ?").get(BUILT_IN, taskId);
    const scope = this.db.prepare("SELECT digest, touches FROM task_scope WHERE task_id = ?").get(taskId);
    if (ref === undefined || ref["repo"] == null) return { verdict: "seal", protectedWork: false };
    const repo = String(ref["repo"]);
    const rules = this.approvalRules(repo);
    let touches: string[] = [];
    try { const parsed = JSON.parse(String(scope?.["touches"] ?? "[]")); if (Array.isArray(parsed)) touches = parsed.map(String); } catch { touches = []; }
    const protectedWork = isProtectedWork(rules, touches);
    if (!rules.notRequester && !protectedWork) return { verdict: "seal", protectedWork: false };
    if (kind === "ai") return { verdict: "refuse", reason: "person-required" };
    const requesters = rules.notRequester ? this.requestersOf(taskId) : new Set<string>();
    if (requesters.has(by)) return { verdict: "refuse", reason: "requester" };
    if (!protectedWork) return { verdict: "seal", protectedWork: false };
    if (kind !== "person") return { verdict: "refuse", reason: "person-required" };
    // Only people who can still approve here count: a vote from an account since revoked, demoted or moved off the project doesn't.
    const standing = (name: string) => { const account = this.accountOf(name); return account !== null && account.revokedAt === null && account.role === "approver" && this.accountCanAccess(name, repo); };
    const digest = scope === undefined ? "" : String(scope["digest"]);
    const voters = new Set(this.db.prepare("SELECT approver FROM scope_approval_vote WHERE task_id = ? AND digest = ?").all(taskId, digest).map(row => String(row["approver"])).filter(standing));
    const already = voters.has(by);
    voters.add(by);
    for (const name of requesters) voters.delete(name);
    return voters.size >= 2 ? { verdict: "seal", protectedWork: true } : { verdict: "vote", have: voters.size, need: 2, already };
  }

  /** v102: a result that changed protected files, with a scope only one person approved, completes only
   * by someone other than that approver and the requesters (two people have then seen the work). The
   * changed files come from the build's own diff; `null` (unreadable) counts as protected. */
  protectedResultProblem(taskId: string, changed: readonly string[] | null, completer: string | null): string | null {
    const ref = this.db.prepare("SELECT repo FROM task_ref WHERE backend = ? AND external_id = ?").get(BUILT_IN, taskId);
    if (ref === undefined || ref["repo"] == null) return null;
    const repo = String(ref["repo"]);
    const rules = this.approvalRules(repo);
    if (!rules.protectProject && rules.protectedPaths.length === 0) return null;
    const hits = changed === null ? null : protectedChanges(rules, changed);
    if (hits !== null && hits.length === 0) return null;
    const scope = this.db.prepare("SELECT approved_by, approved_digest FROM task_scope WHERE task_id = ?").get(taskId);
    const approvedDigest = scope?.["approved_digest"] == null ? "" : String(scope["approved_digest"]);
    const standing = (name: string) => { const account = this.accountOf(name); return account !== null && account.revokedAt === null && account.role === "approver" && this.accountCanAccess(name, repo); };
    const voters = new Set(this.db.prepare("SELECT approver FROM scope_approval_vote WHERE task_id = ? AND digest = ?").all(taskId, approvedDigest).map(row => String(row["approver"])).filter(standing));
    // Whoever asked for the work never counts as the second pair of eyes on it, whatever the requester rule says.
    const requesters = this.requestersOf(taskId);
    for (const name of requesters) voters.delete(name);
    if (voters.size >= 2) return null;
    const approver = scope?.["approved_by"] == null ? null : String(scope["approved_by"]);
    const what = hits === null ? "files this project protects (its changed files couldn't be read)" : `protected files (${hits.slice(0, 3).join(", ")}${hits.length > 3 ? ` and ${hits.length - 3} more` : ""})`;
    if (completer === null) return `This result changed ${what}, so a person other than its approver marks it complete.`;
    if (completer === approver || requesters.has(completer) || !standing(completer)) return `This result changed ${what}, and ${approver ?? "one person"} approved its scope alone. Someone else has to mark it complete.`;
    return null;
  }

  /** One person's yes to these exact bytes (protected work counts two). */
  recordApprovalVote(taskId: string, digest: string, by: string, now: Date): void {
    const fresh = this.db.prepare("INSERT OR IGNORE INTO scope_approval_vote (task_id, digest, approver, at) VALUES (?,?,?,?)").run(taskId, digest, by, now.toISOString());
    if (fresh.changes > 0) {
      const repo = this.db.prepare("SELECT repo FROM task_ref WHERE backend = ? AND external_id = ?").get(BUILT_IN, taskId)?.["repo"];
      this.recordAction({ at: now.toISOString(), actor: by, repo: repo == null ? null : String(repo), taskId, runId: null, action: "approval recorded", outcome: "recorded", source: "work", detail: `digest ${digest.slice(0, 12)}` });
    }
  }

  /** Who has approved the current scope so far (protected work). */
  approvalVotes(taskId: string): { approver: string; at: string }[] {
    return this.db.prepare(`SELECT v.approver, v.at FROM scope_approval_vote v JOIN task_scope s ON s.task_id = v.task_id AND s.digest = v.digest
      WHERE v.task_id = ? ORDER BY v.at`).all(taskId).map(row => ({ approver: String(row["approver"]), at: String(row["at"]) }));
  }

  // ---- The ledger chain (v103) --------------------------------------------

  /** Seal every ledger entry written since the last seal (the worker does this each pass; readers before they read). */
  sealLedger(): number {
    return this.transact(() => sealLedger(this.db));
  }

  /** Seal if the database is free within a moment; a reader never waits on (or fails for) a busy worker, and what's
   * left is sealed on the worker's next pass (the report counts it as unsealed). */
  private sealIfFree(): void {
    if (this.transacting) { sealLedger(this.db); return; }
    // Nothing new: no lock at all.
    const ends = this.db.prepare(`SELECT (SELECT MAX(id) FROM action_ledger WHERE id ${IN_RANGE}) AS entry, (SELECT MAX(id) FROM ledger_seal WHERE id ${IN_RANGE}) AS seal`).get();
    if (ends !== undefined && ends["entry"] === ends["seal"]) return;
    try { beginWriteWithin(this.db, 200); }
    catch (error) { if (isDatabaseBusy(error)) return; throw error; }
    this.transacting = true;
    try { sealLedger(this.db); this.db.exec("COMMIT"); }
    catch (error) { this.db.exec("ROLLBACK"); throw error; }
    finally { this.transacting = false; }
  }

  /** Reads that must see one moment of the database (the chain and its seals). */
  private readAtOnce<T>(body: () => T): T {
    if (this.transacting) return body();
    this.db.exec("BEGIN");
    try { const result = body(); this.db.exec("COMMIT"); return result; }
    catch (error) { this.db.exec("ROLLBACK"); throw error; }
  }

  /** The head this process last walked the whole chain to (and when), so a page view checks only what's new; and,
   * once the chain has broken, the first break (reported from then on, even if the chain is later rebuilt to look
   * whole) and the latest walk's report (served until the next whole walk, so a broken chain doesn't cost a walk
   * per page view). */
  private chainHead: (VerifiedHead & { checkedAt: string; walkedAt: number }) | null = null;
  private chainBreak: { first: NonNullable<LedgerChainReport["problem"]>; latest: LedgerChainReport; walkedAt: number } | null = null;

  /** The chain, checked: sealed first. The whole chain is walked every ten minutes (or when asked); between walks,
   * only entries after the last walked head, which must itself be unchanged. */
  ledgerChain(options: { full?: boolean; fresh?: number } = {}): LedgerChainReport {
    const WALK_EVERY = 10 * 60_000;
    this.sealIfFree();
    const now = Date.now();
    // `full`: a whole walk, unless one finished within `fresh` ms (so a burst of exports costs one walk).
    const recent = (walkedAt: number) => options.full === true ? options.fresh !== undefined && now - walkedAt <= options.fresh : now - walkedAt <= WALK_EVERY;
    const alarm = this.chainBreak;
    if (alarm !== null && recent(alarm.walkedAt)) return alarm.latest;
    const cached = alarm === null ? this.chainHead : null;
    const whole = cached === null || !recent(cached.walkedAt);
    const checkedAt = whole ? new Date(now).toISOString() : cached!.checkedAt;
    const report = this.readAtOnce(() => verifyLedgerChain(this.db, whole ? undefined : cached!, checkedAt));
    // Inside someone's transaction, what was read may yet roll back: nothing is remembered from it.
    if (this.transacting) return report;
    // A walk counts as fresh from when it finished (a long one mustn't send everyone waiting on it into another).
    const finished = whole ? Date.now() : now;
    if (!report.ok || alarm !== null) {
      const first = alarm?.first ?? report.problem!;
      const latest = report.ok ? { ...report, ok: false, problem: first } : report;
      this.chainHead = null;
      this.chainBreak = { first, latest, walkedAt: whole ? finished : alarm?.walkedAt ?? finished };
      return latest;
    }
    if (report.through !== null) this.chainHead = { through: report.through, head: report.head, entries: report.entries, checkedAt, walkedAt: whole ? finished : cached!.walkedAt };
    return report;
  }

  /** A checkpoint of the chain as it stands: its head, recorded here and handed back to be copied off the machine.
   * Never over a chain that doesn't verify: that would vouch for what broke it. */
  ledgerCheckpoint(by: string, now: Date): { through: number; hash: string } | { problem: string } | null {
    const report = this.ledgerChain({ full: true });
    if (!report.ok) return { problem: report.problem?.what ?? "the chain doesn't verify" };
    return this.transact(() => {
      sealLedger(this.db);
      const last = this.db.prepare(`SELECT id, hash FROM ledger_seal WHERE id ${IN_RANGE} ORDER BY id DESC LIMIT 1`).get();
      if (last === undefined) return null;
      const through = Number(last["id"]), hash = String(last["hash"]);
      this.db.prepare("INSERT INTO ledger_checkpoint (through, hash, at, by) VALUES (?, ?, ?, ?)").run(through, hash, now.toISOString(), by);
      this.recordAction({ at: now.toISOString(), actor: by, repo: null, taskId: null, runId: null, action: "ledger checkpoint", outcome: "recorded", source: "policy", detail: `${through}:${hash}` });
      sealLedger(this.db);
      return { through, hash };
    });
  }

  /** The checkpoints kept so far, newest first. */
  ledgerCheckpoints(limit = 20): { through: number; hash: string; at: string; by: string }[] {
    return this.db.prepare(`SELECT through, hash, at, by FROM ledger_checkpoint WHERE typeof(through) = 'integer' AND through ${IN_RANGE} ORDER BY id DESC LIMIT ?`).all(limit)
      .map(row => ({ through: Number(row["through"]), hash: String(row["hash"]), at: String(row["at"]), by: String(row["by"]) }));
  }

  // ---- Monitoring (v104) ---------------------------------------------------

  /** Sealed ledger entries after `after`, oldest first: what a stream sends next (unsealed ones wait for their seal). */
  sealedAfter(after: number, limit: number): SealedLedgerEntry[] {
    this.sealIfFree();
    return this.sealedRows(`l.id > ? AND s.hash IS NOT NULL ORDER BY l.id LIMIT ?`, [after, limit]);
  }

  /** Every destination's progress, or one's. */
  monitoringStatus(sink?: string): MonitoringStatus[] {
    return (sink === undefined ? this.db.prepare("SELECT * FROM monitoring_status ORDER BY sink").all() : this.db.prepare("SELECT * FROM monitoring_status WHERE sink = ?").all(sink)).map(row => ({
      sink: String(row["sink"]), target: row["target"] == null ? null : String(row["target"]), through: Number(row["through"]), sent: Number(row["sent"]), lastOkAt: row["last_ok_at"] == null ? null : String(row["last_ok_at"]),
      lastError: row["last_error"] == null ? null : String(row["last_error"]), lastErrorAt: row["last_error_at"] == null ? null : String(row["last_error_at"]),
      failures: Number(row["failures"]), nextTryAt: row["next_try_at"] == null ? null : String(row["next_try_at"]),
    }));
  }

  /** Take (or keep) the right to send to `sink` until `until`; false when another process holds it. */
  holdMonitoring(sink: string, holder: string, now: Date, until: Date): boolean {
    return this.transact(() => {
      this.db.prepare("INSERT OR IGNORE INTO monitoring_status (sink) VALUES (?)").run(sink);
      return Number(this.db.prepare("UPDATE monitoring_status SET holder = ?, held_until = ? WHERE sink = ? AND (holder IS NULL OR holder = ? OR held_until IS NULL OR held_until < ?)")
        .run(holder, until.toISOString(), sink, holder, now.toISOString()).changes) === 1;
    });
  }

  /** A delivery landed: move the cursor from `from` to `to`, only for the holder, and only if the destination and the
   * cursor are still what the delivery started from (a destination changed meanwhile starts over; nothing's skipped). */
  monitoringDelivered(sink: string, holder: string, target: string, from: number, to: number, count: number, now: Date): boolean {
    return Number(this.db.prepare(`UPDATE monitoring_status SET through = ?, sent = sent + ?, last_ok_at = ?, failures = 0, next_try_at = NULL
      WHERE sink = ? AND holder = ? AND target = ? AND through = ?`).run(to, count, now.toISOString(), sink, holder, target, from).changes) === 1;
  }

  /** A delivery failed: say why (in words, never a secret) and when to try again (for the destination it was for). */
  monitoringFailed(sink: string, holder: string, target: string, error: string, now: Date, nextTry: Date): void {
    this.db.prepare(`UPDATE monitoring_status SET last_error = ?, last_error_at = ?, failures = failures + 1, next_try_at = ? WHERE sink = ? AND holder = ? AND target = ?`)
      .run(error.replace(/[\u0000-\u001f\u007f]+/g, " ").slice(0, 300), now.toISOString(), nextTry.toISOString(), sink, holder, target);
  }

  /** A destination is new, or now points elsewhere: it starts from `through` (0: the whole history), with no failures. */
  resetMonitoring(sink: string, target: string, through: number): void {
    this.transact(() => {
      this.db.prepare("INSERT OR IGNORE INTO monitoring_status (sink) VALUES (?)").run(sink);
      this.db.prepare("UPDATE monitoring_status SET target = ?, through = ?, sent = 0, last_ok_at = NULL, last_error = NULL, last_error_at = NULL, failures = 0, next_try_at = NULL WHERE sink = ?")
        .run(target, through, sink);
    });
  }

  /** The newest ledger entry id (0 when empty): where a stream that starts "from now" begins. */
  ledgerHeadId(): number {
    return Number(this.db.prepare(`SELECT MAX(id) AS id FROM action_ledger WHERE id ${IN_RANGE}`).get()?.["id"] ?? 0);
  }

  /** Ledger entries in [from, to) within `repos` (as `actionLedger` reads them), with their seals, oldest first,
   * after entry `after` (a page at a time). Seals first. Reads one more than `limit`, so a caller can tell it was cut short. */
  sealedLedgerEntries(query: { from: string; to: string; repos: readonly string[] | null; instance?: boolean; after?: number; limit: number }): SealedLedgerEntry[] {
    if (query.after === undefined) this.sealIfFree();
    const clauses = ["l.at >= ?", "l.at < ?", "l.id > ?"];
    const args: (string | number)[] = [query.from, query.to, query.after ?? 0];
    if (query.repos !== null) {
      if (query.repos.length === 0 && query.instance !== true) return [];
      const inProjects = query.repos.length === 0 ? null : `l.repo IN (${query.repos.map(() => "?").join(",")})`;
      clauses.push(query.instance === true ? `(${inProjects === null ? "" : `${inProjects} OR `}l.repo IS NULL)` : inProjects!);
      args.push(...query.repos);
    }
    return this.sealedRows(`${clauses.join(" AND ")} ORDER BY l.id LIMIT ?`, [...args, query.limit + 1]);
  }

  /** A task family's ledger entries, with their seals, oldest first. Each version's entries count only from the row
   * its registration wrote (which nothing else can write; a version from before that row existed counts from the
   * start); the worker's own entries also by run. Requests made through the console are kept apart and capped at
   * the newest `requests`, so a flood of them can never push the family's own entries out. */
  taskLedgerEntries(family: { taskIds: readonly string[]; runIds: readonly number[] }, limits: { entries: number; requests: number }): { entries: SealedLedgerEntry[]; truncated: boolean } {
    this.sealIfFree();
    if (family.taskIds.length === 0) return { entries: [], truncated: false };
    // Its registration as the task was filed: the one filing wrote again over a ref an earlier lookup made, else the
    // ref's own; a task from before registration rows existed counts from the start.
    const registered = this.db.prepare(`SELECT COALESCE(
      (SELECT MIN(id) FROM action_ledger WHERE task_id = ? AND action = 'task registered' AND source = 'work' AND actor = 'system' AND detail = ?),
      (SELECT MIN(id) FROM action_ledger WHERE task_id = ? AND action = 'task registered' AND source = 'work' AND actor = 'system'), 0) AS id`);
    const versions = family.taskIds.map(id => ({ id, from: Number(registered.get(id, REGISTERED_AT_FILING, id)?.["id"] ?? 0) }));
    const named = `(${versions.map(() => "(l.task_id = ? AND l.id >= ?)").join(" OR ")})`;
    const namedArgs = versions.flatMap(one => [one.id, one.from]);
    const byRun = family.runIds.length === 0 ? "" : ` OR (l.run_id IN (${family.runIds.map(() => "?").join(",")}) AND l.task_id IS NULL)`;
    const own = this.sealedRows(`(${named}${byRun}) AND l.source <> 'request' ORDER BY l.id LIMIT ?`, [...namedArgs, ...family.runIds, limits.entries + 1]);
    const asked = this.sealedRows(`${named} AND l.source = 'request' ORDER BY l.id DESC LIMIT ?`, [...namedArgs, limits.requests + 1]);
    const truncated = own.length > limits.entries || asked.length > limits.requests;
    return { entries: [...own.slice(0, limits.entries), ...asked.slice(0, limits.requests)].sort((a, b) => a.id - b.id), truncated };
  }

  private sealedRows(where: string, args: (string | number)[]): SealedLedgerEntry[] {
    // Entries numbered outside the chain are left to the chain report, which names them.
    return this.db.prepare(`SELECT l.id, l.at, l.actor, l.repo, l.task_id, ${safeWhole("l.run_id", "run_id")}, l.action, l.outcome, l.source, l.detail,
      s.prev AS seal_prev, s.hash AS seal_hash FROM action_ledger l LEFT JOIN ledger_seal s ON s.id = l.id WHERE l.id ${IN_RANGE} AND ${where}`).all(...args).map(row => ({
      id: Number(row["id"]), at: String(row["at"]), actor: String(row["actor"]), repo: row["repo"] === null ? null : String(row["repo"]),
      taskId: row["task_id"] === null ? null : String(row["task_id"]), runId: typeof row["run_id"] === "number" ? row["run_id"] : null,
      action: String(row["action"]), outcome: String(row["outcome"]), source: String(row["source"]) as LedgerEntry["source"],
      detail: row["detail"] == null ? null : String(row["detail"]),
      seal: row["seal_hash"] == null ? null : { prev: String(row["seal_prev"]), hash: String(row["seal_hash"]) },
    }));
  }

  /** Everyone who wrote a version of this task's scope, and every yes given to any version of it (the evidence pack). */
  scopeHistory(taskId: string): { authors: { digest: string; author: string; at: string }[]; votes: { digest: string; approver: string; at: string }[] } {
    return {
      authors: this.db.prepare("SELECT digest, author, at FROM scope_author WHERE task_id = ? ORDER BY at, author").all(taskId)
        .map(row => ({ digest: String(row["digest"]), author: String(row["author"]), at: String(row["at"]) })),
      votes: this.db.prepare("SELECT digest, approver, at FROM scope_approval_vote WHERE task_id = ? ORDER BY at, approver").all(taskId)
        .map(row => ({ digest: String(row["digest"]), approver: String(row["approver"]), at: String(row["at"]) })),
    };
  }

  /** v99: a policy change, as the ledger keeps it: what changed and from what to what. Nothing is kept when nothing changed. */
  private recordPolicy(by: string, repo: string | null, action: string, before: string, after: string, now: Date, outcome = "changed"): void {
    if (before === after) return;
    this.recordAction({ at: now.toISOString(), actor: by, repo, taskId: null, runId: null, action, outcome, source: "policy", detail: `${before} → ${after}` });
  }

  /** The project's automatic review switch: its explicit setting, else on
   * while a hands-off mode is active on it, else off. */
  reviewSwitch(repo: string, now: Date): ReviewSwitch {
    const row = this.db.prepare("SELECT enabled, changed_by, changed_at FROM review_switch WHERE repo = ?").get(repo);
    if (row !== undefined) return { on: Number(row["enabled"]) === 1, source: "project", changedBy: String(row["changed_by"]), changedAt: String(row["changed_at"]) };
    const handsOff = this.activeMode(repo, now)?.name === "hands-off";
    return { on: handsOff, source: handsOff ? "hands-off" : "default", changedBy: null, changedAt: null };
  }

  /** Turn a project's automatic review on or off; the policy log keeps before → after. */
  setReviewSwitch(repo: string, on: boolean, by: string, now: Date): { before: ReviewSwitch; after: ReviewSwitch } {
    return this.transact(() => {
      const before = this.reviewSwitch(repo, now);
      this.db.prepare(`INSERT INTO review_switch (repo, enabled, changed_by, changed_at) VALUES (?, ?, ?, ?)
        ON CONFLICT(repo) DO UPDATE SET enabled = excluded.enabled, changed_by = excluded.changed_by, changed_at = excluded.changed_at`)
        .run(repo, on ? 1 : 0, by, now.toISOString());
      const after = this.reviewSwitch(repo, now);
      this.recordPolicy(by, repo, "automatic review", reviewSwitchWords(before), reviewSwitchWords(after), now);
      return { before, after };
    });
  }

  /** A project deleted (project-delete.ts): who, and what it held → how it went. Returns the entry's id. */
  recordProjectDeleted(by: string, repo: string, held: string, how: string, now: Date): number {
    this.recordPolicy(by, repo, "project deleted", held, how, now, "deleted");
    return this.ledgerHeadId();
  }

  recordAction(entry: Omit<LedgerEntry, "id" | "detail"> & { detail?: string | null }): number {
    const detail = entry.detail == null ? null : entry.detail.replace(/[\u0000-\u001f\u007f]+/g, " ").slice(0, 300);
    const row = this.db.prepare("INSERT INTO action_ledger(at,actor,repo,task_id,run_id,action,outcome,source,detail) VALUES (?,?,?,?,?,?,?,?,?)")
      .run(entry.at, entry.actor, entry.repo, entry.taskId, entry.runId, entry.action, entry.outcome, entry.source, detail);
    return Number(row.lastInsertRowid);
  }

  serviceCursor(key: string): number {
    const row = this.db.prepare("SELECT value FROM service_cursor WHERE key = ?").get(key);
    const value = row === undefined ? 0 : Number(row["value"]);
    if (!Number.isSafeInteger(value) || value < 0) throw new Error("Worker cursor is invalid");
    return value;
  }

  setServiceCursor(key: string, value: number, now: Date): void {
    if (!/^[a-z0-9:-]{1,180}$/.test(key) || !Number.isSafeInteger(value) || value < 0) throw new Error("Worker cursor is invalid");
    this.db.prepare("INSERT INTO service_cursor(key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at")
      .run(key, value, now.toISOString());
  }

  /** `instance`: also the events that belong to no project (sign-ins, accounts, installation policy), for an instance operator. */
  actionLedger(query: { repos: readonly string[] | null; instance?: boolean; actor?: string; outcome?: string; source?: string; taskId?: string; before?: number; limit?: number }): LedgerEntry[] {
    const clauses: string[] = [];
    const args: (string | number)[] = [];
    if (query.repos !== null) {
      if (query.repos.length === 0 && query.instance !== true) return [];
      const inProjects = query.repos.length === 0 ? null : `repo IN (${query.repos.map(() => "?").join(",")})`;
      clauses.push(query.instance === true ? `(${inProjects === null ? "" : `${inProjects} OR `}repo IS NULL)` : inProjects!);
      args.push(...query.repos);
    }
    for (const [field, value] of [["actor", query.actor], ["outcome", query.outcome], ["source", query.source], ["task_id", query.taskId]] as const) {
      if (value !== undefined && value !== "") { clauses.push(`${field} = ?`); args.push(value); }
    }
    if (query.before !== undefined) { clauses.push("id < ?"); args.push(query.before); }
    args.push(Math.max(1, Math.min(101, query.limit ?? 51)));
    return this.db.prepare(`SELECT id, at, actor, repo, task_id, ${safeWhole("run_id")}, action, outcome, source, detail FROM action_ledger WHERE id ${IN_RANGE}${clauses.length ? ` AND ${clauses.join(" AND ")}` : ""} ORDER BY id DESC LIMIT ?`).all(...args).map(row => ({
      id: Number(row["id"]), at: String(row["at"]), actor: String(row["actor"]), repo: row["repo"] === null ? null : String(row["repo"]),
      taskId: row["task_id"] === null ? null : String(row["task_id"]), runId: typeof row["run_id"] === "number" ? row["run_id"] : null,
      action: String(row["action"]), outcome: String(row["outcome"]), source: String(row["source"]) as LedgerEntry["source"],
      detail: row["detail"] == null ? null : String(row["detail"]),
    }));
  }

  // ---- invites + people (v29, U1-U3/D6/D7) --------------------------------

  /** Every account with its standing — the People screen's spine. History
   * is immutable: a revoked person's rows stay attributed forever. */
  accountFacts(): { name: string; role: "approver" | "viewer"; addedAt: string; revokedAt: string | null; revokedBy: string | null; projects: ProjectAccess }[] {
    return this.db
      .prepare("SELECT name, role, added_at, revoked_at, revoked_by, projects_json FROM approver ORDER BY name")
      .all()
      .map(row => ({
        projects: readProjectAccess(row["projects_json"]),
        name: String(row["name"]),
        role: String(row["role"]) as "approver" | "viewer",
        addedAt: String(row["added_at"]),
        revokedAt: row["revoked_at"] === null ? null : String(row["revoked_at"]),
        revokedBy: row["revoked_by"] === null ? null : String(row["revoked_by"]),
      }));
  }

  /** A single-use door into the instance (U2): 128-bit token, sha256
   * stored, role pinned at mint, 72 hours. Only the caller's own
   * authentication gates this — an approver mints; a viewer cannot. */
  mintInvite(role: "approver" | "viewer", mintedBy: string, now: Date, token: () => string = () => randomBytes(16).toString("base64url"), projects: ProjectAccess = null): { token: string; id: number; expiresAt: string } {
    const access = normalizeProjectAccess(projects);
    return this.transact(() => {
      if (!this.isInstanceOperator(mintedBy)) throw new Error("Only an instance operator can invite people.");
      const value = token();
      const expiresAt = new Date(now.getTime() + 72 * 60 * 60_000).toISOString();
      const inserted = this.db
        .prepare("INSERT INTO invite (token_hash, role, minted_by, minted_at, expires_at, projects_json) VALUES (?, ?, ?, ?, ?, ?)")
        .run(createHash("sha256").update(value, "utf8").digest("hex"), role, mintedBy, now.toISOString(), expiresAt, access === null ? null : JSON.stringify(access));
      this.recordAction({ at: now.toISOString(), actor: mintedBy, repo: null, taskId: null, runId: null, action: "invitation created", outcome: role === "viewer" ? "viewer" : "operator", source: "access" });
      return { token: value, id: Number(inserted.lastInsertRowid), expiresAt };
    });
  }

  /** Liveness WITHOUT spending an attempt — what the GET page renders on.
   * Every dead shape (unknown, expired, revoked, consumed) is the same
   * false: the disclosure boundary is one indistinguishable page (D6). */
  inviteIsLive(tokenValue: string, now: Date): boolean {
    const row = this.db
      .prepare(
        "SELECT 1 AS hit FROM invite WHERE token_hash = ? AND revoked_at IS NULL AND consumed_at IS NULL AND expires_at > ? AND attempts < 10",
      )
      .get(createHash("sha256").update(tokenValue, "utf8").digest("hex"), now.toISOString());
    return row !== undefined;
  }

  /**
   * E3: submissions meter ADMITTED attempts, never refunds. One atomic
   * UPDATE spends the slot BEFORE the KDF runs — the eleventh concurrent
   * submission gets the indistinguishable terminal page without ever
   * reaching scrypt, and neither success nor failure gives it back.
   */
  admitInviteAttempt(tokenValue: string, now: Date): { role: "approver" | "viewer"; mintedBy: string } | null {
    const row = this.db
      .prepare(
        `UPDATE invite SET attempts = attempts + 1
          WHERE token_hash = ? AND revoked_at IS NULL AND consumed_at IS NULL AND expires_at > ? AND attempts < 10
          RETURNING role, minted_by`,
      )
      .get(createHash("sha256").update(tokenValue, "utf8").digest("hex"), now.toISOString());
    return row === undefined
      ? null
      : { role: String(row["role"]) as "approver" | "viewer", mintedBy: String(row["minted_by"]) };
  }

  /**
   * The join commit (D6): consume the invite AND create the account in
   * ONE transaction — the CAS on consumed_at is the single winner under
   * concurrent submissions, the name's uniqueness is proved in the same
   * breath, and the role is the PINNED one from mint, never a request
   * parameter. The caller runs scrypt before calling; the session cookie
   * mints only after this commits.
   */
  consumeInviteAndCreateAccount(
    args: { tokenValue: string; name: string; credentialHash: string },
    now: Date,
  ): { ok: true; role: "approver" | "viewer" } | { ok: false; reason: "gone" | "name-taken" } {
    return this.transact(() => {
      // Liveness FIRST (Codex people round 1, finding 3): the loser of a
      // concurrent join must read as 'gone' — the indistinguishable dead
      // shape — never as a name collision that discloses the winner.
      const hash = createHash("sha256").update(args.tokenValue, "utf8").digest("hex");
      const live = this.db
        .prepare("SELECT 1 AS hit FROM invite WHERE token_hash = ? AND revoked_at IS NULL AND consumed_at IS NULL AND expires_at > ?")
        .get(hash, now.toISOString());
      if (live === undefined) return { ok: false as const, reason: "gone" as const };
      const taken = this.db.prepare("SELECT 1 AS hit FROM approver WHERE name = ?").get(args.name);
      if (taken !== undefined) return { ok: false as const, reason: "name-taken" as const };
      const consumed = this.db
        .prepare(
          `UPDATE invite SET consumed_by = ?, consumed_at = ?
            WHERE token_hash = ? AND revoked_at IS NULL AND consumed_at IS NULL AND expires_at > ?
            RETURNING role, projects_json`,
        )
        .get(args.name, now.toISOString(), hash, now.toISOString());
      if (consumed === undefined) return { ok: false as const, reason: "gone" as const };
      const role = String(consumed["role"]) as "approver" | "viewer";
      this.db
        .prepare("INSERT INTO approver (name, credential_hash, added_at, role, generation, projects_json) VALUES (?, ?, ?, ?, 1, ?)")
        .run(args.name, args.credentialHash, now.toISOString(), role, consumed["projects_json"] ?? null);
      for (const repo of readProjectAccess(consumed["projects_json"]) ?? [null]) {
        this.recordAction({ at: now.toISOString(), actor: args.name, repo, taskId: null, runId: null, action: "joined", outcome: role === "viewer" ? "viewer" : "operator", source: "access" });
      }
      return { ok: true as const, role };
    });
  }

  // ---- API tokens and browser sessions (v101) ------------------------------

  createApiToken(token: { id: string; account: string; name: string; secretHash: string; access: "read" | "act"; expiresAt: string; by: string }, now: Date): void {
    this.transact(() => {
      this.db.prepare("INSERT INTO api_token (id, account, name, secret_hash, access, created_at, created_by, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
        .run(token.id, token.account, token.name, token.secretHash, token.access, now.toISOString(), token.by, token.expiresAt);
      this.recordAction({ at: now.toISOString(), actor: token.by, repo: null, taskId: null, runId: null, action: `API token created: ${token.name}`, outcome: token.access, source: "access",
        detail: `for ${token.account}, until ${token.expiresAt.slice(0, 10)}` });
    });
  }

  /** A token by id with its kept hash (for the check), or null. */
  apiTokenSecret(id: string): { row: ApiTokenRow; secretHash: string } | null {
    const row = this.db.prepare("SELECT * FROM api_token WHERE id = ?").get(id);
    return row === undefined ? null : { row: readApiToken(row), secretHash: String(row["secret_hash"]) };
  }

  /** Tokens, newest first: one person's, or everyone's (null). */
  apiTokens(account: string | null): ApiTokenRow[] {
    return (account === null ? this.db.prepare("SELECT * FROM api_token ORDER BY created_at DESC").all() : this.db.prepare("SELECT * FROM api_token WHERE account = ? ORDER BY created_at DESC").all(account)).map(readApiToken);
  }

  /** Kept at most once a minute: a busy script doesn't write on every request. */
  touchApiToken(id: string, now: Date): void {
    this.db.prepare("UPDATE api_token SET last_used_at = ? WHERE id = ? AND (last_used_at IS NULL OR last_used_at < ?)").run(now.toISOString(), id, new Date(now.getTime() - 60_000).toISOString());
  }

  revokeApiToken(id: string, by: string, now: Date, why = "revoked"): boolean {
    return this.transact(() => {
      const row = this.db.prepare("SELECT name, account FROM api_token WHERE id = ? AND revoked_at IS NULL").get(id);
      if (row === undefined) return false;
      this.db.prepare("UPDATE api_token SET revoked_at = ?, revoked_by = ? WHERE id = ?").run(now.toISOString(), by, id);
      this.recordAction({ at: now.toISOString(), actor: by, repo: null, taskId: null, runId: null, action: `API token revoked: ${String(row["name"])}`, outcome: "revoked", source: "access", detail: `${String(row["account"])}'s · ${why}` });
      return true;
    });
  }

  saveWebSession(session: WebSessionRow): void {
    this.db.prepare(`INSERT INTO web_session (id_hash, account, csrf, role, generation, created_at, last_seen, project, project_revision, sso_at, agent, address) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id_hash) DO UPDATE SET last_seen = excluded.last_seen, project = excluded.project, project_revision = excluded.project_revision, sso_at = excluded.sso_at`)
      .run(session.idHash, session.account, session.csrf, session.role, session.generation, session.createdAt, session.lastSeen, session.project, session.projectRevision, session.ssoAt, session.agent, session.address);
  }

  webSession(idHash: string): WebSessionRow | null {
    const row = this.db.prepare("SELECT * FROM web_session WHERE id_hash = ?").get(idHash);
    return row === undefined ? null : readWebSession(row);
  }

  webSessions(account: string | null): WebSessionRow[] {
    return (account === null ? this.db.prepare("SELECT * FROM web_session ORDER BY last_seen DESC").all() : this.db.prepare("SELECT * FROM web_session WHERE account = ? ORDER BY last_seen DESC").all(account)).map(readWebSession);
  }

  dropWebSession(idHash: string): void {
    this.db.prepare("DELETE FROM web_session WHERE id_hash = ?").run(idHash);
  }

  /** Sessions past their idle or absolute limit, or opened under an old credential generation, are gone. */
  sweepWebSessions(now: number, idleMs: number, absoluteMs: number): number {
    return Number(this.db.prepare(`DELETE FROM web_session WHERE last_seen < ? OR created_at < ? OR generation <> COALESCE((SELECT generation FROM approver WHERE name = web_session.account AND revoked_at IS NULL), -1)`)
      .run(now - idleMs, now - absoluteMs).changes);
  }

  /** v100: the account an identity-provider identity signs in as, or null. */
  ssoAccount(issuer: string, subject: string): string | null {
    const row = this.db.prepare("SELECT account FROM sso_identity WHERE issuer = ? AND subject = ?").get(issuer, subject);
    return row === undefined ? null : String(row["account"]);
  }

  /** v100: the provider identities linked to an account. */
  ssoIdentitiesOf(account: string): { issuer: string; subject: string; email: string | null; lastSeenAt: string }[] {
    return this.db.prepare("SELECT issuer, subject, email, last_seen_at FROM sso_identity WHERE account = ? ORDER BY created_at").all(account)
      .map(row => ({ issuer: String(row["issuer"]), subject: String(row["subject"]), email: row["email"] == null ? null : String(row["email"]), lastSeenAt: String(row["last_seen_at"]) }));
  }

  /**
   * v100: someone the identity provider vouched for. Linked before, they sign
   * in as that account, and their groups set its role and projects again (a
   * change ends its other sessions, as any access change does). New, they get
   * an account named for them (`name`) that has no password. No matching group
   * (`access` null), a revoked account, or a change that would leave the
   * installation without an instance operator, refuses.
   */
  signInWithSso(identity: { issuer: string; subject: string; email: string | null; label: string }, access: { role: "approver" | "viewer"; projects: ProjectAccess } | null, name: () => string, now: Date):
    { ok: true; account: string; role: "approver" | "viewer"; created: boolean } | { ok: false; reason: "no-group" | "revoked" | "last-instance-operator" } {
    return this.transact(() => {
      const stamp = now.toISOString();
      const linked = this.ssoAccount(identity.issuer, identity.subject);
      if (access === null) return { ok: false as const, reason: "no-group" as const };
      const projects = normalizeProjectAccess(access.projects);
      const words = (role: string, list: ProjectAccess) => `${role === "viewer" ? "viewer" : "operator"} · ${list === null ? "all projects" : list.length === 0 ? "no projects" : list.map(one => one.split(/[\\/]/).filter(Boolean).at(-1) ?? one).join(", ")}`;
      if (linked !== null) {
        const account = this.accountOf(linked);
        if (account === null || account.revokedAt !== null) return { ok: false as const, reason: "revoked" as const };
        this.db.prepare("UPDATE sso_identity SET last_seen_at = ?, email = ? WHERE issuer = ? AND subject = ?").run(stamp, identity.email, identity.issuer, identity.subject);
        const same = account.role === access.role && JSON.stringify(account.projects) === JSON.stringify(projects);
        if (!same) {
          const stillOperator = access.role === "approver" && projects === null;
          if (this.isInstanceOperator(linked) && !stillOperator && !this.accountFacts().some(one => one.name !== linked && this.isInstanceOperator(one.name))) {
            return { ok: false as const, reason: "last-instance-operator" as const };
          }
          this.db.prepare("UPDATE approver SET role = ?, projects_json = ?, generation = generation + 1 WHERE name = ?").run(access.role, projects === null ? null : JSON.stringify(projects), linked);
          this.revokeDerivedAuthority(linked, `${identity.label} groups`, now);
          this.recordAction({ at: stamp, actor: linked, repo: null, taskId: null, runId: null, action: "access changed by groups", outcome: access.role === "viewer" ? "viewer" : "operator", source: "access",
            detail: `${words(account.role, account.projects)} → ${words(access.role, projects)}` });
        }
        return { ok: true as const, account: linked, role: access.role, created: false };
      }
      const chosen = name();
      this.db.prepare("INSERT INTO approver (name, credential_hash, added_at, role, generation, projects_json) VALUES (?, ?, ?, ?, 1, ?)")
        .run(chosen, `sso-only$${randomBytes(16).toString("hex")}`, stamp, access.role, projects === null ? null : JSON.stringify(projects));
      this.db.prepare("INSERT INTO sso_identity (issuer, subject, account, email, created_at, last_seen_at) VALUES (?, ?, ?, ?, ?, ?)").run(identity.issuer, identity.subject, chosen, identity.email, stamp, stamp);
      this.recordAction({ at: stamp, actor: chosen, repo: null, taskId: null, runId: null, action: "joined", outcome: access.role === "viewer" ? "viewer" : "operator", source: "access", detail: `via ${identity.label} · ${words(access.role, projects)}` });
      return { ok: true as const, account: chosen, role: access.role, created: true };
    });
  }

  /** v100: sign in with the identity provider as an existing account from now on (the person proved both). */
  linkSsoIdentity(account: string, identity: { issuer: string; subject: string; email: string | null; label: string }, now: Date): { ok: true } | { ok: false; reason: "linked-elsewhere" } {
    return this.transact(() => {
      const linked = this.ssoAccount(identity.issuer, identity.subject);
      if (linked !== null && linked !== account) return { ok: false as const, reason: "linked-elsewhere" as const };
      if (linked === null) {
        this.db.prepare("INSERT INTO sso_identity (issuer, subject, account, email, created_at, last_seen_at) VALUES (?, ?, ?, ?, ?, ?)").run(identity.issuer, identity.subject, account, identity.email, now.toISOString(), now.toISOString());
        this.recordAction({ at: now.toISOString(), actor: account, repo: null, taskId: null, runId: null, action: `linked to ${identity.label}`, outcome: "linked", source: "access", detail: identity.email });
      }
      return { ok: true as const };
    });
  }

  /** The open invites — the People screen's and the CLI's list. Hashes
   * never leave the store; an invite is named by its row id. */
  openInvites(now: Date): { id: number; role: "approver" | "viewer"; mintedBy: string; mintedAt: string; expiresAt: string; attempts: number; projects: ProjectAccess }[] {
    return this.db
      .prepare(
        "SELECT id, role, minted_by, minted_at, expires_at, attempts, projects_json FROM invite WHERE revoked_at IS NULL AND consumed_at IS NULL AND expires_at > ? ORDER BY id",
      )
      .all(now.toISOString())
      .map(row => ({
        id: Number(row["id"]),
        role: String(row["role"]) as "approver" | "viewer",
        mintedBy: String(row["minted_by"]),
        mintedAt: String(row["minted_at"]),
        expiresAt: String(row["expires_at"]),
        attempts: Number(row["attempts"]),
        projects: readProjectAccess(row["projects_json"]),
      }));
  }

  revokeInvite(id: number, now: Date): boolean {
    return (
      Number(
        this.db
          .prepare("UPDATE invite SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL AND consumed_at IS NULL")
          .run(now.toISOString(), id).changes,
      ) > 0
    );
  }

  /**
   * The revocation that actually severs (D7), one transaction: the stamp
   * plus a generation bump (live console sessions die at their next
   * lookup; bearer credentials die at authenticateAccount), their open
   * attended authorizations close, their unconsumed invites die, every
   * mode THEY signed is revoked with the typed 'signer-revoked' event —
   * demoting its derived merge authority through the one reconciliation
   * road — and the derived-authority sweep clears Telegram and push.
   * History is untouched: revocation ends capability, never rewrites the
   * ledger. Removing the LAST active approver is refused — an instance
   * nobody can approve into is a brick, not a posture.
   *
   * THE CLAIM, NARROWED (Codex people round 1, finding 2): what dies here
   * is authority that DERIVES from the person's standing — sessions,
   * invites, modes and everything mode-derived (their sealed filings
   * demote through the reconciliation road), Telegram, push. Standing
   * acts they completed WITH full ceremony — publication/backend/intake
   * grants, worktree setups, approved routines, approved scopes sealed by
   * password — deliberately survive: those are the instance's promises,
   * approved as themselves, and undoing history is not what revocation
   * means. An operator who distrusts those acts revokes them by their own
   * roads.
   */
  revokeAccount(
    name: string,
    by: string,
    now: Date,
  ):
    | { ok: true; modesRevoked: number; authorizationsClosed: number; invitesRevoked: number }
    | { ok: false; reason: "unknown" | "already-revoked" | "last-approver" } {
    return this.transact(() => {
      const account = this.db.prepare("SELECT role, revoked_at, projects_json FROM approver WHERE name = ?").get(name);
      if (account === undefined) return { ok: false as const, reason: "unknown" as const };
      if (account["revoked_at"] !== null) return { ok: false as const, reason: "already-revoked" as const };
      if (String(account["role"]) === "approver" && account["projects_json"] === null) {
        const others = this.db
          .prepare("SELECT COUNT(*) AS n FROM approver WHERE role = 'approver' AND revoked_at IS NULL AND projects_json IS NULL AND name <> ?")
          .get(name);
        if (Number(others?.["n"] ?? 0) === 0) return { ok: false as const, reason: "last-approver" as const };
      }
      const stamp = now.toISOString();
      this.db
        .prepare("UPDATE approver SET revoked_at = ?, revoked_by = ?, generation = generation + 1 WHERE name = ?")
        .run(stamp, by, name);
      const closed = this.db
        .prepare("UPDATE attended_authorization SET closed_at = ?, end_reason = 'approver-revoked' WHERE approver = ? AND closed_at IS NULL")
        .run(stamp, name);
      const invites = this.db
        .prepare("UPDATE invite SET revoked_at = ? WHERE minted_by = ? AND revoked_at IS NULL AND consumed_at IS NULL")
        .run(stamp, name);
      // Modes they signed die with them — and every intent that derived
      // merge authority from those signatures demotes through the ONE
      // reconciliation road, exactly as an explicit revocation would.
      const modes = this.db
        .prepare("SELECT id, repo FROM operating_mode WHERE signed_by = ? AND revoked_at IS NULL")
        .all(name);
      for (const mode of modes) {
        this.db
          .prepare("UPDATE operating_mode SET revoked_at = ?, revoked_by = ?, revoke_reason = 'signer-revoked' WHERE id = ?")
          .run(stamp, by, Number(mode["id"]));
        this.db
          .prepare("INSERT INTO operating_mode_event (mode, kind, actor, at) VALUES (?, 'signer-revoked', ?, ?)")
          .run(Number(mode["id"]), by, stamp);
        this.reconcileIntentsForMode(String(mode["repo"]), null, now);
      }
      this.revokeDerivedAuthority(name, by, now);
      this.recordAction({ at: stamp, actor: by, repo: null, taskId: null, runId: null, action: `account removed: ${name}`, outcome: "revoked", source: "access" });
      return {
        ok: true as const,
        modesRevoked: modes.length,
        authorizationsClosed: Number(closed.changes),
        invitesRevoked: Number(invites.changes),
      };
    });
  }

  /** One person's open attended sessions, for their People card. */
  openAttendedOf(name: string): { taskId: string; createdAt: string; lastBeatAt: string | null }[] {
    return this.db
      .prepare(
        `SELECT task_ref.external_id AS taskId, aa.created_at, aa.last_beat_at
           FROM attended_authorization aa JOIN task_ref ON task_ref.id = aa.task_ref
          WHERE aa.approver = ? AND aa.closed_at IS NULL ORDER BY aa.created_at DESC`,
      )
      .all(name)
      .map(row => ({
        taskId: String(row["taskId"]),
        createdAt: String(row["created_at"]),
        lastBeatAt: row["last_beat_at"] === null ? null : String(row["last_beat_at"]),
      }));
  }

  /**
   * One person's recent consequential acts (U3), from the rows that were
   * ALREADY author-stamped — no new event kinds, just the ledger asked a
   * new question. Bounded and newest-first.
   */
  recentActsOf(name: string, limit = 8): { kind: string; subject: string; at: string }[] {
    return this.db
      .prepare(
        `SELECT kind, subject, at FROM (
           SELECT 'approved' AS kind, task_id AS subject, approved_at AS at FROM task_scope WHERE approved_by = ? AND approved_at IS NOT NULL
           UNION ALL
           SELECT 'decided', COALESCE((SELECT external_id FROM task_ref JOIN run ON run.task_ref = task_ref.id WHERE run.id = decision.run), ''), answered_at FROM decision WHERE answered_by = ? AND answered_at IS NOT NULL
           UNION ALL
           SELECT 'steered', (SELECT external_id FROM task_ref WHERE task_ref.id = task_steer.task_ref), created_at FROM task_steer WHERE author = ?
           UNION ALL
           SELECT 'mode ' || kind, (SELECT repo FROM operating_mode WHERE operating_mode.id = operating_mode_event.mode), at FROM operating_mode_event WHERE actor = ?
           UNION ALL
           SELECT 'merge unblocked', COALESCE(task_id, ''), lifted_at FROM merge_blocker WHERE lifted_by = ? AND lifted_at IS NOT NULL
         ) WHERE at IS NOT NULL ORDER BY at DESC LIMIT ?`,
      )
      .all(name, name, name, name, name, limit)
      .map(row => ({ kind: String(row["kind"]), subject: String(row["subject"] ?? ""), at: String(row["at"]) }));
  }

  // ---- runners ------------------------------------------------------------

  /**
   * Replace a runner and return the incarnation timestamp actually stored.
   *
   * `registered_at` is the reviewer custody generation. Its assignment and
   * the credential replacement therefore happen under the SAME IMMEDIATE
   * transaction: concurrent registrations cannot both derive a generation
   * from the same predecessor. A replacement also advances beyond every
   * admitted root reviewer it invalidates. That second bound matters when a
   * coarse/injected clock gives the replacement and reviewer the exact same
   * millisecond — equality is valid for the original admission, but must
   * never make its replacement look original too.
   */
  saveRunner(runner: Runner, credentialHash: string, mutation: Mutation = {}): Runner {
    return this.once(mutation, "saveRunner", () =>
      this.transact(() => {
        const current = this.db
          .prepare("SELECT registered_at FROM runner WHERE name = ?")
          .get(runner.name) as { registered_at: string } | undefined;
        const latestReviewer = this.db
          .prepare(
            `SELECT MAX(root.started_at) AS started_at
               FROM run AS root
               JOIN run AS source ON source.id = root.parent_run
              WHERE root.runner = ? AND root.role = 'reviewer' AND source.role != 'reviewer'`,
          )
          .get(runner.name) as { started_at: string | null } | undefined;

        const proposedMs = Date.parse(runner.registeredAt);
        if (!Number.isFinite(proposedMs)) throw new Error(`runner ${runner.name}'s registration timestamp is invalid`);
        const lowerBounds = [proposedMs];
        if (current !== undefined) {
          const currentMs = Date.parse(current.registered_at);
          if (!Number.isFinite(currentMs)) throw new Error(`runner ${runner.name}'s stored registration timestamp is invalid`);
          lowerBounds.push(currentMs + 1);
        }
        // Historical review admission remains a fence even if a damaged or
        // manually repaired database lost the runner row before re-register.
        const reviewerMs = latestReviewer?.started_at == null ? Number.NaN : Date.parse(latestReviewer.started_at);
        if (Number.isFinite(reviewerMs)) lowerBounds.push(reviewerMs + 1);
        const registeredAt = new Date(Math.max(...lowerBounds)).toISOString();
        const saved: Runner = {
          ...runner,
          registeredAt,
          // Registration supplies equal timestamps. Preserve an explicitly
          // different heartbeat for fixture callers, but move the ordinary
          // registration heartbeat with its atomically assigned generation.
          heartbeatAt: runner.heartbeatAt === runner.registeredAt ? registeredAt : runner.heartbeatAt,
          retiredAt: null,
        };

        this.db
          .prepare(
            `INSERT INTO runner
               (name, host, credential_hash, capacity, repos, agents, registered_at, heartbeat_at, retired_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL)
             ON CONFLICT (name) DO UPDATE SET
               host = excluded.host, credential_hash = excluded.credential_hash,
               capacity = excluded.capacity, repos = excluded.repos, agents = excluded.agents,
               registered_at = excluded.registered_at, heartbeat_at = excluded.heartbeat_at,
               retired_at = NULL`,
          )
          .run(
            saved.name,
            saved.host,
            credentialHash,
            saved.capacity,
            JSON.stringify(saved.repos),
            JSON.stringify(saved.agents),
            saved.registeredAt,
            saved.heartbeatAt,
          );
        return saved;
      }),
    );
  }

  /**
   * The one-time binding ceremony's write (MCP gateway spec v6): REPLACES
   * the runner's repo list — stated authority, never accumulation — and
   * touches nothing else: credential, capacity, heartbeat, and retirement
   * all stand. The caller has already authenticated the operator; a
   * retired runner refuses (retire is final; re-register instead).
   */
  bindRunnerRepos(
    name: string,
    repos: readonly string[],
    now: Date,
  ): { ok: true; repos: string[] } | { ok: false; reason: "unknown" | "retired" } {
    return this.transact(() => {
      const found = this.getRunner(name);
      if (found === null) return { ok: false as const, reason: "unknown" as const };
      if (found.runner.retiredAt !== null) return { ok: false as const, reason: "retired" as const };
      const bound = [...repos];
      this.db
        .prepare("UPDATE runner SET repos = ? WHERE name = ?")
        .run(JSON.stringify(bound), name);
      void now;
      return { ok: true as const, repos: bound };
    });
  }

  /**
   * How many tasks a worker runs at once, set by an operator and kept in
   * the ledger as before → after. Only the number changes: work already
   * running keeps its claim, and the new number applies at the next claim.
   */
  setRunnerCapacity(
    name: string,
    capacity: number,
    by: string,
    now: Date,
  ): { ok: true; before: number; after: number } | { ok: false; reason: "unknown" | "retired" } {
    return this.transact(() => {
      const found = this.getRunner(name);
      if (found === null) return { ok: false as const, reason: "unknown" as const };
      if (found.runner.retiredAt !== null) return { ok: false as const, reason: "retired" as const };
      const before = found.runner.capacity;
      this.db.prepare("UPDATE runner SET capacity = ? WHERE name = ?").run(capacity, name);
      this.recordPolicy(by, null, `worker capacity: ${name}`, String(before), String(capacity), now);
      return { ok: true as const, before, after: capacity };
    });
  }

  /** The hash comes back with it; the token it was made from does not exist here. */
  getRunner(name: string): { runner: Runner; credentialHash: string } | null {
    const row = this.db.prepare("SELECT * FROM runner WHERE name = ?").get(name);
    if (row === undefined) return null;
    return { runner: readRunner(row), credentialHash: String(row["credential_hash"]) };
  }

  listRunners(): Runner[] {
    return this.db.prepare("SELECT * FROM runner ORDER BY name").all().map(readRunner);
  }

  touchRunner(name: string, now: Date): void {
    this.db
      .prepare("UPDATE runner SET heartbeat_at = ? WHERE name = ? AND retired_at IS NULL")
      .run(now.toISOString(), name);
  }

  retireRunner(name: string, now: Date, mutation: Mutation = {}): boolean {
    return this.once(
      mutation,
      "retireRunner",
      () => {
        const { changes } = this.db
          .prepare("UPDATE runner SET retired_at = ? WHERE name = ? AND retired_at IS NULL")
          .run(now.toISOString(), name);
        return Number(changes) > 0;
      },
      retired => retired,
    );
  }

  /**
   * Release every live claim a runner holds, and say which.
   *
   * Not a fenced release: this is the control plane taking a lease back from a
   * machine that is gone, not that machine handing it in. The generation is
   * untouched, so if the runner ever wakes up its completion is still fenced
   * out by the next acquire — which is exactly the behaviour that made the
   * fence worth having.
   */
  releaseClaimsOf(runner: string, now: Date, requeued?: string[]): string[] {
    const held = this.db
      .prepare("SELECT lease_id, task_ref FROM claim WHERE runner = ? AND released_at IS NULL")
      .all(runner);
    if (held.length === 0) return [];

    this.db
      .prepare(
        "UPDATE claim SET released_at = ?, released_by = 'recovered' WHERE runner = ? AND released_at IS NULL",
      )
      .run(now.toISOString(), runner);

    // Releasing the lease is only half of it. Claiming a task moves it to
    // `running`, and the ready query asks for `queued` — so a lease taken back
    // from a dead machine without this leaves the task stranded in `running`
    // forever: not claimed by anybody, and never offered to anybody either.
    // The most expensive kind of bug, because nothing anywhere reports it.
    //
    // Matched on backend as well as id. Claims are backend-agnostic and ids
    // are only unique within a backend, so requeuing by id alone would let a
    // dead runner's GitHub issue #17 reset a built-in task that happens to be
    // called `17`. Somebody else's work, moved by a coincidence of naming.
    //
    // And only when nobody newer owns the task (P0.1a): a lease that ran out
    // unreleased is still a row under this runner's name after a successor
    // acquired the next generation. Requeueing on its account would yank the
    // task out from under the live holder — the one liveness fact the
    // recovery walks guard on, guarded here too.
    for (const row of held) {
      const taskRef = Number(row["task_ref"]);
      if (this.currentLiveLease(taskRef, now) !== null) continue;
      const ref = this.db
        .prepare("SELECT backend, external_id FROM task_ref WHERE id = ?")
        .get(taskRef);
      if (ref === undefined || String(ref["backend"]) !== BUILT_IN) continue;

      const { changes } = this.db
        .prepare("UPDATE task SET state = 'queued', updated_at = ? WHERE id = ? AND state = 'running'")
        .run(now.toISOString(), String(ref["external_id"]));
      if (Number(changes) > 0) requeued?.push(String(ref["external_id"]));
    }

    return held.map(row => String(row["lease_id"]));
  }

  // ---- worktrees ----------------------------------------------------------

  saveWorktree(worktree: WorktreeRow, mutation: Mutation = {}): void {
    this.once(mutation, "saveWorktree", () => {
      this.db
        .prepare(
          `INSERT INTO worktree (path, repo, branch, runner, task_ref, created_at, leased_at, released_at, verified, lease_epoch)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
           ON CONFLICT (path) DO UPDATE SET
             repo = excluded.repo, branch = excluded.branch, runner = excluded.runner,
             task_ref = excluded.task_ref, leased_at = excluded.leased_at,
             released_at = excluded.released_at, verified = excluded.verified,
             lease_epoch = excluded.lease_epoch`,
        )
        .run(
          worktree.path,
          worktree.repo,
          worktree.branch,
          worktree.runner,
          worktree.taskRef,
          worktree.createdAt,
          worktree.leasedAt,
          worktree.releasedAt,
          worktree.verified ? 1 : 0,
          worktree.leaseEpoch ?? null,
        );
      return null;
    });
  }

  /** The last run that lived in this checkout — whose evidence a reclaimed leftover joins. */
  latestRunInWorktree(path: string): number | null {
    const row = this.db.prepare("SELECT id FROM run WHERE worktree = ? ORDER BY id DESC LIMIT 1").get(path) as { id: number } | undefined;
    return row === undefined ? null : Number(row.id);
  }

  /** The newest attempt whose draft custody may still matter after a crash.
   * Open rows cover a runner that vanished before takeover settlement;
   * interrupted rows and their explicit recovery children preserve lineage. */
  latestRecoverableRunInWorktree(path: string): number | null {
    const row = this.db
      .prepare(
        `SELECT id FROM run
          WHERE worktree = ?
            AND (outcome IS NULL OR reason IN ('interrupted', 'no-handoff') OR parent_run IS NOT NULL)
          ORDER BY id DESC LIMIT 1`,
      )
      .get(path) as { id: number } | undefined;
    return row === undefined ? null : Number(row.id);
  }

  getWorktree(path: string): WorktreeRow | null {
    const row = this.db.prepare("SELECT * FROM worktree WHERE path = ?").get(path);
    return row === undefined ? null : readWorktree(row);
  }

  /** Drop a row whose directory is gone; a lease over nothing only refuses work. */
  forgetWorktree(path: string): void {
    this.db.prepare("DELETE FROM worktree WHERE path = ?").run(path);
  }

  // ---- worktree setup (M5.7) ---------------------------------------------

  /**
   * Approve one repo's setup, revoking any predecessor in the same
   * transaction — exactly one live setup per repo, enforced by the partial
   * unique index rather than by anything a caller remembers.
   */
  setWorktreeSetup(
    args: { repo: string; command: string; timeoutMs: number; approvedBy: string },
    now: Date,
  ): WorktreeSetup {
    const digest = createHash("sha256")
      .update(`${args.repo}\u0000${args.command}\u0000${args.timeoutMs}`, "utf8")
      .digest("hex")
      .slice(0, 16);
    return this.transact(() => {
      this.db
        .prepare("UPDATE worktree_setup SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
        .run(now.toISOString(), args.approvedBy, args.repo);
      const inserted = this.db
        .prepare(
          `INSERT INTO worktree_setup (repo, command, timeout_ms, digest, approved_by, approved_at)
           VALUES (?, ?, ?, ?, ?, ?)`,
        )
        .run(args.repo, args.command, args.timeoutMs, digest, args.approvedBy, now.toISOString());
      const row = this.db.prepare("SELECT * FROM worktree_setup WHERE id = ?").get(Number(inserted.lastInsertRowid));
      return readWorktreeSetup(row as Record<string, unknown>);
    });
  }

  liveWorktreeSetup(repo: string): WorktreeSetup | null {
    const row = this.db
      .prepare("SELECT * FROM worktree_setup WHERE repo = ? AND revoked_at IS NULL")
      .get(repo);
    return row === undefined ? null : readWorktreeSetup(row);
  }

  clearWorktreeSetup(repo: string, by: string, now: Date): boolean {
    const done = this.db
      .prepare("UPDATE worktree_setup SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
      .run(now.toISOString(), by, repo);
    return Number(done.changes) > 0;
  }

  /** The cache stamp: this checkout completed this setup. Success-only by contract. */
  stampWorktreeSetup(path: string, digest: string): void {
    this.db.prepare("UPDATE worktree SET setup_digest = ? WHERE path = ?").run(digest, path);
  }

  /** The checkout no longer holds what its setup made (its dependencies were dropped): the next lease runs setup again. */
  forgetWorktreeSetup(path: string): void {
    this.db.prepare("UPDATE worktree SET setup_digest = NULL WHERE path = ?").run(path);
  }

  // ---- verify command (Priority 2) ---------------------------------------

  /**
   * Approve one repo's verification command, revoking any predecessor in
   * the same transaction — exactly one live command per repo, enforced by
   * the partial unique index. Cloned from setWorktreeSetup: same digest
   * shape, same revoke-then-insert ceremony.
   */
  setVerifyCommand(
    args: { repo: string; command: string; timeoutMs: number; approvedBy: string; recoverySetupDigest?: string | null },
    now: Date,
  ): VerifyCommand {
    const legacyDigest = createHash("sha256")
      .update(`${args.repo}\0${args.command}\0${args.timeoutMs}`, "utf8")
      .digest("hex")
      .slice(0, 16);
    const recoverySetupDigest = args.recoverySetupDigest ?? null;
    const digest =
      recoverySetupDigest === null
        ? legacyDigest
        : createHash("sha256")
            .update(`${legacyDigest}:recovery-setup:${recoverySetupDigest}`, "utf8")
            .digest("hex")
            .slice(0, 16);
    return this.transact(() => {
      this.db
        .prepare("UPDATE verify_command SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
        .run(now.toISOString(), args.approvedBy, args.repo);
      const inserted = this.db
        .prepare(
          `INSERT INTO verify_command (repo, command, timeout_ms, digest, recovery_setup_digest, approved_by, approved_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(args.repo, args.command, args.timeoutMs, digest, recoverySetupDigest, args.approvedBy, now.toISOString());
      const row = this.db.prepare("SELECT * FROM verify_command WHERE id = ?").get(Number(inserted.lastInsertRowid));
      return readVerifyCommand(row as Record<string, unknown>);
    });
  }

  liveVerifyCommand(repo: string): VerifyCommand | null {
    const row = this.db.prepare("SELECT * FROM verify_command WHERE repo = ? AND revoked_at IS NULL").get(repo);
    return row === undefined ? null : readVerifyCommand(row);
  }

  clearVerifyCommand(repo: string, by: string, now: Date): boolean {
    const done = this.db
      .prepare("UPDATE verify_command SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
      .run(now.toISOString(), by, repo);
    return Number(done.changes) > 0;
  }

  // ---- proof verdict and acceptance (Priority 2) -------------------------

  /** The machine's one verdict for a run, computed once at completion by
   * adjudicate() — overwritten only by a re-computation of the SAME run's
   * proof, never by a later render. `machineVerdict` (v40) is the verdict
   * BEFORE an independent reviewer's judgements are folded in; omitted (or
   * explicitly `null`) leaves any already-stored value untouched — the
   * builder's own save never touches it, only `ingestCriterionReviews`'s
   * one fold does. */
  saveProofVerdict(
    runId: number,
    verdict: ProofVerdictRow["verdict"],
    reasons: readonly string[],
    now: Date,
    matrix: readonly CriterionMatrixRow[] = [],
    machineVerdict?: ProofVerdictRow["verdict"] | null,
  ): void {
    this.db
      .prepare(
        `INSERT INTO proof_verdict (run, verdict, reasons_json, decided_at, matrix_json, machine_verdict) VALUES (?, ?, ?, ?, ?, ?)
         ON CONFLICT (run) DO UPDATE SET verdict = excluded.verdict, reasons_json = excluded.reasons_json,
           decided_at = excluded.decided_at, matrix_json = excluded.matrix_json,
           machine_verdict = COALESCE(excluded.machine_verdict, proof_verdict.machine_verdict)`,
      )
      .run(runId, verdict, JSON.stringify(reasons), now.toISOString(), matrix.length === 0 ? null : JSON.stringify(matrix), machineVerdict ?? null);
  }

  proofVerdictFor(runId: number): ProofVerdictRow | null {
    const row = this.db.prepare("SELECT * FROM proof_verdict WHERE run = ?").get(runId);
    return row === undefined ? null : readProofVerdict(row as Record<string, unknown>);
  }

  /** Every verdict for a batch of runs, keyed by run id — the board and
   * `/done` read many rows at once and must not pay an N+1 for this. */
  proofVerdictsFor(runIds: readonly number[]): Map<number, ProofVerdictRow> {
    const map = new Map<number, ProofVerdictRow>();
    if (runIds.length === 0) return map;
    const placeholders = runIds.map(() => "?").join(",");
    const rows = this.db.prepare(`SELECT * FROM proof_verdict WHERE run IN (${placeholders})`).all(...runIds);
    for (const row of rows) {
      const read = readProofVerdict(row as Record<string, unknown>);
      map.set(read.run, read);
    }
    return map;
  }

  /** The operator's explicit acceptance of a short/refuted verdict — the
   * one act that lets the task read done despite incomplete proof. */
  acceptProof(runId: number, approver: string, note: string | null, now: Date): void {
    this.db
      .prepare(
        `INSERT INTO proof_acceptance (run, approver, note, accepted_at) VALUES (?, ?, ?, ?)
         ON CONFLICT (run) DO UPDATE SET approver = excluded.approver, note = excluded.note, accepted_at = excluded.accepted_at`,
      )
      .run(runId, approver, note, now.toISOString());
  }

  proofAcceptance(runId: number): ProofAcceptanceRow | null {
    const row = this.db.prepare("SELECT * FROM proof_acceptance WHERE run = ?").get(runId);
    if (row === undefined) return null;
    const r = row as Record<string, unknown>;
    return {
      run: Number(r["run"]),
      approver: String(r["approver"]),
      note: r["note"] === null ? null : String(r["note"]),
      acceptedAt: String(r["accepted_at"]),
    };
  }

  // ---- criterion review (v40, evidence-review-v1) ------------------------

  /** Every criterion judgement recorded against a run's proof, in the order
   * they were saved — the task/run pages' own read, and the input to a
   * repair draft's "named unmet ids". */
  criterionReviewsFor(runId: number): CriterionReviewRow[] {
    return this.db
      .prepare("SELECT * FROM criterion_review WHERE source_run = ? ORDER BY id ASC")
      .all(runId)
      .map(row => readCriterionReview(row as Record<string, unknown>));
  }

  /**
   * The independent reviewer's per-criterion judgements land through ONE
   * proving transaction (the addReviewerComments/D8 pattern, extended):
   * the authoring run must BE the admitted reviewer or one of its bounded
   * same-session correction children, sharing its task/provider/model
   * lineage, and the artifact must be that run's own terminal diff. Every
   * judgement row is immutable once inserted.
   *
   * Audit hardening (still evidence-review-v1, unreleased): `bindings`
   * names every OTHER input the reviewer was materialized — the scope
   * digest it read the rubric against, the run's head, and (when they
   * exist) the proof, check log, and screenshot artifacts — exactly as
   * the reviewer pass captured them at materialization time. Every one is
   * RE-VALIDATED here, against the LIVE store, at ingest time: a caller's
   * claim about what it showed the agent is worth nothing on its own. A
   * mismatch (the scope was revised, an artifact's stored hash no longer
   * matches what was captured) throws and the whole ingest rolls back —
   * "stale" is refused, never silently accepted. `null`/`[]` inside
   * `bindings` means that input never existed for this run (no verify
   * command configured, no screenshots claimed): an omission, which
   * validates trivially, never a mismatch.
   *
   * Immediately afterward, in the SAME transaction, the judgements are
   * FOLDED into the run's already-adjudicated verdict (`foldReview`) and
   * saved back through `saveProofVerdict` — the one "re-computation of the
   * SAME run's proof" its own contract allows. The verdict that existed
   * before the fold is preserved as `machine_verdict`, exactly once (v39's
   * `matrix_json` already made this contract precise: nothing here is
   * silently rewritten, a surface can always say what the machine
   * attested versus what a reviewer later contradicted).
   * A non-empty submission must cover that stored matrix exactly once per
   * id. This repeats the parser's coverage proof at the durable boundary:
   * no proof verdict, partial/foreign ids, or duplicates insert anything.
   *
   * Called with `judgements: []` only when both the signed rubric and stored
   * matrix are proved empty (every genuinely grandfathered/rubricless
   * review). It remains a fold no-op, but still proves reviewer lineage,
   * exact diff, and the absence of signed criteria before comments can land.
   * Proof/check/screenshot inputs are not materialized for that rubricless
   * path, so their inventory becomes relevant only to a criterion review.
   */
  ingestCriterionReviews(
    args: {
      evidenceRoot?: string;
      reviewerRunId: number;
      runId: number;
      artifactId: number;
      author: string;
      judgements: readonly { id: string; judgement: CriterionJudgementWord; note: string }[];
      bindings: {
        diffSha: string;
        scopeDigest: string | null;
        headSha: string | null;
        proof: { artifactId: number; sha256: string } | null;
        checkLog: { artifactId: number; sha256: string } | null;
        verification?: string;
        screenshots: readonly { artifactId: number; sha256: string; path?: string }[];
        /** v51: the sealed review-context inventory, or null when the run
         * captured none. Absent (undefined) reads as null — every caller
         * before v51 showed the reviewer no inventory. */
        context?: { artifactId: number; sha256: string } | null;
      };
    },
    now: Date,
  ): { verdict: ProofVerdictRow["verdict"] } | null {
    return this.transact(() => {
      const reviewer = this.getRun(args.reviewerRunId);
      if (reviewer === null || reviewer.role !== "reviewer") {
        throw new ReviewBindingError(`run ${args.reviewerRunId} is not a reviewer — only the reviewer role authors criterion judgements`);
      }
      if (!this.reviewerLineageReaches(args.reviewerRunId, args.runId)) {
        throw new ReviewBindingError(
          `reviewer ${args.reviewerRunId} reviews run outside the bounded lineage for ${args.runId} — judgements bind to the run the review was minted for`,
        );
      }
      const source = this.getRun(args.runId);
      if (source === null || source.taskRef !== reviewer.taskRef) {
        throw new ReviewBindingError(`reviewer ${args.reviewerRunId} and run ${args.runId} do not share a task — nothing is ingested`);
      }
      const runArtifacts = this.artifactsFor(args.runId);
      const artifact = runArtifacts.find(one => one.id === args.artifactId);
      if (artifact === undefined || artifact.kind !== "terminal-diff") {
        throw new ReviewBindingError(`artifact ${args.artifactId} is not run ${args.runId}'s terminal diff — judgements bind to the exact bytes reviewed`);
      }
      if (artifact.sha256 !== args.bindings.diffSha) {
        throw new ReviewBindingError(`run ${args.runId}'s terminal diff no longer matches what the reviewer was shown — nothing is ingested`);
      }

      // The parser normally proves full rubric coverage before this call,
      // but the store is the durable trust boundary: direct/replayed callers
      // must not be able to fold a partial, duplicated, or ungrounded review.
      // Resolve the exact signed matrix BEFORE inserting anything so every
      // refusal rolls comments and judgements back together in ingestReview.
      const existing = this.proofVerdictFor(args.runId);
      const expectedIds = existing?.matrix.map(row => row.id) ?? [];
      const expected = new Set(expectedIds);
      if (expected.size !== expectedIds.length) {
        throw new ReviewBindingError(`run ${args.runId}'s stored criterion matrix contains duplicate ids — nothing is ingested`);
      }

      // Scope is historical build authority. A digest-bearing run must still
      // resolve to those exact signed bytes at ingest, including the legacy
      // case where those bytes carried no rubric. A run with no digest is
      // genuinely grandfathered: a scope added later is never retroactive.
      let signedIds: string[] = [];
      if (source.scopeDigest !== null) {
        const taskId = this.externalIdFor(source.taskRef);
        const liveScope = taskId === null ? null : this.getScope(taskId);
        if (liveScope === null || liveScope.digest !== source.scopeDigest) {
          throw new ReviewBindingError(
            `run ${args.runId}'s scope no longer matches the signed build scope — nothing is ingested`,
          );
        }
        signedIds = liveScope.acceptance.map(criterion => criterion.id);
      }
      const signed = new Set(signedIds);
      if (signed.size !== signedIds.length) {
        throw new ReviewBindingError(`run ${args.runId}'s signed rubric contains duplicate ids — nothing is ingested`);
      }
      const expectedScopeBinding = signed.size === 0 ? null : source.scopeDigest;
      if (args.bindings.scopeDigest !== expectedScopeBinding) {
        throw new ReviewBindingError(
          `run ${args.runId}'s build scope does not match the digest the reviewer was shown — nothing is ingested`,
        );
      }
      if (
        source.scopeDigest !== null &&
        (expected.size !== signed.size || [...expected].some(id => !signed.has(id)))
      ) {
        throw new ReviewBindingError(
          `run ${args.runId}'s stored criterion matrix does not match its exact signed criterion set — nothing is ingested`,
        );
      }
      if (existing === null && args.judgements.length > 0) {
        throw new ReviewBindingError(`run ${args.runId} has no proof verdict to review — nothing is ingested`);
      }

      const submittedIds = args.judgements.map(judgement => judgement.id);
      const submitted = new Set(submittedIds);
      if (submitted.size !== submittedIds.length) {
        throw new ReviewBindingError(`reviewer ${args.reviewerRunId} submitted a criterion more than once — nothing is ingested`);
      }
      if (submitted.size !== expected.size || [...submitted].some(id => !expected.has(id))) {
        throw new ReviewBindingError(
          `reviewer ${args.reviewerRunId} did not cover the exact stored criterion set for run ${args.runId} — nothing is ingested`,
        );
      }
      // Only a truly empty stored/signed rubric admits a comments-only
      // review. This check deliberately comes AFTER deriving both sets: an
      // empty caller array is input, never proof that there was no rubric.
      if (args.judgements.length === 0) return null;
      if (existing === null) throw new ReviewBindingError("unreachable criterion review without a proof verdict");

      // Re-derive and re-validate every OTHER input the reviewer was
      // shown — never trust the caller's claim about what it showed the
      // agent. Bindings are mandatory: absence must never silently mean
      // "the reviewer saw nothing".
      const bindings = args.bindings;
      const liveHead = source.headRevision ?? source.baseRevision;
      if (bindings.headSha !== liveHead) {
        throw new ReviewBindingError(`run ${args.runId}'s head no longer matches what the reviewer was shown — nothing is ingested`);
      }

      // Proof and check-log are singular review inputs. Refuse an ambiguous
      // live inventory, then require the caller's binding to equal the one
      // source artifact exactly — including proving absence when it says
      // null. This closes both forged omissions and mid-review additions.
      const proofArtifacts = runArtifacts.filter(one => one.kind === "proof");
      if (proofArtifacts.length > 1) {
        throw new ReviewBindingError(`run ${args.runId} has more than one proof artifact — the exact review inventory is ambiguous; nothing is ingested`);
      }
      const liveProof = proofArtifacts[0] ?? null;
      if (
        (liveProof === null) !== (bindings.proof === null) ||
        (liveProof !== null &&
          bindings.proof !== null &&
          (liveProof.id !== bindings.proof.artifactId || liveProof.sha256 !== bindings.proof.sha256))
      ) {
        throw new ReviewBindingError(`run ${args.runId}'s proof inventory no longer matches what the reviewer was shown — nothing is ingested`);
      }

      const checkLogArtifacts = runArtifacts.filter(one => one.kind === "check-log");
      if (checkLogArtifacts.length > 1) {
        throw new ReviewBindingError(`run ${args.runId} has more than one check-log artifact — the exact review inventory is ambiguous; nothing is ingested`);
      }
      const liveCheckLog = checkLogArtifacts[0] ?? null;
      if (
        (liveCheckLog === null) !== (bindings.checkLog === null) ||
        (liveCheckLog !== null &&
          bindings.checkLog !== null &&
          (liveCheckLog.id !== bindings.checkLog.artifactId || liveCheckLog.sha256 !== bindings.checkLog.sha256))
      ) {
        throw new ReviewBindingError(`run ${args.runId}'s check-log inventory no longer matches what the reviewer was shown — nothing is ingested`);
      }

      // Screenshots are plural: equality means the complete id/hash/capture
      // set, not merely that every caller-supplied member happens to exist.
      const liveScreenshots = runArtifacts.filter(one => one.kind === "screenshot");
      const boundScreenshots = new Map(bindings.screenshots.map(shot => [shot.artifactId, shot]));
      if (
        boundScreenshots.size !== bindings.screenshots.length ||
        liveScreenshots.length !== bindings.screenshots.length ||
        liveScreenshots.some(shot => {
          const bound = boundScreenshots.get(shot.id);
          return bound === undefined || bound.sha256 !== shot.sha256 || bound.path !== shot.capture;
        })
      ) {
        throw new ReviewBindingError(`run ${args.runId}'s screenshot inventory no longer matches what the reviewer was shown — nothing is ingested`);
      }
      const screenshotsJson = JSON.stringify(
        liveScreenshots.map(shot => ({ artifact: shot.id, sha256: shot.sha256, path: shot.capture })),
      );

      // v51: the review-context inventory is singular like the proof, and
      // its binding is proved both ways — a caller that showed none while
      // the run now carries one (empty-to-added), or showed one the run no
      // longer carries at that exact hash, is refused whole.
      const contextArtifacts = runArtifacts.filter(one => one.kind === "review-context");
      if (contextArtifacts.length > 1) {
        throw new ReviewBindingError(`run ${args.runId} has more than one review-context artifact — the exact review inventory is ambiguous; nothing is ingested`);
      }
      const liveContext = contextArtifacts[0] ?? null;
      const boundContext = bindings.context ?? null;
      if (
        (liveContext === null) !== (boundContext === null) ||
        (liveContext !== null &&
          boundContext !== null &&
          (liveContext.id !== boundContext.artifactId || liveContext.sha256 !== boundContext.sha256))
      ) {
        throw new ReviewBindingError(`run ${args.runId}'s review-context inventory no longer matches what the reviewer was shown — nothing is ingested`);
      }

      for (const judgement of args.judgements) {
        this.db
          .prepare(
            `INSERT INTO criterion_review
               (reviewer_run, source_run, criterion_id, judgement, note, artifact, artifact_sha, author, created_at,
                scope_digest, head_sha, proof_artifact, proof_sha, check_log_artifact, check_log_sha, screenshots_json,
                context_artifact, context_sha)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            args.reviewerRunId,
            args.runId,
            judgement.id,
            judgement.judgement,
            judgement.note,
            args.artifactId,
            artifact.sha256,
            args.author,
            now.toISOString(),
            bindings.scopeDigest,
            bindings.headSha,
            bindings.proof?.artifactId ?? null,
            bindings.proof?.sha256 ?? null,
            bindings.checkLog?.artifactId ?? null,
            bindings.checkLog?.sha256 ?? null,
            screenshotsJson,
            boundContext?.artifactId ?? null,
            boundContext?.sha256 ?? null,
          );
      }
      const reassessed = args.evidenceRoot === undefined || args.bindings.verification === undefined || args.bindings.context == null
        ? null : assessmentFromSavedEvidence(this, args.evidenceRoot, args.runId);
      if (reassessed !== null) this.addRunNote(args.runId, "Toolroll", "Fresh goal assessment uses this result's original saved source and verification receipt. Its earlier status was: no proof was written. No check or artifact was replaced.", now);
      const folded = foldReview(
        reassessed ?? { verdict: existing.verdict, reasons: existing.reasons, matrix: existing.matrix, ...(existing.machineVerdict === null ? {} : { machineVerdict: existing.machineVerdict }) },
        args.judgements.map((j): CriterionJudgement => ({ id: j.id, judgement: j.judgement, note: j.note, author: args.author })),
      );
      this.saveProofVerdict(args.runId, folded.verdict, folded.reasons, now, folded.matrix, reassessed?.machineVerdict ?? existing.machineVerdict ?? existing.verdict);
      return { verdict: folded.verdict };
    });
  }

  /**
   * The whole review, ingested atomically (audit hardening — still
   * evidence-review-v1, unreleased): comments and criterion judgements
   * used to commit through two separate `transact()` calls from the
   * caller — reentrant, so never actually torn in production, but two
   * calls a crash between could still leave comments landed with no
   * judgements, or vice versa. This is the ONE call the reviewer pass
   * makes: everything above rolls back together, or none of it lands. The
   * admitted root reviewer and, when present, the correction child that
   * authored the accepted payload are concluded in this transaction too.
   * That terminal run state is the replay latch: committed review rows can
   * never be left beside an open root that could author them again after a
   * process crash.
   */
  ingestReview(
    args: {
      reviewerRunId: number;
      evidenceRoot?: string;
      learning?: unknown;
      learningAssessment?: unknown;
      runId: number;
      artifactId: number;
      author: string;
      comments: readonly { path: string; line: number | null; note: string; severity: "note" | "question" | "problem" }[];
      judgements: readonly { id: string; judgement: CriterionJudgementWord; note: string }[];
      bindings: {
        diffSha: string;
        scopeDigest: string | null;
        headSha: string | null;
        proof: { artifactId: number; sha256: string } | null;
        checkLog: { artifactId: number; sha256: string } | null;
        verification?: string;
        screenshots: readonly { artifactId: number; sha256: string; path?: string }[];
        context?: { artifactId: number; sha256: string } | null;
      };
    },
    now: Date,
  ): { commentIds: number[]; folded: { verdict: ProofVerdictRow["verdict"] } | null } {
    return this.transact(() => {
      // The last provider turn and this write are separated by application
      // code. Re-prove the admitted runner incarnation inside the SAME
      // transaction that lands the review so a rotation cannot win that
      // final gap. The caller maps this named error back to its typed
      // runner-custody outcome.
      if (!this.proveRunnerCustodyForSpawn(args.reviewerRunId, now)) {
        const error = new Error(
          `reviewer ${args.reviewerRunId}'s runner custody no longer stands — nothing is ingested`,
        );
        error.name = "ReviewerCustodyError";
        throw error;
      }
      // THE STOP FENCE at ingestion (v52): a stop recorded against this
      // reviewer (or the root it corrects) before this write wins — late
      // review output is never ingested as a judgement. Named so the
      // caller seals the attempt as interrupted, never as a review failure.
      if (this.applicableStopFor(args.reviewerRunId) !== null) {
        const error = new Error(`reviewer ${args.reviewerRunId} was stopped by the operator before its review could be ingested — nothing is ingested`);
        error.name = "ReviewerStoppedError";
        throw error;
      }
      const authoringReviewer = this.getRun(args.reviewerRunId);
      const rootReviewer = authoringReviewer === null ? null : this.reviewerRoot(authoringReviewer, true);
      if (rootReviewer === null) {
        throw new ReviewBindingError(`reviewer ${args.reviewerRunId} no longer has a live, provider-started admitted lineage — nothing is ingested`);
      }
      const terminalDiff = this.artifactsFor(args.runId).find(one => one.id === args.artifactId);
      if (
        terminalDiff === undefined ||
        terminalDiff.kind !== "terminal-diff" ||
        terminalDiff.sha256 !== args.bindings.diffSha
      ) {
        throw new ReviewBindingError(`run ${args.runId}'s terminal diff no longer matches what the reviewer was shown — nothing is ingested`);
      }
      // Context is an input inventory with ancestor dependencies. Re-read
      // its bytes and every bound ancestor inside the same write transaction.
      const contexts = this.artifactsFor(args.runId).filter(one => one.kind === "review-context");
      if (contexts.length > 0 || args.bindings.context != null) {
        const context = contexts[0];
        if (contexts.length !== 1 || context === undefined || args.bindings.context == null || context.id !== args.bindings.context.artifactId || context.sha256 !== args.bindings.context.sha256 || args.evidenceRoot === undefined) throw new ReviewBindingError("the review context inventory or evidence root is missing or changed");
        const verified = readVerifiedArtifact(args.evidenceRoot, context);
        if (!verified.ok) throw new ReviewBindingError("the review context bytes no longer verify");
        const parsed = parseReviewContext(verified.content.toString("utf8"));
        if (!parsed.ok) throw new ReviewBindingError(parsed.problem);
        const problem = reviewContextCustodyProblem(this, args.evidenceRoot, parsed.inventory);
        if (problem !== null) throw new ReviewBindingError(problem);
      }
      if (args.bindings.verification !== undefined) {
        const route = this.proveRouteForSpawn(args.reviewerRunId, now);
        if (!route.ok) throw new ReviewBindingError(route.problem);
        if (args.evidenceRoot === undefined) throw new ReviewBindingError("Verification evidence root is missing");
        const gate = verificationEvidence(this, args.evidenceRoot, args.runId);
        if (!gate.ok || gate.digest !== args.bindings.verification) throw new ReviewBindingError(gate.ok ? "Verification authority or receipt changed" : gate.problem);
      }
      const commentIds = this.addReviewerComments(
        { reviewerRunId: args.reviewerRunId, runId: args.runId, artifactId: args.artifactId, author: args.author, comments: args.comments },
        now,
      );
      const folded = this.ingestCriterionReviews(
        {
          ...(args.evidenceRoot === undefined ? {} : { evidenceRoot: args.evidenceRoot }),
          reviewerRunId: args.reviewerRunId,
          runId: args.runId,
          artifactId: args.artifactId,
          author: args.author,
          judgements: args.judgements,
          bindings: args.bindings,
        },
        now,
      );
      if (args.reviewerRunId !== rootReviewer.id) {
        this.finishRun(args.reviewerRunId, {
          outcome: "no-change",
          reason: "structured review repaired",
          now,
        });
      }
      const judged =
        args.judgements.length > 0
          ? `, ${args.judgements.length} judgement(s)${folded?.verdict === "refuted" ? " (review-contradicted)" : ""}`
          : "";
      this.finishRun(rootReviewer.id, {
        outcome: "no-change",
        reason: `reviewed — ${commentIds.length} comment(s)${judged}`,
        now,
      });
      queueLearning(this, args.runId, args.reviewerRunId, args.learning, [
        { artifactId: args.artifactId, sha256: args.bindings.diffSha },
        ...[args.bindings.proof, args.bindings.checkLog, args.bindings.context].filter((x): x is { artifactId: number; sha256: string } => x != null),
      ], now, args.learningAssessment);
      return { commentIds, folded };
    });
  }

  // ---- run notes (M6) -----------------------------------------------------

  /** Append one immutable operator note to a run. Validation is the caller's (validateNote). */
  addRunNote(runId: number, author: string, note: string, now: Date): number {
    const run = this.getRun(runId);
    if (run === null) throw new Error(`run ${runId} does not exist — a note needs a record to sit next to`);
    const inserted = this.db
      .prepare("INSERT INTO run_note (run, author, note, created_at) VALUES (?, ?, ?, ?)")
      .run(runId, author, note, now.toISOString());
    return Number(inserted.lastInsertRowid);
  }

  // ---- intake grants (M8.16) ---------------------------------------------

  setIntakeGrant(
    args: { repo: string; github: string; label: string; reviewers: string[] | null; approvedBy: string },
    now: Date,
  ): IntakeGrant {
    return this.transact(() => {
      this.db
        .prepare("UPDATE intake_grant SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
        .run(now.toISOString(), args.approvedBy, args.repo);
      const inserted = this.db
        .prepare(
          `INSERT INTO intake_grant (repo, github, label, reviewers, approved_by, approved_at)
           VALUES (?, ?, ?, ?, ?, ?)`,
        )
        .run(
          args.repo,
          args.github,
          args.label,
          args.reviewers === null ? null : args.reviewers.join(","),
          args.approvedBy,
          now.toISOString(),
        );
      const row = this.db.prepare("SELECT * FROM intake_grant WHERE id = ?").get(Number(inserted.lastInsertRowid));
      return readIntakeGrant(row as Record<string, unknown>);
    });
  }

  liveIntakeGrant(repo: string): IntakeGrant | null {
    const row = this.db.prepare("SELECT * FROM intake_grant WHERE repo = ? AND revoked_at IS NULL").get(repo);
    return row === undefined ? null : readIntakeGrant(row);
  }

  clearIntakeGrant(repo: string, by: string, now: Date): boolean {
    const done = this.db
      .prepare("UPDATE intake_grant SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
      .run(now.toISOString(), by, repo);
    return Number(done.changes) > 0;
  }

  // ---- diff comments and revision tasks (M6.8) ---------------------------

  /**
   * A comment on an immutable terminal diff. The artifact must belong to
   * the run and be a terminal diff; the recorded sha binds the words to the
   * exact bytes reviewed — a comment whose artifact hash no longer matches
   * is a comment on something else, refused at read time by the verifier.
   */
  addDiffComment(
    args: {
      artifactId: number;
      runId: number;
      path: string | null;
      line: number | null;
      note: string;
      author: string;
      /** Ingested comments carry their origin id — the idempotency key (M8.17). */
      sourceKey?: string;
    },
    now: Date,
  ): number | null {
    const artifact = this.artifactsFor(args.runId).find(one => one.id === args.artifactId);
    if (artifact === undefined || artifact.kind !== "terminal-diff") {
      throw new Error(`artifact ${args.artifactId} is not run ${args.runId}'s terminal diff — comments bind to the exact bytes reviewed`);
    }
    // The unique index is the real concurrent guard (audit C-9): a race on
    // the same source key lands in DO NOTHING, not in a thrown constraint.
    const inserted = this.db
      .prepare(
        `INSERT INTO diff_comment (artifact, artifact_sha, run, path, line, note, author, created_at, source_key)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT (source_key) WHERE source_key IS NOT NULL DO NOTHING`,
      )
      .run(
        args.artifactId,
        artifact.sha256,
        args.runId,
        args.path,
        args.line,
        args.note,
        args.author,
        now.toISOString(),
        args.sourceKey ?? null,
      );
    return Number(inserted.changes) === 0 ? null : Number(inserted.lastInsertRowid);
  }

  /** Live (unsuperseded, unconsumed) comments on a run's terminal diff. */
  liveDiffComments(runId: number): DiffComment[] {
    return this.db
      .prepare("SELECT * FROM diff_comment WHERE run = ? AND superseded_by IS NULL AND consumed_by IS NULL ORDER BY id")
      .all(runId)
      .map(readDiffComment);
  }

  /** The comment a source key already names, on ANY run (repair
   * 2026-09-14): the read behind a request-token retry, so a replay can be
   * told from a conflicting reuse — same run and same words land on the
   * same receipt; different words, or another run, are refused. */
  diffCommentBySourceKey(sourceKey: string): DiffComment | null {
    const row = this.db.prepare("SELECT * FROM diff_comment WHERE source_key = ?").get(sourceKey);
    return row === undefined ? null : readDiffComment(row);
  }

  /** Every comment on a run, consumed included — the audit view. */
  allDiffComments(runId: number): DiffComment[] {
    return this.db.prepare("SELECT * FROM diff_comment WHERE run = ? ORDER BY id").all(runId).map(readDiffComment);
  }

  /**
   * Seal a comment batch into a revision task, in one transaction: the
   * comments are marked consumed by the new task id, so a second click
   * finds nothing to consume instead of minting a duplicate task.
   */
  consumeDiffComments(runId: number, ids: readonly number[], taskId: string): number {
    if (ids.length === 0) return 0;
    let consumed = 0;
    for (const id of ids) {
      const done = this.db
        .prepare("UPDATE diff_comment SET consumed_by = ? WHERE id = ? AND run = ? AND consumed_by IS NULL AND superseded_by IS NULL")
        .run(taskId, id, runId);
      consumed += Number(done.changes);
    }
    return consumed;
  }

  // ---- fallback chains: the fenced cycle state machine (v30, C7) --------

  /** The open cycle for a task, if one exists (the runtime's read). */
  fallbackCycleFor(taskRef: number): FallbackCycle | null {
    const row = this.db
      .prepare("SELECT * FROM fallback_cycle WHERE task_ref = ? AND state NOT IN ('closed','incident') ORDER BY id DESC LIMIT 1")
      .get(taskRef);
    return row === undefined ? null : readFallbackCycle(row as Record<string, unknown>);
  }

  /** Open a fresh cycle at index 0 for a running base attempt. One live
   * cycle per task — the SELECT-then-INSERT under BEGIN IMMEDIATE
   * serializes writers, and the one_live_fallback_cycle_per_task partial
   * unique index is the durable backstop (finding 5). A second refuses. */
  openFallbackCycle(taskRef: number, chainDigest: string, tailRun: number | null, now: Date): { ok: true; id: number } | { ok: false } {
    return this.transact(() => {
      const existing = this.db
        .prepare("SELECT 1 AS hit FROM fallback_cycle WHERE task_ref = ? AND state NOT IN ('closed','incident') LIMIT 1")
        .get(taskRef);
      if (existing !== undefined) return { ok: false as const };
      const inserted = this.db
        .prepare(
          `INSERT INTO fallback_cycle (task_ref, chain_digest, cursor, state, transition_generation, tail_run, created_at, updated_at)
           VALUES (?, ?, 0, 'open', 0, ?, ?, ?)`,
        )
        .run(taskRef, chainDigest, tailRun, now.toISOString(), now.toISOString());
      return { ok: true as const, id: Number(inserted.lastInsertRowid) };
    });
  }

  /**
   * The task's IMMUTABLE approved chain — the runtime's single source of
   * truth for chain length and per-entry authority (never mutable config).
   * Returns the rehydrated entries when the approval sealed a chain and the
   * snapshot still rehydrates strictly; null otherwise (a single-profile
   * approval, or a snapshot that fails the strict rehydrator — fail closed,
   * so a corrupt chain dispatches nothing).
   */
  approvedChainOf(taskId: string): ChainEntry[] | null {
    const scope = this.getScope(taskId);
    if (scope === null || scope.termsProblem != null || scope.approvalKind !== "chain" || scope.approvedChainJson == null) return null;
    // The approval must still STAND (Codex E2/E3 review, finding 2): a scope
    // rewritten without reapproval has withdrawn its authority — chain
    // snapshot included — so a stale approved_chain_json can never remain
    // fallback authority. approvedDigest === digest is the same freshness the
    // build gate proves.
    if (scope.approvedAt === null || scope.approvedDigest === null || scope.approvedDigest !== scope.digest) {
      return null;
    }
    const chain = chainFromJson(scope.approvedChainJson);
    if (chain === null) return null;
    // The snapshot must be the one the SIGNED digest binds — recompute from
    // the current scope fields + this chain and require an exact match, so a
    // snapshot that does not correspond to the approved digest never governs.
    const rederived = digestOf(
      { goal: scope.goal, outOfScope: scope.outOfScope, touches: scope.touches, budgetMicrousd: scope.budgetMicrousd, acceptance: scope.acceptance, candidate: scope.candidate ?? null, qualityMode: scope.qualityMode ?? "default" },
      { chain },
      routeFromJson(scope.approvedRouteJson ?? null),
    );
    if (rederived !== scope.approvedDigest) return null;
    // THE MIRROR MUST STAND (v48 integrity): a chain approval also seals
    // the profile column as a mirror of the chain's base entry. A mirror
    // that is missing, cannot be read exactly, or names another profile
    // is a tampered seal — the chain is NOT downgraded to "chain-only
    // authority"; nothing dispatches on it until it is approved again.
    const base = chain[0];
    const mirrored = profileFromJson(scope.approvedProfileJson === undefined ? (scope.approvedProfile == null ? null : canonicalProfileJson(scope.approvedProfile)) : scope.approvedProfileJson);
    if (base === undefined || mirrored === null || profileDigestOf(mirrored) !== profileDigestOf(base.profile)) return null;
    return chain;
  }

  /**
   * The ONE chain-cycle resolver at a run's end (E3c/E3d): every concluded
   * tail resolves its cycle — success closes it, an ordinary end closes it
   * (the retry road runs the BASE entry under a FRESH cycle; a concluded
   * tail can never be re-tagged, so leaving it open would only strand it),
   * a parked tail is a PAUSED lineage and stays open for repair, and a
   * recognized eligible exhaustion advances. Both the disposition hook and
   * the crash reconciler call THIS method, so a crash between disposition
   * and resolution re-derives the same answer from durable state.
   *
   * The advance is FAIL CLOSED at every gate:
   *   - an OPEN cycle whose tail is exactly this finished run;
   *   - the run genuinely finished (outcome + finished_at +
   *     provider_started_at, same task) — never live custody;
   *   - a fallback-ELIGIBLE class consistent with the run's auth mode;
   *   - the C8 re-check: THIS build recognizes the exact class/auth for the
   *     run's (provider, version) — a downgrade severs to incident;
   *   - the LIVE signed mode's paid-fallback grant, re-read IN-transaction;
   *   - a next entry in the IMMUTABLE approved chain (else exhausted-end).
   * The fenced custody walk — sanitize, advance, release-to-pending — runs
   * atomically inside ONE transaction; a lost inner CAS rolls the whole
   * walk back. It NEVER dispatches: the admission pass creates the run.
   */
  resolveChainOnRunEnd(
    taskRef: number,
    taskId: string,
    repo: string | null,
    finishedRunId: number,
    now: Date,
  ):
    | { kind: "advanced"; toIndex: number }
    | { kind: "exhausted-end" }
    | { kind: "closed"; reason: "succeeded" | "entry-ended" }
    | { kind: "blocked"; reason: "no-recognizer" | "grant-withheld" | "corrupt-chain" | "cycle-mismatch" }
    | { kind: "parked-tail" }
    | { kind: "no-cycle" } {
    try {
      return this.transact(() => {
        const cycle = this.fallbackCycleFor(taskRef);
        if (cycle === null || cycle.state !== "open" || cycle.tailRun !== finishedRunId) {
          return { kind: "no-cycle" as const };
        }
        const run = this.getRun(finishedRunId);
        if (run === null) return { kind: "no-cycle" as const };
        // The predecessor must be genuinely FINISHED (Codex E2/E3 review,
        // finding 7): a run whose outcome is still open — or that never
        // spawned a provider — is live custody, and advancing off it could
        // start the next entry beside a running predecessor. Its task must be
        // this task, too. (A success that never spawned — a no-change without
        // a provider — still closes below; the started-at proof gates only
        // the ADVANCE road.)
        if (run.taskRef !== taskRef || run.outcome === null || run.finishedAt === null) {
          return { kind: "no-cycle" as const };
        }
        // A successful tail: the chain did its job — closed, terminally.
        if (run.outcome === "built" || run.outcome === "no-change") {
          this.closeFallbackCycle(cycle.id, cycle.transitionGeneration, "succeeded", now);
          return { kind: "closed" as const, reason: "succeeded" as const };
        }
        // A parked tail is a PAUSED lineage, not an ended one: repair resumes
        // the same custody, and the cycle stays open for it.
        if (run.outcome === "parked") return { kind: "parked-tail" as const };
        // An operator-stopped tail (v52) ends the cycle as an ordinary end:
        // a stop never advances a chain, spends a fallback edge, or counts
        // as the exhaustion the chain was approved to survive. The resumed
        // attempt opens its own cycle at the base, under the same approval.
        if (this.applicableStopFor(finishedRunId) !== null) {
          this.closeFallbackCycle(cycle.id, cycle.transitionGeneration, "entry-ended", now);
          return { kind: "closed" as const, reason: "entry-ended" as const };
        }
        const cls: TerminalClass = run.terminalClass ?? "unknown";
        // A chain-bound tail carries its pinned auth mode from admission; a
        // row whose auth mode does not read (v48 authority repair) is a corrupt stamp and
        // ends the cycle as an ordinary end — never as a subscription run.
        const authMode = run.authMode ?? null;
        // An ordinary end (failure, refusal, interruption) — or a corrupt
        // class/auth pairing, which must READ as ordinary (finding 8) —
        // ends the cycle. The retry road opens a fresh one at the base.
        if (authMode === null || !isFallbackEligible(cls) || !classMatchesAuthMode(cls, authMode)) {
          this.closeFallbackCycle(cycle.id, cycle.transitionGeneration, "entry-ended", now);
          return { kind: "closed" as const, reason: "entry-ended" as const };
        }
        // The ADVANCE road requires a proven provider spawn.
        if (run.providerStartedAt === null) {
          this.closeFallbackCycle(cycle.id, cycle.transitionGeneration, "entry-ended", now);
          return { kind: "closed" as const, reason: "entry-ended" as const };
        }
        // C8 re-check at the authority point (findings 1/8): THIS build must
        // recognize the EXACT eligible class for this auth mode — not merely
        // "some eligible recognizer exists." A build with no such fixture
        // (every real build) severs the cycle to incident, loudly.
        if (!recognizesEligible(run.provider as ProviderId, run.providerVersion, authMode)) {
          this.incidentFallback(cycle.id, cycle.transitionGeneration, "recognizer-absent-at-advance", now);
          return { kind: "blocked" as const, reason: "no-recognizer" as const };
        }
        // The paid-fallback grant is re-proved from the LIVE signed mode
        // INSIDE this transaction (finding 4): a boolean read before the
        // transaction is a TOCTOU — a mode revoked or replaced meanwhile must
        // deny the advance.
        const liveGrant =
          repo === null
            ? false
            : modeTermsFromJson(this.activeMode(repo, now)?.termsJson ?? null)?.allowPaidFallback === true;
        if (!liveGrant) {
          // No live grant: the cycle ends here, cleanly, and the run disposes
          // as the ordinary exhaustion it is.
          this.closeFallbackCycle(cycle.id, cycle.transitionGeneration, "grant-withheld", now);
          return { kind: "blocked" as const, reason: "grant-withheld" as const };
        }
        const chain = this.approvedChainOf(taskId);
        if (chain === null) {
          // A chain we can no longer re-derive (or whose approval was
          // withdrawn) is never advanced on.
          this.incidentFallback(cycle.id, cycle.transitionGeneration, "approved-chain-unrehydratable", now);
          return { kind: "blocked" as const, reason: "corrupt-chain" as const };
        }
        // The open cycle must belong to THIS approved chain (finding 2,
        // scenario B): a scope reapproved under a different chain must not
        // let an old cycle admit into the new one.
        if (cycle.chainDigest !== chainDigestOf(chain)) {
          this.incidentFallback(cycle.id, cycle.transitionGeneration, "cycle-chain-digest-mismatch", now);
          return { kind: "blocked" as const, reason: "cycle-mismatch" as const };
        }
        const chainLength = chain.length;
        if (cycle.cursor + 1 >= chainLength) {
          // Eligible, but the whole chain is spent — the exhausted terminal.
          this.closeFallbackCycle(cycle.id, cycle.transitionGeneration, "chain-exhausted", now);
          return { kind: "exhausted-end" as const };
        }
        const g0 = cycle.transitionGeneration;
        if (!this.beginFallbackSanitize(cycle.id, g0, finishedRunId, now)) {
          throw new Error("fallback sanitize lost its CAS");
        }
        const adv = this.advanceFallbackFenced(
          {
            cycleId: cycle.id,
            expectGeneration: g0 + 1,
            fromIndex: cycle.cursor,
            chainLength,
            predecessorRun: finishedRunId,
            terminalClass: cls,
            evidence: {
              provider: run.provider,
              version: run.providerVersion,
              authMode: run.authMode ?? "subscription",
              fp: "",
            },
          },
          now,
        );
        if (!adv.ok) throw new Error(`fallback advance lost: ${adv.reason}`);
        if (!this.releaseFallbackToPending(cycle.id, g0 + 2, now)) {
          throw new Error("fallback release lost its CAS");
        }
        return { kind: "advanced" as const, toIndex: adv.toIndex };
      });
    } catch {
      // A lost CAS rolled the whole walk back (the cycle is untouched at its
      // generation): another authority raced us. Do nothing — next tick.
      return { kind: "no-cycle" as const };
    }
  }

  /**
   * The crash reconciler's read (E3d, review finding 3): OPEN cycles whose
   * tail run CONCLUDED (non-parked) but whose cycle was never resolved — the
   * window a crash between disposition and resolveChainOnRunEnd leaves. The
   * reconciler feeds each through the SAME resolver, so nothing is decided
   * twice or differently.
   */
  strandedChainCycles(repo: string): { cycleId: number; taskRef: number; taskId: string; tailRun: number }[] {
    return this.db
      .prepare(
        `SELECT fc.id AS cycle_id, fc.task_ref AS task_ref, tr.external_id AS task_id, fc.tail_run AS tail_run
           FROM fallback_cycle fc
           JOIN run r ON r.id = fc.tail_run
           JOIN task_ref tr ON tr.id = fc.task_ref AND tr.backend = ? AND tr.repo = ?
          WHERE fc.state = 'open' AND r.outcome IS NOT NULL AND r.outcome <> 'parked'`,
      )
      .all(BUILT_IN, repo)
      .map(row => ({
        cycleId: Number((row as Record<string, unknown>)["cycle_id"]),
        taskRef: Number((row as Record<string, unknown>)["task_ref"]),
        taskId: String((row as Record<string, unknown>)["task_id"]),
        tailRun: Number((row as Record<string, unknown>)["tail_run"]),
      }));
  }

  /**
   * The chain reconciler in ONE callable piece (F+G review, finding 5): the
   * EXACT code the tick runs each pass, so the fault tests drive the same
   * road production does — deleting the tick's call would fail them.
   * Resolves every open cycle whose tail concluded (non-parked) through the
   * one resolver; returns how many it fed through.
   */
  reconcileStrandedChains(repo: string, now: Date): number {
    let fed = 0;
    for (const stranded of this.strandedChainCycles(repo)) {
      this.resolveChainOnRunEnd(stranded.taskRef, stranded.taskId, repo, stranded.tailRun, now);
      fed++;
    }
    return fed;
  }

  /** Cycles awaiting their next entry's admission, for one repo — what the
   * tick's chain admission pass walks. */
  pendingChainAdmissions(repo: string): { cycleId: number; taskRef: number; taskId: string; cursor: number }[] {
    return this.db
      .prepare(
        `SELECT fc.id AS cycle_id, fc.task_ref AS task_ref, tr.external_id AS task_id, fc.cursor AS cursor
           FROM fallback_cycle fc
           JOIN task_ref tr ON tr.id = fc.task_ref AND tr.backend = ? AND tr.repo = ?
          WHERE fc.state = 'pending-admission'
          ORDER BY fc.id`,
      )
      .all(BUILT_IN, repo)
      .map(row => ({
        cycleId: Number((row as Record<string, unknown>)["cycle_id"]),
        taskRef: Number((row as Record<string, unknown>)["task_ref"]),
        taskId: String((row as Record<string, unknown>)["task_id"]),
        cursor: Number((row as Record<string, unknown>)["cursor"]),
      }));
  }

  /**
   * The PROVING admission (E3d): create the next entry's run from a
   * pending-admission cycle, with EVERY authority re-derived inside one
   * transaction — the approved chain must still stand and match the cycle's
   * digest, the entry at the cursor must exist, the LIVE signed mode must
   * still grant the paid fallback (revocation between advance and admission
   * denies), and the exact unconsumed pending edge is consumed by the run
   * it creates (admitFallback's single-use CAS). The caller carries only
   * claim, worktree, and rail; nothing it asserts becomes authority.
   */
  admitNextChainEntry(
    cycleId: number,
    run: { leaseId: string; runner: string; branch: string; worktree: string; recoveredFrom?: number },
    now: Date,
  ):
    | { ok: true; runId: number; taskId: string; provider: string; model: string }
    | { ok: false; reason: "not-pending" | "stale-approval" | "grant-withheld" | "no-edge" | "raced" | "provider-unavailable"; detail?: string } {
    return this.transact(() => {
      const cycle = this.db.prepare("SELECT * FROM fallback_cycle WHERE id = ?").get(cycleId);
      if (cycle === undefined) return { ok: false as const, reason: "not-pending" as const };
      const c = readFallbackCycle(cycle as Record<string, unknown>);
      if (c.state !== "pending-admission") return { ok: false as const, reason: "not-pending" as const };
      // Task and repo are DERIVED from the cycle's own task_ref (Codex E3d
      // review, finding 7) — never accepted from the caller, so a mismatched
      // call can't marry task B's approval to task A's cycle.
      const owner = this.db
        .prepare("SELECT external_id, repo FROM task_ref WHERE id = ? AND backend = ?")
        .get(c.taskRef, BUILT_IN);
      const taskId = owner === undefined ? null : String((owner as Record<string, unknown>)["external_id"]);
      const repo = owner === undefined ? null : ((owner as Record<string, unknown>)["repo"] as string | null);
      if (taskId === null || repo === null) {
        this.incidentFallback(c.id, c.transitionGeneration, "cycle-task-unresolvable", now);
        return { ok: false as const, reason: "stale-approval" as const };
      }
      const chain = this.approvedChainOf(taskId);
      if (chain === null || chainDigestOf(chain) !== c.chainDigest) {
        this.incidentFallback(c.id, c.transitionGeneration, "approved-chain-invalid-at-admission", now);
        return { ok: false as const, reason: "stale-approval" as const };
      }
      const entry = chain[c.cursor];
      if (entry === undefined) {
        this.incidentFallback(c.id, c.transitionGeneration, "cursor-beyond-approved-chain", now);
        return { ok: false as const, reason: "stale-approval" as const };
      }
      // The paid-fallback grant, re-proved at the MONEY moment: an advance
      // was granted, but a mode revoked since must still deny the spend.
      const liveGrant = modeTermsFromJson(this.activeMode(repo, now)?.termsJson ?? null)?.allowPaidFallback === true;
      if (!liveGrant) {
        this.closeFallbackCycle(c.id, c.transitionGeneration, "grant-withheld", now);
        return { ok: false as const, reason: "grant-withheld" as const };
      }
      // The entry's provider is re-checked INSIDE admission (v47): the
      // approved chain is the only substitution road, and it still never
      // opens a run on a provider this runner reports unavailable. The
      // cycle stays pending for a runner that can.
      const readiness = this.runnerReadinessOf(run.runner, entry.profile.provider);
      if (readiness !== null && readiness.state === "unavailable") {
        return {
          ok: false as const,
          reason: "provider-unavailable" as const,
          detail: `${entry.profile.provider} is reported unavailable on ${run.runner} (${readiness.reason}; observed ${readiness.observedAt}) — the approved fallback entry cannot run here`,
        };
      }
      const edge = this.db
        .prepare("SELECT id FROM fallback_transition WHERE cycle = ? AND to_index = ? AND consumed_by IS NULL ORDER BY id DESC LIMIT 1")
        .get(c.id, c.cursor);
      if (edge === undefined) {
        this.incidentFallback(c.id, c.transitionGeneration, "no-unconsumed-edge-at-admission", now);
        return { ok: false as const, reason: "no-edge" as const };
      }
      // Route provenance (v47/v48), proved and written INSIDE the admission
      // savepoint, before the row: an approved fallback entry spends as
      // `fallback` under the SEALED route, bound to exactly this cursor's
      // entry. There is no chain-only digest (raw authority repair): a
      // chain approval whose raw profile mirror, chain, and route do not
      // form one strict parity-valid sealed authority — a pre-routing chain,
      // a mirror that does not read or match, a route whose build and
      // repair legs are not the sealed profile's pairs — admits nothing.
      // The refusal is words alone: no run, no consumed edge, and no cycle
      // transition — the cycle stays exactly as it was.
      const sealed = this.sealedRouteOf(taskId);
      const mirror = this.getScope(taskId)?.approvedProfile ?? null;
      if (!sealed.ok || mirror === null) {
        return {
          ok: false as const,
          reason: "stale-approval" as const,
          detail: !sealed.ok
            ? `the chain approval's sealed agent route does not stand (${sealed.detail}) — nothing spends as a fallback under a chain-only digest; re-file the scope and approve it again`
            : "the approval's sealed agent profile mirror cannot be read — re-file the scope and approve it again",
        };
      }
      const admitted = this.admitFallback(
        {
          kind: "entry",
          cycleId: c.id,
          expectGeneration: c.transitionGeneration,
          expectCursor: c.cursor,
          expectTail: c.tailRun,
          transitionId: Number((edge as Record<string, unknown>)["id"]),
          run: {
            taskRef: c.taskRef,
            leaseId: run.leaseId,
            runner: run.runner,
            branch: run.branch,
            worktree: run.worktree,
            provider: entry.profile.provider,
            model: entry.profile.model,
            ...(run.recoveredFrom === undefined ? {} : { recoveredFrom: run.recoveredFrom }),
          },
          entryDigest: entryDigestOf(entry),
          authMode: entry.authMode,
          repairModel: entry.profile.repairModel === "inherit" ? entry.profile.model : entry.profile.repairModel,
          approved: { chainDigest: chainDigestOf(chain), profile: mirror },
          route: { routeDigest: routeDigestOf(sealed.route), phase: "build", provider: entry.profile.provider, model: entry.profile.model, chosen: "fallback" },
        },
        now,
      );
      if (!admitted.ok) {
        if (admitted.reason === "refused") throw new Error(admitted.problem);
        return { ok: false as const, reason: "raced" as const };
      }
      return { ok: true as const, runId: admitted.runId, taskId, provider: entry.profile.provider, model: entry.profile.model };
    });
  }

  /**
   * The PRE-SPAWN custody proof (Codex E3d review, finding 3): the LAST
   * gate before a chain-bound run's provider process starts, coupled to the
   * start stamp in ONE transaction so nothing can lapse between the proof
   * and the money. Re-derives, from durable state only: the approved chain
   * still stands (freshness + digest); the run's cycle is live and OPEN
   * with THIS run as tail at THIS run's index; the entry digest and pinned
   * auth mode still match; and — for any entry past the base — the LIVE
   * signed mode still grants the paid fallback (a base entry is the
   * ordinary approved work and needs no grant). Only when every fact stands
   * is provider_started_at stamped (first-write, with the version when the
   * gateway proved one). Returns false — and stamps NOTHING — otherwise.
   */
  proveChainCustodyForSpawn(runId: number, now: Date, providerVersion?: string): boolean {
    return this.transact(() => {
      const run = this.getRun(runId);
      if (run === null || run.chainCycle == null || run.outcome !== null) return false;
      const owner = this.db
        .prepare("SELECT external_id, repo FROM task_ref WHERE id = ? AND backend = ?")
        .get(run.taskRef, BUILT_IN);
      if (owner === undefined) return false;
      const taskId = String((owner as Record<string, unknown>)["external_id"]);
      const repo = (owner as Record<string, unknown>)["repo"] as string | null;
      const chain = this.approvedChainOf(taskId);
      if (chain === null) return false;
      const cycle = this.fallbackCycleFor(run.taskRef);
      // The custody holder is normally the run itself — but a bounded
      // REPAIR turn spends under its PARENT'S custody (verify round, R2):
      // the parent is still the cycle's open tail while its own attempt
      // mends, and it vouches for exactly its child. Anything else refuses.
      const tailHolds =
        cycle !== null &&
        (cycle.tailRun === runId ||
          (run.role === "repair" && run.parentRun !== null && cycle.tailRun === run.parentRun));
      if (
        cycle === null ||
        cycle.id !== run.chainCycle ||
        cycle.state !== "open" ||
        cycle.cursor !== run.chainIndex ||
        !tailHolds ||
        cycle.chainDigest !== chainDigestOf(chain)
      ) {
        return false;
      }
      const entry = chain[run.chainIndex ?? -1];
      if (entry === undefined || entryDigestOf(entry) !== run.entryDigest || entry.authMode !== run.authMode) {
        return false;
      }
      if ((run.chainIndex ?? 0) > 0) {
        const liveGrant =
          repo !== null && modeTermsFromJson(this.activeMode(repo, now)?.termsJson ?? null)?.allowPaidFallback === true;
        if (!liveGrant) return false;
      }
      if (providerVersion !== undefined) {
        this.db
          .prepare("UPDATE run SET provider_started_at = COALESCE(provider_started_at, ?), provider_version = ? WHERE id = ?")
          .run(now.toISOString(), providerVersion, runId);
      } else {
        this.db
          .prepare("UPDATE run SET provider_started_at = COALESCE(provider_started_at, ?) WHERE id = ?")
          .run(now.toISOString(), runId);
      }
      return true;
    });
  }

  /**
   * open -> sanitizing (C7): a recognized ELIGIBLE exhaustion of the tail
   * run begins the sanitizer. CAS proves exact state, generation, and tail
   * run; a stale caller loses. Marks the cycle sanitizing so ordinary
   * admission is blocked even if the claim later expires.
   */
  beginFallbackSanitize(cycleId: number, expectGeneration: number, tailRun: number, now: Date): boolean {
    return (
      Number(
        this.db
          .prepare(
            `UPDATE fallback_cycle SET state = 'sanitizing', transition_generation = transition_generation + 1, updated_at = ?
              WHERE id = ? AND state = 'open' AND transition_generation = ? AND tail_run = ?`,
          )
          .run(now.toISOString(), cycleId, expectGeneration, tailRun).changes,
      ) > 0
    );
  }

  /**
   * sanitizing -> awaiting-release (C2/C7): the durable one-step advance.
   * ONE transaction: prove the cycle is sanitizing at this generation and
   * cursor i with this tail run; insert the immutable transition (unique
   * per (cycle, from_index)); advance the cursor to i+1; bump generation.
   * The target index MUST be < chainLength (proven by the caller from the
   * approved snapshot). Returns the new transition id, or null on a lost
   * CAS or an already-recorded step.
   */
  advanceFallbackFenced(
    args: {
      cycleId: number;
      expectGeneration: number;
      fromIndex: number;
      chainLength: number;
      predecessorRun: number;
      terminalClass: string;
      evidence: { provider: string; version: string | null; authMode: string; fp: string };
    },
    now: Date,
  ): { ok: true; transitionId: number; toIndex: number } | { ok: false; reason: "raced" | "at-end" | "dup" } {
    if (args.fromIndex + 1 >= args.chainLength) return { ok: false as const, reason: "at-end" as const };
    // A SAVEPOINT (finding 4): a UNIQUE(cycle, from_index) conflict rolls
    // the cursor move back too, even inside an outer transaction a caller
    // might catch around — never a committed cursor without its transition.
    return this.savepoint(() => {
      // Prove the from-state (no move yet); the state cannot change under
      // us inside the savepoint's serialized transaction.
      const at = this.db
        .prepare("SELECT 1 AS hit FROM fallback_cycle WHERE id = ? AND state = 'sanitizing' AND transition_generation = ? AND cursor = ? AND tail_run = ?")
        .get(args.cycleId, args.expectGeneration, args.fromIndex, args.predecessorRun);
      if (at === undefined) return { ok: false as const, reason: "raced" as const };
      // Insert the transition FIRST: its UNIQUE(cycle, from_index) is the
      // double-advance guard, and on a dup NOTHING has moved yet.
      let transitionId: number;
      try {
        const inserted = this.db
          .prepare(
            `INSERT INTO fallback_transition (cycle, kind, from_index, to_index, predecessor_run, terminal_class, evidence_provider, evidence_version, evidence_auth_mode, evidence_fp, created_at)
             VALUES (?, 'exhaustion', ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            args.cycleId,
            args.fromIndex,
            args.fromIndex + 1,
            args.predecessorRun,
            args.terminalClass,
            args.evidence.provider,
            args.evidence.version,
            args.evidence.authMode,
            args.evidence.fp,
            now.toISOString(),
          );
        transitionId = Number(inserted.lastInsertRowid);
      } catch {
        return { ok: false as const, reason: "dup" as const };
      }
      // Only now move the cursor. If this CAS somehow fails, throw so the
      // savepoint rolls the inserted transition back too.
      const moved = this.db
        .prepare(
          `UPDATE fallback_cycle SET state = 'awaiting-release', cursor = cursor + 1, transition_generation = transition_generation + 1, updated_at = ?
            WHERE id = ? AND state = 'sanitizing' AND transition_generation = ? AND cursor = ? AND tail_run = ?`,
        )
        .run(now.toISOString(), args.cycleId, args.expectGeneration, args.fromIndex, args.predecessorRun);
      if (Number(moved.changes) === 0) throw new Error("fallback advance raced its own from-state");
      return { ok: true as const, transitionId, toIndex: args.fromIndex + 1 };
    });
  }

  /** awaiting-release -> pending-admission (C7): the epoch-fenced custody
   * release completed; the next entry is now admittable. */
  releaseFallbackToPending(cycleId: number, expectGeneration: number, now: Date): boolean {
    return (
      Number(
        this.db
          .prepare(
            `UPDATE fallback_cycle SET state = 'pending-admission', tail_run = NULL, transition_generation = transition_generation + 1, updated_at = ?
              WHERE id = ? AND state = 'awaiting-release' AND transition_generation = ?`,
          )
          .run(now.toISOString(), cycleId, expectGeneration).changes,
      ) > 0
    );
  }

  /**
   * pending-admission -> open at the new index (C3): the SINGLE-USE
   * admission. ONE transaction: prove pending at this generation, consume
   * the transition (consumed_by set once — a replay finds it consumed and
   * loses), and open the cycle at the new tail. Returns false on a lost
   * CAS or an already-consumed transition.
   */
  /**
   * THE FALLBACK ADMISSION (E3d; the ONE insert path for `fallback`
   * provenance since the v48 integrity repair). Every run bound to a
   * NON-primary entry of the approved chain — the entry's own admission
   * from a pending edge, a parked tail's successor, a repair turn under
   * the live tail — is created here and nowhere else; the generic
   * admission refuses `fallback` outright.
   *
   * EVERYTHING the caller states is re-proved against durable state
   * before any row exists, and one disagreement creates no run and
   * consumes no edge: the cycle is the task's own and live; the approved
   * chain still stands, is the cycle's, and its base entry is mirrored by
   * the sealed profile exactly as the caller presents it; the cursor,
   * the tail, the entry digest, the auth mode, the provider, the EXACT
   * model (required, never defaulted), and the repair binding all equal
   * the approved entry at the cursor; the presented stamp is `fallback`
   * on exactly that entry for the phase this run spends as; and the
   * kind-specific custody fact holds — an unconsumed pending edge at the
   * cursor, a parked tail the cycle still names, or a live parent tail.
   * The run is opened WITH its chain metadata (cycle, index, entry
   * digest, auth mode) and its route in one body, so nothing downstream
   * can substitute a foreign run.
   */
  admitFallback(
    args: {
      run: {
        taskRef: number;
        leaseId: string;
        runner: string;
        branch: string;
        worktree: string;
        provider: string;
        model: string;
        sessionId?: string;
        /** The interrupted attempt whose draft this entry or resume
         * recovers (raw authority repair): proved this task's own run and
         * written as the row's parent in this same insert — never stamped
         * later. A repair turn's parent is its live tail; it recovers none. */
        recoveredFrom?: number;
      };
      cycleId: number;
      /** The cursor the caller understands the cycle to stand at — the
       * entry index this run binds to. */
      expectCursor: number;
      /** The cycle's tail as the caller understands it: null for an entry
       * admitted from a pending edge, the parked run for a resume, the
       * live parent for a repair turn. */
      expectTail: number | null;
      entryDigest: string;
      authMode: "subscription" | "api-key";
      /** The entry's effective repair model as the caller understands it —
       * `inherit` resolved to the build model — proved against the approved
       * entry so a repair turn later spends as exactly what was approved. */
      repairModel: string;
      /** The approved authority as the caller holds it: the chain's digest
       * and the FULL sealed-profile mirror (the chain's base entry). */
      approved: { chainDigest: string; profile: ExecutionProfile };
      /** The run's `fallback` route provenance, proved against the exact
       * entry this admission binds (cursor + entry digest) BEFORE the row
       * exists and written beside it. Required: nothing is dictated here. */
      route: RouteStamp;
    } & (
      | { kind: "entry"; expectGeneration: number; transitionId: number }
      | { kind: "resume"; parkedRun: number }
      | { kind: "repair"; parentRun: number }
    ),
    now: Date,
  ): { ok: true; runId: number } | { ok: false; reason: "refused" | "raced"; problem: string } {
    // The savepoint rides inside a (reentrant) transaction so the route
    // write nests instead of colliding with it; every refusal below
    // happens BEFORE any write, so nothing is ever rolled back partially.
    return this.transact(() => this.savepoint(() => {
      const refuse = (problem: string): { ok: false; reason: "refused"; problem: string } => ({ ok: false as const, reason: "refused" as const, problem: `fallback admission refused for task_ref ${args.run.taskRef}: ${problem}` });
      const role: "builder" | "repair" = args.kind === "repair" ? "repair" : "builder";
      const cycleRow = this.db.prepare("SELECT * FROM fallback_cycle WHERE id = ?").get(args.cycleId) as Record<string, unknown> | undefined;
      if (cycleRow === undefined) return refuse(`no fallback cycle ${args.cycleId} exists`);
      const cycle = readFallbackCycle(cycleRow);
      // The exact task: the cycle's own owner, never the caller's word.
      if (cycle.taskRef !== args.run.taskRef) return refuse(`cycle ${args.cycleId} belongs to task_ref ${cycle.taskRef}, not ${args.run.taskRef}`);
      const owner = this.refForId(args.run.taskRef);
      if (owner === null) return refuse("no such task");
      const live = this.fallbackCycleFor(args.run.taskRef);
      if (live === null || live.id !== cycle.id) return refuse(`cycle ${args.cycleId} is not this task's live fallback cycle`);
      const chain = this.approvedChainOf(owner.externalId);
      if (chain === null) return refuse("the chain approval no longer stands (or its sealed profile mirror does not verify) — nothing is admitted under it");
      const chainDigest = chainDigestOf(chain);
      if (chainDigest !== args.approved.chainDigest) return refuse(`the caller holds chain ${args.approved.chainDigest}, but the approved chain is ${chainDigest}`);
      if (chainDigest !== cycle.chainDigest) return refuse(`the live cycle was opened under chain ${cycle.chainDigest}, but the approved chain is ${chainDigest}`);
      const scope = this.getScope(owner.externalId);
      const base = chain[0];
      const mirror = scope?.approvedProfile ?? null;
      if (base === undefined || mirror === null || profileDigestOf(mirror) !== profileDigestOf(base.profile)) return refuse("the approval's sealed profile does not mirror the chain's base entry");
      // ONE sealed authority (raw authority repair): the raw profile
      // mirror, the chain, and the route must verify together as the
      // sealed route — a chain approval with no sealed route (pre-routing),
      // or whose route's build and repair legs are not the sealed
      // profile's exact pairs, admits nothing. There is no chain-only
      // route digest to fall back to.
      const sealed = this.sealedRouteOf(owner.externalId);
      if (!sealed.ok) return refuse(`the chain approval's sealed agent route does not stand (${sealed.detail}) — nothing spends as a fallback under a chain-only digest`);
      if (profileDigestOf(args.approved.profile) !== profileDigestOf(mirror)) return refuse(`the caller's sealed-profile mirror (${args.approved.profile.provider} · ${args.approved.profile.model}) is not the approval's (${mirror.provider} · ${mirror.model})`);
      if (cycle.cursor !== args.expectCursor) return refuse(`the cycle stands at entry ${cycle.cursor}, not ${args.expectCursor}`);
      if (cycle.tailRun !== args.expectTail) return refuse(`the cycle's tail is ${cycle.tailRun ?? "none"}, not ${args.expectTail ?? "none"}`);
      const entry = chain[args.expectCursor];
      if (entry === undefined) return refuse(`the approved chain has no entry ${args.expectCursor}`);
      if (args.expectCursor === 0) return refuse("entry 0 is the chain's primary — it is dispatched as the base, never admitted as a fallback");
      if (entryDigestOf(entry) !== args.entryDigest) return refuse(`the stated entry digest ${args.entryDigest} is not the approved entry ${args.expectCursor}'s ${entryDigestOf(entry)}`);
      if (entry.authMode !== args.authMode) return refuse(`the approved entry ${args.expectCursor} is pinned to ${entry.authMode}, not ${args.authMode}`);
      if (entry.profile.provider !== args.run.provider) return refuse(`the approved entry ${args.expectCursor} runs ${entry.profile.provider}, not ${args.run.provider}`);
      const entryRepairModel = entry.profile.repairModel === "inherit" ? entry.profile.model : entry.profile.repairModel;
      const spendsAs = role === "repair" ? entryRepairModel : entry.profile.model;
      if (typeof args.run.model !== "string" || args.run.model === "") return refuse("the caller names no exact model — nothing is defaulted here");
      if (args.run.model !== spendsAs) return refuse(`the approved entry ${args.expectCursor} ${role === "repair" ? "repairs" : "runs"} on ${entry.profile.provider} · ${spendsAs}, not ${args.run.provider} · ${args.run.model}`);
      if (entryRepairModel !== args.repairModel) return refuse(`the approved entry ${args.expectCursor} repairs on ${entry.profile.provider} · ${entryRepairModel}, not ${args.repairModel}`);
      // THE ADMISSION PROOF (v48, authority repair), before the row: the presented stamp
      // must be `fallback` on exactly the entry this admission binds, as
      // the pair the run will spend as. A stamp that cannot be proved
      // opens nothing.
      const bound = { index: args.expectCursor, entryDigest: args.entryDigest };
      const stamp: RouteStamp = args.route;
      if ((stamp as { chosen?: unknown }).chosen !== "fallback") return refuse(`an admitted fallback entry spends as \`fallback\`, not \`${String((stamp as { chosen?: unknown }).chosen)}\``);
      const problem = this.routeAdmissionProblem({ taskRef: args.run.taskRef, role, provider: args.run.provider, model: args.run.model, contestant: null, chain: bound }, stamp, now);
      if (problem !== null) return refuse(problem);
      // The kind-specific custody fact, proved before the row.
      let parentRun: number | null = null;
      if (args.run.recoveredFrom !== undefined) {
        if (args.kind === "repair") return refuse("a repair turn mends its live tail — it recovers no interrupted attempt");
        const recovered = this.getRun(args.run.recoveredFrom);
        if (recovered === null || recovered.taskRef !== args.run.taskRef) return refuse(`run #${args.run.recoveredFrom} is not one of this task's attempts — nothing recovers its draft`);
        // THE SAME RECOVERY GRANT the recovered-draft admission proves
        // (final authority closure): a same-task run is not authority by
        // itself — it must be this task's interrupted builder or repair
        // turn in this very workspace, and an open one only under a lease
        // nobody holds. A failed planner, a parked run, a live attempt, or
        // a foreign worktree recovers nothing, and the edge stays unconsumed.
        const grant = this.recoveryGrantProblem(recovered, { taskRef: args.run.taskRef, branch: args.run.branch, worktree: args.run.worktree }, now);
        if (grant !== null) return refuse(grant);
        parentRun = recovered.id;
      }
      if (args.kind === "entry") {
        if (args.expectTail !== null) return refuse("an entry admitted from a pending edge follows no tail — the cycle's tail is cleared by the advance");
        const edge = this.db
          .prepare(
            `SELECT 1 AS hit FROM fallback_transition t JOIN fallback_cycle c ON c.id = t.cycle
              WHERE t.id = ? AND t.cycle = ? AND t.consumed_by IS NULL AND t.to_index = c.cursor
                AND c.state = 'pending-admission' AND c.transition_generation = ? AND c.cursor = ?`,
          )
          .get(args.transitionId, args.cycleId, args.expectGeneration, args.expectCursor);
        if (edge === undefined) return { ok: false as const, reason: "raced" as const, problem: `fallback admission refused for task_ref ${args.run.taskRef}: no unconsumed pending edge ${args.transitionId} stands at entry ${args.expectCursor} of cycle ${args.cycleId} at generation ${args.expectGeneration}` };
      } else {
        if (cycle.state !== "open") return refuse(`the cycle is ${cycle.state}, not open — nothing continues its tail`);
        const holder = this.getRun(args.kind === "resume" ? args.parkedRun : args.parentRun);
        const word = args.kind === "resume" ? "parked tail" : "repair parent";
        if (holder === null || holder.taskRef !== args.run.taskRef) return refuse(`the ${word} is not one of this task's runs`);
        if (args.kind === "resume" && holder.outcome !== "parked") return refuse(`run #${holder.id} did not park — nothing resumes it`);
        if (args.kind === "repair" && holder.outcome !== null) return refuse(`run #${holder.id} has ended — a repair turn mends a live attempt only`);
        if (holder.id !== args.expectTail) return refuse(`the ${word} #${holder.id} is not the tail the caller names (${args.expectTail ?? "none"})`);
        if (holder.chainCycle !== cycle.id || holder.chainIndex !== args.expectCursor || holder.entryDigest !== args.entryDigest || holder.authMode !== args.authMode) {
          return refuse(`run #${holder.id} is not bound to entry ${args.expectCursor} of cycle ${cycle.id} under digest ${args.entryDigest} (${args.authMode})`);
        }
        if (args.kind === "repair") {
          // THE ONE REPAIR RULE (final authority closure), the same words
          // admitRepair refuses in: a fallback entry's repair turn mends
          // its live tail under the tail's own runner and lease, and that
          // lease must be the task's CURRENT live claim — an attempt whose
          // claim was released, expired, or superseded is one nobody is
          // building, and copying its identity proves nothing.
          if (holder.runner !== args.run.runner) return refuse(`run #${holder.id} runs on ${holder.runner} — its repair turn on ${args.run.runner} is another machine's`);
          if (holder.leaseId !== args.run.leaseId) return refuse(`run #${holder.id} holds lease ${holder.leaseId} — a repair turn under lease ${args.run.leaseId} is not its own`);
          const holding = this.currentLiveLease(args.run.taskRef, now);
          if (holding !== holder.leaseId) {
            return refuse(`run #${holder.id}'s lease ${holder.leaseId} is not this task's current live claim (${holding === null ? "nothing holds it" : `${holding} does`}) — a repair turn mends an attempt still being built under its claim`);
          }
          parentRun = holder.id;
        }
      }
      // THE CURRENT CLAIM, for every kind (final admission closure): the
      // entry, the resume, and the repair turn alike open only under the
      // lease that holds the task now, on the runner that claim names —
      // proved here, before the row, so a mismatched, expired, released,
      // or superseded claim creates no run and consumes no edge.
      const custody = this.custodyClaimProblem(args.run, now, `a fallback ${args.kind === "repair" ? "repair turn" : args.kind === "resume" ? "resume" : "entry"}`);
      if (custody !== null) return refuse(custody);
      // Open the fallback run WITH its chain metadata, in the same body.
      const inserted = this.db
        .prepare(
          `INSERT INTO run (task_ref, lease_id, runner, branch, worktree, model, role, provider, parent_run, session_id, chain_cycle, chain_index, entry_digest, auth_mode, started_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          args.run.taskRef,
          args.run.leaseId,
          args.run.runner,
          args.run.branch,
          args.run.worktree,
          args.run.model,
          role,
          args.run.provider,
          parentRun,
          args.run.sessionId ?? null,
          args.cycleId,
          args.expectCursor,
          args.entryDigest,
          args.authMode,
          now.toISOString(),
        );
      const runId = Number(inserted.lastInsertRowid);
      this.writeRunRoute(runId, stamp, now);
      if (args.kind === "entry") {
        // Consume the edge with the real run id — the WHERE re-proves it is
        // still the unconsumed edge at the current cursor (single-use).
        const consumed = this.db
          .prepare(
            `UPDATE fallback_transition SET consumed_by = ?
              WHERE id = ? AND cycle = ? AND consumed_by IS NULL
                AND to_index = (SELECT cursor FROM fallback_cycle WHERE id = ?)`,
          )
          .run(runId, args.transitionId, args.cycleId, args.cycleId);
        if (Number(consumed.changes) === 0) throw new Error("the fallback edge was consumed under us");
        const moved = this.db
          .prepare(
            `UPDATE fallback_cycle SET state = 'open', tail_run = ?, transition_generation = transition_generation + 1, updated_at = ?
              WHERE id = ? AND state = 'pending-admission' AND transition_generation = ? AND cursor = ?`,
          )
          .run(runId, now.toISOString(), args.cycleId, args.expectGeneration, args.expectCursor);
        if (Number(moved.changes) === 0) throw new Error("admission raced the cycle state");
      } else if (args.kind === "resume") {
        // The parked-resume transfer: the tail moves to the successor
        // through a CAS on the very tail proved above.
        const moved = this.db
          .prepare("UPDATE fallback_cycle SET tail_run = ?, updated_at = ? WHERE id = ? AND state = 'open' AND tail_run = ?")
          .run(runId, now.toISOString(), args.cycleId, args.parkedRun);
        if (Number(moved.changes) === 0) throw new Error("the parked tail moved under us");
      }
      // A repair turn spends under its parent's custody: the parent stays
      // the tail, and the pre-spawn proof vouches for exactly its child.
      return { ok: true as const, runId };
    }));
  }

  /**
   * THE UNAVAILABLE-PRIMARY TRANSITION (v47): the approved chain's base
   * entry runs a provider THIS runner has reported unavailable, so the
   * task moves — before any claim, run, or spend — to the EXPLICITLY
   * APPROVED next entry, and only that one: a fresh cycle opens at index 0
   * with no tail and skips, one step, to pending-admission at index 1,
   * citing the readiness observation as its evidence. The admission pass
   * then re-proves everything (approved chain standing, live paid-fallback
   * grant, the next entry's own readiness) before it runs. Every other
   * case fails closed with the words: no approved chain, a live cycle
   * already, a base that is not actually unavailable, no next entry, a
   * next entry that is unavailable too, or no live grant — nothing
   * substitutes outside the approved chain.
   */
  skipUnavailablePrimary(
    taskRef: number,
    taskId: string,
    repo: string | null,
    runner: string,
    now: Date,
  ):
    | { ok: true; cycleId: number; toIndex: number; next: { provider: string; model: string } }
    | { ok: false; reason: "no-chain" | "cycle-live" | "primary-available" | "at-end" | "next-unavailable" | "grant-withheld" | "raced"; detail: string } {
    return this.transact(() => {
      const chain = this.approvedChainOf(taskId);
      if (chain === null) return { ok: false as const, reason: "no-chain" as const, detail: "no approved fallback chain stands for this task — nothing substitutes" };
      if (this.fallbackCycleFor(taskRef) !== null) return { ok: false as const, reason: "cycle-live" as const, detail: "a fallback cycle is already live for this task" };
      const primary = chain[0];
      if (primary === undefined) return { ok: false as const, reason: "no-chain" as const, detail: "the approved chain is empty" };
      const seen = this.runnerReadinessOf(runner, primary.profile.provider);
      if (seen === null || seen.state !== "unavailable") return { ok: false as const, reason: "primary-available" as const, detail: `${primary.profile.provider} is not reported unavailable on ${runner}` };
      const next = chain[1];
      if (next === undefined) return { ok: false as const, reason: "at-end" as const, detail: `the approved chain names no entry after ${primary.profile.provider} · ${primary.profile.model} — nothing substitutes` };
      const nextSeen = this.runnerReadinessOf(runner, next.profile.provider);
      if (nextSeen !== null && nextSeen.state === "unavailable") {
        return { ok: false as const, reason: "next-unavailable" as const, detail: `the approved fallback ${next.profile.provider} · ${next.profile.model} is also reported unavailable on ${runner} (${nextSeen.reason}) — nothing substitutes` };
      }
      const liveGrant = repo === null ? false : modeTermsFromJson(this.activeMode(repo, now)?.termsJson ?? null)?.allowPaidFallback === true;
      if (!liveGrant) return { ok: false as const, reason: "grant-withheld" as const, detail: `the approved fallback ${next.profile.provider} · ${next.profile.model} needs a live operating mode that allows paid fallback — none stands` };
      const inserted = this.db
        .prepare(
          `INSERT INTO fallback_cycle (task_ref, chain_digest, cursor, state, transition_generation, tail_run, created_at, updated_at)
           VALUES (?, ?, 0, 'open', 0, NULL, ?, ?)`,
        )
        .run(taskRef, chainDigestOf(chain), now.toISOString(), now.toISOString());
      const cycleId = Number(inserted.lastInsertRowid);
      const skipped = this.quotaSkipFallback(
        { cycleId, expectGeneration: 0, fromIndex: 0, chainLength: chain.length, tailRun: null, evidence: { provider: primary.profile.provider, fp: `readiness:${runner}:${seen.observedAt}:${seen.reason}` } },
        now,
      );
      if (!skipped.ok) return { ok: false as const, reason: "raced" as const, detail: `the fallback transition lost its race (${skipped.reason})` };
      this.bumpWake();
      return { ok: true as const, cycleId, toIndex: skipped.toIndex, next: { provider: next.profile.provider, model: next.profile.model } };
    });
  }

  /** open -> open at i+1 via a quota-skip (C7): index 0 (or any) already
   * durably exhausted before dispatch is skipped, one step, recorded. */
  quotaSkipFallback(
    args: { cycleId: number; expectGeneration: number; fromIndex: number; chainLength: number; tailRun: number | null; evidence?: { provider: string; fp: string } },
    now: Date,
  ): { ok: true; toIndex: number; transitionId: number } | { ok: false; reason: "raced" | "at-end" | "dup" } {
    if (args.fromIndex + 1 >= args.chainLength) return { ok: false as const, reason: "at-end" as const };
    return this.savepoint(() => {
      const at = this.db
        .prepare("SELECT 1 AS hit FROM fallback_cycle WHERE id = ? AND state = 'open' AND transition_generation = ? AND cursor = ?")
        .get(args.cycleId, args.expectGeneration, args.fromIndex);
      if (at === undefined) return { ok: false as const, reason: "raced" as const };
      // Insert FIRST (the UNIQUE(cycle, from_index) guard); on a dup nothing
      // moved. Nothing RAN at this index, so we go STRAIGHT to
      // pending-admission with the tail cleared — admission is the ONE road
      // that installs the next tail (Codex E1 review, finding 3).
      let transitionId: number;
      try {
        const inserted = this.db
          .prepare("INSERT INTO fallback_transition (cycle, kind, from_index, to_index, predecessor_run, evidence_provider, evidence_fp, created_at) VALUES (?, 'quota-skip', ?, ?, ?, ?, ?, ?)")
          .run(args.cycleId, args.fromIndex, args.fromIndex + 1, args.tailRun, args.evidence?.provider ?? null, args.evidence?.fp ?? null, now.toISOString());
        transitionId = Number(inserted.lastInsertRowid);
      } catch {
        return { ok: false as const, reason: "dup" as const };
      }
      const moved = this.db
        .prepare(
          `UPDATE fallback_cycle SET state = 'pending-admission', tail_run = NULL, cursor = cursor + 1, transition_generation = transition_generation + 1, updated_at = ?
            WHERE id = ? AND state = 'open' AND transition_generation = ? AND cursor = ?`,
        )
        .run(now.toISOString(), args.cycleId, args.expectGeneration, args.fromIndex);
      if (Number(moved.changes) === 0) throw new Error("quota-skip raced its own from-state");
      return { ok: true as const, toIndex: args.fromIndex + 1, transitionId };
    });
  }

  /** Any nonterminal state -> incident (C8): a sanitizer failure, a
   * severed grant, or a policy downgrade pages a human; never silent. */
  /** Any nonterminal -> incident (C8): CAS on the exact generation so a
   * STALE observer cannot terminate a cycle that has since advanced
   * (Codex E1 review, finding 1). */
  incidentFallback(cycleId: number, expectGeneration: number, reason: string, now: Date): boolean {
    return (
      Number(
        this.db
          .prepare(
            "UPDATE fallback_cycle SET state = 'incident', closed_reason = ?, transition_generation = transition_generation + 1, updated_at = ? WHERE id = ? AND state NOT IN ('closed','incident') AND transition_generation = ?",
          )
          .run(reason, now.toISOString(), cycleId, expectGeneration).changes,
      ) > 0
    );
  }

  /** A cycle succeeds or exhausts its chain: closed, terminally — CAS on
   * the exact generation (finding 1: a stale success observer cannot close
   * after an advance + admit). */
  closeFallbackCycle(cycleId: number, expectGeneration: number, reason: string, now: Date): boolean {
    return (
      Number(
        this.db
          .prepare("UPDATE fallback_cycle SET state = 'closed', closed_reason = ?, transition_generation = transition_generation + 1, updated_at = ? WHERE id = ? AND state NOT IN ('closed','incident') AND transition_generation = ?")
          .run(reason, now.toISOString(), cycleId, expectGeneration).changes,
      ) > 0
    );
  }

  // ---- the reviewer role (v29) --------------------------------------------

  /**
   * The bounded review-retry projection (v50): one source run's ROOT
   * reviewer attempts in ordinal order, its open request, and the ONE
   * state they add up to — the same facts requestReview and admitReview
   * decide on inside their transactions, read here for the CLI, the
   * dispatch diagnosis, and the console. A root attempt is a reviewer run
   * carrying `review_attempt`; correction children never count. Null for
   * a run that does not exist or is itself a review.
   */
  reviewRetryStateOf(sourceRunId: number): ReviewRetryState | null {
    const source = this.getRun(sourceRunId);
    if (source === null || source.role === "reviewer") return null;
    const attempts = this.db
      .prepare(
        `SELECT run.id, run.review_attempt AS attempt, run.outcome, run.reason, run.runner, run.provider, run.model,
                run.started_at, run.finished_at,
                (SELECT rr.id FROM review_request rr WHERE rr.reviewer_run = run.id ORDER BY rr.id LIMIT 1) AS request
           FROM run
          WHERE run.parent_run = ? AND run.role = 'reviewer' AND run.review_attempt IS NOT NULL
          ORDER BY run.review_attempt, run.id`,
      )
      .all(sourceRunId)
      .map(row => ({
        runId: Number(row["id"]),
        attempt: Number(row["attempt"]),
        outcome: (row["outcome"] === null ? null : String(row["outcome"])) as Run["outcome"],
        reason: row["reason"] === null ? null : String(row["reason"]),
        runner: String(row["runner"]),
        provider: String(row["provider"]),
        model: row["model"] === null ? null : String(row["model"]),
        startedAt: String(row["started_at"]),
        finishedAt: row["finished_at"] === null ? null : String(row["finished_at"]),
        requestId: row["request"] === null || row["request"] === undefined ? null : Number(row["request"]),
      }));
    const openRow = this.db
      .prepare("SELECT id, requested_by, basis, origin, requested_at FROM review_request WHERE run = ? AND consumed_at IS NULL ORDER BY id LIMIT 1")
      .get(sourceRunId) as Record<string, unknown> | undefined;
    const openRequest =
      openRow === undefined
        ? null
        : {
            id: Number(openRow["id"]),
            requestedBy: String(openRow["requested_by"]),
            basis: String(openRow["basis"]) as "human" | "mode",
            origin: reviewRequestOriginOf(openRow),
            requestedAt: String(openRow["requested_at"]),
          };
    const succeeded = attempts.find(one => one.outcome === "no-change") ?? null;
    const live = attempts.find(one => one.outcome === null) ?? null;
    const latest = attempts.length === 0 ? null : attempts[attempts.length - 1]!;
    const cap = REVIEW_ROOT_ATTEMPTS;
    const state: ReviewRetryState["state"] =
      succeeded !== null ? "succeeded"
        : live !== null ? "running"
          : openRequest !== null ? "queued"
            : attempts.length >= cap ? "exhausted"
              : latest !== null ? "retryable"
                : "unrequested";
    // Retries are attempts beyond the first: a queued request counts as
    // the attempt it will run; the very first ask is never a retry.
    const retriesRemaining = succeeded !== null || live !== null ? 0 : Math.max(0, cap - Math.max(1, attempts.length + (openRequest === null ? 0 : 1)));
    return {
      cap,
      attempts,
      openRequest,
      live,
      latest,
      succeeded,
      state,
      retriesUsed: Math.max(0, attempts.length - 1),
      retriesRemaining,
      nextAttempt: state === "queued" || state === "retryable" || state === "unrequested" ? attempts.length + 1 : null,
    };
  }

  /**
   * Why a source run admits no further ROOT reviewer right now (v50), in
   * the words requestReview and admitReview both refuse with — or null
   * when the next attempt may open. Decided inside the caller's
   * transaction against live rows: one successful review ends the
   * allowance forever, one open root is the only live attempt, and the
   * third root is the last. A live request is the caller's own check.
   */
  private rootReviewAdmissionProblem(sourceRunId: number): { reason: "already-reviewed" | "review-running" | "retries-exhausted"; detail: string } | null {
    const roots = this.db
      .prepare("SELECT id, outcome FROM run WHERE parent_run = ? AND role = 'reviewer' AND review_attempt IS NOT NULL ORDER BY review_attempt")
      .all(sourceRunId) as { id: number | bigint; outcome: string | null }[];
    const succeeded = roots.find(one => one.outcome === "no-change");
    if (succeeded !== undefined) return { reason: "already-reviewed", detail: `run #${sourceRunId} already has its review (reviewer run #${Number(succeeded.id)}) — a successful review is never retried` };
    const live = roots.find(one => one.outcome === null);
    if (live !== undefined) return { reason: "review-running", detail: `reviewer run #${Number(live.id)} is still open on run #${sourceRunId} — one review attempt at a time` };
    for (const root of roots) {
      const id = Number(root.id);
      const stop = this.stopOf(id);
      if (stop !== null && (stop.settledAt === null || this.stopQuiescenceProblem(id) !== null)) {
        return { reason: "review-running", detail: `reviewer run #${id} is still stopping; its processes must exit before another review can start` };
      }
    }
    if (roots.length >= REVIEW_ROOT_ATTEMPTS) return { reason: "retries-exhausted", detail: `run #${sourceRunId} has spent all ${REVIEW_ROOT_ATTEMPTS} review attempts — the failed attempts remain on record; nothing retries a fourth time` };
    return null;
  }

  /**
   * Ask for an agent review of one finished run's sealed diff. Manual
   * (`task review`, the task and result pages) and automatic (a mode whose
   * terms say reviewAuto) requests land through this ONE door, and every
   * refusal is decided transactionally against the same facts the pass
   * will re-prove: the diff must exist and be complete (a truncated
   * artifact is refused HERE, before any money), and the run's bounded
   * review allowance (v50) must still admit an attempt — no successful
   * review yet, no root still open, no request already queued, and fewer
   * than REVIEW_ROOT_ATTEMPTS roots so far. A second ask after a failed or
   * interrupted attempt IS the explicit retry. Signed service retries use
   * requestAutomaticReviewRetry and the same queue and admission rails.
   *
   * `origin` says how the ask was produced (explicit-only retries): an
   * 'operator' ask is a fresh credentialed act and may be the retry; an
   * 'automatic' ask — a mode-basis request always, and the Strict /
   * release producer by declaration — is one-shot per source run and
   * refuses 'explicit-only' the moment the run carries any root attempt
   * or any earlier request, so a replayed build disposition never queues
   * a retry.
   */
  requestReview(
    runId: number,
    by: string,
    now: Date,
    basis?: { kind: "mode"; digest: string },
    origin: ReviewRequestOrigin = basis === undefined ? "operator" : "automatic",
  ): ReturnType<Store["queueReviewRequest"]> {
    return this.queueReviewRequest(runId, by, now, basis, origin, false);
  }

  private queueReviewRequest(
    runId: number,
    by: string,
    now: Date,
    basis: { kind: "mode"; digest: string } | undefined,
    origin: ReviewRequestOrigin,
    signedRetry: boolean,
  ):
    | { ok: true; id: number; attempt: number }
    | {
        ok: false;
        reason:
          | "no-run"
          | "not-reviewable"
          | "unfinished"
          | "no-diff"
          | "diff-capture-failed"
          | "diff-truncated"
          | "already-reviewed"
          | "review-running"
          | "retries-exhausted"
          | "explicit-only"
          | "already-requested"
          | "route-unreadable"
          | "route-unapproved"
          | "review-leg-problem";
        detail?: string;
      } {
    const automatic = basis !== undefined || origin === "automatic";
    return this.transact(() => {
      const run = this.getRun(runId);
      if (run === null) return { ok: false as const, reason: "no-run" as const };
      // A review reviews work — never another review.
      if (run.role === "reviewer") return { ok: false as const, reason: "not-reviewable" as const };
      if (run.outcome === null) return { ok: false as const, reason: "unfinished" as const };
      const diff = this.artifactsFor(runId).find(one => one.kind === "terminal-diff");
      if (diff === undefined) return { ok: false as const, reason: "no-diff" as const };
      // A failed capture stores the failure's words AS the artifact —
      // reviewing an error message would spend the run's one review on
      // nothing (Codex reviewer round 1, finding 5a).
      if (diff.captureStatus !== "ok") return { ok: false as const, reason: "diff-capture-failed" as const };
      if (diff.truncated) return { ok: false as const, reason: "diff-truncated" as const };
      const allowance = this.rootReviewAdmissionProblem(runId);
      if (allowance !== null) return { ok: false as const, reason: allowance.reason, detail: allowance.detail };
      // THE ONE SHOT (explicit-only retries): an automatic producer queues
      // the first attempt and nothing after it — a source run that already
      // carries a root attempt, or any earlier ask at all, takes a retry
      // only from a fresh operator act.
      if (automatic && !signedRetry) {
        const replay = this.automaticReviewReplayProblem(runId);
        if (replay !== null) return { ok: false as const, reason: "explicit-only" as const, detail: replay };
      }
      // A request already queued refuses at the insert below (the open
      // request index is the backstop) — after the route is proved, as it
      // always was, so a routing problem is named before a duplicate ask.
      const attempt = this.nextRootReviewAttempt(runId);
      // v47: the request binds the task's SEALED route — admission re-proves
      // it and runs its exact review leg. A routed task whose approval does
      // not stand, whose route cannot be read, or whose review leg the
      // configuration cannot run is REFUSED here, in words, before any
      // request exists; only a row proven to predate routing queues with
      // no route and reviews on the legacy resolution.
      const owner = this.refForId(run.taskRef);
      const sealed = owner === null ? null : this.sealedRouteOf(owner.externalId);
      let routeDigest: string | null = null;
      if (sealed !== null && sealed.ok) {
        const leg = legOf(sealed.route, "review");
        if (leg.problem !== null) return { ok: false as const, reason: "review-leg-problem" as const, detail: leg.problem };
        routeDigest = routeDigestOf(sealed.route);
      } else if (sealed !== null && sealed.reason === "unreadable") {
        return { ok: false as const, reason: "route-unreadable" as const, detail: sealed.detail };
      } else if (sealed !== null && sealed.reason === "unapproved" && this.getScope(owner!.externalId)?.routeEra != null) {
        return { ok: false as const, reason: "route-unapproved" as const, detail: `${sealed.detail} — the approval seals which reviewer runs` };
      }
      const inserted = this.db
        .prepare(
          `INSERT INTO review_request (run, requested_by, basis, mode_digest, requested_at, route_digest, origin)
           SELECT ?, ?, ?, ?, ?, ?, ?
           WHERE NOT EXISTS (SELECT 1 FROM review_request WHERE run = ? AND consumed_at IS NULL)`,
        )
        .run(runId, by, basis === undefined ? "human" : "mode", basis === undefined ? null : basis.digest, now.toISOString(), routeDigest, automatic ? "automatic" : "operator", runId);
      if (Number(inserted.changes) === 0) return { ok: false as const, reason: "already-requested" as const };
      // The review-requested fact (Telegram task updates): the saved result
      // is what it was; an independent pass is queued, not run.
      const reviewedTask = this.externalIdFor(run.taskRef);
      if (reviewedTask !== null) {
        this.noteLifecycle(
          {
            taskRef: run.taskRef, run: runId, kind: "review-requested", identity: `r${runId}`,
            subject: "Independent review requested",
            body: `${automatic ? "Queued automatically" : `Requested by ${lifecycleWords(by, 40)}`} for attempt #${runId}'s saved result. A connected reviewer runs it next.`,
            link: chatResultHref(reviewedTask, runId, "checks"),
          },
          now,
        );
      }
      this.bumpWake();
      return { ok: true as const, id: Number(inserted.lastInsertRowid), attempt };
    });
  }

  /** The only producer of automatic retries. The signed mode adds no
   * attempts: this queues through the existing three-root review allowance. */
  requestAutomaticReviewRetry(sourceRunId: number, now: Date): ReturnType<Store["requestReview"]> {
    return this.transact(() => {
      const authority = this.automaticReviewRetryAuthority(sourceRunId, now);
      if (!authority.ok) return { ok: false as const, reason: "explicit-only" as const, detail: authority.detail };
      return this.queueReviewRequest(sourceRunId, authority.mode.signedBy, now, { kind: "mode", digest: authority.mode.digest }, "automatic", true);
    });
  }

  /** Recover a crash between recording a failed root and queueing its retry.
   * One durable keyset page per ordinary pass, wrapping after exhaustion;
   * one-shot workers reopening the store make the same bounded progress. */
  reconcileAutomaticReviewRetries(now: Date): void {
    this.transact(() => {
      // Page the request primary key BEFORE eligibility checks: even a ledger
      // full of successes/withdrawn requests reads at most fifty rows, rather
      // than scanning all history to find fifty eligible failures.
      const candidates = this.db.prepare("SELECT id, run AS source, reviewer_run FROM review_request WHERE id > ? ORDER BY id LIMIT 50").all(this.serviceCursor("review-retry-scan"));
      for (const candidate of candidates) {
        if (candidate["reviewer_run"] !== null) this.requestAutomaticReviewRetry(Number(candidate["source"]), now);
      }
      this.setServiceCursor("review-retry-scan", candidates.length < 50 ? 0 : Number(candidates[candidates.length - 1]!["id"]), now);
    });
  }

  /** Live permission and failure classification, re-proved at queue, admit,
   * and raw root insertion. An ordinary automatic producer cannot call this
   * exception through requestReview. A spent unrun request is not resurrected. */
  private automaticReviewRetryAuthority(sourceRunId: number, now: Date, ignoringRequest?: number):
    | { ok: true; mode: NonNullable<ReturnType<Store["activeMode"]>> }
    | { ok: false; detail: string } {
    const deny = (detail: string) => ({ ok: false as const, detail });
    const source = this.getRun(sourceRunId);
    if (source === null || source.role === "reviewer" || source.outcome === null) return deny("a retry needs a completed source run");
    const owner = this.refForId(source.taskRef);
    const scope = owner === null ? null : this.getScope(owner.externalId);
    if (owner?.repo == null || scope === null || scope.termsProblem != null || !approvalOf(scope).approved || source.scopeDigest !== scope.digest || !this.modeApprovalLive(source.taskRef, now)) {
      return deny("the completed source no longer holds its exact approved scope");
    }
    const scopeSigner = scope.approvedBy === null ? null : this.accountOf(scope.approvedBy);
    if (scopeSigner?.role !== "approver" || scopeSigner.revokedAt !== null || !this.accountCanAccess(scope.approvedBy!, owner.repo)) return deny("the scope approver no longer has access to this project");
    const sealed = this.sealedRouteOf(owner.externalId);
    if (!sealed.ok) return deny(`automatic retries need a current sealed route: ${sealed.detail}`);
    const mode = this.activeMode(owner.repo, now);
    const terms = mode === null ? null : modeTermsFromJson(mode.termsJson);
    if (mode === null || terms?.reviewAuto !== true || terms.reviewRetryAuto !== true || modeDigestOf(terms) !== mode.digest || terms.absoluteExpiry !== mode.absoluteExpiry || !this.accountCanAccess(mode.signedBy, owner.repo)) {
      return deny("no current signed mode permits automatic review retries");
    }
    const allowance = this.rootReviewAdmissionProblem(sourceRunId);
    if (allowance !== null) return deny(allowance.detail);
    const state = this.reviewRetryStateOf(sourceRunId);
    const latest = state?.latest;
    // Only recorded provider exits, timeouts, and initialization failures.
    // Unknown invocation/ingestion exceptions and every authority refusal
    // remain manual; a generic exception is not evidence of a transient fault.
    if (latest == null || latest.outcome !== "failed" || !["reviewer-agent", "reviewer-timeout", "reviewer-provider-init"].includes(latest.reason ?? "")) {
      return deny("only a failed review service attempt can retry automatically");
    }
    // Stops remain stops even after their processes have exited. Holds and
    // source proof integrity failures also require an operator decision.
    if (this.applicableStopFor(sourceRunId) !== null || this.applicableStopFor(latest.runId) !== null || this.activeHolds(source.taskRef, now).length > 0) return deny("this work was stopped or held by an operator");
    if (/custody|integrity|fenced|interrupted|stopped/.test(source.reason ?? "") || this.proofVerdictFor(sourceRunId)?.reasons.some(one => one.includes("was signed as") || one.includes("not in the sealed diff"))) return deny("the source has a custody or integrity failure");
    const previous = this.db.prepare("SELECT id FROM review_request WHERE run = ? AND id <> ? ORDER BY id DESC LIMIT 1").get(sourceRunId, ignoringRequest ?? -1);
    if (latest.requestId === null || Number(previous?.["id"]) !== latest.requestId) return deny("a later review request already handled this failure; a person must ask again");
    return { ok: true, mode };
  }

  /** The ordinal the next ROOT reviewer of a source run takes (v50): one
   * past the highest so far. The unique ordinal index backstops it. */
  private nextRootReviewAttempt(sourceRunId: number): number {
    const row = this.db
      .prepare("SELECT COALESCE(MAX(review_attempt), 0) AS last FROM run WHERE parent_run = ? AND role = 'reviewer' AND review_attempt IS NOT NULL")
      .get(sourceRunId) as { last: number | bigint } | undefined;
    return Number(row?.last ?? 0) + 1;
  }

  /**
   * Why an AUTOMATIC ask (a reviewAuto mode, a Strict / release scope) is
   * a replay rather than a source run's one shot (explicit-only retries),
   * in words — or null when it is the first ask. Decided inside the
   * caller's transaction against live rows, by requestReview before any
   * row exists and by admitReview/admitRun before any rail or run: a root
   * attempt already on record, or any earlier request at all, means the
   * producer has had its shot, and only a fresh operator act retries.
   */
  private automaticReviewReplayProblem(sourceRunId: number, ignoringRequest?: number): string | null {
    const root = this.db
      .prepare("SELECT id, outcome, reason, review_attempt AS attempt FROM run WHERE parent_run = ? AND role = 'reviewer' AND review_attempt IS NOT NULL ORDER BY review_attempt DESC LIMIT 1")
      .get(sourceRunId) as { id: number | bigint; outcome: string | null; reason: string | null; attempt: number | bigint } | undefined;
    if (root !== undefined) {
      const ended = root.outcome === null ? "is still open" : `ended ${root.reason ?? root.outcome}`;
      return `run #${sourceRunId}'s review attempt ${Number(root.attempt)} (reviewer run #${Number(root.id)}) ${ended} — an automatic review ask is one-shot, and a retry takes a fresh operator action: \`task review ${sourceRunId}\``;
    }
    const earlier = this.db
      .prepare("SELECT id, consumed_reason FROM review_request WHERE run = ? AND id <> ? ORDER BY id LIMIT 1")
      .get(sourceRunId, ignoringRequest ?? -1) as { id: number | bigint; consumed_reason: string | null } | undefined;
    if (earlier !== undefined) {
      return `run #${sourceRunId} already had its review ask (request #${Number(earlier.id)}${earlier.consumed_reason === null ? ", still queued" : `, spent as ${earlier.consumed_reason}`}) — an automatic review ask is one-shot; a person asks again with \`task review ${sourceRunId}\``;
    }
    return null;
  }

  /** The open review asks, oldest first, with the facts the pass needs. */
  openReviewRequests(): {
    id: number;
    run: number;
    requestedBy: string;
    basis: "human" | "mode";
    origin: ReviewRequestOrigin;
    modeDigest: string | null;
    requestedAt: string;
    taskRef: number;
    taskId: string;
    repo: string | null;
  }[] {
    return this.db
      .prepare(
        `SELECT rr.id, rr.run, rr.requested_by, rr.basis, rr.origin, rr.mode_digest, rr.requested_at,
                run.task_ref AS taskRef, task_ref.external_id AS taskId, task_ref.repo
           FROM review_request rr
           JOIN run ON run.id = rr.run
           JOIN task_ref ON task_ref.id = run.task_ref
          WHERE rr.consumed_at IS NULL
          ORDER BY rr.id`,
      )
      .all()
      .map(row => ({
        id: Number((row as Record<string, unknown>)["id"]),
        run: Number((row as Record<string, unknown>)["run"]),
        requestedBy: String((row as Record<string, unknown>)["requested_by"]),
        basis: String((row as Record<string, unknown>)["basis"]) as "human" | "mode",
        origin: reviewRequestOriginOf(row as Record<string, unknown>),
        modeDigest:
          (row as Record<string, unknown>)["mode_digest"] === null
            ? null
            : String((row as Record<string, unknown>)["mode_digest"]),
        requestedAt: String((row as Record<string, unknown>)["requested_at"]),
        taskRef: Number((row as Record<string, unknown>)["taskRef"]),
        taskId: String((row as Record<string, unknown>)["taskId"]),
        repo:
          (row as Record<string, unknown>)["repo"] === null
            ? null
            : String((row as Record<string, unknown>)["repo"]),
      }));
  }

  /** One attempt, whatever it came to (R4): the request is spent, never retried. */
  consumeReviewRequest(id: number, reason: string, now: Date): void {
    this.db
      .prepare("UPDATE review_request SET consumed_at = ?, consumed_reason = ? WHERE id = ? AND consumed_at IS NULL")
      .run(now.toISOString(), reason, id);
  }

  /** How the ledger's spent row learns what the attempt came to. */
  stampReviewRequestOutcome(id: number, reason: string): void {
    this.db.prepare("UPDATE review_request SET consumed_reason = ? WHERE id = ?").run(reason, id);
  }

  /**
   * The ADMISSION (Codex reviewer round 1, findings 4/5b/6): claim the
   * request, re-prove its authority, reserve the rail, and open the
   * reviewer run in ONE transaction — one winner under concurrent passes,
   * one rail reservation per actual start, and a crash after commit
   * leaves a spent request plus an outcome-NULL run row (a visible
   * cut-down attempt, the run table's own honesty) instead of an open
   * request no pass can ever consume.
   *
   * The mode re-proof is EXACT (R-REVOKE): the active mode's digest must
   * equal the digest the request was queued under — a renewal is a new
   * signature and inherits nothing; reviewAuto must still be among its
   * terms. A railed refusal leaves the request OPEN for a later pass.
   */
  admitReview(
    requestId: number,
    spec: { runner: string; token: string; provider: string; model: string | null; watchIncarnation?: string },
    now: Date,
  ):
    | { ok: true; reviewerRunId: number; sourceRun: number; taskRef: number; taskId: string; attempt: number }
    | { ok: false; reason: "gone" | "mode-ended" | "already-reviewed" | "review-running" | "retries-exhausted" | "explicit-only" | "railed" | "unauthenticated" | "route-changed" | "route-mismatch" | "provider-unavailable" | "watch-custody"; rail?: string; detail?: string } {
    return this.transact(() => {
      // The reviewer road authenticates INSIDE the admission transaction
      // (review finding 4): reviewer runs hold no task claim by design,
      // so this txn-time identity proof is what a takeover cannot ride —
      // a name alone is never authority.
      const identity = runnerAuthenticate(this, spec.runner, spec.token);
      if (!identity.ok) return { ok: false as const, reason: "unauthenticated" as const, detail: identity.reason };
      const row = this.db
        .prepare(
          `SELECT rr.run, rr.basis, rr.origin, rr.mode_digest, rr.route_digest,
                  run.task_ref AS taskRef, task_ref.external_id AS taskId, task_ref.repo
             FROM review_request rr
             JOIN run ON run.id = rr.run
             JOIN task_ref ON task_ref.id = run.task_ref
            WHERE rr.id = ? AND rr.consumed_at IS NULL`,
        )
        .get(requestId) as Record<string, unknown> | undefined;
      if (row === undefined) return { ok: false as const, reason: "gone" as const };
      const sourceRun = Number(row["run"]);
      const repo = row["repo"] === null ? null : String(row["repo"]);
      if (spec.watchIncarnation !== undefined && (repo === null || !this.db.prepare(
        "SELECT 1 FROM watch_lease WHERE runner = ? AND repo = ? AND owner = ? AND expires_at > ?",
      ).get(spec.runner, repo, spec.watchIncarnation, now.toISOString()))) {
        return { ok: false as const, reason: "watch-custody" as const, detail: "the watch no longer owns this repository; the review request remains pending" };
      }
      // v47: a request queued under a sealed route re-proves, INSIDE this
      // admission transaction, that the route is STILL the task's sealed
      // route (a rewritten-and-reapproved task spends the request unrun, in
      // words), rehydrates it, and requires the reviewer this pass supplies
      // to BE its review leg — the same provider and the exact, non-null
      // model — before any run row exists. A legacy request (no route
      // digest) admits only while the row is still a proven pre-routing
      // row. The provider must not be one this runner reports unavailable.
      let stamp: RouteStamp;
      if (row["route_digest"] !== null && row["route_digest"] !== undefined) {
        const sealedNow = this.sealedRouteOf(String(row["taskId"]));
        if (!sealedNow.ok || routeDigestOf(sealedNow.route) !== String(row["route_digest"])) {
          this.consumeReviewRequest(requestId, "route-changed", now);
          return { ok: false as const, reason: "route-changed" as const, detail: sealedNow.ok ? "the task was approved again under a different route" : sealedNow.detail };
        }
        const leg = legOf(sealedNow.route, "review");
        if (leg.problem !== null) {
          return { ok: false as const, reason: "route-mismatch" as const, detail: leg.problem };
        }
        if (spec.provider !== leg.provider || spec.model === null || spec.model !== leg.model) {
          return {
            ok: false as const,
            reason: "route-mismatch" as const,
            detail: `the approved route reviews on ${leg.provider} · ${leg.model}; this pass offered ${spec.provider}${spec.model === null ? " with no model" : ` · ${spec.model}`} — nothing substitutes`,
          };
        }
        stamp = { routeDigest: String(row["route_digest"]), phase: "review", provider: leg.provider, model: leg.model, chosen: leg.chosen };
      } else {
        const scope = this.getScope(String(row["taskId"]));
        if (scope !== null && scope.routeEra != null) {
          this.consumeReviewRequest(requestId, "route-changed", now);
          return { ok: false as const, reason: "route-changed" as const, detail: "the task has been re-filed under an agent route since this review was asked for — ask again" };
        }
        stamp = { routeDigest: scope?.approvedProfile == null ? "legacy" : `profile:${profileDigestOf(scope.approvedProfile)}`, phase: "review", provider: spec.provider, model: spec.model, chosen: "legacy" };
      }
      const readiness = this.runnerReadinessOf(spec.runner, spec.provider);
      if (readiness !== null && readiness.state === "unavailable") {
        return {
          ok: false as const,
          reason: "provider-unavailable" as const,
          detail: `${spec.provider} is reported unavailable on ${spec.runner} (${readiness.reason}; observed ${readiness.observedAt}) — nothing substitutes for the routed reviewer`,
        };
      }
      if (String(row["basis"]) === "mode") {
        const mode = repo === null ? null : this.activeMode(repo, now);
        let reviewAuto = false;
        if (mode !== null && mode.digest === String(row["mode_digest"] ?? "")) {
          try {
            reviewAuto = (JSON.parse(mode.termsJson) as { reviewAuto?: unknown }).reviewAuto === true;
          } catch {
            reviewAuto = false;
          }
        }
        if (!reviewAuto) {
          this.consumeReviewRequest(requestId, "mode-ended", now);
          return { ok: false as const, reason: "mode-ended" as const };
        }
      }
      // THE ALLOWANCE (v50): re-proved INSIDE this admission, against live
      // rows — a request queued while the door was open but overtaken by a
      // success, a still-open root, or the third attempt is spent unrun, in
      // words, and no fourth root ever opens. admitRun re-proves the same
      // facts in the insert; the four partial uniques backstop it.
      const allowance = this.rootReviewAdmissionProblem(sourceRun);
      if (allowance !== null) {
        this.consumeReviewRequest(requestId, allowance.reason, now);
        return { ok: false as const, reason: allowance.reason, detail: allowance.detail };
      }
      // An automatic replay is still one-shot unless this exact queued
      // request holds the new signed service-retry authority. Re-prove it
      // before reserving the rail or opening a run.
      if (reviewRequestOriginOf(row) === "automatic") {
        const replay = this.automaticReviewReplayProblem(sourceRun, requestId);
        const retry = replay === null ? null : this.automaticReviewRetryAuthority(sourceRun, now, requestId);
        if (retry !== null && (!retry.ok || String(row["basis"]) !== "mode" || retry.mode.digest !== row["mode_digest"])) {
          this.consumeReviewRequest(requestId, "explicit-only", now);
          return { ok: false as const, reason: "explicit-only" as const, detail: retry.ok ? "the retry names another mode signature" : retry.detail };
        }
      }
      if (repo !== null) {
        const railed = this.reserveModeRail(repo, 1, now);
        if (!railed.ok) return { ok: false as const, reason: "railed" as const, rail: railed.rail, detail: railed.detail };
      }
      // The authenticated incarnation may itself have been assigned one or
      // more logical milliseconds past this coarse/injected wall clock. Make
      // the admitted root no older than that incarnation: equality means
      // "this runner admitted this review"; the next atomic replacement is
      // forced strictly past both and therefore fences it.
      const registeredMs = Date.parse(identity.runner.registeredAt);
      const admittedAt = new Date(Math.max(now.getTime(), registeredMs));
      // The request is consumed INSIDE the run's own admission (raw
      // authority repair): the row that answers it spends it, or no row.
      const reviewerRunId = this.startRun({
        taskRef: Number(row["taskRef"]),
        leaseId: `review:${requestId}:${now.getTime().toString(36)}`,
        runner: spec.runner,
        role: "reviewer",
        parentRun: sourceRun,
        request: requestId,
        provider: spec.provider,
        ...(spec.model === null ? {} : { model: spec.model }),
        now: admittedAt,
        route: stamp,
      });
      if (spec.watchIncarnation !== undefined) {
        this.db.prepare("UPDATE run SET watch_incarnation = ? WHERE id = ?").run(spec.watchIncarnation, reviewerRunId);
      }
      return {
        ok: true as const,
        reviewerRunId,
        sourceRun,
        taskRef: Number(row["taskRef"]),
        taskId: String(row["taskId"]),
        attempt: this.getRun(reviewerRunId)?.reviewAttempt ?? 1,
      };
    });
  }

  /**
   * The reviewer's comments land through ONE proving transaction (D8):
   * the authoring run must BE the root reviewer or one of its at-most-two
   * same-session structured-output repair children, must share the source's
   * task/provider/model lineage, and the artifact must be the commented
   * run's own terminal diff. Anything else is an invariant breach — thrown,
   * nothing inserted — because a comment bound to bytes the reviewer never
   * saw is worse than no comment.
   */
  addReviewerComments(
    args: {
      reviewerRunId: number;
      runId: number;
      artifactId: number;
      author: string;
      comments: readonly { path: string; line: number | null; note: string; severity: "note" | "question" | "problem" }[];
    },
    now: Date,
  ): number[] {
    return this.transact(() => {
      const reviewer = this.getRun(args.reviewerRunId);
      if (reviewer === null || reviewer.role !== "reviewer") {
        throw new ReviewBindingError(`run ${args.reviewerRunId} is not a reviewer — only the reviewer role authors reviewer comments`);
      }
      if (!this.reviewerLineageReaches(args.reviewerRunId, args.runId)) {
        throw new ReviewBindingError(
          `reviewer ${args.reviewerRunId} reviews run outside the bounded lineage for ${args.runId} — comments bind to the run the review was minted for`,
        );
      }
      const source = this.getRun(args.runId);
      if (source === null || source.taskRef !== reviewer.taskRef) {
        throw new ReviewBindingError(`reviewer ${args.reviewerRunId} and run ${args.runId} do not share a task — nothing is ingested`);
      }
      const artifact = this.artifactsFor(args.runId).find(one => one.id === args.artifactId);
      if (artifact === undefined || artifact.kind !== "terminal-diff") {
        throw new ReviewBindingError(`artifact ${args.artifactId} is not run ${args.runId}'s terminal diff — comments bind to the exact bytes reviewed`);
      }
      const ids: number[] = [];
      for (const comment of args.comments) {
        const inserted = this.db
          .prepare(
            `INSERT INTO diff_comment (artifact, artifact_sha, run, path, line, note, author, created_at, reviewer_run, severity)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            args.artifactId,
            artifact.sha256,
            args.runId,
            comment.path,
            comment.line,
            comment.note,
            args.author,
            now.toISOString(),
            args.reviewerRunId,
            comment.severity,
          );
        ids.push(Number(inserted.lastInsertRowid));
      }
      return ids;
    });
  }

  /**
   * Prove an actual authoring reviewer is either the admitted root or one of
   * its two linear correction children. The database's one-child-per-parent
   * reviewer index prevents branching; this walk prevents an arbitrary or
   * unbounded reviewer chain from borrowing another run's sealed diff.
   */
  private reviewerLineageReaches(reviewerRunId: number, sourceRunId: number): boolean {
    const first = this.getRun(reviewerRunId);
    if (first === null || first.role !== "reviewer") return false;
    const root = this.reviewerRoot(first, true);
    if (root === null || root.parentRun !== sourceRunId) return false;
    const source = this.getRun(sourceRunId);
    return source !== null && source.role !== "reviewer" && source.taskRef === first.taskRef;
  }

  /** Find the admitted root behind a reviewer correction, proving the
   * bounded, same-task/provider/model chain on the way. The accepted leaf
   * and admitted root must still be open; every superseded correction
   * between them must already be terminal failed. That state sequence is
   * the durable proof this is one linear correction attempt, not several
   * simultaneously live authors whose eventual outputs could all ingest. */
  private reviewerRoot(first: Run, requireProviderStarted = false): Run | null {
    if (first.role !== "reviewer" || first.outcome !== null) return null;
    const provider = first.provider;
    const model = first.model;
    const taskRef = first.taskRef;
    const runner = first.runner;
    const leaseId = first.leaseId;
    if (requireProviderStarted && first.providerStartedAt === null) return null;
    let cursor = first;
    const lineage: Run[] = [first];
    let repairEdges = 0;
    while (cursor.parentRun !== null) {
      const parent = this.getRun(cursor.parentRun);
      if (parent === null) return null;
      if (parent.role !== "reviewer") {
        if (
          parent.taskRef !== taskRef ||
          cursor.outcome !== null ||
          (requireProviderStarted && cursor.providerStartedAt === null)
        ) return null;
        // `lineage` is leaf -> ... -> root. Exclude both endpoints: only
        // superseded correction attempts belong in this failed-state check.
        if (lineage.slice(1, -1).some(run => run.outcome !== "failed")) return null;
        return cursor;
      }
      repairEdges += 1;
      if (
        repairEdges > 2 ||
        parent.taskRef !== taskRef ||
        parent.provider !== provider ||
        parent.model !== model ||
        parent.runner !== runner ||
        cursor.runner !== runner ||
        parent.leaseId !== leaseId ||
        cursor.leaseId !== leaseId ||
        (requireProviderStarted && parent.providerStartedAt === null) ||
        cursor.sessionId === null ||
        parent.sessionId === null ||
        cursor.sessionId !== parent.sessionId
      ) return null;
      lineage.push(parent);
      cursor = parent;
    }
    return null;
  }

  /**
   * The lineage a revision task carries (v51, inherited review context):
   * the source task it revises and the exact source run its sealed brief
   * was written against — the brief artifact's own `run` column, the one
   * durable fact every revision road (annotation, CI repair, criterion
   * repair) writes. null for a task that is not a revision, or whose brief
   * artifact row is gone: lineage is read, never inferred from a title.
   */
  revisionSourceOf(taskRef: number): { sourceTask: string; sourceRun: number; briefArtifact: Artifact } | null {
    const ref = this.refForId(taskRef);
    if (ref === null || ref.revisionOf === null || ref.revisionBriefArtifact === null) return null;
    const briefArtifact = this.getArtifact(ref.revisionBriefArtifact);
    if (briefArtifact === null || briefArtifact.kind !== "revision-brief") return null;
    return { sourceTask: ref.revisionOf, sourceRun: briefArtifact.run, briefArtifact };
  }

  /** Stamp a task as the revision it is: source task + immutable brief. */
  markRevision(taskRef: number, revisionOf: string, briefArtifact: number): void {
    this.db
      .prepare("UPDATE task_ref SET revision_of = ?, revision_brief_artifact = ? WHERE id = ?")
      .run(revisionOf, briefArtifact, taskRef);
  }

  // ---- the revision boundary: ONE field-by-field policy -------------------

  /**
   * Seal a revision in ONE transaction (Codex M5-M8 audit, C-3; contract
   * handoff task 2): the SOURCE BINDING is proven here, against live rows,
   * before anything is created — the source task must exist, the source
   * run must be that task's own, the source scope's digest must still be
   * the one the caller read, the stored terms must read back exactly, and
   * the brief file the caller wrote must verify byte-for-byte AND name the
   * same source — then the child task is filed under the inherited terms
   * `revisionTermsOf` computes from the SOURCE ROWS (never from a caller's
   * copy), the brief's artifact row, the revision relation, and — when
   * comments are being consumed — exactly the expected batch, or the whole
   * seal rolls back, nested or not (a savepoint, so an enclosing
   * transaction can never commit half a seal). A brief FILE whose seal
   * failed is an orphan on disk, not authority — no artifact row points at
   * it. Two concurrent seals race on the comment consumption count, the
   * deterministic child id, or the repair chain's `source_run UNIQUE`, and
   * exactly one wins; the loser refuses in words with zero rows.
   *
   * The child is filed UNAPPROVED, always: this method never stamps an
   * approval, never mints an attended authorization, never touches a
   * publication or merge grant. Only the normal approval roads — the
   * password ceremony, or a live mode's own filing coverage re-proved by
   * the caller inside its own transaction — can approve the child.
   */
  sealRevision(
    args: {
      /** The exact source: task id, run id, and the scope digest the
       * caller READ (null = the caller saw no scope; proven still absent). */
      source: { task: string; run: number; scopeDigest: string | null };
      /** The brief the caller wrote to disk BEFORE this transaction — re-read
       * and re-hashed here, never trusted from the caller's numbers. */
      brief: { evidenceRoot: string; key: string; sha256: string; bytes: number; capture: string };
      /** The child's own words: an optional deterministic id, its title,
       * and the explicitly described repair appended to the SOURCE goal. */
      child: { id?: string; title: string; repair: string };
      /** Comments to consume, or null when the brief has no comment batch (CI / criterion repair). */
      commentIds: readonly number[] | null;
      /** v102: who asked for this revision (a person, an AI teammate's "Name (AI)", or none for machine repairs): its filer. */
      requestedBy?: string | null;
      /** Fresh mode filing coverage, re-proved by the caller INSIDE this
       * transaction (never carried across one): its budget default may only
       * TIGHTEN the inherited ceiling; its escalated posture may apply only when the source already
       * permits full access (or no source scope exists). */
      coverage?: { defaultBudgetMicrousd: number | null; escalated: boolean } | null;
    },
    now: Date,
  ): { ok: true; id: string; artifactId: number; terms: RevisionTerms } | { ok: false; reason: RevisionRefusal; detail: string } {
    const refuse = (reason: RevisionRefusal, detail: string): { ok: false; reason: RevisionRefusal; detail: string } => ({ ok: false, reason, detail });
    try {
      return this.transact(() =>
        this.savepoint(() => {
          // THE SOURCE BINDING, against live rows.
          const sourceRef = this.lookupRef(args.source.task);
          if (sourceRef === null) return refuse("source-task", `no such source task ${args.source.task}`);
          const sourceRun = this.getRun(args.source.run);
          if (sourceRun === null || sourceRun.taskRef !== sourceRef.id) {
            return refuse("source-run", `run #${args.source.run} is not an attempt of ${args.source.task} — a revision binds to its own source's run`);
          }
          const sourceScope = this.getScope(args.source.task);
          if ((sourceScope?.digest ?? null) !== args.source.scopeDigest) {
            return refuse(
              "stale-source",
              sourceScope === null
                ? `${args.source.task} has no scope now, but the brief was drafted against one — read it again`
                : `${args.source.task}'s scope changed while this revision was being drafted — read it again and draft against the current terms`,
            );
          }
          if (sourceScope !== null && sourceScope.termsProblem != null) {
            return refuse("source-terms", `${args.source.task}'s stored terms do not read back exactly (${sourceScope.termsProblem}) — nothing inherits from a row that is not authority`);
          }
          const sourceRunDigest = sourceRun.scopeDigest === "" ? null : sourceRun.scopeDigest;
          if (sourceRunDigest !== args.source.scopeDigest) {
            return refuse("stale-source", `run #${sourceRun.id} was built against different terms — a newer task scope cannot stand in for that run's contract`);
          }
          const ancestry = this.revisionAncestryStatus(args.source.task);
          if (ancestry.problem !== null) return refuse("source-terms", ancestry.problem);
          // THE BRIEF CUSTODY: the file, re-read and re-hashed under the
          // evidence root, must be the bytes the caller claims AND name
          // exactly this source. A brief for another run is a wrong brief.
          const custody = readVerifiedArtifact(args.brief.evidenceRoot, {
            id: 0,
            run: args.source.run,
            kind: "revision-brief",
            key: args.brief.key,
            bytesOriginal: args.brief.bytes,
            bytesStored: args.brief.bytes,
            truncated: false,
            sha256: args.brief.sha256,
            capture: args.brief.capture,
            createdAt: now.toISOString(),
            redacted: false,
            captureStatus: null,
          });
          if (!custody.ok) return refuse("brief-custody", `the revision brief does not verify — ${custody.problem}`);
          let named: { sourceTask?: unknown; sourceRun?: unknown; sourceScopeDigest?: unknown; head?: unknown; comments?: unknown };
          try {
            named = JSON.parse(custody.content.toString("utf8")) as typeof named;
          } catch {
            return refuse("brief-custody", "the revision brief is not JSON");
          }
          if (named === null || typeof named !== "object" || named.sourceTask !== args.source.task || named.sourceRun !== args.source.run) {
            return refuse("brief-custody", `the revision brief names ${String(named?.sourceTask ?? "?")} / run #${String(named?.sourceRun ?? "?")}, not ${args.source.task} / run #${args.source.run}`);
          }
          if (named.sourceScopeDigest !== sourceRunDigest || named.head !== sourceRun.headRevision) {
            return refuse("brief-custody", "the revision brief does not bind the source run's exact scope and head");
          }
          if (args.commentIds !== null) {
            const ids = new Set(args.commentIds);
            const live = this.liveDiffComments(sourceRun.id).filter(one => ids.has(one.id));
            if (ids.size !== args.commentIds.length || live.length !== ids.size) {
              throw new RevisionRaced("this annotation batch is no longer whole — read the current comments before sealing it");
            }
            const exactComment = (one: Record<string, unknown>) => ({ id: one["id"], path: one["path"], line: one["line"], note: one["note"], author: one["author"], createdAt: one["createdAt"] });
            const expected = live.map(one => exactComment({ ...one }));
            const described = Array.isArray(named.comments) && named.comments.every(one => one !== null && typeof one === "object" && !Array.isArray(one))
              ? named.comments.map(one => exactComment(one as Record<string, unknown>)) : null;
            if (JSON.stringify(described) !== JSON.stringify(expected)) {
              return refuse("brief-custody", "the revision brief does not contain the exact annotation batch being consumed");
            }
          }
          // THE TERMS, from the source rows this transaction just proved.
          const terms = revisionTermsOf(sourceRef, sourceScope, args.coverage ?? null, this.permissionDefault().mode, this.qualityDefault().mode);
          const goal = `${terms.fromScope ? terms.goal : `revise ${args.source.task}`} — ${args.child.repair}`;
          // Only the newly authored repair/title face new-request limits.
          // Inherited bytes came from the source rows proved above. This
          // runtime-private insert cannot be selected by a filing caller.
          const badText = validateTaskText({ title: args.child.title, goal: args.child.repair });
          if (badText !== null) return refuse(badText.reason, badText.message);
          const made = this.#insertConsoleTask(
            {
              ...(args.child.id === undefined ? {} : { id: args.child.id }),
              title: args.child.title,
              ...(sourceRef.repo === null ? {} : { repo: sourceRef.repo }),
              goal,
              outOfScope: terms.outOfScope,
              touches: terms.touches,
              acceptance: terms.acceptance,
              budgetMicrousd: terms.budgetMicrousd,
              permissionMode: terms.permissionMode,
              qualityMode: terms.qualityMode,
              riskLevel: terms.riskLevel,
              routeOverridesJson: terms.routeOverridesJson,
              agentPin: terms.agentPin,
              planPin: terms.planPin,
              ...(terms.escalated ? { posture: "escalated" as const } : {}),
              filedVia: "revision",
              filedBy: filerFor(args.requestedBy),
            },
            now,
          );
          if (!made.ok) return refuse(made.reason, `the revision task could not be filed: ${made.reason}`);
          const artifactId = this.saveArtifact(
            { run: args.source.run, kind: "revision-brief", key: args.brief.key, bytesOriginal: args.brief.bytes, bytesStored: args.brief.bytes, truncated: false, sha256: args.brief.sha256, capture: args.brief.capture },
            now,
          );
          const ref = this.lookupRef(made.id);
          if (ref === null) throw new Error("the task this transaction just created has no ref — impossible, roll back");
          this.markRevision(ref.id, args.source.task, artifactId);
          if (args.commentIds !== null) {
            const consumed = this.consumeDiffComments(args.source.run, args.commentIds, made.id);
            if (consumed !== args.commentIds.length) {
              throw new RevisionRaced("another seal took part of this batch — nothing is half-sealed, roll back");
            }
          }
          // THE NO-GRANT INVARIANT, proved on the way out: the child leaves
          // this seal unapproved — nothing above stamps an approval, mints
          // an authorization, or touches a grant, and a row that says
          // otherwise is a bug: the seal rolls back rather than mint
          // authority by accident.
          const filed = this.getScope(made.id);
          if (filed === null || filed.approvedAt !== null || filed.approvedDigest !== null) {
            throw new Error("a revision left its seal approved — impossible, roll back");
          }
          return { ok: true as const, id: made.id, artifactId, terms };
        }),
      );
    } catch (error) {
      if (error instanceof RevisionRaced) return refuse("comments-taken", error.message);
      const message = String((error as Error).message ?? error);
      if (/database (?:is )?locked|SQLITE_BUSY/.test(message)) return refuse("busy", "another writer holds the revision boundary; read the current source before retrying");
      if (/UNIQUE constraint failed/.test(message)) return refuse("duplicate", `another draft won this source run — ${message}`);
      return refuse("invariant", message);
    }
  }

  /**
   * Walk a task's revision ancestry — itself first, then `revision_of`
   * upward to the root — bounded and cycle-safe. Every projection of
   * lineage (task page, chat, approval, the repair loop) reads this walk,
   * never a caller's copy of it.
   */
  revisionAncestryStatus(taskId: string): { chain: string[]; problem: string | null } {
    const seen = new Set<string>();
    const chain: string[] = [];
    let cursor: string | null = taskId;
    while (cursor !== null) {
      if (seen.has(cursor)) return { chain, problem: `revision ancestry cycles at ${cursor}` };
      if (chain.length >= 64) return { chain, problem: "revision ancestry exceeds the 64-task verification bound" };
      const ref = this.lookupRef(cursor);
      if (ref === null) return { chain, problem: `revision ancestor ${cursor} is missing` };
      seen.add(cursor);
      chain.push(cursor);
      cursor = ref.revisionOf;
    }
    return { chain, problem: null };
  }

  revisionAncestryOf(taskId: string): string[] {
    return this.revisionAncestryStatus(taskId).chain;
  }

  /** Permission-aware metadata projection, shared by bounded lists and counts.
   * Walk only valid edges down from real roots. Missing, circular, foreign,
   * over-depth or borrowed-source chains never join another family's card.
   * The 64-version ancestry bound matches revisionAncestryStatus; it is NOT
   * a row cap: all siblings and all versions of selected families survive. */
  private taskFamilyProjection(admitted: readonly string[] | null, includeUnplaced: boolean) {
    return {
      params: [BUILT_IN, includeUnplaced ? 1 : 0, admitted === null ? 1 : 0, ...(admitted ?? [])],
      sql: `WITH RECURSIVE admitted AS MATERIALIZED (
        SELECT task_ref.id AS ref_id, task_ref.external_id AS id, task_ref.repo,
          task_ref.revision_of, task_ref.revision_brief_artifact,
          task.state, task.created_at, task.updated_at
        FROM task_ref JOIN task ON task.id = task_ref.external_id
        WHERE task_ref.backend = ? AND ((task_ref.repo IS NULL AND ? = 1)
          OR (task_ref.repo IS NOT NULL AND (? = 1 OR task_ref.repo IN (${(admitted ?? []).map(() => "?").join(",")}))))
      ), lineage(ref_id, root_ref, depth) AS (
        SELECT ref_id, ref_id, 0 FROM admitted WHERE revision_of IS NULL
        UNION ALL
        SELECT child.ref_id, lineage.root_ref, lineage.depth + 1
        FROM lineage JOIN admitted parent ON parent.ref_id = lineage.ref_id
        JOIN admitted child ON child.revision_of = parent.id AND child.repo IS parent.repo
        JOIN artifact brief ON brief.id = child.revision_brief_artifact AND brief.kind = 'revision-brief'
        JOIN run source_run ON source_run.id = brief.run AND source_run.task_ref = parent.ref_id
        WHERE lineage.depth < 63
      ), members AS MATERIALIZED (
        SELECT admitted.*, COALESCE(lineage.root_ref, admitted.ref_id) AS root_ref,
          lineage.ref_id IS NULL AS broken
        FROM admitted LEFT JOIN lineage ON lineage.ref_id = admitted.ref_id
      ), ordered AS MATERIALIZED (
        SELECT members.*, ROW_NUMBER() OVER (PARTITION BY root_ref
          ORDER BY (ref_id = root_ref), created_at DESC, ref_id DESC) AS version_rank
        FROM members
      )`,
    };
  }

  private taskFamilyFromRows(rows: Record<string, unknown>[]): TaskFamily {
    const versions = rows.map(row => ({ ...readTask(row), repo: row["repo"] === null ? null : String(row["repo"]), refId: Number(row["ref_id"]) }));
    const root = versions.find(one => one.refId === Number(rows[0]!["root_ref"]))!;
    versions.sort((a, b) => a.id === root.id ? -1 : b.id === root.id ? 1 : a.createdAt.localeCompare(b.createdAt) || a.refId - b.refId);
    const current = versions.at(-1)!;
    return { root, current, versions,
      otherActive: versions.filter(one => one.id !== current.id && (one.state === "queued" || one.state === "running")),
      problem: Number(rows[0]!["broken"]) === 0 ? null : "Task history is unavailable or incomplete. This task is shown separately." };
  }

  /** Group and filter BEFORE the family limit; hydrate only that page's
   * exact versions, never all tasks followed by a JavaScript slice. */
  taskFamiliesAdmitted(admitted: readonly string[] | null, includeUnplaced: boolean,
    options: { limit?: number; states?: readonly TaskState[]; order?: "created" | "updated" } = {}): TaskFamily[] {
    const projection = this.taskFamilyProjection(admitted, includeUnplaced);
    const order = options.order === "updated" ? "updated_at" : "created_at";
    const rows = this.db.prepare(`${projection.sql}, selected AS MATERIALIZED (
        SELECT * FROM ordered WHERE version_rank = 1
          ${options.states === undefined ? "" : `AND state IN (${options.states.map(() => "?").join(",")})`}
        ORDER BY ${order} DESC, ref_id DESC LIMIT ?
      ) SELECT task.*, members.repo, members.ref_id, members.root_ref, members.broken
      FROM selected JOIN members ON members.root_ref = selected.root_ref
      JOIN task ON task.id = members.id
      ORDER BY selected.${order} DESC, selected.ref_id DESC, members.ref_id`)
      .all(...projection.params, ...(options.states ?? []), Math.max(1, Math.floor(options.limit ?? 201)));
    const grouped = new Map<number, Record<string, unknown>[]>();
    for (const row of rows) {
      const root = Number(row["root_ref"]);
      const family = grouped.get(root) ?? [];
      family.push(row); grouped.set(root, family);
    }
    return [...grouped.values()].map(rows => this.taskFamilyFromRows(rows));
  }

  /** Opening one task uses at most 64 permission-aware point reads, then
   * one descendant query rooted at its proven ancestor. No fleet listing,
   * no per-card materialization of unrelated tasks, no historical writes. */
  taskFamilyOf(taskId: string, admitted: readonly string[] | null, includeUnplaced: boolean): TaskFamily | null {
    const point = this.db.prepare(`SELECT task.*, child.id AS ref_id, child.repo, child.revision_of,
        parent.id AS parent_ref, source_run.task_ref AS source_ref
      FROM task_ref child JOIN task ON task.id = child.external_id
      LEFT JOIN task_ref parent ON parent.backend = child.backend AND parent.external_id = child.revision_of AND parent.repo IS child.repo
      LEFT JOIN artifact brief ON brief.id = child.revision_brief_artifact AND brief.kind = 'revision-brief'
      LEFT JOIN run source_run ON source_run.id = brief.run
      WHERE child.backend = ? AND child.external_id = ? AND ((child.repo IS NULL AND ? = 1)
        OR (child.repo IS NOT NULL AND (? = 1 OR child.repo IN (${(admitted ?? []).map(() => "?").join(",")}))))`);
    const seen = new Set<string>();
    let cursor = taskId;
    let first: Record<string, unknown> | undefined;
    let root: Record<string, unknown> | undefined;
    while (seen.size < 64 && !seen.has(cursor)) {
      const row = point.get(BUILT_IN, cursor, includeUnplaced ? 1 : 0, admitted === null ? 1 : 0, ...(admitted ?? []));
      if (row === undefined) break;
      first ??= row;
      seen.add(cursor);
      if (row["revision_of"] === null) { root = row; break; }
      if (row["parent_ref"] === null || row["source_ref"] !== row["parent_ref"]) break;
      cursor = String(row["revision_of"]);
    }
    if (first === undefined) return null;
    if (root === undefined) return this.taskFamilyFromRows([{ ...first, root_ref: first["ref_id"], broken: 1 }]);
    // Admission is already proven for the root; each descendant must be in
    // that SAME project and bind a brief to its parent's own run.
    const rows = this.db.prepare(`WITH RECURSIVE descendants(ref_id, id, depth) AS (
        SELECT id, external_id, 0 FROM task_ref WHERE id = ?
        UNION ALL
        SELECT child.id, child.external_id, parent.depth + 1 FROM descendants parent
        JOIN task_ref child ON child.backend = ? AND child.revision_of = parent.id AND child.repo IS ?
        JOIN task ON task.id = child.external_id
        JOIN artifact brief ON brief.id = child.revision_brief_artifact AND brief.kind = 'revision-brief'
        JOIN run source_run ON source_run.id = brief.run AND source_run.task_ref = parent.ref_id
        WHERE parent.depth < 63
      ) SELECT task.*, task_ref.repo, descendants.ref_id, ? AS root_ref, 0 AS broken
      FROM descendants JOIN task ON task.id = descendants.id JOIN task_ref ON task_ref.id = descendants.ref_id`)
      .all(root["ref_id"], BUILT_IN, root["repo"], root["ref_id"]);
    return this.taskFamilyFromRows(rows);
  }

  /** Only possible live executions need dispatch/run enrichment for counts.
   * Admission binds here too; an orphaned run is merely a candidate, not
   * evidence of liveness. The caller uses the shared Work projection. */
  taskActivityCandidates(admitted: readonly string[] | null, includeUnplaced: boolean, now: Date, taskIds?: readonly string[]): TaskVersion[] {
    return this.db.prepare(`SELECT task.*, task_ref.repo, task_ref.id AS ref_id
      FROM task_ref JOIN task ON task.id = task_ref.external_id
      WHERE task_ref.backend = ? AND ((task_ref.repo IS NULL AND ? = 1)
        OR (task_ref.repo IS NOT NULL AND (? = 1 OR task_ref.repo IN (${(admitted ?? []).map(() => "?").join(",")}))))
      ${taskIds === undefined ? "" : "AND task.id IN (SELECT value FROM json_each(?))"}
      AND (EXISTS (SELECT 1 FROM claim WHERE claim.task_ref = task_ref.id AND claim.released_at IS NULL AND claim.expires_at > ?)
        OR EXISTS (SELECT 1 FROM run WHERE run.task_ref = task_ref.id AND run.outcome IS NULL AND run.role = 'reviewer'))`)
      .all(BUILT_IN, includeUnplaced ? 1 : 0, admitted === null ? 1 : 0, ...(admitted ?? []), ...(taskIds === undefined ? [] : [JSON.stringify(taskIds)]), now.toISOString())
      .map(row => ({ ...readTask(row), repo: row["repo"] === null ? null : String(row["repo"]), refId: Number(row["ref_id"]) }));
  }

  /** Aggregate families in SQL. A live older sibling counts the family once
   * as live, even if its newest execution is queued or already finished. */
  taskFamilyCounts(admitted: readonly string[] | null, includeUnplaced: boolean, now: Date, liveTasks: readonly string[]) {
    const projection = this.taskFamilyProjection(admitted, includeUnplaced);
    const row = this.db.prepare(`${projection.sql}, live_families AS (
        SELECT DISTINCT root_ref FROM members WHERE id IN (SELECT value FROM json_each(?))
      ) SELECT
        COUNT(CASE WHEN live_families.root_ref IS NOT NULL THEN 1 END) AS running,
        COUNT(CASE WHEN live_families.root_ref IS NULL AND ordered.state = 'queued' THEN 1 END) AS queued,
        COUNT(CASE WHEN live_families.root_ref IS NULL AND ordered.state = 'done' AND ordered.updated_at >= ? THEN 1 END) AS doneRecently
      FROM ordered LEFT JOIN live_families ON live_families.root_ref = ordered.root_ref WHERE version_rank = 1`)
      .get(...projection.params, JSON.stringify(liveTasks), new Date(now.getTime() - 24 * 60 * 60_000).toISOString())!;
    return { running: Number(row["running"]), queued: Number(row["queued"]), doneRecently: Number(row["doneRecently"]) };
  }

  /**
   * The revision tasks sealed FROM one reviewed run (workspace package 3):
   * every task whose brief artifact belongs to the run, oldest first, with
   * the child's current state and whether its own approval was given. A
   * result page links forward to these; the child's approval card already
   * links back to the source task and build. Read-only — the seal itself
   * is `sealRevision`.
   */
  revisionsFromRun(runId: number): { id: string; title: string; state: TaskState; approved: boolean; createdAt: string }[] {
    const rows = this.db
      .prepare(
        `SELECT task_ref.external_id AS id
         FROM task_ref JOIN artifact ON artifact.id = task_ref.revision_brief_artifact
         WHERE artifact.run = ? AND task_ref.revision_of IS NOT NULL
         ORDER BY task_ref.id`,
      )
      .all(runId) as { id: string }[];
    return rows.flatMap(row => {
      const task = this.getTask(row.id);
      if (task === null) return [];
      // CURRENT exact approval (repair 2026-09-14): the same predicate every
      // consent surface reads — a stamp on terms that were since rewritten is
      // no approval of the current ones.
      const scope = this.getScope(row.id);
      const approved = scope !== null && scope.termsProblem == null && approvalOf(scope).approved;
      return [{ id: task.id, title: task.title, state: task.state, approved, createdAt: task.createdAt }];
    });
  }

  /**
   * Which repair chain a task CONTINUES (contract handoff task 2): the
   * nearest task in its revision ancestry — itself included — that is a
   * repair draft names the chain; failing that, the nearest ancestor that
   * ROOTS a chain. An annotation or CI detour between two repair attempts
   * therefore keeps the chain's root, its attempt count, and its remaining
   * automatic bound; nothing resets because a person annotated the draft.
   * A task with no chain anywhere above it roots its own, as before.
   */
  repairLineageOf(taskId: string): RepairLineage {
    const ancestry = this.revisionAncestryStatus(taskId);
    if (ancestry.problem !== null) return { rootTask: taskId, attempts: [], continues: null, via: null, problem: ancestry.problem };
    for (const ancestor of ancestry.chain) {
      const asDraft = this.repairChainForDraft(ancestor);
      if (asDraft !== null) {
        const attempts = this.repairChainForRoot(asDraft.rootTask);
        return { rootTask: asDraft.rootTask, attempts, continues: asDraft, via: ancestor === taskId ? null : ancestor };
      }
      const asRoot = this.repairChainForRoot(ancestor);
      if (asRoot.length > 0) {
        return { rootTask: ancestor, attempts: asRoot, continues: asRoot[asRoot.length - 1] ?? null, via: ancestor === taskId ? null : ancestor };
      }
    }
    return { rootTask: taskId, attempts: [], continues: null, via: null };
  }

  /**
   * The lineage and ACTUAL terms of a revision task, as every projection
   * shows them (task page, chat, approval card): the source, the ancestry
   * to the root, the terms the child really carries — read from its own
   * scope and ref, never restated from the brief — and, when the task
   * continues a repair chain, the attempts used against the signed cap.
   * Null for a task that revises nothing.
   */
  revisionLineageOf(taskId: string, now: Date): RevisionLineage | null {
    const ref = this.lookupRef(taskId);
    if (ref === null || ref.revisionOf === null) return null;
    const ancestry = this.revisionAncestryOf(taskId);
    const scope = this.getScope(taskId);
    const artifact = ref.revisionBriefArtifact === null ? null : this.getArtifact(ref.revisionBriefArtifact);
    const sourceRun = artifact === null ? null : artifact.run;
    const sourceScope = this.getScope(ref.revisionOf);
    const lineage = this.repairLineageOf(taskId);
    const mode = ref.repo === null ? null : this.activeMode(ref.repo, now);
    const modeTerms = mode === null ? null : modeTermsFromJson(mode.termsJson);
    const cap = modeTerms !== null && modeTerms.repairAuto === true ? modeTerms.repairMaxAttempts : null;
    const attemptsUsed = lineage.attempts.reduce((highest, row) => Math.max(highest, row.attempt), 0);
    const profile = scope === null ? null : (scope.approvedProfile ?? scope.profile ?? null);
    return {
      sourceTask: ref.revisionOf,
      sourceRun,
      ancestors: ancestry.slice(1),
      root: ancestry[ancestry.length - 1] ?? taskId,
      terms:
        scope === null
          ? null
          : {
              riskLevel: scope.riskLevel ?? "routine",
              qualityMode: scope.qualityMode ?? "default",
              // The posture that will actually run: the working profile's
              // (a live mode's escalation rides it), else the durable choice.
              permissionMode: permissionModeOfProfile(profile) ?? ref.permissionMode ?? this.permissionDefault().mode,
              budgetMicrousd: scope.budgetMicrousd,
              exclusions: scope.outOfScope !== null,
              touches: scope.touches.length,
              criteria: scope.acceptance.length,
              routeOverrides: ref.routeOverrides === null || ref.routeOverrides === undefined ? 0 : ref.routeOverrides.length,
            },
      sourceHadScope: sourceScope !== null,
      ...(lineage.problem === undefined ? {} : { problem: lineage.problem }),
      repair:
        lineage.attempts.length === 0
          ? null
          : {
              rootTask: lineage.rootTask,
              attemptsUsed,
              cap,
              remaining: cap === null ? null : Math.max(0, cap - attemptsUsed),
              thisAttempt: this.repairChainForDraft(taskId)?.attempt ?? null,
              via: lineage.via,
            },
    };
  }

  // ---- repair chain (v40, evidence-review-v1) -----------------------------

  /**
   * Draft one repair through the SAME `sealRevision` road CI repair already
   * uses (`commentIds: null` — a repair draft never consumes a comment
   * batch, only names unresolved criterion ids), then records the chain's
   * ledger row in the same transaction. `source_run UNIQUE` is the backstop
   * that makes "at most one draft per source run, ever" a database fact,
   * not just caller discipline.
   */
  openRepairDraft(
    args: {
      source: { task: string; run: number; scopeDigest: string | null };
      brief: { evidenceRoot: string; key: string; sha256: string; bytes: number; capture: string };
      child: { id: string; title: string; repair: string };
      rootTask: string;
      attempt: number;
      basis: "human" | "mode";
      modeDigest: string | null;
      unresolved: readonly string[];
    },
    now: Date,
  ): { ok: true; id: string; artifactId: number; terms: RevisionTerms } | { ok: false; reason: RevisionRefusal; detail: string } {
    try {
      return this.transact(() =>
        this.savepoint(() => {
          if (this.repairChainFor(args.source.run) !== null) return { ok: false as const, reason: "duplicate" as const, detail: "this source run already produced a repair disposition" };
          const lineage = this.repairLineageOf(args.source.task);
          const next = lineage.attempts.reduce((highest, row) => Math.max(highest, row.attempt), 0) + 1;
          if (lineage.problem !== undefined || args.rootTask !== lineage.rootTask || args.attempt !== next) {
            return { ok: false as const, reason: "source-terms" as const, detail: lineage.problem ?? "the repair root or attempt changed; a handoff cannot reset its allowance" };
          }
          if (args.basis === "mode") {
            const repo = this.lookupRef(args.source.task)?.repo;
            const mode = repo == null ? null : this.activeMode(repo, now);
            const terms = mode === null ? null : modeTermsFromJson(mode.termsJson);
            if (mode === null || mode.digest !== args.modeDigest || terms?.repairAuto !== true || next > terms.repairMaxAttempts) {
              return { ok: false as const, reason: "source-terms" as const, detail: "the automatic repair authority is absent, changed, or spent" };
            }
          } else if (args.modeDigest !== null) {
            return { ok: false as const, reason: "source-terms" as const, detail: "a human repair draft cannot carry an automatic approval basis" };
          }
          const sealed = this.sealRevision({ source: args.source, brief: args.brief, child: args.child, commentIds: null }, now);
          if (!sealed.ok) return sealed;
          // The chain row rides the same savepoint as the seal: a second
          // drafter of the same source run trips `source_run UNIQUE` here,
          // and the whole draft — task, artifact row, relation — rolls back
          // with it. Exactly one winner, in words for the loser.
          this.db
            .prepare(
              `INSERT INTO repair_chain (root_task, source_run, attempt, draft_task, basis, mode_digest, unresolved_json, outcome, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, 'drafted', ?)`,
            )
            .run(args.rootTask, args.source.run, args.attempt, sealed.id, args.basis, args.modeDigest, JSON.stringify(args.unresolved), now.toISOString());
          return sealed;
        }),
      );
    } catch (error) {
      const message = String((error as Error).message ?? error);
      return { ok: false, reason: /database (?:is )?locked|SQLITE_BUSY/.test(message) ? "busy" : /UNIQUE constraint failed/.test(message) ? "duplicate" : "invariant", detail: message };
    }
  }

  /** The one chain-attempt row a given source run drafted, if any. */
  repairChainFor(sourceRunId: number): RepairChainRow | null {
    const row = this.db.prepare("SELECT * FROM repair_chain WHERE source_run = ?").get(sourceRunId);
    return row === undefined ? null : readRepairChain(row as Record<string, unknown>);
  }

  /** The chain-attempt row that drafted a given task, if it IS a repair
   * draft — the trigger's own way to find "what chain, and what attempt
   * number, does this task continue" without walking task_ref.revision_of. */
  repairChainForDraft(draftTaskId: string): RepairChainRow | null {
    const row = this.db.prepare("SELECT * FROM repair_chain WHERE draft_task = ?").get(draftTaskId);
    return row === undefined ? null : readRepairChain(row as Record<string, unknown>);
  }

  /**
   * Record a chain stop that never produced a draft — the one edge case
   * possible: the FIRST attempt in a chain, refused outright by the
   * integrity stop, with no prior row to settle instead. Already-settled
   * on arrival: there is no "later" for a row that was never drafted.
   */
  recordRepairStop(
    args: {
      rootTask: string;
      sourceRun: number;
      attempt: number;
      basis: "human" | "mode";
      modeDigest: string | null;
      unresolved: readonly string[];
      outcome: Exclude<RepairChainRow["outcome"], "drafted">;
    },
    now: Date,
  ): void {
    this.db
      .prepare(
        `INSERT INTO repair_chain (root_task, source_run, attempt, draft_task, basis, mode_digest, unresolved_json, outcome, created_at, settled_at)
         VALUES (?, ?, ?, NULL, ?, ?, ?, ?, ?, ?)`,
      )
      .run(args.rootTask, args.sourceRun, args.attempt, args.basis, args.modeDigest, JSON.stringify(args.unresolved), args.outcome, now.toISOString(), now.toISOString());
  }

  /** Every attempt in a chain rooted at one original task, in attempt order
   * — the attempt-cap count, the no-progress comparison, and the one
   * inbox item's trajectory all read this. */
  repairChainForRoot(rootTask: string): RepairChainRow[] {
    return this.db
      .prepare("SELECT * FROM repair_chain WHERE root_task = ? ORDER BY attempt ASC")
      .all(rootTask)
      .map(row => readRepairChain(row as Record<string, unknown>));
  }

  /** Settle a chain attempt exactly once — the four stops (attempts-spent,
   * no-progress, integrity-refused) and the happy path (resolved) all
   * funnel through here. A row already settled is left untouched. */
  settleRepairChain(id: number, outcome: Exclude<RepairChainRow["outcome"], "drafted">, now: Date): void {
    this.db.prepare("UPDATE repair_chain SET outcome = ?, settled_at = ? WHERE id = ? AND settled_at IS NULL").run(outcome, now.toISOString(), id);
  }

  notesForRun(runId: number): { id: number; author: string; note: string; createdAt: string }[] {
    return this.db
      .prepare("SELECT * FROM run_note WHERE run = ? ORDER BY id")
      .all(runId)
      .map(row => ({
        id: Number(row["id"]),
        author: String(row["author"]),
        note: String(row["note"]),
        createdAt: String(row["created_at"]),
      }));
  }

  listWorktrees(): WorktreeRow[] {
    return this.db.prepare("SELECT * FROM worktree ORDER BY path").all().map(readWorktree);
  }

  /**
   * Hand back every worktree a dead runner held, unverified.
   *
   * Nobody watched what its process was doing when it stopped, so what is on
   * disk describes the past rather than the present. Marking these verified
   * would be asserting something we did not check.
   */
  releaseWorktreesOf(runner: string, now: Date): string[] {
    const held = this.db
      .prepare("SELECT path FROM worktree WHERE runner = ? AND released_at IS NULL")
      .all(runner)
      .map(row => String(row["path"]));
    if (held.length === 0) return [];

    this.db
      .prepare(
        "UPDATE worktree SET released_at = ?, verified = 0 WHERE runner = ? AND released_at IS NULL",
      )
      .run(now.toISOString(), runner);
    return held;
  }

  // ---- capabilities -------------------------------------------------------

  saveCapability(capability: Capability, mutation: Mutation = {}): void {
    this.once(mutation, "saveCapability", () => {
      this.db
        .prepare(
          `INSERT INTO capability (repo, kind, name, probe, status, added_by, created_at, last_verified_at, verified_by, last_result, expires_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
           ON CONFLICT (repo, kind, name) DO UPDATE SET
             probe = excluded.probe, status = excluded.status,
             last_verified_at = excluded.last_verified_at,
             verified_by = excluded.verified_by, last_result = excluded.last_result,
             expires_at = excluded.expires_at`,
        )
        .run(
          capability.repo,
          capability.kind,
          capability.name,
          capability.probe,
          capability.status,
          capability.addedBy,
          capability.createdAt,
          capability.lastVerifiedAt,
          capability.verifiedBy,
          capability.lastResult,
          capability.expiresAt,
        );
      return null;
    });
  }

  getCapability(repo: string, kind: string, name: string): Capability | null {
    const row = this.db
      .prepare("SELECT * FROM capability WHERE repo = ? AND kind = ? AND name = ?")
      .get(repo, kind, name);
    return row === undefined ? null : readCapability(row);
  }

  /** By name alone, any kind — how a task requirement refers to one. */
  capabilityNamed(repo: string, name: string): Capability | null {
    const row = this.db
      .prepare("SELECT * FROM capability WHERE repo = ? AND name = ? ORDER BY kind LIMIT 1")
      .get(repo, name);
    return row === undefined ? null : readCapability(row);
  }

  listCapabilities(repo: string): Capability[] {
    return this.db
      .prepare("SELECT * FROM capability WHERE repo = ? ORDER BY kind, name")
      .all(repo)
      .map(readCapability);
  }

  /**
   * Record a probe's answer. Verification carries the moment it happened,
   * because "verified" is always a claim about a time (§3: presence is not
   * enough, and neither is a stale yes).
   */
  markCapability(
    repo: string,
    kind: string,
    name: string,
    outcome: { status: "verified" | "failed"; by: string; detail?: string },
    now: Date,
    expiresAt: string | null = null,
  ): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE capability SET status = ?, last_verified_at = ?, verified_by = ?, last_result = ?, expires_at = COALESCE(?, expires_at)
          WHERE repo = ? AND kind = ? AND name = ?`,
      )
      .run(
        outcome.status,
        outcome.status === "verified" ? now.toISOString() : null,
        outcome.by,
        outcome.detail ?? null,
        expiresAt,
        repo,
        kind,
        name,
      );
    // A gap that just filled ends its notification episode: the next failure
    // is a new fact, and must be allowed to say so.
    if (Number(changes) > 0 && outcome.status === "verified") {
      this.clearGapEpisode(repo, kind, name);
      this.bumpWake();
    }
    return Number(changes) > 0;
  }

  /** Set what a task needs, as `kind:name` keys, replacing what it needed before. */
  setRequirements(taskRef: number, keys: readonly string[], mutation: Mutation = {}): boolean {
    return this.once(mutation, "setRequirements", () => {
      const { changes } = this.db
        .prepare("UPDATE task_ref SET capability_requirements = ? WHERE id = ?")
        .run(JSON.stringify([...keys]), taskRef);
      return Number(changes) > 0;
    });
  }

  /**
   * The operator's answer to a stall: one transaction that resolves the
   * task's open incidents (lifting their holds), clears strikes and any
   * backoff, and returns the task to the queue. The authenticated act that
   * un-decides "this stopped being worth retrying".
   *
   * Requeueability is re-proved HERE, not by whoever rendered the button: a
   * task is requeueable when it is failed or carries an unresolved
   * incident, and nothing holds a live claim on it. A stale form submitted
   * after the world moved gets a refusal, never a silent erase of somebody
   * else's incident and backoff state.
   */
  /**
   * Whether a still-current, unexpired claim holds this task right now — the
   * one predicate cancel, requeue, and scope edits all defer to, because a
   * console act that ignored a live runner would be overwritten by that
   * runner's completion minutes later.
   */
  hasLiveClaim(taskRef: number, now: Date): boolean {
    return this.currentLiveLease(taskRef, now) !== null;
  }

  /**
   * The lease currently holding this task — the MAXIMUM claim generation,
   * still unreleased, strictly unexpired — or null. This is the one fact
   * "is this run live" derives from: a run is being built right now iff its
   * outcome is null AND its lease is this lease. `liveClaimByLease` proves
   * only that a lease exists; it cannot prove the lease is current, so it
   * must never stand in for this.
   */
  /**
   * Whether this connection's database still carries EXACTLY this build's
   * schema version (MCP spec v6): the non-migrating server calls this
   * inside every unit of work, because a concurrent process may migrate
   * underneath a long-lived connection — a negative version (the epoch
   * sentinel) or any other version answers false.
   */
  schemaCurrent(): boolean {
    // The one strict reader (raw authority repair): anything it cannot
    // name — including a table that vanished — answers false, never a
    // coerced number that happens to compare equal.
    try {
      const read = readSchemaVersion(this.db);
      return read.ok && read.version === SCHEMA_VERSION;
    } catch {
      return false;
    }
  }

  /**
   * The spawn leg of the runner gate (MCP gateway spec v6, rounds 4–5):
   * ONE transaction, immediately before a provider process exists, that
   * re-proves the tuple against LIVE rows — the run open, its lease still
   * the task's current claim held by ITS runner, the runner row present
   * and unretired, the task placed, and the placement inside the runner's
   * bound repos. A retirement, takeover, re-binding, or re-placement
   * between acquisition and this instant refuses the spawn, whatever road
   * built the request — build, plan, repair, review, and held alike.
   */
  proveRunnerCustodyForSpawn(runId: number, now: Date): boolean {
    return this.transact(() => {
      const run = this.getRun(runId);
      if (run === null || run.outcome !== null) return false;
      const found = this.getRunner(run.runner);
      if (found === null || found.runner.retiredAt !== null) return false;
      const repo = this.refForId(run.taskRef)?.repo ?? null;
      if (repo === null || !found.runner.repos.includes(repo)) return false;
      // Reviewer runs are the one role that holds NO task claim by design
      // — they run after the build, on a task whose lease is settled, under
      // admitReview's own single-winner admission (its synthetic lease id
      // is a marker, not a claim). Identity, liveness, and membership are
      // proven above; INCARNATION stands in for lease currency (round-2
      // finding 3): a rotation re-registers, which stamps a NEWER
      // registered_at. Structured-output repair children are opened after
      // the original admission, so their own started_at cannot be the
      // credential fence; every descendant compares against the admitted
      // ROOT reviewer's timestamp instead.
      if (run.role === "reviewer") {
        const root = this.reviewerRoot(run);
        if (root === null || found.runner.registeredAt > root.startedAt) return false;
        return root.watchIncarnation == null || this.db.prepare(
          "SELECT 1 FROM watch_lease WHERE runner = ? AND repo = ? AND owner = ? AND expires_at > ?",
        ).get(run.runner, repo, root.watchIncarnation, now.toISOString()) !== undefined;
      }
      return this.currentLiveLease(run.taskRef, now) === run.leaseId;
    });
  }

  currentLiveLease(taskRef: number, now: Date): string | null {
    const live = this.db
      .prepare(
        `SELECT lease_id FROM claim
          WHERE task_ref = ? AND released_at IS NULL AND expires_at > ?
            AND lease_generation = (
              SELECT MAX(newest.lease_generation) FROM claim AS newest
              WHERE newest.task_ref = claim.task_ref
            )`,
      )
      .get(taskRef, now.toISOString());
    return live === undefined ? null : String(live["lease_id"]);
  }

  /** The task's most recent finished builder attempt, or null. */
  lastBuilderRun(taskRef: number): Run | null {
    const row = this.db
      .prepare("SELECT id FROM run WHERE task_ref = ? AND role = 'builder' AND finished_at IS NOT NULL ORDER BY id DESC LIMIT 1")
      .get(taskRef);
    return row === undefined ? null : this.getRun(Number(row["id"]));
  }

  /** How many finished builder attempts of this task ended at `head`. */
  builderAttemptsAt(taskRef: number, head: string): number {
    const row = this.db
      .prepare("SELECT count(*) AS n FROM run WHERE task_ref = ? AND role = 'builder' AND finished_at IS NOT NULL AND head_revision = ?")
      .get(taskRef, head);
    return Number(row?.["n"] ?? 0);
  }

  /** Why a finished result can't be built again on the same filing: it was
   * verified, attested or accepted, or its branch was published (revised
   * through its pull request). Null when `requeueTask` may run it again. */
  finalResultReason(runId: number): "accepted-result" | "published" | null {
    const verdict = this.proofVerdictFor(runId);
    if (verdict !== null && (verdict.verdict === "verified" || verdict.verdict === "attested")) return "accepted-result";
    if (this.proofAcceptance(runId) !== null) return "accepted-result";
    // An intent that never pushed is not a publication; a pushed or
    // opened branch is, and is revised through its pull request.
    const publication = this.publicationForRun(runId);
    if (publication !== null && (publication.state === "pushed" || publication.state === "opened")) return "published";
    return null;
  }

  requeueTask(
    taskId: string,
    by: string,
    now: Date,
  ):
    | { ok: true; resolvedIncidents: number; rejectedRun: number | null }
    | { ok: false; reason: "unknown-task" | "not-stalled" | "claimed" | "accepted-result" | "published" } {
    return this.transact(() => {
      const ref = this.db
        .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
        .get(BUILT_IN, taskId);
      if (ref === undefined) return { ok: false as const, reason: "unknown-task" as const };
      const taskRef = Number(ref["id"]);

      const stamp = now.toISOString();
      if (this.hasLiveClaim(taskRef, now)) return { ok: false as const, reason: "claimed" as const };

      const incidents = this.db
        .prepare(
          `SELECT incident.id FROM incident
           JOIN run ON run.id = incident.run
           WHERE run.task_ref = ? AND incident.resolved_at IS NULL`,
        )
        .all(taskRef)
        .map(row => Number(row["id"]));
      const state = String(this.db.prepare("SELECT state FROM task WHERE id = ?").get(taskId)?.["state"]);
      // A finished task whose last result was rejected — a failed gate, a
      // contradicting review, a refuted proof — runs again on the SAME
      // filing: the branch keeps the earlier attempt, the sealed diff still
      // spans from the original base, and a corrected candidate needs a
      // re-scope, not a new task. An accepted or published result is final
      // here; it is revised through a revision or its pull request.
      let rejectedRun: number | null = null;
      if (state === "done") {
        // The guards hold whether or not an incident is open: a finished
        // task's last result decides, and an accepted or published one is
        // never reopened by resolving an incident beside it.
        const last = this.db
          .prepare("SELECT id FROM run WHERE task_ref = ? AND role = 'builder' AND finished_at IS NOT NULL ORDER BY id DESC LIMIT 1")
          .get(taskRef);
        if (last === undefined) {
          if (incidents.length === 0) return { ok: false as const, reason: "not-stalled" as const };
        } else {
          rejectedRun = Number(last["id"]);
          const final = this.finalResultReason(rejectedRun);
          if (final !== null) return { ok: false as const, reason: final };
        }
      } else if (incidents.length === 0 && state !== "failed") {
        return { ok: false as const, reason: "not-stalled" as const };
      }

      for (const incident of incidents) this.resolveIncidentLocked(incident, by, now);

      this.resetStrikes(taskRef);
      this.db
        .prepare("UPDATE task SET state = 'queued', updated_at = ? WHERE id = ? AND state IN ('failed','queued','done')")
        .run(stamp, taskId);
      // The stall's page is answered by the act itself.
      this.resolveEpisode(`stalled:${taskRef}`, now);
      this.noteLifecycle(
        {
          taskRef, kind: "task-requeued", identity: `t${taskRef}`,
          subject: "Requeued",
          body: rejectedRun !== null
            ? `Its last result (attempt #${rejectedRun}) was not accepted; the next attempt continues on the same branch under the current scope.`
            : `${incidents.length > 0 ? "Its incident is resolved and its" : "Its"} failure streak is cleared; a worker can take it again.`,
          link: chatControlHref("task", taskId),
        },
        now,
      );
      this.bumpWake();
      return { ok: true as const, resolvedIncidents: incidents.length, rejectedRun };
    });
  }

  /**
   * Cancel, aware of who might be building right now. A live claim wins:
   * cancelling under a runner would let its completion overwrite the
   * cancellation minutes later, so the answer is a refusal that names the
   * holder — stop the claim first (or let it lapse), then cancel.
   */
  cancelTask(
    taskId: string,
    now: Date,
    reason?: string,
  ): { ok: true } | { ok: false; reason: "unknown-task" | "claimed" | "already-terminal" | CancellationRefusal } {
    return this.transact(() => {
      const ref = this.db
        .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
        .get(BUILT_IN, taskId);
      if (ref === undefined) return { ok: false as const, reason: "unknown-task" as const };

      if (this.hasLiveClaim(Number(ref["id"]), now)) return { ok: false as const, reason: "claimed" as const };

      const done = this.applyCancellation(
        taskId,
        { kind: "operator", text: reason ?? null },
        now,
        ["queued", "failed", "running"],
      );
      if (done.reason !== undefined) return { ok: false as const, reason: done.reason };
      if (!done.changed) return { ok: false as const, reason: "already-terminal" as const };
      this.bumpWake();
      return { ok: true as const };
    });
  }

  /**
   * The console's task creation: admission control and atomicity the CLI's
   * local-trust path does not need. One transaction checks the active
   * backlog (queued + running below the cap), validates the writable
   * fields' caps and control rules — these strings will be rendered to
   * every surface — and creates the task, its placement, and its optional
   * scope together or not at all.
   */
  createConsoleTask(
    spec: {
      id?: string;
      title: string;
      repo?: string;
      goal?: string;
      /** Mode filing defaults (C1/C7, people round-1 f2): the budget and
       * escalated posture ride the FILING, before the digest is computed —
       * never stamped after the fact. */
      budgetMicrousd?: number | null;
      /** Durable task-level choice; absent means use the installation
       * default whenever this task's scope is next filed. */
      permissionMode?: UnattendedPermissionMode;
      /** Durable per-task evidence depth; absent inherits installation
       * default when the scope is filed. */
      qualityMode?: QualityMode;
      /** The revision road's inherited declarations (contract handoff task
       * 2): the source's declared risk, the approver's per-phase route
       * overrides, and its build/plan pins — stamped on the ref BEFORE the
       * scope resolves, so the child's route is recommended over them
       * exactly as the source's was, never over the installation's
       * defaults of the day. */
      riskLevel?: RiskLevel;
      /** How big the change is, sized at filing (v2 routing). */
      sizing?: TaskSizing;
      routeOverridesJson?: string | null;
      agentPin?: { provider: string; model: string | null } | null;
      planPin?: { provider: string; model: string | null } | null;
      posture?: "escalated";
      /** Revision tasks inherit these from the source scope (Codex M5-M8
       * audit, IV-2): a revision that silently drops the original's
       * exclusions and path limits is an approval screen claiming "no
       * exclusions" over work that had them. */
      outOfScope?: string | null;
      touches?: string[];
      /** v39: the signed acceptance rubric — unparsed input, validated here
       * the same way `proposeGuarded` validates it, because this is the
       * OTHER road every filing door funnels through. Absent/empty refuses
       * whenever a `goal` is also being set (a scope is about to exist);
       * a bare title with no goal creates no scope yet, so nothing to sign. */
      acceptance?: unknown;
      /** v102: who filed it (the person, or the person a coordinator acts for). */
      filedBy?: Filer;
      /** Immutable provenance (v12): which door filed this. Stamped in the
       * same transaction as the create; there is no API to change it. */
      filedVia?: string;
      /** Who wrote the scope text (mate arc, ruling 2): a confirmed mate
       * proposal stamps `mate`, and mode coverage then never seals it.
       * 'scout' (v34) is a follow-up filed from a scout's report. */
      proposedVia?: "mate" | "coordinator" | "scout" | null;
      /** What comes back (v34): 'report' files a scout task. Immutable. */
      deliverable?: "branch" | "report";
    },
    now: Date,
    cap = 500,
  ):
    | { ok: true; id: string }
    | { ok: false; reason: "backlog-full" | "bad-id" | "bad-title" | "bad-goal" | "bad-acceptance" | "acceptance-required" | "duplicate" } {
    const badText = validateTaskText(spec);
    if (badText !== null) return { ok: false, reason: badText.reason };
    return this.#insertConsoleTask({ ...spec, ...(spec.goal === undefined ? {} : { goal: spec.goal.trim() }) }, now, cap);
  }

  /** Shared atomic insertion, callable only by this class. Public new-work
   * filing validates all text; sealRevision validates the new repair after
   * proving source custody, then supplies exact inherited bytes. */
  #insertConsoleTask(
    spec: Parameters<Store["createConsoleTask"]>[0],
    now: Date,
    cap = 500,
  ): ReturnType<Store["createConsoleTask"]> {
    if (spec.id !== undefined && !/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(spec.id)) {
      return { ok: false, reason: "bad-id" };
    }
    // v39: a goal being set here is a scope about to exist — every road that
    // funnels through this method (fileTaskProposal's ~16 callers, and
    // sealRevision) is subject to the same rubric-required gate proposeGuarded
    // enforces on an edit. No goal, no scope, nothing to sign — a bare-title
    // filing (a coordinator's intent-less filing, `task add --backend`) is
    // untouched.
    const acceptanceParse = spec.goal === undefined ? null : parseAcceptanceCriteria(spec.acceptance);
    if (acceptanceParse !== null && acceptanceParse.problems.length > 0) {
      return { ok: false, reason: "bad-acceptance" };
    }
    if (acceptanceParse !== null && acceptanceParse.criteria.length === 0) {
      return { ok: false, reason: "acceptance-required" };
    }
    return this.transact(() => {
      const backlog = this.db
        .prepare("SELECT COUNT(*) AS n FROM task WHERE state IN ('queued','running')")
        .get();
      if (Number(backlog?.["n"] ?? 0) >= cap) return { ok: false as const, reason: "backlog-full" as const };

      // No id given: slug the title, uniquified inside this same transaction
      // so two concurrent creates cannot mint the same one.
      let id = spec.id;
      if (id === undefined) {
        const base =
          spec.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 56) || "task";
        id = base;
        // An id a built-in ref already names (made by a lookup before any task existed) is taken too: its ledger history isn't this task's.
        for (let n = 2; this.db.prepare("SELECT 1 AS hit FROM task WHERE id = ? UNION ALL SELECT 1 FROM task_ref WHERE backend = 'built-in' AND external_id = ?").get(id, id) !== undefined; n++) {
          id = `${base}-${n}`;
        }
      } else if (this.db.prepare("SELECT 1 AS hit FROM task WHERE id = ?").get(id) !== undefined) {
        return { ok: false as const, reason: "duplicate" as const };
      }

      this.createTask({ id, title: spec.title.trim(), ...(spec.deliverable === undefined ? {} : { deliverable: spec.deliverable }), ...(spec.filedBy === undefined ? {} : { filedBy: spec.filedBy }) }, now);
      const ref = this.refFor(BUILT_IN, id, "ours");
      if (spec.filedVia !== undefined) {
        this.db.prepare("UPDATE task_ref SET filed_via = ? WHERE id = ? AND filed_via IS NULL").run(spec.filedVia, ref.id);
      }
      // Placement happens BEFORE the scope exists, so the immutability guard
      // in placeTask never fires here — atomic create, place, then scope.
      if (spec.repo !== undefined && spec.repo !== "") this.placeTask(ref.id, spec.repo, {}, now);
      if (spec.permissionMode !== undefined) {
        this.db.prepare("UPDATE task_ref SET permission_mode = ? WHERE id = ?").run(spec.permissionMode, ref.id);
      }
      if (spec.qualityMode !== undefined) {
        this.db.prepare("UPDATE task_ref SET quality_mode = ? WHERE id = ?").run(spec.qualityMode, ref.id);
      }
      if (spec.riskLevel !== undefined) {
        this.db.prepare("UPDATE task_ref SET risk_level = ? WHERE id = ?").run(spec.riskLevel, ref.id);
      }
      if (spec.routeOverridesJson !== undefined && spec.routeOverridesJson !== null) {
        this.db.prepare("UPDATE task_ref SET route_overrides_json = ? WHERE id = ?").run(spec.routeOverridesJson, ref.id);
      }
      if (spec.sizing !== undefined) this.writeSizing(ref.id, spec.sizing);
      if (spec.agentPin !== undefined && spec.agentPin !== null) this.pinTaskAgent(ref.id, spec.agentPin.provider, spec.agentPin.model);
      if (spec.planPin !== undefined && spec.planPin !== null) {
        this.db.prepare("UPDATE task_ref SET plan_provider = ?, plan_model = ? WHERE id = ?").run(spec.planPin.provider, spec.planPin.model, ref.id);
      }
      if (spec.goal !== undefined) {
        const draft = {
          goal: spec.goal,
          outOfScope: spec.outOfScope ?? null,
          touches: spec.touches ?? ([] as string[]),
          acceptance: acceptanceParse?.criteria ?? ([] as AcceptanceCriterion[]),
        };
        const budgeted = { ...draft, budgetMicrousd: spec.budgetMicrousd ?? null };
        this.saveScope(
          {
            taskId: id,
            ...budgeted,
            proposedAt: now.toISOString(),
            digest: digestOf(budgeted),
            approvedAt: null,
            approvedBy: null,
            approvedDigest: null,
          },
          {},
          {
            ...(spec.permissionMode === undefined ? {} : { permissionMode: spec.permissionMode }),
            ...(spec.qualityMode === undefined ? {} : { qualityMode: spec.qualityMode }),
            ...(spec.riskLevel === undefined ? {} : { riskLevel: spec.riskLevel }),
            ...(spec.posture === undefined ? {} : { posture: spec.posture }),
            proposedVia: spec.proposedVia ?? null,
          },
        );
      }
      return { ok: true as const, id };
    });
  }

  /**
   * Tasks stranded behind a terminally failed or cancelled blocker — work
   * that will never become ready, silently, unless somebody looks. Derived,
   * never stored; edges are preserved, and `task requeue <blocker>` is the
   * way out.
   */
  strandedTasks(repo: string | null = null): { id: string; blockedBy: string[] }[] {
    const rows = this.db
      .prepare(
        `SELECT task_edge.blocked AS id, task_edge.blocker AS blocker FROM task_edge
         JOIN task AS dependent ON dependent.id = task_edge.blocked AND dependent.state = 'queued'
         JOIN task AS blocker ON blocker.id = task_edge.blocker AND blocker.state IN ('failed','cancelled')
         JOIN task_ref ON task_ref.backend = '${'built-in'}' AND task_ref.external_id = task_edge.blocked
         WHERE (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
         ORDER BY task_edge.blocked, task_edge.blocker`,
      )
      .all(repo, repo);
    const grouped = new Map<string, string[]>();
    for (const row of rows) {
      const id = String(row["id"]);
      grouped.set(id, [...(grouped.get(id) ?? []), String(row["blocker"])]);
    }
    return [...grouped.entries()].map(([id, blockedBy]) => ({ id, blockedBy }));
  }

  /** One more consecutive failure. Returns the new count. */
  /**
   * The operator's explicit ask: plan this before anything builds. Refused
   * transactionally when the moment has passed — an approved scope means
   * the promise is already made, a live claim means the machine is already
   * spending, and a plan already under way needs no second request.
   */
  requestPlan(taskRef: number, now: Date): { ok: true } | { ok: false; reason: string } {
    return this.transact(() => {
      const ref = this.db.prepare("SELECT * FROM task_ref WHERE id = ?").get(taskRef);
      if (ref === undefined) return { ok: false as const, reason: "no such task reference" };
      const task = this.db
        .prepare("SELECT state FROM task WHERE id = ?")
        .get(String(ref["external_id"]));
      if (task === undefined) return { ok: false as const, reason: "no such task" };
      if (String(task["state"]) !== "queued") {
        return { ok: false as const, reason: `state is ${String(task["state"])}, not queued` };
      }
      if (ref["plan"] !== null && ref["plan"] !== undefined) {
        return { ok: false as const, reason: `a plan is already ${String(ref["plan"])}` };
      }
      const approved = this.db
        .prepare(
          `SELECT 1 AS hit FROM task_scope
           WHERE task_id = ? AND approved_digest = digest AND approved_at IS NOT NULL`,
        )
        .get(String(ref["external_id"]));
      if (approved !== undefined) {
        return { ok: false as const, reason: "the scope is already approved — planning happens before the promise, not after" };
      }
      const live = this.db
        .prepare(
          `SELECT 1 AS hit FROM claim WHERE task_ref = ? AND released_at IS NULL AND expires_at > ?`,
        )
        .get(taskRef, now.toISOString());
      if (live !== undefined) {
        return { ok: false as const, reason: "a runner holds this task right now" };
      }
      this.db.prepare("UPDATE task_ref SET plan = 'requested' WHERE id = ?").run(taskRef);
      this.bumpWake();
      return { ok: true as const };
    });
  }

  /** Plan pins (P2/C7): separate columns, read ONLY by the plan phase,
   * with a mutation cutoff — a live plan claim means the pinned pair is
   * already spending, and rerouting a spend mid-flight is not a pin. */
  setPlanPins(
    taskRef: number,
    provider: string,
    model: string | null,
    now: Date,
  ): { ok: true } | { ok: false; reason: "live-claim" } {
    return this.transact(() => {
      const live = this.db
        .prepare("SELECT 1 AS hit FROM claim WHERE task_ref = ? AND released_at IS NULL AND expires_at > ? LIMIT 1")
        .get(taskRef, now.toISOString());
      if (live !== undefined) return { ok: false as const, reason: "live-claim" as const };
      this.db.prepare("UPDATE task_ref SET plan_provider = ?, plan_model = ? WHERE id = ?").run(provider, model, taskRef);
      return { ok: true as const };
    });
  }

  /** Move the planning state; null clears it. Caller owns the transaction story. */
  setPlanState(taskRef: number, state: "requested" | "drafted" | null): void {
    this.db.prepare("UPDATE task_ref SET plan = ? WHERE id = ?").run(state, taskRef);
  }

  addPlanStrike(taskRef: number): number {
    this.db.prepare("UPDATE task_ref SET plan_strikes = plan_strikes + 1 WHERE id = ?").run(taskRef);
    const row = this.db.prepare("SELECT plan_strikes FROM task_ref WHERE id = ?").get(taskRef);
    return Number(row?.["plan_strikes"] ?? 0);
  }

  resetPlanStrikes(taskRef: number): void {
    this.db.prepare("UPDATE task_ref SET plan_strikes = 0 WHERE id = ?").run(taskRef);
  }

  addStrike(taskRef: number): number {
    this.db.prepare("UPDATE task_ref SET strikes = strikes + 1 WHERE id = ?").run(taskRef);
    const row = this.db.prepare("SELECT strikes FROM task_ref WHERE id = ?").get(taskRef);
    return Number(row?.["strikes"] ?? 0);
  }

  /**
   * A concluded success — built, no-change, or parked — ends the streak and
   * lifts any backoff still standing from it.
   */
  resetStrikes(taskRef: number): void {
    this.db.prepare("UPDATE task_ref SET strikes = 0 WHERE id = ?").run(taskRef);
    this.releaseOwnedHold("backoff", String(taskRef));
  }

  /** Say which repository a task's work lives in. */
  /**
   * Placement is immutable once a scope exists: an approval restates a goal
   * *for a project*, and moving the task afterwards would re-aim the yes at
   * a repo nobody agreed to. Place first, then scope — or requeue a fresh
   * task. (Console v2 review, finding 3.)
   */
  placeTask(
    taskRef: number,
    repo: string,
    mutation: Mutation = {},
    now?: Date,
  ): boolean | { ok: false; reason: "scoped" } {
    return this.once(mutation, "placeTask", () => {
      return this.transact(() => {
        const external = this.db
          .prepare("SELECT external_id, repo FROM task_ref WHERE id = ?")
          .get(taskRef);
        const already = external === undefined || external["repo"] === null ? null : String(external["repo"]);
        if (external !== undefined) {
          const scoped = this.db
            .prepare("SELECT 1 AS hit FROM task_scope WHERE task_id = ?")
            .get(String(external["external_id"]));
          if (scoped !== undefined && already !== repo) {
            return { ok: false as const, reason: "scoped" as const };
          }
        }
        const { changes } = this.db
          .prepare("UPDATE task_ref SET repo = ? WHERE id = ?")
          .run(repo, taskRef);
        // Filing speaks once the project is known (Telegram task updates):
        // the FIRST placement is the moment a task becomes deliverable to
        // that project's phones, whichever door filed it — console form,
        // CLI add, a proposal, a revision, a routine firing, an external
        // mirror. A same-repo repeat changes nothing and says nothing.
        if (Number(changes) > 0 && external !== undefined && already === null) {
          const taskId = String(external["external_id"]);
          const task = this.db.prepare("SELECT title FROM task WHERE id = ?").get(taskId);
          const title = task === undefined ? taskId : String(task["title"]);
          this.noteLifecycle(
            { taskRef, kind: "task-filed", identity: `t${taskRef}`, subject: `New task: ${lifecycleWords(title, 80)}`, body: "Filed and waiting in the queue.", link: chatControlHref("task", taskId) },
            now ?? mutation.at ?? new Date(),
          );
        }
        return Number(changes) > 0;
      });
    });
  }

  /**
   * The newest moment a provider provably worked here: a stamped, concluded
   * success. Historical proof only — it says "was authenticated then",
   * never "is authenticated now".
   */
  providerLastSuccess(provider: string): string | null {
    const row = this.db
      .prepare(
        `SELECT MAX(started_at) AS at FROM run
          WHERE provider = ? AND provider_started_at IS NOT NULL
            AND outcome IN ('built','parked','no-change')`,
      )
      .get(provider);
    return row?.["at"] === null || row?.["at"] === undefined ? null : String(row["at"]);
  }

  // ---- phase configuration ------------------------------------------------

  /** Installation filing default. Existing approved scopes remain immutable;
   * this is consulted only when a new or rewritten scope resolves. */
  permissionDefault(): { mode: UnattendedPermissionMode; updatedAt: string | null; updatedBy: string | null } {
    const row = this.db.prepare("SELECT mode, updated_at, updated_by FROM permission_default WHERE id = 1").get();
    return {
      mode: row?.["mode"] === "bypassPermissions" ? "bypassPermissions" : "auto",
      updatedAt: row?.["updated_at"] == null ? null : String(row["updated_at"]),
      updatedBy: row?.["updated_by"] == null ? null : String(row["updated_by"]),
    };
  }

  setPermissionDefault(mode: UnattendedPermissionMode, by: string, now: Date): void {
    const before = this.permissionDefault().mode;
    this.db
      .prepare("UPDATE permission_default SET mode = ?, updated_at = ?, updated_by = ? WHERE id = 1")
      .run(mode, now.toISOString(), by);
    const words = (value: UnattendedPermissionMode) => value === "bypassPermissions" ? "Full access" : "Auto";
    this.recordPolicy(by, null, "permission default changed", words(before), words(mode), now);
  }

  /** Installation filing default for evidence depth. It never rewrites an
   * existing scope: that scope already carries the concrete signed choice. */
  qualityDefault(): { mode: QualityMode; updatedAt: string | null; updatedBy: string | null } {
    const row = this.db.prepare("SELECT mode, updated_at, updated_by FROM quality_default WHERE id = 1").get();
    return {
      mode: row?.["mode"] === "strict" ? "strict" : "default",
      updatedAt: row?.["updated_at"] == null ? null : String(row["updated_at"]),
      updatedBy: row?.["updated_by"] == null ? null : String(row["updated_by"]),
    };
  }

  setQualityDefault(mode: QualityMode, by: string, now: Date): void {
    const before = this.qualityDefault().mode;
    this.db
      .prepare("UPDATE quality_default SET mode = ?, updated_at = ?, updated_by = ? WHERE id = 1")
      .run(mode, now.toISOString(), by);
    const words = (value: QualityMode) => value === "strict" ? "Strict / release" : "Default";
    this.recordPolicy(by, null, "quality default changed", words(before), words(mode), now);
  }

  /** One phase's configured agent at one scope, or null. */
  phaseConfig(scope: string, phase: string): { provider: string; model: string | null; updatedAt: string; updatedBy: string } | null {
    const row = this.db
      .prepare("SELECT * FROM phase_config WHERE scope = ? AND phase = ?")
      .get(scope, phase);
    return row === undefined
      ? null
      : {
          provider: String(row["provider"]),
          model: row["model"] === null ? null : String(row["model"]),
          updatedAt: String(row["updated_at"]),
          updatedBy: String(row["updated_by"]),
        };
  }

  listPhaseConfig(scope: string): { phase: string; provider: string; model: string | null; updatedAt: string; updatedBy: string }[] {
    return this.db
      .prepare("SELECT * FROM phase_config WHERE scope = ? ORDER BY phase")
      .all(scope)
      .map(row => ({
        phase: String(row["phase"]),
        provider: String(row["provider"]),
        model: row["model"] === null ? null : String(row["model"]),
        updatedAt: String(row["updated_at"]),
        updatedBy: String(row["updated_by"]),
      }));
  }

  /** Write one complete pair. Audited: who changed spend routing, and when. */
  setPhaseConfig(scope: string, phase: string, provider: string, model: string | null, by: string, now: Date): void {
    const was = this.phaseConfig(scope, phase);
    const words = (agent: { provider: string; model: string | null } | null) => agent === null ? "not set" : `${agent.provider} · ${agent.model ?? "its default model"}`;
    this.recordPolicy(by, scope === "installation" ? null : scope, `agent for ${phase} changed`, words(was), words({ provider, model }), now);
    this.db
      .prepare(
        `INSERT INTO phase_config (scope, phase, provider, model, updated_at, updated_by)
         VALUES (?, ?, ?, ?, ?, ?)
         ON CONFLICT (scope, phase) DO UPDATE SET
           provider = excluded.provider, model = excluded.model,
           updated_at = excluded.updated_at, updated_by = excluded.updated_by`,
      )
      .run(scope, phase, provider, model, now.toISOString(), by);
  }

  /** The ordered FALLBACK entries after the base, for a scope's build
   * phase (v30). Each entry: {provider, model, authMode, repairModel?}.
   * Returns [] when none configured — a chain-of-one is the base alone. */
  fallbackConfig(scope: string): { provider: string; model: string; authMode: "subscription" | "api-key"; repairModel?: string }[] {
    const read = this.readFallbackConfig(scope);
    return read.ok ? read.entries : [];
  }

  /**
   * The configured fallback entries, or the words for why the row on file
   * cannot be read (v48): a row that EXISTS but is not a list of
   * well-shaped entries — corrupt JSON, a non-list, an entry missing its
   * provider, model, or auth mode — is a stated problem, never an empty
   * list. Filing a scope under such a row refuses in these words rather
   * than silently sealing a single-profile approval the operator did not
   * configure; the chain the person believes they set never shrinks to
   * nothing behind their back.
   */
  fallbackConfigProblem(scope: string): string | null {
    const read = this.readFallbackConfig(scope);
    return read.ok ? null : read.problem;
  }

  private readFallbackConfig(scope: string): { ok: true; entries: { provider: string; model: string; authMode: "subscription" | "api-key"; repairModel?: string }[] } | { ok: false; problem: string } {
    const row = this.db.prepare("SELECT entries_json FROM fallback_config WHERE scope = ? AND phase = 'build'").get(scope);
    if (row === undefined) return { ok: true, entries: [] };
    let parsed: unknown;
    try {
      parsed = JSON.parse(String(row["entries_json"]));
    } catch {
      return { ok: false, problem: `the fallback configuration for ${scope} is not valid JSON — set it again with \`config set fallback\`, or clear it` };
    }
    if (!Array.isArray(parsed)) return { ok: false, problem: `the fallback configuration for ${scope} is not a list of entries — set it again with \`config set fallback\`, or clear it` };
    // A PRESENT row carries one to three entries (atomic authority
    // closure) — the very bound `config set fallback` enforces. An empty
    // list is not "no fallback": it is a row this code never wrote, and
    // the chain the operator believes they set must not shrink to nothing
    // behind their back; too many entries is the same corruption.
    if (parsed.length < FALLBACK_ENTRIES_MIN || parsed.length > FALLBACK_ENTRIES_MAX) {
      return { ok: false, problem: `the fallback configuration for ${scope} carries ${parsed.length} entries, not ${FALLBACK_ENTRIES_MIN} to ${FALLBACK_ENTRIES_MAX} — set it again with \`config set fallback\`, or clear it` };
    }
    const entries: { provider: string; model: string; authMode: "subscription" | "api-key"; repairModel?: string }[] = [];
    for (const [index, entry] of parsed.entries()) {
      if (entry === null || typeof entry !== "object" || Array.isArray(entry)) return { ok: false, problem: `fallback entry ${index + 1} for ${scope} is not an object — set the chain again with \`config set fallback\`` };
      const e = entry as Record<string, unknown>;
      // EXACT (raw authority repair): exactly the keys this code writes, a
      // provider this build knows, an exact model id (the shape every
      // argv accepts), an optional exact repair model id, and one of the
      // two auth modes — a row carrying anything else is a stated problem,
      // never the known part of itself.
      if (["provider", "model", "authMode"].some(key => !(key in e))) {
        return { ok: false, problem: `fallback entry ${index + 1} for ${scope} is malformed (provider, model, and auth mode are required) — set the chain again with \`config set fallback\`` };
      }
      if (!exactKeys(e, ["provider", "model", "authMode"], ["repairModel"])) {
        return { ok: false, problem: `fallback entry ${index + 1} for ${scope} carries a key this code never writes — set the chain again with \`config set fallback\`` };
      }
      if (typeof e["provider"] !== "string" || !isProviderId(e["provider"])) {
        return { ok: false, problem: `fallback entry ${index + 1} for ${scope} names an unknown provider — set the chain again with \`config set fallback\`` };
      }
      if (!exactModelId(e["model"]) || (e["repairModel"] !== undefined && !exactModelId(e["repairModel"]))) {
        return { ok: false, problem: `fallback entry ${index + 1} for ${scope} names a model that is not an exact model id — set the chain again with \`config set fallback\`` };
      }
      if (e["authMode"] !== "subscription" && e["authMode"] !== "api-key") {
        return { ok: false, problem: `fallback entry ${index + 1} for ${scope} is malformed (provider, model, and auth mode are required) — set the chain again with \`config set fallback\`` };
      }
      entries.push({ provider: e["provider"], model: e["model"], authMode: e["authMode"], ...(e["repairModel"] !== undefined ? { repairModel: e["repairModel"] } : {}) });
    }
    return { ok: true, entries };
  }

  setFallbackConfig(
    scope: string,
    entries: { provider: string; model: string; authMode: "subscription" | "api-key"; repairModel?: string }[],
    by: string,
    now: Date,
  ): void {
    // The store writes only what it will read back (atomic authority
    // closure): a present row carries one to three entries, never none.
    if (entries.length < FALLBACK_ENTRIES_MIN || entries.length > FALLBACK_ENTRIES_MAX) {
      throw new Error(`a fallback chain carries ${FALLBACK_ENTRIES_MIN} to ${FALLBACK_ENTRIES_MAX} entries, not ${entries.length} — clear the configuration to have none`);
    }
    this.db
      .prepare(
        `INSERT INTO fallback_config (scope, phase, entries_json, updated_at, updated_by)
         VALUES (?, 'build', ?, ?, ?)
         ON CONFLICT (scope, phase) DO UPDATE SET
           entries_json = excluded.entries_json, updated_at = excluded.updated_at, updated_by = excluded.updated_by`,
      )
      .run(scope, JSON.stringify(entries), now.toISOString(), by);
  }

  clearFallbackConfig(scope: string): boolean {
    return Number(this.db.prepare("DELETE FROM fallback_config WHERE scope = ? AND phase = 'build'").run(scope).changes) > 0;
  }

  clearPhaseConfig(scope: string, phase: string): boolean {
    const { changes } = this.db
      .prepare("DELETE FROM phase_config WHERE scope = ? AND phase = ?")
      .run(scope, phase);
    return Number(changes) > 0;
  }

  // ---- phase routing (v47) -----------------------------------------------

  /** The operator's named STRONG candidate for a phase at a scope, or null.
   * Read by the routing policy only — a phase_config row stays the routine
   * tier, so every pre-v47 resolution is untouched. */
  phaseTierConfig(scope: string, phase: string, tier: "light" | "strong"): { provider: string; model: string | null; updatedAt: string; updatedBy: string } | null {
    const row = this.db.prepare("SELECT * FROM phase_tier_config WHERE scope = ? AND phase = ? AND tier = ?").get(scope, phase, tier);
    if (row === undefined) return null;
    return {
      provider: String(row["provider"]),
      model: row["model"] === null ? null : String(row["model"]),
      updatedAt: String(row["updated_at"]),
      updatedBy: String(row["updated_by"]),
    };
  }

  listPhaseTierConfig(scope: string): { phase: string; tier: "light" | "strong"; provider: string; model: string | null; updatedAt: string; updatedBy: string }[] {
    return this.db
      .prepare("SELECT * FROM phase_tier_config WHERE scope = ? ORDER BY phase, tier")
      .all(scope)
      .map(row => ({
        phase: String(row["phase"]),
        tier: row["tier"] === "light" ? ("light" as const) : ("strong" as const),
        provider: String(row["provider"]),
        model: row["model"] === null ? null : String(row["model"]),
        updatedAt: String(row["updated_at"]),
        updatedBy: String(row["updated_by"]),
      }));
  }

  setPhaseTierConfig(scope: string, phase: string, tier: "light" | "strong", provider: string, model: string | null, by: string, now: Date): void {
    // A small change makes no plan and repairs resume the builder: only the build phase has a light agent.
    if (tier === "light" && phase !== "build") throw new Error(`a light agent is for the build phase only, not ${phase}`);
    this.db
      .prepare(
        `INSERT INTO phase_tier_config (scope, phase, tier, provider, model, updated_at, updated_by)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT (scope, phase, tier) DO UPDATE SET provider = excluded.provider, model = excluded.model,
                                                        updated_at = excluded.updated_at, updated_by = excluded.updated_by`,
      )
      .run(scope, phase, tier, provider, model, now.toISOString(), by);
  }

  clearPhaseTierConfig(scope: string, phase: string, tier: "light" | "strong"): boolean {
    const { changes } = this.db.prepare("DELETE FROM phase_tier_config WHERE scope = ? AND phase = ? AND tier = ?").run(scope, phase, tier);
    return Number(changes) > 0;
  }

  /** A tier's candidates on other providers at a scope, in provider order (sized routing). */
  phaseTierAlternates(scope: string, phase: string, tier: CandidateTier): { provider: string; model: string; updatedAt: string; updatedBy: string }[] {
    return this.db
      .prepare("SELECT * FROM phase_tier_alternate WHERE scope = ? AND phase = ? AND tier = ?")
      .all(scope, phase, tier)
      .map(row => ({ provider: String(row["provider"]), model: String(row["model"]), updatedAt: String(row["updated_at"]), updatedBy: String(row["updated_by"]) }))
      .sort((a, b) => PROVIDER_ID_LIST.indexOf(a.provider as ProviderId) - PROVIDER_ID_LIST.indexOf(b.provider as ProviderId));
  }

  listPhaseTierAlternates(scope: string): { phase: string; tier: CandidateTier; provider: string; model: string; updatedAt: string; updatedBy: string }[] {
    return this.db
      .prepare("SELECT * FROM phase_tier_alternate WHERE scope = ? ORDER BY phase, tier, provider")
      .all(scope)
      .map(row => ({
        phase: String(row["phase"]),
        tier: (row["tier"] === "light" ? "light" : row["tier"] === "strong" ? "strong" : "routine") as CandidateTier,
        provider: String(row["provider"]),
        model: String(row["model"]),
        updatedAt: String(row["updated_at"]),
        updatedBy: String(row["updated_by"]),
      }));
  }

  /** Name this provider's candidate on a tier, beside the tier's own (one per provider; a second replaces the first). */
  setPhaseTierAlternate(scope: string, phase: "plan" | "build", tier: CandidateTier, provider: string, model: string, by: string, now: Date): void {
    if (tier === "light" && phase !== "build") throw new Error(`a light agent is for the build phase only, not ${phase}`);
    this.db
      .prepare(
        `INSERT INTO phase_tier_alternate (scope, phase, tier, provider, model, updated_at, updated_by)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT (scope, phase, tier, provider) DO UPDATE SET model = excluded.model,
                                                                  updated_at = excluded.updated_at, updated_by = excluded.updated_by`,
      )
      .run(scope, phase, tier, provider, model, now.toISOString(), by);
  }

  /** Remove one provider's candidate from a tier, or every one when no provider is named; how many went. */
  clearPhaseTierAlternates(scope: string, phase: string, tier: CandidateTier, provider: string | null): number {
    const { changes } = provider === null
      ? this.db.prepare("DELETE FROM phase_tier_alternate WHERE scope = ? AND phase = ? AND tier = ?").run(scope, phase, tier)
      : this.db.prepare("DELETE FROM phase_tier_alternate WHERE scope = ? AND phase = ? AND tier = ? AND provider = ?").run(scope, phase, tier, provider);
    return Number(changes);
  }

  /** Each provider's plan headroom right now, from the latest readings of
   * its usage windows — the routing policy's headroom input at filing. */
  planHeadroom(now: Date): ProviderRoom[] {
    return headroomFrom(this.providerLimits(), now);
  }

  /** How far the plane may carry this repo's results unattended: a live
   * automerge mode, a publication grant whose merges wait for a person, or
   * nothing. A signed routing input, read at filing. */
  publicationAuthorityOf(repo: string | null, now: Date): PublicationAuthority {
    if (repo === null) return "none";
    const mode = this.activeMode(repo, now);
    if (mode !== null && modeTermsFromJson(mode.termsJson)?.publication === "automerge") return "automerge";
    return this.publicationGrantFor(repo) === null ? "none" : "notify";
  }

  /**
   * THE ROUTE EDIT (v47): declare the task's risk, override one phase to an
   * exact agent, or clear an override — ONE authenticated transaction that
   * re-proves the editor's authority, CAS-checks the scope digest the
   * editor saw (a string to match, null = "I saw no scope", undefined =
   * no expectation), records the change, reconciles the planner pin with a
   * plan override (the override IS the pin from then on; clearing it
   * clears the pin), re-files the scope under the same words so the route
   * is recomputed and the prior approval goes stale by digest, and — when
   * a drafted plan came from the old planner — asks for a real re-plan.
   * No claimant can observe a half-updated authority: it is all or
   * nothing, and refused under a live claim or tournament terms.
   */
  editTaskRoute(
    taskRef: number,
    edit: {
      by: string;
      authenticate: () => { ok: true } | { ok: false; reason: string };
      risk?: RiskLevel;
      /** v2: a person's size for the task — it outranks the classifier's. */
      size?: { size: TaskSize; risky: boolean };
      override?: { phase: RouteOverride["phase"]; provider: ProviderId; model: string } | { phase: RouteOverride["phase"]; clear: true };
      expectDigest?: string | null;
      /** v48: the agent must be one of the CONFIGURED, role-valid choices
       * for that role RIGHT NOW — re-proved inside this transaction, so a
       * choice drafted against yesterday's configuration (a card, a form
       * left open) mutates nothing. The console and chat doors set this;
       * the CLI's attributed override is the operator typing exactly. */
      configured?: boolean;
    },
    now: Date,
  ):
    | { ok: true; scope: Scope | null; staled: boolean; replanned: boolean; overrides: RouteOverride[] }
    | { ok: false; reason: "unauthenticated" | "no-task" | "live-claim" | "contest-open" | "changed" | "nothing" | "not-configured"; detail: string; choices?: { provider: string; model: string }[] } {
    return this.transact(() => {
      const authenticated = edit.authenticate();
      if (!authenticated.ok) return { ok: false as const, reason: "unauthenticated" as const, detail: authenticated.reason };
      const ref = this.refForId(taskRef);
      if (ref === null) return { ok: false as const, reason: "no-task" as const, detail: "no such task" };
      if (edit.risk === undefined && edit.override === undefined && edit.size === undefined) return { ok: false as const, reason: "nothing" as const, detail: "nothing to change" };
      if (this.hasLiveClaim(taskRef, now)) return { ok: false as const, reason: "live-claim" as const, detail: "this task is running — the agents cannot change under a live claim" };
      if (this.activeTournamentTerms(taskRef) !== null) return { ok: false as const, reason: "contest-open" as const, detail: "tournament terms are on file — its lanes decide the agents; exclude or settle the contest first" };
      const before = this.getScope(ref.externalId);
      const currentDigest = before?.digest ?? null;
      if (edit.expectDigest !== undefined && edit.expectDigest !== currentDigest) {
        return { ok: false as const, reason: "changed" as const, detail: before === null ? "the scope was removed while you were editing — reload and try again" : "the scope changed while you were editing — reload, read it again, and try again" };
      }
      // THE CONFIGURED-CHOICE PROOF (v48), inside the transaction: the
      // pair must be one of the role's configured choices under the
      // configuration and route that stand at this instant — not the ones
      // a card was drafted against. Nothing is written otherwise.
      if (edit.configured === true && edit.override !== undefined && !("clear" in edit.override)) {
        const routed = routeOfTask(this, ref.externalId, ref, now);
        const offered = agentChoicesFor(this, ref.repo, routed !== null && routed.kind === "route" ? routed.route : null)[edit.override.phase].filter(one => one.selectable);
        const wanted = edit.override;
        if (!offered.some(one => one.provider === wanted.provider && one.model === wanted.model)) {
          const noun = { plan: "planner", build: "builder", repair: "repair", review: "reviewer" }[wanted.phase];
          return {
            ok: false as const,
            reason: "not-configured" as const,
            detail:
              offered.length === 0
                ? `no configured agent can take the ${noun} role for this task right now — configure one first`
                : `${wanted.provider} · ${wanted.model} is not one of the configured agents for the ${noun} right now (${offered.map(one => `${one.provider} · ${one.model}`).join(", ")}) — look again`,
            choices: offered.map(one => ({ provider: one.provider, model: one.model })),
          };
        }
      }
      if (edit.risk !== undefined) {
        this.db.prepare("UPDATE task_ref SET risk_level = ? WHERE id = ?").run(edit.risk, taskRef);
      }
      if (edit.size !== undefined) {
        this.writeSizing(taskRef, { size: edit.size.size, risky: edit.size.risky, source: "person", reason: `set by ${edit.by}` });
      }
      let overrides = ref.routeOverrides ?? [];
      if (edit.override !== undefined) {
        const kept = overrides.filter(one => one.phase !== edit.override!.phase);
        overrides = "clear" in edit.override ? kept : [...kept, { phase: edit.override.phase, provider: edit.override.provider, model: edit.override.model, by: edit.by, at: now.toISOString() }];
        this.db.prepare("UPDATE task_ref SET route_overrides_json = ? WHERE id = ?").run(canonicalOverridesJson(overrides), taskRef);
        // The planner pin and a plan override are ONE authority: an
        // override becomes the pin (a pin would otherwise silently beat
        // it), and clearing the override clears the pin.
        if (edit.override.phase === "plan") {
          if ("clear" in edit.override) this.db.prepare("UPDATE task_ref SET plan_provider = NULL, plan_model = NULL WHERE id = ?").run(taskRef);
          else this.db.prepare("UPDATE task_ref SET plan_provider = ?, plan_model = ? WHERE id = ?").run(edit.override.provider, edit.override.model, taskRef);
        }
      }
      const wasApproved = before !== null && before.approvedAt !== null && before.approvedDigest === before.digest;
      const refiled = before === null ? null : this.refileScope(ref.externalId, now);
      const staled = wasApproved && refiled !== null && refiled.approvedDigest !== refiled.digest;
      // Planning follows a new size, and elevated or high risk always plans — after the re-file, so an approval
      // this edit staled does not refuse the plan request.
      if (edit.size !== undefined || (edit.risk !== undefined && edit.risk !== "routine")) this.planToSizing(taskRef, now);
      // A plan drafted by the previous planner is not relabeled: a plan
      // override (set or cleared) asks for a REAL re-plan.
      let replanned = false;
      if (edit.override !== undefined && edit.override.phase === "plan" && ref.plan === "drafted") {
        this.db.prepare("UPDATE task_ref SET plan = 'requested' WHERE id = ?").run(taskRef);
        replanned = true;
      }
      this.bumpWake();
      return { ok: true as const, scope: refiled, staled, replanned, overrides: overridesFromJson(canonicalOverridesJson(overrides)) ?? [] };
    });
  }

  /** Store a task's size (v2 routing); the next scope filing routes by it. */
  writeSizing(taskRef: number, sizing: TaskSizing): void {
    this.db
      .prepare("UPDATE task_ref SET size = ?, size_risky = ?, size_source = ?, size_reason = ? WHERE id = ?")
      .run(sizing.size, sizing.risky ? 1 : 0, sizing.source, sizing.reason.slice(0, 300), taskRef);
  }

  /** Planning follows the size and risk while nothing has run: a small
   * change at routine risk drops a plan that is only requested; a large or
   * risky one, or any task at elevated or high risk, asks for a plan. A
   * drafted plan is never discarded. */
  private planToSizing(taskRef: number, now: Date): "requested" | "cleared" | null {
    const ref = this.refForId(taskRef);
    if (ref === null || ref.repo === null || ref.deliverable === "report") return null;
    const sizing = ref.sizing ?? null;
    if (makesNoPlan(sizing, ref.riskLevel ?? "routine")) {
      if (ref.plan !== "requested" || this.hasLiveClaim(taskRef, now)) return null;
      this.db.prepare("UPDATE task_ref SET plan = NULL WHERE id = ? AND plan = 'requested'").run(taskRef);
      return "cleared";
    }
    const wanted = (ref.riskLevel ?? "routine") !== "routine" || (sizing !== null && (sizing.size === "large" || sizing.risky));
    if (wanted && ref.plan === null) return this.requestPlan(taskRef, now).ok ? "requested" : null;
    return null;
  }

  /**
   * The classifier's answer, applied after filing (v2 routing): filing never
   * waits for it, so its size lands here — only while the task is still
   * unapproved, unclaimed, and not sized by a person. The scope is re-filed
   * under its own words so the route (and its digest) carries the size, and
   * planning follows it unless the filer chose planning explicitly.
   */
  applySizing(
    taskId: string,
    sizing: TaskSizing,
    options: { followPlanning: boolean },
    now: Date,
  ): { ok: true; changed: boolean; planning: "requested" | "cleared" | null } | { ok: false; reason: "no-task" | "person" | "running" | "approved" } {
    return this.transact(() => {
      const ref = this.lookupRef(taskId);
      if (ref === null) return { ok: false as const, reason: "no-task" as const };
      if (ref.sizing?.source === "person") return { ok: false as const, reason: "person" as const };
      if (this.hasLiveClaim(ref.id, now)) return { ok: false as const, reason: "running" as const };
      const scope = this.getScope(taskId);
      if (scope !== null && scope.approvedAt !== null && scope.approvedDigest === scope.digest) return { ok: false as const, reason: "approved" as const };
      const before = ref.sizing ?? null;
      if (before !== null && before.size === sizing.size && before.risky === sizing.risky && before.source === sizing.source && before.reason === sizing.reason) {
        return { ok: true as const, changed: false, planning: null };
      }
      this.writeSizing(ref.id, sizing);
      if (scope !== null) this.refileScope(taskId, now);
      const planning = options.followPlanning ? this.planToSizing(ref.id, now) : null;
      this.bumpWake();
      return { ok: true as const, changed: true, planning };
    });
  }

  /** A runner's own non-spending observations, replacing its previous ones
   * per provider. Callers authenticate the runner first (runner.ts). */
  recordProviderReadiness(runner: string, observations: readonly Omit<ReadinessObservation, "runner" | "observedAt">[], now: Date): void {
    this.transact(() => {
      for (const one of observations) {
        this.db
          .prepare(
            `INSERT INTO provider_readiness (runner, provider, state, reason, probe, observed_at) VALUES (?, ?, ?, ?, ?, ?)
             ON CONFLICT (runner, provider) DO UPDATE SET state = excluded.state, reason = excluded.reason,
                                                          probe = excluded.probe, observed_at = excluded.observed_at`,
          )
          .run(runner, one.provider, one.state, one.reason, one.probe, now.toISOString());
      }
    });
  }

  providerReadiness(runner: string): ReadinessObservation[] {
    return this.db
      .prepare("SELECT * FROM provider_readiness WHERE runner = ? ORDER BY provider")
      .all(runner)
      .map(row => ({
        runner: String(row["runner"]),
        provider: String(row["provider"]) as ProviderId,
        state: String(row["state"]) as ReadinessState,
        reason: String(row["reason"]),
        probe: String(row["probe"]),
        observedAt: String(row["observed_at"]),
      }));
  }

  /** ONE runner's answer for one provider — the dispatch gate's question.
   * null = that runner never reported it (unknown, never upgraded). */
  runnerReadinessOf(runner: string, provider: string): ReadinessObservation | null {
    const row = this.db.prepare("SELECT * FROM provider_readiness WHERE runner = ? AND provider = ?").get(runner, provider);
    if (row === undefined) return null;
    return {
      runner: String(row["runner"]),
      provider: String(row["provider"]) as ProviderId,
      state: String(row["state"]) as ReadinessState,
      reason: String(row["reason"]),
      probe: String(row["probe"]),
      observedAt: String(row["observed_at"]),
    };
  }

  /**
   * The readiness a task's surfaces show: the assigned runner's own report
   * when the task is reserved for one, else the freshest report among
   * live, unretired runners bound to the repo. A provider no runner has
   * reported is unknown — said, never guessed.
   */
  readinessLookupFor(repo: string | null, assignedRunner: string | null, now: Date): ReadinessLookup {
    const rows = this.db
      .prepare(
        `SELECT pr.*, runner.heartbeat_at AS heartbeat_at, runner.repos AS repos FROM provider_readiness pr
           JOIN runner ON runner.name = pr.runner AND runner.retired_at IS NULL
          ORDER BY pr.observed_at DESC`,
      )
      .all() as Record<string, unknown>[];
    const liveness = 3 * 60_000;
    const alive = (row: Record<string, unknown>): boolean => now.getTime() - Date.parse(String(row["heartbeat_at"])) <= liveness;
    // Bound runners' observations, a live runner's first, freshest first
    // within each — a stale report still speaks (its time is shown), but
    // never over a runner that is here now.
    const eligible = rows
      .filter(row => {
        if (assignedRunner !== null) return String(row["runner"]) === assignedRunner;
        const repos = readJsonArray(row["repos"]);
        return repo === null || repos.includes(repo);
      })
      .sort((a, b) => Number(alive(b)) - Number(alive(a)));
    return provider => {
      const row = eligible.find(one => String(one["provider"]) === provider);
      if (row === undefined) return null;
      return {
        state: String(row["state"]) as ReadinessState,
        reason: String(row["reason"]),
        runner: String(row["runner"]),
        observedAt: String(row["observed_at"]),
        probe: String(row["probe"]),
      };
    };
  }

  /**
   * The ADMISSION PROOF for one route stamp (v48), in words or null.
   * Shape first (a malformed stamp proves nothing), then phase against
   * role, then exact provider and model against the run, then provenance
   * against the authority the task holds RIGHT NOW, inside the caller's
   * transaction:
   *
   *   recommended / override / pinned — the sealed route's digest and that
   *     phase's exact leg. A planner may also run under the working
   *     proposed route, or — with no scope yet — the live recommendation,
   *     re-derived here from durable state. Nothing else.
   *   fallback — the task's approved chain: the digest is the sealed
   *     route's (or the chain's, when no route is sealed) and the pair is
   *     a NON-primary entry of that chain (its repair model for a repair).
   *   legacy — only a row proven to predate routing, a task with no scope,
   *     a tournament lane, or an attended session; never a routed row.
   */
  private routeAdmissionProblem(
    run: {
      taskRef: number;
      role: Run["role"] | "scout";
      provider: string;
      model: string | null;
      contestant: number | null;
      /** The chain entry the run is bound to, when it is: a fallback stamp
       * must name THIS entry's exact pair — never any entry that happens to
       * share a provider and model under a different auth mode or repair
       * model. */
      chain?: { index: number; entryDigest: string } | null;
    },
    stamp: unknown,
    now: Date,
  ): string | null {
    const shape = routeStampProblem(stamp);
    if (shape !== null) return shape;
    const leg = stamp as RouteStamp;
    const phase = phaseOfRole(run.role);
    if (leg.phase !== phase) return `a ${run.role} run spends as the ${phase} leg, but the stamp says ${leg.phase}`;
    if (leg.provider !== run.provider) return `the stamp names ${leg.provider} but the run would spend as ${run.provider}`;
    if (leg.model !== run.model) return `the stamp names model ${leg.model ?? "(none)"} but the run would spend as ${run.model ?? "(none)"}`;
    const ref = this.refForId(run.taskRef);
    if (ref === null) return "no such task";
    const taskId = ref.externalId;
    const sealed = this.sealedRouteOf(taskId);
    const scope = this.getScope(taskId);
    const routed = scope !== null && scope.routeEra != null;
    const sameLeg = (route: PhaseRoute): string | null => {
      const expected = legOf(route, phase);
      if (leg.routeDigest !== routeDigestOf(route)) return `the stamp's route ${leg.routeDigest} is not the governing route ${routeDigestOf(route)}`;
      if (expected.provider !== leg.provider || expected.model !== leg.model || expected.chosen !== leg.chosen) {
        return `the governing route's ${phase} leg is ${expected.provider} · ${expected.model} [${expected.chosen}], not ${leg.provider} · ${leg.model ?? "(none)"} [${leg.chosen}]`;
      }
      return null;
    };
    if (leg.chosen === "recommended" || leg.chosen === "override" || leg.chosen === "pinned") {
      if (sealed.ok) return sameLeg(sealed.route);
      if (phase !== "plan") return `nothing spends as a ${leg.chosen} ${phase} leg without a sealed route — ${sealed.detail}`;
      // A planner runs before any approval: under the working proposed
      // route when a scope exists, else the live recommendation.
      if (scope !== null) {
        if (!routed) return "a row that predates agent routing plans as legacy, never as a routed leg";
        // THE STRICT WORKING PROJECTION (final authority closure): a
        // planner's proposed route is believed only as the whole scope
        // re-proves — exact terms, profile, chain, route, parity, digest,
        // and auth mode — never parsed from the route column alone.
        const working = this.workingPlanRouteOf(taskId);
        if (!working.ok) return working.problem;
        return sameLeg(working.route);
      }
      // A task with NO scope holds no route anybody filed (final authority
      // closure): its planner presents the bare word `legacy` for the pair
      // it spends as, never a live recommendation re-derived here.
      return "a task with no scope plans as the word legacy — nothing spends as a routed plan leg on it";
    }
    if (leg.chosen === "fallback") {
      const chain = this.approvedChainOf(taskId);
      if (chain === null) return "no approved fallback chain stands for this task — nothing spends as a fallback";
      // No chain-only digest (raw authority repair): a fallback spends
      // under the SEALED route or not at all.
      if (!sealed.ok) return `the chain approval's sealed agent route does not stand (${sealed.detail}) — nothing spends as a fallback under a chain-only digest`;
      const expectedDigest = routeDigestOf(sealed.route);
      if (leg.routeDigest !== expectedDigest) return `the fallback stamp's route ${leg.routeDigest} is not the approved authority ${expectedDigest}`;
      if (phase !== "build" && phase !== "repair") return `an approved fallback entry builds and repairs — it does not ${phase}`;
      const pairOf = (entry: ChainEntry): { provider: string; model: string } => ({
        provider: entry.profile.provider,
        model: phase === "repair" ? (entry.profile.repairModel === "inherit" ? entry.profile.model : entry.profile.repairModel) : entry.profile.model,
      });
      // A run bound to a chain entry spends as THAT entry: the index must
      // exist, its digest must be the bound one, and its pair must be the
      // stamp's. Two entries that share a provider and model but differ in
      // auth mode or repair model are different authorities — a stamp
      // cannot borrow one's pair under the other's binding.
      const bound = run.chain ?? null;
      if (bound !== null) {
        const entry = chain[bound.index];
        if (entry === undefined) return `the run is bound to chain entry ${bound.index}, which the approved chain does not have`;
        if (entryDigestOf(entry) !== bound.entryDigest) return `the run is bound to chain entry ${bound.index} under digest ${bound.entryDigest}, but the approved entry there is ${entryDigestOf(entry)}`;
        if (bound.index === 0) return `${leg.provider} · ${leg.model ?? "(none)"} is the chain's primary entry — it spends as the sealed build leg, not as a fallback`;
        const pair = pairOf(entry);
        if (pair.provider !== leg.provider || pair.model !== leg.model) return `the bound chain entry ${bound.index} is ${pair.provider} · ${pair.model}, not ${leg.provider} · ${leg.model ?? "(none)"}`;
        return null;
      }
      // Unbound: the pair must name exactly ONE non-primary entry — an
      // ambiguous pair (duplicates differing in auth mode or repair model)
      // proves nothing, because the stamp cannot say which one spends.
      const matches = chain.map((entry, index) => ({ entry, index })).filter(({ entry }) => {
        const pair = pairOf(entry);
        return pair.provider === leg.provider && pair.model === leg.model;
      });
      if (matches.length === 0) return `${leg.provider} · ${leg.model ?? "(none)"} is not an entry of the approved fallback chain`;
      if (matches.some(one => one.index === 0)) return `${leg.provider} · ${leg.model ?? "(none)"} is the chain's primary entry — it spends as the sealed build leg, not as a fallback`;
      if (matches.length > 1) return `${leg.provider} · ${leg.model ?? "(none)"} names ${matches.length} entries of the approved fallback chain (they differ in auth mode or repair model) — a fallback run is bound to exactly one entry`;
      return null;
    }
    // legacy
    if (leg.routeDigest !== "legacy" && !leg.routeDigest.startsWith("profile:")) return `a legacy stamp names a profile digest or the word legacy, not ${leg.routeDigest}`;
    // A CONTEST LANE spends under its race-approved profile, exactly (v48
    // integrity): the lane is this task's, the stamp names that profile's
    // digest, and a build pair is the lane's own.
    if (run.contestant !== null) {
      const lane = this.getContestant(run.contestant);
      const contest = lane === null ? null : this.getContest(lane.contest);
      if (lane === null || contest === null || contest.taskRef !== run.taskRef) return `contestant ${run.contestant} is not one of this task's racing agents`;
      // The STORED sealed profile alone (atomic authority closure): no
      // synthesized profile is accepted beside it.
      if (lane.profile == null) return `contestant ${lane.id} carries no sealed profile — nothing spends on the lane`;
      const laneProblem = laneAuthorityProblem(lane);
      if (laneProblem !== null) return laneProblem;
      if (leg.routeDigest !== `profile:${profileDigestOf(lane.profile)}`) return `a contest lane spends under its race-approved profile, not ${leg.routeDigest}`;
      if ((phase === "build" || phase === "repair") && (leg.provider !== lane.provider || leg.model !== (phase === "repair" ? lane.repairModel : lane.model))) {
        return `the racing agent is ${lane.provider} · ${phase === "repair" ? lane.repairModel : lane.model}, not ${leg.provider} · ${leg.model ?? "(none)"}`;
      }
      return null;
    }
    // An ATTENDED SESSION spends under the authorization's pinned profile,
    // exactly (v48 integrity), when the authorization pins one; an
    // authorization that pins none falls to the ordinary rules below and
    // spends nothing (the coordinator's proof refuses it).
    const open = this.openAuthorizationFor(run.taskRef);
    if (open !== null) {
      let pinned: ExecutionProfile | null = null;
      try {
        const terms = JSON.parse(open.termsJson) as { profileJson?: unknown };
        pinned = profileFromJson(typeof terms.profileJson === "string" ? terms.profileJson : null);
      } catch {
        pinned = null;
      }
      if (pinned !== null) {
        if (leg.routeDigest !== `profile:${profileDigestOf(pinned)}`) return `an attended session spends under the authorization's pinned profile profile:${profileDigestOf(pinned)}, not ${leg.routeDigest}`;
        const expectedModel = phase === "repair" ? (pinned.repairModel === "inherit" ? pinned.model : pinned.repairModel) : pinned.model;
        if ((phase === "build" || phase === "repair") && (leg.provider !== pinned.provider || leg.model !== expectedModel)) {
          return `the authorization pins ${pinned.provider} · ${expectedModel}, not ${leg.provider} · ${leg.model ?? "(none)"}`;
        }
        return null;
      }
    }
    if (routed) {
      return sealed.ok ? "a sealed agent route governs this task — nothing spends as legacy under it" : "this task is filed under agent routing — nothing spends as legacy on it";
    }
    // EXACT legacy authority (v48 authority repair): an ordinary run on a pre-routing row
    // names the very profile that governs it — the sealed profile's digest
    // (the bound chain entry's for a chain-bound run), and for a build or
    // repair its exact pair — or nothing. The bare word `legacy` belongs to
    // a task with no scope at all.
    if (scope === null) return leg.routeDigest === "legacy" ? null : "a task with no scope spends as the word legacy, not under a profile digest";
    const chain = this.approvedChainOf(taskId);
    const boundEntry = run.chain != null && chain !== null ? chain[run.chain.index] : undefined;
    if (run.chain != null && (chain === null || boundEntry === undefined || entryDigestOf(boundEntry) !== run.chain.entryDigest)) {
      return `the run is bound to chain entry ${run.chain.index}, which the approved chain does not carry under that digest`;
    }
    if (run.chain != null && run.chain.index > 0) {
      return "this pre-routing chain approval seals no agent route — nothing spends as a fallback under a chain-only digest; re-file the scope and approve it again";
    }
    const approved = scope.termsProblem == null && scope.approvedAt !== null && scope.approvedDigest !== null && scope.approvedDigest === scope.digest;
    const governing = boundEntry !== undefined ? boundEntry.profile : approved ? (scope.approvedProfile ?? null) : null;
    if (governing === null) return "no sealed profile governs this pre-routing row — nothing spends as legacy on it";
    const expected = `profile:${profileDigestOf(governing)}`;
    if (leg.routeDigest !== expected) return `the legacy stamp names ${leg.routeDigest}, but the sealed profile is ${expected}`;
    if (phase === "build" || phase === "repair") {
      const expectedModel = phase === "repair" ? (governing.repairModel === "inherit" ? governing.model : governing.repairModel) : governing.model;
      if (governing.provider !== leg.provider || expectedModel !== leg.model) {
        return `the sealed profile's ${phase} agent is ${governing.provider} · ${expectedModel}, not ${leg.provider} · ${leg.model ?? "(none)"}`;
      }
    }
    return null;
  }

  /**
   * Route provenance per run (v47), IMMUTABLE and written ONCE, inside the
   * run's own admission transaction (v48 integrity): there is no late
   * stamp — a run and its route are one fact, or there is no run. The
   * proof happened in the admission that calls this; a row that already
   * carries provenance is an invariant violation, thrown so the enclosing
   * admission rolls back.
   */
  private writeRunRoute(run: number, leg: RouteStamp, now: Date): void {
    const existing = this.runRoute(run);
    if (existing !== null) throw new Error(`run #${run} already carries route provenance — provenance is written once, at admission`);
    const inserted = this.db
      .prepare(
        `INSERT INTO run_route (run, route_digest, phase, provider, model, chosen, stamped_at)
         SELECT ?, ?, ?, ?, ?, ?, ? WHERE EXISTS (SELECT 1 FROM run WHERE id = ?)`,
      )
      .run(run, leg.routeDigest, leg.phase, leg.provider, leg.model, leg.chosen, now.toISOString(), run);
    if (Number(inserted.changes) === 0) throw new Error(`run ${run} is not an open attempt — nothing spends without a run record that will outlive it`);
  }

  runRoute(run: number): (RouteStamp & { stampedAt: string }) | null {
    const row = this.db.prepare("SELECT * FROM run_route WHERE run = ?").get(run);
    if (row === undefined) return null;
    return {
      routeDigest: String(row["route_digest"]),
      phase: String(row["phase"]) as RouteStamp["phase"],
      provider: String(row["provider"]),
      model: row["model"] === null ? null : String(row["model"]),
      chosen: String(row["chosen"]) as RouteStamp["chosen"],
      stampedAt: String(row["stamped_at"]),
    };
  }

  /**
   * The SEALED route, if the approval still stands — or the exact reason
   * there is none. The seal's snapshot is rehydrated strictly and proved
   * to be the one the approved digest binds by re-deriving that digest
   * from the live fields, the sealed target, and this route; its build and
   * repair legs must be the sealed profile's exact pair. A row proven to
   * predate v47 (no route era) answers `legacy` — its sealed profile alone
   * governs; a routed row whose snapshot is missing, unreadable, or does
   * not verify answers `unreadable` — FAIL CLOSED, nothing dispatches on
   * it. A rewritten scope answers `unapproved`.
   */
  sealedRouteOf(taskId: string): { ok: true; route: PhaseRoute } | { ok: false; reason: "no-scope" | "unapproved" | "legacy" | "unreadable"; detail: string } {
    const scope = this.getScope(taskId);
    if (scope === null) return { ok: false, reason: "no-scope", detail: "the task has no scope" };
    // The raw terms first (raw authority repair): a seal over terms that do
    // not read back exactly is no seal — nothing dispatches on it.
    if (scope.termsProblem != null) return { ok: false, reason: "unreadable", detail: `the scope's stored terms cannot be read exactly (${scope.termsProblem}) — re-file the scope and approve it again` };
    if (scope.approvedAt === null || scope.approvedDigest === null || scope.approvedDigest !== scope.digest) {
      return { ok: false, reason: "unapproved", detail: scope.approvedAt === null ? "the scope is not approved" : "the scope was approved and then changed — approve it again" };
    }
    if (scope.routeEra == null) {
      return { ok: false, reason: "legacy", detail: "approved before agent routing existed — the sealed agent profile alone governs the build" };
    }
    const route = routeFromJson(scope.approvedRouteJson ?? null);
    if (route === null) {
      return { ok: false, reason: "unreadable", detail: scope.approvedRouteJson == null ? "the approval sealed no agent route — re-file the scope and approve it again" : "the approval's sealed agent route cannot be read — re-file the scope and approve it again" };
    }
    const fields = { goal: scope.goal, outOfScope: scope.outOfScope, touches: scope.touches, budgetMicrousd: scope.budgetMicrousd, acceptance: scope.acceptance, candidate: scope.candidate ?? null, qualityMode: scope.qualityMode ?? "default" };
    const chain = scope.approvalKind === "chain" ? chainFromJson(scope.approvedChainJson ?? null) : null;
    const target = chain !== null ? { chain } : (scope.approvedProfile ?? null);
    if (target === null) return { ok: false, reason: "unreadable", detail: "the approval sealed no agent profile — re-file the scope and approve it again" };
    if (digestOf(fields, target, route) !== scope.approvedDigest) {
      return { ok: false, reason: "unreadable", detail: "the sealed agent route does not verify against the approval — re-file the scope and approve it again" };
    }
    const sealedProfile = chain !== null ? chain[0]?.profile ?? null : scope.approvedProfile ?? null;
    if (sealedProfile === null) return { ok: false, reason: "unreadable", detail: "the approval sealed no agent profile — re-file the scope and approve it again" };
    // The profile column mirrors the chain's base entry on a chain
    // approval; a mirror that cannot be read or disagrees is a tampered
    // seal, not a detail to overlook.
    const mirrored = scope.approvedProfile ?? null;
    if (mirrored === null || profileDigestOf(mirrored) !== profileDigestOf(sealedProfile)) {
      return { ok: false, reason: "unreadable", detail: "the approval's sealed agent profile cannot be read or does not match its sealed chain — re-file the scope and approve it again" };
    }
    // The ONE parity rule (atomic authority closure): build and repair
    // legs against the sealed profile, and the route's signed risk and
    // quality against the row's — the same function the working-side
    // projection and the last-mile dispatch proof apply.
    const parity = routeParityProblem(route, sealedProfile, { riskLevel: scope.riskLevel ?? "routine", qualityMode: scope.qualityMode ?? "default" });
    if (parity !== null) {
      return { ok: false, reason: "unreadable", detail: `${parity} — re-file the scope and approve it again` };
    }
    return { ok: true, route };
  }

  /** The sealed route as a plain value: null whenever `sealedRouteOf`
   * refuses, for callers that only need "the route the approval binds". */
  approvedRouteOf(taskId: string): PhaseRoute | null {
    const sealed = this.sealedRouteOf(taskId);
    return sealed.ok ? sealed.route : null;
  }

  /** Pin a task's agent — the fire transaction's stamp; flags never override it. */
  pinTaskAgent(taskRef: number, provider: string, model: string | null): void {
    this.db
      .prepare("UPDATE task_ref SET agent_provider = ?, agent_model = ? WHERE id = ?")
      .run(provider, model, taskRef);
  }

  // ---- routines -----------------------------------------------------------

  /**
   * File a standing order, unapproved. The digest is computed by the caller
   * (routineDigestOf) from exactly the terms stored here; approval later
   * binds to it. Nothing fires until a person agrees to the template.
   */
  createRoutine(
    spec: {
      name: string;
      repo: string;
      goal: string;
      outOfScope: string | null;
      touches: string[];
      acceptance: AcceptanceCriterion[];
      requirements: string[];
      schedule: string;
      singleFlight: boolean;
      costCeilingUsd: number | null;
      budgetPerRunMicrousd?: number | null;
      digest: string;
      /** Immutable provenance (v12), same contract as createConsoleTask's. */
      filedVia?: string;
      /** v102: who made it; its instances are filed as theirs. */
      createdBy?: string | null;
      /** v24: resolved at filing by the caller who computed the digest —
       * stored verbatim so digest and profile can never disagree. */
      profile?: ExecutionProfile;
      /** v48: the four-role route the digest binds, computed by the same
       * caller from the same configuration — stored verbatim. */
      route?: PhaseRoute;
    },
    now: Date,
  ): { ok: true; id: number } | { ok: false; reason: "duplicate" } {
    return this.transact(() => {
      const existing = this.db.prepare("SELECT 1 AS hit FROM routine WHERE name = ?").get(spec.name);
      if (existing !== undefined) return { ok: false as const, reason: "duplicate" as const };
      const stamp = now.toISOString();
      const inserted = this.db
        .prepare(
          `INSERT INTO routine
             (name, repo, goal, out_of_scope, touches, requirements, schedule,
              single_flight, cost_ceiling_usd, budget_per_run_microusd, digest, created_at, updated_at, filed_via,
              profile_json, digest_version, acceptance_json, route_json)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          spec.name,
          spec.repo,
          spec.goal,
          spec.outOfScope,
          JSON.stringify(spec.touches),
          JSON.stringify(spec.requirements),
          spec.schedule,
          spec.singleFlight ? 1 : 0,
          spec.costCeilingUsd,
          spec.budgetPerRunMicrousd ?? null,
          spec.digest,
          stamp,
          stamp,
          spec.filedVia ?? null,
          spec.profile === undefined ? null : canonicalProfileJson(spec.profile),
          spec.profile === undefined ? 1 : 2,
          spec.acceptance.length === 0 ? null : JSON.stringify(spec.acceptance),
          spec.route === undefined ? null : canonicalRouteJson(spec.route),
        );
      if (spec.createdBy != null && spec.createdBy !== "") this.db.prepare("UPDATE routine SET created_by = ? WHERE id = ?").run(spec.createdBy, Number(inserted.lastInsertRowid));
      return { ok: true as const, id: Number(inserted.lastInsertRowid) };
    });
  }

  /**
   * Set-once installation markers (v12). INSERT OR IGNORE is the whole
   * contract: the first write wins forever, there is no update and no
   * delete, so 'demo' can never be quietly unset and 'first-success-at'
   * survives any later pruning of the rows it was derived from.
   */
  recordInstallationFact(key: string, value: string, now: Date): void {
    this.db
      .prepare("INSERT OR IGNORE INTO installation_fact (key, value, created_at) VALUES (?, ?, ?)")
      .run(key, value, now.toISOString());
  }

  installationFact(key: string): string | null {
    const row = this.db.prepare("SELECT value FROM installation_fact WHERE key = ?").get(key);
    return row === undefined ? null : String(row["value"]);
  }

  /** A database stamped as a demo sandbox: every spending or external-effect
   * entry point fails closed on it (adoption review, finding 8). */
  isDemo(): boolean {
    return this.installationFact("demo") !== null;
  }

  // ---- spend defaults (v15) ----------------------------------------------

  setSpendDefaults(
    defaults: { buildPerRunMicrousd: number | null; racePerAgentMicrousd: number | null; raceTotalMicrousd: number | null; raceAgents?: number | null },
    by: string,
    now: Date,
  ): void {
    const before = this.getSpendDefaults();
    this.db
      .prepare(
        `INSERT INTO spend_defaults (id, build_per_run_microusd, race_per_agent_microusd, race_total_microusd, race_agents, updated_at, updated_by)
         VALUES (1, ?, ?, ?, ?, ?, ?)
         ON CONFLICT (id) DO UPDATE SET
           build_per_run_microusd = excluded.build_per_run_microusd,
           race_per_agent_microusd = excluded.race_per_agent_microusd,
           race_total_microusd = excluded.race_total_microusd,
           race_agents = excluded.race_agents,
           updated_at = excluded.updated_at, updated_by = excluded.updated_by`,
      )
      .run(defaults.buildPerRunMicrousd, defaults.racePerAgentMicrousd, defaults.raceTotalMicrousd, defaults.raceAgents ?? null, now.toISOString(), by);
    const dollars = (micro: number | null) => micro === null ? "none" : `$${(micro / 1_000_000).toFixed(2)}`;
    const words = (row: { buildPerRunMicrousd: number | null; racePerAgentMicrousd: number | null; raceTotalMicrousd: number | null } | null) => row === null ? "not set"
      : `per build ${dollars(row.buildPerRunMicrousd)}, per race agent ${dollars(row.racePerAgentMicrousd)}, per race ${dollars(row.raceTotalMicrousd)}`;
    this.recordPolicy(by, null, "spend limits changed", words(before), words(defaults), now);
  }

  getSpendDefaults(): { buildPerRunMicrousd: number | null; racePerAgentMicrousd: number | null; raceTotalMicrousd: number | null; raceAgents: number | null; updatedBy: string } | null {
    const row = this.db.prepare("SELECT * FROM spend_defaults WHERE id = 1").get();
    if (row === undefined) return null;
    const maybe = (key: string): number | null => (row[key] === null || row[key] === undefined ? null : Number(row[key]));
    return {
      buildPerRunMicrousd: maybe("build_per_run_microusd"),
      racePerAgentMicrousd: maybe("race_per_agent_microusd"),
      raceTotalMicrousd: maybe("race_total_microusd"),
      raceAgents: maybe("race_agents"),
      updatedBy: String(row["updated_by"]),
    };
  }

  // ---- tournaments (v14): persistence + the CAS primitives ---------------

  /**
   * File a new terms row: the previous active row (if any) deactivates in
   * the same transaction — rows are immutable, the ACTIVE pointer moves.
   * Approval lands later, by the same ceremony that approves the scope.
   */
  /** Withdraw the standing race: the row survives deactivated, exactly as
   * a superseding filing would leave it — the task returns to the ordinary
   * one-agent path. */
  retractTournamentTerms(taskRef: number): boolean {
    const changed = this.db
      .prepare("UPDATE tournament_terms SET active = 0 WHERE task_ref = ? AND active = 1")
      .run(taskRef);
    return Number(changed.changes) > 0;
  }

  fileTournamentTerms(
    spec: {
      taskRef: number;
      /** v27: absent = 'race' (every historical caller). */
      kind?: "race" | "comparison";
      raceDigest: string;
      agents: { provider: string; model: string; repairModel: string; permissionMode?: UnattendedPermissionMode }[];
      perAgentBudgetMicrousd: number;
      overrunReserveMicrousd: number;
      totalBudgetMicrousd: number;
      priceVersion: number;
      publicationPolicy: string;
    },
    now: Date,
  ): number {
    return this.transact(() => {
      // D1 (external dispatch, finding 40): external work does not race in
      // this release — the STORE refuses, so no forged POST and no future
      // caller can file race terms on a mirror. UI hiding is convenience.
      const external = this.db
        .prepare(
          `SELECT 1 AS hit FROM external_mirror
            JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = external_mirror.local_task_id
           WHERE task_ref.id = ? LIMIT 1`,
        )
        .get(BUILT_IN, spec.taskRef);
      if (external !== undefined) {
        throw new Error("external work races in a follow-up release — file the tournament on a local task");
      }
      const previous = this.db
        .prepare("SELECT id, generation FROM tournament_terms WHERE task_ref = ? AND active = 1")
        .get(spec.taskRef);
      if (previous !== undefined) {
        this.db.prepare("UPDATE tournament_terms SET active = 0 WHERE id = ?").run(Number(previous["id"]));
      }
      const generation = previous === undefined ? 1 : Number(previous["generation"]) + 1;
      const inserted = this.db
        .prepare(
          `INSERT INTO tournament_terms
             (task_ref, generation, active, kind, race_digest, agents, n, per_agent_budget_microusd,
              overrun_reserve_microusd, total_budget_microusd, price_version, retries,
              publication_policy, created_at)
           VALUES (?, ?, 1, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?)`,
        )
        .run(
          spec.taskRef,
          generation,
          spec.kind ?? "race",
          spec.raceDigest,
          JSON.stringify(spec.agents),
          spec.agents.length,
          spec.perAgentBudgetMicrousd,
          spec.overrunReserveMicrousd,
          spec.totalBudgetMicrousd,
          spec.priceVersion,
          spec.publicationPolicy,
          now.toISOString(),
        );
      return Number(inserted.lastInsertRowid);
    });
  }

  activeTournamentTerms(taskRef: number): TournamentTerms | null {
    const row = this.db.prepare("SELECT * FROM tournament_terms WHERE task_ref = ? AND active = 1").get(taskRef);
    return row === undefined ? null : readTournamentTerms(row);
  }

  /** Approval persistence only — the restating ceremony wires in later. */
  approveTournamentTerms(id: number, by: string, sawDigest: string, now: Date): boolean {
    const changed = this.db
      .prepare(
        "UPDATE tournament_terms SET approved_at = ?, approved_by = ?, approved_digest = ? WHERE id = ? AND active = 1 AND race_digest = ?",
      )
      .run(now.toISOString(), by, sawDigest, id, sawDigest);
    return Number(changed.changes) === 1;
  }

  createContest(
    spec: { taskRef: number; terms: number; scopeDigest: string; raceDigest: string; kind?: "race" | "comparison" },
    now: Date,
  ): number {
    const inserted = this.db
      .prepare(
        `INSERT INTO contest (task_ref, terms, state, scope_digest, race_digest, created_at, race_semantics, kind)
         VALUES (?, ?, 'dispatching', ?, ?, ?, 2, ?)`,
      )
      .run(spec.taskRef, spec.terms, spec.scopeDigest, spec.raceDigest, now.toISOString(), spec.kind ?? "race");
    return Number(inserted.lastInsertRowid);
  }

  getContest(id: number): Contest | null {
    const row = this.db.prepare("SELECT * FROM contest WHERE id = ?").get(id);
    return row === undefined ? null : readContest(row);
  }

  /** The one non-finished tournament for a task, when one exists. */
  /** The newest tournament still owed to an operator — open states plus
   * the two that end with nothing pickable and wait for a human verdict. */
  contestNeedingOperator(taskRef: number): Contest | null {
    const row = this.db
      .prepare(
        `SELECT * FROM contest WHERE task_ref = ?
           AND state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted')
         ORDER BY id DESC LIMIT 1`,
      )
      .get(taskRef);
    return row === undefined ? null : readContest(row);
  }

  openContestFor(taskRef: number): Contest | null {
    const row = this.db
      .prepare(
        `SELECT * FROM contest WHERE task_ref = ?
           AND state IN ('dispatching','racing','pick-wait','decision-wait')
         ORDER BY id DESC LIMIT 1`,
      )
      .get(taskRef);
    return row === undefined ? null : readContest(row);
  }

  /**
   * Every state change is a compare-and-swap on (state, generation): the
   * caller proves what it believes, the write bumps the generation, and
   * whichever of aggregation, reaping, or crash recovery loses the race
   * changes nothing (finding 17/27).
   */
  casContestState(id: number, from: readonly ContestState[], to: ContestState, expectedGeneration: number): boolean {
    const marks = from.map(() => "?").join(",");
    const changed = this.db
      .prepare(
        `UPDATE contest SET state = ?, generation = generation + 1
          WHERE id = ? AND generation = ? AND state IN (${marks})`,
      )
      .run(to, id, expectedGeneration, ...from);
    return Number(changed.changes) === 1;
  }

  stampContestLease(id: number, leaseId: string, runner: string, incarnation: string | null): void {
    this.db
      .prepare("UPDATE contest SET current_lease_id = ?, runner = ?, incarnation = ? WHERE id = ?")
      .run(leaseId, runner, incarnation, id);
  }

  stampContestDispatch(id: number, baseSha: string, setupDigest: string | null): void {
    this.db.prepare("UPDATE contest SET base_sha = ?, setup_digest = ? WHERE id = ?").run(baseSha, setupDigest, id);
  }

  createContestants(
    contest: number,
    agents: { provider: string; model: string; repairModel: string; permissionMode?: UnattendedPermissionMode; branch: string; budgetMicrousd: number; reserveMicrousd: number; unknownSpend?: boolean }[],
  ): number[] {
    return this.transact(() =>
      agents.map((agent, index) => {
        const inserted = this.db
          .prepare(
            `INSERT INTO contestant
               (contest, ordinal, provider, model, repair_model, branch, budget_microusd, reserve_microusd, unknown_spend, profile_json)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            contest,
            index + 1,
            agent.provider,
            agent.model,
            agent.repairModel,
            agent.branch,
            agent.budgetMicrousd,
            agent.reserveMicrousd,
            // v27 (comparisons): a lane whose harness reports no dollars is
            // PRE-latched — unmeasured is a fact of the lane, not a
            // wait-and-see. Race lanes stay 0 and measure normally.
            agent.unknownSpend === true ? 1 : 0,
            // v24: the contestant's OWN sealed profile — race terms carry
            // exact models already; the effective limits join them here so
            // the dispatch proof holds each lane to its lane.
            canonicalProfileJson(contestantProfileOf(agent.provider, agent.model, agent.repairModel, agent.permissionMode)),
          );
        return Number(inserted.lastInsertRowid);
      }),
    );
  }

  /** The lane's CUMULATIVE wall clock across its whole lineage — main
   * attempt, resumes, and repair children (Phase 3 slice B, Codex
   * finding 1): three sealed clocks bound a comparison lane. */
  contestantCumulativeMs(contestantId: number): number {
    const row = this.db
      .prepare(
        `SELECT COALESCE(SUM(
           MAX(0, (julianday(COALESCE(finished_at, provider_started_at)) - julianday(provider_started_at)) * 86400000)
         ), 0) AS total
           FROM run
          WHERE provider_started_at IS NOT NULL
            AND (contestant = ? OR parent_run IN (SELECT id FROM run WHERE contestant = ?))`,
      )
      .get(contestantId, contestantId);
    return Math.round(Number(row?.["total"] ?? 0));
  }

  /** The lane's money and tokens across its WHOLE lineage — main attempt,
   * resumes, and repair children (Codex slice-B finding 6): a lane's cell
   * that reads only the newest run under-reports every park cycle. */
  contestantSpendRollup(contestantId: number): { costMicrousd: number; tokensIn: number; tokensOut: number; measuredRuns: number; totalRuns: number } {
    const row = this.db
      .prepare(
        `SELECT COALESCE(SUM(CASE WHEN cost_usd IS NULL THEN 0 ELSE CAST(ROUND(cost_usd * 1000000) AS INTEGER) END), 0) AS cost,
                COALESCE(SUM(COALESCE(tokens_in, 0)), 0) AS tin,
                COALESCE(SUM(COALESCE(tokens_out, 0)), 0) AS tout,
                SUM(CASE WHEN cost_usd IS NULL THEN 0 ELSE 1 END) AS measured,
                COUNT(*) AS total
           FROM run
          WHERE provider_started_at IS NOT NULL
            AND (contestant = ? OR parent_run IN (SELECT id FROM run WHERE contestant = ?))`,
      )
      .get(contestantId, contestantId);
    return {
      costMicrousd: Number(row?.["cost"] ?? 0),
      tokensIn: Number(row?.["tin"] ?? 0),
      tokensOut: Number(row?.["tout"] ?? 0),
      measuredRuns: Number(row?.["measured"] ?? 0),
      totalRuns: Number(row?.["total"] ?? 0),
    };
  }

  contestants(contest: number): Contestant[] {
    return this.db.prepare("SELECT * FROM contestant WHERE contest = ? ORDER BY ordinal").all(contest).map(readContestant);
  }

  getContestant(id: number): Contestant | null {
    const row = this.db.prepare("SELECT * FROM contestant WHERE id = ?").get(id);
    return row === undefined ? null : readContestant(row);
  }

  casContestantState(
    id: number,
    from: readonly ContestantState[],
    to: ContestantState,
    expectedGeneration: number,
  ): boolean {
    const marks = from.map(() => "?").join(",");
    const changed = this.db
      .prepare(
        `UPDATE contestant SET state = ?, generation = generation + 1
          WHERE id = ? AND generation = ? AND state IN (${marks})`,
      )
      .run(to, id, expectedGeneration, ...from);
    return Number(changed.changes) === 1;
  }

  // Exactly one live run per agent (finding 22): the lane's pointer is
  // bound by `startRun` alone (raw authority repair) — a run admitted with
  // `contestant` takes the lane inside its own insert, a held lane admits
  // no second run, and there is no post-insert claim road.

  /**
   * The exact authority a contest lane PRESENTS at admission (raw
   * authority repair): its race-approved profile's digest as a `legacy`
   * stamp, with the pair the lane spends as for the phase — the same
   * facts `startRun` re-proves against the lane before the row exists.
   * Null for no such lane.
   */
  laneAuthorityFor(contestantId: number, phase: "build" | "repair" = "build"): RouteStamp | null {
    const lane = this.getContestant(contestantId);
    // The STORED sealed profile, or nothing (atomic authority closure): a
    // lane with no readable profile has no authority to present, and no
    // synthesized profile stands in for the one the race approved. A lane
    // that has ended, or whose stored profile disagrees with its own
    // provider, model, or repair-model columns, presents nothing either
    // (final authority closure) — the admission refuses the same row in
    // words, so nothing derived here can be accepted there.
    if (lane === null || lane.profile == null || laneAuthorityProblem(lane) !== null) return null;
    const profile = lane.profile;
    return { routeDigest: `profile:${profileDigestOf(profile)}`, phase, provider: lane.provider, model: phase === "repair" ? lane.repairModel : lane.model, chosen: "legacy" };
  }

  releaseContestantRun(id: number, runId: number): void {
    this.db.prepare("UPDATE contestant SET active_run = NULL WHERE id = ? AND active_run = ?").run(id, runId);
  }

  setContestantWorktree(id: number, worktree: string): void {
    this.db.prepare("UPDATE contestant SET worktree = ? WHERE id = ?").run(worktree, id);
  }

  /** The lineage meter (finding 25 + round-2 finding on repairs): each
   * finished invocation settles ONCE, and the agent's total is the SUM
   * across its whole lineage — a park's spend and its resume's spend are
   * both real money. Accounted tracks at least the measured total. */
  recordContestantSpend(id: number, invocationMicrousd: number): void {
    this.db
      .prepare(
        `UPDATE contestant SET
           measured_microusd = measured_microusd + ?,
           accounted_microusd = MAX(accounted_microusd, measured_microusd + ?)
         WHERE id = ?`,
      )
      .run(Math.max(0, invocationMicrousd), Math.max(0, invocationMicrousd), id);
  }

  /** A started invocation that never reported: the ledger charges the FULL
   * reservation — never the remaining amount — and says the real figure is
   * unknown (finding 25). Idempotent; never lowers a larger accounting. */
  latchContestantUnknownSpend(id: number): void {
    this.db
      .prepare(
        `UPDATE contestant SET
           accounted_microusd = MAX(accounted_microusd, budget_microusd + reserve_microusd),
           unknown_spend = 1
         WHERE id = ?`,
      )
      .run(id);
  }

  setContestantCustody(id: number, custody: string | null): void {
    this.db.prepare("UPDATE contestant SET custody = ? WHERE id = ?").run(custody, id);
  }

  /** The cleanup queue (stage 6): agents of DECIDED tournaments whose
   * checkouts still sit outside the pool. Terminal contest states only —
   * an undecided tournament's evidence is never touched. */
  contestantsForCleanup(): Contestant[] {
    return this.db
      .prepare(
        `SELECT contestant.* FROM contestant
         JOIN contest ON contest.id = contestant.contest
         WHERE contest.state IN ('picked','abandoned') AND contestant.cleanup = 'pending'
         ORDER BY contestant.id`,
      )
      .all()
      .map(readContestant);
  }

  /** Exactly-once overdue escalation: the mark rides the page (stage 6). */
  markContestOverduePaged(contestId: number): boolean {
    const changed = this.db
      .prepare("UPDATE contest SET overdue_paged = 1 WHERE id = ? AND overdue_paged = 0")
      .run(contestId);
    return Number(changed.changes) === 1;
  }

  /** The pick, stamped: who chose, when, and which agent won. */
  setContestWinner(contestId: number, contestantId: number, approver: string, now: Date): void {
    this.db
      .prepare("UPDATE contest SET winner_contestant = ?, picked_by = ?, picked_at = ? WHERE id = ?")
      .run(contestantId, approver, now.toISOString(), contestId);
  }

  setContestantCleanup(id: number, cleanup: "pending" | "done" | "attention"): void {
    this.db.prepare("UPDATE contestant SET cleanup = ? WHERE id = ?").run(cleanup, id);
  }

  contestsInStates(states: readonly ContestState[]): Contest[] {
    const marks = states.map(() => "?").join(",");
    return this.db.prepare(`SELECT * FROM contest WHERE state IN (${marks}) ORDER BY id`).all(...states).map(readContest);
  }

  /** The still-live claim behind a lease id, or null — recovery's question.
   * The clock is INJECTED like everywhere else; SQL wall-clock time would
   * silently disagree with every test's fixed timestamps. */
  liveClaimByLease(leaseId: string, now: Date): { leaseId: string } | null {
    const row = this.db
      .prepare("SELECT lease_id FROM claim WHERE lease_id = ? AND released_at IS NULL AND expires_at >= ?")
      .get(leaseId, now.toISOString());
    return row === undefined ? null : { leaseId: String(row["lease_id"]) };
  }


  /**
   * Close a racing agent's question WITHOUT answering it (the exclude
   * ceremony, round-3 finding 28): typed closure, never a fake option.
   * The caller owns authentication and the contestant's stop.
   */
  excludeDecision(id: number, by: string, now: Date): boolean {
    return this.transact(() => {
      const changed = this.db
        .prepare(
          `UPDATE decision SET state = 'answered', answered_at = ?, answered_by = ?, closed_reason = 'excluded'
            WHERE id = ? AND state IN ('open','expired') AND contestant IS NOT NULL`,
        )
        .run(now.toISOString(), by, id);
      if (Number(changed.changes) !== 1) return false;
      // Closure clears what an answer would have cleared (external
      // dispatch review, finding 43): the decision-owned hold and the
      // page episode — an excluded question must not hold work forever.
      this.releaseOwnedHold("decision", String(id));
      this.resolveEpisode(`decision:${id}`, now);
      this.bumpWake();
      return true;
    });
  }

  /** A racing agent's answered-but-undelivered question, for the resume pass. */
  answeredDecisionForContestant(contestantId: number): number | null {
    const row = this.db
      .prepare(
        `SELECT decision.id AS id FROM decision
          WHERE decision.contestant = ? AND decision.state = 'answered'
            AND (decision.closed_reason IS NULL OR decision.closed_reason != 'excluded')
            AND NOT EXISTS (
              SELECT 1 FROM run_decision
              JOIN run AS delivered ON delivered.id = run_decision.run
              WHERE run_decision.decision = decision.id AND delivered.outcome IS NOT NULL
            )
          LIMIT 1`,
      )
      .get(contestantId);
    return row === undefined ? null : Number(row["id"]);
  }

  /** A racing agent's one open (or expired-but-unanswered) question. */
  openDecisionForContestant(contestantId: number): number | null {
    const row = this.db
      .prepare("SELECT id FROM decision WHERE contestant = ? AND state IN ('open','expired') LIMIT 1")
      .get(contestantId);
    return row === undefined ? null : Number(row["id"]);
  }

  /** Admission binds each reserved slot to its agent, so recovery can
   * find and free every one of them (nothing reserved is ever orphaned). */
  assignSlotContestant(slotId: number, contestantId: number): void {
    this.db.prepare("UPDATE execution_slot SET contestant = ? WHERE id = ?").run(contestantId, slotId);
  }

  releaseSlotsForContest(contestId: number, now: Date): number {
    const changed = this.db
      .prepare(
        `UPDATE execution_slot SET state = 'released', released_at = ?
          WHERE state IN ('reserved','running')
            AND contestant IN (SELECT id FROM contestant WHERE contest = ?)`,
      )
      .run(now.toISOString(), contestId);
    return Number(changed.changes);
  }

  // ---- worker-process slots (v14, finding 26) ----------------------------

  reserveExecutionSlots(runner: string, count: number, now: Date): number[] {
    return this.transact(() => {
      const ids: number[] = [];
      for (let index = 0; index < count; index++) {
        const inserted = this.db
          .prepare("INSERT INTO execution_slot (runner, reserved_at) VALUES (?, ?)")
          .run(runner, now.toISOString());
        ids.push(Number(inserted.lastInsertRowid));
      }
      return ids;
    });
  }

  /** reserved → running happens in the stamp-before-spawn moment, carrying
   * the process group so recovery can ask the OS before freeing capacity. */
  markSlotRunning(
    id: number,
    facts: { run: number; contestant?: number | null; incarnation?: string | null; processGroup?: number | null },
    now: Date,
  ): boolean {
    const changed = this.db
      .prepare(
        `UPDATE execution_slot SET state = 'running', run = ?, contestant = ?, incarnation = ?, process_group = ?, running_at = ?
          WHERE id = ? AND state = 'reserved'`,
      )
      .run(facts.run, facts.contestant ?? null, facts.incarnation ?? null, facts.processGroup ?? null, now.toISOString(), id);
    return Number(changed.changes) === 1;
  }

  /** A correction process replaces the exited provider in the same open
   * root attempt. It may refresh only that attempt's exact occupied slot. */
  refreshSlotProcess(id: number, facts: { run: number; contestant?: number | null; incarnation?: string | null; processGroup: number }): boolean {
    if (!Number.isInteger(facts.processGroup) || facts.processGroup <= 0) return false;
    const changed = this.db.prepare(`UPDATE execution_slot SET process_group = ?
      WHERE id = ? AND state = 'running' AND run = ? AND contestant IS ? AND incarnation IS ?
        AND EXISTS (SELECT 1 FROM run WHERE id = ? AND outcome IS NULL)`)
      .run(facts.processGroup, id, facts.run, facts.contestant ?? null, facts.incarnation ?? null, facts.run);
    return Number(changed.changes) === 1;
  }

  releaseExecutionSlot(id: number, now: Date): boolean {
    const changed = this.db
      .prepare("UPDATE execution_slot SET state = 'released', released_at = ? WHERE id = ? AND state IN ('reserved','running')")
      .run(now.toISOString(), id);
    return Number(changed.changes) === 1;
  }

  liveSlotCount(runner: string): number {
    const row = this.db
      .prepare("SELECT COUNT(*) AS n FROM execution_slot WHERE runner = ? AND state IN ('reserved','running')")
      .get(runner);
    return Number(row?.["n"] ?? 0);
  }

  getExecutionSlot(id: number): ExecutionSlot | null {
    const row = this.db.prepare("SELECT * FROM execution_slot WHERE id = ?").get(id);
    return row === undefined ? null : readExecutionSlot(row);
  }

  // ---- durable ceremony nonces (v14, findings 21/30) ---------------------

  /** Minted from a POST, never a GET. Bounded per approver; expired rows
   * are swept rather than accumulating. */
  mintCeremonyNonce(
    spec: { hash: string; approver: string; subject: string; subjectId: number; digest: string; ttlMs: number },
    now: Date,
  ): { ok: true } | { ok: false; reason: "too-many" } {
    return this.transact(() => {
      const open = this.db
        .prepare("SELECT COUNT(*) AS n FROM ceremony_nonce WHERE approver = ? AND consumed_at IS NULL AND expires_at >= ?")
        .get(spec.approver, now.toISOString());
      if (Number(open?.["n"] ?? 0) >= 50) return { ok: false as const, reason: "too-many" as const };
      this.db
        .prepare(
          `INSERT INTO ceremony_nonce (hash, approver, subject, subject_id, digest, created_at, expires_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          spec.hash,
          spec.approver,
          spec.subject,
          spec.subjectId,
          spec.digest,
          now.toISOString(),
          new Date(now.getTime() + spec.ttlMs).toISOString(),
        );
      return { ok: true as const };
    });
  }

  /** Single use, inside whatever transaction the act runs in: the same
   * write that authorizes the act consumes its nonce, or neither happens. */
  consumeCeremonyNonce(
    hash: string,
    approver: string,
    subject: string,
    subjectId: number,
    digest: string,
    now: Date,
  ): boolean {
    const changed = this.db
      .prepare(
        `UPDATE ceremony_nonce SET consumed_at = ?
          WHERE hash = ? AND approver = ? AND subject = ? AND subject_id = ? AND digest = ?
            AND consumed_at IS NULL AND expires_at >= ?`,
      )
      .run(now.toISOString(), hash, approver, subject, subjectId, digest, now.toISOString());
    return Number(changed.changes) === 1;
  }

  sweepCeremonyNonces(now: Date): number {
    const swept = this.db.prepare("DELETE FROM ceremony_nonce WHERE expires_at < ?").run(now.toISOString());
    return Number(swept.changes);
  }

  // ----- fleet chat (v13) -------------------------------------------------

  /**
   * The chat context, read by DEDICATED queries only (Codex v3 review,
   * change 9): a non-empty explicit repo list is REQUIRED, admission binds
   * inside every query before its LIMIT, repo-null rows are excluded from
   * rows AND aggregates, and each item carries its repo as an INDEX into
   * the caller's list — the serializer turns that into an opaque id; full
   * paths never leave this process. Everything here is intentional
   * provider egress: titles and questions are operator text and go as-is.
   */
  chatSnapshot(admittedRepos: readonly string[], now: Date): ChatSnapshot {
    if (admittedRepos.length === 0) {
      throw new Error("chatSnapshot requires the explicit non-empty repo list — an empty ceiling has nothing to say");
    }
    const marks = admittedRepos.map(() => "?").join(",");
    const repoIndex = new Map(admittedRepos.map((repo, index) => [repo, index]));
    const indexOf = (repo: unknown): number => repoIndex.get(String(repo)) ?? -1;
    const hours = (iso: unknown): number => Math.max(0, Math.round((now.getTime() - Date.parse(String(iso))) / 3_600_000));
    return this.transact(() => {
      const families = this.taskFamiliesAdmitted(admittedRepos, false, { limit: 61 });
      const taskRows = families.slice(0, 61).map(family => {
        const current = family.current;
        const ref = this.lookupRef(current.id)!;
        const run = this.runsFor(ref.id).find(one => one.finishedAt !== null && (one.role === "builder" || one.role === "scout"));
        const proof = current.state === "done" && run !== undefined ? this.proofVerdictFor(run.id) : null;
        return { family, current, ref, proof, accepted: run !== undefined && this.proofAcceptance(run.id) !== null };
      });
      const decisionRows = this.db
        .prepare(
          `SELECT decision.id AS id, decision.question AS question, decision.options AS options, task_ref.repo AS repo,
                  task_ref.external_id AS task_id, decision.created_at AS created_at
             FROM decision JOIN run ON run.id = decision.run JOIN task_ref ON task_ref.id = run.task_ref
            WHERE decision.state IN ('open','expired') AND task_ref.repo IN (${marks})
            ORDER BY decision.id DESC LIMIT 21`,
        )
        .all(...admittedRepos);
      const incidentRows = this.db
        .prepare(
          `SELECT incident.kind AS kind, incident.created_at AS created_at, task_ref.repo AS repo
             FROM incident JOIN run ON run.id = incident.run JOIN task_ref ON task_ref.id = run.task_ref
            WHERE incident.resolved_at IS NULL AND task_ref.repo IN (${marks})
            ORDER BY incident.id DESC LIMIT 21`,
        )
        .all(...admittedRepos);
      const routineRows = this.db
        .prepare(
          `SELECT id, name, schedule, paused, digest, approved_at, approved_digest, repo
             FROM routine WHERE repo IN (${marks}) ORDER BY id LIMIT 31`,
        )
        .all(...admittedRepos);
      const publicationRows = this.db
        .prepare(
          `SELECT publication.pr_number AS pr, publication.last_check_state AS check_state, task_ref.repo AS repo
             FROM publication JOIN task_ref ON task_ref.id = publication.task_ref
            WHERE publication.state = 'opened'
              AND (publication.remote_state IS NULL OR publication.remote_state NOT IN ('MERGED','CLOSED'))
              AND task_ref.repo IN (${marks})
            ORDER BY publication.id DESC LIMIT 21`,
        )
        .all(...admittedRepos);
      const optionsOf = (raw: unknown): { id: string; label: string; reversible: boolean }[] => {
        try {
          const parsed = JSON.parse(String(raw)) as { id?: unknown; label?: unknown; reversible?: unknown }[];
          return Array.isArray(parsed)
            ? parsed.slice(0, 6).map(one => ({ id: String(one?.id ?? ""), label: String(one?.label ?? ""), reversible: one?.reversible === true }))
            : [];
        } catch {
          return [];
        }
      };
      const optionLabelsOf = (raw: unknown): string[] => optionsOf(raw).map(one => one.label);
      return {
        repos: [...admittedRepos],
        tasks: taskRows.slice(0, 60).map(({ family, current, ref, proof, accepted }) => ({
          repoIndex: indexOf(current.repo), id: current.id, rootId: family.root.id,
          title: family.root.title, state: current.state, ageHours: hours(current.updatedAt),
          strikes: ref.strikes, proofVerdict: proof?.verdict ?? null, proofMatrix: proof?.matrix ?? [], proofAccepted: accepted,
          historyProblem: family.problem, otherActive: family.otherActive.map(one => one.id),
        })),
        tasksSaturated: taskRows.length > 60,
        decisions: decisionRows.slice(0, 20).map(row => ({
          repoIndex: indexOf(row["repo"]),
          id: Number(row["id"]),
          question: String(row["question"]),
          optionLabels: optionLabelsOf(row["options"]),
          taskId: String(row["task_id"]),
          options: optionsOf(row["options"]),
          ageHours: Math.max(0, Math.round((now.getTime() - Date.parse(String(row["created_at"]))) / 3_600_000)),
        })),
        decisionsSaturated: decisionRows.length > 20,
        incidents: incidentRows.slice(0, 20).map(row => ({
          repoIndex: indexOf(row["repo"]),
          kind: String(row["kind"]),
          ageHours: hours(row["created_at"]),
        })),
        incidentsSaturated: incidentRows.length > 20,
        routines: routineRows.slice(0, 30).map(row => {
          const approved = row["approved_at"] !== null && row["approved_digest"] === row["digest"];
          const fires = this.routineFires(Number(row["id"]), 1);
          return {
            repoIndex: indexOf(row["repo"]),
            name: String(row["name"]),
            schedule: String(row["schedule"]),
            status: Number(row["paused"]) === 1 ? "paused" : approved ? "live" : "awaiting approval",
            lastFire: fires.length === 0 ? null : `${fires[0]?.outcome}${fires[0]?.reason === null ? "" : `: ${fires[0]?.reason}`}`,
          };
        }),
        routinesSaturated: routineRows.length > 30,
        publications: publicationRows.slice(0, 20).map(row => ({
          repoIndex: indexOf(row["repo"]),
          pr: row["pr"] === null ? null : Number(row["pr"]),
          checkState: row["check_state"] === null ? null : String(row["check_state"]),
        })),
        publicationsSaturated: publicationRows.length > 20,
      };
    });
  }

  setChatConfig(
    config: {
      provider: ChatProviderId;
      model: string;
      dailyTurns: number;
      weeklyCeilingMicrousd: number;
      priceInMicrousd: number;
      priceOutMicrousd: number;
    },
    by: string,
    now: Date,
  ): void {
    this.db
      .prepare(
        `INSERT INTO chat_config (id, provider, model, daily_turns, weekly_ceiling_microusd, price_in_microusd, price_out_microusd, updated_at, updated_by)
         VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT (id) DO UPDATE SET provider = excluded.provider, model = excluded.model,
           daily_turns = excluded.daily_turns, weekly_ceiling_microusd = excluded.weekly_ceiling_microusd,
           price_in_microusd = excluded.price_in_microusd, price_out_microusd = excluded.price_out_microusd,
           updated_at = excluded.updated_at, updated_by = excluded.updated_by`,
      )
      .run(
        config.provider,
        config.model,
        config.dailyTurns,
        config.weeklyCeilingMicrousd,
        config.priceInMicrousd,
        config.priceOutMicrousd,
        now.toISOString(),
        by,
      );
  }

  getChatConfig(): ChatConfig | null {
    const row = this.db.prepare("SELECT * FROM chat_config WHERE id = 1").get();
    if (row === undefined) return null;
    return {
      provider: String(row["provider"]) as ChatProviderId,
      model: String(row["model"]),
      dailyTurns: Number(row["daily_turns"]),
      weeklyCeilingMicrousd: Number(row["weekly_ceiling_microusd"]),
      priceInMicrousd: row["price_in_microusd"] === null || row["price_in_microusd"] === undefined ? null : Number(row["price_in_microusd"]),
      priceOutMicrousd: row["price_out_microusd"] === null || row["price_out_microusd"] === undefined ? null : Number(row["price_out_microusd"]),
      updatedAt: String(row["updated_at"]),
      updatedBy: String(row["updated_by"]),
    };
  }

  clearChatConfig(): void {
    this.db.prepare("DELETE FROM chat_config WHERE id = 1").run();
  }

  /**
   * Admit one turn, transactionally: the unknown-spend latch, the
   * one-live-turn-per-approver rule, the daily turn cap, and the rolling
   * 7-day ceiling (reservations count until settled — change 4) are all
   * proved inside the same write, so two concurrent posts cannot both
   * slip under a cap.
   */
  openChatTurn(
    args: {
      approver: string;
      credentialKey: string;
      provider: ChatProviderId;
      model: string;
      reservedMicrousd: number;
      dailyTurns: number;
      weeklyCeilingMicrousd: number;
      deadlineMs: number;
    },
    now: Date,
  ): { ok: true; id: number } | { ok: false; reason: "latched" | "concurrent" | "daily-cap" | "over-budget" | "monthly-budget" } {
    return this.transact(() => {
      const latched = this.db
        .prepare("SELECT 1 AS hit FROM chat_turn WHERE credential_key = ? AND unknown_spend = 1 AND acknowledged_at IS NULL LIMIT 1")
        .get(args.credentialKey);
      if (latched !== undefined) return { ok: false as const, reason: "latched" as const };
      // v105: a monthly budget this person's spend counts toward, used up (a subscription chat costs nothing extra).
      if (this.budgetGate(now)({ project: null, person: args.approver, teammate: null, agents: this.agentsFor([args.provider]) }).over !== null) return { ok: false as const, reason: "monthly-budget" as const };
      const live = this.db
        .prepare("SELECT 1 AS hit FROM chat_turn WHERE approver = ? AND state IN ('queued','running') LIMIT 1")
        .get(args.approver);
      const liveMate = this.db
        .prepare("SELECT 1 AS hit FROM mate_turn WHERE approver = ? AND state IN ('queued','running') LIMIT 1")
        .get(args.approver);
      if (live !== undefined || liveMate !== undefined) return { ok: false as const, reason: "concurrent" as const };
      if (this.chatTurnsToday(args.approver, now) >= args.dailyTurns) return { ok: false as const, reason: "daily-cap" as const };
      if (this.chatWeeklySpendMicrousd(args.credentialKey, now) + args.reservedMicrousd > args.weeklyCeilingMicrousd) {
        return { ok: false as const, reason: "over-budget" as const };
      }
      const inserted = this.db
        .prepare(
          `INSERT INTO chat_turn (approver, credential_key, provider, model, state, created_at, deadline_at, reserved_microusd)
           VALUES (?, ?, ?, ?, 'queued', ?, ?, ?)`,
        )
        .run(
          args.approver,
          args.credentialKey,
          args.provider,
          args.model,
          now.toISOString(),
          new Date(now.getTime() + args.deadlineMs).toISOString(),
          args.reservedMicrousd,
        );
      return { ok: true as const, id: Number(inserted.lastInsertRowid) };
    });
  }

  /** queued → running, exactly once. The dispatch CAS: whoever wins this
   * write sends the ONE request this row will ever describe. */
  startChatTurn(id: number, now: Date): { ok: true; generation: number } | { ok: false } {
    const changed = this.db
      .prepare("UPDATE chat_turn SET state = 'running', generation = generation + 1, started_at = ? WHERE id = ? AND state = 'queued'")
      .run(now.toISOString(), id);
    if (Number(changed.changes) !== 1) return { ok: false };
    const row = this.db.prepare("SELECT generation FROM chat_turn WHERE id = ?").get(id);
    return { ok: true, generation: Number(row?.["generation"] ?? 0) };
  }

  /** Terminal CAS, generation-checked: a response arriving after the sweep
   * already judged this row loses and changes nothing (change 5). */
  finalizeChatTurn(
    id: number,
    generation: number,
    outcome: {
      state: "answered" | "failed";
      failureReason?: ChatFailureReason;
      tokensIn?: number;
      tokensOut?: number;
      settledMicrousd: number | null;
      unknownSpend?: boolean;
      replyBytes?: number;
      candidateCount?: number;
    },
    now: Date,
  ): boolean {
    this.spendCache = null; // its spend counts toward the next budget check
    const changed = this.db
      .prepare(
        `UPDATE chat_turn SET state = ?, failure_reason = ?, tokens_in = ?, tokens_out = ?,
           settled_microusd = ?, unknown_spend = ?, reply_bytes = ?, candidate_count = ?, finished_at = ?
         WHERE id = ? AND generation = ? AND state IN ('queued','running')`,
      )
      .run(
        outcome.state,
        outcome.failureReason ?? null,
        outcome.tokensIn ?? null,
        outcome.tokensOut ?? null,
        outcome.settledMicrousd,
        outcome.unknownSpend === true ? 1 : 0,
        outcome.replyBytes ?? null,
        outcome.candidateCount ?? null,
        now.toISOString(),
        id,
        generation,
      );
    return Number(changed.changes) === 1;
  }

  /**
   * The crash sweep: turns past their deadline become failed('crashed'),
   * generation-bumped so a late finalize loses. A turn that STARTED may
   * have billed — it latches unknown spend and blocks its credential; a
   * queued one never dispatched and settles at zero.
   */
  sweepStaleChatTurns(now: Date): number {
    const swept = this.db
      .prepare(
        `UPDATE chat_turn SET state = 'failed', failure_reason = 'crashed', generation = generation + 1,
           unknown_spend = CASE WHEN started_at IS NOT NULL THEN 1 ELSE 0 END,
           settled_microusd = CASE WHEN started_at IS NOT NULL THEN settled_microusd ELSE 0 END,
           finished_at = ?
         WHERE state IN ('queued','running') AND deadline_at < ?`,
      )
      .run(now.toISOString(), now.toISOString());
    return Number(swept.changes);
  }

  getChatTurn(id: number): ChatTurn | null {
    const row = this.db.prepare("SELECT * FROM chat_turn WHERE id = ?").get(id);
    return row === undefined ? null : readChatTurn(row);
  }

  liveChatTurnFor(approver: string): ChatTurn | null {
    const row = this.db
      .prepare("SELECT * FROM chat_turn WHERE approver = ? AND state IN ('queued','running') ORDER BY id DESC LIMIT 1")
      .get(approver);
    return row === undefined ? null : readChatTurn(row);
  }

  recentChatTurns(approver: string, limit = 20): ChatTurn[] {
    return this.db
      .prepare("SELECT * FROM chat_turn WHERE approver = ? ORDER BY id DESC LIMIT ?")
      .all(approver, Math.max(1, Math.min(limit, 100)))
      .map(readChatTurn);
  }

  /** Rolling 7-day spend for the caps line: settled where known, reserved
   * where not — the same arithmetic the admission transaction uses. */
  chatWeeklySpendMicrousd(credentialKey: string, now: Date): number {
    const since7 = new Date(now.getTime() - 7 * 24 * 3_600_000).toISOString();
    const liveMate = this.db
      .prepare("SELECT COALESCE(SUM(reserved_microusd), 0) AS n FROM mate_turn WHERE credential_key = ? AND state IN ('queued','running') AND created_at >= ?")
      .get(credentialKey, since7);
    const settledMate = this.db
      .prepare("SELECT COALESCE(SUM(settled_microusd), 0) AS n FROM mate_turn WHERE credential_key = ? AND state IN ('answered','failed') AND created_at >= ?")
      .get(credentialKey, since7);
    return this.chatOnlyWeeklySpendMicrousd(credentialKey, now) + Number(liveMate?.["n"] ?? 0) + Number(settledMate?.["n"] ?? 0);
  }

  private chatOnlyWeeklySpendMicrousd(credentialKey: string, now: Date): number {
    const since = new Date(now.getTime() - 7 * 24 * 3_600_000).toISOString();
    const row = this.db
      .prepare(
        `SELECT COALESCE(SUM(COALESCE(settled_microusd, reserved_microusd)), 0) AS spent
           FROM chat_turn WHERE credential_key = ? AND created_at >= ? AND kind = 'chat'`,
      )
      .get(credentialKey, since);
    return Number(row?.["spent"] ?? 0);
  }

  /** The day's turns: fleet chat turns plus mate turns — a mate turn is
   * one turn however many steps it took (slice-1 review, finding 11). */
  chatTurnsToday(approver: string, now: Date): number {
    const dayStart = `${now.toISOString().slice(0, 10)}T00:00:00.000Z`;
    const chat = this.db
      .prepare("SELECT COUNT(*) AS n FROM chat_turn WHERE approver = ? AND created_at >= ? AND kind = 'chat'")
      .get(approver, dayStart);
    const mate = this.db
      .prepare("SELECT COUNT(*) AS n FROM mate_turn WHERE approver = ? AND created_at >= ?")
      .get(approver, dayStart);
    return Number(chat?.["n"] ?? 0) + Number(mate?.["n"] ?? 0);
  }

  /** Turns blocking this credential until somebody owns the worst case. */
  latchedChatTurns(credentialKey: string): ChatTurn[] {
    return this.db
      .prepare("SELECT * FROM chat_turn WHERE credential_key = ? AND unknown_spend = 1 AND acknowledged_at IS NULL ORDER BY id")
      .all(credentialKey)
      .map(readChatTurn);
  }

  /**
   * The acknowledgement (change 6): append-only, names who accepted, and
   * charges the reserved worst case unless an authoritative settled cost
   * already exists — the ledger never shows unknown spend as free.
   */
  acknowledgeChatTurn(id: number, by: string, now: Date): boolean {
    const changed = this.db
      .prepare(
        `UPDATE chat_turn SET acknowledged_at = ?, acknowledged_by = ?,
           settled_microusd = COALESCE(settled_microusd, reserved_microusd)
         WHERE id = ? AND unknown_spend = 1 AND acknowledged_at IS NULL`,
      )
      .run(now.toISOString(), by, id);
    return Number(changed.changes) === 1;
  }

  /** Provenance for filing paths that create their ref outside
   * createConsoleTask. Set-once: an already-stamped row never changes. */
  stampFiledVia(refId: number, via: string): void {
    this.db.prepare("UPDATE task_ref SET filed_via = ? WHERE id = ? AND filed_via IS NULL").run(via, refId);
  }

  /**
   * When this installation first finished a run with a change — the
   * moment the first-run checklist retires, permanently. Derived from run
   * history the first time it is observed, then stamped as an append-only
   * installation fact so later pruning of those rows cannot resurrect the
   * checklist (adoption review, finding 14).
   */
  firstSuccessAt(now: Date): string | null {
    const fact = this.installationFact("first-success-at");
    if (fact !== null) return fact;
    const row = this.db
      .prepare("SELECT finished_at FROM run WHERE outcome = 'built' AND finished_at IS NOT NULL ORDER BY id LIMIT 1")
      .get();
    if (row === undefined) return null;
    const when = String(row["finished_at"]);
    this.recordInstallationFact("first-success-at", when, now);
    return when;
  }

  /** When this installation began: its first account. Accounts are never
   * deleted (revocation is a stamp), so this never moves. */
  installationStartedAt(): string | null {
    const row = this.db.prepare("SELECT MIN(added_at) AS at FROM approver").get();
    return row === undefined || row["at"] == null ? null : String(row["at"]);
  }


  /** The jump palette's food: open (queued/running/failed) tasks, admission
   * inside the query before its LIMIT, newest first. */
  paletteTasks(
    repo: string | null,
    limit: number,
    admitted: string[] | null = null,
    includeUnplaced = true,
  ): { id: string; title: string; repo: string | null }[] {
    const projects = repo === null ? admitted : admitted === null || admitted.includes(repo) ? [repo] : [];
    return this.taskFamiliesAdmitted(projects, includeUnplaced, { states: ["queued", "running", "failed"], order: "updated", limit: Math.max(1, Math.min(limit, 500)) })
      .map(one => ({ id: one.root.id, title: one.root.title, repo: one.root.repo }));
  }

  /** Whether any work was ever filed — task or routine. */
  hasAnyWork(): boolean {
    if (this.db.prepare("SELECT 1 AS hit FROM task LIMIT 1").get() !== undefined) return true;
    return this.db.prepare("SELECT 1 AS hit FROM routine LIMIT 1").get() !== undefined;
  }

  /** Which door filed a task; null for history from before v12. */
  /** The coordinator provenance label for a task — `mcp:<name>#<cid4>` —
   * or null for every other filer. Rendered on the task page and INSIDE
   * the approval ceremony (MCP spec v6: the operator sees WHO asked
   * before signing). */
  coordinatorProvenanceOf(taskId: string): { label: string; filedAt: string | null } | null {
    const row = this.db
      .prepare(
        `SELECT c.name AS name, c.cid AS cid,
                (SELECT MIN(e.created_at) FROM coordinator_event e WHERE e.cid = c.cid AND e.task_id = task_ref.external_id AND e.kind = 'filed') AS filed_at
           FROM task_ref
           JOIN coordinator_credential c ON c.cid = task_ref.coordinator_cid
          WHERE task_ref.backend = ? AND task_ref.external_id = ?`,
      )
      .get(BUILT_IN, taskId);
    if (row === undefined) return null;
    return {
      label: `mcp:${String(row["name"])}#${String(row["cid"]).slice(0, 4)}`,
      filedAt: row["filed_at"] === null ? null : String(row["filed_at"]),
    };
  }

  filedViaOf(taskId: string): string | null {
    const row = this.db
      .prepare("SELECT filed_via FROM task_ref WHERE backend = ? AND external_id = ?")
      .get(BUILT_IN, taskId);
    return row === undefined || row["filed_via"] === null ? null : String(row["filed_via"]);
  }

  getRoutine(id: number): Routine | null {
    const row = this.db.prepare("SELECT * FROM routine WHERE id = ?").get(id);
    return row === undefined ? null : readRoutine(row);
  }

  routineByName(name: string): Routine | null {
    const row = this.db.prepare("SELECT * FROM routine WHERE name = ?").get(name);
    return row === undefined ? null : readRoutine(row);
  }

  /** Every routine one view may see. NULL repo filter means "no filter". */
  listRoutines(repo: string | null, admitted: string[] | null = null): Routine[] {
    const where =
      admitted === null
        ? "WHERE (? IS NULL OR routine.repo = ?)"
        : `WHERE routine.repo IN (${admitted.map(() => "?").join(",") || "''"})`;
    const params = admitted === null ? [repo, repo] : admitted;
    return this.db
      .prepare(`SELECT * FROM routine ${where} ORDER BY routine.name`)
      .all(...params)
      .map(readRoutine);
  }

  /**
   * Rewrite a template's terms. The new digest rides along, and the old
   * approval is kept — invalidated by the mismatch, exactly like a scope
   * edit, so the refusal can say "approved, then edited" rather than
   * "never approved". The firing transaction re-proves the match.
   */
  updateRoutineTerms(
    id: number,
    terms: {
      goal: string;
      outOfScope: string | null;
      touches: string[];
      /** v39: absent leaves the stored rubric untouched (a caller editing
       * goal/touches without an opinion on acceptance); present REPLACES
       * it — never merged, so the digest the caller computed from these
       * exact terms is what ends up stored. */
      acceptance?: AcceptanceCriterion[];
      requirements: string[];
      schedule: string;
      costCeilingUsd: number | null;
      digest: string;
      /** v24: restatement carries the profile its digest binds. */
      profile?: ExecutionProfile | null;
      /** v48: restatement carries the route its digest binds; absent or
       * null leaves the stored route untouched. */
      route?: PhaseRoute | null;
    },
    now: Date,
  ): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE routine SET goal = ?, out_of_scope = ?, touches = ?, requirements = ?,
                            schedule = ?, cost_ceiling_usd = ?, digest = ?, updated_at = ?,
                            profile_json = COALESCE(?, profile_json),
                            acceptance_json = COALESCE(?, acceptance_json),
                            route_json = COALESCE(?, route_json)
          WHERE id = ?`,
      )
      .run(
        terms.goal,
        terms.outOfScope,
        JSON.stringify(terms.touches),
        JSON.stringify(terms.requirements),
        terms.schedule,
        terms.costCeilingUsd,
        terms.digest,
        now.toISOString(),
        terms.profile === undefined || terms.profile === null ? null : canonicalProfileJson(terms.profile),
        terms.acceptance === undefined ? null : terms.acceptance.length === 0 ? null : JSON.stringify(terms.acceptance),
        terms.route === undefined || terms.route === null ? null : canonicalRouteJson(terms.route),
        id,
      );
    return Number(changes) > 0;
  }

  /**
   * The approval stamp, raw. Callers own the ceremony — credential,
   * digest re-read, and the transaction — in approveRoutine (routine.ts).
   */
  stampRoutineApproval(id: number, by: string, digest: string, nextFireAt: string, now: Date): void {
    this.db
      .prepare(
        `UPDATE routine SET approved_at = ?, approved_by = ?, approved_digest = ?,
                            approved_profile_json = profile_json,
                            approved_route_json = route_json,
                            next_fire_at = ?, updated_at = ?
          WHERE id = ?`,
      )
      .run(now.toISOString(), by, digest, nextFireAt, now.toISOString(), id);
  }

  /**
   * WITHDRAW an approval that no longer verifies (v48 authority repair): the refresh road
   * clears the approval's authority — its digest, its frozen snapshot, the
   * armed schedule — so a corrupt or never-taken snapshot cannot keep
   * reading as approved while the working agents happen to be unchanged.
   * `approved_at`/`approved_by` stay as history: the page reads "approved,
   * then refreshed — approve again", never "never approved".
   */
  withdrawRoutineApproval(id: number, now: Date): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE routine SET approved_digest = NULL, approved_profile_json = NULL, approved_route_json = NULL,
                            next_fire_at = NULL, updated_at = ?
          WHERE id = ?`,
      )
      .run(now.toISOString(), id);
    return Number(changes) > 0;
  }

  /** Pausing is instant and needs no ceremony; resuming re-arms the schedule. */
  setRoutinePaused(id: number, paused: boolean, now: Date): boolean {
    const { changes } = this.db
      .prepare("UPDATE routine SET paused = ?, updated_at = ? WHERE id = ?")
      .run(paused ? 1 : 0, now.toISOString(), id);
    if (Number(changes) > 0) this.bumpWake();
    return Number(changes) > 0;
  }

  /**
   * Routines a pass should try to fire: approved (digest intact), unpaused,
   * due, and placed in this pass's repository. Each candidate is re-proved
   * inside fireRoutine's own transaction — this list only nominates.
   */
  dueRoutines(repo: string, now: Date): Routine[] {
    return this.db
      .prepare(
        `SELECT * FROM routine
         WHERE repo = ? AND paused = 0
           AND approved_at IS NOT NULL AND approved_digest = digest
           AND next_fire_at IS NOT NULL AND next_fire_at <= ?
         ORDER BY next_fire_at, id`,
      )
      .all(repo, now.toISOString())
      .map(readRoutine);
  }

  /** The last firings, newest first — the board's run-history strip. */
  routineFires(routineId: number, limit = 14): (RoutineFire & { instanceTaskId: string | null; instanceState: string | null })[] {
    return this.db
      .prepare(
        `SELECT routine_fire.*, task_ref.external_id AS instance_task_id, task.state AS instance_state
           FROM routine_fire
           LEFT JOIN task_ref ON task_ref.id = routine_fire.instance_task_ref
           LEFT JOIN task ON task.id = task_ref.external_id
          WHERE routine_fire.routine_id = ?
          ORDER BY routine_fire.id DESC LIMIT ?`,
      )
      .all(routineId, Math.max(1, Math.min(limit, 100)))
      .map(row => ({
        ...readRoutineFire(row),
        instanceTaskId: row["instance_task_id"] === null || row["instance_task_id"] === undefined ? null : String(row["instance_task_id"]),
        instanceState: row["instance_state"] === null || row["instance_state"] === undefined ? null : String(row["instance_state"]),
      }));
  }

  /**
   * What one routine's instances actually cost in a window, and whether any
   * paid run in it is unmeasured. NULL costs are counted, not summed over:
   * a sum that silently omits them reads as headroom that may not exist
   * (finding 5 — the arithmetic behind failing closed).
   */
  routineSpend(routineId: number, sinceIso: string): { costUsd: number; unmeasuredRuns: number; totalRuns: number } {
    // The window is anchored to provider_started_at — the exact stamp money
    // can move — never to when the run row was opened (Codex Phase C
    // review, M2): a run opened before the cutoff whose provider started
    // inside it is spend inside the window, measured or not.
    const row = this.db
      .prepare(
        `SELECT COALESCE(SUM(run.cost_usd), 0) AS cost,
                SUM(CASE WHEN run.cost_usd IS NULL THEN 1 ELSE 0 END) AS unmeasured,
                COUNT(*) AS invoked
           FROM run
           JOIN task_ref ON task_ref.id = run.task_ref
          WHERE task_ref.routine_id = ?
            AND run.provider_started_at IS NOT NULL AND run.provider_started_at >= ?`,
      )
      .get(routineId, sinceIso);
    return {
      costUsd: Number(row?.["cost"] ?? 0),
      unmeasuredRuns: Number(row?.["unmeasured"] ?? 0),
      totalRuns: Number(row?.["invoked"] ?? 0),
    };
  }

  /**
   * The single-flight question: the oldest instance not successfully
   * completed nor explicitly abandoned — queued, running, held, parked,
   * and failed instances all block (finding 9's definition, verbatim).
   * A LIVE CLAIM blocks regardless of task state (Codex Phase C review,
   * H2): a state string written over a running build — `task state <id>
   * done` bypassing the guarded cancel — must not conjure a twin beside
   * a provider that is still spending.
   */
  routineBlocker(routineId: number, now: Date): { taskId: string; state: string } | null {
    const row = this.db
      .prepare(
        `SELECT task.id, task.state FROM task
           JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
          WHERE task_ref.routine_id = ?
            AND (
              task.state NOT IN ('done','cancelled')
              OR EXISTS (
                SELECT 1 FROM claim
                WHERE claim.task_ref = task_ref.id
                  AND claim.released_at IS NULL AND claim.expires_at > ?
                  AND claim.lease_generation = (
                    SELECT MAX(newest.lease_generation) FROM claim AS newest
                    WHERE newest.task_ref = task_ref.id
                  )
              )
            )
          ORDER BY task.created_at LIMIT 1`,
      )
      .get(BUILT_IN, routineId, now.toISOString());
    return row === undefined
      ? null
      : { taskId: String(row["id"]), state: String(row["state"]) };
  }

  /**
   * Whether a slot is still unrecorded. Only sound inside the fire
   * transaction — the IMMEDIATE lock is what makes read-then-insert atomic.
   */
  routineSlotOpen(routineId: number, scheduledFor: string): boolean {
    return (
      this.db
        .prepare("SELECT 1 AS hit FROM routine_fire WHERE routine_id = ? AND scheduled_for = ?")
        .get(routineId, scheduledFor) === undefined
    );
  }

  /** Record one slot's outcome. False: the slot was already recorded — the caller lost the race. */
  recordRoutineFire(
    fire: {
      routineId: number;
      scheduledFor: string;
      outcome: "fired" | "skipped";
      reason: string | null;
      instanceTaskRef: number | null;
    },
    now: Date,
  ): boolean {
    const { changes } = this.db
      .prepare(
        `INSERT OR IGNORE INTO routine_fire
           (routine_id, scheduled_for, outcome, reason, instance_task_ref, created_at)
         VALUES (?, ?, ?, ?, ?, ?)`,
      )
      .run(fire.routineId, fire.scheduledFor, fire.outcome, fire.reason, fire.instanceTaskRef, now.toISOString());
    return Number(changes) > 0;
  }

  /** Advance the schedule. The fire transaction is the only caller. */
  setRoutineNextFire(id: number, nextFireAt: string, now: Date): void {
    this.db
      .prepare("UPDATE routine SET next_fire_at = ?, updated_at = ? WHERE id = ?")
      .run(nextFireAt, now.toISOString(), id);
  }

  /** Stamp which routine a task is an instance of. Set at spawn, never after. */
  linkRoutineInstance(taskRef: number, routineId: number): void {
    this.db.prepare("UPDATE task_ref SET routine_id = ? WHERE id = ?").run(routineId, taskRef);
  }

  /**
   * Page a blocked track once per EPISODE: an open episode under this
   * prefix already nags, so nothing enqueues; a resolved one is history,
   * and the fresh suffix keys a new row past the dedupe uniqueness — a
   * recurrence after recovery pages again (Codex Phase C review, L1).
   * Prefix matching is exact-bytes (substr), never LIKE — task ids may
   * contain `_`, which LIKE would read as a wildcard.
   */
  enqueueRoutineEpisode(
    prefix: string,
    notification: Omit<NotificationInput, "dedupeKey">,
    suffix: string,
    now: Date,
  ): boolean {
    return this.transact(() => {
      const head = `${prefix}:`;
      const open = this.db
        .prepare(
          `SELECT 1 AS hit FROM notification
            WHERE substr(dedupe_key, 1, ?) = ? AND resolved_at IS NULL LIMIT 1`,
        )
        .get(head.length, head);
      if (open !== undefined) return false;
      return this.enqueueNotification({ dedupeKey: `${head}${suffix}`, ...notification }, now);
    });
  }

  /**
   * Close every blocked-track episode for a routine — called when a firing
   * succeeds, because success is the proof the blocker is gone (budget
   * cleared, blocking instance finished). Receipts stay; only the "wants a
   * person" bit resolves.
   */
  resolveRoutineEpisodes(routineId: number, now: Date): void {
    for (const prefix of [
      `routine-budget:${routineId}:`,
      `routine-unmeasured:${routineId}:`,
      `routine-singleflight:${routineId}:`,
      `routine-route:${routineId}:`,
    ]) {
      this.db
        .prepare(
          `UPDATE notification SET resolved_at = ?
            WHERE resolved_at IS NULL AND substr(dedupe_key, 1, ?) = ?`,
        )
        .run(now.toISOString(), prefix.length, prefix);
    }
  }

  /**
   * Everything the board's track rows need, in one snapshot: each routine
   * with its recent firings, its rolling-window spend, and the instance
   * blocking it, if any. The caller applies the ceiling row by row.
   */
  routineTracks(
    repo: string | null,
    now: Date,
    admitted: string[] | null = null,
  ): {
    routine: Routine;
    fires: ReturnType<Store["routineFires"]>;
    spend: { costUsd: number; unmeasuredRuns: number; totalRuns: number };
    blocker: { taskId: string; state: string } | null;
  }[] {
    const since = new Date(now.getTime() - 7 * 24 * 60 * 60_000).toISOString();
    return this.transact(() =>
      this.listRoutines(repo, admitted).map(routine => ({
        routine,
        fires: this.routineFires(routine.id, 14),
        spend: this.routineSpend(routine.id, since),
        blocker: this.routineBlocker(routine.id, now),
      })),
    );
  }

  // ---- lifecycle updates ---------------------------------------------------

  /** The latest saved line for one approved check. Corrupt rows stay absent. */
  checkProgress(run: number): CheckProgress | null {
    const row = this.db.prepare("SELECT snapshot, line, final, updated_at, notified_at FROM run_check WHERE run = ? AND snapshot IS NOT NULL").get(run);
    if (row === undefined) return null;
    const snapshot = parseCheckProgressSnapshot(String(row["snapshot"]));
    if (snapshot === null || snapshot.line !== String(row["line"]) || snapshot.final !== (Number(row["final"]) === 1)) return null;
    return {
      ...snapshot,
      run,
      updatedAt: String(row["updated_at"]),
      notifiedAt: row["notified_at"] == null ? null : String(row["notified_at"]),
    };
  }

  /**
   * Save every visible change, but notify at most once a minute. The final
   * summary is an exception to the wait and is emitted exactly once.
   */
  saveCheckProgress(run: number, snapshot: CheckProgressSnapshot, now: Date): { changed: boolean; notified: boolean } {
    const validated = parseCheckProgressSnapshot(JSON.stringify(snapshot));
    if (validated === null) throw new Error("invalid check progress");
    return this.transact(() => {
      const source = this.getRun(run);
      if (source === null) return { changed: false, notified: false };
      const prior = this.db.prepare("SELECT snapshot, notified_at FROM run_check WHERE run = ? AND snapshot IS NOT NULL").get(run);
      const priorSnapshot = prior === undefined ? null : parseCheckProgressSnapshot(String(prior["snapshot"]));
      if (priorSnapshot !== null && JSON.stringify(priorSnapshot) === JSON.stringify(validated)) return { changed: false, notified: false };

      const priorNotified = prior?.["notified_at"] == null ? null : String(prior["notified_at"]);
      const due = validated.final
        ? priorSnapshot?.final !== true
        : priorNotified === null || !Number.isFinite(Date.parse(priorNotified)) || now.getTime() - Date.parse(priorNotified) >= 60_000;
      this.db.prepare(`INSERT INTO run_check (run, snapshot, line, final, updated_at, notified_at)
        VALUES (?, ?, ?, ?, ?, ?)
        ON CONFLICT(run) DO UPDATE SET snapshot = excluded.snapshot, line = excluded.line,
          final = excluded.final, updated_at = excluded.updated_at, notified_at = excluded.notified_at`)
        .run(run, JSON.stringify(validated), validated.line, validated.final ? 1 : 0, now.toISOString(), priorNotified);

      const notified = due && this.noteLifecycle({
        taskRef: source.taskRef,
        run,
        kind: "check-progress",
        identity: `r${run}`,
        subject: validated.final ? `Attempt #${run}: checks finished` : `Attempt #${run}: checks in progress`,
        body: validated.line,
        link: `/r/${run}`,
      }, now);
      if (notified) this.db.prepare("UPDATE run_check SET notified_at = ? WHERE run = ?").run(now.toISOString(), run);
      return { changed: true, notified };
    });
  }

  /**
   * One project-bound lifecycle fact (Telegram task updates, 2026-09-16),
   * recorded by the mutation that made it true and inside that mutation's
   * own transaction — a rollback takes the fact with it. Only a PLACED task
   * speaks: an unplaced one has no project to deliver to, and a row with no
   * trusted project provenance would only sit in the outbox refusing. The
   * key is `life:<kind>:<identity>:<ordinal>`: the ordinal is the count of
   * earlier facts under the same head, read in this same transaction, so a
   * real recurrence (held, released, held again — even under one clock
   * value) is a new row, while each caller's own same-state guard keeps a
   * repeat from reaching here at all. No new event bus or clock in the
   * identity. Most lifecycle facts remain digest-only; validated check
   * progress is also eligible for the separate push-delivery ledger.
   */
  private noteLifecycle(
    fact: { taskRef: number; run?: number | null; kind: LifecycleKind; identity: string; subject: string; body: string; link: string | null; attention?: boolean },
    now: Date,
  ): boolean {
    const ref = this.db.prepare("SELECT repo FROM task_ref WHERE id = ?").get(fact.taskRef);
    if (ref === undefined || ref["repo"] === null || ref["repo"] === undefined) return false;
    const head = `${LIFECYCLE_KEY_PREFIX}${fact.kind}:${fact.identity}:`;
    const earlier = this.db
      .prepare("SELECT COUNT(*) AS n FROM notification WHERE substr(dedupe_key, 1, ?) = ?")
      .get(head.length, head);
    const ordinal = Number(earlier?.["n"] ?? 0) + 1;
    return this.enqueueNotification(
      {
        dedupeKey: `${head}${ordinal}`,
        kind: fact.kind,
        subject: fact.subject,
        body: fact.body,
        ...(fact.attention ? { pushClass: "attention" as const } : {}),
        ...(fact.link === null ? {} : { link: fact.link }),
        source: fact.run === undefined || fact.run === null ? { taskRef: fact.taskRef } : { run: fact.run },
      },
      now,
    );
  }

  /**
   * The ending of an OPEN run, in words that keep the distinctions a phone
   * needs: a built attempt is a saved result, not a reviewed or published
   * one; a finished review names its verdict; a stopped attempt is stopped,
   * not failed. Failures, refusals, parks, plans and reports already page
   * through their own producers (build-failed, stalled, commit-failure,
   * malformed-*, plan-ready, report-ready, fenced, external-closed) and are
   * not repeated here. Contest lanes and repair/correction children are the
   * attempt's own and say nothing on their own.
   */
  private noteRunEnding(
    id: number,
    prior: Record<string, unknown>,
    result: { outcome: string; reason?: string; committed?: boolean },
    now: Date,
  ): void {
    if (prior["contestant"] !== null && prior["contestant"] !== undefined) return;
    const taskRef = Number(prior["task_ref"]);
    const taskId = this.externalIdFor(taskRef);
    if (taskId === null) return;
    const role = String(prior["role"]);
    const stopped = result.outcome === "failed" && result.reason === "interrupted" && this.stopOf(id) !== null;
    if (role === "builder") {
      if (stopped) {
        this.noteLifecycle({ taskRef, run: id, kind: "run-stopped", identity: `r${id}`, subject: `Attempt #${id} stopped`, body: "Its work is preserved. Resume this attempt from the task page when ready.", link: chatControlHref("recovery", taskId) }, now);
      } else if (result.outcome === "built") {
        this.noteLifecycle({
          taskRef, run: id, kind: "run-finished", identity: `r${id}`,
          subject: `Attempt #${id} built`,
          body: result.committed === false ? "It finished without a commit; the handoff explains why." : "The result is saved locally. It is not yet independently reviewed or published.",
          link: chatResultHref(taskId, id, "changes"),
        }, now);
      } else if (result.outcome === "no-change") {
        this.noteLifecycle({ taskRef, run: id, kind: "run-finished", identity: `r${id}`, subject: `Attempt #${id} finished with no changes`, body: "Nothing needed to change; the handoff explains why.", link: chatResultHref(taskId, id) }, now);
      }
      return;
    }
    if (role === "reviewer" && prior["review_attempt"] != null && prior["parent_run"] != null) {
      const parent = Number(prior["parent_run"]);
      const attempt = Number(prior["review_attempt"]);
      const link = chatResultHref(taskId, parent, "checks");
      if (stopped) {
        this.noteLifecycle({ taskRef, run: id, kind: "run-stopped", identity: `r${id}`, subject: `Independent review attempt ${attempt} stopped`, body: "The saved result is unchanged.", link }, now);
      } else if (result.outcome === "no-change") {
        const proof = this.proofVerdictFor(parent);
        const verdict = proof?.verdict ?? "none";
        const accepted = this.proofAcceptance(parent) !== null;
        const human = manualReviewOnly(proof);
        const requirements = human ? proof!.matrix.filter(row => row.state === "manual-review").map(row => `${row.id}: ${lifecycleWords(row.statement, 220)}${row.review == null ? " · No independent judgement recorded" : ` · Reviewer ${row.review.judgement === "upholds" ? "supports this finding" : row.review.judgement === "contradicts" ? "disputes this finding" : "could not confirm this finding"}. ${lifecycleWords(row.review.note, 250)}`}`) : [];
        // Each screenshot is its own existing outbox row: a failed upload
        // retries that row, never an already-confirmed earlier image. The
        // key binds the saved bytes; the sender re-proves them at upload.
        const images = human && !accepted ? this.artifactsFor(parent).filter(one => one.kind === "screenshot") : [];
        const words = human ? {
          subject: accepted ? "human acceptance recorded" : "human review needed",
          body: `${accepted ? "This result already has recorded human acceptance." : "The remaining requirements need your review; the recorded checks did not fail."}\n${requirements.join("\n")}${accepted ? "" : images.length === 0 ? "\nThe acceptance summary follows." : "\nSaved screenshots and the acceptance summary follow."}`,
        } : LIFECYCLE_REVIEW_WORDS[verdict];
        this.noteLifecycle({ taskRef, run: id, kind: "review-finished", identity: `r${id}`, subject: `Independent review finished: ${words.subject}`, body: words.body, link, attention: human && !accepted }, now);
        if (human && !accepted) {
          for (const image of images.slice(0, 8)) {
            this.noteLifecycle({ taskRef, run: parent, kind: "acceptance-evidence", identity: `r${id}-a${image.id}-${image.sha256}`,
              subject: "Saved screenshot for review", body: "Open the result to inspect this saved screenshot.", link: chatResultHref(taskId, parent) }, now);
          }
          const remaining = Math.max(0, images.length - 8);
          this.noteLifecycle({ taskRef, run: parent, kind: "acceptance-ready", identity: `r${id}`,
            subject: "Review for acceptance",
            body: `${images.length === 0 ? "No screenshots were saved for this result. " : ""}${remaining > 0 ? `${remaining} more screenshots remain; ask for the remaining images. ` : ""}Review the full requirements, checks, reviewer findings and limitations before recording your decision. Opening this link accepts nothing.`,
            link: chatControlHref("acceptance", taskId, parent) }, now);
        }
      } else {
        this.noteLifecycle({ taskRef, run: id, kind: "review-finished", identity: `r${id}`, subject: `Independent review attempt ${attempt} did not finish`, body: "The saved result is unchanged. Check the current review status for the next step.", link }, now);
      }
    }
  }

  // ---- the outbox ---------------------------------------------------------

  /** True if this is a new fact; false if the episode already knows.
   * `pushClass`/`link` (arc 3): the CLOSED attention class and machine-
   * minted console path a phone may be paged with — stamped here at
   * enqueue or never; subject and body never reach a push service. */
  enqueueNotification(
    notification: NotificationInput,
    now: Date,
  ): boolean {
    const source = notification.source;
    const run = source !== undefined && "run" in source ? this.getRun(source.run) : null;
    const taskRef = source !== undefined && "taskRef" in source ? source.taskRef : run?.taskRef ?? null;
    const ref = taskRef === null ? undefined : this.db.prepare("SELECT id, repo, external_id FROM task_ref WHERE id = ?").get(taskRef);
    // Invalid or unplaced task references remain explicitly unknown. No guessed
    // legacy backfill, and a producer cannot smuggle a project beside a run.
    const scope = ref !== undefined && ref["repo"] != null ? "task"
      : source !== undefined && "project" in source && source.project !== "" ? "project"
      : source !== undefined && "installation" in source ? "installation" : "unknown";
    const project = scope === "task" ? String(ref!["repo"]) : scope === "project" && source !== undefined && "project" in source ? source.project : null;
    const { changes, lastInsertRowid } = this.db
      .prepare(
        `INSERT OR IGNORE INTO notification (dedupe_key, kind, subject, body, created_at, push_class, link, provenance_scope, project, task_ref, task_id, source_run, recipient)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        notification.dedupeKey,
        notification.kind,
        notification.subject,
        notification.body,
        now.toISOString(),
        notification.pushClass ?? null,
        notification.link ?? null,
        scope, project, ref === undefined ? null : taskRef, ref === undefined ? null : String(ref["external_id"]), run?.id ?? null,
        notification.recipient ?? null,
      );
    // Whose act made this fact: pings follow it (see pingAllowed).
    const actor = currentActor();
    if (Number(changes) > 0 && actor !== null) {
      this.db.prepare("INSERT OR IGNORE INTO notification_actor (notification, account, lead) VALUES (?, ?, ?)").run(Number(lastInsertRowid), actor.account, actor.lead ? 1 : 0);
    }
    if (Number(changes) > 0 && run !== null && notification.recipient == null) {
      const made = this.notificationById(Number(lastInsertRowid));
      if (made !== null) this.enqueueResultShots(made, now);
    }
    return Number(changes) > 0;
  }

  /**
   * Episode semantics for recurring faults (arc 3 finding 23, generalizing
   * the routine-episode pattern): one OPEN row per prefix nags; a RESOLVED
   * one is history, and a fresh suffix keys a new row past the dedupe
   * uniqueness so a recurrence pages again instead of being suppressed
   * forever by its own past.
   */
  enqueueEpisode(
    prefix: string,
    notification: Omit<NotificationInput, "dedupeKey">,
    suffix: string,
    now: Date,
  ): boolean {
    return this.transact(() => {
      const head = `${prefix}:`;
      const open = this.db
        .prepare(
          `SELECT 1 AS hit FROM notification
            WHERE substr(dedupe_key, 1, ?) = ? AND resolved_at IS NULL LIMIT 1`,
        )
        .get(head.length, head);
      if (open !== undefined) return false;
      return this.enqueueNotification({ dedupeKey: `${head}${suffix}`, ...notification }, now);
    });
  }

  /** Close every open episode under a prefix — the fault is provably gone. */
  resolveEpisodes(prefix: string, now: Date): number {
    const head = `${prefix}:`;
    const { changes } = this.db
      .prepare(
        `UPDATE notification SET resolved_at = ?
          WHERE resolved_at IS NULL AND substr(dedupe_key, 1, ?) = ?`,
      )
      .run(now.toISOString(), head.length, head);
    return Number(changes);
  }

  notificationById(id: number): Notification | null {
    const row = this.db.prepare("SELECT * FROM notification WHERE id = ?").get(id);
    return row === undefined ? null : readNotification(row);
  }

  notificationsAfter(id: number, limit = 100): Notification[] {
    return this.db.prepare("SELECT * FROM notification WHERE id>? ORDER BY id LIMIT ?").all(id, Math.max(1,Math.min(100,limit))).map(readNotification);
  }

  listNotifications(only: "pending" | "all" = "pending"): Notification[] {
    // Resolved-but-undelivered is not pending: a decision answered before the
    // outbox ran is a fact that stopped wanting a person, and paging someone
    // about it anyway would teach them to ignore the pager.
    const where = only === "pending" ? "WHERE delivered_at IS NULL AND resolved_at IS NULL" : "";
    return this.db
      .prepare(`SELECT * FROM notification ${where} ORDER BY id`)
      .all()
      .map(readNotification);
  }

  recordDelivery(
    id: number,
    outcome: { ok: true; receipt: string | null } | { ok: false; error: string },
    now: Date,
  ): void {
    if (outcome.ok) {
      this.db
        .prepare(
          `UPDATE notification SET delivered_at = ?, receipt = ?, attempts = attempts + 1, last_attempt_at = ?, last_error = NULL
            WHERE id = ?`,
        )
        .run(now.toISOString(), outcome.receipt, now.toISOString(), id);
      return;
    }
    this.db
      .prepare(
        `UPDATE notification SET attempts = attempts + 1, last_attempt_at = ?, last_error = ?
          WHERE id = ?`,
      )
      .run(now.toISOString(), outcome.error, id);
  }

  /**
   * Close a gap's notification episode. Called when its capability verifies:
   * the next failure is a *new* fact, and a dedupe key that suppressed it
   * forever would be a gap the operator hears about exactly once per lifetime.
   */
  clearGapEpisode(repo: string, kind: string, name: string): void {
    this.db
      .prepare("DELETE FROM notification WHERE dedupe_key = ?")
      .run(`gap:${repo}:${kind}:${name}`);
  }

  /**
   * The other way an episode ends: the fact stopped wanting a person. Unlike
   * a gap — which is deleted so a recurrence can speak again — a resolved
   * decision or incident never recurs under the same key, so the row stays,
   * receipts and all.
   */
  resolveEpisode(dedupeKey: string, now: Date): void {
    this.db
      .prepare("UPDATE notification SET resolved_at = ? WHERE dedupe_key = ? AND resolved_at IS NULL")
      .run(now.toISOString(), dedupeKey);
  }

  // ---- runs ---------------------------------------------------------------

  /**
   * Open the record before the money is spent. If the process dies with the
   * agent, the row survives with outcome NULL — an attempt that was cut down
   * mid-flight, visible the next morning instead of vanished.
   *
   * THE GENERIC ADMISSION (atomic authority closure) opens exactly four
   * shapes: an ordinary builder (no parent, no lane, no open attended
   * authorization on its task), a planner (optionally continuing its own
   * same-task planner run), a scout, and a ROOT reviewer answering an open
   * review request. Every other shape has its own admission that proves
   * and consumes or binds its exact authority in one transaction —
   * `admitRepair`, `admitAttended`, `admitCorrection`, `admitContestLane`,
   * `admitRecoveredBuilder`, `admitFallback` — and this road refuses it in
   * words before any row exists. Every run PRESENTS its route authority: a
   * task with no scope presents the bare word `legacy` for the exact pair
   * it spends as; nothing opens unstamped anywhere.
   */
  startRun(
    run: {
      taskRef: number;
      leaseId: string;
      runner: string;
      model?: string;
      provider?: string;
      sessionId?: string;
      /** v47: the run's route provenance, written in this same admission
       * transaction so provenance can never lag authority. REQUIRED on
       * every road (atomic authority closure): the caller presents the
       * exact authority it holds — a sealed leg, a working plan leg, a
       * pre-routing row's sealed profile, or the bare word `legacy` on a
       * task with no scope — or no row opens. Optional in the TYPE only so
       * a caller can spread the authority it resolved; absent at runtime
       * it refuses in words. */
      route?: RouteStamp;
      /** v48 authority repair: how this run takes fallback-chain custody, proved and
       * persisted in this same insert — `base` opens the task's cycle at
       * the approved chain's first entry (inert without a chain approval),
       * `resume` takes a parked BASE tail's custody through the proven
       * transfer. A binding that cannot be proved rolls the insert back.
       * Builder-only: no other role takes custody. Every run bound to a
       * NON-primary entry — the entry's own admission, a parked tail's
       * successor, a repair turn — is admitted by admitFallback alone. */
      custody?: { kind: "base" } | { kind: "resume"; parkedRun: number };
      now: Date;
    } & (
      | {
          role?: "builder" | "planner" | "scout";
          branch: string;
          worktree: string;
          /** A planner correction continues its own same-task planner run
           * (the nonce-bound protocol repair). A builder never names one
           * here: a recovered draft is admitted by admitRecoveredBuilder,
           * a warm resume binds through bindWarmResume. */
          parentRun?: number;
        }
      // The reviewer (v29, D5): an artifact-only pass over a sealed diff.
      // No branch, no worktree — the CHECK enforces the exclusive shape,
      // and the discriminated arm makes a workspace unrepresentable rather
      // than optional. The parent is mandatory: a review reviews a run.
      | {
          role: "reviewer";
          parentRun: number;
          branch?: undefined;
          worktree?: undefined;
          /** The LIVE review request this root reviewer answers (raw
           * authority repair): proved open for exactly the parent run and
           * consumed as `dispatched` inside this same admission. A
           * correction child is admitted by admitCorrection, never here. */
          request: number;
        }
    ),
  ): number {
    return this.transact(() => this.admitRun(run, { road: "generic" }));
  }

  /**
   * THE REPAIR ADMISSION (atomic authority closure): a repair turn mends
   * exactly one LIVE same-task builder attempt — the parent exists, is
   * this task's, is a builder, is still open, and this turn runs under
   * the parent's own runner and lease — which must be the task's CURRENT
   * live claim, on the runner that claim names (repair custody closure:
   * the same tuple invariant every fallback admission proves). An
   * attended parent's authorization
   * must have spent its one attempt on that parent; a racing lane's
   * parent must be the lane's live run; a chain-bound parent must be the
   * live base tail (a fallback entry's repair is admitFallback's). The
   * stamp is the repair leg of the authority the parent spent under.
   * Value-shaped: a refusal names its reason and leaves zero rows.
   */
  admitRepair(
    run: {
      taskRef: number;
      leaseId: string;
      runner: string;
      branch: string;
      worktree: string;
      provider: string;
      model?: string;
      sessionId?: string;
      parentRun: number;
      route: RouteStamp;
      now: Date;
    },
  ): { ok: true; runId: number } | { ok: false; problem: string } {
    return this.admission(() => this.admitRun({ ...run, role: "repair" }, { road: "repair" }));
  }

  /**
   * THE ATTENDED ADMISSION (atomic authority closure): one watched attempt
   * opens under exactly ONE live authorization the caller names — open on
   * this task, unexpired, unspent, minted for this runner at this
   * generation, pinning a readable profile the stamp restates as its
   * legacy authority; a continuation names the finished parent the
   * authorization continues, nothing else names a parent. The insert
   * binds the row to the authorization and CONSUMES its one attempt in
   * the same transaction: `run.attended_authorization` and
   * `authorization.attempt_run` move together or not at all.
   */
  admitAttended(
    run: {
      taskRef: number;
      leaseId: string;
      runner: string;
      branch: string;
      worktree: string;
      provider: string;
      model?: string;
      sessionId?: string;
      parentRun?: number;
      authorization: { id: string; runner: string; generation: number };
      route: RouteStamp;
      now: Date;
    },
  ): { ok: true; runId: number } | { ok: false; problem: string } {
    const { authorization, ...rest } = run;
    return this.admission(() => this.admitRun({ ...rest, role: "builder" }, { road: "attended", authorization }));
  }

  /**
   * THE CORRECTION ADMISSION (atomic authority closure): a reviewer
   * correction continues a LIVE root review in the SAME session — the
   * parent is a same-task reviewer (the root, or a finished correction of
   * it), the root is still open and carries a session id, and this child
   * runs under the root's runner, lease, and exactly that session. One
   * use: a parent takes exactly one correction child, ever. Nothing
   * answers a review request here — the root spent it.
   */
  admitCorrection(
    run: {
      taskRef: number;
      leaseId: string;
      runner: string;
      provider: string;
      model?: string;
      sessionId: string;
      parentRun: number;
      route: RouteStamp;
      now: Date;
    },
  ): { ok: true; runId: number } | { ok: false; problem: string } {
    return this.admission(() => this.admitRun({ ...run, role: "reviewer" }, { road: "correction" }));
  }

  /**
   * THE CONTEST LANE ADMISSION (atomic authority closure): a racing agent's
   * run opens on ITS lane, in a contest still dispatching or racing, under
   * the contest's live custody — the caller's lease, runner, and watch
   * incarnation are exactly the ones the contest was stamped with — and it
   * presents the lane's STORED sealed profile as its legacy authority: no
   * synthesized profile, no other digest. The lane's pointer moves to the
   * row inside the insert (from free, or from the parked attempt this run
   * resumes); a lane that moved rolls the row back.
   */
  admitContestLane(
    run: {
      taskRef: number;
      leaseId: string;
      runner: string;
      incarnation: string | null;
      branch: string;
      worktree: string;
      provider: string;
      model?: string;
      sessionId?: string;
      contestant: number;
      parentRun?: number;
      route: RouteStamp;
      now: Date;
    },
  ): { ok: true; runId: number } | { ok: false; problem: string } {
    const { incarnation, ...rest } = run;
    return this.admission(() => this.admitRun({ ...rest, role: "builder" }, { road: "contest", incarnation }));
  }

  /**
   * THE RECOVERED-DRAFT ADMISSION (atomic authority closure): a fresh
   * builder attempt that inherits an INTERRUPTED attempt's draft names it
   * as its parent — this task's own builder (or its repair turn), left in
   * this very worktree and branch, either still open with a lease nobody
   * holds any more or ended as `failed` for `interrupted`. A planner, a
   * scout, a reviewer, a parked or built run, or an attempt still being
   * built is no recovery grant, and nothing opens over it.
   */
  admitRecoveredBuilder(
    run: {
      taskRef: number;
      leaseId: string;
      runner: string;
      branch: string;
      worktree: string;
      provider: string;
      model?: string;
      sessionId?: string;
      recoveredFrom: number;
      custody?: { kind: "base" } | { kind: "resume"; parkedRun: number };
      route: RouteStamp;
      now: Date;
    },
  ): { ok: true; runId: number } | { ok: false; problem: string } {
    const { recoveredFrom, ...rest } = run;
    return this.admission(() => this.admitRun({ ...rest, role: "builder", parentRun: recoveredFrom }, { road: "recovered" }));
  }

  /** A dedicated admission's transaction: a refusal thrown inside rolls
   * every write back and comes out as words; anything else propagates. */
  private admission(body: () => number): { ok: true; runId: number } | { ok: false; problem: string } {
    try {
      return { ok: true, runId: this.transact(body) };
    } catch (error) {
      if (error instanceof RunAdmissionRefused) return { ok: false, problem: error.message };
      throw error;
    }
  }

  private admitRun(
    run: {
      taskRef: number;
      leaseId: string;
      runner: string;
      model?: string;
      provider?: string;
      sessionId?: string;
      contestant?: number;
      route?: RouteStamp;
      custody?: { kind: "base" } | { kind: "resume"; parkedRun: number };
      now: Date;
      role?: "builder" | "repair" | "planner" | "scout" | "reviewer";
      branch?: string | undefined;
      worktree?: string | undefined;
      parentRun?: number | undefined;
      request?: number | undefined;
    },
    road:
      | { road: "generic" }
      | { road: "repair" }
      | { road: "attended"; authorization: { id: string; runner: string; generation: number } }
      | { road: "correction" }
      | { road: "contest"; incarnation: string | null }
      | { road: "recovered" },
  ): number {
    const role = run.role ?? "builder";
    // THE ADMISSION PROOF (v48, authority repair): a run's route provenance is held to
    // the authority the task holds BEFORE the row exists — the stamp's
    // shape, its phase against the role, its exact provider and model
    // against what the run will spend as, and its digest and leg against
    // the sealed route, the approved chain's base entry the run is bound
    // to, or a proven pre-routing row. A stamp that cannot be proved opens
    // no run: nothing spends with provenance that disagrees with authority.
    // The stamp is the authority for the provider and model columns when
    // the caller left them unsaid; a caller who says otherwise is refused.
    //
    // The store DICTATES nothing (v48 authority repair): the caller PRESENTS the exact
    // route authority it holds — the sealed leg for its phase, the working
    // plan leg before approval, the sealed profile of a pre-routing row, a
    // contest lane's or attended session's pinned profile, the bare word
    // `legacy` on a task with no scope — or no row opens, in words.
    //
    // `fallback` provenance NEVER enters here (v48 integrity): a run bound
    // to a non-primary chain entry is admitted by admitFallback alone,
    // which re-proves the live cycle, tail, index, digest, auth mode,
    // provider, model, repair binding, and approved mirror in one body.
    const refuse: (problem: string) => never = problem => {
      throw new RunAdmissionRefused(`run admission refused for task_ref ${run.taskRef} (${role}): ${problem}`);
    };
    let provider = run.provider ?? null;
    let model = run.model ?? null;
    const ref = this.refForId(run.taskRef);
    if (ref === null) throw new RunAdmissionRefused(`run admission refused: task_ref ${run.taskRef} is not a task`);
    const taskId = ref.externalId;
    const scope = this.getScope(taskId);
    const contestant = run.contestant ?? null;
    // THE ROAD (atomic authority closure): every shape with its own
    // admission is refused here in words when it arrives by any other
    // door — the generic road opens nothing a dedicated road proves.
    if (role === "repair" && road.road !== "repair") refuse("a repair turn is admitted by admitRepair — the generic admission opens no repair");
    if (contestant !== null && road.road !== "contest") refuse("a contest lane's run is admitted by admitContestLane — the generic admission opens nothing on a lane");
    if (road.road === "contest" && contestant === null) refuse("a contest lane admission names its lane");
    if (road.road === "correction" && role !== "reviewer") refuse("a correction child is a reviewer");
    if (road.road === "recovered" && role !== "builder") refuse("a recovered draft is a builder's");
    if (road.road === "attended" && role !== "builder") refuse("an attended attempt is a builder's");
    if (road.road === "repair" && run.parentRun === undefined) refuse("a repair turn mends exactly one live builder attempt — none was named");
    const openAuthorization = this.openAuthorizationFor(run.taskRef);
    if (road.road === "generic" && openAuthorization !== null && role === "builder") {
      refuse(`the task holds an open attended authorization ${openAuthorization.id} — an attended attempt is admitted by admitAttended, and nothing else builds beside it`);
    }
    if (road.road === "attended" && openAuthorization === null) refuse("this task holds no open attended authorization — nothing opens as an attended attempt");
    if (run.route !== undefined && (run.route as { chosen?: unknown }).chosen === "fallback") {
      refuse("an approved fallback entry is admitted only through admitFallback — the generic admission opens nothing as `fallback`");
    }
    // EVERY run presents (atomic authority closure): a task with no scope
    // presents the bare word `legacy` for the pair it spends as; a task
    // with a scope presents the leg its authority names. Nothing opens
    // unstamped — the words say what the caller would have had to hold.
    if (run.route === undefined) {
      const could = this.routeAuthorityFor(run.taskRef, role, null, { provider: provider ?? "claude", model });
      refuse(
        scope === null
          ? "this task has no scope and the caller presented no route authority — a run on such a task presents the bare word legacy for the exact pair it spends as"
          : `this task has a scope and the caller presented no route authority — ${
              could !== null && !could.ok ? could.problem : `nothing opens unstamped on it (present its ${phaseOfRole(role)} leg)`
            }`,
      );
    }
    const custody = run.custody ?? null;
    if (custody !== null && role !== "builder") refuse(`chain custody is a builder's to take — a ${role} run takes none`);
    if (custody !== null && (contestant !== null || road.road === "attended")) refuse("a contest lane or attended session spends under its own authority — it takes no chain custody");
    const parent = run.parentRun === undefined ? null : this.getRun(run.parentRun);
    if (run.parentRun !== undefined && parent === null) refuse(`run #${run.parentRun} does not exist — nothing continues it`);
    // A parent is this task's own (raw authority repair): every lineage is
    // proved here, in the insert, and no later stamp can bind one. Which
    // lineages the generic road admits at all is narrow (atomic authority
    // closure): a planner continuing its own planner run. A builder's
    // parent is a recovered draft (admitRecoveredBuilder) or a
    // continuation's finished attempt (admitAttended); a scout has none.
    if (parent !== null && parent.taskRef !== run.taskRef) {
      refuse(`run #${parent.id} belongs to task_ref ${parent.taskRef} — a ${role} run continues its own task's run only`);
    }
    if (road.road === "generic" && parent !== null) {
      if (role === "builder") refuse(`a builder names no parent here — a recovered draft is admitted by admitRecoveredBuilder (run #${parent.id})`);
      if (role === "scout") refuse("a scout continues nothing");
      if (role === "planner" && parent.role !== "planner") refuse(`run #${parent.id} is a ${parent.role} run — a planner correction continues its own planner run only`);
    }
    // THE LIVE REVIEW REQUEST (raw authority repair): a root reviewer
    // answers exactly one OPEN request for its parent run, consumed as
    // `dispatched` in this same transaction below; a correction child —
    // admitted by admitCorrection — continues a LIVE root in its exact
    // session and answers no request of its own. Nothing else opens as a
    // reviewer.
    let requestToConsume: number | null = null;
    let reviewAttempt: number | null = null;
    if (role === "reviewer") {
      if (parent === null) refuse("a review reviews a run — none was named");
      const request = run.request;
      if (road.road === "correction") {
        if (request !== undefined) refuse(`reviewer run #${parent.id} is a review already — a correction child continues it and answers no request of its own`);
        if (parent.role !== "reviewer") refuse(`run #${parent.id} is a ${parent.role} run — a correction continues a review`);
        // The lineage is linear — each correction continues the previous
        // (already-ended) one — and it is live only while its ROOT
        // reviewer, the run that spent the request, is still open.
        let root: Run = parent;
        const seen = new Set<number>([parent.id]);
        while (root.role === "reviewer" && root.parentRun !== null) {
          const above = this.getRun(root.parentRun);
          if (above === null || above.role !== "reviewer") break;
          if (seen.has(above.id)) refuse(`reviewer run #${parent.id}'s lineage loops — nothing continues it`);
          seen.add(above.id);
          root = above;
        }
        if (root.taskRef !== run.taskRef) refuse(`reviewer run #${root.id} belongs to task_ref ${root.taskRef} — a correction continues its own task's review only`);
        if (root.outcome !== null) refuse(`the root reviewer run #${root.id} has ended — a correction child continues a live review only`);
        if (parent.id !== root.id && parent.outcome === null) refuse(`correction run #${parent.id} is still open — the next correction continues an ended one`);
        // THE ONE-USE SAME-SESSION GRANT (atomic authority closure): the
        // root's announced session is the only authority for a correction,
        // and this child runs as the root does — same runner, same lease,
        // exactly that session. A parent takes one correction, ever.
        if (root.sessionId === null) refuse(`the root reviewer run #${root.id} announced no session — nothing corrects it in one`);
        if (run.sessionId === undefined || run.sessionId !== root.sessionId) refuse(`a correction resumes the root reviewer's session ${root.sessionId} — ${run.sessionId === undefined ? "none was named" : `${run.sessionId} is another`}`);
        if (run.runner !== root.runner) refuse(`the root reviewer run #${root.id} runs on ${root.runner} — a correction on ${run.runner} is another machine's`);
        if (run.leaseId !== root.leaseId) refuse(`the root reviewer run #${root.id} holds lease ${root.leaseId} — a correction under lease ${run.leaseId} is not its own`);
        const taken = this.db.prepare("SELECT id FROM run WHERE parent_run = ? AND role = 'reviewer' LIMIT 1").get(parent.id) as { id: number } | undefined;
        if (taken !== undefined) refuse(`reviewer run #${parent.id} was corrected once already (run #${Number(taken.id)}) — a correction grant is one-use`);
      } else {
        if (parent.role === "reviewer") refuse(`reviewer run #${parent.id} is a review already — a correction child is admitted by admitCorrection`);
        if (request === undefined) refuse(`run #${parent.id} is reviewed only through its open review request — none was presented`);
        const open = this.db.prepare("SELECT basis, origin, mode_digest FROM review_request WHERE id = ? AND run = ? AND consumed_at IS NULL").get(request, parent.id) as Record<string, unknown> | undefined;
        if (open === undefined) refuse(`review request #${request} is not run #${parent.id}'s open request — nothing reviews without one`);
        // THE BOUNDED ALLOWANCE (v50): a root opens only while its source
        // has no successful review, no root still open, and fewer than
        // REVIEW_ROOT_ATTEMPTS roots — and it takes the next ordinal, in
        // this same insert. The partial uniques backstop every clause.
        const allowance = this.rootReviewAdmissionProblem(parent.id);
        if (allowance !== null) refuse(allowance.detail);
        reviewAttempt = this.nextRootReviewAttempt(parent.id);
        if (reviewAttempt > REVIEW_ROOT_ATTEMPTS) refuse(`run #${parent.id} has spent all ${REVIEW_ROOT_ATTEMPTS} review attempts — nothing retries a fourth time`);
        // The raw insert also re-proves the narrow signed retry exception;
        // presenting a queued automatic row alone grants no new authority.
        if (reviewRequestOriginOf(open!) === "automatic") {
          const replay = this.automaticReviewReplayProblem(parent.id, request);
          if (replay !== null) {
            const retry = this.automaticReviewRetryAuthority(parent.id, run.now, request);
            if (!retry.ok) refuse(`${replay}; ${retry.detail}`);
            else if (open!["basis"] !== "mode" || open!["mode_digest"] !== retry.mode.digest) refuse("the automatic review retry names another mode signature");
          }
        }
        requestToConsume = request;
      }
    } else if (run.request !== undefined) {
      refuse(`a ${role} run answers no review request`);
    }
    // THE REPAIR PARENT (atomic authority closure): exactly one live
    // same-task builder attempt, mended under its own runner and lease.
    if (road.road === "repair") {
      if (parent === null) refuse("a repair turn mends exactly one live builder attempt — none was named");
      if (parent.role !== "builder") refuse(`run #${parent.id} is a ${parent.role} run — a repair turn mends a builder attempt`);
      if (parent.outcome !== null) refuse(`run #${parent.id} ended as ${parent.outcome} — a repair turn mends a live attempt only`);
      if (parent.runner !== run.runner) refuse(`run #${parent.id} runs on ${parent.runner} — its repair turn on ${run.runner} is another machine's`);
      if (parent.leaseId !== run.leaseId) refuse(`run #${parent.id} holds lease ${parent.leaseId} — a repair turn under lease ${run.leaseId} is not its own`);
      // THE CURRENT CLAIM (final authority closure): an open parent whose
      // lease is no longer the task's live claim — released, expired, or
      // superseded by a newer generation — is an attempt nobody is
      // building; copying its runner and lease proves nothing. The lease
      // must be the claim that holds the task RIGHT NOW.
      const holding = this.currentLiveLease(run.taskRef, run.now);
      if (holding !== parent.leaseId) {
        refuse(`run #${parent.id}'s lease ${parent.leaseId} is not this task's current live claim (${holding === null ? "nothing holds it" : `${holding} does`}) — a repair turn mends an attempt still being built under its claim`);
      }
      // THE EXACT CLAIM TUPLE (repair custody closure): a live lease is
      // held by ONE runner, and the parent row's runner column is not
      // that fact — a claim re-taken under the same lease id by another
      // machine, or a row written beside a claim it never held, would
      // pass the copy above. The same tuple invariant every fallback
      // admission proves: this task, this lease, on the runner the claim
      // names — or no row, in the same words.
      const claimProblem = this.custodyClaimProblem({ taskRef: run.taskRef, leaseId: run.leaseId, runner: run.runner }, run.now, "a repair turn");
      if (claimProblem !== null) refuse(claimProblem);
    }
    // THE LIVE AUTHORIZATION (atomic authority closure): an attended
    // attempt opens under exactly the authorization the caller names —
    // open on this task, unexpired by its own clock, its one attempt
    // unspent, minted for THIS runner at THIS generation, pinning a
    // readable profile the run presents as its `legacy` authority. A
    // repair turn on an attended parent runs under the authorization that
    // spent its attempt on that parent. Any other road on a task with an
    // open authorization refused above.
    let authorizationToConsume: AttendedAuthorization | null = null;
    if (road.road === "attended") {
      const live = openAuthorization as AttendedAuthorization;
      const named = road.authorization;
      if (live.id !== named.id) refuse(`the task's open attended authorization is ${live.id}, not ${named.id}`);
      if (live.closedAt !== null) refuse(`the attended authorization ${live.id} is closed — nothing spends under it`);
      if (Date.parse(live.absoluteExpiry) <= run.now.getTime()) refuse(`the attended authorization ${live.id} expired at ${live.absoluteExpiry} — nothing spends under it`);
      if (live.attemptRun !== null) refuse(`the attended authorization ${live.id} already spent its one attempt on run #${live.attemptRun} — nothing else opens under it`);
      if (live.runner !== run.runner || named.runner !== run.runner) refuse(`the attended authorization ${live.id} names runner ${live.runner} — an attempt on ${run.runner}${named.runner !== run.runner ? ` presented as ${named.runner}` : ""} is not its own`);
      if (live.runnerGeneration !== named.generation) refuse(`the attended authorization ${live.id} was minted for ${live.runner} at generation ${live.runnerGeneration}, not ${named.generation}`);
      let pinned: ExecutionProfile | null = null;
      try {
        const terms = JSON.parse(live.termsJson) as { profileJson?: unknown };
        pinned = profileFromJson(typeof terms.profileJson === "string" ? terms.profileJson : null);
      } catch {
        pinned = null;
      }
      if (pinned === null) refuse(`the attended authorization ${live.id} pins no readable profile — nothing spends under it`);
      if ((run.route as { chosen?: unknown }).chosen !== "legacy") refuse(`an attended builder spends under the authorization's pinned profile (a legacy stamp), not as a ${String((run.route as { chosen?: unknown }).chosen)} leg`);
      if (live.parentRun === null) {
        if (parent !== null) refuse(`the attended authorization ${live.id} continues nothing — an attempt under it names no parent`);
      } else {
        if (parent === null || parent.id !== live.parentRun) refuse(`the attended authorization ${live.id} continues run #${live.parentRun} — ${parent === null ? "no parent was named" : `run #${parent.id} is not it`}`);
        if (parent.outcome === null) refuse(`run #${parent.id} is still open — a continuation continues a finished attempt`);
      }
      authorizationToConsume = live;
    } else if (road.road === "repair" && openAuthorization !== null) {
      const live = openAuthorization;
      if (Date.parse(live.absoluteExpiry) <= run.now.getTime()) refuse(`the attended authorization ${live.id} expired at ${live.absoluteExpiry} — nothing spends under it`);
      if (parent === null || live.attemptRun !== parent.id) refuse(`the attended authorization ${live.id} spent its attempt on run #${live.attemptRun ?? "none"} — a repair turn mends that attempt only`);
      if ((run.route as { chosen?: unknown }).chosen !== "legacy") refuse(`an attended repair spends under the authorization's pinned profile (a legacy stamp), not as a ${String((run.route as { chosen?: unknown }).chosen)} leg`);
    }
    // THE LANE (atomic authority closure): a contest lane's run is one of
    // THIS task's racing agents, in a contest still dispatching or racing,
    // under the contest's live custody — the lease, runner, and watch
    // incarnation the contest was stamped with — on a lane whose pointer
    // is free or held by exactly the parked attempt this run resumes, and
    // it presents the lane's STORED sealed profile as its `legacy`
    // authority. The pointer moves to the row below, in this transaction.
    let lane: Contestant | null = null;
    if (road.road === "contest") {
      lane = this.getContestant(contestant as number);
      const contest = lane === null ? null : this.getContest(lane.contest);
      if (lane === null || contest === null || contest.taskRef !== run.taskRef) refuse(`contestant ${contestant} is not one of this task's racing agents`);
      if (contest.state !== "dispatching" && contest.state !== "racing") refuse(`the contest is ${contest.state} — its lanes admit nothing`);
      if (contest.currentLeaseId === null || contest.currentLeaseId !== run.leaseId) refuse(`the contest holds lease ${contest.currentLeaseId ?? "none"} — a lane run under lease ${run.leaseId} is not its custody`);
      if (contest.runner === null || contest.runner !== run.runner) refuse(`the contest runs on ${contest.runner ?? "no runner"} — a lane run on ${run.runner} is another machine's`);
      if ((contest.incarnation ?? null) !== (road.incarnation ?? null)) refuse(`the contest was dispatched by watch incarnation ${contest.incarnation ?? "none"}, not ${road.incarnation ?? "none"}`);
      if (lane.profile == null) refuse(`contestant ${lane.id} carries no sealed profile — nothing spends on the lane`);
      // THE LIVE LANE, exactly (final authority closure): a lane that has
      // ended admits nothing; a stored profile whose provider, model, or
      // repair model disagrees with the lane's own columns is a row two
      // authorities wrote, and no stamp is derived from or accepted on it;
      // and the contest's stamped lease must be the task's CURRENT live
      // claim, not merely the lease the contest remembers.
      const laneProblem = laneAuthorityProblem(lane);
      if (laneProblem !== null) refuse(laneProblem);
      const laneHolding = this.currentLiveLease(run.taskRef, run.now);
      if (laneHolding !== run.leaseId) refuse(`the contest's lease ${run.leaseId} is not this task's current live claim (${laneHolding === null ? "nothing holds it" : `${laneHolding} does`}) — a lane run opens under live custody only`);
      if (lane.activeRun !== null && !(parent !== null && lane.activeRun === parent.id && parent.outcome === "parked")) {
        refuse(`contestant ${contestant} already holds run #${lane.activeRun} — one live run per racing agent`);
      }
      if (parent !== null && (parent.contestant !== lane.id || parent.outcome !== "parked")) refuse(`run #${parent.id} is not this lane's parked attempt — nothing resumes it`);
      const leg = run.route as RouteStamp;
      if (leg.chosen !== "legacy") refuse(`a contest lane spends under its race-approved profile (a legacy stamp), not as a ${String(leg.chosen)} leg`);
      const expected = `profile:${profileDigestOf(lane.profile)}`;
      if (leg.routeDigest !== expected) refuse(`a contest lane spends under its race-approved profile, not ${leg.routeDigest}`);
    }
    // THE RECOVERY GRANT (atomic authority closure): the interrupted
    // attempt whose draft this builder inherits — this task's own builder
    // or repair turn, left in this very worktree on this branch, either
    // ended as `failed` for `interrupted` or still open under a lease
    // nobody holds any more.
    if (road.road === "recovered") {
      if (parent === null) refuse("a recovered draft names the interrupted attempt it inherits — none was named");
      const grant = this.recoveryGrantProblem(parent, { taskRef: run.taskRef, branch: run.branch ?? "", worktree: run.worktree ?? "" }, run.now);
      if (grant !== null) refuse(grant);
    }
    // CHAIN CUSTODY, decided before the row (v48 authority repair): a repair turn inherits
    // exactly its SAME-TASK parent's binding — and only while that parent IS
    // the live tail of the task's open cycle under the approved chain (v48
    // integrity): a parent whose custody has moved, ended, or never existed
    // vouches for nothing. A reviewer, planner, or builder child never
    // inherits. Base and parked-resume custody are proved here and
    // written below, in this transaction.
    let binding: { cycle: number | null; index: number; entryDigest: string; authMode: "subscription" | "api-key" | null } | null = null;
    if (role === "repair" && parent !== null) {
      if (parent.chainCycle != null || parent.chainIndex != null || parent.entryDigest != null) {
        if (parent.chainCycle == null || parent.chainIndex == null || parent.entryDigest == null) {
          refuse(`run #${parent.id}'s chain binding is not whole — nothing repairs under it`);
        }
        if (parent.chainIndex > 0) {
          refuse(`run #${parent.id} is bound to fallback entry ${parent.chainIndex} — its repair turn is admitted only through admitFallback`);
        }
        const tail = this.liveTailProblem(run.taskRef, taskId, parent);
        if (tail !== null) refuse(tail);
        binding = { cycle: parent.chainCycle, index: parent.chainIndex, entryDigest: parent.entryDigest, authMode: parent.authMode ?? null };
      }
    }
    const chain = role === "builder" && contestant === null && road.road !== "attended" ? this.approvedChainOf(taskId) : null;
    // A CHAIN approval dispatches only through its cycle (v48 integrity):
    // a builder on such a task PRESENTS its custody — the base, or the
    // parked base tail it resumes — or no row opens. A row outside the
    // cycle would be one nothing could spend on, and it is not created.
    if (chain !== null && custody === null) {
      refuse("this task's approval sealed a fallback chain — a build takes the chain's custody (base, or the parked tail it resumes) or opens nothing");
    }
    let parkedTail: Run | null = null;
    if (custody !== null && custody.kind === "resume") {
      parkedTail = this.getRun(custody.parkedRun);
      if (parkedTail === null || parkedTail.taskRef !== run.taskRef || parkedTail.outcome !== "parked" || parkedTail.chainCycle == null || parkedTail.chainIndex == null || parkedTail.entryDigest == null) {
        refuse(`run #${custody.parkedRun} is not this task's parked chain tail — nothing resumes its custody`);
      }
      if (chain === null) refuse("the chain approval no longer stands — nothing resumes custody under it");
      if (parkedTail.chainIndex > 0) {
        refuse(`run #${parkedTail.id} parked on fallback entry ${parkedTail.chainIndex} — its successor is admitted only through admitFallback`);
      }
      const entry = chain[parkedTail.chainIndex];
      if (entry === undefined || entryDigestOf(entry) !== parkedTail.entryDigest) {
        refuse(`the parked tail is bound to chain entry ${parkedTail.chainIndex} under a digest the approved chain no longer carries`);
      }
      const tail = this.liveTailProblem(run.taskRef, taskId, parkedTail);
      if (tail !== null) refuse(tail);
      binding = { cycle: parkedTail.chainCycle, index: parkedTail.chainIndex, entryDigest: parkedTail.entryDigest, authMode: parkedTail.authMode ?? null };
    } else if (custody !== null && custody.kind === "base" && chain !== null) {
      const base = chain[0];
      if (base === undefined) refuse("the approved chain has no base entry");
      binding = { cycle: null, index: 0, entryDigest: entryDigestOf(base), authMode: base.authMode };
    }
    const bound = binding === null ? null : { index: binding.index, entryDigest: binding.entryDigest };
    const stampProvider = typeof (run.route as { provider?: unknown }).provider === "string" ? (run.route as { provider: string }).provider : null;
    const stampModel = (run.route as { model?: unknown }).model;
    provider = provider ?? stampProvider;
    model = model ?? (typeof stampModel === "string" ? stampModel : null);
    // A racing lane's repair turn is proved against the lane exactly as
    // its build was (atomic authority closure): the parent's lane is the
    // authority the repair leg spends under.
    const proofLane = contestant ?? (road.road === "repair" && parent !== null ? parent.contestant : null);
    if (proofLane !== null && contestant === null) {
      const parentLane = this.getContestant(proofLane);
      const parentContest = parentLane === null ? null : this.getContest(parentLane.contest);
      if (parentLane === null || parentContest === null || parentContest.taskRef !== run.taskRef) refuse(`contestant ${proofLane} is not one of this task's racing agents`);
      if (parentContest.state !== "dispatching" && parentContest.state !== "racing") refuse(`the contest is ${parentContest.state} — its lanes admit nothing`);
      if (parentLane.activeRun !== (parent as Run).id) refuse(`contestant ${proofLane} holds run #${parentLane.activeRun ?? "none"} — a repair turn mends the lane's live attempt only`);
    }
    const problem = this.routeAdmissionProblem(
      { taskRef: run.taskRef, role, provider: provider ?? "claude", model, contestant: proofLane, chain: bound },
      run.route,
      run.now,
    );
    if (problem !== null) refuse(problem);
    const stamp = run.route as RouteStamp;
    const qualityMode: QualityMode =
      role === "reviewer" && parent !== null
        ? parent.qualityMode ?? "default"
        : (() => {
            const row = this.db
              .prepare(
                `SELECT task_scope.quality_mode FROM task_ref
                  LEFT JOIN task_scope ON task_scope.task_id = task_ref.external_id AND task_ref.backend = ?
                 WHERE task_ref.id = ?`,
              )
              .get(BUILT_IN, run.taskRef);
            return row?.["quality_mode"] === "strict" ? "strict" : "default";
          })();
    // THE CURRENT CLAIM (final admission closure): custody that changes
    // fallback state — the base that opens the cycle, the resume that
    // moves its tail — is taken only under the lease that holds the task
    // now, on the runner that claim names; proved before any write.
    if (custody !== null && ((custody.kind === "base" && chain !== null && binding !== null) || (custody.kind === "resume" && parkedTail !== null))) {
      const claimProblem = this.custodyClaimProblem({ taskRef: run.taskRef, leaseId: run.leaseId, runner: run.runner }, run.now, custody.kind === "base" ? "base custody" : "a parked tail's resume");
      if (claimProblem !== null) refuse(claimProblem);
    }
    // THE CUSTODY WRITE (v48 authority repair), before the row and in the
    // same transaction: a base cycle that cannot open (one is live already)
    // throws, and no row is ever created outside the custody it was
    // admitted under.
    let cycleId: number | null = binding?.cycle ?? null;
    if (custody !== null && custody.kind === "base" && chain !== null && binding !== null) {
      const opened = this.openFallbackCycle(run.taskRef, chainDigestOf(chain), null, run.now);
      if (!opened.ok) refuse("the task's fallback cycle is live — base custody cannot open beside it");
      cycleId = opened.id;
    }
    const inserted = this.db
      .prepare(
        `INSERT INTO run (task_ref, lease_id, runner, branch, worktree, model, role, provider, parent_run, session_id, contestant, quality_mode,
                          chain_cycle, chain_index, entry_digest, auth_mode, attended_authorization, started_at, review_attempt)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        run.taskRef,
        run.leaseId,
        run.runner,
        run.branch ?? null,
        run.worktree ?? null,
        model,
        role,
        provider ?? "claude",
        run.parentRun ?? null,
        run.sessionId ?? null,
        contestant,
        qualityMode,
        cycleId,
        binding === null || cycleId === null ? null : binding.index,
        binding === null || cycleId === null ? null : binding.entryDigest,
        binding === null || cycleId === null ? null : binding.authMode,
        // The attended binding rides the insert (atomic authority closure):
        // a row admitted under an authorization is bound to it from birth.
        authorizationToConsume === null ? null : authorizationToConsume.id,
        run.now.toISOString(),
        // The root reviewer's ordinal (v50) rides the insert: a root and
        // its attempt number are one fact, and the ordinal index refuses a
        // duplicate before any request is consumed.
        reviewAttempt,
      );
    const id = Number(inserted.lastInsertRowid);
    // The provenance row lands in the same transaction as the run row —
    // proved above, written here; a run and its route are one fact.
    this.writeRunRoute(id, stamp, run.now);
    if (role === "reviewer" && parent?.role === "reviewer" && parent.watchIncarnation != null) {
      this.db.prepare("UPDATE run SET watch_incarnation = ? WHERE id = ?").run(parent.watchIncarnation, id);
    }
    if (requestToConsume !== null) {
      // The request is spent by the very row that answers it — a CAS on the
      // open request proved above; a request consumed under us rolls the
      // row back.
      // …and bound (v50) to the root that answers it: the request row
      // names its attempt from the same transaction that opened it.
      const consumed = this.db
        .prepare("UPDATE review_request SET consumed_at = ?, consumed_reason = 'dispatched', reviewer_run = ? WHERE id = ? AND run = ? AND consumed_at IS NULL AND reviewer_run IS NULL")
        .run(run.now.toISOString(), id, requestToConsume, run.parentRun ?? null);
      if (Number(consumed.changes) !== 1) refuse(`review request #${requestToConsume} was consumed under this admission — nothing reviews without it`);
    }
    if (authorizationToConsume !== null) {
      // THE ONE ATTEMPT, consumed by the very row that spends it (atomic
      // authority closure): a CAS on the open, unspent authorization
      // proved above — one that moved under us rolls the row back, and
      // `run.attended_authorization` and `authorization.attempt_run` can
      // never disagree.
      const consumed = this.db
        .prepare(
          `UPDATE attended_authorization SET attempt_run = ?, consumed_at = ?
            WHERE id = ? AND closed_at IS NULL AND attempt_run IS NULL AND runner = ? AND runner_generation = ?`,
        )
        .run(id, run.now.toISOString(), authorizationToConsume.id, run.runner, authorizationToConsume.runnerGeneration);
      if (Number(consumed.changes) !== 1) refuse(`the attended authorization ${authorizationToConsume.id} moved under this admission — its attempt did not bind`);
    }
    if (lane !== null) {
      // The lane's pointer moves to this row — from free, or from the parked
      // attempt this run resumes — through a CAS on the generation proved
      // above; a lane that moved under us rolls the row back.
      const claimed = this.db
        .prepare("UPDATE contestant SET active_run = ?, generation = generation + 1 WHERE id = ? AND generation = ? AND (active_run IS NULL OR active_run = ?)")
        .run(id, lane.id, lane.generation, lane.activeRun);
      if (Number(claimed.changes) !== 1) refuse(`contestant ${lane.id} moved under this admission — its lane did not bind`);
    }
    if (custody !== null && custody.kind === "base" && cycleId !== null) {
      const tailed = this.db
        .prepare("UPDATE fallback_cycle SET tail_run = ?, updated_at = ? WHERE id = ? AND state = 'open' AND tail_run IS NULL AND cursor = 0")
        .run(id, run.now.toISOString(), cycleId);
      if (Number(tailed.changes) === 0) refuse("the task's fallback cycle moved under this admission — base custody did not bind");
    } else if (custody !== null && custody.kind === "resume" && parkedTail !== null) {
      // The parked-resume transfer: the tail moves to this run through a
      // CAS on the very tail proved above.
      const moved = this.db
        .prepare("UPDATE fallback_cycle SET tail_run = ?, updated_at = ? WHERE id = ? AND state = 'open' AND tail_run = ?")
        .run(id, run.now.toISOString(), parkedTail.chainCycle, parkedTail.id);
      if (Number(moved.changes) === 0) refuse(`run #${parkedTail.id}'s cycle is not open with it as the parked tail — nothing resumes its custody`);
    }
    // The start fact (Telegram task updates), after every proof above so a
    // refused admission says nothing: one per ATTEMPT — a builder, planner
    // or scout head, or a root reviewer. A repair turn and a correction
    // child are the attempt's own; a contest lane is the tournament's; a
    // planner correction continues its own run.
    if (road.road !== "repair" && road.road !== "correction" && contestant === null && !(role === "planner" && parent !== null)) {
      const agent = lifecycleWords(`${provider ?? "claude"}${model === null ? "" : ` · ${model}`}`, 60);
      const words =
        role === "reviewer"
          ? { subject: `Independent review started (attempt ${reviewAttempt ?? 1})`, body: `Reviewing the saved result of attempt #${run.parentRun}. Running on ${agent}.`, link: chatResultHref(taskId, run.parentRun as number, "checks") }
          : role === "planner"
            ? { subject: `Planning started (run #${id})`, body: `Drafting the scope and plan on ${agent}.`, link: chatControlHref("planning", taskId) }
            : role === "scout"
              ? { subject: `Scouting started (run #${id})`, body: `A read-only look on ${agent}; what comes back is a report.`, link: chatControlHref("task", taskId) }
              : { subject: road.road === "recovered" ? `Attempt #${id} resumed from its preserved draft` : `Attempt #${id} started`, body: `Building on ${agent}.`, link: chatControlHref("task", taskId) };
      this.noteLifecycle({ taskRef: run.taskRef, run: id, kind: "run-started", identity: `r${id}`, ...words }, run.now);
    }
    return id;
  }

  /**
   * THE CURRENT CLAIM, exactly (final admission closure): every admission
   * that changes fallback state — the base that opens a cycle, an entry
   * admitted from a pending edge, a parked tail's resume, a repair turn
   * under the live tail — proves in its own transaction that the run it
   * opens is the task's, under the lease that holds the task RIGHT NOW,
   * on the runner that claim names. A lease nobody holds, one released,
   * expired, or superseded by a newer generation, or a claim another
   * machine holds admits nothing: the words say which, and no cycle,
   * edge, tail, or claim moves. Shared by the fallback road, the primary
   * repair road, and the generic road's custody so all refuse in the
   * same words.
   */
  private custodyClaimProblem(run: { taskRef: number; leaseId: string; runner: string }, now: Date, what: string): string | null {
    const holding = this.currentLiveLease(run.taskRef, now);
    if (holding !== run.leaseId) {
      return `lease ${run.leaseId} is not this task's current live claim (${holding === null ? "nothing holds it" : `${holding} does`}) — ${what} opens under the claim that holds the task now`;
    }
    const claim = this.db.prepare("SELECT runner FROM claim WHERE lease_id = ? AND task_ref = ?").get(run.leaseId, run.taskRef) as { runner: string } | undefined;
    if (claim === undefined) return `lease ${run.leaseId} is not one of this task's claims — ${what} opens under the claim that holds the task now`;
    if (claim.runner !== run.runner) return `this task's live claim ${run.leaseId} is held by ${claim.runner} — ${what} on ${run.runner} is another machine's`;
    return null;
  }

  /**
   * THE ONE RECOVERY GRANT (final authority closure), shared by the
   * recovered-draft admission and the fallback admission's `recoveredFrom`:
   * the interrupted attempt whose draft a fresh run inherits is THIS
   * task's own builder or repair turn, left in this very worktree on this
   * branch, either ended as `failed` for `interrupted` (or `no-handoff`) or still open under
   * a lease nobody holds any more. A planner, scout, or reviewer; a
   * parked, built, or otherwise failed run; a foreign workspace; or an
   * attempt still being built under a live claim is no grant — the words
   * say which, and the caller opens nothing.
   */
  private recoveryGrantProblem(parent: Run, run: { taskRef: number; branch: string; worktree: string }, now: Date): string | null {
    if (parent.taskRef !== run.taskRef) return `run #${parent.id} belongs to task_ref ${parent.taskRef} — a builder run continues its own task's run only`;
    if (parent.role !== "builder" && parent.role !== "repair") return `run #${parent.id} is a ${parent.role} run — a recovered draft is a builder's or its repair turn's`;
    if (parent.worktree !== run.worktree || parent.branch !== run.branch) return `run #${parent.id} left its draft in ${parent.worktree ?? "no worktree"} on ${parent.branch ?? "no branch"}, not ${run.worktree} on ${run.branch}`;
    // An attempt that stopped before its handoff (run 2085) left its work in
    // place for exactly this: the retry inherits it, like an interrupted one's.
    const interrupted = parent.outcome === null || (parent.outcome === "failed" && (parent.reason === "interrupted" || parent.reason === "no-handoff"));
    if (!interrupted) return `run #${parent.id} ended as ${parent.outcome}${parent.reason === null ? "" : ` (${parent.reason})`} — only an interrupted attempt's draft is recovered`;
    if (parent.outcome === null && this.liveClaimByLease(parent.leaseId, now) !== null) return `run #${parent.id} is still being built under lease ${parent.leaseId} — nothing recovers a live attempt's draft`;
    // THE RESUME GRANT (v52): an operator-stopped attempt's draft is
    // inherited only after that exact attempt was resumed — the stop's own
    // hold keeps the queue away, and this keeps every other road away too.
    const stop = this.stopOf(parent.id);
    if (stop !== null && stop.resumedAt === null) return `run #${parent.id} was stopped by ${stop.requestedBy} and has not been resumed — resume that exact attempt before anything inherits its draft`;
    return null;
  }

  /**
   * Whether `holder` is the LIVE tail of its task's open fallback cycle
   * under the approved chain — the words when it is not (v48 integrity).
   * Re-derived from durable state only: the task's one live cycle is the
   * holder's cycle, open, its cursor at the holder's index, the holder as
   * its tail, its digest the approved chain's, and the approved entry at
   * that index carrying exactly the holder's digest and auth mode.
   */
  private liveTailProblem(taskRef: number, taskId: string, holder: Run): string | null {
    if (holder.chainCycle == null || holder.chainIndex == null || holder.entryDigest == null) return `run #${holder.id} carries no chain binding`;
    const cycle = this.fallbackCycleFor(taskRef);
    if (cycle === null || cycle.id !== holder.chainCycle) return `run #${holder.id}'s cycle is not this task's live fallback cycle`;
    if (cycle.state !== "open") return `run #${holder.id}'s cycle is ${cycle.state}, not open`;
    if (cycle.cursor !== holder.chainIndex || cycle.tailRun !== holder.id) return `run #${holder.id} is not the live tail of its fallback cycle (the cycle is at entry ${cycle.cursor}, tail ${cycle.tailRun ?? "none"})`;
    const chain = this.approvedChainOf(taskId);
    if (chain === null) return "the chain approval no longer stands";
    if (cycle.chainDigest !== chainDigestOf(chain)) return `the live cycle was opened under chain ${cycle.chainDigest}, but the approved chain is ${chainDigestOf(chain)}`;
    const entry = chain[holder.chainIndex];
    if (entry === undefined || entryDigestOf(entry) !== holder.entryDigest || entry.authMode !== holder.authMode) {
      return `run #${holder.id} is bound to chain entry ${holder.chainIndex} under a digest or auth mode the approved chain does not carry there`;
    }
    return null;
  }

  /**
   * THE WORKING PLAN AUTHORITY (final authority closure): the route a
   * planner runs under before any approval, believed only as the ONE strict
   * stored-scope projection proves it — exact raw terms (a proposed-via
   * marker this code never writes is a terms problem), a resolved profile,
   * a whole fallback chain (an empty or malformed one is no chain), a
   * readable route whose build and repair legs are the profile's exact
   * pairs and whose signed risk and quality are the row's, the digest
   * re-derived from those very values, the operator's live auth mode read
   * strictly and agreeing with a chain's pinned base mode, and no leg
   * stating a problem. The claim, the admission, and the invocation all
   * ask this same question; one disagreement is the words, and nothing
   * opens or spawns on it. A sealed route is not this road's business —
   * the caller reads the seal first.
   */
  workingPlanRouteOf(taskId: string): { ok: true; route: PhaseRoute } | { ok: false; problem: string } {
    const scope = this.getScope(taskId);
    if (scope === null) return { ok: false, problem: "the task has no scope — a planner on it presents the bare word legacy" };
    const authority = scopeAuthorityOf(scope, { authMode: provider => readAuthModeStrict(provider) });
    if (!authority.ok) return { ok: false, problem: `the task's filed scope holds no plan authority (${authority.problem}) — re-file the scope` };
    const problems = routeProblems(authority.route);
    if (problems.length > 0) return { ok: false, problem: `the task's filed route states a problem (${problems.join("; ")}) — re-file the scope under a configuration that resolves every role` };
    return { ok: true, route: authority.route };
  }

  /**
   * THE SPAWN-TIME ROUTE PROOF (final authority closure): the provenance a
   * run was admitted under, re-proved against the authority the task holds
   * RIGHT NOW, immediately before a provider process exists — the same
   * proof the admission ran, over the same durable state. A planner whose
   * scope was rewritten, corrupted, or unresolved between its claim and
   * this instant spawns nothing; the words say why.
   */
  proveRouteForSpawn(runId: number, now: Date): { ok: true } | { ok: false; problem: string } {
    const run = this.getRun(runId);
    if (run === null || run.outcome !== null) return { ok: false, problem: `run #${runId} is not an open attempt` };
    const stamped = this.runRoute(runId);
    if (stamped === null) return { ok: false, problem: `run #${runId} carries no route provenance — nothing spends unstamped` };
    const { stampedAt: _stampedAt, ...leg } = stamped;
    const parent = run.parentRun === null ? null : this.getRun(run.parentRun);
    const proofLane = run.contestant ?? (run.role === "repair" && parent !== null ? parent.contestant : null);
    const bound = run.chainIndex != null && run.entryDigest != null ? { index: run.chainIndex, entryDigest: run.entryDigest } : null;
    const problem = this.routeAdmissionProblem({ taskRef: run.taskRef, role: run.role, provider: run.provider, model: run.model, contestant: proofLane, chain: bound }, leg, now);
    return problem === null ? { ok: true } : { ok: false, problem };
  }

  /**
   * The exact route authority a task holds for one run, in the caller's
   * hands (v48 authority repair): the sealed route's leg for the run's phase when the
   * approval stands; the working proposed route's plan leg for a planner
   * before any approval; for a run bound to a NON-primary chain entry, that
   * entry's `fallback` provenance for its phase. The store never applies
   * this on a caller's behalf — `startRun` requires the caller to PRESENT
   * it and proves the presented stamp against the same durable state, so
   * a caller that holds no authority opens nothing. Null when the task is
   * not filed under agent routing (a pre-routing row, a task with no
   * scope — those roads stamp when they spend); the words when the task
   * is routed and nothing could govern the run.
   */
  routeAuthorityFor(
    taskRef: number,
    role: Run["role"] | "scout",
    bound: { index: number; entryDigest: string } | null = null,
    /** What the run would spend as, for the roads no profile governs: the
     * bare word `legacy` on a task with no scope, and the plan/review
     * pair of a pre-routing row (its profile names only build and
     * repair). Ignored wherever an authority names the pair itself. */
    spend?: { provider: string; model: string | null },
  ): { ok: true; stamp: RouteStamp } | { ok: false; problem: string } | null {
    const ref = this.refForId(taskRef);
    if (ref === null) return null;
    const scope = this.getScope(ref.externalId);
    const phase = phaseOfRole(role);
    if (scope === null) {
      // No scope at all: the bare word, as what the caller would spend —
      // nothing builds on such a row, and the row says so honestly.
      return spend === undefined ? null : { ok: true, stamp: { routeDigest: "legacy", phase, provider: spend.provider, model: spend.model, chosen: "legacy" } };
    }
    if (scope.routeEra == null) {
      // A row proven to predate routing (v48 integrity): its SEALED
      // profile alone governs, named exactly — the bound chain entry's
      // profile for a chain-bound run, else the approved snapshot while
      // the approval stands. Nothing governs an unapproved pre-routing
      // row; re-filing routes it.
      const approved = scope.termsProblem == null && scope.approvedAt !== null && scope.approvedDigest !== null && scope.approvedDigest === scope.digest;
      const chain = this.approvedChainOf(ref.externalId);
      const boundEntry = bound !== null && chain !== null ? chain[bound.index] : undefined;
      if (bound !== null && (boundEntry === undefined || entryDigestOf(boundEntry) !== bound.entryDigest)) {
        return { ok: false, problem: `the run is bound to chain entry ${bound.index}, which the approved chain does not carry under that digest` };
      }
      // A NON-primary entry of a pre-routing chain has no sealed route to
      // spend under and no chain-only digest to borrow (raw authority
      // repair): nothing governs it until the scope is re-filed and
      // approved under a route.
      if (bound !== null && bound.index > 0) {
        return { ok: false, problem: "this pre-routing chain approval seals no agent route — nothing spends as a fallback under a chain-only digest; re-file the scope and approve it again" };
      }
      const governing = boundEntry !== undefined ? boundEntry.profile : approved ? (scope.approvedProfile ?? null) : null;
      if (governing === null) return { ok: false, problem: "no sealed profile governs this pre-routing row — nothing spends as legacy on it; re-file the scope to route it" };
      const pair =
        phase === "build"
          ? { provider: governing.provider, model: governing.model }
          : phase === "repair"
            ? { provider: governing.provider, model: governing.repairModel === "inherit" ? governing.model : governing.repairModel }
            : { provider: spend?.provider ?? governing.provider, model: spend === undefined ? governing.model : spend.model };
      return { ok: true, stamp: { routeDigest: `profile:${profileDigestOf(governing)}`, phase, ...pair, chosen: "legacy" } };
    }
    const sealed = this.sealedRouteOf(ref.externalId);
    if (bound !== null && bound.index > 0 && (phase === "build" || phase === "repair")) {
      const chain = this.approvedChainOf(ref.externalId);
      const entry = chain === null ? undefined : chain[bound.index];
      if (chain === null || entry === undefined) return { ok: false, problem: "the run is bound to a fallback chain entry the task's approved chain does not have" };
      if (entryDigestOf(entry) !== bound.entryDigest) return { ok: false, problem: `the run is bound to chain entry ${bound.index} under digest ${bound.entryDigest}, but the approved entry there is ${entryDigestOf(entry)}` };
      const model = phase === "repair" ? (entry.profile.repairModel === "inherit" ? entry.profile.model : entry.profile.repairModel) : entry.profile.model;
      if (!sealed.ok) return { ok: false, problem: `the chain approval's sealed agent route does not stand (${sealed.detail}) — nothing spends as a fallback under a chain-only digest` };
      return { ok: true, stamp: { routeDigest: routeDigestOf(sealed.route), phase, provider: entry.profile.provider, model, chosen: "fallback" } };
    }
    if (sealed.ok) {
      const leg = legOf(sealed.route, phase);
      return { ok: true, stamp: { routeDigest: routeDigestOf(sealed.route), phase, provider: leg.provider, model: leg.model, chosen: leg.chosen } };
    }
    if (phase === "plan") {
      // The working route a planner may present is the strict projection's
      // (final authority closure) — an invalid or unresolved scope holds
      // no plan authority, in words.
      const working = this.workingPlanRouteOf(ref.externalId);
      if (!working.ok) return { ok: false, problem: working.problem };
      const leg = legOf(working.route, "plan");
      return { ok: true, stamp: { routeDigest: routeDigestOf(working.route), phase, provider: leg.provider, model: leg.model, chosen: leg.chosen } };
    }
    return { ok: false, problem: `this task is filed under agent routing and nothing spends as its ${phase} leg without a sealed route — ${sealed.detail}` };
  }

  /**
   * Facts learned after the row was opened: the base revision is read just
   * before the agent spends, and the session id only exists once the agent's
   * envelope comes back. COALESCE, never overwrite — the first stamp is the
   * true one.
   */
  stampRun(
    id: number,
    facts: {
      baseRevision?: string;
      sessionId?: string;
      /** v24 dispatch stamps: what this invocation was PROVED against. */
      scopeDigest?: string;
      profileDigest?: string;
      providerVersion?: string;
    },
  ): void {
    // Lineage is NOT a late fact (raw authority repair): a parent is proved
    // and written by the admission alone, so there is no parent stamp here.
    this.db
      .prepare(
        `UPDATE run SET base_revision = COALESCE(base_revision, ?),
                        session_id = COALESCE(session_id, ?),
                        scope_digest = COALESCE(scope_digest, ?),
                        profile_digest = COALESCE(profile_digest, ?),
                        provider_version = COALESCE(provider_version, ?)
          WHERE id = ?`,
      )
      .run(
        facts.baseRevision ?? null,
        facts.sessionId ?? null,
        facts.scopeDigest ?? null,
        facts.profileDigest ?? null,
        facts.providerVersion ?? null,
        id,
      );
  }

  /**
   * THE ONE WARM-RESUME BINDING (raw authority repair): an OPEN builder
   * attempt takes a parked run's session forward, and the record says so
   * — parent and session identity in one transaction, each fact re-proved
   * from durable state here rather than stamped as a late COALESCE: the
   * attempt is open, a builder, and unparented; the park is this task's
   * own parked builder run carrying exactly that session; and no earlier
   * attempt has already carried it (one warm try per park). Anything else
   * binds nothing and says why; the caller goes cold.
   */
  bindWarmResume(runId: number, parkedRunId: number, sessionId: string): { ok: true } | { ok: false; problem: string } {
    return this.transact(() => {
      const attempt = this.getRun(runId);
      const parked = this.getRun(parkedRunId);
      if (attempt === null || attempt.outcome !== null || attempt.role !== "builder") return { ok: false as const, problem: `run #${runId} is not an open builder attempt` };
      if (attempt.parentRun !== null) return { ok: false as const, problem: `run #${runId} already continues run #${attempt.parentRun}` };
      if (parked === null || parked.taskRef !== attempt.taskRef || parked.role !== "builder" || parked.outcome !== "parked") return { ok: false as const, problem: `run #${parkedRunId} is not this task's parked builder attempt` };
      if (parked.sessionId === null || parked.sessionId !== sessionId) return { ok: false as const, problem: `run #${parkedRunId} does not carry session ${sessionId}` };
      const tried = this.db.prepare("SELECT 1 AS hit FROM run WHERE parent_run = ? AND role = 'builder' AND id <> ? LIMIT 1").get(parkedRunId, runId);
      if (tried !== undefined) return { ok: false as const, problem: `run #${parkedRunId} was already resumed once — the second attempt goes cold` };
      const bound = this.db
        .prepare("UPDATE run SET parent_run = ?, session_id = COALESCE(session_id, ?) WHERE id = ? AND parent_run IS NULL AND outcome IS NULL")
        .run(parkedRunId, sessionId, runId);
      if (Number(bound.changes) !== 1) return { ok: false as const, problem: `run #${runId} moved under the binding` };
      return { ok: true as const };
    });
  }

  /**
   * The warm-resume candidate (M6.9): the latest PARKED builder run whose
   * session could carry this task's next attempt — same provider, same
   * branch, session captured — with the disqualifiers the Codex slice
   * names checked here, in one place: a newer accepted build supersedes
   * the park, and `tried` says whether any attempt already resumed it
   * (one warm try per park; after that the successor goes cold with the
   * answered decisions rather than failing on a dead session forever).
   */
  resumeCandidate(
    taskRef: number,
    provider: string,
    branch: string,
  ): { run: Run; tried: boolean } | null {
    const row = this.db
      .prepare(
        `SELECT * FROM run
          WHERE task_ref = ? AND outcome = 'parked' AND role = 'builder'
            AND session_id IS NOT NULL AND provider = ? AND branch = ?
          ORDER BY id DESC LIMIT 1`,
      )
      .get(taskRef, provider, branch);
    if (row === undefined) return null;
    const parked = readRun(row);
    const superseded = this.db
      .prepare(
        `SELECT 1 AS hit FROM run
          WHERE task_ref = ? AND id > ? AND role = 'builder' AND outcome IN ('built','no-change') LIMIT 1`,
      )
      .get(taskRef, parked.id);
    if (superseded !== undefined) return null;
    const child = this.db
      .prepare("SELECT 1 AS hit FROM run WHERE parent_run = ? AND role = 'builder' LIMIT 1")
      .get(parked.id);
    return { run: parked, tried: child !== undefined };
  }

  /**
   * The pinned base for a task's branch (run 1461's fix): the EARLIEST
   * builder run's base_revision for this task_ref+branch, chronological by
   * id. A branch is reused across attempts — a strike retry, a warm-cold
   * resume, an operator re-dispatch after a short verdict — and every
   * attempt after the first reads base_revision as wherever the PRIOR
   * attempt's HEAD landed, not where the branch started. That is correct
   * for the HEAD-immutability fence (each attempt owns only its own
   * commits) but wrong for evidence: a whole-task rubric is judged once,
   * against everything the branch has ever changed, so the terminal diff
   * this attempt seals must run from the branch's true origin, not from
   * its own incremental slice. A first attempt has no earlier row, so this
   * returns null and the caller falls back to its own base_revision —
   * legacy first-attempt behavior, unchanged byte-for-byte.
   */
  firstBuilderBase(taskRef: number, branch: string): string | null {
    const row = this.db
      .prepare(
        `SELECT base_revision FROM run
          WHERE task_ref = ? AND branch = ? AND role = 'builder' AND base_revision IS NOT NULL
          ORDER BY id ASC LIMIT 1`,
      )
      .get(taskRef, branch) as { base_revision: string } | undefined;
    return row === undefined ? null : row.base_revision;
  }

  finishRun(
    id: number,
    result: {
      outcome: "built" | "failed" | "refused" | "parked" | "no-change" | "interrupted";
      reason?: string;
      committed?: boolean;
      now: Date;
      /** v52: how this ending settles a pending operator stop on the run,
       * when one stands. The fenced interruption seal and the held fence
       * name their own word; every other road settles it as `finished` —
       * the attempt reached this ending first, and its outcome stands. */
      stopSettlement?: StopSettlement;
    },
  ): void {
    this.transact(() => {
    // Read before the write (Telegram task updates): only the OPEN → closed
    // transition is an ending. A later call that only restates the reason
    // (a report's "task external-closed" suffix, a re-dispose) is the same
    // ending and says nothing again.
    const prior = this.db
      .prepare("SELECT task_ref, role, parent_run, contestant, review_attempt, outcome FROM run WHERE id = ?")
      .get(id);
    this.settleRunSpend(id, result.now);
    this.db
      .prepare("UPDATE run SET outcome = ?, reason = ?, committed = ?, finished_at = ? WHERE id = ?")
      .run(
        result.outcome,
        result.reason ?? null,
        result.committed === undefined ? null : result.committed ? 1 : 0,
        result.now.toISOString(),
        id,
      );
    // An outcome alone does not prove subprocess exit. Settlement checks
    // retained witnesses and every owned run; recovery revisits a pending
    // stop after an orphan or held supervisor finishes shutdown.
    this.recordRunProcessExits(id, result.now);
    this.settleRunStop(id, result.stopSettlement ?? "finished", result.now);
    // The first Ready result is an installation fact the moment it lands,
    // not only when something later looks for it. A run that changed
    // nothing is not a first result.
    if (result.outcome === "built") this.firstSuccessAt(result.now);
    // The park rate is *measured* — parked over concluded builder attempts —
    // and maintained where attempts conclude, because the attention budget's
    // gate reads it inside a claim transaction and must never trust a number
    // something else remembered to update.
    if (result.outcome === "parked" || result.outcome === "built" || result.outcome === "no-change") {
      // Continuation runs are EXCLUDED (Phase 2E, v4 Q7/v5 P5): a watched
      // follow-up neither counts toward nor triggers the parent task's
      // measured park rate — "never mutates the parent task" includes its
      // derived statistics.
      this.db
        .prepare(
          `UPDATE task_ref SET park_rate = COALESCE((
             SELECT CAST(SUM(CASE WHEN outcome = 'parked' THEN 1 ELSE 0 END) AS REAL) / COUNT(*)
               FROM run
              WHERE run.task_ref = task_ref.id
                AND run.role = 'builder'
                AND run.outcome IN ('built', 'parked', 'no-change')
                AND NOT EXISTS (SELECT 1 FROM attended_authorization aa
                                 WHERE aa.id = run.attended_authorization AND aa.parent_run IS NOT NULL)
           ), 0)
           WHERE id = (SELECT task_ref FROM run
                        WHERE run.id = ? AND run.role = 'builder'
                          AND NOT EXISTS (SELECT 1 FROM attended_authorization aa
                                           WHERE aa.id = run.attended_authorization AND aa.parent_run IS NOT NULL))`,
        )
        .run(id);
    }
    if (prior !== undefined && prior["outcome"] === null) this.noteRunEnding(id, prior, result, result.now);
    });
  }

  /** Every run still open UNDER A LIVE LEASE, oldest first, with its task's
   * id and title — what `peek` watches. An orphaned null-outcome run (a
   * crashed worker's) is the reconciler's, not a pane. */
  liveRuns(now: Date): (Run & { taskId: string; title: string; repo: string | null })[] {
    return this.db
      .prepare(
        `SELECT run.*, task_ref.external_id AS task_id, task_ref.repo AS task_repo, task.title AS task_title
           FROM run
           JOIN task_ref ON task_ref.id = run.task_ref
           LEFT JOIN task ON task_ref.backend = ? AND task.id = task_ref.external_id
          WHERE run.outcome IS NULL
            AND EXISTS (SELECT 1 FROM claim WHERE claim.lease_id = run.lease_id AND claim.released_at IS NULL AND claim.expires_at > ?)
          ORDER BY run.id`,
      )
      .all(BUILT_IN, now.toISOString())
      .map(row => ({
        ...readRun(row as Record<string, unknown>),
        taskId: String(row["task_id"]),
        title: row["task_title"] === null || row["task_title"] === undefined ? String(row["task_id"]) : String(row["task_title"]),
        repo: row["task_repo"] === null || row["task_repo"] === undefined ? null : String(row["task_repo"]),
      }));
  }

  getRun(id: number): Run | null {
    const row = this.db.prepare("SELECT * FROM run WHERE id = ?").get(id);
    return row === undefined ? null : readRun(row);
  }

  /**
   * The instant before the provider process spawns, stamped by the gateway
   * and nothing else. First stamp wins: a run either paid once or it did
   * not, and "provider spawns == runs carrying this stamp" is the
   * zero-token invariant's testable half.
   */
  stampProviderStart(id: number, now: Date, providerVersion?: string): void {
    // The version is the GATEWAY'S authoritative fact (Phase 3 C5): it
    // OVERWRITES any caller-side best-effort stamp, in the same pre-spawn
    // statement as the start stamp so a daemon death loses neither.
    if (providerVersion !== undefined) {
      this.db
        .prepare(
          "UPDATE run SET provider_started_at = COALESCE(provider_started_at, ?), provider_version = ? WHERE id = ?",
        )
        .run(now.toISOString(), providerVersion, id);
      return;
    }
    this.db
      .prepare("UPDATE run SET provider_started_at = COALESCE(provider_started_at, ?) WHERE id = ?")
      .run(now.toISOString(), id);
  }

  /**
   * The gateway's honest disposal record for the fallback taxonomy (E2):
   * how this attempt authenticated, and the class its terminal fell into.
   * Recorded where the evidence still exists — the gateway holds the
   * structural terminal, the authoritative version, and the auth mode — and
   * NEVER re-derived in disposal, by which time the structural signal is
   * gone. Purely observational: the class is stamped on EVERY finished
   * attempt (usually 'unknown'/'not-exhausted', since the recognizers ship
   * empty), and it authorizes NOTHING on its own — the dispatch's C8 gate
   * re-proves hasRecognizer before any advance ever reads it.
   */
  stampTerminalClass(id: number, authMode: "subscription" | "api-key", terminalClass: TerminalClass): void {
    // FIRST-WRITE only (Codex E2/E3 review, finding 8): the gateway stamps
    // the disposal class exactly once, before disposition; nothing may
    // overwrite it into a class/auth pairing the recognizer never produced.
    // auth_mode is NEVER overwritten if already set — a fallback run's
    // admitted pin is authority (finding 5), so COALESCE keeps it and only a
    // never-stamped (base) run takes the gateway's mode.
    this.db
      .prepare("UPDATE run SET auth_mode = COALESCE(auth_mode, ?), terminal_class = ? WHERE id = ? AND terminal_class IS NULL")
      .run(authMode, terminalClass, id);
  }

  /** The race-refusal stamp (Phase 3 C5): the version that was REFUSED,
   * recorded without provider_started_at — no provider process started. */
  stampProviderVersion(id: number, providerVersion: string): void {
    this.db.prepare("UPDATE run SET provider_version = ? WHERE id = ?").run(providerVersion, id);
  }

  /** What the provider said it cost. NULL columns stay NULL — unmeasured, and said so. */
  recordUsage(
    id: number,
    usage: { tokensIn?: number; tokensOut?: number; costUsd?: number; usageJson?: string },
  ): void {
    this.db
      .prepare(
        `UPDATE run SET tokens_in = COALESCE(?, tokens_in),
                        tokens_out = COALESCE(?, tokens_out),
                        cost_usd = COALESCE(?, cost_usd),
                        usage_json = COALESCE(?, usage_json)
          WHERE id = ?`,
      )
      .run(
        usage.tokensIn ?? null,
        usage.tokensOut ?? null,
        usage.costUsd ?? null,
        usage.usageJson ?? null,
        id,
      );
    this.settleRunSpend(id, new Date());
  }

  /** v105: price a run as it stands (reported cost, or tokens at the catalogue price, or unpriced), frozen at the
   * price of the moment it's settled. Settled again whenever its usage changes. */
  settleRunSpend(id: number, now: Date): void {
    const row = this.db.prepare("SELECT run.provider, run.model, run.cost_usd, run.tokens_in, run.tokens_out, run.auth_mode, s.billing FROM run LEFT JOIN run_spend s ON s.run = run.id WHERE run.id = ?").get(id);
    if (row === undefined) return;
    // How the run is billed is fixed the first time it's settled (its chain entry's, or the provider's login or key).
    const billing: Billing = row["billing"] === "subscription" || row["billing"] === "api-key" ? row["billing"]
      : row["auth_mode"] === "subscription" || row["auth_mode"] === "api-key" ? row["auth_mode"] : billingOf(String(row["provider"]), this.db);
    const priced = priceWork(this.db, { provider: String(row["provider"]), model: row["model"] == null ? null : String(row["model"]), billing,
      costUsd: row["cost_usd"] == null ? null : Number(row["cost_usd"]), tokensIn: row["tokens_in"] == null ? null : Number(row["tokens_in"]), tokensOut: row["tokens_out"] == null ? null : Number(row["tokens_out"]) });
    this.db.prepare(`INSERT INTO run_spend (run, microusd, source, billing, price_model, input_usd, output_usd, priced_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(run) DO UPDATE SET microusd = excluded.microusd, source = excluded.source, price_model = excluded.price_model, input_usd = excluded.input_usd, output_usd = excluded.output_usd, priced_at = excluded.priced_at`)
      .run(id, priced.microusd, priced.source, billing, priced.price?.model ?? null, priced.price?.inputUsd ?? null, priced.price?.outputUsd ?? null, now.toISOString());    this.spendCache = null;
  }

  // ---- Backups (sprint 8) ---------------------------------------------------

  backupSettings(): BackupSettings {
    const row = this.db.prepare("SELECT * FROM backup_settings WHERE id = 1").get();
    if (row === undefined) return { ...DEFAULT_BACKUP_SETTINGS };
    return { enabled: Number(row["enabled"]) === 1, everyHours: Number(row["every_hours"]), keep: Number(row["keep"]), folder: row["folder"] == null ? null : String(row["folder"]) };
  }

  /** Change the backup settings; the ledger keeps before → after. */
  setBackupSettings(next: BackupSettings, by: string, now: Date): BackupSettings {
    return this.transact(() => {
      const before = this.backupSettings();
      this.db.prepare(`INSERT INTO backup_settings (id, enabled, every_hours, keep, folder) VALUES (1, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET enabled = excluded.enabled, every_hours = excluded.every_hours, keep = excluded.keep, folder = excluded.folder`)
        .run(next.enabled ? 1 : 0, next.everyHours, next.keep, next.folder);
      this.recordPolicy(by, null, "backup settings changed", backupSettingsWords(before), backupSettingsWords(next), now);
      return this.backupSettings();
    });
  }

  startBackupRun(trigger: "scheduled" | "manual", now: Date): number {
    return Number(this.db.prepare("INSERT INTO backup_run (trigger, started_at) VALUES (?, ?)").run(trigger, now.toISOString()).lastInsertRowid);
  }

  finishBackupRun(id: number, outcome: { ok: true; file: string; bytes: number; schemaVersion: number | null; removed: number } | { ok: false; error: string }, now: Date): void {
    if (outcome.ok) {
      this.db.prepare("UPDATE backup_run SET finished_at = ?, ok = 1, file = ?, bytes = ?, schema_version = ?, removed = ? WHERE id = ?")
        .run(now.toISOString(), outcome.file, outcome.bytes, outcome.schemaVersion, outcome.removed, id);
    } else {
      this.db.prepare("UPDATE backup_run SET finished_at = ?, ok = 0, error = ? WHERE id = ?").run(now.toISOString(), outcome.error.replace(/[\u0000-\u001f\u007f]+/g, " ").slice(0, 300), id);
    }
  }

  /** Backups, newest first. */
  backupRuns(limit = 20): BackupRun[] {
    return this.db.prepare("SELECT * FROM backup_run ORDER BY id DESC LIMIT ?").all(limit).map(row => ({
      id: Number(row["id"]), trigger: String(row["trigger"]) as BackupRun["trigger"], startedAt: String(row["started_at"]), finishedAt: row["finished_at"] == null ? null : String(row["finished_at"]),
      ok: row["ok"] == null ? null : Number(row["ok"]) === 1, file: row["file"] == null ? null : String(row["file"]), bytes: row["bytes"] == null ? null : Number(row["bytes"]),
      schemaVersion: row["schema_version"] == null ? null : Number(row["schema_version"]), removed: Number(row["removed"]), error: row["error"] == null ? null : String(row["error"]),
    }));
  }

  /** Take (or keep) the backup loop's lease until `until`; false while another process holds it. */
  holdBackupLease(holder: string, now: Date, until: Date): boolean {
    return this.transact(() => {
      this.db.prepare("INSERT OR IGNORE INTO backup_lease (id) VALUES (1)").run();
      return Number(this.db.prepare("UPDATE backup_lease SET holder = ?, held_until = ? WHERE id = 1 AND (holder IS NULL OR holder = ? OR held_until IS NULL OR held_until < ?)")
        .run(holder, until.toISOString(), holder, now.toISOString()).changes) === 1;
    });
  }

  releaseBackupLease(holder: string): void {
    this.db.prepare("UPDATE backup_lease SET holder = NULL, held_until = NULL WHERE id = 1 AND holder = ?").run(holder);
  }

  /** Who holds the backup loop's lease, if it hasn't run out: a console that's running. */
  backupLease(now: Date): { holder: string; heldUntil: string } | null {
    const row = this.db.prepare("SELECT holder, held_until FROM backup_lease WHERE id = 1 AND holder IS NOT NULL AND held_until >= ?").get(now.toISOString());
    return row === undefined ? null : { holder: String(row["holder"]), heldUntil: String(row["held_until"]) };
  }

  // ---- Organisation policy (sprint 8) -----------------------------------------

  /** The organisation policy in force: allowed providers, models and tools, and the permission ceiling. */
  orgPolicy(): SavedPolicy {
    return readPolicy(this.db);
  }

  /** Save the organisation policy. The ledger keeps each rule that changed, before → after. */
  setOrgPolicy(policy: OrgPolicy, by: string, now: Date): SavedPolicy {
    return this.transact(() => {
      const before = policyParts(this.orgPolicy());
      const json = (list: readonly string[] | null) => list === null ? null : JSON.stringify(list);
      this.db.prepare(`INSERT INTO org_policy (id, providers_json, models_json, tools_json, ceiling, updated_by, updated_at) VALUES (1, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET providers_json = excluded.providers_json, models_json = excluded.models_json, tools_json = excluded.tools_json,
          ceiling = excluded.ceiling, updated_by = excluded.updated_by, updated_at = excluded.updated_at`)
        .run(json(policy.providers), json(policy.models), json(policy.tools), policy.ceiling, by, now.toISOString());
      const after = policyParts(policy);
      const words = { providers: "allowed providers", models: "allowed models", tools: "allowed tools", ceiling: "permission ceiling" } as const;
      for (const rule of ["providers", "models", "tools", "ceiling"] as const) this.recordPolicy(by, null, `organisation policy: ${words[rule]}`, before[rule], after[rule], now);
      return this.orgPolicy();
    });
  }

  /** The policy's changes, newest first, from the action ledger. */
  policyHistory(limit = 50): LedgerEntry[] {
    return this.db.prepare(`SELECT id, at, actor, action, detail FROM action_ledger WHERE source = 'policy' AND action LIKE 'organisation policy:%' ORDER BY id DESC LIMIT ?`)
      .all(Math.max(1, Math.min(500, limit))).map(row => ({
        id: Number(row["id"]), at: String(row["at"]), actor: String(row["actor"]), repo: null, taskId: null, runId: null,
        action: String(row["action"]), outcome: "changed", source: "policy" as LedgerEntry["source"], detail: row["detail"] == null ? null : String(row["detail"]),
      }));
  }

  /** Why the policy stops a task's approved terms (its profile, every fallback entry, every routed leg), or null. */
  scopePolicyRefusal(taskId: string): string | null {
    const policy = this.orgPolicy();
    const scope = this.getScope(taskId);
    if (scope === null) return null;
    const profiles = [scope.profile ?? null, ...(chainFromJson(scope.proposedChainJson ?? null) ?? []).map(entry => entry.profile)].filter((one): one is ExecutionProfile => one !== null);
    const ref = this.lookupRef(taskId);
    // A race's lanes are legs too: each names its provider and model in the terms signed with the scope.
    const lanes = ref === null ? [] : (this.activeTournamentTerms(ref.id)?.agents ?? []).map(agent => ({ provider: agent.provider, model: agent.model }));
    const legs = [...(routeFromJson(scope.proposedRouteJson ?? null)?.legs.map(leg => ({ provider: leg.provider, model: leg.model })) ?? []), ...lanes];
    return approvalRefusal(policy, profiles, legs);
  }

  /** Why the policy stops an agent on a provider and model now, or null (chats, teammates, flow steps). */
  agentPolicyRefusal(provider: string, model: string | null): string | null {
    return agentRefusal(this.orgPolicy(), provider, model);
  }

  /** Why the policy stops a planner, scout or native coding session (no profile to lower) on a provider and model, or null. */
  sessionPolicyRefusal(provider: string, model: string | null, what: string): string | null {
    const policy = this.orgPolicy();
    return agentRefusal(policy, provider, model) ?? sessionCeilingRefusal(policy, provider, what);
  }

  /** Why the policy stops an attended session's signed profile, or null (it is never lowered: see policy.attendedRefusal). */
  attendedPolicyRefusal(profile: ExecutionProfile): string | null {
    return attendedRefusal(this.orgPolicy(), profile);
  }

  /** The policy's word on a profile about to run: refused, or what runs (lowered under the ceiling, with words). */
  runPolicy(profile: ExecutionProfile): ReturnType<typeof underCeiling> {
    const policy = this.orgPolicy();
    const refused = agentRefusal(policy, profile.provider, profile.model);
    if (refused !== null) return { ok: false, message: refused };
    return underCeiling(policy, profile);
  }

  // ---- Budgets (v105) -------------------------------------------------------

  /** The budgets in force. */
  budgets(): Budget[] {
    return this.db.prepare("SELECT * FROM budget WHERE removed_at IS NULL ORDER BY scope_kind, scope_key").all().map(row => ({
      id: Number(row["id"]), scope: String(row["scope_kind"]) as BudgetScope, key: String(row["scope_key"]), limitMicrousd: Number(row["limit_microusd"]),
      hardStop: Number(row["hard_stop"]) === 1, updatedBy: String(row["updated_by"]), updatedAt: String(row["updated_at"]),
    }));
  }

  /** Set a monthly budget (replacing the one for that scope); the ledger keeps before → after. */
  setBudget(budget: { scope: BudgetScope; key: string; limitMicrousd: number; hardStop: boolean }, by: string, now: Date): Budget {
    this.spendCache = null;
    return this.transact(() => {
      const key = budget.scope === "installation" ? "*" : budget.key;
      const before = this.budgets().find(one => one.scope === budget.scope && one.key === key) ?? null;
      const stamp = now.toISOString();
      if (before === null) {
        this.db.prepare("INSERT INTO budget (scope_kind, scope_key, limit_microusd, hard_stop, created_by, created_at, updated_by, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
          .run(budget.scope, key, budget.limitMicrousd, budget.hardStop ? 1 : 0, by, stamp, by, stamp);
      } else {
        this.db.prepare("UPDATE budget SET limit_microusd = ?, hard_stop = ?, updated_by = ?, updated_at = ? WHERE id = ?").run(budget.limitMicrousd, budget.hardStop ? 1 : 0, by, stamp, before.id);
      }
      const words = (one: Pick<Budget, "limitMicrousd" | "hardStop"> | null) => one === null ? "none" : `${usd(one.limitMicrousd)} a month${one.hardStop ? ", stops API work" : ", alerts only"}`;
      this.recordPolicy(by, budget.scope === "project" ? key : null, `budget set: ${budgetName(budget.scope, key)}`, words(before), words(budget), now);
      return this.budgets().find(one => one.scope === budget.scope && one.key === key)!;
    });
  }

  removeBudget(id: number, by: string, now: Date): boolean {
    this.spendCache = null;
    return this.transact(() => {
      const before = this.budgets().find(one => one.id === id);
      if (before === undefined) return false;
      this.db.prepare("UPDATE budget SET removed_by = ?, removed_at = ? WHERE id = ?").run(by, now.toISOString(), id);
      this.recordPolicy(by, before.scope === "project" ? before.key : null, `budget removed: ${budgetName(before.scope, before.key)}`, usd(before.limitMicrousd), "none", now);
      return true;
    });
  }

  // ---- Retention (v105) -----------------------------------------------------

  /** How long each kind of data is kept; null is forever. A kind nobody chose keeps its default (evidence 28 days, the rest forever). */
  retentionPeriods(): RetentionPeriods {
    return { ...DEFAULT_PERIODS, ...this.retentionChosen() };
  }

  /** The periods someone chose: only kinds with a saved row. */
  retentionChosen(): Partial<RetentionPeriods> {
    const chosen: Partial<RetentionPeriods> = {};
    for (const row of this.db.prepare("SELECT kind, days FROM retention_setting").all()) {
      chosen[String(row["kind"]) as RetentionKind] = row["days"] === null ? null : Number(row["days"]);
    }
    return chosen;
  }

  /** Set how long one kind is kept (null: forever); the ledger keeps before → after. */
  setRetentionPeriod(kind: RetentionKind, days: number | null, by: string, now: Date): RetentionPeriods {
    return this.transact(() => {
      const before = this.retentionPeriods()[kind];
      this.db.prepare("INSERT INTO retention_setting (kind, days, updated_by, updated_at) VALUES (?, ?, ?, ?) ON CONFLICT(kind) DO UPDATE SET days = excluded.days, updated_by = excluded.updated_by, updated_at = excluded.updated_at")
        .run(kind, days, by, now.toISOString());
      this.recordPolicy(by, null, `retention changed: ${kind}`, periodWords(before), periodWords(days), now);
      return this.retentionPeriods();
    });
  }

  /** Settings → Storage: when a finished task's clean checkout is removed (the default until someone chooses). */
  checkoutCleanup(): CheckoutCleanup {
    const row = this.db.prepare("SELECT cleanup FROM checkout_cleanup_setting WHERE id = 1").get();
    return row === undefined ? DEFAULT_CLEANUP : String(row["cleanup"]) as CheckoutCleanup;
  }

  /** Choose when a finished task's clean checkout is removed; the ledger keeps before → after. */
  setCheckoutCleanup(cleanup: CheckoutCleanup, by: string, now: Date): CheckoutCleanup {
    return this.transact(() => {
      const before = this.checkoutCleanup();
      this.db.prepare("INSERT INTO checkout_cleanup_setting (id, cleanup, updated_by, updated_at) VALUES (1, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET cleanup = excluded.cleanup, updated_by = excluded.updated_by, updated_at = excluded.updated_at")
        .run(cleanup, by, now.toISOString());
      this.recordPolicy(by, null, "checkout cleanup changed", cleanupWords(before), cleanupWords(cleanup), now);
      return this.checkoutCleanup();
    });
  }

  /** v105: keep a provider's latest reading of its plan's usage windows (a window it no longer reports is dropped). */
  recordProviderLimits(reading: LimitReading, now: Date): void {
    this.transact(() => {
      if (reading.billing !== undefined) this.recordProviderBilling(reading.provider, reading.billing, now);
      if (reading.windows.length === 0) return;
      const names = reading.windows.map(one => one.window);
      if (reading.partial !== true) this.db.prepare(`DELETE FROM provider_limit WHERE provider = ? AND window NOT IN (${names.map(() => "?").join(", ")})`).run(reading.provider, ...names);
      const put = this.db.prepare(`INSERT INTO provider_limit (provider, window, used_percent, window_minutes, resets_at, reached, plan, observed_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(provider, window) DO UPDATE SET used_percent = excluded.used_percent, window_minutes = excluded.window_minutes, resets_at = excluded.resets_at,
          reached = excluded.reached, plan = COALESCE(excluded.plan, provider_limit.plan), observed_at = excluded.observed_at`);
      for (const one of reading.windows) put.run(reading.provider, one.window, one.usedPercent, one.windowMinutes, one.resetsAt, one.reached ? 1 : 0, reading.plan, now.toISOString());
    });
  }

  /** The latest reading of every provider's plan windows, shortest window first. */
  providerLimits(): (LimitWindow & { provider: string; plan: string | null; observedAt: string })[] {
    return this.db.prepare("SELECT * FROM provider_limit ORDER BY provider, COALESCE(window_minutes, 1e9), window").all().map(row => ({
      provider: String(row["provider"]), window: String(row["window"]), usedPercent: Number(row["used_percent"]),
      windowMinutes: row["window_minutes"] == null ? null : Number(row["window_minutes"]), resetsAt: row["resets_at"] == null ? null : String(row["resets_at"]),
      reached: Number(row["reached"]) === 1, plan: row["plan"] == null ? null : String(row["plan"]), observedAt: String(row["observed_at"]),
    }));
  }

  /** This month's spend, and each budget's state. */
  monthSpend(now: Date): { month: string; items: SpendItem[]; budgets: BudgetState[] } {
    const month = monthOf(now);
    const items = spendItems(this.db, month.from, month.to);
    return { month: month.name, items, budgets: budgetStates(this.budgets(), items) };
  }

  /** The month's spend as a gate reads it: kept for a few seconds (a run's settling clears it), so a chat turn or a
   * tick asking again doesn't re-read the month. */
  private spendCache: { month: string; at: number; value: { month: string; items: SpendItem[]; budgets: BudgetState[] } } | null = null;
  monthSpendCached(now: Date): { month: string; items: SpendItem[]; budgets: BudgetState[] } {
    const month = monthOf(now).name;
    const cached = this.spendCache;
    if (cached !== null && cached.month === month && Math.abs(Date.now() - cached.at) < 5_000) return cached.value;
    const value = this.monthSpend(now);
    this.spendCache = { month, at: Date.now(), value };
    return value;
  }

  /** A gate for this moment: given what a piece of new work would count toward (and, with `agents`, which providers
   * it runs on, billed how), the hard-stop budget that holds it, or none. Budgets are dollars: work that runs only on
   * plans passes; API work waits when a covering budget is used up, or when it can't be priced at all (never free).
   * Built once and asked many times; the month's spend behind it is cached for a few seconds. */
  budgetGate(now: Date): (work: { project: string | null; person: string | null; teammate: number | null; agents?: readonly BudgetAgent[] }) => BudgetHold {
    const none: BudgetHold = { over: null, why: null, unpricedProvider: null, remainingMicrousd: null };
    const hard = this.budgets().filter(one => one.hardStop);
    if (hard.length === 0) return () => none;
    const states = this.monthSpendCached(now).budgets.filter(one => one.hardStop);
    const priceable = new Map<string, boolean>();
    return work => {
      const keyed = work.agents?.filter(agent => agent.billing === "api-key");
      if (keyed !== undefined && keyed.length === 0) return none;
      const item: SpendItem = { project: work.project, person: work.person, teammate: work.teammate, kind: "run", at: "", microusd: 0, source: "reported", provider: "", model: null, tokensIn: null, tokensOut: null, taskId: null, runId: null, authMode: null };
      const mine = states.filter(budget => countsToward(item, budget));
      if (mine.length === 0) return none;
      const remaining = Math.min(...mine.map(budget => budget.limitMicrousd - budget.spentMicrousd));
      const over = mine.find(budget => budget.spentMicrousd >= budget.limitMicrousd) ?? null;
      if (over !== null) return { over, why: "used-up", unpricedProvider: null, remainingMicrousd: remaining };
      const blind = keyed?.find(agent => {
        if (!priceable.has(agent.provider)) priceable.set(agent.provider, canPrice(this.db, agent.provider));
        return !priceable.get(agent.provider);
      });
      if (blind !== undefined) return { over: mine[0]!, why: "unpriced", unpricedProvider: blind.provider, remainingMicrousd: remaining };
      return { ...none, remainingMicrousd: remaining };
    };
  }

  /** How each provider would bill new work now (see spend.billingOf). */
  agentsFor(providers: readonly string[]): BudgetAgent[] {
    return [...new Set(providers)].map(provider => ({ provider, billing: billingOf(provider, this.db) }));
  }

  /** v105: how a provider's CLI was seen billing (a Claude stream's key source, Codex's account mode). */
  recordProviderBilling(provider: string, billing: Billing, now: Date): void {
    const before = seenBillingOf(this.db, provider);
    this.db.prepare(`INSERT INTO provider_account (provider, billing, observed_at) VALUES (?, ?, ?)
      ON CONFLICT(provider) DO UPDATE SET billing = excluded.billing, observed_at = excluded.observed_at`).run(provider, billing, now.toISOString());
    if (before !== billing) this.spendCache = null;
  }

  /** How a run was billed: its evidence, or the mode it was admitted under (a pinned chain entry's); null when unknown. */
  runBilling(id: number): Billing | null {
    const row = this.db.prepare("SELECT s.billing, run.auth_mode FROM run LEFT JOIN run_spend s ON s.run = run.id WHERE run.id = ?").get(id);
    const one = row?.["billing"] ?? row?.["auth_mode"];
    return one === "subscription" || one === "api-key" ? one : null;
  }

  /** v105: how a run was really billed, from its own evidence, fixed before its usage is priced. */
  fixRunBilling(id: number, billing: Billing, now: Date): void {
    // The first evidence sets it; a later turn of the same run (a resumed session) can only make it a key.
    this.db.prepare(`INSERT INTO run_spend (run, microusd, source, billing, billing_fixed, priced_at) VALUES (?, NULL, 'unpriced', ?, 1, ?)
      ON CONFLICT(run) DO UPDATE SET billing = CASE WHEN run_spend.billing_fixed = 1 AND run_spend.billing = 'api-key' THEN 'api-key' ELSE excluded.billing END, billing_fixed = 1`)
      .run(id, billing, now.toISOString());
    this.settleRunSpend(id, now);
  }

  /** What a task's new work counts toward: its project, its filer (a person, or the person behind a coordinator), and
   * the teammate that filed it. A revision (an automatic repair included) counts as its source task's. */
  budgetSubject(taskRef: number): { project: string | null; person: string | null; teammate: number | null } {
    const filer = filersOf(this.db)(taskRef);
    return { project: filer.repo, person: (filer.kind === "person" || filer.kind === "coordinator") && filer.filedBy !== null ? filer.filedBy : null,
      teammate: teammateFilers(this.db)(filer.repo, filer.filedBy, filer.kind) };
  }

  /**
   * Stamp the machine's current phase on an OPEN run. A closed run's phase
   * is history and stays put; an unknown phase is a caller bug and throws.
   * Bounded writes by construction: the vocabulary has four values and the
   * state machine passes each boundary once.
   */
  setRunPhase(id: number, phase: RunPhase, now: Date = new Date()): void {
    if (!RUN_PHASES.includes(phase)) {
      throw new Error(`"${phase}" is not a phase this machine has — the vocabulary is closed`);
    }
    this.transact(() => {
      const prior = this.db.prepare("SELECT task_ref, phase, outcome FROM run WHERE id = ?").get(id);
      this.db.prepare("UPDATE run SET phase = ? WHERE id = ? AND outcome IS NULL").run(phase, id);
      // The phase fact (Telegram task updates): a boundary the OPEN run
      // actually crossed. A closed run's leftover phase is history and a
      // same-phase repeat is the same state — neither speaks.
      if (prior === undefined || prior["outcome"] !== null || prior["phase"] === phase) return;
      const taskRef = Number(prior["task_ref"]);
      const taskId = this.externalIdFor(taskRef);
      if (taskId === null) return;
      const words = LIFECYCLE_PHASE_WORDS[phase];
      this.noteLifecycle({ taskRef, run: id, kind: "run-phase", identity: `r${id}`, subject: `Attempt #${id}: ${words.subject}`, body: words.body, link: chatControlHref("task", taskId) }, now);
    });
  }

  /** The accepted head and the validated conclusion, once known. */
  recordOutcomeFacts(id: number, facts: { headRevision?: string; handoff?: string }): void {
    this.db
      .prepare(
        `UPDATE run SET head_revision = COALESCE(?, head_revision),
                        handoff = COALESCE(?, handoff)
          WHERE id = ?`,
      )
      .run(facts.headRevision ?? null, facts.handoff ?? null, id);
  }

  /** Save the small, machine-owned projection of a run's approved project
   * check. The sealed receipt remains the evidence; this is only the status
   * index and first write wins so a later read cannot rewrite history. The
   * check's saved progress on the same row is kept. */
  recordRunCheck(
    id: number,
    check: { status: "passed" | "failed" | "not-run"; exitCode: number | null; suites: readonly RunCheckSuite[] },
    at: Date = new Date(),
  ): void {
    if (!isCheckExitCode(check.exitCode)) {
      throw new Error("a check exit code must be a non-negative 32-bit integer");
    }
    if (check.suites.length > 8 || check.suites.some(one => one.name.trim() === "" || one.name.length > 80 ||
      !["passed", "failed", "not-run"].includes(one.status) || !isCheckExitCode(one.exitCode))) {
      throw new Error("the check suite summary is not bounded");
    }
    this.db.prepare(`INSERT INTO run_check (run, status, exit_code, suites_json, release, recorded_at)
      SELECT id, ?, ?, ?, CASE WHEN quality_mode = 'strict' THEN 1 ELSE 0 END, ? FROM run WHERE id = ?
      ON CONFLICT(run) DO UPDATE SET status = excluded.status, exit_code = excluded.exit_code,
        suites_json = excluded.suites_json, release = excluded.release, recorded_at = excluded.recorded_at
      WHERE run_check.status IS NULL`)
      .run(check.status, check.exitCode, JSON.stringify(check.suites), at.toISOString(), id);
  }

  /** A run's recorded check summary, or null for a run recorded before summaries existed. */
  runCheckFor(id: number): RunCheck | null {
    const row = this.db.prepare("SELECT status, exit_code, suites_json FROM run_check WHERE run = ? AND status IS NOT NULL").get(id);
    if (row === undefined) return null;
    return {
      status: String(row["status"]) as RunCheck["status"],
      exitCode: wholeNumber(row["exit_code"]),
      suites: checkSuitesOf(row["suites_json"]),
    };
  }

  /** Every attempt since a moment, task ids attached — the overnight, as data. */
  runsSince(since: string): (Run & { taskId: string })[] {
    return this.db
      .prepare(
        `SELECT run.*, task_ref.external_id AS task_id FROM run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE run.started_at >= ? ORDER BY run.id`,
      )
      .all(since)
      .map(row => ({ ...readRun(row), taskId: String(row["task_id"]) }));
  }

  /**
   * The scoped read family: every list the console shows can be filtered to
   * one project. NULL repo rows (unplaced work) are always included — they
   * belong to every view — and a NULL filter means "no filter". Bounding
   * happens in the SQL, never by slicing a global read afterwards.
   */
  runsSinceScoped(since: string, repo: string | null): (Run & { taskId: string })[] {
    return this.db
      .prepare(
        `SELECT run.*, task_ref.external_id AS task_id FROM run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE run.started_at >= ? AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
         ORDER BY run.id`,
      )
      .all(since, repo, repo)
      .map(row => ({ ...readRun(row), taskId: String(row["task_id"]) }));
  }

  /**
   * One bounded page of tasks for the list pane, newest first, with the
   * selected task injected even when it falls outside the page — a detail
   * view whose own row is missing from its list reads as a bug.
   */
  listTasksScoped(
    repo: string | null,
    state: TaskState | undefined,
    limit: number,
    selectedId: string | null,
  ): (Task & { repo: string | null })[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 500));
    const rows = this.db
      .prepare(
        `SELECT * FROM (
           SELECT task.*, task_ref.repo AS task_repo FROM task
           JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
           WHERE (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
             AND (? IS NULL OR task.state = ?)
           ORDER BY task.created_at DESC, task.id DESC LIMIT ?
         )
         UNION
         SELECT task.*, task_ref.repo AS task_repo FROM task
         JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
         WHERE task.id = ?
         ORDER BY created_at DESC, id DESC`,
      )
      .all(BUILT_IN, repo, repo, state ?? null, state ?? null, page, BUILT_IN, selectedId);
    return rows.map(row => ({
      id: String(row["id"]),
      title: String(row["title"]),
      state: String(row["state"]) as TaskState,
      createdAt: String(row["created_at"]),
      updatedAt: String(row["updated_at"]),
      priority: row["priority"] === null || row["priority"] === undefined ? 0 : Number(row["priority"]),
      repo: row["task_repo"] === null ? null : String(row["task_repo"]),
    }));
  }

  /**
   * The Work destination's one bounded page (workspace package 1 query):
   * the newest tasks the viewer may see, with the viewer's already-proved
   * admission bound BEFORE the ordering and the limit — never a wider
   * read post-filtered in the caller. `admitted` is the resolved
   * permitted repo set: `null` means unrestricted (every placed row),
   * `[]` means no placed project is permitted (no placed row at all).
   * `includeUnplaced` says whether NULL-repo rows belong to this viewer;
   * an account restricted to projects never sees them, so they must not
   * spend its page. Every predicate is a bound parameter; the limit is
   * clamped here, not trusted from the caller. Read-only; the legacy
   * `listTasksScoped` is untouched.
   */
  listWorkTasksAdmitted(
    admitted: readonly string[] | null,
    includeUnplaced: boolean,
    limit: number,
  ): (Task & { repo: string | null })[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 500));
    // SQLite accepts an empty IN list, so an empty admission binds as
    // "no placed row" without any special SQL shape.
    const rows = this.db
      .prepare(
        `SELECT task.*, task_ref.repo AS task_repo FROM task
         JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
         WHERE ((task_ref.repo IS NULL AND ? = 1)
             OR (task_ref.repo IS NOT NULL AND (? = 1 OR task_ref.repo IN (${(admitted ?? []).map(() => "?").join(",")}))))
         ORDER BY task.created_at DESC, task.id DESC LIMIT ?`,
      )
      .all(BUILT_IN, includeUnplaced ? 1 : 0, admitted === null ? 1 : 0, ...(admitted ?? []), page);
    return rows.map(row => ({
      id: String(row["id"]),
      title: String(row["title"]),
      state: String(row["state"]) as TaskState,
      createdAt: String(row["created_at"]),
      updatedAt: String(row["updated_at"]),
      priority: row["priority"] === null || row["priority"] === undefined ? 0 : Number(row["priority"]),
      repo: row["task_repo"] === null ? null : String(row["task_repo"]),
    }));
  }

  /** Newest first, because the question is almost always "what just happened". */
  runsFor(taskRef: number): Run[] {
    return this.db
      .prepare("SELECT * FROM run WHERE task_ref = ? ORDER BY id DESC")
      .all(taskRef)
      .map(readRun);
  }

  /**
   * One page of runs, newest first, strictly before the cursor — id order,
   * because ids are the one monotonic thing a page can key on without a row
   * ever repeating or vanishing between requests. `null` means "from the
   * top". The limit is clamped here, not trusted from the caller: a page is
   * bounded by construction or it is not a page.
   */
  listRunsBefore(
    cursor: number | null,
    limit: number,
    repo: string | null = null,
  ): (Run & { taskId: string })[] {
    if (cursor !== null && (!Number.isSafeInteger(cursor) || cursor <= 0)) return [];
    const page = Math.max(1, Math.min(Math.floor(limit), 200));
    return this.db
      .prepare(
        `SELECT run.*, task_ref.external_id AS task_id FROM run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE (? IS NULL OR run.id < ?)
           AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
         ORDER BY run.id DESC LIMIT ?`,
      )
      .all(cursor, cursor, repo, repo, page)
      .map(row => ({ ...readRun(row), taskId: String(row["task_id"]) }));
  }

  // ---- decisions -----------------------------------------------------------

  /**
   * Insert a decision. Callers hand this a payload `parseDecision` already
   * validated and run it inside the park's fenced transaction — this method
   * is the write, not the policy.
   */
  saveDecision(
    decision: {
      run: number;
      urgency: "blocking";
      recap: string;
      question: string;
      options: DecisionOption[];
      recommendation: string;
      assignee?: string;
      deadline?: string;
      /** Which racing agent asked (v14); absent = ordinary. */
      contestant?: number;
    },
    now: Date,
  ): number {
    const inserted = this.db
      .prepare(
        `INSERT INTO decision (run, urgency, recap, question, options, recommendation, assignee, deadline, contestant, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        decision.run,
        decision.urgency,
        decision.recap,
        decision.question,
        JSON.stringify(decision.options),
        decision.recommendation,
        decision.assignee ?? null,
        decision.deadline ?? null,
        decision.contestant ?? null,
        now.toISOString(),
      );
    return Number(inserted.lastInsertRowid);
  }

  getDecision(id: number): Decision | null {
    const row = this.db.prepare("SELECT * FROM decision WHERE id = ?").get(id);
    return row === undefined ? null : readDecision(row);
  }

  decisionForRun(run: number): Decision | null {
    const row = this.db.prepare("SELECT * FROM decision WHERE run = ?").get(run);
    return row === undefined ? null : readDecision(row);
  }

  /**
   * Decisions with their task attached, oldest first — the attention surface
   * reads in the order the questions arrived. "unanswered" is open + expired:
   * expiry makes a decision louder, never gone.
   */
  /** The newest planner run's plan document for a task, when one exists. */
  latestPlanArtifact(taskRef: number): Artifact | null {
    const row = this.db
      .prepare(
        `SELECT artifact.* FROM artifact
         JOIN run ON run.id = artifact.run
         WHERE run.task_ref = ? AND run.role = 'planner' AND artifact.kind = 'plan'
         ORDER BY artifact.id DESC LIMIT 1`,
      )
      .get(taskRef);
    return row === undefined ? null : readArtifact(row as Record<string, unknown>);
  }

  /** The newest plan-contract INGESTION record on one of this task's
   * planner runs (contract handoff, task 1): what the draft proposed
   * against the filed terms, and every change between them. The source
   * record of the same attempt is `plannerSourceArtifactFor(run)`. */
  latestPlanContractArtifact(taskRef: number): Artifact | null {
    const row = this.db
      .prepare(
        `SELECT artifact.* FROM artifact
         JOIN run ON run.id = artifact.run
         WHERE run.task_ref = ? AND run.role = 'planner' AND artifact.kind = 'plan-contract'
           AND artifact.key LIKE '%/plan-contract.json'
         ORDER BY artifact.id DESC LIMIT 1`,
      )
      .get(taskRef);
    return row === undefined ? null : readArtifact(row as Record<string, unknown>);
  }

  /** The recorded planner SOURCE of one planner run — the exact filed
   * request quoted into its brief. A correction child carries none of its
   * own: its parent's record is the one it inherited. */
  plannerSourceArtifactFor(runId: number): Artifact | null {
    const row = this.db
      .prepare(
        `SELECT * FROM artifact
         WHERE run = ? AND kind = 'plan-contract' AND key LIKE '%/planner-source.json'
         ORDER BY id ASC LIMIT 1`,
      )
      .get(runId);
    return row === undefined ? null : readArtifact(row as Record<string, unknown>);
  }

  // ---- adaptive execution plans (v44) --------------------------------------

  /** Append one immutable plan-revision row. The caller has already written
   * the replacement document as a `kind: 'plan'` artifact and, for a
   * builder-filed proposal, already classified its authority against the
   * run's own snapshot — this only records the ledger entry around that
   * work. `revision` is the caller's to assign (one past whatever
   * `latestPlanRevision` returned, read in the same transaction) so two
   * concurrent proposals can never collide silently on the UNIQUE index. */
  insertPlanRevision(
    revision: {
      taskRef: number;
      revision: number;
      artifact: number;
      parentHash: string | null;
      reason: string;
      evidenceLink: string | null;
      author: string;
      originRun: number | null;
      kind: PlanRevisionKind;
      authorityKind: "plan-only" | "authority-change";
      authorityDigest: string;
      changedFields: readonly string[];
      status: PlanRevisionStatus;
    },
    now: Date,
  ): number {
    const inserted = this.db
      .prepare(
        `INSERT INTO plan_revision
           (task_ref, revision, artifact, parent_hash, reason, evidence_link, author, origin_run,
            kind, authority_kind, authority_digest, changed_fields, status, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        revision.taskRef,
        revision.revision,
        revision.artifact,
        revision.parentHash,
        revision.reason,
        revision.evidenceLink,
        revision.author,
        revision.originRun,
        revision.kind,
        revision.authorityKind,
        revision.authorityDigest,
        JSON.stringify(revision.changedFields),
        revision.status,
        now.toISOString(),
      );
    return Number(inserted.lastInsertRowid);
  }

  /** Every revision for a task, newest first — the immutable history a
   * reader can show without a second table. */
  listPlanRevisions(taskRef: number): PlanRevision[] {
    return this.db
      .prepare("SELECT * FROM plan_revision WHERE task_ref = ? ORDER BY revision DESC")
      .all(taskRef)
      .map(readPlanRevision);
  }

  /** The current plan revision: the newest row an operator (or an
   * auto-applied plan-only proposal) has actually put in force. Null for
   * every task filed before this feature, and for a task whose only
   * revision so far is still 'blocked' — callers fall back to
   * `latestPlanArtifact`'s synthetic revision 1 in both cases. */
  currentPlanRevision(taskRef: number): PlanRevision | null {
    const row = this.db
      .prepare("SELECT * FROM plan_revision WHERE task_ref = ? AND status = 'applied' ORDER BY revision DESC LIMIT 1")
      .get(taskRef);
    return row === undefined ? null : readPlanRevision(row as Record<string, unknown>);
  }

  /** The newest revision regardless of status, including one still
   * 'blocked' awaiting an operator's decision — what a reader shows
   * alongside the current one to render a pending proposal at all. */
  latestPlanRevision(taskRef: number): PlanRevision | null {
    const row = this.db.prepare("SELECT * FROM plan_revision WHERE task_ref = ? ORDER BY revision DESC LIMIT 1").get(taskRef);
    return row === undefined ? null : readPlanRevision(row as Record<string, unknown>);
  }

  getPlanRevision(id: number): PlanRevision | null {
    const row = this.db.prepare("SELECT * FROM plan_revision WHERE id = ?").get(id);
    return row === undefined ? null : readPlanRevision(row as Record<string, unknown>);
  }

  /**
   * An operator's accept/reject of a 'blocked' (authority-changing) revision.
   * Fails closed (returns false) unless the row is still exactly 'blocked' —
   * a stale page reload must never resolve a decision that already
   * resolved, or resolve one that was never open. The content columns
   * (artifact, reason, evidence link, author) never change; only this
   * disposition does.
   */
  resolvePlanRevision(id: number, outcome: "applied" | "rejected", resolvedBy: string, now: Date): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE plan_revision SET status = ?, resolved_at = ?, resolved_by = ?
          WHERE id = ? AND status = 'blocked'`,
      )
      .run(outcome, now.toISOString(), resolvedBy, id);
    return Number(changes) > 0;
  }

  /** Stamp the exact plan revision and authority snapshot a run's brief was
   * built from — set once, early, before the agent is invoked. */
  setRunPlanRevision(id: number, planRevisionId: number | null, authorityDigest: string | null): void {
    this.db
      .prepare("UPDATE run SET plan_revision = ?, authority_digest = ? WHERE id = ?")
      .run(planRevisionId, authorityDigest, id);
  }

  /** Append one atomic milestone checkpoint. Append-only: the newest row
   * for a run is its current progress, and every earlier row is history a
   * reader can show without a second table. */
  insertRunCheckpoint(
    checkpoint: { run: number; taskRef: number; planRevision: number; snapshot: ProgressSnapshot },
    now: Date,
  ): number {
    const inserted = this.db
      .prepare(
        `INSERT INTO run_checkpoint (run, task_ref, plan_revision, snapshot_json, created_at)
         VALUES (?, ?, ?, ?, ?)`,
      )
      .run(checkpoint.run, checkpoint.taskRef, checkpoint.planRevision, JSON.stringify(checkpoint.snapshot), now.toISOString());
    return Number(inserted.lastInsertRowid);
  }

  /** One run's current progress, or null if it has never checkpointed —
   * true of every run before this feature, and of a run still on its first
   * milestone. */
  latestCheckpointForRun(run: number): RunCheckpoint | null {
    const row = this.db.prepare("SELECT * FROM run_checkpoint WHERE run = ? ORDER BY id DESC LIMIT 1").get(run);
    return row === undefined ? null : readRunCheckpoint(row as Record<string, unknown>);
  }

  /** The latest progress for a task, whichever run wrote it — what the task
   * page and focused chat render live, including once the run that wrote
   * it has ended. */
  latestCheckpointForTask(taskRef: number): RunCheckpoint | null {
    const row = this.db.prepare("SELECT * FROM run_checkpoint WHERE task_ref = ? ORDER BY id DESC LIMIT 1").get(taskRef);
    return row === undefined ? null : readRunCheckpoint(row as Record<string, unknown>);
  }

  /** One run's full checkpoint history, oldest first. */
  checkpointHistory(run: number): RunCheckpoint[] {
    return this.db.prepare("SELECT * FROM run_checkpoint WHERE run = ? ORDER BY id ASC").all(run).map(readRunCheckpoint);
  }

  /** The newest scout run's report for a task (v34), when one exists. */
  latestReportArtifact(taskRef: number): Artifact | null {
    const row = this.db
      .prepare(
        `SELECT artifact.* FROM artifact
         JOIN run ON run.id = artifact.run
         WHERE run.task_ref = ? AND run.role = 'scout' AND artifact.kind = 'report'
         ORDER BY artifact.id DESC LIMIT 1`,
      )
      .get(taskRef);
    return row === undefined ? null : readArtifact(row as Record<string, unknown>);
  }

  /** Answered questions for one task, newest first — the planner's memory. */
  answeredDecisionsFor(
    taskId: string,
    limit = 5,
  ): { question: string; choice: string | null; note: string | null }[] {
    return this.db
      .prepare(
        `SELECT decision.question, decision.choice, decision.note
         FROM decision
         JOIN run ON run.id = decision.run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE task_ref.backend = ? AND task_ref.external_id = ?
           AND decision.answered_at IS NOT NULL
         ORDER BY decision.answered_at DESC, decision.id DESC LIMIT ?`,
      )
      .all(BUILT_IN, taskId, Math.max(1, Math.min(Math.floor(limit), 20)))
      .map(row => ({
        question: String(row["question"]),
        choice: row["choice"] === null ? null : String(row["choice"]),
        note: row["note"] === null ? null : String(row["note"]),
      }));
  }

  listDecisions(only: "open" | "unanswered" | "all" = "unanswered"): (Decision & { taskId: string })[] {
    const where =
      only === "open"
        ? "WHERE decision.state = 'open'"
        : only === "unanswered"
          ? "WHERE decision.state IN ('open','expired')"
          : "";
    return this.db
      .prepare(
        `SELECT decision.*, task_ref.external_id AS task_id FROM decision
         JOIN run ON run.id = decision.run
         JOIN task_ref ON task_ref.id = run.task_ref
         ${where} ORDER BY decision.id`,
      )
      .all()
      .map(row => ({ ...readDecision(row), taskId: String(row["task_id"]) }));
  }

  /**
   * The lazy deadline sweep, run at every entry point that shows or answers
   * decisions. Expiry changes what a decision looks like, never what happens
   * to its task: the hold stays, and nothing chooses.
   */
  expireOverdueDecisions(now: Date): number {
    const { changes } = this.db
      .prepare(
        `UPDATE decision SET state = 'expired'
          WHERE state = 'open' AND deadline IS NOT NULL AND deadline <= ?`,
      )
      .run(now.toISOString());
    return Number(changes);
  }

  /** Every decision this task's runs ever raised, newest first — one task page's worth. */
  decisionsForTask(taskRef: number): Decision[] {
    return this.db
      .prepare(
        `SELECT decision.* FROM decision
         JOIN run ON run.id = decision.run
         WHERE run.task_ref = ? ORDER BY decision.id DESC`,
      )
      .all(taskRef)
      .map(readDecision);
  }

  /** Unanswered decisions whose task belongs to this project (or is unplaced). */
  listDecisionsScoped(repo: string | null): (Decision & { taskId: string; repo: string | null })[] {
    // The row's repo rides along so a roll-up caller can prove it against
    // the ceiling per row (Codex roll-up inbox review, finding 1). No SQL
    // LIMIT here, so post-filtering cannot be crowded out.
    return this.db
      .prepare(
        `SELECT decision.*, task_ref.external_id AS task_id, task_ref.repo AS task_repo FROM decision
         JOIN run ON run.id = decision.run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE decision.state IN ('open','expired')
           AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
         ORDER BY decision.id`,
      )
      .all(repo, repo)
      .map(row => ({
        ...readDecision(row),
        taskId: String(row["task_id"]),
        repo: row["task_repo"] === null || row["task_repo"] === undefined ? null : String(row["task_repo"]),
      }));
  }

  countUnansweredScoped(repo: string | null): number {
    const row = this.db
      .prepare(
        `SELECT COUNT(*) AS n FROM decision
         JOIN run ON run.id = decision.run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE decision.state IN ('open','expired')
           AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)`,
      )
      .get(repo, repo);
    return Number(row?.["n"] ?? 0);
  }

  countUnanswered(): number {
    const row = this.db
      .prepare("SELECT COUNT(*) AS n FROM decision WHERE state IN ('open','expired')")
      .get();
    return Number(row?.["n"] ?? 0);
  }

  /**
   * Attach every answered-but-undelivered decision of this task to a run,
   * snapshot included — the causal record of which answers this attempt was
   * actually given (§4's parent_run provenance, as a relation).
   *
   * "Undelivered" means: not yet attached to any run that finished `built`.
   * A resume that failed may be handed the same answers again; the accepted
   * build is the durable terminus. Selection is causal, never temporal —
   * "newer than the last built run" stops being true the moment a resume
   * fails and a second decision is answered in between.
   */
  attachAnswers(runId: number, taskRef: number): (Decision & { taskId: string })[] {
    // Lineage filter (tournament round-2 finding 7): a racing agent's
    // answers reach only ITS runs; ordinary runs see only ordinary
    // decisions. NULL matches NULL — the two worlds never cross.
    const receiving = this.db.prepare("SELECT contestant FROM run WHERE id = ?").get(runId);
    const contestant = receiving === undefined || receiving["contestant"] === null ? null : Number(receiving["contestant"]);
    const rows = this.db
      .prepare(
        `SELECT decision.*, task_ref.external_id AS task_id FROM decision
         JOIN run ON run.id = decision.run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE run.task_ref = ? AND decision.state = 'answered'
           AND (decision.contestant IS ? OR decision.contestant = ?)
           AND NOT EXISTS (
             SELECT 1 FROM run_decision
             JOIN run AS delivered ON delivered.id = run_decision.run
             WHERE run_decision.decision = decision.id AND delivered.outcome = 'built'
           )
         ORDER BY decision.id`,
      )
      .all(taskRef, contestant, contestant);
    for (const row of rows) {
      this.db
        .prepare(
          `INSERT OR IGNORE INTO run_decision (run, decision, choice, note) VALUES (?, ?, ?, ?)`,
        )
        .run(runId, Number(row["id"]), row["choice"], row["note"]);
    }
    return rows.map(row => ({ ...readDecision(row), taskId: String(row["task_id"]) }));
  }

  // ---- attended core (v25) -------------------------------------------------

  /**
   * Mint one attended authorization. Expired predecessors are closed in the
   * SAME transaction (end reason 'expired'); a live one refuses — revoke
   * first, never silently supersede a signature.
   */
  mintAttendedAuthorization(
    input: {
      id: string;
      taskRef: number;
      approver: string;
      runner: string;
      runnerGeneration: number;
      compositeDigest: string;
      termsJson: string;
      maxSessionTurns: number;
      budgetMicrousd: number;
      parentRun?: number | null;
      followup?: string | null;
      absoluteExpiry: string;
      /** Quick mint (C2/M4): the mode signature substitutes for the
       * per-mint password — RE-PROVED here, in the mint transaction
       * itself, never a pre-checked flag: the mode must be live, its
       * digest exact, and the minting approver must BE the signer. */
      basis?: { kind: "mode"; digest: string };
      now: Date;
    },
    mutation: Mutation = {},
  ): { ok: true; authorization: AttendedAuthorization } | { ok: false; reason: "authorization-open" | "mode-ended" | "approval-rules" } {
    return this.once(mutation, "mintAttendedAuthorization", () =>
      this.transact(() => {
        const now = input.now.toISOString();
        // v102: a watched run is one person's yes, so a project's approval rules bind it like a seal:
        // never the requester's where that's refused, never protected work (which takes two people).
        const externalId = this.externalIdFor(input.taskRef);
        if (externalId !== null) {
          const gate = this.approvalGate(externalId, input.approver, input.basis === undefined ? "person" : "mode");
          // Protected work runs only on a scope two people sealed; a watched run is never the second yes.
          if (gate.verdict !== "seal" || (gate.protectedWork && !this.scopeSealed(externalId))) return { ok: false as const, reason: "approval-rules" as const };
        }
        if (input.basis !== undefined) {
          const ref = this.refForId(input.taskRef);
          const mode = ref === null || ref.repo === null ? null : this.activeMode(ref.repo, input.now);
          let quickMint = false;
          if (mode !== null && mode.digest === input.basis.digest && mode.signedBy === input.approver) {
            try {
              quickMint = (JSON.parse(mode.termsJson) as { quickMint?: unknown }).quickMint === true;
            } catch {
              quickMint = false;
            }
          }
          if (!quickMint) return { ok: false as const, reason: "mode-ended" as const };
        }
        this.db
          .prepare(
            `UPDATE attended_authorization SET closed_at = ?, end_reason = 'expired'
              WHERE task_ref = ? AND closed_at IS NULL AND absolute_expiry <= ?`,
          )
          .run(now, input.taskRef, now);
        const open = this.db
          .prepare("SELECT 1 AS hit FROM attended_authorization WHERE task_ref = ? AND closed_at IS NULL LIMIT 1")
          .get(input.taskRef);
        if (open !== undefined) return { ok: false as const, reason: "authorization-open" as const };
        this.db
          .prepare(
            `INSERT INTO attended_authorization
               (id, task_ref, approver, runner, runner_generation, composite_digest, terms_json,
                max_session_turns, budget_microusd, parent_run, followup, created_at, absolute_expiry,
                authority_basis, mode_digest)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            input.id,
            input.taskRef,
            input.approver,
            input.runner,
            input.runnerGeneration,
            input.compositeDigest,
            input.termsJson,
            input.maxSessionTurns,
            input.budgetMicrousd,
            input.parentRun ?? null,
            input.followup ?? null,
            now,
            input.absoluteExpiry,
            input.basis === undefined ? "password" : "mode",
            input.basis === undefined ? null : input.basis.digest,
          );
        const minted = this.readAuthorization(input.id);
        if (minted === null) throw new Error("attended authorization vanished inside its own mint");
        return { ok: true as const, authorization: minted };
      }),
      result => result.ok,
    );
  }

  /** Close every authorization past its absolute expiry (round-6 finding
   * 8): the durable closure the gates and the partial unique rely on —
   * an expired corpse must not keep a task locked to its named runner. */
  sweepExpiredAuthorizations(now: Date): number {
    const stamp = now.toISOString();
    const { changes } = this.db
      .prepare(
        `UPDATE attended_authorization SET closed_at = ?, end_reason = 'expired'
          WHERE closed_at IS NULL AND absolute_expiry <= ?`,
      )
      .run(stamp, stamp);
    return Number(changes);
  }

  readAuthorization(id: string): AttendedAuthorization | null {
    const row = this.db.prepare("SELECT * FROM attended_authorization WHERE id = ?").get(id);
    return row === undefined ? null : readAuthorizationRow(row);
  }

  /** Open continuation authorizations named to this runner (Phase 2E, A4):
   * unconsumed, carrying a parent attempt — tick's continuation pass reads
   * this; liveness is the caller's check, as everywhere. */
  openContinuationAuthorizations(runner: string): AttendedAuthorization[] {
    return this.db
      .prepare(
        `SELECT * FROM attended_authorization
          WHERE closed_at IS NULL AND attempt_run IS NULL AND parent_run IS NOT NULL AND runner = ?
          ORDER BY created_at`,
      )
      .all(runner)
      .map(readAuthorizationRow);
  }

  /**
   * Why a finished run cannot be continued right now, in words — or null.
   * The ENUMERATED non-terminal publication states (round-3 R7 demanded
   * the concrete list, not "open intents"): a publication still moving
   * ('intended','pushed', or 'opened' with the remote not yet settled) and
   * a merge intent still live ('pending','claimed') both block.
   */
  continuationBlockOf(runId: number): string | null {
    const publication = this.db
      .prepare(
        `SELECT state, remote_state FROM publication WHERE run = ?
          ORDER BY id DESC LIMIT 1`,
      )
      .get(runId);
    if (publication !== undefined) {
      const state = String(publication["state"]);
      const remote = publication["remote_state"] === null ? null : String(publication["remote_state"]);
      if (state === "intended" || state === "pushed") {
        return `this attempt is being published (${state}) — continue after the pull request settles`;
      }
      if (state === "opened" && (remote === null || remote === "open")) {
        return "this attempt's pull request is open — review it there, or close it before continuing";
      }
      const intent = this.db
        .prepare(
          `SELECT merge_intent.state AS state FROM merge_intent
            JOIN publication ON publication.id = merge_intent.publication
           WHERE publication.run = ? AND merge_intent.state IN ('pending','claimed') LIMIT 1`,
        )
        .get(runId);
      if (intent !== undefined) return "a merge is in flight for this attempt — continue after it settles";
    }
    return null;
  }

  /** The one OPEN authorization for a task, or null. */
  openAuthorizationFor(taskRef: number): AttendedAuthorization | null {
    const row = this.db
      .prepare("SELECT * FROM attended_authorization WHERE task_ref = ? AND closed_at IS NULL")
      .get(taskRef);
    return row === undefined ? null : readAuthorizationRow(row);
  }

  /**
   * One durable liveness beat. The DURABLE COLUMN IS THE AUTHORITATIVE
   * CLOCK; the only suppressed writes are duplicate-tab beats landing
   * within 5 seconds of the stored value, so observed grace never shrinks
   * below 40 of the nominal 45 seconds.
   */
  beatAuthorization(id: string, now: Date): boolean {
    const cutoff = new Date(now.getTime() - 5_000).toISOString();
    const { changes } = this.db
      .prepare(
        `UPDATE attended_authorization SET last_beat_at = ?
          WHERE id = ? AND closed_at IS NULL
            AND (last_beat_at IS NULL OR last_beat_at <= ?)`,
      )
      .run(now.toISOString(), id, cutoff);
    return Number(changes) > 0;
  }

  /** Explicit terminal closure — run end, expiry, or revocation. CAS on open. */
  closeAuthorization(id: string, endReason: string, now: Date): boolean {
    const { changes } = this.db
      .prepare("UPDATE attended_authorization SET closed_at = ?, end_reason = ? WHERE id = ? AND closed_at IS NULL")
      .run(now.toISOString(), endReason, id);
    return Number(changes) > 0;
  }

  // The one attempt is consumed and bound by `admitAttended` alone (final
  // authority closure): there is no post-insert consume road — a two-write
  // path that could bind a foreign run, or leave `attempt_run` set while
  // the run's own binding stayed null, does not exist.

  /**
   * Money already committed against an authorization: settled and uncertain
   * turns at their accounted charge, plus the live reservation of any
   * unsettled turn. The budget gate reads THIS, never run.cost_usd.
   */
  authorizationSpendMicrousd(id: string): number {
    const row = this.db
      .prepare(
        `SELECT COALESCE(SUM(CASE
            WHEN st.state IN ('settled','uncertain') THEN COALESCE(st.accounted_microusd, 0)
            WHEN st.state IN ('recorded','written','accepted') THEN st.reserved_microusd
            ELSE 0 END), 0) AS spent
           FROM session_turn st JOIN run r ON r.id = st.run
          WHERE r.attended_authorization = ?`,
      )
      .get(id);
    return Number(row?.["spent"] ?? 0);
  }

  /**
   * Record one turn — the gate where the cap, the single-flight rule, the
   * budget reservation, the lease re-proof, and the open-decision rule all
   * hold or refuse ATOMICALLY (v6 W6: a fenced coordinator fails inside
   * this transaction, not at its next poll). For 'answer' turns the
   * delivery-CAS on decision.delivered_turn happens here; run_decision
   * attaches only at ACCEPTANCE (v6 W5).
   */
  recordSessionTurn(input: {
    run: number;
    sourceKind: SessionTurn["sourceKind"];
    sourceId?: number | null;
    author?: string | null;
    text: string;
    repairLimit?: number;
    now: Date;
  }): { ok: true; turn: SessionTurn } | { ok: false; reason: RecordTurnRefusal } {
    return this.transact(() => {
      const now = input.now.toISOString();
      const held = this.heldSessionOf(input.run);
      if (held === null || held.endedAt !== null) return { ok: false as const, reason: "no-held-session" as const };
      if (held.state !== "open") return { ok: false as const, reason: "fenced" as const };
      const run = this.db.prepare("SELECT task_ref, attended_authorization FROM run WHERE id = ?").get(input.run);
      if (run === undefined || run["attended_authorization"] === null) {
        return { ok: false as const, reason: "no-held-session" as const };
      }
      const authorization = this.readAuthorization(String(run["attended_authorization"]));
      if (authorization === null || authorization.closedAt !== null) {
        return { ok: false as const, reason: "fenced" as const };
      }
      // The synchronous lease re-proof (v6 W6): the recorded lease must be
      // the task's current live lease at this instant.
      if (this.currentLiveLease(Number(run["task_ref"]), input.now) !== held.leaseId) {
        return { ok: false as const, reason: "fenced" as const };
      }
      // The per-authorization turn cap counts EVERY injection across the
      // authorization's runs.
      const counted = this.db
        .prepare(
          `SELECT COUNT(*) AS n FROM session_turn st JOIN run r ON r.id = st.run
            WHERE r.attended_authorization = ?`,
        )
        .get(authorization.id);
      if (Number(counted?.["n"] ?? 0) >= authorization.maxSessionTurns) {
        return { ok: false as const, reason: "turn-cap" as const };
      }
      // Single flight: one unsettled turn at a time, by design.
      const unsettled = this.db
        .prepare(
          `SELECT 1 AS hit FROM session_turn
            WHERE run = ? AND state IN ('recorded','written','accepted') LIMIT 1`,
        )
        .get(input.run);
      if (unsettled !== undefined) return { ok: false as const, reason: "turn-open" as const };
      // A waiting question outranks free-form speech: answer it first.
      if (input.sourceKind === "operator") {
        const open = this.db
          .prepare("SELECT 1 AS hit FROM decision WHERE run = ? AND state IN ('open','expired') LIMIT 1")
          .get(input.run);
        if (open !== undefined) return { ok: false as const, reason: "decision-open" as const };
      }
      // Machine repair is bounded per triggering decision, like REPAIR_TURNS.
      if (input.sourceKind === "repair") {
        const limit = input.repairLimit ?? 2;
        const prior = this.db
          .prepare(
            "SELECT COUNT(*) AS n FROM session_turn WHERE run = ? AND source_kind = 'repair' AND source_id IS ?",
          )
          .get(input.run, input.sourceId ?? null);
        if (Number(prior?.["n"] ?? 0) >= limit) return { ok: false as const, reason: "repair-exhausted" as const };
      }
      // Reservation = remaining budget: under the stop-threshold semantic
      // and the CLI's cumulative cap, that is the true worst case.
      const spent = this.authorizationSpendMicrousd(authorization.id);
      const remaining = authorization.budgetMicrousd - spent;
      if (remaining <= 0) return { ok: false as const, reason: "budget-exhausted" as const };
      // Answer exactly-once: the delivery-CAS (v6 W5). This whole method is
      // one transaction, so read-then-set is serialized; the partial unique
      // index is the backstop.
      if (input.sourceKind === "answer") {
        const decision = this.db
          .prepare("SELECT delivered_turn FROM decision WHERE id = ?")
          .get(input.sourceId ?? -1);
        if (decision === undefined || decision["delivered_turn"] !== null) {
          return { ok: false as const, reason: "answer-delivered" as const };
        }
      }
      const top = this.db.prepare("SELECT MAX(seq) AS top FROM session_turn WHERE run = ?").get(input.run);
      const seq = Number(top?.["top"] ?? 0) + 1;
      const { lastInsertRowid } = this.db
        .prepare(
          `INSERT INTO session_turn
             (run, seq, source_kind, source_id, author, text, reserved_microusd, recorded_at, state)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'recorded')`,
        )
        .run(
          input.run,
          seq,
          input.sourceKind,
          input.sourceId ?? null,
          input.author ?? null,
          input.text,
          remaining,
          now,
        );
      const id = Number(lastInsertRowid);
      if (input.sourceKind === "answer") {
        const claimed = this.db
          .prepare("UPDATE decision SET delivered_turn = ? WHERE id = ? AND delivered_turn IS NULL")
          .run(id, input.sourceId ?? -1);
        if (Number(claimed.changes) === 0) throw new Error("answer delivery lost a race inside its own transaction");
      }
      const turn = this.readSessionTurn(id);
      if (turn === null) throw new Error("session turn vanished inside its own recording");
      return { ok: true as const, turn };
    });
  }

  /** Answered decisions on a held run whose answer has not yet been
   * injected — the coordinator's per-pulse scan (v3 R3). */
  undeliveredDecisionsOf(run: number): Decision[] {
    return this.db
      .prepare("SELECT * FROM decision WHERE run = ? AND state = 'answered' AND delivered_turn IS NULL ORDER BY id")
      .all(run)
      .map(readDecision);
  }

  readSessionTurn(id: number): SessionTurn | null {
    const row = this.db.prepare("SELECT * FROM session_turn WHERE id = ?").get(id);
    return row === undefined ? null : readSessionTurnRow(row);
  }

  sessionTurnsOf(run: number): SessionTurn[] {
    return this.db
      .prepare("SELECT * FROM session_turn WHERE run = ? ORDER BY seq")
      .all(run)
      .map(readSessionTurnRow);
  }

  /** Bytes flushed to stdin. Write success is NOT acceptance (spike fact 5). */
  markTurnWritten(id: number, now: Date): boolean {
    const { changes } = this.db
      .prepare("UPDATE session_turn SET state = 'written', written_at = ? WHERE id = ? AND state = 'recorded'")
      .run(now.toISOString(), id);
    return Number(changes) > 0;
  }

  /**
   * Bind pending answers to the BRIEF turn (round-6 finding 2): a held
   * build's brief carries every answered-but-undelivered decision, and the
   * builder's ordinary pre-spawn attach would claim delivery the agent
   * never proved. The pre-attached run_decision rows are WITHDRAWN here and
   * each decision's delivery-CAS points at the brief turn — run_decision
   * re-attaches only at that turn's acceptance, exactly like answer turns.
   */
  bindBriefDeliveries(runId: number, briefTurn: number, decisionIds: readonly number[]): void {
    if (decisionIds.length === 0) return;
    this.transact(() => {
      for (const decision of decisionIds) {
        this.db.prepare("DELETE FROM run_decision WHERE run = ? AND decision = ?").run(runId, decision);
        this.db
          .prepare("UPDATE decision SET delivered_turn = ? WHERE id = ? AND delivered_turn IS NULL")
          .run(briefTurn, decision);
      }
    });
  }

  /**
   * Acceptance — THIS turn's system/init (or its result, retroactively).
   * This is also where run_decision attaches, for EVERY decision whose
   * delivery-CAS points at this turn (answer turns claim one at recording;
   * a brief turn claims every pending answer it carried): delivery is
   * claimed only once the agent provably received the words (v6 W5).
   */
  markTurnAccepted(id: number, now: Date): boolean {
    return this.transact(() => {
      const { changes } = this.db
        .prepare(
          `UPDATE session_turn SET state = 'accepted', accepted_at = ?
            WHERE id = ? AND state IN ('recorded','written')`,
        )
        .run(now.toISOString(), id);
      if (Number(changes) === 0) return false;
      const turn = this.readSessionTurn(id);
      if (turn !== null) this.attachDeliveriesOf(turn.run, id);
      return true;
    });
  }

  private attachDeliveriesOf(runId: number, turnId: number): void {
    const carried = this.db
      .prepare("SELECT id, choice, note FROM decision WHERE delivered_turn = ?")
      .all(turnId);
    for (const decision of carried) {
      this.db
        .prepare("INSERT OR IGNORE INTO run_decision (run, decision, choice, note) VALUES (?, ?, ?, ?)")
        .run(runId, Number(decision["id"]), decision["choice"], decision["note"]);
    }
  }

  /**
   * Settle a turn from its result. The provider's totals are CUMULATIVE per
   * process, so the measured charge is the marginal delta from the held
   * session's durable baseline, advanced here atomically. A missing or
   * regressing total is a TELEMETRY FAILURE: the turn settles uncertain at
   * its reservation, the baseline stays, and the caller must end the hold.
   * Run aggregates gain the same delta so attended spend never disappears
   * from routine reporting (v3 R4).
   */
  settleTurn(
    id: number,
    result: { cumulativeMicrousd: number | null; outputTokens: number | null; now: Date },
  ): { ok: true; measuredMicrousd: number } | { ok: false; reason: "telemetry" | "not-unsettled" } {
    return this.transact(() => {
      const turn = this.readSessionTurn(id);
      if (turn === null || !["recorded", "written", "accepted"].includes(turn.state)) {
        return { ok: false as const, reason: "not-unsettled" as const };
      }
      const held = this.heldSessionOf(turn.run);
      if (held === null) return { ok: false as const, reason: "not-unsettled" as const };
      const now = result.now.toISOString();
      if (result.cumulativeMicrousd === null || result.cumulativeMicrousd < held.cumulativeMicrousd) {
        // Conservative posture: charge the reservation, never invent zero.
        this.db
          .prepare(
            `UPDATE session_turn SET state = 'uncertain', settled_at = ?,
                    accounted_microusd = reserved_microusd, accounted_at = ? WHERE id = ?`,
          )
          .run(now, now, id);
        this.chargeRunAggregates(turn.run, turn.reservedMicrousd, 0);
        return { ok: false as const, reason: "telemetry" as const };
      }
      const measured = result.cumulativeMicrousd - held.cumulativeMicrousd;
      const tokens = result.outputTokens ?? 0;
      // Result proves acceptance when the init was missed (spike-consistent).
      this.db
        .prepare(
          `UPDATE session_turn SET state = 'settled', settled_at = ?,
                  accepted_at = COALESCE(accepted_at, ?),
                  measured_microusd = ?, output_tokens = ?,
                  accounted_microusd = ?, accounted_at = ? WHERE id = ?`,
        )
        .run(now, now, measured, result.outputTokens ?? null, measured, now, id);
      if (turn.acceptedAt === null) {
        // The acceptance this settlement back-filled attaches whatever
        // deliveries the turn carried (answers, or a brief's pending set).
        this.attachDeliveriesOf(turn.run, id);
      }
      this.db
        .prepare(
          `UPDATE held_session SET cumulative_microusd = ?, cumulative_tokens_out = cumulative_tokens_out + ?
            WHERE run = ?`,
        )
        .run(result.cumulativeMicrousd, tokens, turn.run);
      this.chargeRunAggregates(turn.run, measured, tokens);
      return { ok: true as const, measuredMicrousd: measured };
    });
  }

  /**
   * Terminal conservative settlement on process exit (ruling 15).
   * 'cancelled' = recorded but never written: charged zero. 'uncertain' =
   * written or accepted but never proven settled: charged its reservation.
   * A turn that never reached ACCEPTANCE reverts its delivery claim so the
   * ordinary road can deliver the answer later (v6 W5); an accepted turn
   * keeps its attach — acceptance is the proof.
   */
  settleTurnTerminal(id: number, terminal: "uncertain" | "cancelled", now: Date): boolean {
    return this.transact(() => {
      const turn = this.readSessionTurn(id);
      if (turn === null || !["recorded", "written", "accepted"].includes(turn.state)) return false;
      const at = now.toISOString();
      const charge = terminal === "uncertain" ? turn.reservedMicrousd : 0;
      this.db
        .prepare(
          `UPDATE session_turn SET state = ?, settled_at = ?, accounted_microusd = ?, accounted_at = ?
            WHERE id = ?`,
        )
        .run(terminal, at, charge, at, id);
      if (turn.acceptedAt === null) {
        // Never-accepted: EVERY delivery claim this turn held reverts —
        // an answer turn's one decision, or a brief turn's pending set —
        // so the ordinary road can deliver later (v6 W5, round-6 f2).
        this.db.prepare("UPDATE decision SET delivered_turn = NULL WHERE delivered_turn = ?").run(id);
      }
      if (charge > 0) this.chargeRunAggregates(turn.run, charge, 0);
      return true;
    });
  }

  private chargeRunAggregates(run: number, microusd: number, tokensOut: number): void {
    this.db
      .prepare(
        `UPDATE run SET cost_usd = COALESCE(cost_usd, 0) + ?,
                tokens_out = COALESCE(tokens_out, 0) + ? WHERE id = ?`,
      )
      .run(microusd / 1_000_000, tokensOut, run);
    this.settleRunSpend(run, new Date());
  }

  /**
   * Custody intent — INSERTed in the final dispatch-proof transaction,
   * before spawn. The run-held partial unique refuses a
   * second hold typed, not by accident.
   */
  openHeldSession(input: {
    run: number;
    authorizationId: string;
    runner: string;
    leaseId: string;
    upIncarnation: string;
    cookie: string;
    socketPath: string;
    now: Date;
  }): { ok: true } | { ok: false; reason: "run-held" } {
    try {
      this.db
        .prepare(
          `INSERT INTO held_session
             (run, authorization_id, runner, lease_id, up_incarnation, cookie, socket_path, started_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          input.run,
          input.authorizationId,
          input.runner,
          input.leaseId,
          input.upIncarnation,
          input.cookie,
          input.socketPath,
          input.now.toISOString(),
        );
      return { ok: true };
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      // SQLite names the COLUMN in unique violations, never the index.

      if (message.includes("UNIQUE") || message.includes("PRIMARY KEY")) return { ok: false, reason: "run-held" };
      throw error;
    }
  }

  /** Stamp pids after spawn. False = the row closed underneath the spawn — kill the child. */
  stampHeldSession(run: number, supervisorPid: number, agentPgid: number): boolean {
    return this.transact(() => {
      const { changes } = this.db
        .prepare("UPDATE held_session SET supervisor_pid = ?, agent_pgid = ? WHERE run = ? AND ended_at IS NULL")
        .run(supervisorPid, agentPgid, run);
      if (Number(changes) === 0) return false;
      this.recordRunProcess(run, supervisorPid, new Date(), false);
      this.recordRunProcess(run, agentPgid, new Date());
      return true;
    });
  }

  heldSessionOf(run: number): HeldSession | null {
    const row = this.db.prepare("SELECT * FROM held_session WHERE run = ?").get(run);
    return row === undefined ? null : readHeldSessionRow(row);
  }

  /** Every un-ended custody row — the fence sweep's and hard-stop's read. */
  /** The durable session gauge (v28): open custody rows for this runner —
   * a restarted `up` with orphans pending must count them, so the
   * in-process map is never the truth. */
  openHeldSessionCount(runner: string): number {
    const row = this.db
      .prepare("SELECT COUNT(*) AS n FROM held_session WHERE runner = ? AND ended_at IS NULL")
      .get(runner);
    return Number(row?.["n"] ?? 0);
  }

  /** Every open authorization on this runner — the beat-all's worklist. */
  openAuthorizationsOf(runner: string): AttendedAuthorization[] {
    return this.db
      .prepare("SELECT * FROM attended_authorization WHERE runner = ? AND closed_at IS NULL")
      .all(runner)
      .map(readAuthorizationRow);
  }

  openHeldSessions(): HeldSession[] {
    return this.db
      .prepare("SELECT * FROM held_session WHERE ended_at IS NULL ORDER BY run")
      .all()
      .map(readHeldSessionRow);
  }

  /** Ordinary close by the owning coordinator. CAS on un-ended. */
  endHeldSession(run: number, endReason: string, now: Date): boolean {
    const { changes } = this.db
      .prepare("UPDATE held_session SET ended_at = ?, end_reason = ? WHERE run = ? AND ended_at IS NULL")
      .run(now.toISOString(), endReason, run);
    return Number(changes) > 0;
  }

  /**
   * SEIZE custody for fencing (v6, after v4 Q5): CAS open→fencing AND fence
   * the recorded lease in ONE transaction, so a wedged owner's heartbeat
   * revival and every later coordinator write fail before any kill happens.
   */
  seizeHeldSession(
    run: number,
    fencer: string,
    deadline: Date,
    now: Date,
  ): { ok: true; session: HeldSession } | { ok: false; reason: "not-open" } {
    return this.transact(() => {
      const { changes } = this.db
        .prepare(
          `UPDATE held_session SET state = 'fencing', fencer = ?, fencing_deadline = ?
            WHERE run = ? AND state = 'open' AND ended_at IS NULL`,
        )
        .run(fencer, deadline.toISOString(), run);
      if (Number(changes) === 0) return { ok: false as const, reason: "not-open" as const };
      const session = this.heldSessionOf(run);
      if (session === null) throw new Error("held session vanished inside its own seize");
      this.db
        .prepare("UPDATE claim SET released_at = ?, released_by = 'held-fence' WHERE lease_id = ? AND released_at IS NULL")
        .run(now.toISOString(), session.leaseId);
      return { ok: true as const, session };
    });
  }

  /**
   * Take over a fencing operation whose owner went quiet (v5 P3): CAS on
   * the EXPIRED deadline. A loser stops only while a live fencer owns it.
   */
  takeoverHeldFencing(run: number, fencer: string, deadline: Date, now: Date): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE held_session SET fencer = ?, fencing_deadline = ?
          WHERE run = ? AND state = 'fencing' AND ended_at IS NULL AND fencing_deadline <= ?`,
      )
      .run(fencer, deadline.toISOString(), run, now.toISOString());
    return Number(changes) > 0;
  }

  /** Re-arm the fencing deadline while the work continues. Owner-CASed. */
  renewHeldFencing(run: number, fencer: string, deadline: Date): boolean {
    const { changes } = this.db
      .prepare(
        "UPDATE held_session SET fencing_deadline = ? WHERE run = ? AND state = 'fencing' AND fencer = ?",
      )
      .run(deadline.toISOString(), run, fencer);
    return Number(changes) > 0;
  }

  /** Final close of a fenced session — owner-CASed, after kill + settlement. */
  closeHeldFencing(run: number, fencer: string, endReason: string, now: Date): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE held_session SET ended_at = ?, end_reason = ?
          WHERE run = ? AND state = 'fencing' AND fencer = ? AND ended_at IS NULL`,
      )
      .run(now.toISOString(), endReason, run, fencer);
    return Number(changes) > 0;
  }

  /**
   * File one steering note (arc 1). Validation is validateNote EXACTLY —
   * no bespoke rule — and filing refuses on finished tasks and during open
   * tournaments (contestants share a task; all-racer delivery is a future
   * many-to-many, not a silent single-racer lie).
   */
  fileSteerNote(
    taskId: string,
    author: VerifiedAuthor,
    note: string,
    now: Date,
    mutation: Mutation = {},
  ): { ok: true; id: number } | { ok: false; reason: "unknown-task" | "task-finished" | "contest-open" | "invalid-note"; problem?: string } {
    return this.once(
      mutation,
      "fileSteerNote",
      () =>
        this.transact(() => {
          const valid = validateNote(note);
          if (!valid.ok) return { ok: false as const, reason: "invalid-note" as const, problem: valid.problem };
          const task = this.db.prepare("SELECT state FROM task WHERE id = ?").get(taskId);
          const ref = this.db
            .prepare("SELECT id FROM task_ref WHERE backend = ? AND external_id = ?")
            .get(BUILT_IN, taskId);
          if (task === undefined || ref === undefined) return { ok: false as const, reason: "unknown-task" as const };
          const state = String(task["state"]);
          if (state === "done" || state === "cancelled") return { ok: false as const, reason: "task-finished" as const };
          const racing = this.db
            .prepare(
              `SELECT 1 AS hit FROM contest WHERE task_ref = ?
                AND state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted') LIMIT 1`,
            )
            .get(Number(ref["id"]));
          if (racing !== undefined) return { ok: false as const, reason: "contest-open" as const };
          const inserted = this.db
            .prepare("INSERT INTO task_steer (task_ref, author, note, created_at, authorship_state) VALUES (?, ?, ?, ?, 'verified')")
            .run(Number(ref["id"]), author as unknown as string, valid.note, now.toISOString());
          this.bumpWake();
          return { ok: true as const, id: Number(inserted.lastInsertRowid) };
        }),
      result => result.ok,
    );
  }

  /** Every steering note of a task, filing order, delivery state included. */
  listSteerNotes(taskRef: number): SteerNote[] {
    return this.db
      .prepare("SELECT * FROM task_steer WHERE task_ref = ? ORDER BY id")
      .all(taskRef)
      .map(readSteerNote);
  }

  /** Undelivered, unsuperseded notes — the admitContest refusal predicate. */
  pendingSteerCount(taskRef: number): number {
    const row = this.db
      .prepare("SELECT COUNT(*) AS n FROM task_steer WHERE task_ref = ? AND delivered_at IS NULL AND superseded_at IS NULL")
      .get(taskRef);
    return Number(row?.["n"] ?? 0);
  }

  /**
   * The attach transaction (arc 1 finding 9): a DEDICATED pre-invocation
   * step, called by the builder after the run row exists and immediately
   * before the spawn. Selects pending notes whose previous attachment — if
   * any — is provably ABANDONED (finding 12): the attached run concluded,
   * or its lease is no longer the task's current live lease. Crashed runs
   * keep outcome NULL forever, so liveness, not finalization, is the
   * predicate — the same ONE fact the console derives runIsLive from.
   * Stamps attachment and returns exactly what the brief must quote.
   */
  attachSteerNotes(taskRef: number, runId: number, now: Date): SteerNote[] {
    return this.transact(() => {
      const run = this.db.prepare("SELECT task_ref, outcome, lease_id FROM run WHERE id = ?").get(runId);
      if (run === undefined || Number(run["task_ref"]) !== taskRef || run["outcome"] !== null) {
        throw new Error(`run ${runId} is not an open attempt of this task — steering attaches to nothing else`);
      }
      const live = this.currentLiveLease(taskRef, now);
      const rows = this.db
        .prepare(
          `SELECT * FROM task_steer
            -- Only VERIFIED authorship may enter a brief (ruling 11): the
            -- quarantine superseded legacy rows, and this predicate is the
            -- belt to that braces.
            WHERE task_ref = ? AND authorship_state = 'verified'
              AND delivered_at IS NULL AND superseded_at IS NULL
              AND (
                attached_run IS NULL
                OR attached_run = ?
                OR EXISTS (
                  SELECT 1 FROM run AS held WHERE held.id = task_steer.attached_run
                    AND (held.outcome IS NOT NULL OR ? IS NULL OR held.lease_id <> ?)
                )
              )
            ORDER BY id`,
        )
        .all(taskRef, runId, live, live);
      const stamp = now.toISOString();
      for (const row of rows) {
        this.db
          .prepare("UPDATE task_steer SET attached_run = ?, attached_at = ? WHERE id = ?")
          .run(runId, stamp, Number(row["id"]));
      }
      return rows.map(row => readSteerNote({ ...row, attached_run: runId, attached_at: stamp }));
    });
  }

  /**
   * The receipt (arc 1 finding 8): the stream proved the prompt reached the
   * agent, so every note riding this run settles delivered — immediately,
   * durably, and independently of how the run later ends. Null-guarded:
   * first receipt wins, and a replay changes nothing.
   */
  settleSteerDelivered(runId: number, now: Date): number {
    const { changes } = this.db
      .prepare("UPDATE task_steer SET delivered_at = ? WHERE attached_run = ? AND delivered_at IS NULL")
      .run(now.toISOString(), runId);
    return Number(changes);
  }

  /** A finished task's pending notes settle superseded — shown, typed, done. */
  supersedeSteerNotes(taskRef: number, now: Date): number {
    const { changes } = this.db
      .prepare("UPDATE task_steer SET superseded_at = ? WHERE task_ref = ? AND delivered_at IS NULL AND superseded_at IS NULL")
      .run(now.toISOString(), taskRef);
    return Number(changes);
  }

  /** The answers a run was given, exactly as it was given them. */
  answersFor(runId: number): { decision: Decision; choice: string; note: string | null }[] {
    return this.db
      .prepare(
        `SELECT decision.*, run_decision.choice AS given_choice, run_decision.note AS given_note
           FROM run_decision
           JOIN decision ON decision.id = run_decision.decision
          WHERE run_decision.run = ? ORDER BY decision.id`,
      )
      .all(runId)
      .map(row => ({
        decision: readDecision(row),
        choice: String(row["given_choice"]),
        note: row["given_note"] === null ? null : String(row["given_note"]),
      }));
  }

  /**
   * Answer a decision: one transaction for the CAS, the hold, and the outbox
   * episode, because a crash between any two of them leaves a lie — answered
   * but still held, or free but still paging.
   *
   * `by` is an identity the CALLER authenticated; this method records, it
   * does not vouch. A decision is answered once: the same choice replayed is
   * the stored answer handed back, a different choice is refused — "done"
   * is not negotiable, and neither is "decided".
   */
  answerDecision(
    answer: { id: number; choice: string; by: string; via: "cli" | "web" | "telegram" | "slack" | "discord" | "teams"; note?: string },
    now: Date,
    mutation: Mutation = {},
  ):
    | { ok: true; decision: Decision; duplicate?: boolean }
    | { ok: false; reason: "unknown-decision" | "bad-option" | "already-answered" | "bad-note" } {
    return this.once(
      mutation,
      "answerDecision",
      () => this.transact(() => this.answerDecisionLocked(answer, now)),
      result => result.ok,
    );
  }

  /**
   * The answer's body, for callers already holding the transaction — the
   * Telegram bridge re-proves its binding and consumes its action token in
   * the same transaction as this CAS, because "the chat was bound when we
   * looked" and "the chat is bound as this answer lands" are different
   * claims and only the second one authorizes anything.
   */
  answerDecisionLocked(
    answer: { id: number; choice: string; by: string; via: "cli" | "web" | "telegram" | "slack" | "discord" | "teams"; note?: string },
    now: Date,
  ):
    | { ok: true; decision: Decision; duplicate?: boolean }
    | { ok: false; reason: "unknown-decision" | "bad-option" | "already-answered" | "bad-note" } {
    const existing = this.getDecision(answer.id);
    if (existing === null) return { ok: false as const, reason: "unknown-decision" as const };
    if (!existing.options.some(option => option.id === answer.choice)) {
      return { ok: false as const, reason: "bad-option" as const };
    }
    // The note reaches web pages, terminals, and — quoted — a later
    // agent's brief. One shared validator, and this is its final gate.
    if (answer.note !== undefined && !validateNote(answer.note).ok) {
      return { ok: false as const, reason: "bad-note" as const };
    }

    const { changes } = this.db
      .prepare(
        `UPDATE decision SET state = 'answered', answered_at = ?, answered_by = ?,
                             answered_via = ?, choice = ?, note = ?
          WHERE id = ? AND state IN ('open','expired')`,
      )
      .run(now.toISOString(), answer.by, answer.via, answer.choice, answer.note?.trim() ?? null, answer.id);
    if (Number(changes) === 0) {
      // Duplicate success requires the whole TUPLE — choice AND note. The
      // same option with a different note is not the same answer: reporting
      // success while the racing note was silently dropped would tell the
      // operator their constraint traveled when it never did (Codex
      // free-text review, finding 4).
      const settled = this.getDecision(answer.id) as Decision;
      return settled.choice === answer.choice && (settled.note ?? null) === (answer.note?.trim() ?? null)
        ? { ok: true as const, decision: settled, duplicate: true }
        : { ok: false as const, reason: "already-answered" as const };
    }

    this.releaseOwnedHold("decision", String(answer.id));
    this.resolveEpisode(`decision:${answer.id}`, now);
    this.bumpWake();
    return { ok: true as const, decision: this.getDecision(answer.id) as Decision };
  }

  // ---- evidence ------------------------------------------------------------

  saveArtifact(
    artifact: {
      run: number;
      kind: Artifact["kind"];
      key: string;
      bytesOriginal: number;
      bytesStored: number;
      truncated: boolean;
      sha256: string;
      capture: string;
      /** Set when the stored bytes were REDACTED before storage (audit IV-7). */
      redacted?: boolean;
      /** Typed verdict of the capture command — a pick predicate reads THIS, never the prose in `capture`. */
      captureStatus?: "ok" | "failed";
    },
    now: Date,
  ): number {
    const inserted = this.db
      .prepare(
        `INSERT INTO artifact (run, kind, key, bytes_original, bytes_stored, truncated, sha256, capture, created_at, redacted, capture_status)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        artifact.run,
        artifact.kind,
        artifact.key,
        artifact.bytesOriginal,
        artifact.bytesStored,
        artifact.truncated ? 1 : 0,
        artifact.sha256,
        artifact.capture,
        now.toISOString(),
        artifact.redacted === true ? 1 : 0,
        artifact.captureStatus ?? null,
      );
    return Number(inserted.lastInsertRowid);
  }

  /** The latest handoff artifact for a task's runs — what a successor reads (audit SD-2). */
  latestHandoffArtifact(taskRef: number): Artifact | null {
    const row = this.db
      .prepare(
        `SELECT artifact.* FROM artifact
         JOIN run ON run.id = artifact.run
         WHERE run.task_ref = ? AND artifact.kind = 'handoff'
         ORDER BY artifact.id DESC LIMIT 1`,
      )
      .get(taskRef);
    return row === undefined ? null : readArtifact(row);
  }

  /** Whether a run's terminal diff was redacted for secrets (audit IV-7) — the publication gate reads this. */
  hasRedactedTerminalDiff(run: number): boolean {
    const row = this.db
      .prepare("SELECT 1 AS hit FROM artifact WHERE run = ? AND kind = 'terminal-diff' AND redacted = 1 LIMIT 1")
      .get(run);
    return row !== undefined;
  }

  getArtifact(id: number): Artifact | null {
    const row = this.db.prepare("SELECT * FROM artifact WHERE id = ?").get(id);
    return row === undefined ? null : readArtifact(row);
  }

  /**
   * The artifact only if it belongs to this run — membership enforced by
   * the lookup itself, never by route choreography around two lookups. A
   * mismatched pair is simply not found, whatever the URL claimed.
   */
  artifactForRun(runId: number, artifactId: number): Artifact | null {
    const row = this.db
      .prepare("SELECT * FROM artifact WHERE run = ? AND id = ?")
      .get(runId, artifactId);
    return row === undefined ? null : readArtifact(row);
  }

  artifactsFor(run: number): Artifact[] {
    return this.db
      .prepare("SELECT * FROM artifact WHERE run = ? ORDER BY id")
      .all(run)
      .map(readArtifact);
  }

  /**
   * Attach evidence to a decision — refused unless both belong to the same
   * run. The guard is in the INSERT itself rather than checked first, so
   * nothing can slip between the check and the write.
   */
  linkEvidence(decision: number, artifact: number): void {
    const { changes } = this.db
      .prepare(
        `INSERT INTO decision_artifact (decision, artifact)
         SELECT d.id, a.id FROM decision AS d JOIN artifact AS a
          WHERE d.id = ? AND a.id = ? AND a.run = d.run`,
      )
      .run(decision, artifact);
    if (Number(changes) === 0) {
      throw new Error(
        `artifact ${artifact} does not belong to decision ${decision}'s run — evidence never crosses runs`,
      );
    }
  }

  evidenceFor(decision: number): Artifact[] {
    return this.db
      .prepare(
        `SELECT artifact.* FROM artifact
         JOIN decision_artifact ON decision_artifact.artifact = artifact.id
         WHERE decision_artifact.decision = ? ORDER BY artifact.id`,
      )
      .all(decision)
      .map(readArtifact);
  }

  // ---- incidents -----------------------------------------------------------

  createIncident(incident: { run: number; kind: Incident["kind"] }, now: Date): number {
    const inserted = this.db
      .prepare("INSERT INTO incident (run, kind, created_at) VALUES (?, ?, ?)")
      .run(incident.run, incident.kind, now.toISOString());
    return Number(inserted.lastInsertRowid);
  }

  incidentForRun(run: number): Incident | null {
    const row = this.db.prepare("SELECT * FROM incident WHERE run = ?").get(run);
    return row === undefined ? null : readIncident(row);
  }

  /** Unresolved, task attached, oldest first. No time window: these do not age out. */
  openIncidents(repo: string | null = null): (Incident & { taskId: string })[] {
    return this.db
      .prepare(
        `SELECT incident.*, task_ref.external_id AS task_id FROM incident
         JOIN run ON run.id = incident.run
         JOIN task_ref ON task_ref.id = run.task_ref
         WHERE incident.resolved_at IS NULL
           AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
         ORDER BY incident.id`,
      )
      .all(repo, repo)
      .map(row => ({ ...readIncident(row), taskId: String(row["task_id"]) }));
  }

  /** Every incident this task's runs ever raised, newest first, resolved or not. */
  incidentsForTask(taskRef: number): Incident[] {
    return this.db
      .prepare(
        `SELECT incident.* FROM incident
         JOIN run ON run.id = incident.run
         WHERE run.task_ref = ? ORDER BY incident.id DESC`,
      )
      .all(taskRef)
      .map(readIncident);
  }

  /** Resolving also lifts the incident's hold — one act, one transaction, owned here. */
  resolveIncident(id: number, by: string, now: Date): boolean {
    return this.transact(() => this.resolveIncidentLocked(id, by, now));
  }

  /** The body, for callers already holding the transaction (requeueTask). */
  private resolveIncidentLocked(id: number, by: string, now: Date): boolean {
    const incident = this.db
      .prepare("SELECT kind, run FROM incident WHERE id = ?")
      .get(id);
    const { changes } = this.db
      .prepare("UPDATE incident SET resolved_at = ?, resolved_by = ? WHERE id = ? AND resolved_at IS NULL")
      .run(now.toISOString(), by, id);
    if (Number(changes) === 0) return false;
    this.releaseOwnedHold("incident", String(id));
    // The incident's PAGE episode resolves with it (external dispatch
    // review, finding 43) — a stale page delivered after resolution told
    // the operator about a problem that no longer stands. Keys follow the
    // enqueue sites' own vocabulary, per kind.
    if (incident !== undefined) {
      const run = Number(incident["run"]);
      const kind = String(incident["kind"]);
      const taskRef = this.db.prepare("SELECT task_ref FROM run WHERE id = ?").get(run);
      const keys: Record<string, string> = {
        "malformed-decision": `malformed:${run}`,
        "commit-failure": `commit-failure:${run}`,
        "malformed-plan": `malformed-plan:${run}`,
        ...(taskRef === undefined
          ? {}
          : {
              "attempts-exhausted": `stalled:${Number(taskRef["task_ref"])}`,
              "plan-attempts-exhausted": `plan-stalled:${Number(taskRef["task_ref"])}`,
            }),
      };
      const key = keys[kind];
      if (key !== undefined) this.resolveEpisode(key, now);
    }
    this.bumpWake();
    return true;
  }

  // ---- telegram ------------------------------------------------------------

  /** Mint a pairing code's record. The code itself was shown once; this is its hash. */
  createTelegramPairing(
    pairing: { codeHash: string; approver: string; by: string; ttlMs: number },
    now: Date,
  ): void {
    const generation = this.approverGeneration(pairing.approver);
    if (generation === null) throw new Error(`no approver named ${pairing.approver}`);
    this.db
      .prepare(
        `INSERT INTO telegram_pairing (code_hash, approver, approver_generation, created_at, created_by, expires_at)
         VALUES (?, ?, ?, ?, ?, ?)`,
      )
      .run(
        pairing.codeHash,
        pairing.approver,
        generation,
        now.toISOString(),
        pairing.by,
        new Date(now.getTime() + pairing.ttlMs).toISOString(),
      );
  }

  /**
   * Consume a pairing code and create the binding, as one transaction.
   *
   * The conditional UPDATE is the consumption: exactly one caller ever sees
   * `changes = 1`, however many pollers race. A replay of the very update
   * that paired (Telegram redelivers) recognizes the finished binding
   * instead of failing. Success invalidates every other outstanding code —
   * a code that was minted and superseded must not still open a door — and
   * the partial unique index enforces one live binding per bot.
   */
  consumeTelegramPairing(
    attempt: {
      codeHash: string;
      botId: string;
      chatId: string;
      userId: string;
      updateId: number;
    },
    now: Date,
  ):
    | { ok: true; binding: TelegramBinding; replay: boolean }
    | { ok: false; reason: "unknown-code" | "already-bound" } {
    return this.transact(() => {
      const stamp = now.toISOString();
      const { changes } = this.db
        .prepare(
          `UPDATE telegram_pairing
              SET consumed_at = ?, consumed_chat = ?, consumed_user = ?, consumed_update = ?
            WHERE code_hash = ? AND consumed_at IS NULL AND expires_at > ?`,
        )
        .run(stamp, attempt.chatId, attempt.userId, attempt.updateId, attempt.codeHash, stamp);

      if (Number(changes) === 0) {
        // The same update replayed after a crash-between-apply-and-ack:
        // the code is consumed by exactly this chat and user, and the
        // binding it made is live. That is a completed pairing, not a foe.
        const consumed = this.db
          .prepare(
            `SELECT 1 AS hit FROM telegram_pairing
              WHERE code_hash = ? AND consumed_chat = ? AND consumed_user = ? AND consumed_update = ?`,
          )
          .get(attempt.codeHash, attempt.chatId, attempt.userId, attempt.updateId);
        if (consumed !== undefined) {
          const live = this.liveTelegramBindingFor(attempt.botId, attempt.userId);
          if (live !== null && live.chatId === attempt.chatId) {
            return { ok: true as const, binding: live, replay: true };
          }
        }
        return { ok: false as const, reason: "unknown-code" as const };
      }

      const pairing = this.db
        .prepare("SELECT approver, approver_generation FROM telegram_pairing WHERE code_hash = ?")
        .get(attempt.codeHash) as Record<string, unknown>;

      // The code was minted under a generation; the binding is only valid
      // if that generation still stands — a rotation between mint and
      // consumption strands the code.
      const current = this.approverGeneration(String(pairing["approver"]));
      if (current === null || current !== Number(pairing["approver_generation"])) {
        return { ok: false as const, reason: "unknown-code" as const };
      }

      try {
        this.db
          .prepare(
            `INSERT INTO telegram_binding (bot_id, chat_id, user_id, approver, approver_generation, paired_at, paired_by, pair_update_id)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            attempt.botId,
            attempt.chatId,
            attempt.userId,
            String(pairing["approver"]),
            Number(pairing["approver_generation"]),
            stamp,
            String(pairing["approver"]),
            attempt.updateId,
          );
      } catch {
        // The partial unique index said no: this Telegram user already has a live binding.
        return { ok: false as const, reason: "already-bound" as const };
      }
      // Every other outstanding code for this person dies with this success;
      // a teammate's pending code is theirs and stays.
      this.db.prepare("DELETE FROM telegram_pairing WHERE consumed_at IS NULL AND approver = ?").run(String(pairing["approver"]));

      const binding = this.liveTelegramBindingFor(attempt.botId, attempt.userId);
      if (binding === null) throw new Error("the binding vanished inside its own transaction");
      // A person's FIRST pairing starts from now (Telegram task updates): every
      // ROUTINE fact already in the outbox is history for this destination —
      // settled here, in the pairing's own transaction, with a receipt that
      // says it was skipped, never sent as a backlog to a phone that just
      // arrived. The skip is explicit: no delivered_at, no attempt, only the
      // `skipped:` receipt — a message no phone received is never reported
      // as delivered (see TELEGRAM_UNSETTLED). An open decision or an
      // attention-class fact still wants a person and stays pending. A
      // re-pairing after a revocation keeps the older promise instead: what
      // no phone ever received still waits for whenever pairing happens.
      // Existing destinations are untouched.
      const priorPairing = this.db
        .prepare("SELECT 1 AS hit FROM telegram_binding WHERE bot_id = ? AND user_id = ? AND id <> ? LIMIT 1")
        .get(attempt.botId, attempt.userId, binding.id);
      if (priorPairing === undefined) {
        this.db
          .prepare(
            `INSERT OR IGNORE INTO notification_delivery (notification, destination, receipt)
               SELECT id, ?, '${TELEGRAM_SKIPPED_RECEIPT}' FROM notification
                WHERE resolved_at IS NULL
                  AND dedupe_key NOT LIKE 'decision:%'
                  AND (push_class IS NULL OR push_class <> 'attention')`,
          )
          .run(this.telegramDestination(binding));
      }
      return { ok: true as const, binding, replay: false };
    });
  }

  // ---- team chats (v72) -------------------------------------------------------

  /** The live team-conversation row for one chat, group or private. */
  telegramTeamChat(botId: string, chatId: string): TelegramTeamChat | null {
    const row = this.db.prepare("SELECT * FROM telegram_team_chat WHERE bot_id = ? AND chat_id = ? AND revoked_at IS NULL").get(botId, chatId);
    return row === undefined ? null : readTelegramTeamChat(row);
  }

  listTelegramTeamChats(botId: string): TelegramTeamChat[] {
    return this.db.prepare("SELECT * FROM telegram_team_chat WHERE bot_id = ? AND revoked_at IS NULL ORDER BY id").all(botId).map(readTelegramTeamChat);
  }

  /**
   * Point a chat at a team conversation: an earlier choice for the same chat
   * is revoked in the same transaction, and delivery starts from now — the
   * conversation's history is read in the console, never replayed into a
   * chat that just arrived. A group already following another conversation
   * elsewhere, or a conversation already followed by another group, refuses.
   */
  bindTelegramTeamChat(args: { botId: string; chatId: string; binding: number; kind: "group" | "private"; conversation: string; by: string }, now: Date):
    { ok: true; chat: TelegramTeamChat } | { ok: false; reason: "group-taken" } {
    return this.transact(() => this.savepoint(() => {
      // Check the expected collision before revoking the current selection.
      // The IMMEDIATE transaction excludes another group winning between
      // this check and insertion; unexpected failures roll back the switch.
      if (args.kind === "group") {
        const group = this.db.prepare("SELECT bot_id, chat_id FROM telegram_team_chat WHERE conversation = ? AND kind = 'group' AND revoked_at IS NULL").get(args.conversation);
        if (group !== undefined && (group["bot_id"] !== args.botId || group["chat_id"] !== args.chatId)) return { ok: false as const, reason: "group-taken" as const };
      }
      const stamp = now.toISOString();
      this.db.prepare("UPDATE telegram_team_chat SET revoked_at = ?, revoked_by = ? WHERE bot_id = ? AND chat_id = ? AND revoked_at IS NULL").run(stamp, args.by, args.botId, args.chatId);
      const thread = this.db.prepare("SELECT thread FROM team_conversation WHERE id = ?").get(args.conversation);
      if (thread === undefined) throw new Error("no such team conversation");
      const cursor = Number(this.db.prepare("SELECT COALESCE(MAX(id), 0) AS n FROM mate_message WHERE thread = ?").get(Number(thread["thread"]))?.["n"] ?? 0);
      this.db.prepare("INSERT INTO telegram_team_chat (bot_id, chat_id, binding, kind, conversation, bound_by, bound_at, cursor) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
        .run(args.botId, args.chatId, args.binding, args.kind, args.conversation, args.by, stamp, cursor);
      return { ok: true as const, chat: this.telegramTeamChat(args.botId, args.chatId)! };
    }));
  }

  unbindTelegramTeamChat(botId: string, chatId: string, by: string, now: Date): boolean {
    const { changes } = this.db.prepare("UPDATE telegram_team_chat SET revoked_at = ?, revoked_by = ? WHERE bot_id = ? AND chat_id = ? AND revoked_at IS NULL").run(now.toISOString(), by, botId, chatId);
    return Number(changes) > 0;
  }

  /** Forward only: a cursor never moves back, and a revoked row keeps its last position. */
  advanceTelegramTeamCursor(id: number, messageId: number): boolean {
    const { changes } = this.db.prepare("UPDATE telegram_team_chat SET cursor = ? WHERE id = ? AND cursor < ? AND revoked_at IS NULL").run(messageId, id, messageId);
    return Number(changes) > 0;
  }

  /**
   * Every live binding for a bot, oldest first — and only while each
   * approver's credential generation still matches. A rotation that
   * somehow missed the sweep reads as no binding at all, which is the
   * failure direction that fails closed. Several teammates may each hold
   * one (v72); nothing here ranks them.
   */
  liveTelegramBindings(botId: string): TelegramBinding[] {
    return this.db
      .prepare(
        `SELECT telegram_binding.* FROM telegram_binding
         JOIN approver ON approver.name = telegram_binding.approver
          AND approver.generation = telegram_binding.approver_generation
          AND approver.revoked_at IS NULL
         WHERE bot_id = ? AND telegram_binding.revoked_at IS NULL
         ORDER BY telegram_binding.id`,
      )
      .all(botId)
      .map(readTelegramBinding);
  }

  /** The live binding one Telegram user holds with a bot, if any. */
  liveTelegramBindingFor(botId: string, userId: string): TelegramBinding | null {
    return this.liveTelegramBindings(botId).find(binding => binding.userId === userId) ?? null;
  }

  /** The exact binding, if it is still live under its approver's current generation. */
  liveTelegramBindingById(id: number): TelegramBinding | null {
    const row = this.db
      .prepare(
        `SELECT telegram_binding.* FROM telegram_binding
         JOIN approver ON approver.name = telegram_binding.approver
          AND approver.generation = telegram_binding.approver_generation
          AND approver.revoked_at IS NULL
         WHERE telegram_binding.id = ? AND telegram_binding.revoked_at IS NULL`,
      )
      .get(id);
    return row === undefined ? null : readTelegramBinding(row);
  }

  /** The oldest live binding for a bot — the single-person reading kept for
   * status lines and fixtures; delivery and inbound handling read
   * `liveTelegramBindings` / `liveTelegramBindingFor` instead. */
  liveTelegramBinding(botId: string): TelegramBinding | null {
    return this.liveTelegramBindings(botId)[0] ?? null;
  }

  /** Revoke every live binding one person holds with a bot, and everything
   * those chats could still do. Teammates' bindings are untouched. */
  unpairTelegram(botId: string, by: string, now: Date): boolean {
    return this.transact(() => {
      const mine = this.liveTelegramBindings(botId).filter(binding => binding.approver === by);
      if (mine.length === 0) return false;
      const stamp = now.toISOString();
      for (const live of mine) {
        this.db
          .prepare("UPDATE telegram_binding SET revoked_at = ?, revoked_by = ? WHERE id = ?")
          .run(stamp, by, live.id);
        this.db
          .prepare("UPDATE telegram_action SET consumed_at = ? WHERE binding = ? AND consumed_at IS NULL")
          .run(stamp, live.id);
      }
      return true;
    });
  }

  createTelegramAction(
    action: {
      token: string;
      binding: number;
      decision: number;
      optionId: string;
      phase: "choose" | "confirm" | "cancel";
      chatId: string;
      messageId?: string;
      ttlMs?: number;
      /** Binds an irreversible confirmation to the EXACT note it showed. */
      noteDigest?: string;
    },
    now: Date,
  ): void {
    this.db
      .prepare(
        `INSERT INTO telegram_action (token, binding, decision, option_id, phase, chat_id, message_id, created_at, expires_at, note_digest)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        action.token,
        action.binding,
        action.decision,
        action.optionId,
        action.phase,
        action.chatId,
        action.messageId ?? null,
        now.toISOString(),
        action.ttlMs === undefined ? null : new Date(now.getTime() + action.ttlMs).toISOString(),
        action.noteDigest ?? null,
      );
  }

  // ---- free-text drafts (v10) ---------------------------------------------

  /** Which decision an outbound Telegram message carried. Recorded after the
   * send returns its id; a send whose record was lost routes nothing. */
  recordTelegramDecisionMessage(binding: number, chatId: string, messageId: string, decision: number, now: Date): void {
    this.db
      .prepare(
        `INSERT OR IGNORE INTO telegram_decision_message (binding, chat_id, message_id, decision, created_at)
         VALUES (?, ?, ?, ?, ?)`,
      )
      .run(binding, chatId, messageId, decision, now.toISOString());
  }

  /** The decision behind an exact replied-to message, or nothing. Never "the latest". */
  decisionForTelegramMessage(binding: number, chatId: string, messageId: string): number | null {
    const row = this.db
      .prepare(
        "SELECT decision FROM telegram_decision_message WHERE binding = ? AND chat_id = ? AND message_id = ?",
      )
      .get(binding, chatId, messageId);
    return row === undefined ? null : Number(row["decision"]);
  }

  /** The one live, unexpired draft for a decision, if any. */
  liveNoteDraft(binding: number, decision: number, now: Date): { id: number; note: string; updateId: number; state: string } | null {
    const row = this.db
      .prepare(
        `SELECT id, note, update_id, state FROM telegram_note_draft
          WHERE binding = ? AND decision = ? AND state IN ('pending','armed') AND expires_at > ?`,
      )
      .get(binding, decision, now.toISOString());
    return row === undefined
      ? null
      : { id: Number(row["id"]), note: String(row["note"]), updateId: Number(row["update_id"]), state: String(row["state"]) };
  }

  /**
   * Persist a validated note as the live draft. A newer update SUPERSEDES
   * the old draft — drafts are immutable, and only a GREATER update_id may
   * replace one, so out-of-order delivery cannot resurrect an older note
   * (Codex free-text review, state machine). Returns false when an older
   * or equal update tried.
   */
  saveNoteDraft(
    draft: { binding: number; decision: number; updateId: number; messageId: string; replyTo: string; note: string },
    now: Date,
    ttlMs = 10 * 60_000,
  ): boolean {
    return this.transact(() => {
      const live = this.db
        .prepare(
          `SELECT id, update_id FROM telegram_note_draft
            WHERE binding = ? AND decision = ? AND state IN ('pending','armed')`,
        )
        .get(draft.binding, draft.decision);
      if (live !== undefined) {
        if (Number(live["update_id"]) >= draft.updateId) return false;
        this.db.prepare("UPDATE telegram_note_draft SET state = 'superseded' WHERE id = ?").run(live["id"]);
      }
      this.db
        .prepare(
          `INSERT INTO telegram_note_draft (binding, decision, update_id, message_id, reply_to, note, state, created_at, expires_at)
           VALUES (?, ?, ?, ?, ?, ?, 'pending', ?, ?)`,
        )
        .run(
          draft.binding,
          draft.decision,
          draft.updateId,
          draft.messageId,
          draft.replyTo,
          draft.note,
          now.toISOString(),
          new Date(now.getTime() + ttlMs).toISOString(),
        );
      return true;
    });
  }

  /** Move a draft between states; the caller owns the transaction story. */
  setNoteDraftState(id: number, state: "pending" | "armed" | "superseded" | "consumed" | "discarded"): void {
    this.db.prepare("UPDATE telegram_note_draft SET state = ? WHERE id = ?").run(state, id);
  }

  // ---- flow decisions on Telegram (v86) ------------------------------------------

  createTelegramFlowActions(at: { binding: number; chatId: string; card: number; entry: number }, actions: readonly { token: string; action: TelegramFlowAction["action"] }[], now: Date, days = 7): void {
    const stamp = now.toISOString(), expires = new Date(now.getTime() + days * 86_400_000).toISOString();
    const insert = this.db.prepare("INSERT INTO telegram_flow_action (token, binding, card, entry, action, chat_id, message_id, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?, NULL, ?, ?)");
    for (const one of actions) insert.run(one.token, at.binding, at.card, at.entry, one.action, at.chatId, stamp, expires);
  }

  getTelegramFlowAction(token: string): TelegramFlowAction | null {
    if (!/^[0-9a-f]{32}$/.test(token)) return null;
    const row = this.db.prepare("SELECT * FROM telegram_flow_action WHERE token = ?").get(token);
    if (row === undefined) return null;
    return { token: String(row["token"]), binding: Number(row["binding"]), card: Number(row["card"]), entry: Number(row["entry"]), action: String(row["action"]) as TelegramFlowAction["action"],
      chatId: String(row["chat_id"]), messageId: row["message_id"] === null ? null : String(row["message_id"]), expiresAt: String(row["expires_at"]), consumedAt: row["consumed_at"] === null ? null : String(row["consumed_at"]) };
  }

  placeTelegramFlowActions(tokens: readonly string[], messageId: string): void {
    const place = this.db.prepare("UPDATE telegram_flow_action SET message_id = ? WHERE token = ?");
    for (const token of tokens) place.run(messageId, token);
  }

  /** Retire every button (and prompt) for one visit of a card: it was decided, or its draft replaced. */
  retireTelegramFlowVisit(card: number, entry: number, now: Date): void {
    const stamp = now.toISOString();
    this.db.prepare("UPDATE telegram_flow_action SET consumed_at = ? WHERE card = ? AND entry = ? AND consumed_at IS NULL").run(stamp, card, entry);
    this.db.prepare("UPDATE telegram_flow_prompt SET consumed_at = ? WHERE card = ? AND entry = ? AND consumed_at IS NULL").run(stamp, card, entry);
  }

  recordTelegramFlowPrompt(prompt: TelegramFlowPrompt, now: Date, hours = 24): void {
    this.db.prepare("INSERT OR REPLACE INTO telegram_flow_prompt (chat_id, message_id, binding, card, entry, mode, created_at, expires_at, consumed_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL)")
      .run(prompt.chatId, prompt.messageId, prompt.binding, prompt.card, prompt.entry, prompt.mode, now.toISOString(), new Date(now.getTime() + hours * 3_600_000).toISOString());
  }

  /** The live prompt a message replies to, if any. */
  telegramFlowPrompt(chatId: string, messageId: string, now: Date): TelegramFlowPrompt | null {
    const row = this.db.prepare("SELECT * FROM telegram_flow_prompt WHERE chat_id = ? AND message_id = ? AND consumed_at IS NULL AND expires_at > ?").get(chatId, messageId, now.toISOString());
    if (row === undefined) return null;
    return { chatId: String(row["chat_id"]), messageId: String(row["message_id"]), binding: Number(row["binding"]), card: Number(row["card"]), entry: Number(row["entry"]), mode: String(row["mode"]) as TelegramFlowPrompt["mode"] };
  }

  // ---- "Send to me" and "Person chooses" (flow-send.ts) ------------------------------------------

  /** What one visit sent: recorded once, the first time (a later pass finds it kept). */
  recordFlowSend(row: Omit<FlowSendRow, "createdAt">, now: Date): boolean {
    return Number(this.db.prepare("INSERT OR IGNORE INTO flow_send (card, entry, stage, person, content_json, created_at) VALUES (?, ?, ?, ?, ?, ?)")
      .run(row.card, row.entry, row.stage, row.person, row.contentJson, now.toISOString()).changes) === 1;
  }

  flowSend(card: number, entry: number): FlowSendRow | null {
    const row = this.db.prepare("SELECT * FROM flow_send WHERE card = ? AND entry = ?").get(card, entry);
    return row === undefined ? null : { card: Number(row["card"]), entry: Number(row["entry"]), stage: String(row["stage"]), person: String(row["person"]), contentJson: String(row["content_json"]), createdAt: String(row["created_at"]) };
  }

  /** Every visit's send for a card, newest first: what the card shows it sent. */
  flowSends(card: number): FlowSendRow[] {
    return this.db.prepare("SELECT * FROM flow_send WHERE card = ? ORDER BY entry DESC").all(card).map(row => ({ card: Number(row["card"]), entry: Number(row["entry"]), stage: String(row["stage"]),
      person: String(row["person"]), contentJson: String(row["content_json"]), createdAt: String(row["created_at"]) }));
  }

  createTelegramFlowChoices(at: { binding: number; chatId: string; card: number; entry: number }, choices: readonly { token: string; choice: number; label: string }[], now: Date, days = 7): void {
    const stamp = now.toISOString(), expires = new Date(now.getTime() + days * 86_400_000).toISOString();
    const insert = this.db.prepare("INSERT INTO telegram_flow_choice (token, binding, card, entry, choice, label, chat_id, message_id, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)");
    for (const one of choices) insert.run(one.token, at.binding, at.card, at.entry, one.choice, one.label, at.chatId, stamp, expires);
  }

  getTelegramFlowChoice(token: string): TelegramFlowChoice | null {
    if (!/^[0-9a-f]{32}$/.test(token)) return null;
    const row = this.db.prepare("SELECT * FROM telegram_flow_choice WHERE token = ?").get(token);
    if (row === undefined) return null;
    return { token: String(row["token"]), binding: Number(row["binding"]), card: Number(row["card"]), entry: Number(row["entry"]), choice: Number(row["choice"]), label: String(row["label"]),
      chatId: String(row["chat_id"]), messageId: row["message_id"] === null ? null : String(row["message_id"]), expiresAt: String(row["expires_at"]), consumedAt: row["consumed_at"] === null ? null : String(row["consumed_at"]) };
  }

  placeTelegramFlowChoices(tokens: readonly string[], messageId: string): void {
    const place = this.db.prepare("UPDATE telegram_flow_choice SET message_id = ? WHERE token = ?");
    for (const token of tokens) place.run(messageId, token);
  }

  /** Retire every choice button for one visit of a card (and its reply prompt): it was chosen, or the card moved on. */
  /** A choice was made (or the card moved on): every option button, reply prompt and "Use this as your note?" for that
   * visit is spent, in Telegram and in every other chat app, whichever place it was made in. */
  retireFlowChoices(card: number, entry: number, now: Date): void {
    const stamp = now.toISOString();
    this.db.prepare("UPDATE telegram_flow_choice SET consumed_at = ? WHERE card = ? AND entry = ? AND consumed_at IS NULL").run(stamp, card, entry);
    this.retireTelegramFlowVisit(card, entry, now);
    // A chat app's flow tables exist only once that app's chat state created them; an install without it has none.
    const names = ["slack", "discord", "teams"].flatMap(app => ["flow_choice", "flow_note", "flow_prompt", "flow_action"].map(table => `${app}_${table}`));
    const present = new Set(this.db.prepare(`SELECT name FROM sqlite_master WHERE type = 'table' AND name IN (${names.map(() => "?").join(", ")})`).all(...names).map(row => String(row["name"])));
    for (const app of ["slack", "discord", "teams"])
      for (const table of ["flow_choice", "flow_note", "flow_prompt", "flow_action"])
        if (present.has(`${app}_${table}`))
          this.db.prepare(`UPDATE ${app}_${table} SET consumed = ?${table === "flow_note" ? ", words = NULL" : ""} WHERE card = ? AND entry = ? AND consumed IS NULL`).run(stamp, card, entry);
  }

  // ---- v93: a teammate's question on Telegram ------------------------------------------

  createTelegramQuestionActions(at: { binding: number; chatId: string; question: number }, choices: readonly { token: string; choice: string | null }[], now: Date, days = 7): void {
    const stamp = now.toISOString(), expires = new Date(now.getTime() + days * 86_400_000).toISOString();
    const insert = this.db.prepare("INSERT INTO telegram_question_action (token, binding, question, choice, chat_id, message_id, created_at, expires_at) VALUES (?, ?, ?, ?, ?, NULL, ?, ?)");
    for (const one of choices) insert.run(one.token, at.binding, at.question, one.choice, at.chatId, stamp, expires);
  }

  getTelegramQuestionAction(token: string): { token: string; binding: number; question: number; choice: string | null; chatId: string; messageId: string | null; expiresAt: string; consumedAt: string | null } | null {
    if (!/^[0-9a-f]{32}$/.test(token)) return null;
    const row = this.db.prepare("SELECT * FROM telegram_question_action WHERE token = ?").get(token);
    if (row === undefined) return null;
    return { token: String(row["token"]), binding: Number(row["binding"]), question: Number(row["question"]), choice: row["choice"] === null ? null : String(row["choice"]),
      chatId: String(row["chat_id"]), messageId: row["message_id"] === null ? null : String(row["message_id"]), expiresAt: String(row["expires_at"]), consumedAt: row["consumed_at"] === null ? null : String(row["consumed_at"]) };
  }

  placeTelegramQuestionActions(tokens: readonly string[], messageId: string): void {
    const place = this.db.prepare("UPDATE telegram_question_action SET message_id = ? WHERE token = ?");
    for (const token of tokens) place.run(messageId, token);
  }

  /** Retire every button and prompt for a question: it was answered (anywhere). */
  retireTelegramQuestion(question: number, now: Date): void {
    const stamp = now.toISOString();
    this.db.prepare("UPDATE telegram_question_action SET consumed_at = ? WHERE question = ? AND consumed_at IS NULL").run(stamp, question);
    this.db.prepare("UPDATE telegram_question_prompt SET consumed_at = ? WHERE question = ? AND consumed_at IS NULL").run(stamp, question);
  }

  recordTelegramQuestionPrompt(prompt: { chatId: string; messageId: string; binding: number; question: number }, now: Date, hours = 24): void {
    this.db.prepare("INSERT OR REPLACE INTO telegram_question_prompt (chat_id, message_id, binding, question, created_at, expires_at, consumed_at) VALUES (?, ?, ?, ?, ?, ?, NULL)")
      .run(prompt.chatId, prompt.messageId, prompt.binding, prompt.question, now.toISOString(), new Date(now.getTime() + hours * 3_600_000).toISOString());
  }

  telegramQuestionPrompt(chatId: string, messageId: string, now: Date): { chatId: string; messageId: string; binding: number; question: number } | null {
    const row = this.db.prepare("SELECT * FROM telegram_question_prompt WHERE chat_id = ? AND message_id = ? AND consumed_at IS NULL AND expires_at > ?").get(chatId, messageId, now.toISOString());
    return row === undefined ? null : { chatId: String(row["chat_id"]), messageId: String(row["message_id"]), binding: Number(row["binding"]), question: Number(row["question"]) };
  }

  getTelegramAction(token: string): TelegramAction | null {
    const row = this.db.prepare("SELECT * FROM telegram_action WHERE token = ?").get(token);
    return row === undefined ? null : readTelegramAction(row);
  }

  /**
   * Kill every live confirm/cancel challenge on a decision. Cancel means
   * cancelled: a confirm that survived its own cancellation would be an
   * irreversible choice still armed after the person said stop.
   */
  consumeTelegramChallenges(decision: number, now: Date): void {
    this.db
      .prepare(
        `UPDATE telegram_action SET consumed_at = ?
          WHERE decision = ? AND phase IN ('confirm','cancel') AND consumed_at IS NULL`,
      )
      .run(now.toISOString(), decision);
  }

  /** Consume once. False means somebody already did, or it expired — either way, no. */
  consumeTelegramAction(token: string, now: Date): boolean {
    const stamp = now.toISOString();
    const { changes } = this.db
      .prepare(
        `UPDATE telegram_action SET consumed_at = ?
          WHERE token = ? AND consumed_at IS NULL AND (expires_at IS NULL OR expires_at > ?)`,
      )
      .run(stamp, token, stamp);
    return Number(changes) > 0;
  }

  /** Stamp the message a choose-action's keyboard actually landed on. */
  placeTelegramActions(tokens: readonly string[], messageId: string): void {
    for (const token of tokens) {
      this.db
        .prepare("UPDATE telegram_action SET message_id = ? WHERE token = ?")
        .run(messageId, token);
    }
  }

  /**
   * Take or renew the bridge's poll lease. One live poller per bot: cron
   * overlapping a follower gets `bridge-busy`, an expired holder is taken
   * over at the next generation, and the cursor rides the lease so a stale
   * generation can neither poll nor move it.
   */
  acquireBridgeLease(
    botId: string,
    owner: string,
    ttlMs: number,
    now: Date,
  ):
    | { ok: true; generation: number; cursor: number }
    | { ok: false; reason: "bridge-busy"; holder: string; until: string } {
    return this.transact(() => {
      const stamp = now.toISOString();
      const expires = new Date(now.getTime() + ttlMs).toISOString();
      const row = this.db.prepare("SELECT * FROM bridge_lease WHERE bot_id = ?").get(botId);
      if (row === undefined) {
        this.db
          .prepare(
            `INSERT INTO bridge_lease (bot_id, owner, generation, cursor, expires_at, heartbeat_at)
             VALUES (?, ?, 1, 0, ?, ?)`,
          )
          .run(botId, owner, expires, stamp);
        return { ok: true as const, generation: 1, cursor: 0 };
      }
      const holder = String(row["owner"]);
      const live = String(row["expires_at"]) > stamp;
      if (live && holder !== owner) {
        return {
          ok: false as const,
          reason: "bridge-busy" as const,
          holder,
          until: String(row["expires_at"]),
        };
      }
      const generation = live && holder === owner ? Number(row["generation"]) : Number(row["generation"]) + 1;
      this.db
        .prepare(
          "UPDATE bridge_lease SET owner = ?, generation = ?, expires_at = ?, heartbeat_at = ? WHERE bot_id = ?",
        )
        .run(owner, generation, expires, stamp, botId);
      return { ok: true as const, generation, cursor: Number(row["cursor"]) };
    });
  }

  /** Hand the poll back at the end of a pass, so the next cron firing is not told busy. */
  releaseBridgeLease(botId: string, owner: string, now: Date): void {
    this.db
      .prepare("UPDATE bridge_lease SET expires_at = ? WHERE bot_id = ? AND owner = ?")
      .run(now.toISOString(), botId, owner);
  }

  // ---- publication ---------------------------------------------------------

  /** Grant publication for a repo. Replaces any live grant — one at a time, the newest word wins. */
  savePublicationGrant(
    grant: {
      repo: string;
      githubRepo: string;
      remote: string;
      headPrefix: string;
      base: string;
      capabilities: PublicationCapability[];
      selector: "ours" | "all";
      draft: boolean;
      grantedBy: string;
      merge?: boolean;
      mergeMethod?: "squash" | "merge" | "rebase" | null;
      mergeDeleteBranch?: boolean;
      publishOn?: "build" | "complete";
      mergeWhenGreen?: boolean;
    },
    now: Date,
  ): void {
    // Cross-column rule (v21): merge authority names its method, always —
    // additive ALTER cannot carry a table CHECK for this.
    if (grant.merge === true && grant.mergeMethod == null) {
      throw new Error("a merge grant names its method: --merge-method squash|merge|rebase");
    }
    this.transact(() => {
      this.db
        .prepare("UPDATE publication_grant SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
        .run(now.toISOString(), grant.grantedBy, grant.repo);
      this.db
        .prepare(
          `INSERT INTO publication_grant
             (repo, github_repo, remote, head_prefix, base, capabilities, selector, draft, granted_by, granted_at,
              merge, merge_method, merge_delete_branch, publish_on, merge_when_green)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          grant.repo,
          grant.githubRepo,
          grant.remote,
          grant.headPrefix,
          grant.base,
          JSON.stringify(grant.capabilities),
          grant.selector,
          grant.draft ? 1 : 0,
          grant.grantedBy,
          now.toISOString(),
          grant.merge === true ? 1 : 0,
          grant.mergeMethod ?? null,
          grant.mergeDeleteBranch === true ? 1 : 0,
          grant.publishOn ?? "build",
          grant.mergeWhenGreen === true ? 1 : 0,
        );
    });
  }

  // ---- the merge grant's machinery (v21) ----------------------------------

  /**
   * Reserve the next observation generation for a PR BEFORE the network
   * call — the settle below is conditional on still being newest, so a
   * stalled older response can neither overwrite nor authorize.
   */
  reserveObservation(githubRepo: string, prNumber: number): number {
    return this.transact(() => {
      const row = this.db
        .prepare("SELECT generation FROM ci_observation WHERE github_repo = ? AND pr_number = ?")
        .get(githubRepo, prNumber);
      const generation = (row === undefined ? 0 : Number(row["generation"])) + 1;
      if (row === undefined) {
        this.db
          .prepare(
            "INSERT INTO ci_observation (github_repo, pr_number, head_sha, state, generation, observed_at) VALUES (?, ?, '', 'none', ?, '')",
          )
          .run(githubRepo, prNumber, generation);
      } else {
        this.db
          .prepare("UPDATE ci_observation SET generation = ? WHERE github_repo = ? AND pr_number = ?")
          .run(generation, githubRepo, prNumber);
      }
      return generation;
    });
  }

  /**
   * Conditional settle: writes ONLY when this generation is still the
   * newest reserved one, and RETURNS whether it won — a losing response
   * has no effects and never yields a merge-eligible tuple (round-4
   * finding 24). Callers gate every side effect on `won`.
   */
  settleObservation(
    observation: { githubRepo: string; prNumber: number; headSha: string; state: "passing" | "failing" | "running" | "none"; generation: number },
    now: Date,
  ): { won: boolean } {
    const { changes } = this.db
      .prepare(
        `UPDATE ci_observation SET head_sha = ?, state = ?, observed_at = ?
          WHERE github_repo = ? AND pr_number = ? AND generation = ?`,
      )
      .run(observation.headSha, observation.state, now.toISOString(), observation.githubRepo, observation.prNumber, observation.generation);
    return { won: Number(changes) === 1 };
  }

  /** A repair in flight durably blocks its source PR's merge — STICKY:
   * lifted only by the authenticated unblock act or remote closure. */
  createMergeBlocker(publication: number, taskId: string, now: Date): void {
    this.db
      .prepare("INSERT OR IGNORE INTO merge_blocker (publication, reason, task_id, created_at) VALUES (?, 'repair-open', ?, ?)")
      .run(publication, taskId, now.toISOString());
  }

  mergeBlockerFor(publication: number): { reason: string; taskId: string | null; createdAt: string } | null {
    const row = this.db
      .prepare("SELECT reason, task_id, created_at FROM merge_blocker WHERE publication = ? AND lifted_at IS NULL")
      .get(publication);
    return row === undefined
      ? null
      : { reason: String(row["reason"]), taskId: row["task_id"] === null ? null : String(row["task_id"]), createdAt: String(row["created_at"]) };
  }

  /** Lifting is a STAMP, never a delete (D7): the People screen's history
   * claim — who unblocked which merge — has rows to stand on. */
  liftMergeBlocker(publication: number, by: string, now: Date): boolean {
    return (
      Number(
        this.db
          .prepare("UPDATE merge_blocker SET lifted_at = ?, lifted_by = ? WHERE publication = ? AND lifted_at IS NULL")
          .run(now.toISOString(), by, publication).changes,
      ) > 0
    );
  }

  /** Creation binds the AUTHORITY POSTURE the repo holds right now (E1's
   * first two transitions): no mode = the grant's own signature; a notify
   * mode = waiting-human even under a merge-capable grant; an automerge
   * mode = basis 'mode' bound to the signing digest. INSERT OR IGNORE —
   * an existing row's posture is the reconciler's job, never creation's. */
  createMergeIntent(
    intent: { publication: number; repo: string; grantTermsHash: string; headSha: string; method: "squash" | "merge" | "rebase"; deleteBranch: boolean },
    now: Date,
  ): void {
    this.transact(() => {
      const mode = this.activeMode(intent.repo, now);
      let state = "pending";
      let basis = "grant";
      let modeDigest: string | null = null;
      if (mode !== null) {
        let publication: unknown;
        try {
          publication = (JSON.parse(mode.termsJson) as { publication?: unknown }).publication;
        } catch {
          publication = undefined;
        }
        if (publication === "automerge") {
          basis = "mode";
          modeDigest = mode.digest;
        } else {
          state = "waiting-human";
          basis = "human";
        }
      }
      this.db
        .prepare(
          `INSERT OR IGNORE INTO merge_intent (publication, grant_terms_hash, head_sha, method, delete_branch, state, authority_basis, mode_digest, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(intent.publication, intent.grantTermsHash, intent.headSha, intent.method, intent.deleteBranch ? 1 : 0, state, basis, modeDigest, now.toISOString());
    });
  }

  /**
   * Claim by CAS with an expiring lease and a generation fence (the
   * delivery-claim discipline): only pending rows, or claimed rows whose
   * lease EXPIRED, are claimable; every later transition must present the
   * generation this claim minted, so a reclaimed row's old owner loses
   * every subsequent write. No permanently-claimed row is representable
   * (the table CHECK demands owner+expiry on 'claimed').
   */
  claimMergeIntent(id: number, by: string, leaseMs: number, now: Date): { generation: number } | null {
    return this.transact(() => {
      const row = this.db.prepare("SELECT state, claimed_until, generation FROM merge_intent WHERE id = ?").get(id);
      if (row === undefined) return null;
      const state = String(row["state"]);
      const expired = row["claimed_until"] !== null && String(row["claimed_until"]) <= now.toISOString();
      if (state !== "pending" && !(state === "claimed" && expired)) return null;
      const generation = Number(row["generation"]) + 1;
      const { changes } = this.db
        .prepare(
          `UPDATE merge_intent SET state = 'claimed', claimed_by = ?, claimed_until = ?, generation = ?
            WHERE id = ? AND generation = ?`,
        )
        .run(by, new Date(now.getTime() + leaseMs).toISOString(), generation, id, Number(row["generation"]));
      return Number(changes) === 1 ? { generation } : null;
    });
  }

  /** Renew the lease AND re-prove the generation in one CAS — the last
   * gate before the external call; a failed re-proof aborts the attempt. */
  renewMergeClaim(id: number, generation: number, leaseMs: number, now: Date): boolean {
    const { changes } = this.db
      .prepare("UPDATE merge_intent SET claimed_until = ? WHERE id = ? AND state = 'claimed' AND generation = ?")
      .run(new Date(now.getTime() + leaseMs).toISOString(), id, generation);
    return Number(changes) === 1;
  }

  /** STATE-SPECIFIC and TERMINALLY MONOTONIC (E1): the writer names the
   * state it believes it owns, and a terminal row is never overwritten —
   * a stale claim owner cannot un-merge what the observer already settled,
   * even at the same generation. bumpGeneration is the observer's fence:
   * settling somebody else's live row invalidates their later writes. */
  settleMergeIntent(
    id: number,
    generation: number,
    state: "merged" | "refused" | "superseded" | "pending" | "waiting-human",
    now: Date,
    detail: { error?: string | null; receipt?: string | null; countAttempt?: boolean; from?: "claimed" | "firing" | "nonterminal"; bumpGeneration?: boolean } = {},
  ): boolean {
    const from = detail.from ?? "nonterminal";
    const { changes } = this.db
      .prepare(
        `UPDATE merge_intent SET state = ?, claimed_by = NULL, claimed_until = NULL,
           firing_at = NULL, firing_deadline = NULL,
           authority_basis = CASE WHEN ? = 'waiting-human' THEN 'human' ELSE authority_basis END,
           mode_digest = CASE WHEN ? = 'waiting-human' THEN NULL ELSE mode_digest END,
           generation = generation + ?,
           attempts = attempts + ?, last_error = COALESCE(?, last_error), receipt = COALESCE(?, receipt),
           settled_at = CASE WHEN ? IN ('merged','refused','superseded') THEN ? ELSE settled_at END
         WHERE id = ? AND generation = ?
           AND state NOT IN ('merged','refused','superseded')
           AND (? = 'nonterminal' OR state = ?)`,
      )
      .run(
        state, state, state,
        detail.bumpGeneration === true ? 1 : 0,
        detail.countAttempt === true ? 1 : 0,
        detail.error ?? null, detail.receipt ?? null,
        state, now.toISOString(),
        id, generation,
        from, from,
      );
    return Number(changes) === 1;
  }

  /** The per-merge password ceremony's write (E1: waiting-human → pending
   * by the EXACT-INTENT ceremony): the caller has authenticated and shown
   * the operator the head they are authorizing. Basis becomes 'human' —
   * this signature covers this one merge and nothing else. */
  authorizeMergeIntent(id: number, expectedHeadSha: string, by: string, now: Date): { ok: true } | { ok: false; reason: "not-waiting" | "head-moved" } {
    void by;
    void now;
    return this.transact(() => {
      const row = this.db.prepare("SELECT state, head_sha FROM merge_intent WHERE id = ?").get(id);
      if (row === undefined || String(row["state"]) !== "waiting-human") return { ok: false as const, reason: "not-waiting" as const };
      if (String(row["head_sha"]) !== expectedHeadSha) return { ok: false as const, reason: "head-moved" as const };
      this.db
        .prepare(
          `UPDATE merge_intent SET state = 'pending', authority_basis = 'human', mode_digest = NULL,
                  generation = generation + 1, last_error = NULL
            WHERE id = ? AND state = 'waiting-human'`,
        )
        .run(id);
      return { ok: true as const };
    });
  }

  /** E1's linearization point: claimed → firing as a DURABLE CAS that
   * re-proves EVERY piece of the intent's authority inside one
   * transaction — the live grant's terms against the hash the intent was
   * written under, the exact head, and the basis-specific signature (a
   * live automerge mode with the bound digest for 'mode'; the absence of
   * a stricter notify posture for 'grant'). A revocation that committed
   * first already moved the row and this CAS fails; once this CAS
   * commits, no later revocation demotes it — the external call is
   * acknowledged one-shot. */
  fireMergeIntent(
    id: number,
    generation: number,
    proof: { repo: string; headSha: string; liveGrantTermsHash: string | null; graceMs: number },
    now: Date,
  ): { ok: true } | { ok: false; outcome: "raced" | "superseded" | "waiting-human"; why: string } {
    return this.transact(() => {
      const row = this.db
        .prepare("SELECT state, generation, head_sha, grant_terms_hash, authority_basis, mode_digest FROM merge_intent WHERE id = ?")
        .get(id);
      if (row === undefined || String(row["state"]) !== "claimed" || Number(row["generation"]) !== generation) {
        return { ok: false as const, outcome: "raced" as const, why: "the claim moved" };
      }
      const supersede = (why: string): { ok: false; outcome: "superseded"; why: string } => {
        this.settleMergeIntent(id, generation, "superseded", now, { error: why, from: "claimed" });
        return { ok: false as const, outcome: "superseded" as const, why };
      };
      const fence = (why: string): { ok: false; outcome: "waiting-human"; why: string } => {
        this.settleMergeIntent(id, generation, "waiting-human", now, { error: why, from: "claimed", bumpGeneration: true });
        return { ok: false as const, outcome: "waiting-human" as const, why };
      };
      if (String(row["head_sha"]) !== proof.headSha) return supersede("the head moved");
      if (proof.liveGrantTermsHash === null || proof.liveGrantTermsHash !== String(row["grant_terms_hash"])) {
        return supersede("the grant was revoked or its merge terms changed since this intent was written");
      }
      const basis = String(row["authority_basis"]);
      const mode = this.activeMode(proof.repo, now);
      if (basis === "mode") {
        let publication: unknown;
        try {
          publication = mode === null ? undefined : (JSON.parse(mode.termsJson) as { publication?: unknown }).publication;
        } catch {
          publication = undefined;
        }
        if (mode === null || mode.digest !== String(row["mode_digest"]) || publication !== "automerge") {
          return fence("the mode this merge was signed under is gone — it waits for you");
        }
      } else if (basis === "grant" && mode !== null) {
        let publication: unknown;
        try {
          publication = (JSON.parse(mode.termsJson) as { publication?: unknown }).publication;
        } catch {
          publication = undefined;
        }
        if (publication !== "automerge") return fence("the active mode says merges wait for you");
      }
      const { changes } = this.db
        .prepare(
          `UPDATE merge_intent SET state = 'firing', firing_at = ?, firing_deadline = ?
            WHERE id = ? AND state = 'claimed' AND generation = ?`,
        )
        .run(now.toISOString(), new Date(now.getTime() + proof.graceMs).toISOString(), id, generation);
      return Number(changes) === 1
        ? { ok: true as const }
        : { ok: false as const, outcome: "raced" as const, why: "the claim moved" };
    });
  }

  /** F1: an OPEN same-head PR under a STALE firing row is never
   * auto-retried — this authenticated recovery ceremony re-arms it
   * through the full firing CAS, generation bumped so the dead owner's
   * late writes lose. Refuses while the deadline has not passed. */
  refireMergeIntent(id: number, by: string, now: Date): { ok: true } | { ok: false; reason: "not-firing" | "not-stale" } {
    void by;
    return this.transact(() => {
      const row = this.db.prepare("SELECT state, firing_deadline FROM merge_intent WHERE id = ?").get(id);
      if (row === undefined || String(row["state"]) !== "firing") return { ok: false as const, reason: "not-firing" as const };
      if (String(row["firing_deadline"]) > now.toISOString()) return { ok: false as const, reason: "not-stale" as const };
      this.db
        .prepare(
          `UPDATE merge_intent SET state = 'pending', authority_basis = 'human', mode_digest = NULL,
                  firing_at = NULL, firing_deadline = NULL, generation = generation + 1, last_error = NULL
            WHERE id = ? AND state = 'firing'`,
        )
        .run(id);
      return { ok: true as const };
    });
  }

  /** Refused intents rearm to pending after the operator fixed the cause. */
  rearmMergeIntent(publication: number): boolean {
    const { changes } = this.db
      .prepare("UPDATE merge_intent SET state = 'pending', last_error = NULL WHERE publication = ? AND state = 'refused'")
      .run(publication);
    return Number(changes) > 0;
  }

  mergeIntentFor(publication: number): { id: number; state: string; headSha: string; generation: number; attempts: number; lastError: string | null; firingDeadline: string | null } | null {
    const row = this.db
      .prepare("SELECT id, state, head_sha, generation, attempts, last_error, firing_deadline FROM merge_intent WHERE publication = ?")
      .get(publication);
    return row === undefined
      ? null
      : {
          id: Number(row["id"]),
          state: String(row["state"]),
          headSha: String(row["head_sha"]),
          generation: Number(row["generation"]),
          attempts: Number(row["attempts"]),
          lastError: row["last_error"] === null ? null : String(row["last_error"]),
          firingDeadline: row["firing_deadline"] === null ? null : String(row["firing_deadline"]),
        };
  }

  latestObservation(githubRepo: string, prNumber: number): { headSha: string; state: string; observedAt: string; generation: number } | null {
    const row = this.db
      .prepare("SELECT head_sha, state, observed_at, generation FROM ci_observation WHERE github_repo = ? AND pr_number = ?")
      .get(githubRepo, prNumber);
    return row === undefined || String(row["observed_at"]) === ""
      ? null
      : { headSha: String(row["head_sha"]), state: String(row["state"]), observedAt: String(row["observed_at"]), generation: Number(row["generation"]) };
  }

  /** Revocation is immediate: intents not yet pushed die with the grant. */
  revokePublicationGrant(repo: string, by: string, now: Date): boolean {
    const { changes } = this.db
      .prepare("UPDATE publication_grant SET revoked_at = ?, revoked_by = ? WHERE repo = ? AND revoked_at IS NULL")
      .run(now.toISOString(), by, repo);
    return Number(changes) > 0;
  }

  publicationGrantFor(repo: string): PublicationGrant | null {
    const row = this.db
      .prepare("SELECT * FROM publication_grant WHERE repo = ? AND revoked_at IS NULL")
      .get(repo);
    return row === undefined ? null : readPublicationGrant(row);
  }

  /** v29: whether the repo has a live grant that authorizes MERGING — the
   * precondition automerge modes require (D1). */
  hasMergeCapableGrant(repo: string, now: Date): boolean {
    void now;
    const grant = this.publicationGrantFor(repo);
    return grant !== null && grant.merge === true;
  }

  /**
   * The intent, written wherever completion was proved — callers run this
   * inside the fenced completion transaction, so "done" and "this must
   * reach a PR" are one write or neither.
   */
  createPublicationIntent(
    intent: {
      run: number;
      taskRef: number;
      githubRepo: string;
      remote: string;
      base: string;
      head: string;
      headSha: string;
      bodyHash: string;
      draft: boolean;
    },
    now: Date,
  ): number {
    const inserted = this.db
      .prepare(
        `INSERT INTO publication
           (run, task_ref, github_repo, remote, base, head, head_sha, body_hash, draft, state, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'intended', ?, ?)`,
      )
      .run(
        intent.run,
        intent.taskRef,
        intent.githubRepo,
        intent.remote,
        intent.base,
        intent.head,
        intent.headSha,
        intent.bodyHash,
        intent.draft ? 1 : 0,
        now.toISOString(),
        now.toISOString(),
      );
    return Number(inserted.lastInsertRowid);
  }

  /** Work the publisher still owes, oldest first — crash-retryable by construction. */
  pendingPublications(): Publication[] {
    return this.db
      .prepare("SELECT * FROM publication WHERE state IN ('intended','pushed') ORDER BY id")
      .all()
      .map(readPublication);
  }

  publicationForRun(run: number): Publication | null {
    const row = this.db.prepare("SELECT * FROM publication WHERE run = ?").get(run);
    return row === undefined ? null : readPublication(row);
  }

  markPublicationPushed(id: number, now: Date): void {
    this.db
      .prepare("UPDATE publication SET state = 'pushed', updated_at = ? WHERE id = ? AND state = 'intended'")
      .run(now.toISOString(), id);
  }

  /** A PR that exists is recorded as opened, even if a concurrent pass gave up on the row meanwhile: it truly opened. */
  markPublicationOpened(id: number, prNumber: number, prUrl: string, now: Date): void {
    this.db
      .prepare(
        "UPDATE publication SET state = 'opened', pr_number = ?, pr_url = ?, updated_at = ? WHERE id = ? AND state IN ('pushed','failed')",
      )
      .run(prNumber, prUrl, now.toISOString(), id);
  }

  /** One more failed attempt, error kept. Returns the new count; the caller decides when enough is enough. */
  recordPublicationError(id: number, error: string, now: Date): number {
    this.db
      .prepare("UPDATE publication SET attempts = attempts + 1, last_error = ?, updated_at = ? WHERE id = ?")
      .run(error.slice(0, 2_000), now.toISOString(), id);
    const row = this.db.prepare("SELECT attempts FROM publication WHERE id = ?").get(id);
    return Number(row?.["attempts"] ?? 0);
  }

  failPublication(id: number, now: Date): void {
    this.db
      .prepare("UPDATE publication SET state = 'failed', updated_at = ? WHERE id = ? AND state IN ('intended','pushed')")
      .run(now.toISOString(), id);
  }

  /** PRs this control plane opened and should keep watching — remotely
   * merged/closed ones have left the watch (audit C-6). */
  openedPublications(): Publication[] {
    return this.db
      .prepare(
        "SELECT * FROM publication WHERE state = 'opened' AND (remote_state IS NULL OR remote_state NOT IN ('MERGED','CLOSED')) ORDER BY id",
      )
      .all()
      .map(readPublication);
  }

  /** Whether an UNRESOLVED CI failure episode is open for exactly this repository's PR (M8.19; audit C-2). */
  hasOpenCiEpisode(githubRepo: string, prNumber: number): boolean {
    return this.latestOpenCiEpisode(githubRepo, prNumber) !== null;
  }

  /** Record what CI was last SEEN doing (audit SD-4). Observation only. */
  recordPublicationCheckState(id: number, state: string, now: Date): void {
    this.db
      .prepare("UPDATE publication SET last_check_state = ?, last_check_at = ? WHERE id = ?")
      .run(state, now.toISOString(), id);
  }

  /** The remote's own verdict on a PR — MERGED/CLOSED ends the watch (audit C-6). */
  recordPublicationRemoteState(id: number, remoteState: string, now: Date): void {
    this.db
      .prepare("UPDATE publication SET remote_state = ?, updated_at = ? WHERE id = ?")
      .run(remoteState, now.toISOString(), id);
  }

  /**
   * Resolve CI episodes for a PR whose failing head is gone — a new commit
   * superseded it, or the same head turned green. Episodes are keyed
   * `ci:<githubRepo>:<pr>:<headOid>` (the repository is part of the
   * identity — Codex M5-M8 audit, C-2); the legacy `ci:<pr>:<head>` shape
   * is swept too, so pre-rename rows cannot linger open forever.
   */
  resolveCiEpisodes(githubRepo: string, prNumber: number, exceptKey: string | null, now: Date): number {
    const { changes } = this.db
      .prepare(
        `UPDATE notification SET resolved_at = ?
          WHERE (dedupe_key LIKE ? ESCAPE '\\' OR dedupe_key LIKE ? ESCAPE '\\') AND resolved_at IS NULL AND dedupe_key != COALESCE(?, '')`,
      )
      .run(now.toISOString(), `${likeEscape(`ci:${githubRepo}:${prNumber}:`)}%`, `${likeEscape(`ci:${prNumber}:`)}%`, exceptKey);
    return Number(changes);
  }

  /**
   * The latest OPEN failing episode for exactly this repository's PR —
   * head and observation time included, because a repair brief binds the
   * head the failure was SEEN on, never the click (audit C-2).
   */
  latestOpenCiEpisode(githubRepo: string, prNumber: number): { headSha: string; createdAt: string } | null {
    const row = this.db
      .prepare(
        "SELECT dedupe_key, created_at FROM notification WHERE dedupe_key LIKE ? ESCAPE '\\' AND resolved_at IS NULL ORDER BY id DESC LIMIT 1",
      )
      .get(`${likeEscape(`ci:${githubRepo}:${prNumber}:`)}%`);
    if (row === undefined) return null;
    const key = String(row["dedupe_key"]);
    const headSha = key.slice(key.lastIndexOf(":") + 1);
    return { headSha, createdAt: String(row["created_at"]) };
  }

  /** What is being built right now: current, unexpired claims with their task and holder. */
  liveClaims(repo: string | null, now: Date): { taskId: string; runner: string; claimedAt: string; expiresAt: string; model: string | null; repo: string | null }[] {
    return this.db
      .prepare(
        `SELECT task_ref.external_id AS task_id, task_ref.repo AS repo, claim.runner, claim.acquired_at, claim.expires_at,
                (SELECT run.model FROM run WHERE run.lease_id = claim.lease_id LIMIT 1) AS model
         FROM claim JOIN task_ref ON task_ref.id = claim.task_ref
         WHERE claim.released_at IS NULL AND claim.expires_at > ?
           AND claim.lease_generation = (
             SELECT MAX(newest.lease_generation) FROM claim AS newest
             WHERE newest.task_ref = claim.task_ref
           )
           AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
         ORDER BY claim.acquired_at`,
      )
      .all(now.toISOString(), repo, repo)
      .map(row => ({
        taskId: String(row["task_id"]),
        runner: String(row["runner"]),
        claimedAt: String(row["acquired_at"]),
        expiresAt: String(row["expires_at"]),
        model: row["model"] === null || row["model"] === undefined ? null : String(row["model"]),
        repo: row["repo"] === null ? null : String(row["repo"]),
      }));
  }

  // ---- the mate (v32) --------------------------------------------------------

  /** Delegated chat spend, signed once: the row every mate turn debits. */
  mintMateSession(
    args: { approver: string; approverGeneration: number; credentialKey: string; ceilingMicrousd: number; ceilingDigest: string; termsDigest: string },
    now: Date,
  ): number {
    return this.transact(() => {
      // One live session per approver: minting ends the previous one and
      // fences any turn still in flight under it (slice-2 review, finding 7).
      this.failLiveMateTurnsFor(args.approver, "superseded", now, true);
      this.db
        .prepare("UPDATE mate_session SET ended_at = ?, ended_by = ? WHERE approver = ? AND ended_at IS NULL AND NOT EXISTS (SELECT 1 FROM team_mate_session tm WHERE tm.session=mate_session.id)")
        .run(now.toISOString(), args.approver, args.approver);
      const inserted = this.db
        .prepare(
          `INSERT INTO mate_session (approver, approver_generation, credential_key, ceiling_microusd, ceiling_digest, terms_digest, minted_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(args.approver, args.approverGeneration, args.credentialKey, args.ceilingMicrousd, args.ceilingDigest, args.termsDigest, now.toISOString());
      return Number(inserted.lastInsertRowid);
    });
  }

  /** Team sessions are independently signed, actor-owned spending grants for one conversation. */
  mintTeamMateSession(args: { approver: string; approverGeneration: number; credentialKey: string; ceilingMicrousd: number; ceilingDigest: string; termsDigest: string; thread: number }, now: Date): number {
    return this.transact(() => {
      if (!this.teamMateThreadAllows(args.thread, args.approver, args.approverGeneration)) throw new Error("Current conversation contribution access is required.");
      const existing = this.teamMateSession(args.approver, args.thread);
      if (existing !== null) {
        if (this.db.prepare("SELECT 1 FROM mate_turn WHERE session=? AND state IN ('queued','running')").get(existing.id)) throw new Error("Stop the active conversation turn before renewing its session.");
        this.endMateSession(existing.id, args.approver, now);
      }
      const row = this.db.prepare("INSERT INTO mate_session(approver,approver_generation,credential_key,ceiling_microusd,ceiling_digest,terms_digest,minted_at) VALUES(?,?,?,?,?,?,?)")
        .run(args.approver,args.approverGeneration,args.credentialKey,args.ceilingMicrousd,args.ceilingDigest,args.termsDigest,now.toISOString());
      const id = Number(row.lastInsertRowid);
      this.db.prepare("INSERT INTO team_mate_session(session,thread) VALUES(?,?)").run(id,args.thread);
      return id;
    });
  }

  teamMateSession(approver: string, thread: number): MateSession | null {
    const row = this.db.prepare("SELECT ms.* FROM mate_session ms JOIN team_mate_session tm ON tm.session=ms.id WHERE ms.approver=? AND tm.thread=? AND ms.ended_at IS NULL ORDER BY ms.id DESC LIMIT 1").get(approver,thread);
    return row === undefined ? null : readMateSession(row);
  }

  openTeamMateThread(approver: string, ceilingDigest: string, now: Date): MateThread {
    const result = this.db.prepare("INSERT INTO mate_thread(approver,ceiling_digest,opened_at) VALUES(?,?,?)").run(approver,ceilingDigest,now.toISOString());
    return this.getMateThread(Number(result.lastInsertRowid))!;
  }

  canUseTeamMateThread(approver: string, generation: number, thread: number): boolean { return this.teamMateThreadAllows(thread, approver, generation); }

  /** Rechecked at admission; membership never grants project or approval standing. */
  teamMateThreadAllows(thread: number, approver: string, generation: number): boolean {
    const account = this.accountOf(approver);
    if (account === null || account.revokedAt !== null || account.generation !== generation || account.role !== "approver") return false;
    const row = this.db.prepare(`SELECT tc.projects_json FROM team_conversation tc
      JOIN team_lead tl ON tl.id=tc.lead AND tl.status='active'
      JOIN team_lead_member lm ON lm.lead=tc.lead AND lm.account=? AND lm.active=1 AND lm.role IN ('contributor','manager')
      JOIN team_participant tp ON tp.conversation=tc.id AND tp.account=lm.account AND tp.active=1 AND tp.role IN ('contributor','manager')
      WHERE tc.thread=? AND (tc.visibility='team' OR tc.created_by=?)`).get(approver,thread,approver);
    if (row === undefined) return false;
    const projects = readProjectAccess(row["projects_json"]);
    return projects !== null && projects.length > 0 && projects.every(repo => projectAccessAllows(account.projects,repo) && this.db.prepare("SELECT 1 FROM team_lead_project lp JOIN team_conversation tc ON tc.lead=lp.lead WHERE tc.thread=? AND lp.project=?").get(thread,repo) !== undefined);
  }

  /** The live session — explicitly ended or still active. Exhaustion is the caller's arithmetic. */
  activeMateSession(approver: string): MateSession | null {
    const row = this.db
      .prepare("SELECT * FROM mate_session WHERE approver = ? AND ended_at IS NULL AND NOT EXISTS (SELECT 1 FROM team_mate_session tm WHERE tm.session=mate_session.id) ORDER BY id DESC LIMIT 1")
      .get(approver);
    return row === undefined ? null : readMateSession(row);
  }

  getMateSession(id: number): MateSession | null {
    const row = this.db.prepare("SELECT * FROM mate_session WHERE id = ?").get(id);
    return row === undefined ? null : readMateSession(row);
  }

  endMateSession(id: number, by: string, now: Date): boolean {
    const changed = this.db
      .prepare("UPDATE mate_session SET ended_at = ?, ended_by = ? WHERE id = ? AND ended_at IS NULL")
      .run(now.toISOString(), by, id);
    return Number(changed.changes) === 1;
  }

  /** Revocation's companion (ruling 10): an approver's standing ends every session it minted. */
  endMateSessionsFor(approver: string, by: string, now: Date): number {
    const changed = this.db
      .prepare("UPDATE mate_session SET ended_at = ?, ended_by = ? WHERE approver = ? AND ended_at IS NULL")
      .run(now.toISOString(), by, approver);
    return Number(changed.changes);
  }

  /** The live thread for this approver and scope under THIS ceiling; a
   * thread under another ceiling is closed first (ruling 9) — the surface
   * says why. The lead conversation is the default scope. */
  openMateThread(approver: string, ceilingDigest: string, now: Date, scope: MateThreadScope = LEAD_THREAD): { thread: MateThread; ceilingChanged: boolean } {
    const key = scope.kind === "lead" ? null : scope.key;
    return this.transact(() => {
      const live = this.db.prepare("SELECT * FROM mate_thread WHERE approver = ? AND scope_kind = ? AND scope_key IS ? AND closed_at IS NULL AND NOT EXISTS (SELECT 1 FROM team_conversation tc WHERE tc.thread=mate_thread.id) ORDER BY id DESC LIMIT 1").get(approver, scope.kind, key);
      let ceilingChanged = false;
      if (live !== undefined && String(live["ceiling_digest"]) !== ceilingDigest) {
        this.db.prepare("UPDATE mate_thread SET closed_at = ? WHERE id = ?").run(now.toISOString(), Number(live["id"]));
        this.db
          .prepare("UPDATE mate_proposal SET state = 'expired', resolved_at = ? WHERE thread = ? AND state IN ('drafting','pending')")
          .run(now.toISOString(), Number(live["id"]));
        ceilingChanged = true;
      } else if (live !== undefined) {
        return { thread: readMateThread(live), ceilingChanged: false };
      }
      const inserted = this.db
        .prepare("INSERT INTO mate_thread (approver, ceiling_digest, opened_at, scope_kind, scope_key) VALUES (?, ?, ?, ?, ?)")
        .run(approver, ceilingDigest, now.toISOString(), scope.kind, key);
      const row = this.db.prepare("SELECT * FROM mate_thread WHERE id = ?").get(Number(inserted.lastInsertRowid));
      return { thread: readMateThread(row as Record<string, unknown>), ceilingChanged };
    });
  }

  /** The approver's live thread for one scope, read only — null when none is open. */
  liveMateThreadFor(approver: string, scope: MateThreadScope = LEAD_THREAD): MateThread | null {
    const row = this.db.prepare("SELECT * FROM mate_thread WHERE approver = ? AND scope_kind = ? AND scope_key IS ? AND closed_at IS NULL AND NOT EXISTS (SELECT 1 FROM team_conversation tc WHERE tc.thread=mate_thread.id) ORDER BY id DESC LIMIT 1").get(approver, scope.kind, scope.kind === "lead" ? null : scope.key);
    return row === undefined ? null : readMateThread(row);
  }

  /** The task a paired chat is talking about (v78), or null for the lead conversation. */
  chatFocus(surface: string, binding: number): string | null {
    const row = this.db.prepare("SELECT task FROM chat_focus WHERE surface = ? AND binding = ?").get(surface, binding);
    return row === undefined ? null : String(row["task"]);
  }

  setChatFocus(surface: string, binding: number, task: string | null, now: Date): void {
    if (task === null) this.db.prepare("DELETE FROM chat_focus WHERE surface = ? AND binding = ?").run(surface, binding);
    else this.db.prepare("INSERT INTO chat_focus (surface, binding, task, updated_at) VALUES (?, ?, ?, ?) ON CONFLICT (surface, binding) DO UPDATE SET task = excluded.task, updated_at = excluded.updated_at").run(surface, binding, task, now.toISOString());
  }

  // ---- flows (v81) -------------------------------------------------------------

  createFlow(flow: { repo: string; name: string; definitionJson: string; by: string }, now: Date): number {
    const stamp = now.toISOString();
    return Number(this.db.prepare("INSERT INTO flow (repo, name, definition_json, revision, state, created_by, created_at, updated_by, updated_at) VALUES (?, ?, ?, 1, 'active', ?, ?, ?, ?)")
      .run(flow.repo, flow.name, flowDefinitionForStore(flow.definitionJson), flow.by, stamp, flow.by, stamp).lastInsertRowid);
  }

  /** Hand a flow to another person: its "the owner decides" zones ask them from now on. */
  setFlowOwner(id: number, owner: string, now: Date): void {
    this.db.prepare("UPDATE flow SET owner = ?, updated_at = ? WHERE id = ?").run(owner, now.toISOString(), id);
  }

  getFlow(id: number): FlowRow | null {
    const row = this.db.prepare("SELECT * FROM flow WHERE id = ?").get(id);
    return row === undefined ? null : readFlowRow(row);
  }

  listFlows(repos: readonly string[]): FlowRow[] {
    if (repos.length === 0) return [];
    return this.db.prepare(`SELECT * FROM flow WHERE state = 'active' AND repo IN (${repos.map(() => "?").join(",")}) ORDER BY updated_at DESC, id DESC`).all(...repos).map(readFlowRow);
  }

  /** Save a new drawing of the flow only over the revision the editor saw (two editors never overwrite each other silently). */
  saveFlow(id: number, change: { name: string; definitionJson: string; sawRevision: number; by: string }, now: Date): boolean {
    const { changes } = this.db.prepare("UPDATE flow SET name = ?, definition_json = ?, revision = revision + 1, updated_by = ?, updated_at = ? WHERE id = ? AND revision = ? AND state = 'active'")
      .run(change.name, flowDefinitionForStore(change.definitionJson), change.by, now.toISOString(), id, change.sawRevision);
    return Number(changes) === 1;
  }

  archiveFlow(id: number, by: string, now: Date): boolean {
    const { changes } = this.db.prepare("UPDATE flow SET state = 'archived', updated_by = ?, updated_at = ? WHERE id = ? AND state = 'active'").run(by, now.toISOString(), id);
    return Number(changes) === 1;
  }

  addFlowCard(card: { flow: number; title: string; description: string | null; stage: string; by: string; source?: FlowCardSource }, now: Date): number {
    return this.transact(() => {
      const stamp = now.toISOString();
      const id = Number(this.db.prepare("INSERT INTO flow_card (flow, title, description, stage, state, created_by, created_at, updated_at, source_json) VALUES (?, ?, ?, ?, 'active', ?, ?, ?, ?)")
        .run(card.flow, card.title, card.description, card.stage, card.by, stamp, stamp, card.source === undefined ? null : JSON.stringify(card.source)).lastInsertRowid);
      this.db.prepare("INSERT INTO flow_event (card, from_stage, to_stage, outcome, actor, note, at) VALUES (?, NULL, ?, 'created', ?, NULL, ?)").run(id, card.stage, card.by, stamp);
      return id;
    });
  }

  getFlowCard(id: number): FlowCardRow | null {
    const row = this.db.prepare("SELECT * FROM flow_card WHERE id = ?").get(id);
    return row === undefined ? null : readFlowCardRow(row);
  }

  flowCards(flow: number, includeFinished: boolean): FlowCardRow[] {
    return this.db.prepare(`SELECT * FROM flow_card WHERE flow = ? ${includeFinished ? "" : "AND state = 'active'"} ORDER BY updated_at DESC, id DESC LIMIT 500`).all(flow).map(readFlowCardRow);
  }

  /** Every active card of every active flow in one project: what a worker's pass advances. */
  /** The card whose zone filed this task (the newest, should one task have been filed for two). */
  flowCardByTask(task: string): FlowCardRow | null {
    const row = this.db.prepare("SELECT * FROM flow_card WHERE task = ? ORDER BY id DESC LIMIT 1").get(task);
    return row === undefined ? null : readFlowCardRow(row as Record<string, unknown>);
  }

  activeFlowCards(repo: string): FlowCardRow[] {
    return this.db.prepare("SELECT c.* FROM flow_card c JOIN flow f ON f.id = c.flow WHERE f.repo = ? AND f.state = 'active' AND c.state = 'active' ORDER BY c.id").all(repo).map(readFlowCardRow);
  }

  /** Move a card to a zone (a fresh entry: its step runs again), with the history line. `expectEntry` makes a stale move a no-op. */
  moveFlowCard(id: number, move: { to: string; outcome: FlowEventOutcome; actor: string; note?: string | null; task?: string | null; expectEntry?: number;
    /** v91: said in the card's history only; the card's note ({{note}}) is left as it is. */
    historyNote?: string }, now: Date): boolean {
    return this.transact(() => {
      const card = this.getFlowCard(id);
      if (card === null || card.state !== "active" || (move.expectEntry !== undefined && card.entry !== move.expectEntry)) return false;
      const stamp = now.toISOString();
      this.db.prepare("UPDATE flow_card SET stage = ?, entry = entry + 1, task = ?, waiting = NULL, note = COALESCE(?, note), updated_at = ? WHERE id = ?")
        .run(move.to, move.task ?? null, move.note ?? null, stamp, id);
      this.db.prepare("INSERT INTO flow_event (card, from_stage, to_stage, outcome, actor, note, at) VALUES (?, ?, ?, ?, ?, ?, ?)").run(id, card.stage, move.to, move.outcome, move.actor, move.historyNote ?? move.note ?? null, stamp);
      return true;
    });
  }

  /** What a card's current zone is doing: its task, the card's main work, what it waits on, what zones reported. */
  /** Read and written in one transaction, so a pass changing one field never writes back another pass's older task or waiting. */
  updateFlowCard(id: number, change: { task?: string | null; primaryTask?: string; waiting?: string | null; outputs?: Record<string, string>; state?: "done" | "cancelled" }, now: Date): void {
    this.transact(() => {
      const card = this.getFlowCard(id);
      if (card === null) return;
      this.db.prepare("UPDATE flow_card SET task = ?, primary_task = ?, waiting = ?, outputs_json = ?, state = ?, updated_at = ? WHERE id = ?").run(
        change.task === undefined ? card.task : change.task,
        change.primaryTask ?? card.primaryTask,
        change.waiting === undefined ? card.waiting : change.waiting,
        JSON.stringify(change.outputs ?? card.outputs),
        change.state ?? card.state,
        now.toISOString(), id,
      );
    });
  }

  flowEvents(card: number): { fromStage: string | null; toStage: string; outcome: FlowEventOutcome; actor: string; note: string | null; at: string }[] {
    return this.db.prepare("SELECT * FROM flow_event WHERE card = ? ORDER BY id").all(card).map(row => ({
      fromStage: row["from_stage"] === null ? null : String(row["from_stage"]), toStage: String(row["to_stage"]), outcome: String(row["outcome"]) as FlowEventOutcome,
      actor: String(row["actor"]), note: row["note"] === null ? null : String(row["note"]), at: String(row["at"]),
    }));
  }

  /** When a card came into the zone it is in: its latest history line (it is written with every move). */
  flowCardEnteredAt(card: number): string | null {
    const row = this.db.prepare("SELECT at FROM flow_event WHERE card = ? ORDER BY id DESC LIMIT 1").get(card);
    return row === undefined ? null : String(row["at"]);
  }

  /** v91: one email of a card's conversation. A Message-ID is kept once: false when it was already. */
  recordFlowMail(mail: { messageId: string; card: number; direction: "sent" | "received"; address: string }, now: Date): boolean {
    const { changes } = this.db.prepare("INSERT OR IGNORE INTO flow_mail (message_id, card, direction, address, at) VALUES (?, ?, ?, ?, ?)")
      .run(mail.messageId, mail.card, mail.direction, mail.address.toLowerCase(), now.toISOString());
    return Number(changes) === 1;
  }

  /** A card's conversation, oldest first. */
  flowMailOf(card: number): { messageId: string; direction: "sent" | "received"; address: string; at: string }[] {
    return this.db.prepare("SELECT * FROM flow_mail WHERE card = ? ORDER BY at, rowid").all(card).map(row => ({
      messageId: String(row["message_id"]), direction: String(row["direction"]) as "sent" | "received", address: String(row["address"]), at: String(row["at"]) }));
  }

  /** The emails of any card's conversation among these Message-IDs: what a reply names in In-Reply-To and References. */
  flowMailAmong(ids: readonly string[]): { messageId: string; card: number; direction: "sent" | "received"; address: string }[] {
    if (ids.length === 0) return [];
    return this.db.prepare(`SELECT * FROM flow_mail WHERE message_id IN (${ids.map(() => "?").join(", ")}) ORDER BY at DESC, rowid DESC`).all(...ids).map(row => ({
      messageId: String(row["message_id"]), card: Number(row["card"]), direction: String(row["direction"]) as "sent" | "received", address: String(row["address"]) }));
  }

  /** Whether any card still active is in an email conversation: only then is the mailbox read for replies. */
  flowConversationsOpen(): boolean {
    return this.db.prepare("SELECT 1 AS hit FROM flow_mail m JOIN flow_card c ON c.id = m.card WHERE c.state = 'active' AND m.direction = 'sent' LIMIT 1").get() !== undefined;
  }

  /** v91: where the reply watcher stands in the mailbox. */
  flowMailWatch(): { cursor: string | null; nextAt: string | null; failures: number; lastOutcome: string | null } {
    const row = this.db.prepare("SELECT * FROM flow_mail_watch WHERE id = 1").get();
    return row === undefined ? { cursor: null, nextAt: null, failures: 0, lastOutcome: null }
      : { cursor: row["cursor"] === null ? null : String(row["cursor"]), nextAt: row["next_at"] === null ? null : String(row["next_at"]), failures: Number(row["failures"]), lastOutcome: row["last_outcome"] === null ? null : String(row["last_outcome"]) };
  }

  setFlowMailWatch(change: { cursor: string | null; nextAt: string; failures: number; lastOutcome: string | null }, now: Date): void {
    this.db.prepare(`INSERT INTO flow_mail_watch (id, cursor, next_at, failures, last_outcome, updated_at) VALUES (1, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET cursor = excluded.cursor, next_at = excluded.next_at, failures = excluded.failures, last_outcome = excluded.last_outcome, updated_at = excluded.updated_at`)
      .run(change.cursor, change.nextAt, change.failures, change.lastOutcome, now.toISOString());
  }

  // ---- v92: AI teammates ---------------------------------------------------------------

  createTeammate(mate: { repo: string; handle: string; soul: string; model: string | null; manager: string; by: string }, now: Date): number {
    return this.transact(() => {
      const stamp = now.toISOString();
      const id = Number(this.db.prepare("INSERT INTO teammate (repo, handle, state, version, soul, model, manager, created_by, created_at, updated_by, updated_at) VALUES (?, ?, 'active', 1, ?, ?, ?, ?, ?, ?, ?)")
        .run(mate.repo, mate.handle, mate.soul, mate.model, mate.manager, mate.by, stamp, mate.by, stamp).lastInsertRowid);
      this.db.prepare("INSERT INTO teammate_version (teammate, version, soul, saved_by, saved_at) VALUES (?, 1, ?, ?, ?)").run(id, mate.soul, mate.by, stamp);
      return id;
    });
  }

  getTeammate(id: number): TeammateRow | null {
    const row = this.db.prepare("SELECT * FROM teammate WHERE id = ?").get(id);
    return row === undefined ? null : readTeammateRow(row);
  }

  /** The teammate a zone names in a project (paused ones too; never a removed one). */
  teammateByHandle(repo: string, handle: string): TeammateRow | null {
    const row = this.db.prepare("SELECT * FROM teammate WHERE repo = ? AND handle = ? AND state <> 'removed'").get(repo, handle);
    return row === undefined ? null : readTeammateRow(row);
  }

  teammates(repos: readonly string[]): TeammateRow[] {
    if (repos.length === 0) return [];
    return this.db.prepare(`SELECT * FROM teammate WHERE state <> 'removed' AND repo IN (${repos.map(() => "?").join(", ")}) ORDER BY handle`).all(...repos).map(readTeammateRow);
  }

  /** A new version of a teammate's soul file; false when nothing changed. */
  saveTeammateSoul(id: number, soul: string, by: string, now: Date): boolean {
    return this.transact(() => {
      const mate = this.getTeammate(id);
      if (mate === null || mate.soul === soul) return false;
      const stamp = now.toISOString();
      this.db.prepare("UPDATE teammate SET soul = ?, version = version + 1, updated_by = ?, updated_at = ? WHERE id = ?").run(soul, by, stamp, id);
      this.db.prepare("INSERT INTO teammate_version (teammate, version, soul, saved_by, saved_at) VALUES (?, ?, ?, ?, ?)").run(id, mate.version + 1, soul, by, stamp);
      return true;
    });
  }

  teammateVersions(id: number): { version: number; soul: string; savedBy: string; savedAt: string }[] {
    return this.db.prepare("SELECT * FROM teammate_version WHERE teammate = ? ORDER BY version DESC LIMIT 50").all(id).map(row => ({ version: Number(row["version"]), soul: String(row["soul"]), savedBy: String(row["saved_by"]), savedAt: String(row["saved_at"]) }));
  }

  updateTeammate(id: number, change: { state?: TeammateRow["state"]; model?: string | null; dailyTurns?: number; manager?: string; summaryAt?: string; weeklyAt?: string }, by: string, now: Date): void {
    const mate = this.getTeammate(id);
    if (mate === null) return;
    this.db.prepare("UPDATE teammate SET state = ?, model = ?, daily_turns = ?, manager = ?, summary_at = ?, weekly_at = ?, updated_by = ?, updated_at = ? WHERE id = ?").run(
      change.state ?? mate.state, change.model === undefined ? mate.model : change.model, change.dailyTurns ?? mate.dailyTurns, change.manager ?? mate.manager,
      change.summaryAt ?? mate.summaryAt, change.weeklyAt ?? mate.weeklyAt, by, now.toISOString(), id);
  }

  addTeammateEvent(event: { teammate: number; card?: number | null; entry?: number | null; kind: TeammateEventKind; said: string; detail?: Record<string, unknown> | null; by?: string | null }, now: Date): number {
    return Number(this.db.prepare("INSERT INTO teammate_event (teammate, card, entry, kind, said, detail_json, by, at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
      .run(event.teammate, event.card ?? null, event.entry ?? null, event.kind, event.said, event.detail === undefined || event.detail === null ? null : JSON.stringify(event.detail), event.by ?? null, now.toISOString()).lastInsertRowid);
  }

  /** A teammate's log, newest first; `since` bounds it (a day's summary). */
  teammateEvents(teammate: number, limit: number, since: string | null = null): TeammateEventRow[] {
    return this.db.prepare(`SELECT * FROM teammate_event WHERE teammate = ? ${since === null ? "" : "AND at >= ?"} ORDER BY id DESC LIMIT ?`).all(...(since === null ? [teammate, limit] : [teammate, since, limit])).map(row => ({
      id: Number(row["id"]), teammate: Number(row["teammate"]), card: row["card"] === null ? null : Number(row["card"]), entry: row["entry"] === null ? null : Number(row["entry"]),
      kind: String(row["kind"]) as TeammateEventKind, said: String(row["said"]), detail: row["detail_json"] === null ? null : JSON.parse(String(row["detail_json"])) as Record<string, unknown>,
      by: row["by"] === null ? null : String(row["by"]), at: String(row["at"]) }));
  }

  /** How many turns (decisions, handled cards, hand-offs, questions, failures, and v94 tool calls) a teammate took since a time: its daily limit. */
  teammateTurnsSince(teammate: number, since: string): number {
    return Number(this.db.prepare("SELECT COUNT(*) AS n FROM teammate_event WHERE teammate = ? AND at >= ? AND kind IN ('decided','handled','handed','asked','failed')").get(teammate, since)?.["n"] ?? 0)
      + Number(this.db.prepare("SELECT COUNT(*) AS n FROM teammate_call WHERE teammate = ? AND created_at >= ?").get(teammate, since)?.["n"] ?? 0);
  }

  /** Ask a person about one visit of a card (v94: or to approve one tool call); null when that visit, or that call, already has its question. */
  openTeammateQuestion(question: { teammate: number; card: number; entry: number; question: string; options: { id: string; label: string }[]; askedOf: string; toolCall?: number; suggestion?: number }, now: Date): number | null {
    const { changes, lastInsertRowid } = this.db.prepare("INSERT OR IGNORE INTO teammate_question (teammate, card, entry, question, options_json, asked_of, state, created_at, tool_call, suggestion) VALUES (?, ?, ?, ?, ?, ?, 'open', ?, ?, ?)")
      .run(question.teammate, question.card, question.entry, question.question, JSON.stringify(question.options), question.askedOf, now.toISOString(), question.toolCall ?? null, question.suggestion ?? null);
    return Number(changes) === 1 ? Number(lastInsertRowid) : null;
  }

  /** v94: the first question still open on one visit of a card: its own, or a tool call's approval. */
  openTeammateQuestionOn(card: number, entry: number): TeammateQuestionRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_question WHERE card = ? AND entry = ? AND state = 'open' AND suggestion IS NULL ORDER BY id LIMIT 1").get(card, entry);
    return row === undefined ? null : readTeammateQuestion(row);
  }

  /** v94: the approval question of one tool call. */
  teammateQuestionForCall(call: number): TeammateQuestionRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_question WHERE tool_call = ?").get(call);
    return row === undefined ? null : readTeammateQuestion(row);
  }

  /** v96: the flow a teammate's desk is. */
  setTeammateDesk(id: number, flow: number): void {
    this.db.prepare("UPDATE teammate SET desk_flow = ? WHERE id = ?").run(flow, id);
  }

  // ---- v95: what a teammate remembers, and the rule changes it suggests ----------------

  addTeammateMemory(memory: { teammate: number; text: string; source: TeammateMemoryRow["source"]; card?: number | null; by: string }, now: Date): number {
    const stamp = now.toISOString();
    return Number(this.db.prepare("INSERT INTO teammate_memory (teammate, text, source, card, state, created_by, created_at, updated_by, updated_at) VALUES (?, ?, ?, ?, 'active', ?, ?, ?, ?)")
      .run(memory.teammate, memory.text, memory.source, memory.card ?? null, memory.by, stamp, memory.by, stamp).lastInsertRowid);
  }

  teammateMemory(id: number): TeammateMemoryRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_memory WHERE id = ? AND state = 'active'").get(id);
    return row === undefined ? null : readTeammateMemory(row);
  }

  /** What a teammate remembers now, newest first: one source, and every word of `words` (any case), when given. */
  teammateMemories(teammate: number, options: { source?: TeammateMemoryRow["source"]; words?: readonly string[]; limit?: number } = {}): TeammateMemoryRow[] {
    const words = (options.words ?? []).filter(one => one !== "").slice(0, 8);
    return this.db.prepare(`SELECT * FROM teammate_memory WHERE teammate = ? AND state = 'active' ${options.source === undefined ? "" : "AND source = ?"} ${words.map(() => "AND instr(lower(text), ?) > 0").join(" ")} ORDER BY id DESC LIMIT ?`)
      .all(teammate, ...(options.source === undefined ? [] : [options.source]), ...words.map(one => one.toLowerCase()), options.limit ?? 500).map(readTeammateMemory);
  }

  editTeammateMemory(id: number, text: string, by: string, now: Date): boolean {
    return Number(this.db.prepare("UPDATE teammate_memory SET text = ?, updated_by = ?, updated_at = ? WHERE id = ? AND state = 'active'").run(text, by, now.toISOString(), id).changes) === 1;
  }

  forgetTeammateMemory(id: number, by: string, now: Date): boolean {
    return Number(this.db.prepare("UPDATE teammate_memory SET state = 'forgotten', updated_by = ?, updated_at = ? WHERE id = ? AND state = 'active'").run(by, now.toISOString(), id).changes) === 1;
  }

  markTeammateMemoriesUsed(ids: readonly number[], now: Date): void {
    if (ids.length === 0) return;
    this.db.prepare(`UPDATE teammate_memory SET used_at = ? WHERE id IN (${ids.map(() => "?").join(", ")})`).run(now.toISOString(), ...ids);
  }

  addTeammateSuggestion(suggestion: { teammate: number; tool: string; action: string; rule: ToolRule; was: ToolRule; evidence: number[]; said: string }, now: Date): number {
    return Number(this.db.prepare("INSERT INTO teammate_suggestion (teammate, tool, action, rule_json, was_json, evidence_json, said, state, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, 'open', ?)")
      .run(suggestion.teammate, suggestion.tool, suggestion.action, JSON.stringify(suggestion.rule), JSON.stringify(suggestion.was), JSON.stringify(suggestion.evidence), suggestion.said, now.toISOString()).lastInsertRowid);
  }

  teammateSuggestion(id: number): TeammateSuggestionRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_suggestion WHERE id = ?").get(id);
    return row === undefined ? null : readTeammateSuggestion(row);
  }

  /** A teammate's suggestions about one action, newest first. */
  teammateSuggestionsFor(teammate: number, tool: string, action: string): TeammateSuggestionRow[] {
    return this.db.prepare("SELECT * FROM teammate_suggestion WHERE teammate = ? AND tool = ? AND action = ? ORDER BY id DESC LIMIT 20").all(teammate, tool, action).map(readTeammateSuggestion);
  }

  teammateSuggestions(teammate: number, limit = 20): TeammateSuggestionRow[] {
    return this.db.prepare("SELECT * FROM teammate_suggestion WHERE teammate = ? ORDER BY id DESC LIMIT ?").all(teammate, limit).map(readTeammateSuggestion);
  }

  /** Decide a suggestion, once: false when it was already decided. */
  decideTeammateSuggestion(id: number, state: "accepted" | "dismissed" | "stale", by: string | null, now: Date): boolean {
    return Number(this.db.prepare("UPDATE teammate_suggestion SET state = ?, decided_by = ?, decided_at = ? WHERE id = ? AND state = 'open'").run(state, by, now.toISOString(), id).changes) === 1;
  }

  /** v95: the question that offers a suggestion to its manager. */
  teammateQuestionForSuggestion(suggestion: number): TeammateQuestionRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_question WHERE suggestion = ?").get(suggestion);
    return row === undefined ? null : readTeammateQuestion(row);
  }

  // ---- v94: the tools a teammate may use, and its receipts ------------------------------

  teammateGrants(teammate: number): TeammateGrantRow[] {
    return this.db.prepare("SELECT * FROM teammate_tool WHERE teammate = ? ORDER BY tool").all(teammate).map(readTeammateGrant);
  }

  teammateGrant(teammate: number, tool: string): TeammateGrantRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_tool WHERE teammate = ? AND tool = ?").get(teammate, tool);
    return row === undefined ? null : readTeammateGrant(row);
  }

  /** Grant a tool, or change what it offers and the rules: the whole row is written. `listedAt` undefined keeps it. */
  saveTeammateGrant(grant: { teammate: number; tool: string; actions: ToolActionInfo[]; rules: Record<string, ToolRule>; listedAt?: string | null }, by: string, now: Date): void {
    // v99: what the teammate may now do with the tool, action by action.
    const was = this.teammateGrant(grant.teammate, grant.tool);
    const mate = this.getTeammate(grant.teammate);
    const words = (rule: ToolRule | undefined) => rule === undefined ? "not offered" : rule.use === "never" ? "never" : rule.use === "ask" ? "ask first"
      : rule.limit === undefined ? "do it" : `do it up to ${rule.limit.over} (${rule.limit.field})`;
    const changes = [...new Set([...Object.keys(was?.rules ?? {}), ...Object.keys(grant.rules)])]
      .filter(action => words(was?.rules[action]) !== words(grant.rules[action]))
      .map(action => `${action}: ${words(was?.rules[action])} → ${words(grant.rules[action])}`);
    if (was === null || changes.length > 0) {
      this.recordAction({ at: now.toISOString(), actor: by, repo: mate?.repo ?? null, taskId: null, runId: null, source: "policy",
        action: `${was === null ? "tool given" : "tool rules changed"}: ${mate?.handle ?? `teammate ${grant.teammate}`} · ${grant.tool}`, outcome: was === null ? "granted" : "changed",
        detail: was === null ? Object.entries(grant.rules).map(([action, rule]) => `${action}: ${words(rule)}`).join("; ") : changes.join("; ") });
    }
    this.db.prepare(`INSERT INTO teammate_tool (teammate, tool, actions_json, rules_json, listed_at, updated_by, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(teammate, tool) DO UPDATE SET actions_json = excluded.actions_json, rules_json = excluded.rules_json, listed_at = ${grant.listedAt === undefined ? "teammate_tool.listed_at" : "excluded.listed_at"}, updated_by = excluded.updated_by, updated_at = excluded.updated_at`)
      .run(grant.teammate, grant.tool, JSON.stringify(grant.actions), JSON.stringify(grant.rules), grant.listedAt ?? null, by, now.toISOString());
  }

  dropTeammateGrant(teammate: number, tool: string, by: string, now: Date): boolean {
    const dropped = Number(this.db.prepare("DELETE FROM teammate_tool WHERE teammate = ? AND tool = ?").run(teammate, tool).changes) === 1;
    const mate = this.getTeammate(teammate);
    if (dropped) this.recordAction({ at: now.toISOString(), actor: by, repo: mate?.repo ?? null, taskId: null, runId: null, source: "policy",
      action: `tool taken away: ${mate?.handle ?? `teammate ${teammate}`} · ${tool}`, outcome: "removed" });
    return dropped;
  }

  addTeammateCall(call: { teammate: number; card: number; entry: number; tool: string; action: string; input: Record<string, unknown>; rule: ToolRule["use"]; why: string; state: TeammateCallState; result?: string | null; undoOf?: number; decidedBy?: string }, now: Date): number {
    return this.transact(() => {
      const id = Number(this.db.prepare("INSERT INTO teammate_call (teammate, card, entry, tool, action, input_json, rule, why, state, result, created_at, done_at, undo_of, decided_by, decided_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
        .run(call.teammate, call.card, call.entry, call.tool, call.action, JSON.stringify(call.input), call.rule, call.why, call.state, call.result ?? null, now.toISOString(),
          call.state === "refused" ? now.toISOString() : null, call.undoOf ?? null, call.decidedBy ?? null, call.decidedBy === undefined ? null : now.toISOString()).lastInsertRowid);
      this.recordTeammateCall(id, call.decidedBy ?? null, "", call.state, `rule: ${call.rule}${call.undoOf === undefined ? "" : ` · undoes call ${call.undoOf}`}`, now);
      return id;
    });
  }

  /** v103: a teammate's tool call in the ledger, as the teammate (or the person who decided it), on its card's task. */
  private recordTeammateCall(id: number, person: string | null, verb: string, outcome: string, detail: string | null, now: Date): void {
    const row = this.db.prepare(`SELECT c.tool, c.action, m.handle, m.repo, f.task FROM teammate_call c LEFT JOIN teammate m ON m.id = c.teammate LEFT JOIN flow_card f ON f.id = c.card WHERE c.id = ?`).get(id);
    if (row === undefined) return;
    this.recordAction({ at: now.toISOString(), actor: person ?? `${row["handle"] == null ? "teammate" : String(row["handle"])} (AI)`, repo: row["repo"] == null ? null : String(row["repo"]),
      taskId: row["task"] == null ? null : String(row["task"]), runId: null, action: `teammate tool call${verb}: ${String(row["tool"])} ${String(row["action"])}`, outcome, source: "work", detail });
  }

  /** v97: a call was undone by a person; false when it already was. */
  markTeammateCallUndone(id: number, by: string, now: Date): boolean {
    return this.transact(() => {
      const marked = Number(this.db.prepare("UPDATE teammate_call SET undone_by = ?, undone_at = ? WHERE id = ? AND undone_by IS NULL").run(by, now.toISOString(), id).changes) === 1;
      if (marked) this.recordTeammateCall(id, by, " undone", "undone", null, now);
      return marked;
    });
  }

  /** v97: cards someone moved by hand right after this actor (a teammate) moved them, since a time: what people overrode. */
  flowMovesOverridden(actor: string, since: string): { card: number; flow: number; title: string; teammateTo: string; personTo: string; by: string; at: string }[] {
    return this.db.prepare(`SELECT c.id AS card, c.flow AS flow, c.title AS title, mine.to_stage AS mine_to, later.to_stage AS later_to, later.actor AS later_actor, later.at AS later_at
      FROM flow_event mine JOIN flow_event later ON later.card = mine.card AND later.id = (SELECT MIN(id) FROM flow_event WHERE card = mine.card AND id > mine.id)
      JOIN flow_card c ON c.id = mine.card WHERE mine.actor = ? AND later.outcome = 'moved' AND later.actor <> ? AND later.at >= ? ORDER BY later.id DESC LIMIT 100`).all(actor, actor, since).map(row => ({
      card: Number(row["card"]), flow: Number(row["flow"]), title: String(row["title"]), teammateTo: String(row["mine_to"]), personTo: String(row["later_to"]), by: String(row["later_actor"]), at: String(row["later_at"]) }));
  }

  /** v97: undo calls a person asked for that aren't made yet. */
  pendingTeammateUndos(): TeammateCallRow[] {
    return this.db.prepare("SELECT * FROM teammate_call WHERE undo_of IS NOT NULL AND state = 'approved' ORDER BY id LIMIT 50").all().map(readTeammateCall);
  }

  /** v97: an undo that failed leaves the call as it was. */
  clearTeammateCallUndone(id: number, now: Date): void {
    this.transact(() => {
      const cleared = Number(this.db.prepare("UPDATE teammate_call SET undone_by = NULL, undone_at = NULL WHERE id = ? AND undone_by IS NOT NULL").run(id).changes) === 1;
      if (cleared) this.recordTeammateCall(id, null, " undo failed", "failed", null, now);
    });
  }

  /** v97: one model turn a teammate took, with what it cost. */
  addTeammateTurn(turn: { teammate: number; card: number | null; model: string; ok: boolean; ms: number; costUsd?: number | null; tokensIn?: number | null; tokensOut?: number | null }, now: Date): void {
    this.db.prepare("INSERT INTO teammate_turn (teammate, card, model, ok, ms, cost_usd, tokens_in, tokens_out, at, billing) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(turn.teammate, turn.card, turn.model, turn.ok ? 1 : 0, Math.round(turn.ms), turn.costUsd ?? null, turn.tokensIn ?? null, turn.tokensOut ?? null, now.toISOString(), claudeMachineBilling(this.db));
    this.spendCache = null;
  }

  /** v105: a flow's Claude draft, with what the CLI said it cost, billed as the sign-in was. */
  recordDraftSpend(draft: { repo: string | null; model: string | null; costUsd: number | null }, now: Date): void {
    this.db.prepare("INSERT INTO side_spend (kind, repo, provider, model, cost_usd, billing, at) VALUES ('draft', ?, 'claude', ?, ?, ?, ?)")
      .run(draft.repo, draft.model, draft.costUsd, claudeMachineBilling(this.db), now.toISOString());
    this.spendCache = null;
  }

  teammateTurns(teammate: number, since: string): TeammateTurnRow[] {
    return this.db.prepare("SELECT * FROM teammate_turn WHERE teammate = ? AND at >= ? ORDER BY id").all(teammate, since).map(row => ({
      id: Number(row["id"]), teammate: Number(row["teammate"]), card: row["card"] === null ? null : Number(row["card"]), model: String(row["model"]), ok: Number(row["ok"]) === 1, ms: Number(row["ms"]),
      costUsd: row["cost_usd"] === null ? null : Number(row["cost_usd"]), tokensIn: row["tokens_in"] === null ? null : Number(row["tokens_in"]), tokensOut: row["tokens_out"] === null ? null : Number(row["tokens_out"]), at: String(row["at"]) }));
  }

  teammateCall(id: number): TeammateCallRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_call WHERE id = ?").get(id);
    return row === undefined ? null : readTeammateCall(row);
  }

  /** Move a call on, only from the state it is known to be in: false when someone else moved it first. */
  moveTeammateCall(id: number, from: readonly TeammateCallState[], change: { state: TeammateCallState; result?: string | null; decidedBy?: string }, now: Date): boolean {
    const stamp = now.toISOString();
    const done = ["denied", "refused", "done", "failed"].includes(change.state);
    return this.transact(() => {
      const moved = Number(this.db.prepare(`UPDATE teammate_call SET state = ?, result = COALESCE(?, result), decided_by = COALESCE(?, decided_by), decided_at = CASE WHEN ? IS NULL THEN decided_at ELSE ? END,
        done_at = CASE WHEN ? THEN ? ELSE done_at END WHERE id = ? AND state IN (${from.map(() => "?").join(", ")})`)
        .run(change.state, change.result ?? null, change.decidedBy ?? null, change.decidedBy ?? null, stamp, done ? 1 : 0, stamp, id, ...from).changes) === 1;
      // A person's yes or no is theirs; everything else the call does is the teammate's.
      if (moved) this.recordTeammateCall(id, change.state === "approved" || change.state === "denied" ? change.decidedBy ?? null : null, "", change.state, null, now);
      return moved;
    });
  }

  /** A card's receipts, oldest first: one visit (`entry`), or every visit. */
  teammateCallsOn(card: number, entry: number | null = null): TeammateCallRow[] {
    return (entry === null ? this.db.prepare("SELECT * FROM teammate_call WHERE card = ? ORDER BY id").all(card) : this.db.prepare("SELECT * FROM teammate_call WHERE card = ? AND entry = ? ORDER BY id").all(card, entry)).map(readTeammateCall);
  }

  /** A teammate's receipts, newest first; `since` bounds them (a day's summary). */
  teammateCallsOf(teammate: number, limit: number, since: string | null = null): TeammateCallRow[] {
    return this.db.prepare(`SELECT * FROM teammate_call WHERE teammate = ? ${since === null ? "" : "AND created_at >= ?"} ORDER BY id DESC LIMIT ?`).all(...(since === null ? [teammate, limit] : [teammate, since, limit])).map(readTeammateCall);
  }

  teammateQuestion(id: number): TeammateQuestionRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_question WHERE id = ?").get(id);
    return row === undefined ? null : readTeammateQuestion(row);
  }

  /** The question a teammate asked of its own on one visit (never a tool call's approval). */
  teammateQuestionFor(card: number, entry: number): TeammateQuestionRow | null {
    const row = this.db.prepare("SELECT * FROM teammate_question WHERE card = ? AND entry = ? AND tool_call IS NULL AND suggestion IS NULL").get(card, entry);
    return row === undefined ? null : readTeammateQuestion(row);
  }

  /** Open questions for these teammates, oldest first. */
  openTeammateQuestions(teammates: readonly number[]): TeammateQuestionRow[] {
    if (teammates.length === 0) return [];
    return this.db.prepare(`SELECT * FROM teammate_question WHERE state = 'open' AND teammate IN (${teammates.map(() => "?").join(", ")}) ORDER BY id`).all(...teammates).map(readTeammateQuestion);
  }

  /** The answer, once: false when it was already answered (or dropped). */
  answerTeammateQuestion(id: number, answer: { choice: string | null; text: string | null; by: string; via: string }, now: Date): boolean {
    const { changes } = this.db.prepare("UPDATE teammate_question SET state = 'answered', choice = ?, answer = ?, answered_by = ?, answered_via = ?, answered_at = ? WHERE id = ? AND state = 'open'")
      .run(answer.choice, answer.text, answer.by, answer.via, now.toISOString(), id);
    return Number(changes) === 1;
  }

  dropTeammateQuestion(id: number, now: Date): void {
    this.db.prepare("UPDATE teammate_question SET state = 'dropped', answered_at = ? WHERE id = ? AND state = 'open'").run(now.toISOString(), id);
  }

  /** A step waiting on a person's answer becomes due now (the answer came). */
  wakeFlowStep(card: number, entry: number, now: Date): void {
    this.db.prepare("UPDATE flow_step_run SET next_at = ? WHERE card = ? AND entry = ? AND state = 'waiting'").run(now.toISOString(), card, entry);
  }

  /** Cards arriving in one zone of a flow after a history line: what a trigger on another flow follows. */
  flowArrivals(flow: number, stage: string, afterEvent: number, limit: number): { event: number; card: FlowCardRow }[] {
    return this.db.prepare("SELECT e.id AS event_id, c.* FROM flow_event e JOIN flow_card c ON c.id = e.card WHERE c.flow = ? AND e.to_stage = ? AND e.id > ? AND e.outcome <> 'cancelled' ORDER BY e.id LIMIT ?")
      .all(flow, stage, afterEvent, limit).map(row => ({ event: Number(row["event_id"]), card: readFlowCardRow(row) }));
  }

  /** The newest history line anywhere: a new trigger on another flow starts after it, never replaying the past. */
  latestFlowEvent(): number {
    return Number(this.db.prepare("SELECT COALESCE(MAX(id), 0) AS id FROM flow_event").get()?.["id"] ?? 0);
  }

  // ---- scripts and steps outside a model (v84) ------------------------------------

  /** A project's live scripts, by name. */
  flowScripts(repo: string): FlowScriptRow[] {
    return this.db.prepare("SELECT * FROM flow_script WHERE repo = ? AND state = 'active' ORDER BY name").all(repo).map(readFlowScriptRow);
  }

  flowScript(repo: string, name: string): FlowScriptRow | null {
    const row = this.db.prepare("SELECT * FROM flow_script WHERE repo = ? AND name = ? AND state = 'active'").get(repo, name);
    return row === undefined ? null : readFlowScriptRow(row);
  }

  /** Save a script's next version; the previous one stays in history. Returns the version. */
  saveFlowScript(script: { repo: string; name: string; about: string; body: string; timeoutMinutes: number; digest: string; by: string; language?: "shell" | "python" | "node"; file?: string | null; held?: string | null }, now: Date): number {
    return this.transact(() => {
      const current = this.flowScript(script.repo, script.name);
      const version = (current?.version ?? Number(this.db.prepare("SELECT COALESCE(MAX(version), 0) AS v FROM flow_script WHERE repo = ? AND name = ?").get(script.repo, script.name)?.["v"] ?? 0)) + 1;
      if (current !== null) this.db.prepare("UPDATE flow_script SET state = 'removed' WHERE id = ?").run(current.id);
      this.db.prepare(`INSERT INTO flow_script (repo, name, about, body, timeout_minutes, version, digest, saved_by, saved_at, state, language, file, held)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?)`).run(script.repo, script.name, script.about, script.body, script.timeoutMinutes, version, script.digest, script.by, now.toISOString(), script.language ?? "shell", script.file ?? null, script.held ?? null);
      return version;
    });
  }

  /** A person approves a held script (one an imported flow brought): from now on it runs. False when it wasn't held. */
  approveFlowScript(repo: string, name: string): boolean {
    const { changes } = this.db.prepare("UPDATE flow_script SET held = NULL WHERE repo = ? AND name = ? AND state = 'active' AND held IS NOT NULL").run(repo, name);
    return Number(changes) === 1;
  }

  removeFlowScript(repo: string, name: string): boolean {
    const { changes } = this.db.prepare("UPDATE flow_script SET state = 'removed' WHERE repo = ? AND name = ? AND state = 'active'").run(repo, name);
    return Number(changes) === 1;
  }

  /** Claim a card's visit to a step zone. False when another pass holds it or it already finished. */
  claimFlowStep(step: { card: number; entry: number; stage: string; kind: FlowStepKind; script: string | null; scriptVersion: number | null }, now: Date): boolean {
    return this.transact(() => {
      const existing = this.flowStepRun(step.card, step.entry);
      const stamp = now.toISOString();
      if (existing === null) {
        this.db.prepare("INSERT INTO flow_step_run (card, entry, stage, kind, script, script_version, state, attempts, started_at) VALUES (?, ?, ?, ?, ?, ?, 'running', 1, ?)")
          .run(step.card, step.entry, step.stage, step.kind, step.script, step.scriptVersion, stamp);
        return true;
      }
      // A step waiting to try again is due once its time comes.
      if (existing.state === "waiting" && (existing.nextAt === null || existing.nextAt <= stamp)) {
        this.db.prepare("UPDATE flow_step_run SET state = 'running', attempts = attempts + 1, started_at = ?, next_at = NULL, script = ?, script_version = ? WHERE card = ? AND entry = ?")
          .run(stamp, step.script, step.scriptVersion, step.card, step.entry);
        return true;
      }
      return false;
    });
  }

  flowStepRun(card: number, entry: number): FlowStepRunRow | null {
    const row = this.db.prepare("SELECT * FROM flow_step_run WHERE card = ? AND entry = ?").get(card, entry);
    return row === undefined ? null : readFlowStepRunRow(row);
  }

  /** Settle a step: passed or failed for good, or waiting to try again at `nextAt` — with what it printed, its exit code and how long it took. */
  finishFlowStep(card: number, entry: number, outcome: { state: "passed" | "failed" | "waiting"; result: string; nextAt?: string; log?: string | null; exitCode?: number | null; durationMs?: number | null; decisionJson?: string | null }, now: Date): void {
    this.db.prepare("UPDATE flow_step_run SET state = ?, result = ?, next_at = ?, finished_at = ?, log = ?, exit_code = ?, duration_ms = ?, decision_json = ? WHERE card = ? AND entry = ?")
      .run(outcome.state, outcome.result, outcome.nextAt ?? null, outcome.state === "waiting" ? null : now.toISOString(), outcome.log ?? null, outcome.exitCode ?? null, outcome.durationMs ?? null, outcome.decisionJson ?? null, card, entry);
  }

  /** Each card's latest sort decision in a flow: what its card shows. */
  flowSortDecisions(flow: number): Map<number, { entry: number; stage: string; decisionJson: string }> {
    const latest = new Map<number, { entry: number; stage: string; decisionJson: string }>();
    for (const row of this.db.prepare("SELECT r.card, r.entry, r.stage, r.decision_json FROM flow_step_run r JOIN flow_card c ON c.id = r.card WHERE c.flow = ? AND r.kind = 'sort' AND r.decision_json IS NOT NULL ORDER BY r.card, r.entry").all(flow)) {
      latest.set(Number(row["card"]), { entry: Number(row["entry"]), stage: String(row["stage"]), decisionJson: String(row["decision_json"]) });
    }
    return latest;
  }

  /** Steps still running long after they started: their worker stopped. */
  staleFlowSteps(before: Date): FlowStepRunRow[] {
    return this.db.prepare("SELECT * FROM flow_step_run WHERE state = 'running' AND started_at < ?").all(before.toISOString()).map(readFlowStepRunRow);
  }

  /** A flow's step runs, newest first: what the insights and the run log read. */
  flowStepRuns(flow: number, since: Date, limit: number): (FlowStepRunRow & { cardTitle: string })[] {
    return this.db.prepare("SELECT r.*, c.title AS card_title FROM flow_step_run r JOIN flow_card c ON c.id = r.card WHERE c.flow = ? AND r.started_at >= ? ORDER BY r.started_at DESC LIMIT ?")
      .all(flow, since.toISOString(), limit).map(row => ({ ...readFlowStepRunRow(row), cardTitle: String(row["card_title"]) }));
  }

  /** Every move of every card in a flow since a time, oldest first: what the insights count. */
  flowMoves(flow: number, since: Date): { card: number; fromStage: string | null; toStage: string; outcome: FlowEventOutcome; actor: string; note: string | null; at: string }[] {
    return this.db.prepare("SELECT e.card, e.from_stage, e.to_stage, e.outcome, e.actor, e.note, e.at FROM flow_event e JOIN flow_card c ON c.id = e.card WHERE c.flow = ? AND e.at >= ? ORDER BY e.id")
      .all(flow, since.toISOString()).map(row => ({ card: Number(row["card"]), fromStage: row["from_stage"] === null ? null : String(row["from_stage"]), toStage: String(row["to_stage"]),
        outcome: String(row["outcome"]) as FlowEventOutcome, actor: String(row["actor"]), note: row["note"] === null ? null : String(row["note"]), at: String(row["at"]) }));
  }

  // ---- people on flow cards (v83) ------------------------------------------------

  /** Make someone (or no one) a card's owner, with the line its history shows. */
  setFlowCardOwner(card: number, owner: string | null, actor: string, now: Date): void {
    this.transact(() => {
      const stamp = now.toISOString();
      this.db.prepare("UPDATE flow_card SET owner = ?, updated_at = ? WHERE id = ?").run(owner, stamp, card);
      this.db.prepare("INSERT INTO flow_comment (card, kind, author, body, mentions_json, at) VALUES (?, 'owner', ?, ?, '[]', ?)").run(card, actor, owner ?? "", stamp);
    });
  }

  /** Follow or stop following a card. True when it changed. */
  setFlowCardWatcher(card: number, name: string, watching: boolean, now: Date): boolean {
    const { changes } = watching
      ? this.db.prepare("INSERT OR IGNORE INTO flow_card_watcher (card, name, added_at) VALUES (?, ?, ?)").run(card, name, now.toISOString())
      : this.db.prepare("DELETE FROM flow_card_watcher WHERE card = ? AND name = ?").run(card, name);
    return Number(changes) === 1;
  }

  flowCardWatchers(card: number): string[] {
    return this.db.prepare("SELECT name FROM flow_card_watcher WHERE card = ? ORDER BY added_at, name").all(card).map(row => String(row["name"]));
  }

  addFlowComment(comment: { card: number; author: string; body: string; mentions: readonly string[] }, now: Date): number {
    const stamp = now.toISOString();
    const id = Number(this.db.prepare("INSERT INTO flow_comment (card, kind, author, body, mentions_json, at) VALUES (?, 'comment', ?, ?, ?, ?)")
      .run(comment.card, comment.author, comment.body, JSON.stringify(comment.mentions), stamp).lastInsertRowid);
    this.db.prepare("UPDATE flow_card SET updated_at = ? WHERE id = ?").run(stamp, comment.card);
    return id;
  }

  /** A card's discussion, oldest first. */
  flowComments(card: number): FlowCommentRow[] {
    return this.db.prepare("SELECT * FROM flow_comment WHERE card = ? ORDER BY id").all(card).map(row => {
      let mentions: string[] = [];
      try { const parsed = JSON.parse(String(row["mentions_json"])) as unknown; if (Array.isArray(parsed)) mentions = parsed.filter((one): one is string => typeof one === "string"); } catch { mentions = []; }
      return { id: Number(row["id"]), card: Number(row["card"]), kind: String(row["kind"]) as FlowCommentRow["kind"], author: String(row["author"]), body: String(row["body"]), mentions, at: String(row["at"]) };
    });
  }

  // ---- flow triggers (v82) -----------------------------------------------------

  addFlowTrigger(trigger: { flow: number; kind: string; configJson: string; hookHash: string | null; cursor: string | null; nextAt: string | null; by: string }, now: Date): number {
    const stamp = now.toISOString();
    return Number(this.db.prepare("INSERT INTO flow_trigger (flow, kind, config_json, state, hook_hash, cursor, next_at, created_by, created_at, updated_at) VALUES (?, ?, ?, 'active', ?, ?, ?, ?, ?, ?)")
      .run(trigger.flow, trigger.kind, trigger.configJson, trigger.hookHash, trigger.cursor, trigger.nextAt, trigger.by, stamp, stamp).lastInsertRowid);
  }

  getFlowTrigger(id: number): FlowTriggerRow | null {
    const row = this.db.prepare("SELECT * FROM flow_trigger WHERE id = ?").get(id);
    return row === undefined ? null : readFlowTriggerRow(row);
  }

  /** A flow's triggers that are not removed, oldest first. */
  flowTriggers(flow: number): FlowTriggerRow[] {
    return this.db.prepare("SELECT * FROM flow_trigger WHERE flow = ? AND state <> 'removed' ORDER BY id").all(flow).map(readFlowTriggerRow);
  }

  /** Active triggers of active flows in one project: what a worker's pass checks. */
  activeFlowTriggers(repo: string): FlowTriggerRow[] {
    return this.db.prepare("SELECT t.* FROM flow_trigger t JOIN flow f ON f.id = t.flow WHERE f.repo = ? AND f.state = 'active' AND t.state = 'active' ORDER BY t.id").all(repo).map(readFlowTriggerRow);
  }

  /** The trigger a webhook address belongs to (by the address's hash), when it and its flow are active. */
  flowTriggerByHook(hash: string): FlowTriggerRow | null {
    const row = this.db.prepare("SELECT t.* FROM flow_trigger t JOIN flow f ON f.id = t.flow WHERE t.hook_hash = ? AND t.state = 'active' AND f.state = 'active'").get(hash);
    return row === undefined ? null : readFlowTriggerRow(row);
  }

  updateFlowTrigger(id: number, change: { state?: "active" | "paused" | "removed"; cursor?: string | null; nextAt?: string | null; lastAt?: string; lastOutcome?: string; failures?: number; hookHash?: string | null }, now: Date): void {
    const trigger = this.getFlowTrigger(id);
    if (trigger === null) return;
    this.db.prepare("UPDATE flow_trigger SET state = ?, cursor = ?, next_at = ?, last_at = ?, last_outcome = ?, failures = ?, hook_hash = ?, updated_at = ? WHERE id = ?").run(
      change.state ?? trigger.state,
      change.cursor === undefined ? trigger.cursor : change.cursor,
      change.nextAt === undefined ? trigger.nextAt : change.nextAt,
      change.lastAt ?? trigger.lastAt,
      change.lastOutcome ?? trigger.lastOutcome,
      change.failures ?? trigger.failures,
      change.hookHash === undefined ? trigger.hookHash : change.hookHash,
      now.toISOString(), id,
    );
  }

  /** Whether a trigger already handled this outside thing (an issue, a run, a schedule slot). */
  flowTriggerSaw(trigger: number, key: string): boolean {
    return this.db.prepare("SELECT 1 FROM flow_trigger_event WHERE trigger = ? AND key = ?").get(trigger, key) !== undefined;
  }

  /** The card one outside thing made (v89: a chat message, so replies in its thread find it). */
  flowTriggerCard(trigger: number, key: string): number | null {
    const row = this.db.prepare("SELECT card FROM flow_trigger_event WHERE trigger = ? AND key = ?").get(trigger, key);
    return row === undefined || row["card"] === null ? null : Number(row["card"]);
  }

  /** The active chat trigger a channel feeds (v89), if any: one per channel. */
  chatTriggerFor(app: string, installation: string, chat: string): FlowTriggerRow | null {
    const row = this.db.prepare(`SELECT * FROM flow_trigger WHERE kind = 'chat' AND state = 'active'
      AND json_extract(config_json, '$.app') = ? AND json_extract(config_json, '$.installation') = ? AND json_extract(config_json, '$.chat') = ? ORDER BY id DESC LIMIT 1`).get(app, installation, chat);
    return row === undefined ? null : readFlowTriggerRow(row as Record<string, unknown>);
  }

  /** Record what a trigger did with one outside thing: the card it made, or why it made none. False when it was already recorded. */
  recordFlowTriggerEvent(trigger: number, key: string, card: number | null, note: string | null, now: Date): boolean {
    const { changes } = this.db.prepare("INSERT OR IGNORE INTO flow_trigger_event (trigger, key, card, note, at) VALUES (?, ?, ?, ?, ?)").run(trigger, key, card, note, now.toISOString());
    return Number(changes) === 1;
  }

  /** The last card a trigger made, if any. */
  lastFlowTriggerCard(trigger: number): number | null {
    const row = this.db.prepare("SELECT card FROM flow_trigger_event WHERE trigger = ? AND card IS NOT NULL ORDER BY rowid DESC LIMIT 1").get(trigger);
    return row === undefined ? null : Number(row["card"]);
  }

  // ---- project tools (v80) -------------------------------------------------

  /** The tools a project's builds get now (active only), oldest first. */
  projectTools(repo: string): { id: number; repo: string; name: string; specJson: string; digest: string; source: string; createdAt: string; createdBy: string; lastTestJson: string | null }[] {
    return this.db.prepare("SELECT * FROM project_tool WHERE repo = ? AND state = 'active' ORDER BY id").all(repo).map(row => ({
      id: Number(row["id"]), repo: String(row["repo"]), name: String(row["name"]), specJson: String(row["spec_json"]), digest: String(row["digest"]),
      source: String(row["source"]), createdAt: String(row["created_at"]), createdBy: String(row["created_by"]),
      lastTestJson: row["last_test_json"] === null ? null : String(row["last_test_json"]),
    }));
  }

  /** Add one tool; false when the project already has an active tool of that name. */
  addProjectTool(tool: { repo: string; name: string; specJson: string; digest: string; source: string; by: string }, now: Date): boolean {
    const clash = this.db.prepare("SELECT 1 AS hit FROM project_tool WHERE repo = ? AND name = ? AND state = 'active'").get(tool.repo, tool.name);
    if (clash !== undefined) return false;
    this.db.prepare("INSERT INTO project_tool (repo, name, spec_json, digest, source, state, created_at, created_by) VALUES (?, ?, ?, ?, ?, 'active', ?, ?)")
      .run(tool.repo, tool.name, tool.specJson, tool.digest, tool.source, now.toISOString(), tool.by);
    this.recordAction({ at: now.toISOString(), actor: tool.by, repo: tool.repo, taskId: null, runId: null, source: "policy", action: `tool added: ${tool.name}`, outcome: "added", detail: `from ${tool.source}` });
    return true;
  }

  /** Remove one tool from every build at once. False when it was not active. */
  removeProjectTool(repo: string, name: string, by: string, now: Date): boolean {
    const { changes } = this.db.prepare("UPDATE project_tool SET state = 'removed', removed_at = ?, removed_by = ? WHERE repo = ? AND name = ? AND state = 'active'")
      .run(now.toISOString(), by, repo, name);
    if (Number(changes) === 1) this.recordAction({ at: now.toISOString(), actor: by, repo, taskId: null, runId: null, source: "policy", action: `tool removed: ${name}`, outcome: "removed" });
    return Number(changes) === 1;
  }

  recordProjectToolTest(repo: string, name: string, testJson: string): void {
    this.db.prepare("UPDATE project_tool SET last_test_json = ? WHERE repo = ? AND name = ? AND state = 'active'").run(testJson, repo, name);
  }

  /** Record the project's active tools under this approval (re-approving the same bytes re-seals with today's list). */
  sealProjectTools(taskId: string, approvedDigest: string, now: Date): void {
    const repo = this.db.prepare("SELECT repo FROM task_ref WHERE backend = ? AND external_id = ?").get(BUILT_IN, taskId)?.["repo"];
    if (typeof repo !== "string") return;
    const tools = this.projectTools(repo).map(one => ({ name: one.name, digest: one.digest }));
    this.db.prepare("INSERT INTO tool_seal (task, approved_digest, tools_json, sealed_at) VALUES (?, ?, ?, ?) ON CONFLICT (task, approved_digest) DO UPDATE SET tools_json = excluded.tools_json, sealed_at = excluded.sealed_at")
      .run(taskId, approvedDigest, JSON.stringify(tools), now.toISOString());
  }

  /** The tools an approval saw, or null for an approval made before tools were sealed. */
  toolSealFor(taskId: string, approvedDigest: string): { name: string; digest: string }[] | null {
    const row = this.db.prepare("SELECT tools_json FROM tool_seal WHERE task = ? AND approved_digest = ?").get(taskId, approvedDigest);
    if (row === undefined) return null;
    try {
      const parsed = JSON.parse(String(row["tools_json"])) as unknown;
      return Array.isArray(parsed) ? parsed.filter((one): one is { name: string; digest: string } => typeof one?.name === "string" && typeof one?.digest === "string") : [];
    } catch {
      return [];
    }
  }

  /** What one attempt launched with (first launch of the run wins its record; a resumed turn updates it). */
  recordRunTools(run: number, toolsJson: string, now: Date): void {
    this.db.prepare(`INSERT INTO run_tool (run, tools_json, created_at) VALUES (?, ?, ?) ON CONFLICT (run) DO UPDATE SET tools_json =
      CASE WHEN json_extract(tools_json, '$.fence') IS NULL THEN excluded.tools_json ELSE json_set(excluded.tools_json, '$.fence', json(json_extract(tools_json, '$.fence'))) END`).run(run, toolsJson, now.toISOString());
  }

  /** How one attempt was kept away from Toolroll's own secrets (the agent fence), kept beside its tools. */
  recordRunFence(run: number, fence: { method: string; paths: number }, now: Date): void {
    this.db.prepare(`INSERT INTO run_tool (run, tools_json, created_at) VALUES (?, json_object('fence', json(?)), ?)
      ON CONFLICT (run) DO UPDATE SET tools_json = json_set(tools_json, '$.fence', json(?))`).run(run, JSON.stringify(fence), now.toISOString(), JSON.stringify(fence));
  }

  runFence(run: number): { method: string; paths: number } | null {
    const row = this.db.prepare("SELECT json_extract(tools_json, '$.fence') AS fence FROM run_tool WHERE run = ?").get(run);
    if (row === undefined || row["fence"] === null) return null;
    try { return JSON.parse(String(row["fence"])) as { method: string; paths: number }; } catch { return null; }
  }

  runTools(run: number): { tools: { name: string; digest: string }[]; skipped: { name: string; reason: string }[] } | null {
    const row = this.db.prepare("SELECT tools_json FROM run_tool WHERE run = ?").get(run);
    if (row === undefined) return null;
    try {
      const parsed = JSON.parse(String(row["tools_json"])) as { tools?: unknown; skipped?: unknown };
      return { tools: Array.isArray(parsed.tools) ? parsed.tools as { name: string; digest: string }[] : [], skipped: Array.isArray(parsed.skipped) ? parsed.skipped as { name: string; reason: string }[] : [] };
    } catch {
      return null;
    }
  }

  /** A Telegram message this bot sent that showed one task (v79): a reply to
   * it is about that task (and that result, when it showed one). A message
   * edited to show something else forgets it. */
  recordTelegramTaskMessage(binding: TelegramBinding, messageId: string, taskId: string | null, run: number | null, now: Date): void {
    if (taskId === null) {
      this.db.prepare("DELETE FROM telegram_task_message WHERE binding = ? AND chat_id = ? AND message_id = ?").run(binding.id, binding.chatId, messageId);
      return;
    }
    this.db.prepare(`INSERT INTO telegram_task_message (binding, chat_id, message_id, task_id, source_run, created_at) VALUES (?, ?, ?, ?, ?, ?)
      ON CONFLICT (binding, chat_id, message_id) DO UPDATE SET task_id = excluded.task_id, source_run = excluded.source_run, created_at = excluded.created_at`)
      .run(binding.id, binding.chatId, messageId, taskId, run, now.toISOString());
  }

  /** The approver's live personal threads that have messages, most recent
   * first — the chat list. Team conversations list themselves. */
  listMateThreads(approver: string, limit = 30): MateThreadSummary[] {
    const rows = this.db.prepare(
      `SELECT t.*, (SELECT MAX(m.created_at) FROM mate_message m WHERE m.thread = t.id) AS last_message_at,
         (SELECT m.text FROM mate_message m WHERE m.thread = t.id ORDER BY m.id DESC LIMIT 1) AS last_message,
         (SELECT COUNT(*) FROM mate_message m WHERE m.thread = t.id) AS messages
       FROM mate_thread t
       WHERE t.approver = ? AND t.closed_at IS NULL AND NOT EXISTS (SELECT 1 FROM team_conversation tc WHERE tc.thread = t.id)
         AND EXISTS (SELECT 1 FROM mate_message m WHERE m.thread = t.id)
       ORDER BY last_message_at DESC, t.id DESC LIMIT ?`,
    ).all(approver, Math.max(1, Math.min(100, limit)));
    return rows.map(row => ({ ...readMateThread(row), lastMessageAt: row["last_message_at"] === null ? null : String(row["last_message_at"]), lastMessage: row["last_message"] === null ? null : String(row["last_message"]), messages: Number(row["messages"]) }));
  }

  getMateThread(id: number): MateThread | null {
    const row = this.db.prepare("SELECT * FROM mate_thread WHERE id = ?").get(id);
    return row === undefined ? null : readMateThread(row);
  }

  /** `--end` and revocation: the thread's text and every proposal in it are
   * deleted; the thread row stays as closed metadata (when, whose). */
  closeMateThreadsFor(approver: string, now: Date): number {
    return this.transact(() => {
      const rows = this.db.prepare("SELECT id FROM mate_thread WHERE approver = ? AND closed_at IS NULL AND NOT EXISTS (SELECT 1 FROM team_conversation tc WHERE tc.thread=mate_thread.id)").all(approver);
      for (const row of rows) {
        const id = Number(row["id"]);
        this.db.prepare("DELETE FROM mate_message WHERE thread = ?").run(id);
        this.db.prepare("DELETE FROM mate_proposal WHERE thread = ?").run(id);
        this.db.prepare("UPDATE mate_thread SET closed_at = ? WHERE id = ?").run(now.toISOString(), id);
      }
      return rows.length;
    });
  }

  appendMateMessage(message: { thread: number; turn: number | null; role: "operator" | "assistant"; text: string; activity?: string | null }, now: Date): number {
    const inserted = this.db
      .prepare("INSERT INTO mate_message (thread, turn, role, text, activity, created_at) VALUES (?, ?, ?, ?, ?, ?)")
      .run(message.thread, message.turn, message.role, message.text, message.activity ?? null, now.toISOString());
    this.db.prepare("UPDATE mate_thread SET last_turn_at = ? WHERE id = ?").run(now.toISOString(), message.thread);
    return Number(inserted.lastInsertRowid);
  }

  /** The last `limit` messages, oldest first. */
  listMateMessages(thread: number, limit: number): MateMessage[] {
    return this.db
      .prepare("SELECT * FROM (SELECT * FROM mate_message WHERE thread = ? ORDER BY id DESC LIMIT ?) ORDER BY id ASC")
      .all(thread, limit)
      .map(row => ({
        id: Number(row["id"]),
        thread: Number(row["thread"]),
        turn: row["turn"] === null ? null : Number(row["turn"]),
        role: String(row["role"]) as MateMessage["role"],
        text: String(row["text"]),
        activity: row["activity"] === null ? null : String(row["activity"]),
        createdAt: String(row["created_at"]),
      }));
  }

  /** A proposal is inert (`drafting`) until its turn finalizes. */
  draftMateProposal(proposal: { thread: number; turn: number; kind: MateProposalKind; payload: Record<string, unknown>; ceilingDigest: string }, now: Date): number {
    const inserted = this.db
      .prepare("INSERT INTO mate_proposal (thread, turn, kind, payload_json, ceiling_digest, state, created_at) VALUES (?, ?, ?, ?, ?, 'drafting', ?)")
      .run(proposal.thread, proposal.turn, proposal.kind, JSON.stringify(proposal.payload), proposal.ceilingDigest, now.toISOString());
    return Number(inserted.lastInsertRowid);
  }

  // ---- the lead's question to its owner (ask_owner) -----------------------------

  /** Record this turn's one question; false when the turn already asked one. */
  recordMateAsk(ask: { turn: number; thread: number; question: string; options: readonly string[] }, now: Date): boolean {
    const inserted = this.db.prepare("INSERT OR IGNORE INTO mate_ask (turn, thread, question, options_json, created_at) VALUES (?, ?, ?, ?, ?)")
      .run(ask.turn, ask.thread, ask.question, JSON.stringify(ask.options), now.toISOString());
    return Number(inserted.changes) === 1;
  }

  /** A failed turn keeps no question, as it keeps no drafts. */
  dropMateAsk(turn: number): void {
    this.db.prepare("DELETE FROM mate_ask WHERE turn = ?").run(turn);
  }

  /** The question an ANSWERED turn asked; null when it asked none or did not answer. */
  mateAsk(turn: number): MateAsk | null {
    const row = this.db.prepare("SELECT a.* FROM mate_ask a JOIN mate_turn t ON t.id = a.turn WHERE a.turn = ? AND t.state = 'answered'").get(turn);
    if (row === undefined) return null;
    const options = JSON.parse(String(row["options_json"])) as unknown;
    return { turn: Number(row["turn"]), thread: Number(row["thread"]), question: String(row["question"]), options: Array.isArray(options) ? options.map(String) : [], createdAt: String(row["created_at"]) };
  }

  /** What a tap on the question finds: open; answered (its owner has written in its thread since the reply that asked
   * it, typed or tapped; a turn the lead started itself, or another person's message, is no answer); or expired (older
   * than MATE_ASK_TTL_MS, or the question or the reply that asked it is gone, as after a retention purge). */
  mateAskState(turn: number, now: Date): { state: "open"; ask: MateAsk } | { state: "answered" | "expired" } {
    const ask = this.mateAsk(turn);
    if (ask === null) return { state: "expired" };
    const asking = this.db.prepare("SELECT MAX(id) AS id FROM mate_message WHERE thread = ? AND turn = ? AND role = 'assistant'").get(ask.thread, turn);
    if (asking === undefined || asking["id"] === null) return { state: "expired" };
    const owner = String(this.getMateTurn(turn)!.approver);
    const later = this.db.prepare(`SELECT 1 AS hit FROM mate_message m LEFT JOIN mate_turn t ON t.id = m.turn LEFT JOIN team_message tm ON tm.message = m.id
        WHERE m.thread = ? AND m.role = 'operator' AND m.id > ? AND m.text <> ? AND COALESCE(tm.author, t.approver, ?) = ? LIMIT 1`)
      .get(ask.thread, Number(asking["id"]), LEAD_FOLLOW_MESSAGE, owner, owner);
    if (later !== undefined) return { state: "answered" };
    if (new Date(ask.createdAt).getTime() + MATE_ASK_TTL_MS <= now.getTime()) return { state: "expired" };
    return { state: "open", ask };
  }

  /** The question while it is open (see mateAskState); null otherwise. */
  mateAskOpen(turn: number, now: Date): MateAsk | null {
    const found = this.mateAskState(turn, now);
    return found.state === "open" ? found.ask : null;
  }

  // ---- the screenshots a turn selected (v64) ------------------------------------

  /**
   * Record the screenshots one turn selected for an exact result, under the
   * turn, so a channel that delivers files can plan them from the completed
   * turn without another model call. Identities only — the caller proved
   * access and read the artifact rows; the channel re-verifies every one
   * before upload. A turn holds at most `cap` images; the same artifact is
   * recorded once. Returns how many of THESE rows are recorded after the call.
   */
  recordMateTurnEvidence(turn: number, rows: readonly Omit<MateTurnEvidence, "turn" | "ordinal" | "createdAt">[], cap: number, now: Date): number {
    return this.transact(() => {
      const live = this.db.prepare("SELECT 1 AS hit FROM mate_turn WHERE id = ? AND state = 'running'").get(turn);
      if (live === undefined) return 0;
      let ordinal = Number(this.db.prepare("SELECT COUNT(*) AS n FROM mate_turn_evidence WHERE turn = ?").get(turn)?.["n"] ?? 0);
      let recorded = 0;
      for (const row of rows) {
        const seen = this.db.prepare("SELECT 1 AS hit FROM mate_turn_evidence WHERE turn = ? AND artifact = ?").get(turn, row.artifact);
        if (seen !== undefined) { recorded++; continue; }
        if (ordinal >= cap) continue;
        this.db
          .prepare(
            `INSERT INTO mate_turn_evidence (turn, ordinal, task_id, task_ref, run, artifact, sha256, format, bytes, caption, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(turn, ordinal, row.taskId, row.taskRef, row.run, row.artifact, row.sha256, row.format, row.bytes, row.caption, now.toISOString());
        ordinal++;
        recorded++;
      }
      return recorded;
    });
  }

  /** The screenshots a turn selected, in selection order — meaningful only for a turn that ANSWERED (a failed turn's rows are deleted). */
  listMateTurnEvidence(turn: number): MateTurnEvidence[] {
    return this.db.prepare("SELECT * FROM mate_turn_evidence WHERE turn = ? ORDER BY ordinal").all(turn).map(row => ({
      turn: Number(row["turn"]),
      ordinal: Number(row["ordinal"]),
      taskId: String(row["task_id"]),
      taskRef: Number(row["task_ref"]),
      run: Number(row["run"]),
      artifact: Number(row["artifact"]),
      sha256: String(row["sha256"]),
      format: String(row["format"]) as MateTurnEvidence["format"],
      bytes: Number(row["bytes"]),
      caption: String(row["caption"]),
      createdAt: String(row["created_at"]),
    }));
  }

  /** A failed turn's selection is DELETED with its drafts: nothing a failed turn selected is ever sent. */
  discardMateTurnEvidence(turn: number): number {
    return Number(this.db.prepare("DELETE FROM mate_turn_evidence WHERE turn = ?").run(turn).changes);
  }

  /** Drafts become confirmable only under a turn that ANSWERED (review finding 12). */
  promoteMateProposals(turn: number): number {
    const changed = this.db
      .prepare("UPDATE mate_proposal SET state = 'pending' WHERE turn = ? AND state = 'drafting' AND EXISTS (SELECT 1 FROM mate_turn WHERE id = ? AND state = 'answered')")
      .run(turn, turn);
    return Number(changed.changes);
  }

  /** A failed turn's drafts are DELETED — nothing a failed turn produced is durable (finding 4). */
  discardMateProposals(turn: number): number {
    const changed = this.db.prepare("DELETE FROM mate_proposal WHERE turn = ? AND state = 'drafting'").run(turn);
    return Number(changed.changes);
  }

  getMateProposal(id: number): MateProposal | null {
    const row = this.db.prepare("SELECT * FROM mate_proposal WHERE id = ?").get(id);
    return row === undefined ? null : readMateProposal(row);
  }

  listMateProposals(thread: number, states?: readonly MateProposalState[]): MateProposal[] {
    const rows =
      states === undefined
        ? this.db.prepare("SELECT * FROM mate_proposal WHERE thread = ? ORDER BY id ASC").all(thread)
        : this.db
            .prepare(`SELECT * FROM mate_proposal WHERE thread = ? AND state IN (${states.map(() => "?").join(",")}) ORDER BY id ASC`)
            .all(thread, ...states);
    return rows.map(readMateProposal);
  }

  /** The state CAS confirmation rides on (ruling 7). */
  casMateProposal(id: number, from: MateProposalState, to: MateProposalState, by: string | null, outcome: Record<string, unknown> | null, now: Date): boolean {
    const terminal = to === "confirmed" || to === "refused" || to === "dismissed" || to === "expired";
    const changed = this.db
      .prepare(
        `UPDATE mate_proposal SET state = ?, resolved_at = CASE WHEN ? THEN ? ELSE resolved_at END,
           resolved_by = COALESCE(?, resolved_by), outcome_json = COALESCE(?, outcome_json)
         WHERE id = ? AND state = ?`,
      )
      .run(to, terminal ? 1 : 0, now.toISOString(), by, outcome === null ? null : JSON.stringify(outcome), id, from);
    return Number(changed.changes) === 1;
  }

  /**
   * The turn's reservation, in ONE transaction against the session and the
   * weekly ledger, before any dispatch (ruling 5). One live turn per
   * approver serializes the console and the CLI.
   */
  openMateTurn(
    args: { approver: string; session: number; thread: number; credentialKey: string; reservedMicrousd: number; dailyTurns: number; weeklyCeilingMicrousd: number; deadlineMs: number; provider?: string },
    now: Date,
  ): { ok: true; id: number } | { ok: false; reason: "latched" | "concurrent" | "daily-cap" | "session-exhausted" | "session-ended" | "not-yours" | "thread-closed" | "over-budget" | "monthly-budget" } {
    return this.transact(() => {
      // The binding (slice-1 review, finding 2): the session and the thread
      // are THIS approver's, under THIS credential, under one ceiling, and
      // the thread is open — a structural snapshot proves none of that.
      const session = this.getMateSession(args.session);
      const thread = this.getMateThread(args.thread);
      if (session === null || thread === null) return { ok: false as const, reason: "not-yours" as const };
      const teamBinding = this.db.prepare("SELECT 1 FROM team_mate_session WHERE session=? AND thread=?").get(args.session,args.thread) !== undefined;
      if (session.approver !== args.approver || (teamBinding ? !this.teamMateThreadAllows(args.thread,args.approver,session.approverGeneration) : thread.approver !== args.approver || this.db.prepare("SELECT 1 FROM team_conversation WHERE thread=?").get(args.thread) !== undefined) || session.credentialKey !== args.credentialKey) {
        return { ok: false as const, reason: "not-yours" as const };
      }
      if (thread.closedAt !== null || (!teamBinding && thread.ceilingDigest !== session.ceilingDigest)) return { ok: false as const, reason: "thread-closed" as const };
      // v105: a monthly budget this turn counts toward (the person's, the thread's project's or task's project's,
      // everything), used up; a subscription chat costs nothing extra.
      const threadScope = this.db.prepare(`SELECT CASE th.scope_kind WHEN 'project' THEN th.scope_key
          WHEN 'task' THEN (SELECT r.repo FROM task_ref r WHERE r.external_id = th.scope_key ORDER BY r.id DESC LIMIT 1) END AS project
        FROM mate_thread th WHERE th.id = ?`).get(args.thread);
      if (this.budgetGate(now)({ project: threadScope?.["project"] == null ? null : String(threadScope["project"]), person: args.approver, teammate: null,
        ...(args.provider === undefined ? {} : { agents: this.agentsFor([args.provider]) }) }).over !== null) {
        return { ok: false as const, reason: "monthly-budget" as const };
      }
      const latched = this.db
        .prepare("SELECT 1 AS hit FROM chat_turn WHERE credential_key = ? AND unknown_spend = 1 AND acknowledged_at IS NULL LIMIT 1")
        .get(args.credentialKey);
      if (latched !== undefined) return { ok: false as const, reason: "latched" as const };
      const live = teamBinding
        ? this.db.prepare("SELECT 1 FROM mate_turn WHERE thread=? AND state IN ('queued','running') LIMIT 1").get(args.thread)
        : this.db.prepare("SELECT 1 FROM mate_turn WHERE approver=? AND state IN ('queued','running') AND NOT EXISTS (SELECT 1 FROM team_conversation tc WHERE tc.thread=mate_turn.thread) LIMIT 1").get(args.approver);
      const liveChat = this.db.prepare("SELECT 1 FROM chat_turn WHERE approver=? AND state IN ('queued','running') AND mate_turn IS NULL LIMIT 1").get(args.approver);
      if (live !== undefined || liveChat !== undefined) return { ok: false as const, reason: "concurrent" as const };
      if (this.chatTurnsToday(args.approver, now) >= args.dailyTurns) return { ok: false as const, reason: "daily-cap" as const };
      if (session.endedAt !== null) {
        return { ok: false as const, reason: "session-ended" as const };
      }
      if (session.spentMicrousd + args.reservedMicrousd > session.ceilingMicrousd) {
        return { ok: false as const, reason: "session-exhausted" as const };
      }
      if (this.chatWeeklySpendMicrousd(args.credentialKey, now) + args.reservedMicrousd > args.weeklyCeilingMicrousd) {
        return { ok: false as const, reason: "over-budget" as const };
      }
      const inserted = this.db
        .prepare(
          `INSERT INTO mate_turn (approver, session, thread, credential_key, state, created_at, deadline_at, reserved_microusd)
           VALUES (?, ?, ?, ?, 'queued', ?, ?, ?)`,
        )
        .run(args.approver, args.session, args.thread, args.credentialKey, now.toISOString(), new Date(now.getTime() + args.deadlineMs).toISOString(), args.reservedMicrousd);
      return { ok: true as const, id: Number(inserted.lastInsertRowid) };
    });
  }

  startMateTurn(id: number, now: Date): { ok: true; generation: number } | { ok: false } {
    const changed = this.db
      .prepare("UPDATE mate_turn SET state = 'running', generation = generation + 1 WHERE id = ? AND state = 'queued'")
      .run(id);
    if (Number(changed.changes) !== 1) return { ok: false };
    const row = this.db.prepare("SELECT generation FROM mate_turn WHERE id = ?").get(id);
    void now;
    return { ok: true, generation: Number(row?.["generation"] ?? 0) };
  }

  /** One provider request of a mate turn: a chat_turn row of kind
   * 'mate-step', reserved at zero (the turn holds the reservation), with
   * the same dispatch CAS, terminal CAS, and crash latch as fleet chat. */
  openMateStep(
    args: { mateTurn: number; generation: number; approver: string; credentialKey: string; provider: ChatProviderId; model: string; deadlineMs: number },
    now: Date,
  ): { ok: true; id: number } | { ok: false; reason: "latched" | "gone" } {
    return this.transact(() => {
      // The latch is re-checked before EVERY dispatch (finding 11): another
      // approver's unknown-cost turn on the shared credential stops this
      // loop between steps, exactly as it would stop a fresh turn.
      const latched = this.db
        .prepare("SELECT 1 AS hit FROM chat_turn WHERE credential_key = ? AND unknown_spend = 1 AND acknowledged_at IS NULL LIMIT 1")
        .get(args.credentialKey);
      if (latched !== undefined) return { ok: false as const, reason: "latched" as const };
      const parent = this.db
        .prepare("SELECT 1 AS hit FROM mate_turn WHERE id = ? AND generation = ? AND state = 'running'")
        .get(args.mateTurn, args.generation);
      if (parent === undefined) return { ok: false as const, reason: "gone" as const };
      const inserted = this.db
        .prepare(
          `INSERT INTO chat_turn (approver, credential_key, provider, model, state, created_at, deadline_at, reserved_microusd, kind, mate_turn)
           VALUES (?, ?, ?, ?, 'queued', ?, ?, 0, 'mate-step', ?)`,
        )
        .run(args.approver, args.credentialKey, args.provider, args.model, now.toISOString(), new Date(now.getTime() + args.deadlineMs).toISOString(), args.mateTurn);
      this.db.prepare("UPDATE mate_turn SET steps = steps + 1 WHERE id = ?").run(args.mateTurn);
      return { ok: true as const, id: Number(inserted.lastInsertRowid) };
    });
  }

  /**
   * Terminal CAS for the turn. One write settles the turn, debits the
   * session, promotes the drafts, and appends the assistant text (review
   * finding 12) — a crash leaves all of it or none. A step whose cost is
   * unknown charges the WHOLE reservation (finding 1): the ledger never
   * releases money it cannot prove was not spent; acknowledging the step
   * later does not refund it.
   */
  finalizeMateTurn(
    id: number,
    generation: number,
    outcome: {
      state: "answered" | "failed";
      settledMicrousd: number;
      unknownSpend?: boolean;
      tokensIn: number;
      tokensOut: number;
      failureReason?: string;
      /** Answered turns: the assistant row, written in the same transaction as the promotion. */
      message?: { text: string; activity: string };
    },
    now: Date,
  ): boolean {
    this.spendCache = null; // its spend counts toward the next budget check
    return this.transact(() => {
      const before = this.db.prepare("SELECT reserved_microusd AS reserved, session, thread FROM mate_turn WHERE id = ? AND generation = ? AND state IN ('queued','running')").get(id, generation);
      if (before === undefined) return false;
      const settled = outcome.unknownSpend === true ? Math.max(Number(before["reserved"]), outcome.settledMicrousd) : outcome.settledMicrousd;
      const changed = this.db
        .prepare(
          `UPDATE mate_turn SET state = ?, settled_microusd = ?, tokens_in = ?, tokens_out = ?, failure_reason = ?, finished_at = ?
           WHERE id = ? AND generation = ? AND state IN ('queued','running')`,
        )
        .run(outcome.state, settled, outcome.tokensIn, outcome.tokensOut, outcome.failureReason ?? null, now.toISOString(), id, generation);
      if (Number(changed.changes) !== 1) return false;
      this.db.prepare("UPDATE mate_session SET spent_microusd = spent_microusd + ? WHERE id = ?").run(settled, Number(before["session"]));
      if (outcome.state === "answered") {
        this.promoteMateProposals(id);
        if (outcome.message !== undefined) {
          this.appendMateMessage({ thread: Number(before["thread"]), turn: id, role: "assistant", text: outcome.message.text, activity: outcome.message.activity }, now);
        }
      } else {
        this.discardMateProposals(id);
        this.discardMateTurnEvidence(id);
      }
      return true;
    });
  }

  /** Revocation's companion for a loop in flight (finding 5): every live
   * turn of the approver fails NOW, charged its whole reservation, its
   * generation moved so the returning loop's terminal CAS loses. */
  failLiveMateTurnsFor(approver: string, reason: string, now: Date, privateOnly = false): number {
    return this.transact(() => {
      const rows = this.db.prepare("SELECT id, session, reserved_microusd AS reserved FROM mate_turn WHERE approver = ? AND state IN ('queued','running') AND (?=0 OR NOT EXISTS (SELECT 1 FROM team_conversation tc WHERE tc.thread=mate_turn.thread))").all(approver, privateOnly ? 1 : 0);
      for (const row of rows) {
        const id = Number(row["id"]);
        this.db
          .prepare("UPDATE mate_turn SET state = 'failed', failure_reason = ?, generation = generation + 1, settled_microusd = ?, finished_at = ? WHERE id = ?")
          .run(reason, Number(row["reserved"]), now.toISOString(), id);
        this.db.prepare("UPDATE mate_session SET spent_microusd = spent_microusd + ? WHERE id = ?").run(Number(row["reserved"]), Number(row["session"]));
        this.discardMateProposals(id);
        this.discardMateTurnEvidence(id);
      }
      return rows.length;
    });
  }

  /** The crash sweep for turns: past the deadline, failed. The session is
   * charged the settled sum of the steps that answered — unless any step
   * is unproven (dispatched and never settled, or latched), in which case
   * the WHOLE reservation is charged (finding 1). Drafts are deleted. */
  sweepStaleMateTurns(now: Date): number {
    return this.transact(() => {
      this.sweepStaleChatTurns(now);
      const rows = this.db
        .prepare("SELECT id, session, reserved_microusd AS reserved FROM mate_turn WHERE state IN ('queued','running') AND deadline_at < ?")
        .all(now.toISOString());
      for (const row of rows) {
        const id = Number(row["id"]);
        const settled = this.db
          .prepare("SELECT COALESCE(SUM(settled_microusd), 0) AS n FROM chat_turn WHERE mate_turn = ? AND settled_microusd IS NOT NULL")
          .get(id);
        const unproven = this.db
          .prepare("SELECT 1 AS hit FROM chat_turn WHERE mate_turn = ? AND (state IN ('queued','running') OR unknown_spend = 1 OR settled_microusd IS NULL) LIMIT 1")
          .get(id);
        const spent = unproven === undefined ? Number(settled?.["n"] ?? 0) : Math.max(Number(row["reserved"]), Number(settled?.["n"] ?? 0));
        this.db
          .prepare("UPDATE mate_turn SET state = 'failed', failure_reason = 'crashed', generation = generation + 1, settled_microusd = ?, finished_at = ? WHERE id = ?")
          .run(spent, now.toISOString(), id);
        this.db.prepare("UPDATE mate_session SET spent_microusd = spent_microusd + ? WHERE id = ?").run(spent, Number(row["session"]));
        this.discardMateProposals(id);
        this.discardMateTurnEvidence(id);
      }
      return rows.length;
    });
  }

  /** A task_ref by its row id: the external id and repo — for decisions, which hang off runs. */
  refById(id: number): { id: number; externalId: string; repo: string | null } | null {
    const row = this.db.prepare("SELECT id, external_id, repo FROM task_ref WHERE id = ? AND backend = ?").get(id, BUILT_IN);
    return row === undefined ? null : { id: Number(row["id"]), externalId: String(row["external_id"]), repo: row["repo"] === null ? null : String(row["repo"]) };
  }

  // ---- coordinator proposals (mate arc v3) --------------------------------

  fileCoordinatorProposalRow(proposal: { cid: string; name: string; repo: string; kind: CoordinatorProposalKind; payload: Record<string, unknown> }, now: Date): number {
    const inserted = this.db
      .prepare("INSERT INTO coordinator_proposal (cid, name, repo, kind, payload_json, state, created_at) VALUES (?, ?, ?, ?, ?, 'pending', ?)")
      .run(proposal.cid, proposal.name, proposal.repo, proposal.kind, JSON.stringify(proposal.payload), now.toISOString());
    return Number(inserted.lastInsertRowid);
  }

  getCoordinatorProposal(id: number): CoordinatorProposal | null {
    const row = this.db.prepare("SELECT * FROM coordinator_proposal WHERE id = ?").get(id);
    return row === undefined ? null : readCoordinatorProposal(row);
  }

  /** Pending rows over an admitted-repo list (null = every repo — the CLI without a ceiling), newest first, optionally one task's. */
  listCoordinatorProposals(filter: { repos: readonly string[] | null; states?: readonly CoordinatorProposalState[]; taskId?: string; cid?: string; limit?: number }): CoordinatorProposal[] {
    const clauses: string[] = [];
    const args: (string | number)[] = [];
    if (filter.repos !== null) {
      if (filter.repos.length === 0) return [];
      clauses.push(`repo IN (${filter.repos.map(() => "?").join(",")})`);
      args.push(...filter.repos);
    }
    const states = filter.states ?? ["pending"];
    clauses.push(`state IN (${states.map(() => "?").join(",")})`);
    args.push(...states);
    if (filter.cid !== undefined) {
      clauses.push("cid = ?");
      args.push(filter.cid);
    }
    if (filter.taskId !== undefined) {
      clauses.push("json_extract(payload_json, '$.task') = ?");
      args.push(filter.taskId);
    }
    args.push(Math.max(1, Math.min(filter.limit ?? 100, 500)));
    return this.db
      .prepare(`SELECT * FROM coordinator_proposal WHERE ${clauses.join(" AND ")} ORDER BY id DESC LIMIT ?`)
      .all(...args)
      .map(readCoordinatorProposal);
  }

  /** Proposals this credential filed in the window — they share the filing rate with file_proposal. */
  coordinatorProposalsSince(cid: string, since: Date): number {
    const row = this.db.prepare("SELECT COUNT(*) AS n FROM coordinator_proposal WHERE cid = ? AND created_at > ?").get(cid, since.toISOString());
    return Number(row?.["n"] ?? 0);
  }

  casCoordinatorProposal(id: number, from: CoordinatorProposalState, to: CoordinatorProposalState, by: string | null, outcome: Record<string, unknown> | null, now: Date): boolean {
    const terminal = to === "confirmed" || to === "refused" || to === "dismissed" || to === "expired";
    const changed = this.db
      .prepare(
        `UPDATE coordinator_proposal SET state = ?, resolved_at = CASE WHEN ? THEN ? ELSE resolved_at END,
           resolved_by = COALESCE(?, resolved_by), outcome_json = COALESCE(?, outcome_json)
         WHERE id = ? AND state = ?`,
      )
      .run(to, terminal ? 1 : 0, now.toISOString(), by, outcome === null ? null : JSON.stringify(outcome), id, from);
    return Number(changed.changes) === 1;
  }

  /** Pending rows expire after seven days; a revoked credential's pending rows expire at once. */
  sweepCoordinatorProposals(now: Date, cid?: string): number {
    const cutoff = new Date(now.getTime() - 7 * 24 * 3_600_000).toISOString();
    const changed =
      cid === undefined
        ? this.db.prepare("UPDATE coordinator_proposal SET state = 'expired', resolved_at = ? WHERE state = 'pending' AND created_at < ?").run(now.toISOString(), cutoff)
        : this.db.prepare("UPDATE coordinator_proposal SET state = 'expired', resolved_at = ? WHERE state IN ('pending','confirming') AND cid = ?").run(now.toISOString(), cid);
    return Number(changed.changes);
  }

  recentMateTurns(approver: string, limit = 10): MateTurn[] {
    return this.db
      .prepare("SELECT * FROM mate_turn WHERE approver = ? ORDER BY id DESC LIMIT ?")
      .all(approver, Math.max(1, Math.min(limit, 100)))
      .map(readMateTurn);
  }

  getMateTurn(id: number): MateTurn | null {
    const row = this.db.prepare("SELECT * FROM mate_turn WHERE id = ?").get(id);
    return row === undefined ? null : readMateTurn(row);
  }

  liveMateTurnFor(approver: string): MateTurn | null {
    const row = this.db.prepare("SELECT * FROM mate_turn WHERE approver = ? AND state IN ('queued','running') ORDER BY id DESC LIMIT 1").get(approver);
    return row === undefined ? null : readMateTurn(row);
  }

  mateStepsOf(mateTurn: number): ChatTurn[] {
    return this.db.prepare("SELECT * FROM chat_turn WHERE mate_turn = ? ORDER BY id ASC").all(mateTurn).map(readChatTurn);
  }

  // ---- projects ------------------------------------------------------------

  /** Remember a project was opened. Upsert keeps added_at; recency always moves.
   * A project added for the first time starts on Quick checks. */
  upsertProject(path: string, name: string, now: Date): void {
    this.transact(() => {
      const added = this.db.prepare("SELECT 1 FROM project WHERE path = ?").get(path) === undefined;
      this.db
        .prepare(
          `INSERT INTO project (path, name, added_at, last_opened_at) VALUES (?, ?, ?, ?)
           ON CONFLICT (path) DO UPDATE SET name = excluded.name, last_opened_at = excluded.last_opened_at`,
        )
        .run(path, name, now.toISOString(), now.toISOString());
      if (added) stampNewProjectLevel(this, path, now);
    });
  }

  /** Most recently opened first — the opener page's order. */
  listProjects(): { path: string; name: string; addedAt: string; lastOpenedAt: string }[] {
    return this.db
      .prepare("SELECT * FROM project ORDER BY last_opened_at DESC")
      .all()
      .map(row => ({
        path: String(row["path"]),
        name: String(row["name"]),
        addedAt: String(row["added_at"]),
        lastOpenedAt: String(row["last_opened_at"]),
      }));
  }

  /**
   * Tasks whose scope waits on a person's yes: proposed, not approved (or
   * approval voided by an edit), task not terminal. The inbox's core row —
   * an unapproved scope is work the machine is forbidden to start.
   */
  scopesAwaitingApproval(
    repo: string | null,
    limit = 10,
    admitted: string[] | null = null,
  ): { taskId: string; title: string; goal: string; digest: string; proposedAt: string; repo: string | null }[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 50));
    // Roll-up admission binds BEFORE the LIMIT (Codex roll-up review,
    // finding 2): a repo outside the ceiling must not consume the page.
    const admission =
      admitted === null
        ? "(? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)"
        : `(task_ref.repo IS NULL${admitted.length === 0 ? "" : ` OR task_ref.repo IN (${admitted.map(() => "?").join(",")})`})`;
    const params = admitted === null ? [repo, repo] : admitted;
    return this.db
      .prepare(
        `SELECT task.id AS task_id, task.title, task_scope.goal, task_scope.digest, task_scope.proposed_at, task_ref.repo AS task_repo
         FROM task_scope
         JOIN task ON task.id = task_scope.task_id
         JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
         WHERE task.state IN ('queued','running')
           AND (task_scope.approved_at IS NULL OR task_scope.approved_by IS NULL
                OR task_scope.approved_digest IS NULL OR task_scope.approved_digest != task_scope.digest)
           AND ${admission}
         ORDER BY task_scope.proposed_at, task.id LIMIT ?`,
      )
      .all(BUILT_IN, ...params, page)
      .map(row => ({
        taskId: String(row["task_id"]),
        title: String(row["title"]),
        goal: String(row["goal"]),
        digest: String(row["digest"]),
        proposedAt: String(row["proposed_at"]),
        repo: row["task_repo"] === null || row["task_repo"] === undefined ? null : String(row["task_repo"]),
      }));
  }

  /**
   * One row per human-stalled task (v3 review, finding 2): failed, or
   * carrying unresolved incidents, and free of live claims — requeue is the
   * one inline verb, and incident kinds ride along as context, never as
   * separate cards.
   */
  listRequeueablesScoped(
    repo: string | null,
    now: Date,
    limit = 10,
    admitted: string[] | null = null,
  ): { taskId: string; title: string; state: TaskState; strikes: number; incidentCount: number; repo: string | null }[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 50));
    const admission =
      admitted === null
        ? "(? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)"
        : `(task_ref.repo IS NULL${admitted.length === 0 ? "" : ` OR task_ref.repo IN (${admitted.map(() => "?").join(",")})`})`;
    const params = admitted === null ? [repo, repo] : admitted;
    return this.db
      .prepare(
        `WITH open_incidents AS (
           SELECT run.task_ref AS task_ref, COUNT(*) AS incident_count,
                  MIN(incident.created_at) AS oldest
           FROM incident JOIN run ON run.id = incident.run
           WHERE incident.resolved_at IS NULL
           GROUP BY run.task_ref
         )
         SELECT task.id, task.title, task.state, task_ref.strikes, task_ref.repo AS task_repo,
                COALESCE(open_incidents.incident_count, 0) AS incident_count,
                COALESCE(open_incidents.oldest, task.updated_at) AS sort_at
         FROM task
         JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
         LEFT JOIN open_incidents ON open_incidents.task_ref = task_ref.id
         WHERE (task.state = 'failed' OR open_incidents.task_ref IS NOT NULL)
           AND ${admission}
           AND NOT EXISTS (
             SELECT 1 FROM claim
             WHERE claim.task_ref = task_ref.id AND claim.released_at IS NULL
               AND claim.expires_at > ?
               AND claim.lease_generation = (
                 SELECT MAX(newest.lease_generation) FROM claim AS newest
                 WHERE newest.task_ref = claim.task_ref
               )
           )
         ORDER BY sort_at, task_ref.id LIMIT ?`,
      )
      .all(BUILT_IN, ...params, now.toISOString(), page)
      .map(row => ({
        taskId: String(row["id"]),
        title: String(row["title"]),
        state: String(row["state"]) as TaskState,
        strikes: Number(row["strikes"]),
        incidentCount: Number(row["incident_count"]),
        repo: row["task_repo"] === null || row["task_repo"] === undefined ? null : String(row["task_repo"]),
      }));
  }

  /**
   * Cancelled blockers with queued dependents — one repair card per
   * blocker, because a cancelled task cannot be requeued; the dependents
   * are impact, not additional items.
   */
  listCancelledBlockersScoped(
    repo: string | null,
    limit = 10,
    admitted: string[] | null = null,
  ): { blockerId: string; dependentCount: number; exampleDependent: string; repo: string | null; blockerRepo: string | null }[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 50));
    // Edges may cross projects, and "cancelled" is a fact about the
    // BLOCKER's project (Codex roll-up review, finding 4): both refs are
    // joined, both repos returned and admitted BEFORE aggregation, and the
    // grouping carries the pair so one blocker's impact never aggregates
    // across a ceiling the caller must re-prove row by row.
    const admissionOf = (alias: string): string =>
      admitted === null
        ? `(? IS NULL OR ${alias}.repo IS NULL OR ${alias}.repo = ?)`
        : `(${alias}.repo IS NULL${admitted.length === 0 ? "" : ` OR ${alias}.repo IN (${admitted.map(() => "?").join(",")})`})`;
    const paramsOf = (): unknown[] => (admitted === null ? [repo, repo] : [...admitted]);
    return this.db
      .prepare(
        `SELECT task_edge.blocker AS blocker, COUNT(*) AS dependents, MIN(task_edge.blocked) AS example,
                dependent_ref.repo AS dependent_repo, blocker_ref.repo AS blocker_repo
         FROM task_edge
         JOIN task AS blocker_task ON blocker_task.id = task_edge.blocker AND blocker_task.state = 'cancelled'
         JOIN task AS dependent ON dependent.id = task_edge.blocked AND dependent.state = 'queued'
         JOIN task_ref AS dependent_ref ON dependent_ref.backend = ? AND dependent_ref.external_id = task_edge.blocked
         JOIN task_ref AS blocker_ref ON blocker_ref.backend = ? AND blocker_ref.external_id = task_edge.blocker
         WHERE ${admissionOf("dependent_ref")}
           AND ${admissionOf("blocker_ref")}
         GROUP BY task_edge.blocker, dependent_ref.repo, blocker_ref.repo
         ORDER BY task_edge.blocker LIMIT ?`,
      )
      .all(BUILT_IN, BUILT_IN, ...paramsOf(), ...paramsOf(), page)
      .map(row => ({
        blockerId: String(row["blocker"]),
        dependentCount: Number(row["dependents"]),
        exampleDependent: String(row["example"]),
        repo: row["dependent_repo"] === null || row["dependent_repo"] === undefined ? null : String(row["dependent_repo"]),
        blockerRepo: row["blocker_repo"] === null || row["blocker_repo"] === undefined ? null : String(row["blocker_repo"]),
      }));
  }

  /**
   * Active work only, running first — the Work tab's page. Terminal history
   * belongs to Done and the build ledger, never to this list.
   */
  listActiveWorkScoped(
    repo: string | null,
    now: Date,
    limit = 50,
  ): (Task & { repo: string | null; approved: boolean; held: boolean; buildingBy: string | null; strikes: number })[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 100));
    return this.db
      .prepare(
        `SELECT task.*, task_ref.repo AS task_repo, task_ref.strikes AS ref_strikes,
           EXISTS (
             SELECT 1 FROM task_scope
             WHERE task_scope.task_id = task.id AND task_scope.approved_digest = task_scope.digest
               AND task_scope.approved_at IS NOT NULL
           ) AS approved,
           EXISTS (
             SELECT 1 FROM hold
             WHERE hold.task_ref = task_ref.id AND (hold.until IS NULL OR hold.until > ?)
           ) AS held,
           (SELECT claim.runner FROM claim
             WHERE claim.task_ref = task_ref.id AND claim.released_at IS NULL AND claim.expires_at > ?
               AND claim.lease_generation = (
                 SELECT MAX(newest.lease_generation) FROM claim AS newest
                 WHERE newest.task_ref = claim.task_ref)
             LIMIT 1) AS building_by
         FROM task
         JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
         WHERE task.state IN ('running','queued')
           AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
         ORDER BY CASE task.state WHEN 'running' THEN 0 ELSE 1 END, task.updated_at DESC, task.id DESC
         LIMIT ?`,
      )
      .all(now.toISOString(), now.toISOString(), BUILT_IN, repo, repo, page)
      .map(row => ({
        id: String(row["id"]),
        title: String(row["title"]),
        state: String(row["state"]) as TaskState,
        createdAt: String(row["created_at"]),
        updatedAt: String(row["updated_at"]),
        priority: row["priority"] === null || row["priority"] === undefined ? 0 : Number(row["priority"]),
        repo: row["task_repo"] === null ? null : String(row["task_repo"]),
        approved: Number(row["approved"]) === 1,
        held: Number(row["held"]) === 1,
        buildingBy: row["building_by"] === null ? null : String(row["building_by"]),
        strikes: Number(row["ref_strikes"]),
      }));
  }

  /**
   * Completed work, one row per done task with its final accepted run and
   * any publication attached — never composed from separate task and PR
   * lists (v3 review, finding 8). Manual done-without-run rows stay
   * visible; no-change is labeled, not hidden.
   */
  listCompletedWorkScoped(
    repo: string | null,
    limit = 50,
    admitted: string[] | null = null,
  ): {
    taskId: string;
    title: string;
    repo: string | null;
    completedAt: string;
    outcome: string | null;
    handoff: string | null;
    costUsd: number | null;
    provider: string | null;
    authMode: "subscription" | "api-key" | null;
    ranMinutes: number | null;
    prNumber: number | null;
    prUrl: string | null;
    publicationState: string | null;
    runId: number | null;
    proofVerdict: ProofVerdictRow["verdict"] | null;
    proofMatrix: CriterionMatrixRow[];
    proofAccepted: boolean;
  }[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 100));
    // Admission binds BEFORE the LIMIT here exactly as in the board's
    // task query (attended review, finding 3): rolled-up done rows must
    // not spend the page on repos the ceiling hides.
    const admission =
      admitted === null ? "" : `AND (task_ref.repo IS NULL OR task_ref.repo IN (${admitted.map(() => "?").join(",")}))`;
    return this.db
      .prepare(
        `WITH completed AS (
           SELECT task.id, task.title, task.updated_at AS completed_at, task_ref.id AS ref_id,
                  task_ref.repo AS task_repo
           FROM task
           JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
           WHERE task.state = 'done'
             AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
             ${admission}
         )
         SELECT completed.*, run.id AS run_id, run.outcome, run.handoff, run.cost_usd, run.provider, run.auth_mode, run.started_at, run.finished_at,
                publication.state AS pub_state, publication.pr_number, publication.pr_url,
                proof_verdict.verdict AS proof_verdict, proof_verdict.matrix_json AS proof_matrix_json, proof_acceptance.run AS proof_accepted_run
         FROM completed
         LEFT JOIN run ON run.id = (
           SELECT MAX(final.id) FROM run AS final
           WHERE final.task_ref = completed.ref_id
             AND final.outcome IN ('built','no-change') AND final.finished_at IS NOT NULL
             AND final.role IN ('builder','scout')
         )
         LEFT JOIN publication ON publication.run = run.id
         LEFT JOIN proof_verdict ON proof_verdict.run = run.id
         LEFT JOIN proof_acceptance ON proof_acceptance.run = run.id
         ORDER BY completed.completed_at DESC, completed.id DESC LIMIT ?`,
      )
      .all(BUILT_IN, repo, repo, ...(admitted ?? []), page)
      .map(row => ({
        taskId: String(row["id"]),
        title: String(row["title"]),
        repo: row["task_repo"] === null || row["task_repo"] === undefined ? null : String(row["task_repo"]),
        completedAt: String(row["completed_at"]),
        outcome: row["outcome"] === null ? null : String(row["outcome"]),
        handoff: row["handoff"] === null ? null : String(row["handoff"]),
        costUsd: row["cost_usd"] === null ? null : Number(row["cost_usd"]),
        provider: row["provider"] === null || row["provider"] === undefined ? null : String(row["provider"]),
        authMode:
          row["auth_mode"] === "subscription" || row["auth_mode"] === "api-key"
            ? row["auth_mode"]
            : null,
        ranMinutes:
          row["started_at"] === null || row["finished_at"] === null || row["started_at"] === undefined
            ? null
            : Math.max(1, Math.round((new Date(String(row["finished_at"])).getTime() - new Date(String(row["started_at"])).getTime()) / 60_000)),
        prNumber: row["pr_number"] === null ? null : Number(row["pr_number"]),
        prUrl: row["pr_url"] === null ? null : String(row["pr_url"]),
        publicationState: row["pub_state"] === null ? null : String(row["pub_state"]),
        runId: row["run_id"] === null || row["run_id"] === undefined ? null : Number(row["run_id"]),
        proofVerdict: row["proof_verdict"] === null || row["proof_verdict"] === undefined ? null : (String(row["proof_verdict"]) as ProofVerdictRow["verdict"]),
        proofMatrix: readMatrixJson(row["proof_matrix_json"]),
        proofAccepted: row["proof_accepted_run"] !== null && row["proof_accepted_run"] !== undefined,
      }));
  }

  /**
   * The portfolio's ledger (portfolio arc, slice 1a): terminal runs started
   * since the window opened, one row per run with its task's title and any
   * publication — one joined read instead of per-row lookups. The outcome
   * predicate is `IS NOT NULL` exactly: every terminal outcome renders its
   * own chip; unfinished runs belong to the running section or the
   * reconciler, never this ledger. `publication.run` is unique, so the left
   * join cannot duplicate a run. Admission binds INSIDE the WHERE, before
   * ORDER BY and LIMIT, like every rolled-up read — the caller still
   * re-proves each row's repo against the ceiling.
   */
  portfolioLedgerScoped(
    repo: string | null,
    since: string,
    limit: number,
    admitted: string[] | null,
  ): {
    runId: number;
    taskId: string;
    title: string;
    repo: string | null;
    outcome: string;
    /** The run's role — a scout's row says "report" where a build says PR. */
    role: string;
    provider: string | null;
    model: string | null;
    startedAt: string;
    ranMinutes: number | null;
    costUsd: number | null;
    authMode: "subscription" | "api-key" | null;
    prNumber: number | null;
    prUrl: string | null;
  }[] {
    const page = Math.max(1, Math.min(Math.floor(limit), 100));
    const admission =
      admitted === null ? "" : `AND (task_ref.repo IS NULL OR task_ref.repo IN (${admitted.map(() => "?").join(",")}))`;
    return this.db
      .prepare(
        `SELECT run.id AS run_id, run.outcome, run.role, run.provider, run.model, run.cost_usd, run.auth_mode,
                run.started_at, run.finished_at,
                task_ref.external_id AS task_id, task_ref.repo AS task_repo, task.title AS title,
                publication.pr_number, publication.pr_url
         FROM run
         JOIN task_ref ON task_ref.id = run.task_ref
         LEFT JOIN task ON task_ref.backend = ? AND task.id = task_ref.external_id
         LEFT JOIN publication ON publication.run = run.id
         WHERE run.started_at >= ? AND run.outcome IS NOT NULL
           AND (? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)
           ${admission}
         ORDER BY run.id DESC LIMIT ?`,
      )
      .all(BUILT_IN, since, repo, repo, ...(admitted ?? []), page)
      .map(row => ({
        runId: Number(row["run_id"]),
        taskId: String(row["task_id"]),
        title: row["title"] === null || row["title"] === undefined ? String(row["task_id"]) : String(row["title"]),
        repo: row["task_repo"] === null || row["task_repo"] === undefined ? null : String(row["task_repo"]),
        outcome: String(row["outcome"]),
        role: String(row["role"] ?? "builder"),
        provider: row["provider"] === null || row["provider"] === undefined ? null : String(row["provider"]),
        model: row["model"] === null || row["model"] === undefined ? null : String(row["model"]),
        startedAt: String(row["started_at"]),
        ranMinutes:
          row["finished_at"] === null || row["finished_at"] === undefined
            ? null
            : Math.max(1, Math.round((new Date(String(row["finished_at"])).getTime() - new Date(String(row["started_at"])).getTime()) / 60_000)),
        costUsd: row["cost_usd"] === null ? null : Number(row["cost_usd"]),
        authMode:
          row["auth_mode"] === "subscription" || row["auth_mode"] === "api-key"
            ? row["auth_mode"]
            : null,
        prNumber: row["pr_number"] === null || row["pr_number"] === undefined ? null : Number(row["pr_number"]),
        prUrl: row["pr_url"] === null || row["pr_url"] === undefined ? null : String(row["pr_url"]),
      }));
  }

  /**
   * Everything the board needs, in one snapshot: every non-terminal task's
   * lane-relevant facts plus the recent completions, fetched inside a single
   * transaction so a concurrent writer cannot make one card appear in two
   * lanes or in none (Codex board review, finding 2). Classification itself
   * is the pure function in board.ts — this method only gathers facts.
   *
   * Bounded honestly: at most `cap` active tasks, newest first; when the
   * cap is hit `saturated` says so, and the board's lane totals speak only
   * for what was fetched.
   */
  boardScoped(
    repo: string | null,
    now: Date,
    cap = 200,
    admitted: string[] | null = null,
  ): {
    /** blockerRepo rides along so the caller can redact blockerState
     * against its ceiling before the pure classifier ever sees it. */
    tasks: (BoardFacts & { blockerRepo: string | null })[];
    saturated: boolean;
    done: ReturnType<Store["listCompletedWorkScoped"]>;
  } {
    const page = Math.max(1, Math.min(Math.floor(cap), 500));
    // The admission set is applied BEFORE the limit (Codex round 2,
    // finding 11): in the roll-up, rows outside the ceiling must not
    // consume the page and crowd out admitted cards. Serve still filters
    // per-row afterward — this is the bound, that is the law.
    const admission =
      admitted === null
        ? "(? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)"
        : `(task_ref.repo IS NULL OR task_ref.repo IN (${admitted.map(() => "?").join(",")}))`;
    const admissionParams = admitted === null ? [repo, repo] : admitted;

    const columns = `
        SELECT task.id, task.title, task.state, task.updated_at, task.priority, task_ref.strikes, task_ref.repo AS task_repo,
             EXISTS (SELECT 1 FROM task_scope WHERE task_scope.task_id = task.id) AS has_scope,
             EXISTS (
               SELECT 1 FROM task_scope
               WHERE task_scope.task_id = task.id AND task_scope.approved_digest = task_scope.digest
                 AND task_scope.approved_at IS NOT NULL
             ) AS approved,
             (SELECT substr(task_scope.goal, 1, 90) FROM task_scope WHERE task_scope.task_id = task.id) AS goal,
             (SELECT decision.id FROM decision JOIN run ON run.id = decision.run
               WHERE run.task_ref = task_ref.id AND decision.answered_at IS NULL
               ORDER BY decision.id LIMIT 1) AS open_decision,
             (SELECT substr(decision.question, 1, 120) FROM decision JOIN run ON run.id = decision.run
               WHERE run.task_ref = task_ref.id AND decision.answered_at IS NULL
               ORDER BY decision.id LIMIT 1) AS open_question,
             (SELECT decision.created_at FROM decision JOIN run ON run.id = decision.run
               WHERE run.task_ref = task_ref.id AND decision.answered_at IS NULL
               ORDER BY decision.id LIMIT 1) AS open_decision_at,
             (SELECT COUNT(*) FROM incident JOIN run ON run.id = incident.run
               WHERE run.task_ref = task_ref.id AND incident.resolved_at IS NULL) AS open_incidents,
             (SELECT MIN(incident.created_at) FROM incident JOIN run ON run.id = incident.run
               WHERE run.task_ref = task_ref.id AND incident.resolved_at IS NULL) AS oldest_incident_at,
             task_ref.plan AS plan_state,
             task_ref.routine_id AS routine_id,
             (SELECT routine.name FROM routine WHERE routine.id = task_ref.routine_id) AS routine_name,
             live.runner AS claim_runner, live.acquired_at AS claim_at, live.lease_id AS claim_lease,
             claim_run.model AS claim_model, claim_run.branch AS claim_branch, claim_run.worktree AS claim_worktree,
             claim_run.role AS claim_role, claim_run.provider AS claim_provider, claim_run.phase AS claim_phase,
             (SELECT MAX(unfinished.id) FROM run AS unfinished
               WHERE unfinished.lease_id = live.lease_id AND unfinished.outcome IS NULL) AS live_run_id,
             task_ref.assigned_runner AS assigned_runner,
             (SELECT hold.owner_kind FROM hold
               WHERE hold.task_ref = task_ref.id AND (hold.until IS NULL OR hold.until > ?)
               ORDER BY CASE hold.owner_kind WHEN 'operator' THEN 0 WHEN 'backoff' THEN 1 WHEN 'decision' THEN 2 ELSE 3 END, hold.id
               LIMIT 1) AS hold_kind,
             (SELECT hold.until FROM hold
               WHERE hold.task_ref = task_ref.id AND (hold.until IS NULL OR hold.until > ?)
               ORDER BY CASE hold.owner_kind WHEN 'operator' THEN 0 WHEN 'backoff' THEN 1 WHEN 'decision' THEN 2 ELSE 3 END, hold.id
               LIMIT 1) AS hold_until,
             (SELECT task_edge.blocker FROM task_edge
               JOIN task AS blocker_task ON blocker_task.id = task_edge.blocker
               WHERE task_edge.blocked = task.id AND blocker_task.state != 'done'
               ORDER BY task_edge.blocker LIMIT 1) AS unmet_dependency,
             (SELECT blocker_task.state FROM task_edge
               JOIN task AS blocker_task ON blocker_task.id = task_edge.blocker
               WHERE task_edge.blocked = task.id AND blocker_task.state != 'done'
               ORDER BY task_edge.blocker LIMIT 1) AS blocker_state,
             (SELECT blocker_ref.repo FROM task_edge
               JOIN task AS blocker_task ON blocker_task.id = task_edge.blocker
               JOIN task_ref AS blocker_ref ON blocker_ref.backend = task_ref.backend AND blocker_ref.external_id = task_edge.blocker
               WHERE task_edge.blocked = task.id AND blocker_task.state != 'done'
               ORDER BY task_edge.blocker LIMIT 1) AS blocker_repo,
             (SELECT contest.id FROM contest WHERE contest.task_ref = task_ref.id
                AND contest.state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted')
               ORDER BY contest.id DESC LIMIT 1) AS contest_id,
             (SELECT contest.state FROM contest WHERE contest.task_ref = task_ref.id
                AND contest.state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted')
               ORDER BY contest.id DESC LIMIT 1) AS contest_state,
             (SELECT contest.kind FROM contest WHERE contest.task_ref = task_ref.id
                AND contest.state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted')
               ORDER BY contest.id DESC LIMIT 1) AS contest_kind,
             (SELECT COUNT(*) FROM contestant WHERE contestant.contest =
               (SELECT contest.id FROM contest WHERE contest.task_ref = task_ref.id
                  AND contest.state IN ('dispatching','racing','pick-wait','decision-wait','exhausted','interrupted')
                ORDER BY contest.id DESC LIMIT 1)) AS contest_agents,
             (SELECT requirement.value FROM json_each(task_ref.capability_requirements) AS requirement
               WHERE task_ref.repo IS NOT NULL AND NOT EXISTS (
                 SELECT 1 FROM capability
                 WHERE capability.repo = task_ref.repo AND capability.status = 'verified'
                   AND (capability.expires_at IS NULL OR capability.expires_at > ?)
                   AND capability.kind || ':' || capability.name = requirement.value
               ) LIMIT 1) AS missing_requirement
           FROM task
           JOIN task_ref ON task_ref.backend = ? AND task_ref.external_id = task.id
           LEFT JOIN claim AS live ON live.task_ref = task_ref.id
             AND live.released_at IS NULL AND live.expires_at > ?
             AND live.lease_generation = (
               SELECT MAX(newest.lease_generation) FROM claim AS newest
               WHERE newest.task_ref = live.task_ref
             )
           LEFT JOIN run AS claim_run ON claim_run.id = (
             SELECT MAX(candidate.id) FROM run AS candidate WHERE candidate.lease_id = live.lease_id
           )
           WHERE task.state IN ('queued','running','failed')
             AND ${admission}`;
    const shared = [now.toISOString(), now.toISOString(), now.toISOString(), BUILT_IN, now.toISOString(), ...admissionParams];

    return this.transact(() => {
      // Two bounded pages, one snapshot (Codex round 2, finding 11): the
      // newest active work, PLUS the oldest attention candidates by their
      // stall anchor — an old stalled task must not fall off the board
      // just because two hundred newer things moved. The predicate here
      // only SELECTS candidates; the classifier in board.ts still owns
      // what attention means.
      const newest = this.db
        .prepare(`${columns}
           ORDER BY task.updated_at DESC, task.id DESC
           LIMIT ?`)
        .all(...shared, page);
      const attentionPage = Math.min(page, 100);
      const stalled = this.db
        .prepare(`${columns}
             AND (
               task.state = 'failed'
               OR EXISTS (SELECT 1 FROM incident JOIN run ON run.id = incident.run
                          WHERE run.task_ref = task_ref.id AND incident.resolved_at IS NULL)
               OR EXISTS (SELECT 1 FROM decision JOIN run ON run.id = decision.run
                          WHERE run.task_ref = task_ref.id AND decision.answered_at IS NULL)
               OR NOT EXISTS (SELECT 1 FROM task_scope
                              WHERE task_scope.task_id = task.id AND task_scope.approved_digest = task_scope.digest
                                AND task_scope.approved_at IS NOT NULL)
             )
           ORDER BY COALESCE(open_decision_at, oldest_incident_at, task.updated_at) ASC, task.id
           LIMIT ?`)
        .all(...shared, attentionPage);

      // Every column's HEAD is pinned onto the page (queue-columns review,
      // finding 14): after a drag, whole columns carry positive ranks, so
      // "priority > 0" would let long columns crowd out a short column's
      // front card. One head per (worker, repo) partition instead.
      const promoted = this.db
        .prepare(`SELECT * FROM (
             SELECT ranked.*, ROW_NUMBER() OVER (
               PARTITION BY ranked.assigned_runner, ranked.task_repo
               ORDER BY ranked.priority DESC, ranked.updated_at, ranked.id
             ) AS in_column
             FROM (${columns} AND task.state = 'queued') AS ranked
           ) WHERE in_column = 1
           LIMIT ?`)
        .all(...shared, Math.min(page, 50));

      const seen = new Set<string>();
      const rows = [...newest, ...stalled, ...promoted].filter(row => {
        const id = String(row["id"]);
        if (seen.has(id)) return false;
        seen.add(id);
        return true;
      });

      const text = (row: Record<string, unknown>, key: string): string | null =>
        row[key] === null || row[key] === undefined ? null : String(row[key]);

      const tasks = rows.map(row => ({
        taskId: String(row["id"]),
        title: String(row["title"]),
        repo: text(row, "task_repo"),
        state: String(row["state"]) as "queued" | "running" | "failed",
        updatedAt: String(row["updated_at"]),
        strikes: Number(row["strikes"]),
        hasScope: Number(row["has_scope"]) === 1,
        approved: Number(row["approved"]) === 1,
        plan:
          row["plan_state"] === null || row["plan_state"] === undefined
            ? null
            : (String(row["plan_state"]) as "requested" | "drafted"),
        goal: text(row, "goal"),
        openDecisionId:
          row["open_decision"] === null || row["open_decision"] === undefined
            ? null
            : Number(row["open_decision"]),
        question: text(row, "open_question"),
        decisionCreatedAt: text(row, "open_decision_at"),
        openIncidents: Number(row["open_incidents"]),
        oldestIncidentAt: text(row, "oldest_incident_at"),
        claim:
          row["claim_runner"] === null || row["claim_runner"] === undefined
            ? null
            : {
                runner: String(row["claim_runner"]),
                claimedAt: String(row["claim_at"]),
                model: text(row, "claim_model"),
                branch: text(row, "claim_branch"),
                worktree: text(row, "claim_worktree"),
                role: text(row, "claim_role"),
                provider: text(row, "claim_provider"),
                phase: text(row, "claim_phase"),
              },
        liveRunId:
          row["live_run_id"] === null || row["live_run_id"] === undefined
            ? null
            : Number(row["live_run_id"]),
        priority: row["priority"] === null || row["priority"] === undefined ? 0 : Number(row["priority"]),
        assignedRunner:
          row["assigned_runner"] === null || row["assigned_runner"] === undefined ? null : String(row["assigned_runner"]),
        hold:
          row["hold_kind"] === null || row["hold_kind"] === undefined
            ? null
            : {
                ownerKind: String(row["hold_kind"]) as "operator" | "decision" | "incident" | "backoff",
                until: text(row, "hold_until"),
              },
        unmetDependency: text(row, "unmet_dependency"),
        blockerState: text(row, "blocker_state"),
        blockerRepo: text(row, "blocker_repo"),
        missingRequirement: text(row, "missing_requirement"),
        contest:
          row["contest_id"] === null || row["contest_id"] === undefined
            ? null
            : { id: Number(row["contest_id"]), state: String(row["contest_state"]), agents: Number(row["contest_agents"]), kind: (String(row["contest_kind"] ?? "race") === "comparison" ? "comparison" : "race") as "race" | "comparison" },
        routineId:
          row["routine_id"] === null || row["routine_id"] === undefined
            ? null
            : Number(row["routine_id"]),
        routineName: text(row, "routine_name"),
      }));
      return {
        tasks,
        saturated: newest.length === page,
        done: this.listCompletedWorkScoped(repo, 10, admitted),
      };
    });
  }

  /** Whether an open CI-failure episode exists for a PR — observed, never inferred. */
  ciFailureObserved(prNumber: number): boolean {
    const row = this.db
      .prepare(
        "SELECT 1 AS hit FROM notification WHERE dedupe_key LIKE ? AND resolved_at IS NULL LIMIT 1",
      )
      .get(`ci:${prNumber}:%`);
    return row !== undefined;
  }

  /**
   * The inbox badge, saturated: counts action items up to a cap so the
   * sidebar never pays for an unbounded scan (v3 review, finding 7).
   * Requirement gaps are excluded here — they are derived, not stored —
   * and the inbox page itself shows them; the badge under-counting a gap
   * is a smaller wrong than a full graph walk on every render.
   */
  /** A cheap at-a-glance PEEK into one project for the switcher cards
   * (v30 UI): things waiting on a person, work queued, work running, and
   * builds that finished in the last day — each a single COUNT, scoped to
   * this exact repo. Never an unbounded read. */
  projectPeek(repo: string, now: Date): { waiting: number; queued: number; running: number; doneRecently: number } {
    const waiting = this.countInboxScoped(repo, now).count;
    const q = this.db
      .prepare(
        `SELECT
           SUM(CASE WHEN task.state = 'queued' THEN 1 ELSE 0 END) AS queued,
           SUM(CASE WHEN task.state = 'running' THEN 1 ELSE 0 END) AS running
           FROM task JOIN task_ref ON task_ref.backend = 'built-in' AND task_ref.external_id = task.id
          WHERE task_ref.repo = ?`,
      )
      .get(repo) as { queued: number | null; running: number | null };
    const since = new Date(now.getTime() - 24 * 60 * 60_000).toISOString();
    const done = this.db
      .prepare(
        `SELECT COUNT(*) AS n FROM run
           JOIN task_ref ON task_ref.id = run.task_ref
          WHERE task_ref.repo = ? AND run.role IN ('builder','scout')
            AND run.outcome IN ('built','no-change') AND run.finished_at IS NOT NULL AND run.finished_at >= ?`,
      )
      .get(repo, since) as { n: number };
    return { waiting: waiting, queued: Number(q.queued ?? 0), running: Number(q.running ?? 0), doneRecently: Number(done.n) };
  }

  countInboxScoped(
    repo: string | null,
    now: Date,
    cap = 100,
    admitted: string[] | null = null,
  ): { count: number; saturated: boolean } {
    // Roll-up admission binds inside EVERY union branch (Codex roll-up
    // review, finding 11): with repo NULL the old predicate admitted every
    // stored project, ceiling or not. An empty admitted list reduces to
    // unplaced rows only — never IN ().
    const admission =
      admitted === null
        ? "(? IS NULL OR task_ref.repo IS NULL OR task_ref.repo = ?)"
        : `(task_ref.repo IS NULL${admitted.length === 0 ? "" : ` OR task_ref.repo IN (${admitted.map(() => "?").join(",")})`})`;
    const params = (): unknown[] => (admitted === null ? [repo, repo] : [...admitted]);
    const row = this.db
      .prepare(
        `SELECT COUNT(*) AS n FROM (
           SELECT 'd' || decision.id AS k FROM decision
             JOIN run ON run.id = decision.run
             JOIN task_ref ON task_ref.id = run.task_ref
             WHERE decision.state IN ('open','expired')
               AND ${admission}
           UNION ALL
           SELECT 'a' || task.id FROM task_scope
             JOIN task ON task.id = task_scope.task_id
             JOIN task_ref ON task_ref.backend = '${'built-in'}' AND task_ref.external_id = task.id
             WHERE task.state IN ('queued','running')
               AND (task_scope.approved_at IS NULL OR task_scope.approved_by IS NULL
                    OR task_scope.approved_digest IS NULL OR task_scope.approved_digest != task_scope.digest)
               AND ${admission}
           UNION ALL
           SELECT 'r' || task.id FROM task
             JOIN task_ref ON task_ref.backend = '${'built-in'}' AND task_ref.external_id = task.id
             WHERE (task.state = 'failed' OR EXISTS (
                 SELECT 1 FROM incident JOIN run ON run.id = incident.run
                 WHERE run.task_ref = task_ref.id AND incident.resolved_at IS NULL))
               AND ${admission}
               AND NOT EXISTS (
                 SELECT 1 FROM claim
                 WHERE claim.task_ref = task_ref.id AND claim.released_at IS NULL AND claim.expires_at > ?
                   AND claim.lease_generation = (
                     SELECT MAX(newest.lease_generation) FROM claim AS newest
                     WHERE newest.task_ref = claim.task_ref))
           UNION ALL
           SELECT DISTINCT 'c' || task_edge.blocker FROM task_edge
             JOIN task AS blocker_task ON blocker_task.id = task_edge.blocker AND blocker_task.state = 'cancelled'
             JOIN task AS dependent ON dependent.id = task_edge.blocked AND dependent.state = 'queued'
             JOIN task_ref ON task_ref.backend = '${"built-in"}' AND task_ref.external_id = task_edge.blocked
             JOIN task_ref AS blocker_ref ON blocker_ref.backend = '${"built-in"}' AND blocker_ref.external_id = task_edge.blocker
             WHERE ${admission}
               AND ${admission.replace(/task_ref\./g, "blocker_ref.")}
           LIMIT ?
         )`,
      )
      .get(...params(), ...params(), ...params(), now.toISOString(), ...params(), ...params(), cap);
    const count = Number(row?.["n"] ?? 0);
    return { count, saturated: count >= cap };
  }

  /** Every repo the queue has ever seen — candidates for the opener, never authorization. */

  /** Every repo the queue has ever seen — candidates for the opener, never authorization. */
  knownRepos(): string[] {
    return this.db
      .prepare(
        `SELECT DISTINCT repo AS path FROM task_ref WHERE repo IS NOT NULL
         UNION SELECT DISTINCT repo FROM capability
         UNION SELECT DISTINCT repo FROM publication_grant`,
      )
      .all()
      .map(row => String(row["path"]));
  }

  // ---- the watch episode ---------------------------------------------------

  /** The night begins: one row per watch, keyed by its incarnation. */
  startWatchEpisode(episode: { repo: string; runner: string; incarnation: string }, now: Date): number {
    const inserted = this.db
      .prepare(
        "INSERT INTO watch_episode (repo, runner, incarnation, started_at) VALUES (?, ?, ?, ?)",
      )
      .run(episode.repo, episode.runner, episode.incarnation, now.toISOString());
    return Number(inserted.lastInsertRowid);
  }

  /** The night ends, with its own numbers. A crash never writes this — and that absence is data. */
  endWatchEpisode(
    incarnation: string,
    totals: { ticks: number; built: number; broke: number },
    now: Date,
  ): void {
    this.db
      .prepare(
        "UPDATE watch_episode SET ended_at = ?, ticks = ?, built = ?, broke = ? WHERE incarnation = ?",
      )
      .run(now.toISOString(), totals.ticks, totals.built, totals.broke, incarnation);
  }

  latestWatchEpisode(repo: string): {
    id: number;
    repo: string;
    runner: string;
    incarnation: string;
    startedAt: string;
    endedAt: string | null;
    ticks: number;
    built: number;
    broke: number;
  } | null {
    const row = this.db
      .prepare("SELECT * FROM watch_episode WHERE repo = ? ORDER BY id DESC LIMIT 1")
      .get(repo);
    if (row === undefined) return null;
    return {
      id: Number(row["id"]),
      repo: String(row["repo"]),
      runner: String(row["runner"]),
      incarnation: String(row["incarnation"]),
      startedAt: String(row["started_at"]),
      endedAt: row["ended_at"] === null ? null : String(row["ended_at"]),
      ticks: Number(row["ticks"]),
      built: Number(row["built"]),
      broke: Number(row["broke"]),
    };
  }

  // ---- the wake sequence ---------------------------------------------------

  /** Something changed that could make work dispatchable. Cheap, and safe anywhere. */
  bumpWake(): void {
    this.db.prepare("UPDATE wake SET seq = seq + 1 WHERE id = 1").run();
  }

  wakeSeq(): number {
    const row = this.db.prepare("SELECT seq FROM wake WHERE id = 1").get();
    return Number(row?.["seq"] ?? 0);
  }

  // ---- the watch lease -----------------------------------------------------

  /**
   * One watch per (runner, repo). Same shape as the bridge's poll lease:
   * takeover on expiry bumps the generation, and the superseded owner's
   * name comes back so its claims can be recovered before anything new
   * dispatches. `watch + cron tick` deliberately does NOT contend here —
   * ordinary claims make that race safe; only watch+watch is an error.
   */
  acquireWatchLease(
    runner: string,
    repo: string,
    owner: string,
    ttlMs: number,
    now: Date,
  ):
    | { ok: true; generation: number; superseded: string | null }
    | { ok: false; reason: "watch-busy"; holder: string; until: string } {
    return this.transact(() => {
      const stamp = now.toISOString();
      const expires = new Date(now.getTime() + ttlMs).toISOString();
      const row = this.db
        .prepare("SELECT * FROM watch_lease WHERE runner = ? AND repo = ?")
        .get(runner, repo);
      if (row === undefined) {
        this.db
          .prepare(
            `INSERT INTO watch_lease (runner, repo, owner, generation, started_at, expires_at, heartbeat_at)
             VALUES (?, ?, ?, 1, ?, ?, ?)`,
          )
          .run(runner, repo, owner, stamp, expires, stamp);
        return { ok: true as const, generation: 1, superseded: null };
      }
      const holder = String(row["owner"]);
      const live = String(row["expires_at"]) > stamp;
      if (live && holder !== owner) {
        return {
          ok: false as const,
          reason: "watch-busy" as const,
          holder,
          until: String(row["expires_at"]),
        };
      }
      const generation = live && holder === owner ? Number(row["generation"]) : Number(row["generation"]) + 1;
      this.db
        .prepare(
          `UPDATE watch_lease SET owner = ?, generation = ?, expires_at = ?, heartbeat_at = ?
            WHERE runner = ? AND repo = ?`,
        )
        .run(owner, generation, expires, stamp, runner, repo);
      return {
        ok: true as const,
        generation,
        superseded: holder === owner ? null : holder,
      };
    });
  }

  heartbeatWatchLease(runner: string, repo: string, owner: string, ttlMs: number, now: Date): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE watch_lease SET expires_at = ?, heartbeat_at = ?
          WHERE runner = ? AND repo = ? AND owner = ? AND expires_at > ?`,
      )
      .run(
        new Date(now.getTime() + ttlMs).toISOString(),
        now.toISOString(),
        runner,
        repo,
        owner,
        now.toISOString(),
      );
    return Number(changes) > 0;
  }

  releaseWatchLease(runner: string, repo: string, owner: string, now: Date): void {
    this.db
      .prepare("UPDATE watch_lease SET expires_at = ? WHERE runner = ? AND repo = ? AND owner = ?")
      .run(now.toISOString(), runner, repo, owner);
  }

  /** The first still-unexpired watch lease this runner holds, if any (arc 2:
   * the takeover door refuses while one exists). */
  liveWatchLeaseOf(runner: string, now: Date): { repo: string; owner: string; until: string } | null {
    const row = this.db
      .prepare("SELECT repo, owner, expires_at FROM watch_lease WHERE runner = ? AND expires_at > ? LIMIT 1")
      .get(runner, now.toISOString());
    return row === undefined
      ? null
      : { repo: String(row["repo"]), owner: String(row["owner"]), until: String(row["expires_at"]) };
  }

  /**
   * Finish everything a dead runner left mid-flight, BY THE RUNS TABLE
   * (arc 2 findings 26/31): every open run recorded against the runner —
   * deliberately NOT filtered on claim released_at, so work whose claim a
   * reaper already released still gets its run finished as interrupted and
   * its task requeued. The requeue guards on the ONE liveness fact: a task
   * some newer live claim owns is that claim's business, not ours. Also
   * sweeps tasks stranded `running` with no open run at all (a prior
   * recovery crashed between finishing the run and requeueing).
   *
   * Shared by the takeover door and the dead-runner reconcile pass (P0.1a),
   * so it answers with WHAT it settled — the run ids it finished and the
   * built-in task ids it returned to the queue — rather than a bare count.
   * Nothing here decides liveness: the caller proves the runner is gone (or
   * is taking its name over) inside the transaction that calls this. What it
   * never does: touch a run that already has an outcome, a run under a live
   * held session, another runner's rows, or a task some newer live lease
   * owns. A second pass over the same runner settles nothing and says so.
   */
  recoverRunnerWork(runner: string, now: Date): RunnerWorkRecovery {
    return this.transact(() => {
      const stamp = now.toISOString();
      const runs: number[] = [];
      const requeued: string[] = [];
      const requeueUnowned = (taskRef: number): void => {
        if (this.currentLiveLease(taskRef, now) !== null) return;
        const ref = this.db
          .prepare("SELECT external_id FROM task_ref WHERE id = ? AND backend = ?")
          .get(taskRef, BUILT_IN);
        if (ref === undefined) return;
        const { changes } = this.db
          .prepare("UPDATE task SET state = 'queued', updated_at = ? WHERE id = ? AND state = 'running'")
          .run(stamp, String(ref["external_id"]));
        if (Number(changes) > 0) requeued.push(String(ref["external_id"]));
      };
      const open = this.db
        .prepare(
          `SELECT id, task_ref FROM run WHERE runner = ? AND outcome IS NULL
            AND NOT EXISTS (SELECT 1 FROM held_session WHERE held_session.run = run.id AND held_session.ended_at IS NULL)
            ORDER BY id`,
        )
        .all(runner);
      for (const row of open) {
        const taskRef = Number(row["task_ref"]);
        const runId = Number(row["id"]);
        // `outcome IS NULL` again on the write: a finished outcome is never
        // rewritten, whatever the survey above saw.
        const { changes } = this.db
          .prepare("UPDATE run SET outcome = 'failed', reason = 'interrupted', finished_at = ? WHERE id = ? AND outcome IS NULL")
          .run(stamp, runId);
        if (Number(changes) === 0) continue;
        runs.push(runId);
        requeueUnowned(taskRef);
        this.db
          .prepare("UPDATE worktree SET released_at = ?, verified = 0 WHERE runner = ? AND task_ref = ? AND released_at IS NULL")
          .run(stamp, runner, taskRef);
      }
      // Stranded `running` tasks whose newest claim was this runner's and
      // whose lease is gone: no open run to finish, still not in the ready
      // set — requeue them too (finding 31's crashed-recovery walk).
      const stranded = this.db
        .prepare(
          `SELECT task_ref.id AS ref, task.id AS task_id FROM task
             JOIN task_ref ON task_ref.external_id = task.id AND task_ref.backend = ?
            WHERE task.state = 'running'
              AND (SELECT claim.runner FROM claim WHERE claim.task_ref = task_ref.id
                    ORDER BY claim.lease_generation DESC LIMIT 1) = ?
              AND NOT EXISTS (SELECT 1 FROM run WHERE run.task_ref = task_ref.id AND run.outcome IS NULL)
              AND NOT EXISTS (SELECT 1 FROM held_session
                              JOIN run AS held_run ON held_run.id = held_session.run
                              WHERE held_run.task_ref = task_ref.id AND held_session.ended_at IS NULL)`,
        )
        .all(BUILT_IN, runner);
      for (const row of stranded) requeueUnowned(Number(row["ref"]));
      // Closing the runner does not prove subprocess exit. Only exact stops
      // whose retained process witnesses are absent can settle; their own
      // holds keep every other recovered attempt paused.
      this.settleQuiescentStops(now);
      if (runs.length > 0 || requeued.length > 0) this.bumpWake();
      return { runs, requeued };
    });
  }

  /**
   * The first-approver door (arc 2 finding 2): INSERT only while the table
   * is EMPTY, one transaction — `up` can never upsert, never rotate an
   * existing password, and two cold starts serialize to one winner.
   */
  bootstrapApproverIfNone(
    name: string,
    credentialHash: string,
    now: Date,
  ): { ok: true } | { ok: false; reason: "approvers-exist" } {
    return this.transact(() => {
      const count = this.db.prepare("SELECT COUNT(*) AS n FROM approver").get();
      if (Number(count?.["n"] ?? 0) > 0) return { ok: false as const, reason: "approvers-exist" as const };
      this.db
        .prepare("INSERT INTO approver (name, credential_hash, added_at, generation) VALUES (?, ?, ?, 1)")
        .run(name, credentialHash, now.toISOString());
      return { ok: true as const };
    });
  }

  /**
   * Recover everything a dead incarnation still holds, atomically, before
   * its successor dispatches anything: its live claims released as
   * 'recovered', their running tasks requeued, their open runs finished as
   * interrupted, their worktrees released unverified. Keyed to the
   * incarnation, never to runner liveness — the successor IS the runner,
   * alive and heartbeating, which is exactly how the crash would otherwise
   * hide.
   */
  recoverIncarnation(runner: string, incarnation: string, now: Date): number {
    return this.transact(() => {
      const stamp = now.toISOString();
      const claims = this.db
        .prepare(
          `SELECT lease_id, task_ref FROM claim
            WHERE runner = ? AND incarnation = ? AND released_at IS NULL
              AND lease_generation = (
                SELECT MAX(newest.lease_generation) FROM claim AS newest
                WHERE newest.task_ref = claim.task_ref
              )`,
        )
        .all(runner, incarnation);

      for (const row of claims) {
        const leaseId = String(row["lease_id"]);
        const taskRef = Number(row["task_ref"]);
        this.db
          .prepare("UPDATE claim SET released_at = ?, released_by = 'recovered' WHERE lease_id = ?")
          .run(stamp, leaseId);
        this.db
          .prepare(
            `UPDATE task SET state = 'queued', updated_at = ?
              WHERE state = 'running' AND id = (
                SELECT external_id FROM task_ref WHERE id = ? AND backend = ?
              )`,
          )
          .run(stamp, taskRef, BUILT_IN);
        this.db
          .prepare(
            `UPDATE run SET outcome = 'failed', reason = 'interrupted', finished_at = ?
              WHERE lease_id = ? AND outcome IS NULL`,
          )
          .run(stamp, leaseId);
        this.db
          .prepare(
            `UPDATE worktree SET released_at = ?, verified = 0
              WHERE runner = ? AND task_ref = ? AND released_at IS NULL`,
          )
          .run(stamp, runner, taskRef);
      }
      // Claims a reaper already released can still have OPEN runs — the
      // reap stamps released_at without finishing anything (arc 2 findings
      // 26/31). Their runs finish as interrupted here and their tasks
      // requeue when no newer live claim owns them, so reaped work cannot
      // stay `running` outside the ready set forever.
      let extra = 0;
      const orphaned = this.db
        .prepare(
          `SELECT run.id AS run_id, run.task_ref AS task_ref FROM run
             JOIN claim ON claim.lease_id = run.lease_id
            WHERE claim.runner = ? AND claim.incarnation = ? AND run.outcome IS NULL`,
        )
        .all(runner, incarnation);
      for (const row of orphaned) {
        const taskRef = Number(row["task_ref"]);
        this.db
          .prepare("UPDATE run SET outcome = 'failed', reason = 'interrupted', finished_at = ? WHERE id = ?")
          .run(stamp, Number(row["run_id"]));
        if (this.currentLiveLease(taskRef, now) === null) {
          this.db
            .prepare(
              `UPDATE task SET state = 'queued', updated_at = ?
                WHERE state = 'running' AND id = (
                  SELECT external_id FROM task_ref WHERE id = ? AND backend = ?
                )`,
            )
            .run(stamp, taskRef, BUILT_IN);
        }
        this.db
          .prepare("UPDATE worktree SET released_at = ?, verified = 0 WHERE runner = ? AND task_ref = ? AND released_at IS NULL")
          .run(stamp, runner, taskRef);
        extra += 1;
      }
      // Reviews have synthetic lease ids, not task claims. Only explicitly
      // bound reviews belong to this dead watch; concurrent cron reviews and
      // another watch's rows must remain untouched.
      const reviews = this.db.prepare(
        "UPDATE run SET outcome = 'failed', reason = 'interrupted', finished_at = ? WHERE runner = ? AND watch_incarnation = ? AND role = 'reviewer' AND outcome IS NULL",
      ).run(stamp, runner, incarnation);
      extra += Number(reviews.changes);
      // The spent request learns its attempt's fate through its v50
      // binding — exactly the root this watch cut down, never an earlier
      // attempt's request on the same source run.
      this.db.prepare(
        "UPDATE review_request SET consumed_reason = 'interrupted' WHERE consumed_reason = 'dispatched' AND reviewer_run IN (SELECT id FROM run WHERE runner = ? AND watch_incarnation = ? AND role = 'reviewer' AND review_attempt IS NOT NULL AND reason = 'interrupted')",
      ).run(runner, incarnation);
      // A dead incarnation can leave live descendants. Keep its stop pending
      // until the separate process-witness check establishes quiescence.
      this.settleQuiescentStops(now);
      if (claims.length + extra > 0) this.bumpWake();
      return claims.length + extra;
    });
  }

  /** Recovery closing a run does not establish provider death. Reconcile
   * each exact pending stop against the retained process witnesses. */
  settleQuiescentStops(now: Date): number {
    return this.transact(() => {
      let settled = 0;
      const pending = this.db.prepare("SELECT run FROM run_stop WHERE settled_at IS NULL ORDER BY run").all();
      for (const row of pending) {
        const id = Number(row["run"]);
        const kind = this.heldSessionOf(id) === null ? "recovered" : "held";
        if (this.settleRunStop(id, kind, now)) settled++;
      }
      if (settled > 0) this.bumpWake();
      return settled;
    });
  }

  // ---- safe task stop and resume (v52) -------------------------------------

  /** The stop recorded against exactly this run, if any. */
  stopOf(runId: number): RunStop | null {
    const row = this.db.prepare("SELECT * FROM run_stop WHERE run = ?").get(runId);
    return row === undefined ? null : readRunStop(row);
  }

  /**
   * The run ids one exact attempt OWNS (v52): the run itself plus every
   * descendant that runs under the SAME lease — a builder's repair turns,
   * a planner's corrections, a root reviewer's correction child. Ownership
   * is the shared lease, never the task: a successor admitted later under
   * a fresh claim, a warm park resume, or a recovered-draft attempt is its
   * own attempt and inherits nothing.
   */
  ownedRunsOf(runId: number): number[] {
    return this.db
      .prepare(
        `WITH RECURSIVE owned(id, lease_id) AS (
           SELECT id, lease_id FROM run WHERE id = ?
           UNION ALL
           SELECT r.id, r.lease_id FROM run r JOIN owned o ON r.parent_run = o.id WHERE r.lease_id = o.lease_id
         ) SELECT id FROM owned ORDER BY id`,
      )
      .all(runId)
      .map(row => Number(row["id"]));
  }

  /**
   * The stop that APPLIES to a run (v52): its own, or the one recorded
   * against an owning ancestor it shares a lease with (a repair turn under
   * a stopped builder, a correction under a stopped root review). Read by
   * every fence — invocation, settlement, ingestion, admission — so a
   * descendant can never finish work its parent was told to stop.
   */
  applicableStopFor(runId: number): RunStop | null {
    const row = this.db
      .prepare(
        `WITH RECURSIVE lineage(id, parent_run, lease_id) AS (
           SELECT id, parent_run, lease_id FROM run WHERE id = ?
           UNION ALL
           SELECT r.id, r.parent_run, r.lease_id FROM run r JOIN lineage l ON r.id = l.parent_run WHERE r.lease_id = l.lease_id
         ) SELECT s.* FROM run_stop s JOIN lineage l ON l.id = s.run ORDER BY s.run LIMIT 1`,
      )
      .get(runId);
    return row === undefined ? null : readRunStop(row);
  }

  /**
   * THE STOP REQUEST (v52): one exact, still-open attempt, recorded
   * durably with who asked and when BEFORE any process is signalled. The
   * transaction proves the run is this task's, is still open, holds the
   * task's CURRENT live claim (a reviewer's synthetic lease counts through
   * its open outcome alone), is not a racing lane (tournaments keep their
   * own controls), and has admitted no publication — an external request
   * in flight is never recalled by a stop, and the words say so. The
   * stop's hold rides the same write, owned by this run, so nothing
   * automatic retries the task while it is paused; a repeated request
   * finds its own row and answers the same, never a second stop.
   */
  requestRunStop(
    args: { runId: number; taskRef: number; by: string; via: StopVia },
    now: Date,
  ):
    | { ok: true; stop: RunStop; repeated: boolean }
    | { ok: false; reason: "no-run" | "wrong-task" | "finished" | "not-live" | "tournament" | "publication"; detail: string } {
    return this.transact(() => {
      const run = this.getRun(args.runId);
      if (run === null) return { ok: false as const, reason: "no-run" as const, detail: `no run #${args.runId}` };
      if (run.taskRef !== args.taskRef) return { ok: false as const, reason: "wrong-task" as const, detail: `run #${args.runId} is not one of this task's attempts` };
      const existing = this.stopOf(args.runId);
      if (existing !== null) return { ok: true as const, stop: existing, repeated: true };
      if (run.parentRun !== null && this.getRun(run.parentRun)?.leaseId === run.leaseId) {
        return { ok: false as const, reason: "not-live" as const, detail: `run #${run.id} belongs to attempt #${run.parentRun}; stop the owning attempt` };
      }
      if (run.outcome !== null) {
        return { ok: false as const, reason: "finished" as const, detail: `run #${args.runId} already ended (${run.outcome}${run.reason === null ? "" : ` · ${run.reason}`}) — a finished attempt is never rewritten by a stop` };
      }
      if (run.contestant !== null) return { ok: false as const, reason: "tournament" as const, detail: `run #${args.runId} is a racing lane — tournaments are stopped through their own pick/abandon controls` };
      if (run.role !== "reviewer") {
        const holding = this.currentLiveLease(run.taskRef, now);
        if (holding !== run.leaseId) {
          return { ok: false as const, reason: "not-live" as const, detail: holding === null ? `run #${args.runId} holds no live claim — recovery settles it, not a stop` : `run #${args.runId} is not the attempt holding this task now` };
        }
      }
      if (this.publicationForRun(args.runId) !== null) {
        return { ok: false as const, reason: "publication" as const, detail: `run #${args.runId} has already admitted its publication — an external request in flight is not recalled by a stop` };
      }
      this.db
        .prepare("INSERT INTO run_stop (run, task_ref, requested_by, requested_via, requested_at) VALUES (?, ?, ?, ?, ?)")
        .run(args.runId, run.taskRef, args.by, args.via, now.toISOString());
      // The pause this stop OWNS: one row keyed to the run, beside — never
      // over — any operator, decision, incident, or backoff hold already
      // standing. A review has no queue to pause (retries are explicit),
      // so a stopped review places none.
      if (run.role !== "reviewer") {
        this.holdOwned(
          { taskRef: run.taskRef, ownerKind: "stop", ownerId: String(args.runId), reason: `stopped by ${args.by} — resume run #${args.runId} when ready`, until: null },
          now,
        );
      }
      this.addRunNote(args.runId, args.by, `Stop requested. The attempt's own processes are being stopped; its work stays preserved and the task stays paused until this exact attempt is resumed.`, now);
      // The stop fact (Telegram task updates): stopping is not pausing —
      // the live processes end, and the pause it OWNS keeps the task until
      // this exact attempt is resumed. A stopped review changes no result.
      const stoppedTask = this.externalIdFor(run.taskRef);
      if (stoppedTask !== null) {
        this.noteLifecycle(
          run.role === "reviewer"
            ? { taskRef: run.taskRef, run: run.id, kind: "run-stopping", identity: `r${run.id}`, subject: `Stopping review #${run.id}`, body: "The review is being stopped. The saved result is unchanged.", link: chatControlHref("recovery", stoppedTask) }
            : { taskRef: run.taskRef, run: run.id, kind: "run-stopping", identity: `r${run.id}`, subject: `Stopping attempt #${run.id}`, body: "Its processes are being stopped and its work is preserved. The task stays paused until this attempt is resumed.", link: chatControlHref("recovery", stoppedTask) },
          now,
        );
      }
      this.bumpWake();
      return { ok: true as const, stop: this.stopOf(args.runId) as RunStop, repeated: false };
    });
  }

  /** Settle a stop — compare-and-set on the unsettled row. True when THIS
   * call settled it; false when it was already settled or never asked. */
  settleRunStop(runId: number, settlement: StopSettlement, now: Date): boolean {
    const stop = this.stopOf(runId);
    if (stop === null || stop.settledAt !== null) return false;
    return this.transact(() => {
      if (this.stopQuiescenceProblem(runId) !== null) return false;
      const recordExit = this.db.prepare("UPDATE run_process SET exited_at = ? WHERE run = ? AND exited_at IS NULL");
      for (const owned of this.ownedRunsOf(runId)) recordExit.run(now.toISOString(), owned);
      const { changes } = this.db
        .prepare("UPDATE run_stop SET settled_at = ?, settlement = ? WHERE run = ? AND settled_at IS NULL")
        .run(now.toISOString(), settlement, runId);
      return Number(changes) > 0;
    });
  }

  /** Every owned run must have ended, and every retained local process
   * witness must be absent. Read-only probes never authorize PID kills. */
  stopQuiescenceProblem(runId: number): string | null {
    return this.stopQuiescenceFact(runId)?.problem ?? null;
  }

  /** The same answer as stopQuiescenceProblem, with which run it names and
   * what kind of answer it is (needs-you.ts reads it): `alive` while
   * something of the run may still be running, `elsewhere` when only
   * another computer can tell, `unprovable` when nothing is known to run
   * but its exit was never recorded, `unknown` when this computer can't
   * check at all (both are what `run settle` resolves; only the first may
   * be called not running). */
  stopQuiescenceFact(runId: number): { run: number; kind: StopFactKind; problem: string } | null {
    const fact = (run: number, kind: StopFactKind, problem: string) => ({ run, kind, problem });
    const ids = this.ownedRunsOf(runId);
    if (ids.length === 0) return fact(runId, "open", `run #${runId} does not exist`);
    for (const id of ids) {
      const run = this.getRun(id)!;
      if (run.outcome === null) return fact(id, "open", `run #${id} is still open`);
      if (ownedProcessCount(runOwnerTag(this, id)) > 0) return fact(id, "alive", `run #${id} still has an owned subprocess`);
      const held = this.heldSessionOf(id);
      if (held !== null && held.endedAt === null) return fact(id, "alive", `run #${id}'s held supervisor has not finished shutdown`);
      const witnesses = this.db.prepare("SELECT * FROM run_process WHERE run = ? ORDER BY id").all(id);
      if (run.providerStartedAt !== null && witnesses.length === 0) {
        return fact(id, "unprovable", `run #${id} may have spawned before its process witness was recorded; exit is unproven`);
      }
      for (const witness of witnesses) {
        if (witness["exited_at"] !== null) continue;
        const host = String(witness["host"]);
        const bootId = witness["boot_id"] === null || witness["boot_id"] === undefined ? null : String(witness["boot_id"]);
        // A VERIFIED boot change on this host (v53): nothing of the old
        // boot survives — an incomplete spawn, a reused pid and a native
        // object alike are gone. Every other case keeps the conservative
        // road below.
        if (provenDeadByBootChange({ host, bootId })) continue;
        if (host !== hostname()) return fact(id, "elsewhere", `run #${id}'s process belongs to another host; exit is unproven here`);
        const backend = witness["containment"] === null || witness["containment"] === undefined ? null : String(witness["containment"]);
        const container = witness["container"] === null || witness["container"] === undefined ? null : String(witness["container"]);
        if (backend !== null || container !== null) {
          if (backend === null || container === null) return fact(id, "unknown", `run #${id} has incomplete native containment custody`);
          if (witness["container_empty_at"] !== null) continue;
          // A native witness settles ONLY on the OS's word: the object is
          // proven empty, or it is gone (an OS object is removable only
          // when empty). A transport exit never proved it.
          const state = containerEmptiness(backend, container, process.platform, witness["container_identity"] == null ? null : String(witness["container_identity"]));
          if (state === "populated") return fact(id, "alive", `run #${id}'s ${backend} object ${container} still has members`);
          if (state === "unknown") return fact(id, "unknown", `run #${id}'s ${backend} object ${container} cannot be proven empty from here`);
          continue;
        }
        if (witness["pid"] === null) return fact(id, "unprovable", `run #${id} has an incomplete spawn witness; exit is unproven`);
        const pid = Number(witness["pid"]);
        if (processMayBeAlive(pid, witness["process_group"] === 1, { observedAt: witness["observed_at"], finishedAt: run.finishedAt })) return fact(id, "alive", `run #${id}'s process ${pid} may still be running`);
      }
      if (run.worktree !== null) {
        try {
          const occupied = worktreeProcessOccupancy(run.worktree);
          if (occupied.held) return fact(id, "alive", `run #${id}'s workspace is still held by process ${occupied.by}`);
        } catch {
          // An unreadable workspace note is no proof either way; an approver's recorded word settles it.
          if (!this.workspaceConfirmedByApprover(id)) return fact(id, "unknown", `run #${id}'s workspace occupancy could not be established`);
        }
      }
    }
    return null;
  }

  /** `run settle` recorded an approver's word that a run whose workspace
   * note couldn't be read has stopped. */
  private workspaceConfirmedByApprover(runId: number): boolean {
    return this.db.prepare("SELECT 1 FROM action_ledger WHERE run_id = ? AND action = 'workspace settled by approver' LIMIT 1").get(runId) !== undefined;
  }

  reserveRunProcess(runId: number, now: Date, group = true): number {
    return Number(this.db.prepare("INSERT INTO run_process (run,host,process_group,observed_at,boot_id) VALUES (?,?,?,?,?)")
      .run(runId, hostname(), group ? 1 : 0, now.toISOString(), currentBootId()).lastInsertRowid);
  }

  /** Save positive OS exit evidence while it is available, before a numeric
   * PID can be reused. Completion, missing ancestry and age prove nothing.
   * Existing rows stay intact; only a previously unknown exit is recorded.
   * This is also safe for reconciling historical rows after a real exit.
   * No PID read from the database is ever signalled except with signal zero. */
  recordRunProcessExits(runId: number, now: Date, only?: { pid: number; group: boolean }): number {
    const rows = only === undefined
      ? this.db.prepare("SELECT * FROM run_process WHERE run = ? AND exited_at IS NULL").all(runId)
      : this.db.prepare("SELECT * FROM run_process WHERE run = ? AND pid = ? AND process_group = ? AND exited_at IS NULL").all(runId, only.pid, only.group ? 1 : 0);
    // A finished run's witness gets the same proof the deploy's quiescence
    // check uses: ESRCH, or a process now holding the pid that was born after
    // the run ended. An open run has no finish time, so only ESRCH counts.
    const finishedAt = this.getRun(runId)?.finishedAt ?? null;
    let recorded = 0;
    for (const row of rows) {
      const host = String(row["host"]), bootId = row["boot_id"] == null ? null : String(row["boot_id"]);
      if (host !== hostname() || typeof row["observed_at"] !== "string" || !Number.isFinite(Date.parse(row["observed_at"])) || Date.parse(row["observed_at"]) > now.getTime()) continue;
      let gone = provenDeadByBootChange({ host, bootId });
      if (!gone) {
        const backend = row["containment"] == null ? null : String(row["containment"]);
        const container = row["container"] == null ? null : String(row["container"]);
        if (backend !== null || container !== null) {
          gone = backend !== null && container !== null && (row["container_empty_at"] != null || containerEmptiness(backend, container, process.platform, row["container_identity"] == null ? null : String(row["container_identity"])) === "empty");
        } else {
          gone = row["pid"] != null && !processMayBeAlive(Number(row["pid"]), row["process_group"] === 1,
            finishedAt === null ? undefined : { observedAt: row["observed_at"], finishedAt });
        }
      }
      if (gone) recorded += Number(this.db.prepare(`UPDATE run_process SET exited_at = ?
        WHERE id = ? AND run = ? AND exited_at IS NULL AND pid IS ? AND host = ? AND process_group = ?
          AND observed_at = ? AND boot_id IS ? AND containment IS ? AND container IS ? AND container_identity IS ?`)
        .run(now.toISOString(), row["id"], runId, row["pid"], row["host"], row["process_group"], row["observed_at"], row["boot_id"], row["containment"], row["container"], row["container_identity"]).changes);
    }
    return recorded;
  }

  /** The reconcile road for a finished run whose process outlived its
   * finish: once each process is provably gone, its exit is recorded, so
   * the task stops waiting on a person by itself. A run that can't be proven
   * yet stays open and is passed over, never holding newer runs behind it:
   * every finished run is visited, a batch at a time. Never signals. */
  recordFinishedRunExits(now: Date, batch = 200): number {
    const page = this.db.prepare(`SELECT DISTINCT p.run FROM run_process p JOIN run r ON r.id = p.run
      WHERE p.exited_at IS NULL AND p.host = ? AND p.run > ? AND r.outcome IS NOT NULL AND r.finished_at IS NOT NULL
      ORDER BY p.run LIMIT ?`);
    let recorded = 0;
    for (let after = 0; ;) {
      const runs = page.all(hostname(), after, batch).map(row => Number(row["run"]));
      for (const run of runs) recorded += this.recordRunProcessExits(run, now);
      if (runs.length < batch) return recorded;
      after = runs[runs.length - 1]!;
    }
  }

  finishUnspawnedProcess(witness: number, now: Date): void {
    this.db.prepare("UPDATE run_process SET exited_at = ? WHERE id = ? AND pid IS NULL AND ((containment IS NULL AND container IS NULL) OR container_empty_at IS NOT NULL)")
      .run(now.toISOString(), witness);
  }

  /** The reconcile road for a pid-less witness a crash or a thrown spawn
   * left behind: once its run has finished, no live child is tracked for it
   * here, every other witness of the run has exited and none of the run's
   * process groups is alive, it settles as never started, with a ledger
   * entry. A sole pid-less witness has no group to prove gone and stays for
   * `run settle`. Native witnesses keep their OS-only road. */
  settleUnspawnedWitnesses(now: Date): number {
    const candidates = this.db.prepare(`SELECT DISTINCT p.run FROM run_process p JOIN run r ON r.id = p.run
      WHERE p.exited_at IS NULL AND p.pid IS NULL AND p.containment IS NULL AND p.container IS NULL
        AND p.host = ? AND r.outcome IS NOT NULL AND r.finished_at IS NOT NULL ORDER BY p.run`).all(hostname());
    let settled = 0;
    for (const candidate of candidates) {
      const runId = Number(candidate["run"]);
      this.recordRunProcessExits(runId, now);
      settled += this.transact(() => {
        const run = this.getRun(runId);
        if (run === null || run.outcome === null) return 0;
        if (ownedProcessCount(runOwnerTag(this, runId)) > 0) return 0;
        const held = this.heldSessionOf(runId);
        if (held !== null && held.endedAt === null) return 0;
        const rows = this.db.prepare("SELECT * FROM run_process WHERE run = ? ORDER BY id").all(runId);
        const pidless = rows.filter(row => row["exited_at"] === null && row["pid"] === null && row["containment"] === null && row["container"] === null && row["host"] === hostname());
        const others = rows.filter(row => !pidless.includes(row));
        if (pidless.length === 0 || others.length === 0) return 0;
        if (others.some(row => row["exited_at"] === null)) return 0;
        // Exit was recorded once; the group's members are asked again now.
        const groups = others.filter(row => row["pid"] !== null && row["host"] === hostname());
        if (groups.length === 0 || groups.some(row => processMayBeAlive(Number(row["pid"]), row["process_group"] === 1, { observedAt: row["observed_at"], finishedAt: run.finishedAt }))) return 0;
        const ref = this.refById(run.taskRef);
        let count = 0;
        for (const row of pidless) {
          const changed = this.db.prepare(`UPDATE run_process SET exited_at = ?
            WHERE id = ? AND run = ? AND pid IS NULL AND exited_at IS NULL AND containment IS NULL AND container IS NULL`)
            .run(now.toISOString(), row["id"], runId);
          if (Number(changed.changes) !== 1) continue;
          count++;
          this.recordAction({ at: now.toISOString(), actor: "system", repo: ref?.repo ?? null, taskId: ref?.externalId ?? null, runId,
            action: "process witness settled", outcome: "never started", source: "work",
            detail: `witness ${String(row["id"])}: no pid; the run finished, every other witness exited and none of its process groups is alive` });
        }
        return count;
      });
    }
    return settled;
  }

  /** `run settle` (an approver's last resort): every witness of a finished
   * run that cannot be proven either way is recorded settled under the
   * approver's reason, in the ledger. Refuses while anything of the run is
   * alive or could be checked only from another host. Never signals. */
  settleRunWitnessesByApprover(args: { runId: number; by: string; why: string }, now: Date):
    | { ok: true; witnesses: number[]; repeated: boolean }
    | { ok: false; reason: "unknown-run" | "still-running" | "alive"; detail: string } {
    return this.transact(() => {
      const run = this.getRun(args.runId);
      if (run === null) return { ok: false as const, reason: "unknown-run" as const, detail: `no run #${args.runId}` };
      if (run.outcome === null) return { ok: false as const, reason: "still-running" as const, detail: `run #${args.runId} is still open` };
      const alive = (detail: string) => ({ ok: false as const, reason: "alive" as const, detail });
      if (ownedProcessCount(runOwnerTag(this, args.runId)) > 0) return alive(`run #${args.runId} still has an owned subprocess`);
      const held = this.heldSessionOf(args.runId);
      if (held !== null && held.endedAt === null) return alive(`run #${args.runId}'s held supervisor has not finished shutdown`);
      const rows = this.db.prepare("SELECT * FROM run_process WHERE run = ? ORDER BY id").all(args.runId);
      const open = rows.filter(row => row["exited_at"] === null);
      for (const row of rows) {
        if (row["pid"] === null) continue;
        if (row["host"] !== hostname()) {
          if (row["exited_at"] === null) return alive(`run #${args.runId}'s process ${String(row["pid"])} belongs to ${String(row["host"])}; settle it there`);
          continue;
        }
        if (processMayBeAlive(Number(row["pid"]), row["process_group"] === 1, { observedAt: row["observed_at"], finishedAt: run.finishedAt })) return alive(`run #${args.runId}'s process ${String(row["pid"])} is still running`);
      }
      for (const row of open) {
        if (row["pid"] === null && row["host"] !== hostname()) return alive(`run #${args.runId} has a witness from ${String(row["host"])}; settle it there`);
        if (row["containment"] != null && row["container"] != null && row["container_empty_at"] == null &&
            containerEmptiness(String(row["containment"]), String(row["container"]), process.platform, row["container_identity"] == null ? null : String(row["container_identity"])) === "populated") {
          return alive(`run #${args.runId}'s ${String(row["containment"])} object ${String(row["container"])} still has members`);
        }
      }
      // A workspace still held by a live process refuses; one whose note can't
      // be read is settled by the approver's word, in the ledger.
      let workspace = false;
      if (run.worktree !== null) {
        try {
          const occupied = worktreeProcessOccupancy(run.worktree);
          if (occupied.held) return alive(`run #${args.runId}'s workspace is still held by process ${occupied.by}`);
        } catch { workspace = !this.workspaceConfirmedByApprover(args.runId); }
      }
      const ref = this.refById(run.taskRef);
      if (workspace) {
        this.recordAction({ at: now.toISOString(), actor: args.by, repo: ref?.repo ?? null, taskId: ref?.externalId ?? null, runId: args.runId,
          action: "workspace settled by approver", outcome: run.worktree ?? "", source: "request", detail: args.why });
      }
      // A run that may have spawned before any witness was written has none
      // to settle: the approver's word is recorded as one ended witness.
      if (rows.length === 0 && run.providerStartedAt !== null) {
        const id = Number(this.db.prepare("INSERT INTO run_process (run,host,process_group,observed_at,boot_id,exited_at) VALUES (?,?,0,?,?,?)")
          .run(args.runId, hostname(), now.toISOString(), currentBootId(), now.toISOString()).lastInsertRowid);
        this.recordAction({ at: now.toISOString(), actor: args.by, repo: ref?.repo ?? null, taskId: ref?.externalId ?? null, runId: args.runId,
          action: "process witness settled by approver", outcome: `witness ${id}`, source: "request", detail: args.why });
        this.settleQuiescentStops(now);
        return { ok: true as const, witnesses: [id], repeated: false };
      }
      if (open.length === 0) {
        if (workspace) this.settleQuiescentStops(now);
        return { ok: true as const, witnesses: [], repeated: !workspace };
      }
      const ids = open.map(row => Number(row["id"]));
      for (const id of ids) this.db.prepare("UPDATE run_process SET exited_at = ? WHERE id = ? AND run = ? AND exited_at IS NULL").run(now.toISOString(), id, args.runId);
      this.recordAction({ at: now.toISOString(), actor: args.by, repo: ref?.repo ?? null, taskId: ref?.externalId ?? null, runId: args.runId,
        action: "process witness settled by approver", outcome: `witness ${ids.join(", ")}`, source: "request", detail: args.why });
      this.settleQuiescentStops(now);
      return { ok: true as const, witnesses: ids, repeated: false };
    });
  }

  recordRunProcess(runId: number, pid: number, now: Date, group = true, witness?: number): void {
    if (!Number.isSafeInteger(pid) || pid <= 0) throw new Error("a process witness needs a valid spawned PID");
    if (witness !== undefined) {
      const changed = this.db.prepare("UPDATE run_process SET pid = ? WHERE id = ? AND run = ? AND pid IS NULL AND exited_at IS NULL")
        .run(pid, witness, runId);
      if (Number(changed.changes) !== 1) throw new Error("spawn witness custody changed");
      return;
    }
    this.db.prepare("INSERT INTO run_process (run,pid,host,process_group,observed_at,boot_id) VALUES (?,?,?,?,?,?)")
      .run(runId, pid, hostname(), group ? 1 : 0, now.toISOString(), currentBootId());
  }

  /** The native OS object a witnessed spawn ran inside (v53) — recorded
   * with the spawn, before the target can execute. */
  recordRunContainer(witness: number, backend: string, container: string, identity?: string): void {
    const changed = this.db.prepare("UPDATE run_process SET containment = ?, container = ?, container_identity = ? WHERE id = ? AND container IS NULL AND exited_at IS NULL")
      .run(backend, container, identity ?? null, witness);
    if (Number(changed.changes) !== 1) throw new Error("container custody changed");
  }

  /** The OS proved the witness's object empty (v53): the ONLY road that
   * marks a native witness settled; a transport exit never does. */
  markRunContainerEmpty(witness: number, now: Date): void {
    this.db.prepare("UPDATE run_process SET container_empty_at = ? WHERE id = ? AND container IS NOT NULL AND container_empty_at IS NULL")
      .run(now.toISOString(), witness);
  }

  /** A held socket can disappear across reboot. Every process witness
   * must independently prove gone; this never grants authority to signal. */
  runCustodyProvenGone(runId: number): boolean {
    const rows = this.db.prepare("SELECT * FROM run_process WHERE run = ?").all(runId);
    return rows.length > 0 && rows.every(row => {
      if (String(row["host"]) !== hostname()) return false;
      if (provenDeadByBootChange({ host: String(row["host"]), bootId: row["boot_id"] == null ? null : String(row["boot_id"]) })) return true;
      if (row["containment"] == null || row["container"] == null) return false;
      return row["container_empty_at"] != null || containerEmptiness(String(row["containment"]), String(row["container"]), process.platform, row["container_identity"] == null ? null : String(row["container_identity"])) === "empty";
    });
  }

  /** The newest witness a run holds, for a caller that must name one. */
  latestRunProcessWitness(runId: number): number | null {
    const row = this.db.prepare("SELECT id FROM run_process WHERE run = ? ORDER BY id DESC LIMIT 1").get(runId);
    return row === undefined ? null : Number(row["id"]);
  }

  /**
   * THE RESUME (v52): the stopped attempt the operator actually reviewed,
   * and only once it is quiescent — its stop settled, the run and every
   * owned descendant ended, no live claim on the task, and it still the
   * task's NEWEST attempt (a later attempt makes this stop history; a
   * replayed or stale resume names it and is refused). It lifts exactly
   * the hold this stop owns: an operator pause, a decision, an incident, a
   * backoff, a revision hold placed beside it all stand. It approves
   * nothing and admits nothing — the next pass re-proves the signed scope,
   * takes a fresh claim, and inherits the draft through the recovered-draft
   * road. A review resumes through the explicit bounded retry door instead,
   * and this refuses in those words.
   */
  resumeRunStop(
    args: { runId: number; taskRef: number; by: string; via: StopVia },
    now: Date,
  ):
    | { ok: true; stop: RunStop }
    | { ok: false; reason: "no-stop" | "wrong-task" | "stopping" | "already-resumed" | "superseded" | "busy" | "review"; detail: string } {
    return this.transact(() => {
      const stop = this.stopOf(args.runId);
      const run = this.getRun(args.runId);
      if (stop === null || run === null) return { ok: false as const, reason: "no-stop" as const, detail: `run #${args.runId} was not stopped` };
      if (stop.taskRef !== args.taskRef) return { ok: false as const, reason: "wrong-task" as const, detail: `run #${args.runId} is not one of this task's attempts` };
      if (stop.resumedAt !== null) return { ok: false as const, reason: "already-resumed" as const, detail: `run #${args.runId} was already resumed by ${stop.resumedBy ?? "?"} at ${stop.resumedAt}` };
      if (run.role === "reviewer") return { ok: false as const, reason: "review" as const, detail: `run #${args.runId} is a review — a stopped review is retried through the explicit review-retry door, which keeps its bounded attempts` };
      if (stop.settledAt === null || run.outcome === null) {
        return { ok: false as const, reason: "stopping" as const, detail: `run #${args.runId} is still stopping — its processes have not been established gone yet` };
      }
      const quiescence = this.stopQuiescenceProblem(args.runId);
      if (quiescence !== null) return { ok: false as const, reason: "stopping" as const, detail: quiescence };
      const openOwned = this.db
        .prepare(
          `WITH RECURSIVE owned(id, lease_id) AS (
             SELECT id, lease_id FROM run WHERE id = ?
             UNION ALL
             SELECT r.id, r.lease_id FROM run r JOIN owned o ON r.parent_run = o.id WHERE r.lease_id = o.lease_id
           ) SELECT run.id AS id FROM run JOIN owned ON owned.id = run.id WHERE run.outcome IS NULL LIMIT 1`,
        )
        .get(args.runId);
      if (openOwned !== undefined) {
        return { ok: false as const, reason: "stopping" as const, detail: `run #${Number(openOwned["id"])}, owned by the stopped attempt, is still open` };
      }
      // The newest ATTEMPT: a lease-group head (a repair turn under the
      // stopped attempt is the attempt's own, not a successor).
      const newest = this.db
        .prepare(
          `SELECT r.id AS id FROM run r LEFT JOIN run p ON p.id = r.parent_run
            WHERE r.task_ref = ? AND r.role <> 'reviewer' AND (r.parent_run IS NULL OR p.lease_id <> r.lease_id)
            ORDER BY r.id DESC LIMIT 1`,
        )
        .get(args.taskRef);
      if (newest !== undefined && Number(newest["id"]) !== args.runId) {
        return { ok: false as const, reason: "superseded" as const, detail: `run #${args.runId} is no longer this task's newest attempt — #${Number(newest["id"])} came after it; reload and decide against the current state` };
      }
      const holding = this.currentLiveLease(args.taskRef, now);
      if (holding !== null) return { ok: false as const, reason: "busy" as const, detail: `the task is claimed right now (lease ${holding}) — nothing resumes over live work` };
      this.db
        .prepare("UPDATE run_stop SET resumed_at = ?, resumed_by = ?, resumed_via = ? WHERE run = ? AND resumed_at IS NULL")
        .run(now.toISOString(), args.by, args.via, args.runId);
      // Exactly this stop's hold — by owner, never by task.
      this.releaseOwnedHold("stop", String(args.runId));
      this.addRunNote(args.runId, args.by, "Resumed. The next pass takes a fresh claim, re-proves the signed scope, and inherits this attempt's preserved draft with fresh proof.", now);
      const resumedTask = this.externalIdFor(args.taskRef);
      if (resumedTask !== null) {
        this.noteLifecycle(
          { taskRef: args.taskRef, run: args.runId, kind: "run-resumed", identity: `r${args.runId}`, subject: `Attempt #${args.runId} resumed`, body: "The next pass takes a fresh claim and continues from the preserved work.", link: chatControlHref("task", resumedTask) },
          now,
        );
      }
      this.bumpWake();
      return { ok: true as const, stop: this.stopOf(args.runId) as RunStop };
    });
  }

  /** Every stop recorded on a task, newest request first. */
  stopsForTask(taskRef: number): RunStop[] {
    return this.db
      .prepare("SELECT * FROM run_stop WHERE task_ref = ? ORDER BY requested_at DESC, run DESC")
      .all(taskRef)
      .map(readRunStop);
  }

  // ---- quota ---------------------------------------------------------------

  /** Record that a credential ran dry — from a structured signal or an operator, never prose. */
  stampQuota(
    quota: { runner: string; provider: string; scope?: string; reason: string; resetAt?: Date; authMode?: "subscription" | "api-key"; credentialFp?: string },
    now: Date,
  ): void {
    this.db
      .prepare(
        `INSERT INTO quota (runner, provider, scope, auth_mode, credential_fp, state, reason, observed_at, reset_at)
         VALUES (?, ?, ?, ?, ?, 'exhausted', ?, ?, ?)
         ON CONFLICT (runner, provider, scope, auth_mode, credential_fp) DO UPDATE SET
           state = 'exhausted', reason = excluded.reason,
           observed_at = excluded.observed_at, reset_at = excluded.reset_at`,
      )
      .run(
        quota.runner,
        quota.provider,
        quota.scope ?? "",
        quota.authMode ?? "subscription",
        quota.credentialFp ?? "",
        quota.reason,
        now.toISOString(),
        quota.resetAt === undefined ? null : quota.resetAt.toISOString(),
      );
  }

  /**
   * The quota gate's answer, with the lazy exhausted→half-open transition at
   * the known reset. Null means no recorded constraint.
   */
  quotaState(
    runner: string,
    provider: string,
    scope: string,
    now: Date,
    authMode: "subscription" | "api-key" = "subscription",
    credentialFp = "",
  ): { state: "exhausted" | "half-open"; reason: string; resetAt: string | null } | null {
    const stamp = now.toISOString();
    this.db
      .prepare(
        `UPDATE quota SET state = 'half-open'
          WHERE runner = ? AND provider = ? AND scope = ? AND auth_mode = ? AND credential_fp = ? AND state = 'exhausted'
            AND reset_at IS NOT NULL AND reset_at <= ?`,
      )
      .run(runner, provider, scope, authMode, credentialFp, stamp);
    const row = this.db
      .prepare("SELECT state, reason, reset_at FROM quota WHERE runner = ? AND provider = ? AND scope = ? AND auth_mode = ? AND credential_fp = ?")
      .get(runner, provider, scope, authMode, credentialFp);
    if (row === undefined) return null;
    return {
      state: String(row["state"]) as "exhausted" | "half-open",
      reason: String(row["reason"]),
      resetAt: row["reset_at"] === null ? null : String(row["reset_at"]),
    };
  }

  /** Read-only quota observation for status surfaces. A passed reset reads
   * half-open, matching quotaState's lazy transition, but this method never
   * consumes or changes the probe slot. */
  readQuotaState(
    runner: string,
    provider: string,
    scope: string,
    now: Date,
    authMode: "subscription" | "api-key" = "subscription",
    credentialFp = "",
  ): { state: "exhausted" | "half-open"; reason: string; resetAt: string | null } | null {
    const row = this.db
      .prepare("SELECT state, reason, reset_at FROM quota WHERE runner = ? AND provider = ? AND scope = ? AND auth_mode = ? AND credential_fp = ?")
      .get(runner, provider, scope, authMode, credentialFp);
    if (row === undefined) return null;
    const resetAt = row["reset_at"] === null ? null : String(row["reset_at"]);
    const resetPassed = resetAt !== null && resetAt <= now.toISOString();
    return {
      state: resetPassed ? "half-open" : String(row["state"]) as "exhausted" | "half-open",
      reason: String(row["reason"]),
      resetAt,
    };
  }

  /**
   * Take the half-open slot: exactly one dispatch probes a recovered quota.
   * The conditional update is what makes it exactly one — and it re-arms
   * the exhausted state for a short window so racing passes stay refused
   * while the probe flies. The probe's success clears the row; the same
   * structured signal that stamped it re-stamps on failure.
   */
  consumeHalfOpen(runner: string, provider: string, scope: string, now: Date, authMode: "subscription" | "api-key" = "subscription", credentialFp = ""): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE quota SET state = 'exhausted', reset_at = ?
          WHERE runner = ? AND provider = ? AND scope = ? AND auth_mode = ? AND credential_fp = ? AND state = 'half-open'`,
      )
      .run(new Date(now.getTime() + 5 * 60_000).toISOString(), runner, provider, scope, authMode, credentialFp);
    return Number(changes) > 0;
  }

  /** A structured all-clear (or an operator's), by name. */
  clearQuota(runner: string, provider: string, scope: string, authMode: "subscription" | "api-key" = "subscription", credentialFp = ""): boolean {
    const { changes } = this.db
      .prepare("DELETE FROM quota WHERE runner = ? AND provider = ? AND scope = ? AND auth_mode = ? AND credential_fp = ?")
      .run(runner, provider, scope, authMode, credentialFp);
    return Number(changes) > 0;
  }

  /**
   * Live claims this runner holds right now — the occupied slots of §8's
   * capacity gate. A claim whose run is a HELD attended session is EXCLUDED
   * (v6 W2): capacity governs unattended work; the attended bound is the
   * session's own signed envelope (v28: any number of them), so watched
   * conversations never freeze the runner's queue.
   */
  liveClaimCount(runner: string, now: Date): number {
    const row = this.db
      .prepare(
        `SELECT COUNT(*) AS n FROM claim
          WHERE runner = ? AND released_at IS NULL AND expires_at > ?
            AND lease_generation = (
              SELECT MAX(newest.lease_generation) FROM claim AS newest
              WHERE newest.task_ref = claim.task_ref
            )
            AND lease_id NOT IN (SELECT lease_id FROM held_session WHERE ended_at IS NULL)`,
      )
      .get(runner, now.toISOString());
    return Number(row?.["n"] ?? 0);
  }

  /** The same live claims as liveClaimCount, by the project their task is placed in. */
  liveClaimCountsByRepo(runner: string, now: Date): Map<string, number> {
    const rows = this.db
      .prepare(
        `SELECT task_ref.repo AS repo, COUNT(*) AS n FROM claim
           JOIN task_ref ON task_ref.id = claim.task_ref
          WHERE claim.runner = ? AND claim.released_at IS NULL AND claim.expires_at > ?
            AND claim.lease_generation = (
              SELECT MAX(newest.lease_generation) FROM claim AS newest
              WHERE newest.task_ref = claim.task_ref
            )
            AND claim.lease_id NOT IN (SELECT lease_id FROM held_session WHERE ended_at IS NULL)
          GROUP BY task_ref.repo`,
      )
      .all(runner, now.toISOString());
    const counts = new Map<string, number>();
    for (const row of rows) if (row["repo"] != null) counts.set(String(row["repo"]), Number(row["n"]));
    return counts;
  }

  /** Every builder's live attempts, by project: what `status` shows against each project's limit. */
  runningBuildsByRepo(now: Date): Map<string, number> {
    const rows = this.db
      .prepare(
        `SELECT task_ref.repo AS repo, COUNT(*) AS n FROM claim
           JOIN task_ref ON task_ref.id = claim.task_ref
          WHERE claim.released_at IS NULL AND claim.expires_at > ?
            AND claim.lease_generation = (
              SELECT MAX(newest.lease_generation) FROM claim AS newest
              WHERE newest.task_ref = claim.task_ref
            )
            AND claim.lease_id NOT IN (SELECT lease_id FROM held_session WHERE ended_at IS NULL)
          GROUP BY task_ref.repo`,
      )
      .all(now.toISOString());
    const counts = new Map<string, number>();
    for (const row of rows) if (row["repo"] != null) counts.set(String(row["repo"]), Number(row["n"]));
    return counts;
  }

  /** A project's build concurrency changed (project-concurrency.ts): the ledger keeps before → after. */
  recordProjectConcurrency(by: string, repo: string, before: number, after: number, now: Date): void {
    this.recordPolicy(by, repo, "builds at once", String(before), String(after), now);
  }

  /** Review 827: a project's demo URL changed (`off` when it has none). */
  recordProjectDemo(by: string, repo: string, before: string | null, after: string | null, now: Date): void {
    this.recordPolicy(by, repo, "demo URL", before ?? "off", after ?? "off", now);
  }

  /** Forward only, and only under the live generation. A stale poller moves nothing. */
  /** v98: an update Telegram pushed, kept until the bridge applies it; false when it's already kept or applied. */
  queueTelegramUpdate(botId: string, updateId: number, payload: string, now: Date): boolean {
    if (this.db.prepare("SELECT 1 AS hit FROM telegram_update WHERE update_id = ?").get(updateId) !== undefined) return false;
    return Number(this.db.prepare("INSERT OR IGNORE INTO telegram_inbox (update_id, bot_id, payload, received_at) VALUES (?, ?, ?, ?)").run(updateId, botId, payload, now.toISOString()).changes) === 1;
  }

  /** v98: pushed updates waiting for the bridge, oldest first. */
  telegramInbox(botId: string, limit: number): { updateId: number; payload: string }[] {
    return this.db.prepare("SELECT update_id, payload FROM telegram_inbox WHERE bot_id = ? ORDER BY update_id LIMIT ?").all(botId, limit)
      .map(row => ({ updateId: Number(row["update_id"]), payload: String(row["payload"]) }));
  }

  dropTelegramInbox(updateId: number): void {
    this.db.prepare("DELETE FROM telegram_inbox WHERE update_id = ?").run(updateId);
  }

  /** v98: where Telegram pushes this bot's updates (null: the bridge asks for them), and what's wrong, if anything. */
  setTelegramPush(botId: string, state: { url: string | null; problem: string | null }, now: Date): void {
    this.db.prepare("UPDATE bridge_lease SET push_url = ?, push_problem = ?, push_at = ? WHERE bot_id = ?").run(state.url, state.problem, now.toISOString(), botId);
  }

  telegramPush(botId: string): { url: string | null; problem: string | null; at: string | null } | null {
    const row = this.db.prepare("SELECT push_url, push_problem, push_at FROM bridge_lease WHERE bot_id = ?").get(botId);
    return row === undefined ? null : { url: row["push_url"] === null ? null : String(row["push_url"]), problem: row["push_problem"] === null ? null : String(row["push_problem"]), at: row["push_at"] === null ? null : String(row["push_at"]) };
  }

  advanceBridgeCursor(
    botId: string,
    owner: string,
    generation: number,
    cursor: number,
    now: Date,
  ): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE bridge_lease SET cursor = ?, heartbeat_at = ?
          WHERE bot_id = ? AND owner = ? AND generation = ? AND cursor < ?`,
      )
      .run(cursor, now.toISOString(), botId, owner, generation, cursor);
    return Number(changes) > 0;
  }

  /** True if this update has not been applied before. The PRIMARY KEY is the idempotency. */
  markTelegramUpdateApplied(updateId: number, result: string, now: Date): boolean {
    const { changes } = this.db
      .prepare(
        "INSERT OR IGNORE INTO telegram_update (update_id, applied_at, result) VALUES (?, ?, ?)",
      )
      .run(updateId, now.toISOString(), result);
    return Number(changes) > 0;
  }

  // ---- the conversation queue (v62) ------------------------------------------

  /** Persist one ordinary message before its update is acknowledged. The caller's transaction also marks the update applied. */
  enqueueTelegramConversation(
    row: {
      binding: TelegramBinding; updateId: number; messageId: string; replyTo: string | null; request: string; text: string;
      context: string | null; taskId: string | null; sourceRun: number | null;
    },
    now: Date,
  ): number {
    const inserted = this.db
      .prepare(
        `INSERT INTO telegram_conversation (binding, bot_id, chat_id, user_id, approver, approver_generation, update_id, message_id, reply_to,
           request, text, context, task_id, source_run, state, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'queued', ?)`,
      )
      .run(
        row.binding.id, row.binding.botId, row.binding.chatId, row.binding.userId, row.binding.approver, row.binding.approverGeneration,
        row.updateId, row.messageId, row.replyTo, row.request, row.text, row.context, row.taskId, row.sourceRun, now.toISOString(),
      );
    return Number(inserted.lastInsertRowid);
  }

  /** Whether a message from this chat is already waiting on, or being answered from, this bot message (a tapped question). */
  telegramConversationWaitingOn(binding: number, messageId: string): boolean {
    return this.db.prepare("SELECT 1 AS hit FROM telegram_conversation WHERE binding = ? AND message_id = ? AND state IN ('queued', 'running') LIMIT 1").get(binding, messageId) !== undefined;
  }

  getTelegramConversation(id: number): TelegramConversation | null {
    const row = this.db.prepare("SELECT * FROM telegram_conversation WHERE id = ?").get(id);
    return row === undefined ? null : readTelegramConversation(row);
  }

  listTelegramConversations(botId: string): TelegramConversation[] {
    return this.db.prepare("SELECT * FROM telegram_conversation WHERE bot_id = ? ORDER BY id").all(botId).map(readTelegramConversation);
  }

  /**
   * Claim the oldest message that still needs a turn: queued, or running
   * under a claim that lapsed (a crash mid-turn), and not deferred past now.
   * One at a time per bot — the mate runs one turn per approver anyway.
   */
  claimTelegramConversation(botId: string, owner: string, ttlMs: number, now: Date, only?: "turns" | "replies"): TelegramConversation | null {
    return this.transact(() => {
      const stamp = now.toISOString();
      // "turns": still needs the assistant; "replies": the reply is planned and only sending remains.
      const planned = "EXISTS (SELECT 1 FROM telegram_conversation_part p WHERE p.conversation = telegram_conversation.id)";
      const which = only === "turns" ? `AND NOT ${planned}` : only === "replies" ? `AND ${planned}` : "";
      const row = this.db
        .prepare(
          `SELECT * FROM telegram_conversation
            WHERE bot_id = ? AND state IN ('queued','running')
              AND (claim_expires_at IS NULL OR claim_expires_at <= ?)
              AND (next_attempt_at IS NULL OR next_attempt_at <= ?)
              ${which}
            ORDER BY id LIMIT 1`,
        )
        .get(botId, stamp, stamp);
      if (row === undefined) return null;
      this.db
        .prepare(
          `UPDATE telegram_conversation SET state = 'running', claim_owner = ?, claim_expires_at = ?, attempts = attempts + 1,
             started_at = COALESCE(started_at, ?), next_attempt_at = NULL WHERE id = ?`,
        )
        .run(owner, new Date(now.getTime() + ttlMs).toISOString(), stamp, Number(row["id"]));
      return this.getTelegramConversation(Number(row["id"]));
    });
  }

  /** Extend a held claim; false means it lapsed and somebody else may hold the row. */
  renewTelegramConversation(id: number, owner: string, ttlMs: number, now: Date): boolean {
    const { changes } = this.db
      .prepare("UPDATE telegram_conversation SET claim_expires_at = ? WHERE id = ? AND claim_owner = ? AND claim_expires_at > ? AND state = 'running'")
      .run(new Date(now.getTime() + ttlMs).toISOString(), id, owner, now.toISOString());
    return Number(changes) === 1;
  }

  /**
   * Bind the session a turn is about to be dispatched under, BEFORE the
   * dispatch: the engine receipts the request inside that session, so a
   * later attempt — after a crash, even after the session was ended and
   * replaced from the console — reads the receipt where it was written
   * instead of resolving today's session and finding nothing there.
   */
  bindTelegramConversationSession(id: number, owner: string, session: number): boolean {
    const { changes } = this.db
      .prepare("UPDATE telegram_conversation SET session = ? WHERE id = ? AND claim_owner = ? AND state = 'running'")
      .run(session, id, owner);
    return Number(changes) === 1;
  }

  /** Bind the admitted turn to its row as soon as the engine's receipt names it. */
  bindTelegramConversationTurn(id: number, owner: string, session: number, turn: number): boolean {
    const { changes } = this.db
      .prepare("UPDATE telegram_conversation SET session = ?, turn = ? WHERE id = ? AND claim_owner = ?")
      .run(session, turn, id, owner);
    return Number(changes) === 1;
  }

  /**
   * Settle a claimed row: done or failed with its outcome word, or back to
   * queued for a later attempt (a busy engine). Only the claim holder may;
   * a lapsed claim settles nothing, so a reclaimer's outcome stands.
   */
  finishTelegramConversation(
    id: number,
    owner: string,
    result: { state: "done" | "failed"; outcome: string; replyMessageId?: string | null } | { state: "queued"; outcome: string; nextAttemptAt: string },
    now: Date,
  ): boolean {
    const stamp = now.toISOString();
    const { changes } = result.state === "queued"
      ? this.db
          .prepare(
            `UPDATE telegram_conversation SET state = 'queued', outcome = ?, next_attempt_at = ?, claim_owner = NULL, claim_expires_at = NULL
              WHERE id = ? AND claim_owner = ? AND claim_expires_at > ? AND state = 'running'`,
          )
          .run(result.outcome, result.nextAttemptAt, id, owner, stamp)
      : this.db
          .prepare(
            `UPDATE telegram_conversation SET state = ?, outcome = ?, reply_message_id = COALESCE(?, reply_message_id), finished_at = ?,
               claim_owner = NULL, claim_expires_at = NULL
              WHERE id = ? AND claim_owner = ? AND claim_expires_at > ? AND state = 'running'`,
          )
          .run(result.state, result.outcome, result.replyMessageId ?? null, stamp, id, owner, stamp);
    return Number(changes) === 1;
  }

  /**
   * Replies the assistant wrote that still have not reached the person
   * `since` ago or longer (status and the console show them with a Retry):
   * the message's row, whose it is, when the oldest unsent part was
   * written, and the last send error.
   */
  unsentTelegramReplies(botId: string | null, approver: string | null, since: Date): { conversation: number; approver: string; since: string; error: string | null }[] {
    return this.db
      .prepare(
        `SELECT c.id, c.approver, MIN(p.created_at) AS since,
           (SELECT q.last_error FROM telegram_conversation_part q WHERE q.conversation = c.id AND q.state = 'pending' ORDER BY q.ordinal LIMIT 1) AS error
          FROM telegram_conversation c JOIN telegram_conversation_part p ON p.conversation = c.id AND p.state = 'pending'
         WHERE c.state IN ('queued','running') AND (? IS NULL OR c.bot_id = ?) AND (? IS NULL OR c.approver = ?)
         GROUP BY c.id HAVING MIN(p.created_at) <= ? ORDER BY c.id`,
      )
      .all(botId, botId, approver, approver, since.toISOString())
      .map(row => ({ conversation: Number(row["id"]), approver: String(row["approver"]), since: String(row["since"]), error: row["error"] === null ? null : String(row["error"]) }));
  }

  /** Send unsent replies on the next bridge pass instead of waiting out their backoff; returns how many. */
  retryTelegramReplies(approver: string | null, now: Date): number {
    const { changes } = this.db
      .prepare(
        `UPDATE telegram_conversation SET next_attempt_at = ?
          WHERE state = 'queued' AND (? IS NULL OR approver = ?)
            AND EXISTS (SELECT 1 FROM telegram_conversation_part p WHERE p.conversation = telegram_conversation.id AND p.state = 'pending')`,
      )
      .run(now.toISOString(), approver, approver);
    return Number(changes);
  }

  // ---- the outbound parts (v63) ------------------------------------------------

  /**
   * Persist the whole outbound half of a turn — every reply part and every
   * card, with the cards' tokens already minted — in one transaction, BEFORE
   * any send. Only the claim holder may, and only once: a row that already
   * has parts keeps them (a retry resumes, never re-plans). The turn's
   * identity rides the row too, so the parts answer to exactly that turn.
   */
  planTelegramConversationParts(
    id: number,
    owner: string,
    turn: { session: number; turn: number },
    parts: readonly TelegramConversationPartPlan[],
    now: Date,
  ): boolean {
    return this.transact(() => {
      const stamp = now.toISOString();
      const held = this.db
        .prepare("SELECT 1 AS hit FROM telegram_conversation WHERE id = ? AND claim_owner = ? AND claim_expires_at > ? AND state = 'running'")
        .get(id, owner, stamp);
      if (held === undefined) return false;
      const existing = this.db.prepare("SELECT COUNT(*) AS n FROM telegram_conversation_part WHERE conversation = ?").get(id);
      if (Number(existing?.["n"] ?? 0) > 0) return false;
      this.db.prepare("UPDATE telegram_conversation SET session = ?, turn = ? WHERE id = ?").run(turn.session, turn.turn, id);
      const insert = this.db.prepare(
        `INSERT INTO telegram_conversation_part (conversation, ordinal, kind, text, reply_to, proposal, keyboard_json, state, created_at, task_id, source_run, artifact, sha256)
         VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?)`,
      );
      parts.forEach((part, ordinal) => {
        const image = part.kind === "image" ? part : null;
        insert.run(
          id, ordinal, part.kind, part.text, part.kind === "reply" ? part.replyTo ?? null : null, part.kind === "card" ? part.proposal : null,
          (part.kind === "card" || part.kind === "reply") && part.keyboard != null ? JSON.stringify(part.keyboard) : null, stamp,
          image?.taskId ?? null, image?.run ?? null, image?.artifact ?? null, image?.sha256 ?? null,
        );
      });
      return true;
    });
  }

  listTelegramConversationParts(conversation: number): TelegramConversationPart[] {
    return this.db.prepare("SELECT * FROM telegram_conversation_part WHERE conversation = ? ORDER BY ordinal").all(conversation).map(readTelegramConversationPart);
  }

  /**
   * Settle one send attempt under the row's claim. A confirmed message id
   * is the only success: the part is sent, and a reply part's id becomes
   * the row's reply id. Anything else leaves the part pending with its
   * attempt counted, its error named, its next attempt scheduled, and —
   * when the answer was lost rather than refused — its uncertainty counted.
   * A lapsed claim settles nothing, so a reclaimer's outcome stands.
   */
  settleTelegramConversationPart(
    conversation: number,
    ordinal: number,
    owner: string,
    outcome: { ok: true; messageId: string } | { ok: false; error: string; uncertain: boolean; retryAt: string },
    now: Date,
  ): boolean {
    return this.transact(() => {
      const stamp = now.toISOString();
      const held = this.db
        .prepare("SELECT 1 AS hit FROM telegram_conversation WHERE id = ? AND claim_owner = ? AND claim_expires_at > ? AND state = 'running'")
        .get(conversation, owner, stamp);
      if (held === undefined) return false;
      const { changes } = outcome.ok
        ? this.db
            .prepare(
              `UPDATE telegram_conversation_part SET state = 'sent', message_id = ?, sent_at = ?, attempts = attempts + 1, next_attempt_at = NULL, last_error = NULL
                WHERE conversation = ? AND ordinal = ? AND state = 'pending'`,
            )
            .run(outcome.messageId, stamp, conversation, ordinal)
        : this.db
            .prepare(
              `UPDATE telegram_conversation_part SET attempts = attempts + 1, uncertain = uncertain + ?, next_attempt_at = ?, last_error = ?
                WHERE conversation = ? AND ordinal = ? AND state = 'pending'`,
            )
            .run(outcome.uncertain ? 1 : 0, outcome.retryAt, outcome.error, conversation, ordinal);
      if (Number(changes) !== 1) return false;
      if (outcome.ok) {
        const part = this.db.prepare("SELECT kind FROM telegram_conversation_part WHERE conversation = ? AND ordinal = ?").get(conversation, ordinal);
        if (part?.["kind"] === "reply") this.db.prepare("UPDATE telegram_conversation SET reply_message_id = ? WHERE id = ?").run(outcome.messageId, conversation);
      }
      return true;
    });
  }

  /** A card whose proposal no longer waits (confirmed or dismissed from another surface, or gone) is moot: dropped with the reason, never sent. */
  dropTelegramConversationPart(conversation: number, ordinal: number, owner: string, reason: string, now: Date): boolean {
    const stamp = now.toISOString();
    const held = this.db
      .prepare("SELECT 1 AS hit FROM telegram_conversation WHERE id = ? AND claim_owner = ? AND claim_expires_at > ? AND state = 'running'")
      .get(conversation, owner, stamp);
    if (held === undefined) return false;
    const { changes } = this.db
      .prepare("UPDATE telegram_conversation_part SET state = 'dropped', last_error = ?, next_attempt_at = NULL WHERE conversation = ? AND ordinal = ? AND state = 'pending'")
      .run(reason, conversation, ordinal);
    return Number(changes) === 1;
  }

  /** The exact task/run bindings of one outbound message this bot sent: a
   * plain fact names one, a digest part may name several, (v64) a confirmed
   * result image names its exact task and run, the lead's reply names the
   * task its turn was about, a card names its task, and (v79) a status
   * message names the task it showed. */
  telegramMessageBindings(binding: TelegramBinding, messageId: string): { taskId: string | null; taskRef: number | null; run: number | null; project: string | null }[] {
    const facts = this.db
      .prepare(
        `SELECT DISTINCT task_id, task_ref, source_run, project FROM telegram_outbound_message
          WHERE binding = ? AND chat_id = ? AND message_id = ? ORDER BY notification`,
      )
      .all(binding.id, binding.chatId, messageId)
      .map(row => ({
        taskId: row["task_id"] === null ? null : String(row["task_id"]),
        taskRef: row["task_ref"] === null ? null : Number(row["task_ref"]),
        run: row["source_run"] === null ? null : (this.telegramProgressRun({ taskRef: row["task_ref"] === null ? null : Number(row["task_ref"]), run: Number(row["source_run"]) })?.id ?? Number(row["source_run"])),
        project: row["project"] === null ? null : String(row["project"]),
      }));
    const images = this.db
      .prepare(
        `SELECT DISTINCT p.task_id, p.source_run FROM telegram_conversation_part p
          JOIN telegram_conversation c ON c.id = p.conversation
          WHERE c.binding = ? AND c.chat_id = ? AND p.message_id = ? AND p.kind = 'image' AND p.state = 'sent'
          ORDER BY p.conversation, p.ordinal`,
      )
      .all(binding.id, binding.chatId, messageId)
      .map(row => {
        const taskId = String(row["task_id"]);
        const ref = this.lookupRef(taskId);
        return { taskId, taskRef: ref?.id ?? null, run: Number(row["source_run"]), project: ref?.repo ?? null };
      });
    // The lead's own messages: a reply from a turn that was about one task,
    // and a card, which names its task (or, once it filed one, the new task).
    const lead = this.db
      .prepare(
        `SELECT c.task_id, c.source_run, p.kind, p.proposal FROM telegram_conversation_part p
          JOIN telegram_conversation c ON c.id = p.conversation
          WHERE c.binding = ? AND c.chat_id = ? AND p.message_id = ? AND p.state = 'sent' AND p.kind IN ('reply', 'card')
          ORDER BY p.conversation, p.ordinal`,
      )
      .all(binding.id, binding.chatId, messageId)
      .map(row => row["kind"] === "card"
        ? proposalTaskOf(row["proposal"] === null ? null : this.getMateProposal(Number(row["proposal"])))
        : row["task_id"] === null ? null : { task: String(row["task_id"]), run: row["source_run"] === null ? null : Number(row["source_run"]) });
    const shown = this.db
      .prepare("SELECT task_id, source_run FROM telegram_task_message WHERE binding = ? AND chat_id = ? AND message_id = ?")
      .all(binding.id, binding.chatId, messageId)
      .map(row => ({ task: String(row["task_id"]), run: row["source_run"] === null ? null : Number(row["source_run"]) }));
    const pointed = [...lead, ...shown].flatMap(one => {
      if (one === null) return [];
      const ref = this.lookupRef(one.task);
      return [{ taskId: one.task, taskRef: ref?.id ?? null, run: one.run, project: ref?.repo ?? null }];
    });
    return [...facts, ...images, ...pointed].filter((one, index, all) => all.findIndex(fact => fact.taskId === one.taskId && fact.taskRef === one.taskRef && fact.run === one.run && fact.project === one.project) === index);
  }

  // ---- proposal-card tokens (v62) ---------------------------------------------

  createTelegramProposalAction(
    action: { token: string; binding: number; proposal: number; phase: TelegramProposalAction["phase"]; chatId: string; messageId?: string; ttlMs?: number },
    now: Date,
  ): void {
    this.db
      .prepare(
        `INSERT INTO telegram_proposal_action (token, binding, proposal, phase, chat_id, message_id, created_at, expires_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        action.token, action.binding, action.proposal, action.phase, action.chatId, action.messageId ?? null, now.toISOString(),
        action.ttlMs === undefined ? null : new Date(now.getTime() + action.ttlMs).toISOString(),
      );
  }

  getTelegramProposalAction(token: string): TelegramProposalAction | null {
    const row = this.db.prepare("SELECT * FROM telegram_proposal_action WHERE token = ?").get(token);
    return row === undefined ? null : readTelegramProposalAction(row);
  }

  /** Consume once. False means somebody already did, or it expired. */
  consumeTelegramProposalAction(token: string, now: Date): boolean {
    const stamp = now.toISOString();
    const { changes } = this.db
      .prepare("UPDATE telegram_proposal_action SET consumed_at = ? WHERE token = ? AND consumed_at IS NULL AND (expires_at IS NULL OR expires_at > ?)")
      .run(stamp, token, stamp);
    return Number(changes) > 0;
  }

  /** Kill every live token on a proposal — after it resolves, or when a challenge is cancelled. */
  consumeTelegramProposalActions(proposal: number, now: Date, phases?: readonly TelegramProposalAction["phase"][]): void {
    const filter = phases === undefined ? "" : ` AND phase IN (${phases.map(() => "?").join(",")})`;
    this.db
      .prepare(`UPDATE telegram_proposal_action SET consumed_at = ? WHERE proposal = ? AND consumed_at IS NULL${filter}`)
      .run(now.toISOString(), proposal, ...(phases ?? []));
  }

  /** Stamp the message a card's keyboard actually landed on. */
  placeTelegramProposalActions(tokens: readonly string[], messageId: string): void {
    for (const token of tokens) {
      this.db.prepare("UPDATE telegram_proposal_action SET message_id = ? WHERE token = ?").run(messageId, token);
    }
  }

  // ---- delivery claiming ---------------------------------------------------

  telegramDestination(binding: TelegramBinding): string {
    return `telegram:${binding.botId}:${binding.chatId}:${binding.id}:${binding.approverGeneration}`;
  }

  /** A progress card belongs to one builder result, including its root review.
   * Do not combine planners, correction children, or separate build attempts. */
  telegramProgressRun(row: Pick<Notification, "taskRef" | "run">): Run | null {
    const source = row.run === null ? null : this.getRun(row.run);
    const result = source?.role === "reviewer" && source.reviewAttempt != null && source.parentRun !== null
      ? this.getRun(source.parentRun) : source;
    return result?.role === "builder" && result.contestant === null && result.taskRef === row.taskRef && source?.taskRef === row.taskRef ? result : null;
  }

  /** Reuse a confirmed message in this exact destination. A mixed digest,
   * decision, image, or message naming another attempt is never editable. The
   * outbound history survives a restart even if the final receipt was lost. */
  telegramProgressMessage(binding: TelegramBinding, result: Run): string | null {
    const messages = this.db.prepare(`SELECT DISTINCT message_id FROM telegram_outbound_message
      WHERE destination = ? AND task_ref = ? ORDER BY CAST(message_id AS INTEGER) DESC`)
      .all(this.telegramDestination(binding), result.taskRef);
    for (const message of messages) {
      const rows = this.db.prepare(`SELECT n.* FROM telegram_outbound_message m JOIN notification n ON n.id = m.notification
        WHERE m.destination = ? AND m.message_id = ?`).all(this.telegramDestination(binding), String(message["message_id"]));
      if (rows.length > 0 && rows.every(raw => {
        const row = readNotification(raw);
        return isTelegramProgressNotification(row) && this.telegramProgressRun(row)?.id === result.id;
      })) return String(message["message_id"]);
    }
    return null;
  }

  /** The existing outbox, with a separate receipt for this exact pairing. */
  claimTelegramDeliveries(binding: TelegramBinding, owner: string, ttlMs: number, now: Date, only: "all" | "urgent" = "all"): TelegramDelivery[] {
    return this.transact(() => {
      const destination = this.telegramDestination(binding);
      this.db.prepare(`INSERT OR IGNORE INTO notification_delivery (notification, destination)
        SELECT id, ? FROM notification WHERE resolved_at IS NULL`).run(destination);
      // Someone else's notification is settled here as skipped, never sent —
      // and never left unsettled, where it would fence that task's later rows.
      this.db.prepare(`UPDATE notification_delivery SET receipt = '${TELEGRAM_SKIPPED_ELSEWHERE}'
        WHERE destination = ? AND delivered_at IS NULL AND receipt IS NULL
          AND notification IN (SELECT id FROM notification WHERE recipient IS NOT NULL AND recipient <> ?)`).run(destination, binding.approver);
      // A promise the lead made on another chat is reported there (lead-commitments.ts), not here.
      this.db.prepare(`UPDATE notification_delivery SET receipt = '${TELEGRAM_SKIPPED_OTHER_CHAT}'
        WHERE destination = ? AND delivered_at IS NULL AND receipt IS NULL
          AND notification IN (SELECT id FROM notification WHERE dedupe_key LIKE 'lead-promise:%' AND dedupe_key NOT LIKE 'lead-promise:telegram:%')`).run(destination);
      // Pings follow responsibility (the lead's work, this person's own act, a muted project): settled here, unsent.
      for (const raw of this.db.prepare(`SELECT n.* FROM notification n JOIN notification_delivery d ON d.notification = n.id AND d.destination = ?
          WHERE n.resolved_at IS NULL AND d.delivered_at IS NULL AND d.receipt IS NULL AND (d.claim_owner IS NULL OR d.claim_expires_at <= ?)`).all(destination, now.toISOString())) {
        const row = readNotification(raw);
        if (!this.pingAllowed(row, binding.approver)) {
          this.db.prepare(`UPDATE notification_delivery SET receipt = '${TELEGRAM_SKIPPED_QUIET}' WHERE notification = ? AND destination = ?`).run(row.id, destination);
        }
      }
      if (this.telegramRetryAt(binding.botId) > now.toISOString()) return [];
      const rows = this.db.prepare(`SELECT n.*, d.claim_generation FROM notification n
        JOIN notification_delivery d ON d.notification = n.id AND d.destination = ?
        WHERE n.resolved_at IS NULL AND ${TELEGRAM_UNSETTLED}
          AND (d.claim_owner IS NULL OR d.claim_expires_at <= ?)
          AND (d.next_attempt_at IS NULL OR d.next_attempt_at <= ?)
          AND (? = 'all' OR d.attempts > 0 OR n.dedupe_key LIKE 'decision:%' OR n.push_class = 'attention' OR n.kind IN ('acceptance-evidence', 'acceptance-ready')
            OR EXISTS (SELECT 1 FROM notification urgent
              WHERE urgent.task_ref = n.task_ref AND urgent.id > n.id AND urgent.resolved_at IS NULL
                AND (urgent.dedupe_key LIKE 'decision:%' OR urgent.push_class = 'attention' OR urgent.kind IN ('acceptance-evidence', 'acceptance-ready'))))
        ORDER BY n.id`).all(destination, now.toISOString(), now.toISOString(), only);
      return rows.map(row => {
        this.db.prepare(`UPDATE notification_delivery SET claim_owner = ?, claim_expires_at = ?,
          claim_generation = claim_generation + 1 WHERE notification = ? AND destination = ?`)
          .run(owner, new Date(now.getTime() + ttlMs).toISOString(), Number(row["id"]), destination);
        return { ...readNotification(row), destination, claimGeneration: Number(row["claim_generation"]) + 1 };
      });
    });
  }

  telegramRetryAt(botId: string): string {
    return String(this.db.prepare("SELECT next_attempt_at FROM telegram_retry WHERE bot_id = ?").get(botId)?.["next_attempt_at"] ?? "");
  }

  deferTelegram(botId: string, until: string): void {
    this.db.prepare(`INSERT INTO telegram_retry (bot_id, next_attempt_at) VALUES (?, ?)
      ON CONFLICT (bot_id) DO UPDATE SET next_attempt_at = MAX(next_attempt_at, excluded.next_attempt_at)`).run(botId, until);
  }

  /** Synchronous final fence, called AFTER each asynchronous enrollment read. */
  telegramDeliveryProblem(row: TelegramDelivery, binding: TelegramBinding, owner: string, projects: readonly string[], now: Date, batch: readonly number[] = [row.id]): string | null {
    const live = this.liveTelegramBindingById(binding.id);
    if (live === null || live.approverGeneration !== binding.approverGeneration ||
        this.accountOf(binding.approver)?.role !== "approver") return TELEGRAM_HOLD_REASONS.authority;
    if (row.destination !== this.telegramDestination(live)) return TELEGRAM_HOLD_REASONS.destination;
    if (!this.telegramClaimHeld(row, owner, now)) return TELEGRAM_HOLD_REASONS.claim;
    if (this.telegramRetryAt(binding.botId) > now.toISOString()) return TELEGRAM_HOLD_REASONS.rateLimit;
    const current = this.db.prepare("SELECT * FROM notification WHERE id = ?").get(row.id);
    if (current === undefined || current["resolved_at"] !== null) return TELEGRAM_HOLD_REASONS.resolved;
    if (row.scope === "unknown") return TELEGRAM_HOLD_REASONS.provenance;
    if (row.scope === "installation") {
      // One addressed to this person (their own budget, v105) reaches them; the rest of the installation's are an operator's.
      if (!this.isInstanceOperator(binding.approver) && current["recipient"] !== binding.approver) return TELEGRAM_HOLD_REASONS.installation;
    } else {
      if (row.project === null || !projects.includes(row.project) || !this.accountCanAccess(binding.approver, row.project)) return TELEGRAM_HOLD_REASONS.project;
      if (row.scope === "task") {
        const ref = this.db.prepare("SELECT repo, external_id FROM task_ref WHERE id = ?").get(row.taskRef);
        if (ref === undefined || ref["repo"] !== row.project || ref["external_id"] !== row.taskId ||
            (row.run !== null && this.getRun(row.run)?.taskRef !== row.taskRef)) return TELEGRAM_HOLD_REASONS.task;
      }
    }
    if (row.taskRef !== null) {
      // Skipped history never fences what follows it: it is settled.
      const earlier = this.db.prepare(`SELECT n.id FROM notification n
        LEFT JOIN notification_delivery d ON d.notification = n.id AND d.destination = ?
        WHERE n.task_ref = ? AND n.id < ? AND n.resolved_at IS NULL AND ${TELEGRAM_UNSETTLED}`)
        .all(row.destination, row.taskRef, row.id);
      if (earlier.some(one => !batch.includes(Number(one["id"])))) return TELEGRAM_HOLD_REASONS.order;
    }
    return null;
  }

  private telegramClaimHeld(row: TelegramDelivery, owner: string, now: Date): boolean {
    return this.db.prepare(`SELECT 1 FROM notification_delivery WHERE notification = ? AND destination = ?
      AND claim_owner = ? AND claim_generation = ? AND claim_expires_at > ? AND delivered_at IS NULL`)
      .get(row.id, row.destination, owner, row.claimGeneration, now.toISOString()) !== undefined;
  }

  /** A confirmed network message remains history even if authority changed
   * while it was in flight. It only binds the OLD destination, never new work. */
  recordTelegramMessage(row: TelegramDelivery, binding: TelegramBinding, messageId: string, now: Date): void {
    if (row.destination !== this.telegramDestination(binding)) throw new Error("Telegram message destination mismatch");
    this.db.prepare(`INSERT OR IGNORE INTO telegram_outbound_message
      (binding, bot_id, chat_id, message_id, notification, destination, project, task_ref, task_id, source_run, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
      .run(binding.id, binding.botId, binding.chatId, messageId, row.id, row.destination, row.project, row.taskRef, row.taskId, row.run, now.toISOString());
  }

  /** The newest confirmed message this notification became at one destination, if any. */
  telegramMessageOf(notification: number, destination: string): string | null {
    const row = this.db.prepare("SELECT message_id FROM telegram_outbound_message WHERE notification = ? AND destination = ? ORDER BY CAST(message_id AS INTEGER) DESC LIMIT 1").get(notification, destination);
    return row === undefined ? null : String(row["message_id"]);
  }

  finalizeTelegramDelivery(row: TelegramDelivery, binding: TelegramBinding, owner: string,
    outcome: { ok: true; receipt: string | null } | { ok: false; error: string; retryAt?: string }, now: Date): boolean {
    return this.transact(() => {
      if (!this.telegramClaimHeld(row, owner, now) || row.destination !== this.telegramDestination(binding)) return false;
      if (outcome.ok && (this.liveTelegramBindingById(binding.id) === null || this.accountOf(binding.approver)?.role !== "approver")) return false;
      // A `skipped:` receipt settles the row without a delivery: nothing
      // reached the phone, so delivered_at stays empty exactly as it does
      // for the pairing skip (TELEGRAM_UNSETTLED treats both as settled).
      const skipped = outcome.ok && outcome.receipt !== null && outcome.receipt.startsWith("skipped:");
      this.db.prepare(`UPDATE notification_delivery SET attempts = attempts + 1, last_attempt_at = ?,
        delivered_at = ?, receipt = ?, last_error = ?, next_attempt_at = ?, claim_owner = NULL, claim_expires_at = NULL
        WHERE notification = ? AND destination = ? AND claim_owner = ? AND claim_generation = ?`)
        .run(now.toISOString(), outcome.ok && !skipped ? now.toISOString() : null, outcome.ok ? outcome.receipt : null,
          outcome.ok ? null : outcome.error, outcome.ok ? null : outcome.retryAt ?? new Date(now.getTime() + 1_000).toISOString(),
          row.id, row.destination, owner, row.claimGeneration);
      return true;
    });
  }

  /** Read receipts without changing the meaning of shell/webhook history. */
  telegramDeliveries(binding: TelegramBinding): Notification[] {
    return this.db.prepare(`SELECT n.*, d.attempts, d.last_attempt_at, d.last_error, d.delivered_at, d.receipt
      FROM notification n JOIN notification_delivery d ON d.notification = n.id WHERE d.destination = ? ORDER BY n.id`)
      .all(this.telegramDestination(binding)).map(readNotification);
  }

  /**
   * Claim pending notifications for one deliverer. Two deliverers — the
   * bridge and `outbox deliver` — select-then-send-then-record, and without
   * a claim both can send the same row in the gap. The claim is a short
   * lease on the act of sending; a deliverer that dies mid-send leaves rows
   * that unclaim themselves by expiry.
   */
  claimDeliveries(owner: string, ttlMs: number, now: Date, only: "all" | "urgent" = "all"): Notification[] {
    return this.transact(() => {
      const stamp = now.toISOString();
      // `urgent` (v34, digests): only what must page NOW — a decision, or
      // an attention-class fact. Routine rows stay unclaimed and pending
      // until a pass asks for `all`; nothing about them is written here.
      const rows = this.db
        .prepare(
          `SELECT id FROM notification
            WHERE delivered_at IS NULL AND resolved_at IS NULL AND recipient IS NULL
              AND (claim_owner IS NULL OR claim_expires_at <= ?)
              AND (? = 'all' OR dedupe_key LIKE 'decision:%' OR COALESCE(push_class, '') = 'attention')
            ORDER BY id`,
        )
        .all(stamp, only)
        .map(row => Number(row["id"]));
      const expires = new Date(now.getTime() + ttlMs).toISOString();
      for (const id of rows) {
        this.db
          .prepare("UPDATE notification SET claim_owner = ?, claim_expires_at = ? WHERE id = ?")
          .run(owner, expires, id);
      }
      return rows
        .map(id => this.db.prepare("SELECT * FROM notification WHERE id = ?").get(id))
        .filter((row): row is Record<string, unknown> => row !== undefined)
        .map(readNotification);
    });
  }

  /** Finalize only what this owner still holds. A lapsed claim writes nothing. */
  finalizeDelivery(
    id: number,
    owner: string,
    outcome: { ok: true; receipt: string | null } | { ok: false; error: string },
    now: Date,
  ): boolean {
    const stamp = now.toISOString();
    if (outcome.ok) {
      const { changes } = this.db
        .prepare(
          `UPDATE notification SET delivered_at = ?, receipt = ?, attempts = attempts + 1,
                                   last_attempt_at = ?, last_error = NULL,
                                   claim_owner = NULL, claim_expires_at = NULL
            WHERE id = ? AND claim_owner = ? AND delivered_at IS NULL`,
        )
        .run(stamp, outcome.receipt, stamp, id, owner);
      return Number(changes) > 0;
    }
    const { changes } = this.db
      .prepare(
        `UPDATE notification SET attempts = attempts + 1, last_attempt_at = ?, last_error = ?,
                                 claim_owner = NULL, claim_expires_at = NULL
          WHERE id = ? AND claim_owner = ?`,
      )
      .run(stamp, outcome.error, id, owner);
    return Number(changes) > 0;
  }

  // ---- the Telegram digest (v34, away mode) --------------------------------

  /** The digest cadence: null everyMs = off. */
  telegramDigest(): TelegramDigest {
    const row = this.db.prepare("SELECT every_ms, set_by, set_at, last_sent_at FROM telegram_digest WHERE id = 1").get();
    return {
      everyMs: row?.["every_ms"] === null || row?.["every_ms"] === undefined ? null : Number(row["every_ms"]),
      setBy: row?.["set_by"] === null || row?.["set_by"] === undefined ? null : String(row["set_by"]),
      setAt: row?.["set_at"] === null || row?.["set_at"] === undefined ? null : String(row["set_at"]),
      lastSentAt: row?.["last_sent_at"] === null || row?.["last_sent_at"] === undefined ? null : String(row["last_sent_at"]),
    };
  }

  /** Set (or clear, with null) the cadence. Turning it on starts the
   * window NOW — nothing held before the choice is dumped at once. */
  setTelegramDigest(everyMs: number | null, by: string, now: Date): void {
    this.db
      .prepare("UPDATE telegram_digest SET every_ms = ?, set_by = ?, set_at = ?, last_sent_at = CASE WHEN ? IS NULL THEN NULL ELSE COALESCE(last_sent_at, ?) END WHERE id = 1")
      .run(everyMs, by, now.toISOString(), everyMs, now.toISOString());
  }

  // ---- quiet chat: each person's notification choice and each task's one message ----

  /** How chats reach this person: only when they are needed unless they chose every step. */
  notificationPreference(account: string): NotificationPreference {
    const row = this.db.prepare("SELECT mode, digest_at, digest_on, updated_at, screenshots FROM notification_preference WHERE account = ?").get(account);
    return row === undefined ? { mode: "quiet", digestAt: null, digestOn: null, updatedAt: null, screenshots: "off" }
      : { mode: row["mode"] === "all" ? "all" : "quiet", digestAt: row["digest_at"] == null ? null : String(row["digest_at"]),
        digestOn: row["digest_on"] == null ? null : String(row["digest_on"]), updatedAt: String(row["updated_at"]),
        screenshots: row["screenshots"] === "first" || row["screenshots"] === "all" ? row["screenshots"] : "off" };
  }

  /** Change one person's choice; a digest time is a local HH:MM, or null for no evening digest. */
  setNotificationPreference(account: string, change: { mode?: NotificationMode; digestAt?: string | null; screenshots?: ResultScreenshots }, by: string, now: Date): NotificationPreference {
    if (change.digestAt != null && !isDigestTime(change.digestAt)) throw new Error("digest time must be HH:MM");
    if (change.screenshots !== undefined && !RESULT_SCREENSHOTS.includes(change.screenshots)) throw new Error("screenshots must be off, first or all");
    const current = this.notificationPreference(account);
    const mode = change.mode ?? current.mode;
    const digestAt = change.digestAt === undefined ? current.digestAt : change.digestAt;
    const screenshots = change.screenshots ?? current.screenshots;
    this.db.prepare(`INSERT INTO notification_preference (account, mode, digest_at, digest_on, updated_at, updated_by, screenshots) VALUES (?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT (account) DO UPDATE SET mode = excluded.mode, digest_at = excluded.digest_at, updated_at = excluded.updated_at, updated_by = excluded.updated_by,
        screenshots = excluded.screenshots`)
      .run(account, mode, digestAt, current.digestOn, now.toISOString(), by, screenshots);
    return this.notificationPreference(account);
  }

  // ---- screenshots with results (result-shots.ts) ----

  /** The screenshots of this result already sent (or being sent) to one destination. */
  resultShotsSent(destination: string, run: number): Set<number> {
    return new Set(this.db.prepare("SELECT artifact FROM result_shot_sent WHERE destination = ? AND run = ?").all(destination, run).map(row => Number(row["artifact"])));
  }

  /** Mark screenshots as sent BEFORE they go: an unconfirmed send is never repeated. */
  markResultShotsSent(destination: string, run: number, artifacts: readonly number[], now: Date): void {
    const insert = this.db.prepare("INSERT OR IGNORE INTO result_shot_sent (destination, run, artifact, sent_at) VALUES (?, ?, ?, ?)");
    this.transact(() => { for (const artifact of artifacts) insert.run(destination, run, artifact, now.toISOString()); });
  }

  /** Telegram refused them outright, so nothing arrived: they may be tried again. */
  unmarkResultShotsSent(destination: string, run: number, artifacts: readonly number[]): void {
    const remove = this.db.prepare("DELETE FROM result_shot_sent WHERE destination = ? AND run = ? AND artifact = ?");
    this.transact(() => { for (const artifact of artifacts) remove.run(destination, run, artifact); });
  }

  /**
   * A result message just became a fact: everyone who asked for screenshots with results, can see the project and
   * would be pinged by it gets one row of their own that follows it — once per result, whatever produced the fact.
   * Only a result that saved screenshots qualifies; what is sent, and whether at all, is decided again at send time.
   */
  private enqueueResultShots(source: Notification, now: Date): void {
    if (source.run === null || source.taskRef === null || source.project === null || source.recipient !== null) return;
    const run = this.getRun(source.run);
    if (run === null || run.contestant !== null) return;
    // One path per role (review 826): a scout's report is its result, so only its "report ready" carries the
    // screenshots it saved; a build's are carried by its finished or failed message.
    const carries = run.role === "scout" ? source.kind === "report-ready"
      : ["builder", "repair"].includes(run.role) && ((isLifecycleNotification(source) && source.kind === "run-finished") || /fail/.test(source.kind));
    if (!carries) return;
    if (!this.artifactsFor(run.id).some(one => one.kind === "screenshot")) return;
    const people = this.db.prepare("SELECT account FROM notification_preference WHERE screenshots IN ('first', 'all') ORDER BY account").all().map(row => String(row["account"]));
    for (const account of people) {
      if (!this.accountCanAccess(account, source.project) || !this.pingAllowed(source, account)) continue;
      this.enqueueNotification({ dedupeKey: `result-shots:r${run.id}:${account}`, kind: RESULT_SHOTS_KIND, subject: "Screenshots with this result", body: "",
        ...(source.link === null ? {} : { link: source.link }), source: { run: run.id }, recipient: account }, now);
    }
  }

  /** Everyone who asked for an evening digest, with the local day theirs was last considered. */
  eveningDigestPeople(): { account: string; digestAt: string; digestOn: string | null }[] {
    return this.db.prepare("SELECT account, digest_at, digest_on FROM notification_preference WHERE digest_at IS NOT NULL ORDER BY account").all()
      .map(row => ({ account: String(row["account"]), digestAt: String(row["digest_at"]), digestOn: row["digest_on"] == null ? null : String(row["digest_on"]) }));
  }

  /** Claim one local day's digest for one person: true once, false if it was already considered. */
  claimEveningDigestDay(account: string, day: string): boolean {
    return Number(this.db.prepare("UPDATE notification_preference SET digest_on = ? WHERE account = ? AND digest_at IS NOT NULL AND (digest_on IS NULL OR digest_on < ?)")
      .run(day, account, day).changes) === 1;
  }

  // ---- pings follow responsibility: the lead, who acted, replacements and muted projects ----

  /** What this person named their lead and its persona, or null when they never saved one. An empty name or persona
   * (a row saved only for what the lead knows about them) reads as the default. */
  leadConfig(account: string): { name: string; persona: string } | null {
    const row = this.db.prepare("SELECT name, persona FROM lead_config WHERE account = ? AND (name <> '' OR persona <> '')").get(account);
    return row === undefined ? null : { name: String(row["name"]), persona: String(row["persona"]) };
  }

  /** Save this person's lead name and persona (checked by the caller: lead-identity.ts). */
  setLeadConfig(account: string, name: string, persona: string, now: Date): void {
    this.db.prepare(`INSERT INTO lead_config (account, name, persona, updated_at) VALUES (?, ?, ?, ?)
      ON CONFLICT(account) DO UPDATE SET name = excluded.name, persona = excluded.persona, updated_at = excluded.updated_at`).run(account, name, persona, now.toISOString());
  }

  /** What this person's lead knows about them: their confirmed lines, in order (none when they never saved any). */
  leadAbout(account: string): string[] {
    const row = this.db.prepare("SELECT about_json FROM lead_config WHERE account = ?").get(account);
    if (row === undefined) return [];
    try {
      const lines = JSON.parse(String(row["about_json"]));
      return Array.isArray(lines) ? lines.filter((one): one is string => typeof one === "string") : [];
    } catch { return []; }
  }

  /** Save what this person's lead knows about them (checked by the caller: lead-about.ts). A person who never named
   * their lead gets an empty name and persona, so they keep following the defaults. */
  setLeadAbout(account: string, lines: readonly string[], now: Date): void {
    this.db.prepare(`INSERT INTO lead_config (account, name, persona, updated_at, about_json) VALUES (?, '', '', ?, ?)
      ON CONFLICT(account) DO UPDATE SET about_json = excluded.about_json, updated_at = excluded.updated_at`).run(account, now.toISOString(), JSON.stringify(lines));
  }

  /** A lead token for one person, shown once. A new one ends their earlier ones; the ledger names it "lead for <owner>". */
  mintLeadCredential(owner: string, by: string, now: Date): { id: string; token: string } {
    return this.transact(() => {
      const stamp = now.toISOString();
      this.db.prepare("UPDATE lead_credential SET revoked_at = ?, revoked_by = ? WHERE owner = ? AND revoked_at IS NULL").run(stamp, by, owner);
      const minted = mintLeadToken();
      this.db.prepare("INSERT INTO lead_credential (id, owner, secret_hash, created_at, created_by) VALUES (?, ?, ?, ?, ?)").run(minted.id, owner, minted.hash, stamp, by);
      this.recordAction({ at: stamp, actor: by, repo: null, taskId: null, runId: null, action: "lead token created", outcome: "recorded", source: "access", detail: `lead for ${owner}` });
      return { id: minted.id, token: minted.token };
    });
  }

  /** End every live lead token for one person. */
  revokeLeadCredentials(owner: string, by: string, now: Date): number {
    return this.transact(() => {
      const ended = Number(this.db.prepare("UPDATE lead_credential SET revoked_at = ?, revoked_by = ? WHERE owner = ? AND revoked_at IS NULL").run(now.toISOString(), by, owner).changes);
      if (ended > 0) this.recordAction({ at: now.toISOString(), actor: by, repo: null, taskId: null, runId: null, action: "lead token revoked", outcome: "recorded", source: "access", detail: `lead for ${owner}` });
      return ended;
    });
  }

  /** Whose lead a presented token is: a live token whose owner is still an approver, or null. */
  leadFor(presented: string): { owner: string; id: string } | null {
    const parsed = parseLeadToken(presented);
    if (parsed === null) return null;
    const row = this.db.prepare("SELECT owner, secret_hash FROM lead_credential WHERE id = ? AND revoked_at IS NULL").get(parsed.id);
    if (row === undefined || !leadSecretMatches(parsed.secret, String(row["secret_hash"]))) return null;
    const owner = String(row["owner"]), account = this.accountOf(owner);
    return account === null || account.revokedAt !== null || account.role !== "approver" ? null : { owner, id: parsed.id };
  }

  /** Record who did this to a task, when someone is acting. The lead's acts are also in the ledger as "lead for <owner>". */
  noteTaskAct(taskRef: number, act: TaskAct, now: Date, handed?: { person: string; why: string }, actor: Actor | null = currentActor()): void {
    if (actor === null) return;
    this.db.prepare("INSERT INTO task_act (task_ref, act, account, lead, person, why, at) VALUES (?, ?, ?, ?, ?, ?, ?)")
      .run(taskRef, act, actor.account, actor.lead ? 1 : 0, handed?.person ?? null, handed?.why ?? null, now.toISOString());
    if (!actor.lead) return;
    const ref = this.db.prepare("SELECT repo, external_id FROM task_ref WHERE id = ?").get(taskRef);
    this.recordAction({ at: now.toISOString(), actor: actorLabel(actor), repo: ref?.["repo"] == null ? null : String(ref["repo"]), taskId: ref === undefined ? null : String(ref["external_id"]), runId: null,
      action: act === "asked" ? "task handed to a person" : `task ${act}`, outcome: "recorded", source: "work", detail: handed === undefined ? null : `${handed.person}: ${handed.why}` });
  }

  /** Every recorded act on a task, oldest first. */
  taskActs(taskRef: number): TaskActRow[] {
    return this.db.prepare("SELECT act, account, lead, person, why, at FROM task_act WHERE task_ref = ? ORDER BY id").all(taskRef).map(row => ({
      act: String(row["act"]) as TaskAct, account: String(row["account"]), lead: Number(row["lead"]) === 1,
      person: row["person"] == null ? null : String(row["person"]), why: row["why"] == null ? null : String(row["why"]), at: String(row["at"]) }));
  }

  /** Whose lead's work this task is: the last to file, approve or hand it on was that person's lead (null: a person's). */
  leadWorkOf(taskRef: number): string | null {
    const row = this.db.prepare("SELECT account, lead, act FROM task_act WHERE task_ref = ? AND act IN ('filed', 'approved', 'asked') ORDER BY id DESC LIMIT 1").get(taskRef);
    return row === undefined || Number(row["lead"]) !== 1 || row["act"] === "asked" ? null : String(row["account"]);
  }

  /** The lead hands a task to a person: it becomes theirs, and they get one message saying why. */
  askPerson(taskId: string, person: string, why: string, now: Date): { ok: true } | { ok: false; reason: "unknown-task" | "unknown-person" | "unplaced" } {
    return this.transact(() => {
      const ref = this.lookupRef(taskId);
      if (ref === null) return { ok: false as const, reason: "unknown-task" as const };
      if (ref.repo === null) return { ok: false as const, reason: "unplaced" as const };
      const account = this.accountOf(person);
      if (account === null || account.revokedAt !== null || !this.accountCanAccess(person, ref.repo)) return { ok: false as const, reason: "unknown-person" as const };
      this.noteTaskAct(ref.id, "asked", now, { person, why });
      const asks = this.taskActs(ref.id).filter(one => one.act === "asked").length;
      const actor = currentActor();
      this.enqueueNotification({ dedupeKey: `ask:${ref.id}:${asks}`, kind: "task-ask", pushClass: "attention", recipient: person,
        subject: `${actor?.lead ? "The lead" : actor?.account ?? "Someone"} needs you: ${lifecycleWords(this.getTask(taskId)?.title ?? taskId, 80)}`,
        body: lifecycleWords(why, 400), link: chatControlHref("task", taskId), source: { taskRef: ref.id } }, now);
      return { ok: true as const };
    });
  }

  /** The task that replaced a cancelled one, or null. */
  replacementOf(taskId: string): string | null {
    const row = this.db.prepare("SELECT r.successor FROM task_replacement r JOIN task_ref t ON t.id = r.task_ref WHERE t.backend = ? AND t.external_id = ?").get(BUILT_IN, taskId);
    return row === undefined ? null : String(row["successor"]);
  }

  /** Every replaced task in one read, for lists: task id → its successor. */
  replacements(): Map<string, string> {
    return new Map(this.db.prepare("SELECT t.external_id, r.successor FROM task_replacement r JOIN task_ref t ON t.id = r.task_ref").all()
      .map(row => [String(row["external_id"]), String(row["successor"])]));
  }

  /** Mute or unmute one project's pings for one person. The console and digest keep everything. */
  setProjectMuted(account: string, repo: string, muted: boolean, now: Date): void {
    if (muted) this.db.prepare("INSERT OR IGNORE INTO project_mute (account, repo, at) VALUES (?, ?, ?)").run(account, repo, now.toISOString());
    else this.db.prepare("DELETE FROM project_mute WHERE account = ? AND repo = ?").run(account, repo);
  }

  mutedProjects(account: string): string[] {
    return this.db.prepare("SELECT repo FROM project_mute WHERE account = ? ORDER BY repo").all(account).map(row => String(row["repo"]));
  }

  /** Whose act made this fact, if anyone's. */
  notificationActor(id: number): Actor | null {
    const row = this.db.prepare("SELECT account, lead FROM notification_actor WHERE notification = ?").get(id);
    return row === undefined ? null : { account: String(row["account"]), lead: Number(row["lead"]) === 1 };
  }

  /**
   * Whether this fact may message this person (every chat, phone and browser asks here). Pings follow
   * responsibility: a security alert always does; nobody is messaged about their own act (or their lead's);
   * the lead's work messages nobody unless it is handed to a person or fails with nothing left for the lead
   * to try; and a person's muted project stays quiet. A fact addressed to one person is theirs. The console
   * and the evening digest keep every fact either way.
   */
  pingAllowed(row: Pick<Notification, "id" | "kind" | "recipient" | "project" | "taskRef">, account: string): boolean {
    // A security alert always pings, ahead of every rule below: own acts, settled, replaced or release-check tasks.
    if (SECURITY_KINDS.has(row.kind) || row.kind === "evening-digest") return true;
    if (row.recipient !== null && row.kind === "task-ask") return true;
    // The lead's own words reach the person it speaks for, and its claim repaints only that person's card (lead-voice.ts).
    if (row.kind === "lead-say") return row.recipient === account;
    const actor = this.notificationActor(row.id);
    if (row.kind === "lead-on-it" || row.kind === "lead-lapsed") return actor?.lead === true && actor.account === account;
    if (actor !== null && actor.account === account) return false;
    if (row.recipient !== null) return true;
    // A task this person (or their lead) completed or cancelled is settled for them: nothing more about it.
    // Release checks and replaced or superseded tasks never ping anyone; a deploy says "is live" instead.
    if (row.taskRef !== null && (this.settledBy(row.taskRef) === account || this.neverPings(row.taskRef))) return false;
    if (this.leadQuiet(row, actor)) return false;
    return row.project === null || this.db.prepare("SELECT 1 AS hit FROM project_mute WHERE account = ? AND repo = ?").get(account, row.project) === undefined;
  }

  /** Who last completed or cancelled this task, when that is still its latest act: null otherwise. A revision's
   * completion is recorded on its root, so an act on a task it revises counts too, but only one made after this
   * revision was filed: settling older work never silences a newer revision, whose failures still reach people. */
  settledBy(taskRef: number): string | null {
    const ancestors: number[] = [];
    for (let at = 0, from = taskRef; at < 20; at++) {
      const parent = this.db.prepare(`SELECT p.id FROM task_ref c JOIN task_ref p ON p.backend = c.backend AND p.external_id = c.revision_of AND p.repo IS c.repo
        WHERE c.id = ?`).get(from);
      if (parent === undefined || from === Number(parent["id"]) || ancestors.includes(Number(parent["id"]))) break;
      from = Number(parent["id"]);
      ancestors.push(from);
    }
    const filed = this.db.prepare("SELECT t.created_at FROM task_ref r JOIN task t ON t.id = r.external_id AND r.backend = ? WHERE r.id = ?").get(BUILT_IN, taskRef);
    const since = filed === undefined || ancestors.length === 0 ? null : String(filed["created_at"]);
    const last = since === null
      ? this.db.prepare("SELECT act, account FROM task_act WHERE task_ref = ? ORDER BY id DESC LIMIT 1").get(taskRef)
      : this.db.prepare(`SELECT act, account FROM task_act WHERE task_ref = ? OR (task_ref IN (${ancestors.map(() => "?").join(", ")}) AND at >= ?)
          ORDER BY id DESC LIMIT 1`).get(taskRef, ...ancestors, since);
    return last !== undefined && (last["act"] === "completed" || last["act"] === "cancelled") ? String(last["account"]) : null;
  }

  /** A release check, a replaced task, or one a revision superseded: its facts stay in the console. */
  neverPings(taskRef: number): boolean {
    return this.db.prepare(`SELECT 1 AS hit FROM task_ref r WHERE r.id = ? AND (
        EXISTS (SELECT 1 FROM run JOIN run_check rc ON rc.run = run.id WHERE run.task_ref = r.id AND rc.release = 1)
        OR EXISTS (SELECT 1 FROM task_replacement x WHERE x.task_ref = r.id)
        OR EXISTS (SELECT 1 FROM task_ref c WHERE c.backend = r.backend AND c.revision_of = r.external_id AND c.repo IS r.repo))`).get(taskRef) !== undefined;
  }

  /** The lead's work, which messages nobody: unless it is a security alert or a failure with nothing left for the lead. */
  leadQuiet(row: Pick<Notification, "id" | "kind" | "taskRef">, actor: Actor | null = this.notificationActor(row.id)): boolean {
    if (SECURITY_KINDS.has(row.kind)) return false;
    const lead = actor?.lead === true || (row.taskRef !== null && this.leadWorkOf(row.taskRef) !== null);
    return lead && !this.failedForGood(row);
  }

  /** A failure with nothing left for the lead to do: its attempts are spent, or the task has failed for good. */
  private failedForGood(row: Pick<Notification, "kind" | "taskRef">): boolean {
    if (SPENT_KINDS.has(row.kind)) return true;
    if (!/fail|exhausted/.test(row.kind) || row.taskRef === null) return false;
    return this.db.prepare("SELECT 1 AS hit FROM task t JOIN task_ref r ON r.external_id = t.id AND r.backend = ? WHERE r.id = ? AND t.state = 'failed'").get(BUILT_IN, row.taskRef) !== undefined;
  }

  /** The card a destination keeps for this task. A task with none joins a card whose first task was filed within
   * a minute of it (up to eight tasks), or starts its own. */
  chatCardFor(destination: string, taskRef: number, filedAt: string, now: Date): ChatCard {
    return this.transact(() => {
      const known = this.db.prepare("SELECT card FROM chat_card_task WHERE destination = ? AND task_ref = ?").get(destination, taskRef);
      if (known !== undefined) return this.chatCard(Number(known["card"]))!;
      const at = Date.parse(filedAt);
      const low = new Date(at - QUIET_GROUP_MS).toISOString(), high = new Date(at + QUIET_GROUP_MS).toISOString();
      const together = Number.isFinite(at) ? this.db.prepare(`SELECT id FROM chat_card c WHERE destination = ? AND anchor_at BETWEEN ? AND ?
        AND (SELECT COUNT(*) FROM chat_card_task t WHERE t.card = c.id) < 8 ORDER BY id DESC LIMIT 1`).get(destination, low, high) : undefined;
      const card = together !== undefined ? Number(together["id"])
        : Number(this.db.prepare("INSERT INTO chat_card (destination, anchor_at, created_at) VALUES (?, ?, ?)")
          .run(destination, Number.isFinite(at) ? new Date(at).toISOString() : now.toISOString(), now.toISOString()).lastInsertRowid);
      this.db.prepare("INSERT INTO chat_card_task (destination, task_ref, card, joined_at) VALUES (?, ?, ?, ?)").run(destination, taskRef, card, now.toISOString());
      return this.chatCard(card)!;
    });
  }

  chatCard(id: number): ChatCard | null {
    const row = this.db.prepare("SELECT * FROM chat_card WHERE id = ?").get(id);
    if (row === undefined) return null;
    const tasks = this.db.prepare("SELECT task_ref FROM chat_card_task WHERE card = ? ORDER BY joined_at, task_ref").all(id).map(one => Number(one["task_ref"]));
    return { id, destination: String(row["destination"]), anchorAt: String(row["anchor_at"]), message: row["message"] == null ? null : String(row["message"]),
      digest: row["digest"] == null ? null : String(row["digest"]), tasks };
  }

  /** The newest lifecycle fact a task has recorded — what its card says before any attempt starts. */
  latestTaskFact(taskRef: number): { kind: string; createdAt: string } | null {
    const row = this.db.prepare("SELECT kind, created_at FROM notification WHERE task_ref = ? AND substr(dedupe_key, 1, ?) = ? ORDER BY id DESC LIMIT 1")
      .get(taskRef, LIFECYCLE_KEY_PREFIX.length, LIFECYCLE_KEY_PREFIX);
    return row === undefined ? null : { kind: String(row["kind"]), createdAt: String(row["created_at"]) };
  }

  /** Task-bound facts recorded since an instant, newest last (bounded): what an evening digest reads. */
  taskFactsSince(since: string, limit = 2000): Notification[] {
    return this.db.prepare("SELECT * FROM notification WHERE created_at >= ? AND task_ref IS NOT NULL AND project IS NOT NULL ORDER BY id DESC LIMIT ?")
      .all(since, limit).map(readNotification).reverse();
  }

  /** The one message this update joins: the destination's batch opened within `windowMs`, or a new one. A task
   * has one line in it, saying its newest update (`notification`; null for a finished result). */
  chatBatchFor(destination: string, taskRef: number, run: number | null, now: Date, windowMs: number, notification: number | null = null): ChatBatch {
    return this.transact(() => {
      const open = this.db.prepare("SELECT id FROM chat_batch WHERE destination = ? AND opened_at > ? AND opened_at <= ? ORDER BY id DESC LIMIT 1")
        .get(destination, new Date(now.getTime() - windowMs).toISOString(), now.toISOString());
      const batch = open !== undefined ? Number(open["id"])
        : Number(this.db.prepare("INSERT INTO chat_batch (destination, opened_at) VALUES (?, ?)").run(destination, now.toISOString()).lastInsertRowid);
      this.db.prepare(`INSERT INTO chat_batch_item (batch, task_ref, run, joined_at, notification) VALUES (?, ?, ?, ?, ?)
        ON CONFLICT (batch, task_ref) DO UPDATE SET run = excluded.run, notification = excluded.notification`).run(batch, taskRef, run, now.toISOString(), notification);
      return this.chatBatch(batch)!;
    });
  }

  chatBatch(id: number): ChatBatch | null {
    const row = this.db.prepare("SELECT * FROM chat_batch WHERE id = ?").get(id);
    if (row === undefined) return null;
    const items = this.db.prepare("SELECT task_ref, run, notification FROM chat_batch_item WHERE batch = ? ORDER BY joined_at, task_ref").all(id)
      .map(one => ({ taskRef: Number(one["task_ref"]), run: one["run"] == null ? null : Number(one["run"]),
        notification: one["notification"] == null ? null : Number(one["notification"]) }));
    return { id, destination: String(row["destination"]), openedAt: String(row["opened_at"]), message: row["message"] == null ? null : String(row["message"]),
      digest: row["digest"] == null ? null : String(row["digest"]), items };
  }

  setChatBatchMessage(id: number, message: string, digest: string): void {
    this.db.prepare("UPDATE chat_batch SET message = ?, digest = ? WHERE id = ?").run(message, digest, id);
  }

  /** The finished-work message that carries this result at one destination, if one was placed: screenshots follow it. */
  chatBatchMessageFor(destination: string, taskRef: number, run: number): string | null {
    const row = this.db.prepare(`SELECT b.message FROM chat_batch b JOIN chat_batch_item i ON i.batch = b.id
      WHERE b.destination = ? AND i.task_ref = ? AND (i.run = ? OR i.run IS NULL) AND b.message IS NOT NULL ORDER BY b.id DESC LIMIT 1`).get(destination, taskRef, run);
    return row === undefined ? null : String(row["message"]);
  }

  /** The message now showing this card, and what it shows. */
  setChatCardMessage(id: number, message: string, digest: string): void {
    this.db.prepare("UPDATE chat_card SET message = ?, digest = ? WHERE id = ?").run(message, digest, id);
  }

  markTelegramDigestSent(now: Date): void {
    this.db.prepare("UPDATE telegram_digest SET last_sent_at = ? WHERE id = 1").run(now.toISOString());
  }

  /** Every batched row finalized delivered AND the anchor moved, in ONE
   * transaction (v4 review, finding 5): a digest is either recorded whole
   * or not at all. Rows whose claim lapsed meanwhile are reported, not
   * silently skipped. */
  finalizeDigest(ids: readonly number[], owner: string, receipt: string | null, now: Date): { finalized: number; lapsed: number } {
    return this.transact(() => {
      let finalized = 0;
      for (const id of ids) {
        if (this.finalizeDelivery(id, owner, { ok: true, receipt }, now)) finalized++;
      }
      this.markTelegramDigestSent(now);
      return { finalized, lapsed: ids.length - finalized };
    });
  }

  /** Routine rows waiting for the next digest: pending, and not urgent.
   * A row the live pairing delivered, or skipped as pre-pairing history,
   * is settled and not waiting. */
  countRoutinePending(): number {
    const row = this.db
      .prepare(
        `SELECT COUNT(*) AS n FROM notification
          WHERE resolved_at IS NULL AND recipient IS NULL
            AND NOT EXISTS (SELECT 1 FROM notification_delivery d
              JOIN telegram_binding b ON d.destination = 'telegram:' || b.bot_id || ':' || b.chat_id || ':' || b.id || ':' || b.approver_generation
              JOIN approver a ON a.name = b.approver AND a.generation = b.approver_generation
              WHERE d.notification = notification.id AND NOT (${TELEGRAM_UNSETTLED})
                AND b.revoked_at IS NULL AND a.revoked_at IS NULL)
            AND NOT (dedupe_key LIKE 'decision:%' OR COALESCE(push_class, '') = 'attention')`,
      )
      .get();
    return Number(row?.["n"] ?? 0);
  }

  /**
   * What the console and the morning brief count as "pending delivery":
   * every non-lifecycle row still pending in the shared outbox (the legacy
   * meaning, unchanged), plus a routine lifecycle row only once the LIVE
   * Telegram pairing actually tried to send it and the wire refused —
   * "offline", a rate-limit answer, no confirmed message identity. Routine
   * progress waiting for its digest window, for a pairing, or behind one
   * of the store's own holds (TELEGRAM_HOLD_REASONS: an excluded project,
   * changed provenance, the per-task order fence) is delivery, not
   * trouble, and never pads the number; a failed send is trouble and must
   * not hide behind quiet progress. Skipped pre-pairing history is never
   * counted. The bridge's own pass report still names every held row.
   */
  pendingForAttention(): Notification[] {
    const holds = Object.values(TELEGRAM_HOLD_REASONS);
    // A successful shell/webhook receipt does not settle a different
    // destination's failure. Select that union before applying the global
    // pending filter, and exclude resolved facts from both arms.
    return this.db
      .prepare(
        `WITH troubled AS (
           SELECT d.notification AS id FROM notification_delivery d
            JOIN telegram_binding b ON d.destination = 'telegram:' || b.bot_id || ':' || b.chat_id || ':' || b.id || ':' || b.approver_generation
            JOIN approver a ON a.name = b.approver AND a.generation = b.approver_generation
           WHERE b.revoked_at IS NULL AND a.revoked_at IS NULL
             AND ${TELEGRAM_UNSETTLED}
             AND d.attempts > 0 AND d.last_error IS NOT NULL
             AND d.last_error NOT IN (${holds.map(() => "?").join(", ")})
         )
         SELECT n.* FROM notification n
          WHERE n.resolved_at IS NULL
            AND ((n.delivered_at IS NULL AND n.recipient IS NULL AND substr(n.dedupe_key, 1, ${LIFECYCLE_KEY_PREFIX.length}) <> '${LIFECYCLE_KEY_PREFIX}')
              OR n.id IN (SELECT id FROM troubled))
          ORDER BY n.id`,
      )
      .all(...holds)
      .map(readNotification);
  }

  // ---- web push (arc 3) ----------------------------------------------------

  /**
   * Enroll a phone. One transaction: the high-water mark is MAX
   * (notification.id) read HERE (finding 11 — only newer facts ever page
   * this device); an identical live enrollment (same endpoint, approver,
   * generation) returns idempotent success; a CONFLICTING live binding —
   * different approver or a stale generation — is retired 'replaced' with
   * its pairs settled, and the fresh activation gets its own row
   * (finding 28).
   */
  enrollPushSubscription(
    args: {
      endpoint: string;
      p256dh: string;
      auth: string;
      approver: string;
      approverGeneration: number;
      uaWords: string;
      vapidFingerprint: string;
    },
    now: Date,
  ): { ok: true; id: number; replayed: boolean } | { ok: false; reason: "approver-cap" | "installation-cap" } {
    return this.transact(() => {
      const live = this.db
        .prepare("SELECT * FROM push_subscription WHERE endpoint = ? AND retired_at IS NULL")
        .get(args.endpoint);
      if (live !== undefined) {
        if (
          String(live["approver"]) === args.approver &&
          Number(live["approver_generation"]) === args.approverGeneration &&
          String(live["vapid_fingerprint"]) === args.vapidFingerprint
        ) {
          return { ok: true as const, id: Number(live["id"]), replayed: true };
        }
        this.retirePushSubscription(Number(live["id"]), "replaced", now);
      }
      const mine = this.db
        .prepare("SELECT COUNT(*) AS n FROM push_subscription WHERE approver = ? AND retired_at IS NULL")
        .get(args.approver);
      if (Number(mine?.["n"] ?? 0) >= 5) return { ok: false as const, reason: "approver-cap" as const };
      const all = this.db.prepare("SELECT COUNT(*) AS n FROM push_subscription WHERE retired_at IS NULL").get();
      if (Number(all?.["n"] ?? 0) >= 20) return { ok: false as const, reason: "installation-cap" as const };
      const mark = this.db.prepare("SELECT COALESCE(MAX(id), 0) AS top FROM notification").get();
      const inserted = this.db
        .prepare(
          `INSERT INTO push_subscription
             (endpoint, p256dh, auth, approver, approver_generation, ua_words, vapid_fingerprint,
              starts_after_notification, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          args.endpoint,
          args.p256dh,
          args.auth,
          args.approver,
          args.approverGeneration,
          args.uaWords,
          args.vapidFingerprint,
          Number(mark?.["top"] ?? 0),
          now.toISOString(),
        );
      return { ok: true as const, id: Number(inserted.lastInsertRowid), replayed: false };
    });
  }

  /**
   * Retire an enrollment and terminally settle EVERY unsettled pair —
   * pending AND claimed (finding 25): an in-flight sender's fence or
   * settlement fails instead of paging a device that was just removed.
   */
  retirePushSubscription(id: number, reason: string, now: Date): void {
    this.transact(() => {
      const stamp = now.toISOString();
      this.db
        .prepare("UPDATE push_subscription SET retired_at = ?, retired_reason = ? WHERE id = ? AND retired_at IS NULL")
        .run(stamp, reason, id);
      this.db
        .prepare(
          `UPDATE push_delivery SET state = 'retired', claim_owner = NULL, claim_expires_at = NULL,
                                    claim_generation = claim_generation + 1
            WHERE subscription = ? AND state IN ('pending','claimed')`,
        )
        .run(id);
    });
  }

  listPushSubscriptions(approver?: string): PushSubscription[] {
    const rows =
      approver === undefined
        ? this.db.prepare("SELECT * FROM push_subscription ORDER BY id").all()
        : this.db.prepare("SELECT * FROM push_subscription WHERE approver = ? ORDER BY id").all(approver);
    return rows.map(readPushSubscription);
  }

  /** Retire every live enrollment whose VAPID key is not the current one
   * (finding 27): a subscription is bound to the key it enrolled under and
   * rejects any other — after a key regeneration they are dead weight. */
  retirePushSubscriptionsOfOtherKeys(currentFingerprint: string, now: Date): number {
    const stale = this.db
      .prepare("SELECT id FROM push_subscription WHERE retired_at IS NULL AND vapid_fingerprint <> ?")
      .all(currentFingerprint)
      .map(row => Number(row["id"]));
    for (const id of stale) this.retirePushSubscription(id, "key-rotated", now);
    return stale.length;
  }

  /**
   * Seed pairs (arc 3 finding 1): one per (eligible notification, live
   * subscription), INSERT OR IGNORE — eligibility is a STAMPED class, an
   * unresolved row, and an id NEWER than the subscription's high-water
   * mark. The outbox's delivered_at is deliberately not consulted.
   */
  seedPushPairs(now: Date): number {
    const { changes } = this.db
      .prepare(
        `INSERT OR IGNORE INTO push_delivery (notification, subscription, created_at)
         SELECT notification.id, push_subscription.id, ?
           FROM notification, push_subscription
          WHERE (notification.push_class IS NOT NULL OR notification.kind = 'check-progress')
            AND notification.resolved_at IS NULL
            AND (notification.recipient IS NULL OR notification.recipient = push_subscription.approver)
            AND push_subscription.retired_at IS NULL
            AND notification.id > push_subscription.starts_after_notification`,
      )
      .run(now.toISOString());
    // Pings follow responsibility: a pair this person must not be alerted about retires before it is ever sent.
    if (Number(changes) > 0) {
      const fresh = this.db.prepare(`SELECT p.id AS pair, s.approver AS approver, n.* FROM push_delivery p
          JOIN push_subscription s ON s.id = p.subscription JOIN notification n ON n.id = p.notification
          WHERE p.state = 'pending' AND p.attempts = 0 AND p.created_at = ?`).all(now.toISOString());
      for (const raw of fresh) {
        // A met promise made on a chat app is said there (lead-commitments.ts), not as a push: settled here, unsent. One
        // made in the console or app is this phone's own.
        const elsewhere = /^lead-promise:(telegram|slack|discord|teams):/.test(String(raw["dedupe_key"]));
        if (elsewhere || !this.pingAllowed(readNotification(raw), String(raw["approver"]))) {
          this.db.prepare("UPDATE push_delivery SET state = 'retired', last_error = ? WHERE id = ? AND state = 'pending'")
            .run(elsewhere ? TELEGRAM_SKIPPED_OTHER_CHAT : "quiet", Number(raw["pair"]));
        }
      }
    }
    return Number(changes);
  }

  /**
   * Claim due pairs: pending (respecting next_attempt_at) or claimed-but-
   * expired (reclaim bumps the generation — the old owner loses every
   * subsequent conditional write, the merge-ledger discipline).
   */
  claimPushPairs(owner: string, ttlMs: number, limit: number, now: Date): PushPair[] {
    return this.transact(() => {
      const stamp = now.toISOString();
      const expires = new Date(now.getTime() + ttlMs).toISOString();
      const due = this.db
        .prepare(
          `SELECT id FROM push_delivery
            WHERE (state = 'pending' AND (next_attempt_at IS NULL OR next_attempt_at <= ?))
               OR (state = 'claimed' AND claim_expires_at <= ?)
            ORDER BY id LIMIT ?`,
        )
        .all(stamp, stamp, limit)
        .map(row => Number(row["id"]));
      const taken: number[] = [];
      for (const id of due) {
        const { changes } = this.db
          .prepare(
            `UPDATE push_delivery SET state = 'claimed', claim_owner = ?, claim_expires_at = ?,
                                      claim_generation = claim_generation + 1
              WHERE id = ? AND (
                (state = 'pending' AND (next_attempt_at IS NULL OR next_attempt_at <= ?))
                OR (state = 'claimed' AND claim_expires_at <= ?)
              )`,
          )
          .run(owner, expires, id, stamp, stamp);
        if (Number(changes) > 0) taken.push(id);
      }
      return taken
        .map(id => this.db.prepare("SELECT * FROM push_delivery WHERE id = ?").get(id))
        .filter((row): row is Record<string, unknown> => row !== undefined)
        .map(readPushPair);
    });
  }

  /** Renew a claim this owner+generation still holds — false is FATAL to the send. */
  renewPushClaim(id: number, owner: string, generation: number, ttlMs: number, now: Date): boolean {
    const { changes } = this.db
      .prepare(
        `UPDATE push_delivery SET claim_expires_at = ?
          WHERE id = ? AND state = 'claimed' AND claim_owner = ? AND claim_generation = ?`,
      )
      .run(new Date(now.getTime() + ttlMs).toISOString(), id, owner, generation);
    return Number(changes) > 0;
  }

  /**
   * The send-time fence (finding 12/25), one read: the pair still ours,
   * the subscription live under its enrolled generation, the notification
   * unresolved and still stamped. Null = do not transmit.
   */
  pushSendFence(id: number, owner: string, generation: number): (PushPair & { subscriptionRow: PushSubscription; notificationRow: Notification }) | null {
    const pair = this.db
      .prepare(
        `SELECT * FROM push_delivery
          WHERE id = ? AND state = 'claimed' AND claim_owner = ? AND claim_generation = ?`,
      )
      .get(id, owner, generation);
    if (pair === undefined) return null;
    const subscription = this.db
      .prepare("SELECT * FROM push_subscription WHERE id = ? AND retired_at IS NULL")
      .get(Number(pair["subscription"]));
    if (subscription === undefined) return null;
    const approver = this.db.prepare("SELECT generation FROM approver WHERE name = ?").get(String(subscription["approver"]));
    if (approver === undefined || Number(approver["generation"]) !== Number(subscription["approver_generation"])) return null;
    const notification = this.db
      .prepare("SELECT * FROM notification WHERE id = ? AND resolved_at IS NULL AND (push_class IS NOT NULL OR kind = 'check-progress')")
      .get(Number(pair["notification"]));
    if (notification === undefined) return null;
    return { ...readPushPair(pair), subscriptionRow: readPushSubscription(subscription), notificationRow: readNotification(notification) };
  }

  /** Settle a pair, conditionally on owner + generation (finding 25). */
  settlePushPair(
    id: number,
    owner: string,
    generation: number,
    outcome:
      | { kind: "accepted" }
      | { kind: "rejected"; error: string }
      | { kind: "undeliverable"; error: string }
      | { kind: "backoff"; nextAttemptAt: Date; error: string },
    now: Date,
  ): boolean {
    return this.transact(() => {
      const stamp = now.toISOString();
      const fence = "id = ? AND state = 'claimed' AND claim_owner = ? AND claim_generation = ?";
      if (outcome.kind === "accepted") {
        const { changes } = this.db
          .prepare(
            `UPDATE push_delivery SET state = 'accepted', accepted_at = ?, attempts = attempts + 1,
                                      claim_owner = NULL, claim_expires_at = NULL, last_error = NULL
              WHERE ${fence}`,
          )
          .run(stamp, id, owner, generation);
        if (Number(changes) > 0) {
          this.db
            .prepare(
              `UPDATE push_subscription SET last_ok_at = ?, consecutive_failures = 0
                WHERE id = (SELECT subscription FROM push_delivery WHERE id = ?)`,
            )
            .run(stamp, id);
        }
        return Number(changes) > 0;
      }
      if (outcome.kind === "backoff") {
        const { changes } = this.db
          .prepare(
            `UPDATE push_delivery SET state = 'pending', next_attempt_at = ?, attempts = attempts + 1,
                                      last_error = ?, claim_owner = NULL, claim_expires_at = NULL
              WHERE ${fence}`,
          )
          .run(outcome.nextAttemptAt.toISOString(), outcome.error, id, owner, generation);
        if (Number(changes) > 0) this.bumpPushFailures(id);
        return Number(changes) > 0;
      }
      const { changes } = this.db
        .prepare(
          `UPDATE push_delivery SET state = ?, attempts = attempts + 1, last_error = ?,
                                    claim_owner = NULL, claim_expires_at = NULL
            WHERE ${fence}`,
        )
        .run(outcome.kind, outcome.error, id, owner, generation);
      if (Number(changes) > 0) this.bumpPushFailures(id);
      return Number(changes) > 0;
    });
  }

  private bumpPushFailures(pairId: number): void {
    this.db
      .prepare(
        `UPDATE push_subscription SET consecutive_failures = consecutive_failures + 1
          WHERE id = (SELECT subscription FROM push_delivery WHERE id = ?)`,
      )
      .run(pairId);
  }

  // ---- idempotency --------------------------------------------------------

  /** A chat send receipt contains no message text. The session is part of
   * its namespace; callers must prove that session before reading it. */
  mateRequestReceipt(session: number, request: string): { digest: string; turn: number } | null {
    const row = this.db.prepare("SELECT result FROM mutation WHERE idempotency_key = ? AND operation = 'mate-send'")
      .get(`mate-send:${session}:${request}`);
    return row === undefined ? null : JSON.parse(String(row["result"])) as { digest: string; turn: number };
  }

  /**
   * Run `body` once per key, ever.
   *
   * The case this exists for is a runner that completes its work, has its
   * acknowledgement lost to a dropped connection, and retries. Without a key
   * the retry is a second, different mutation; with one it is the same answer
   * handed back. Callers that pass no key are not protected, which is why the
   * dispatch path always passes one.
   */
  /**
   * `worthRecording` exists for one case, and it is not a nicety.
   *
   * Idempotency protects against a mutation happening twice. A refusal is not
   * a mutation — nothing happened — so recording it turns the key into a
   * permanent "no". A dispatcher that asked for a busy task, was told no, and
   * retried the same key an hour later would be handed that hour-old refusal
   * about a task that has been free for fifty minutes.
   */
  replay<T>(
    mutation: Mutation,
    operation: string,
    body: () => T,
    worthRecording: (result: T) => boolean = () => true,
  ): T {
    return this.once(mutation, operation, body, worthRecording);
  }

  private once<T>(
    mutation: Mutation,
    operation: string,
    body: () => T,
    worthRecording: (result: T) => boolean = () => true,
  ): T {
    const { idempotencyKey, actor = DEFAULT_ACTOR, at = new Date() } = mutation;
    if (idempotencyKey === undefined) return body();

    const seen = this.db
      .prepare("SELECT result FROM mutation WHERE idempotency_key = ?")
      .get(idempotencyKey);
    if (seen !== undefined) return JSON.parse(String(seen["result"])) as T;

    const result = body();
    if (!worthRecording(result)) return result;

    this.db
      .prepare(
        "INSERT INTO mutation (idempotency_key, operation, result, actor, created_at) VALUES (?, ?, ?, ?, ?)",
      )
      .run(idempotencyKey, operation, JSON.stringify(result ?? null), actor, at.toISOString());
    return result;
  }
}

/** A stored count or id that must be a whole, non-negative number — a
 * NULL, an empty string, a fraction, or text reads as null (v48 authority repair). */
function wholeNumber(value: unknown): number | null {
  if (value === null || value === undefined) return null;
  if (typeof value === "bigint") return value >= 0n ? Number(value) : null;
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) return null;
  return value;
}

function readRun(row: Record<string, unknown>): Run {
  return {
    id: Number(row["id"]),
    taskRef: Number(row["task_ref"]),
    leaseId: String(row["lease_id"]),
    runner: String(row["runner"]),
    watchIncarnation: row["watch_incarnation"] == null ? null : String(row["watch_incarnation"]),
    reviewAttempt: wholeNumber(row["review_attempt"]),
    role: String(row["role"] ?? "builder") as Run["role"],
    provider: String(row["provider"] ?? "claude"),
    parentRun: row["parent_run"] === null || row["parent_run"] === undefined ? null : Number(row["parent_run"]),
    sessionId: row["session_id"] === null || row["session_id"] === undefined ? null : String(row["session_id"]),
    contestant: row["contestant"] === null || row["contestant"] === undefined ? null : Number(row["contestant"]),
    baseRevision:
      row["base_revision"] === null || row["base_revision"] === undefined
        ? null
        : String(row["base_revision"]),
    scopeDigest: row["scope_digest"] === null || row["scope_digest"] === undefined ? null : String(row["scope_digest"]),
    profileDigest: row["profile_digest"] === null || row["profile_digest"] === undefined ? null : String(row["profile_digest"]),
    qualityMode: row["quality_mode"] === "strict" ? "strict" : "default",
    attendedAuthorization:
      row["attended_authorization"] === null || row["attended_authorization"] === undefined
        ? null
        : String(row["attended_authorization"]),
    branch: row["branch"] === null ? null : String(row["branch"]),
    worktree: row["worktree"] === null ? null : String(row["worktree"]),
    model: row["model"] === null ? null : String(row["model"]),
    outcome: row["outcome"] === null ? null : (String(row["outcome"]) as Run["outcome"]),
    reason: row["reason"] === null ? null : String(row["reason"]),
    committed: row["committed"] === null ? null : Number(row["committed"]) === 1,
    startedAt: String(row["started_at"]),
    finishedAt: row["finished_at"] === null ? null : String(row["finished_at"]),
    providerVersion:
      row["provider_version"] === null || row["provider_version"] === undefined
        ? null
        : String(row["provider_version"]),
    providerStartedAt:
      row["provider_started_at"] === null || row["provider_started_at"] === undefined
        ? null
        : String(row["provider_started_at"]),
    tokensIn: row["tokens_in"] === null || row["tokens_in"] === undefined ? null : Number(row["tokens_in"]),
    tokensOut: row["tokens_out"] === null || row["tokens_out"] === undefined ? null : Number(row["tokens_out"]),
    costUsd: row["cost_usd"] === null || row["cost_usd"] === undefined ? null : Number(row["cost_usd"]),
    headRevision:
      row["head_revision"] === null || row["head_revision"] === undefined
        ? null
        : String(row["head_revision"]),
    handoff: row["handoff"] === null || row["handoff"] === undefined ? null : String(row["handoff"]),
    phase:
      row["phase"] === null || row["phase"] === undefined
        ? null
        : (RUN_PHASES as readonly string[]).includes(String(row["phase"]))
          ? (String(row["phase"]) as RunPhase)
          : null,
    // The chain binding is read STRICTLY (v48 authority repair): a cycle id and an index
    // are non-negative integers, an entry digest is a non-empty string, an
    // auth mode is exactly one of the two words — anything else reads as
    // no binding at all, which every custody proof refuses, never as the
    // base entry or the subscription credential.
    chainCycle: wholeNumber(row["chain_cycle"]),
    chainIndex: wholeNumber(row["chain_index"]),
    entryDigest: row["entry_digest"] === null || row["entry_digest"] === undefined || String(row["entry_digest"]) === "" ? null : String(row["entry_digest"]),
    authMode: row["auth_mode"] === "api-key" ? "api-key" : row["auth_mode"] === "subscription" ? "subscription" : null,
    terminalClass:
      row["terminal_class"] === null || row["terminal_class"] === undefined
        ? null
        : (String(row["terminal_class"]) as TerminalClass),
    planRevision: row["plan_revision"] === null || row["plan_revision"] === undefined ? null : Number(row["plan_revision"]),
    authorityDigest: row["authority_digest"] === null || row["authority_digest"] === undefined ? null : String(row["authority_digest"]),
  };
}

